COPLAS_PIEZA(1, [["rm_t3-n5392",1,"¿Quién sabe lo que sucede\nEn las entrañas del mar?\n¿Quién sabe lo que yo sufro,\nAunque no me ven llorar?",1,0,-1,8,"",0,4,"a",21,0,-1,0,419,419,"5392","",0,"","","",1,0,0,[],""],["rm_t3-n5393",1,"Muertas mis esperanzas,\nNo me lamento,\nPor que no sepa nádie\nMi sentimiento.\nMe quejo al aire,\nPorque no encuentro amigo\nDe quien fiarme.",1,0,-1,8,"",4,7,"ae",-1,0,-1,0,419,419,"5393","",0,"","","",1,0,0,[],""],["rm_t3-n5394",1,"Tengo un pesar que me aflige\nDentro de mi corazon;\nPero contarse no puede,\nY esa es mi pena mayor.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,419,420,"5394","",0,"","","",1,0,0,[],""],["rm_t3-n5395",1,"No solicito alivio\nA mis tormentos,\nPorque á nádie declaro\nMi pensamiento.\nMas con silencio,\nPara lograr mi gusto,\nDoy tiempo al tiempo.",1,0,-1,8,"",4,7,"eo",-1,0,-1,0,420,420,"5395","",0,"","","",1,0,0,[],""],["rm_t3-n5396",1,"La Bígen de las Angustias\nEs la que sabe mi má;\nQue me meto en su capiya\nY me jarto de yorá.",1,0,-1,8,"",0,4,"a",9,0,-1,0,420,420,"5396","",0,"","","",1,0,0,[],""],["rm_t3-n5397",1,"A las flores les cuento\nTodo mi penar,\nPorque sé que las flores\nNo lo han de contar.\nTodo mi sentir,\nPorque sé que las flores\nNo lo han de decir.",1,0,-1,8,"",4,7,"i",157,0,-1,0,420,420,"5397","",0,"","","",1,0,0,[],""],["rm_t3-n5398",1,"¿A quién le contaré yo\nLo que á mí me está pasando?\nSe lo contaré á la tierra,\nCuando me estén enterrando.",1,0,-1,8,"",0,4,"ao",33,0,-1,0,420,420,"5398","",0,"fernan_caballero","","",3,0,0,[],""],["rm_t3-n5399",1,"Tan solamente á la tierra\nLe cuento lo que me pasa,\nPorque no encuentro en el mundo\nPersona de confianza.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,420,420,"5399","",0,"","","",1,0,0,[],""],["rm_t3-n5400",1,"Tengo una pena conmigo,\nQue á nádie se la diré;\nEl fondo de mi pechito\nSu sepultura ha de ser.",1,0,-1,8,"",0,4,"e",-1,0,-1,0,421,421,"5400","",0,"","","",7,0,0,[],""],["rm_t3-n5401",1,"Tengo una pena muy grande;\nSi no la callo, reviento;\nY si llego á publicarla,\nMe muero de sentimiento.",1,0,-1,8,"",0,4,"eo",94,0,-1,0,421,421,"5401","",0,"","","",1,0,0,[],""],["rm_t3-n5402",1,"Mi corazon tiene penas\nY él mismo las administra;\nPor no descubrirse á nádie,\nLlorando se mortifica.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,421,421,"5402","",0,"","","",1,0,0,[],""],["rm_t3-n5403",1,"Jise un joyito en l' arena\nY enterré mi pensamiento;\nPor no descubrirme á nádie,\nMartirio le dí á mi cuerpo.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,421,421,"5403","",0,"","","",1,0,0,[],""],["rm_t3-n5404",1,"Más bien consiento en morir\nQue nó en publicar mis penas,\nQue como un borcan de fuego\nSalen del arma y me queman.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,421,421,"5404","",0,"","","",1,0,0,[],""],["rm_t3-n5405",1,"Corazon mio, no llores,\nNo sientas ni sufras penas.\nNo hay corazon como el mio,\nQue sufre, calla y espera.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,421,421,"5405","",0,"","","",3,0,0,[],""],["rm_t3-n5406",1,"No hay corazon como el mio\nQue calle y sienta su pena:\nCorazon que siente y calla\nNo se encuentra dondequiera.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,421,421,"5406","",0,"palau_cantares","","",9,0,0,[],""],["rm_t3-n5407",1,"Por culpa de malas lenguas\nPerdí la prenda que amaba,\nQue me la encuentro en la calle,\nNi me mira ni me habla.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,422,422,"5407","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5408",1,"Por mor de las malas lenguas\nQue jablan lo que no es,\nTengo mi créito perdío;\n¡Cuándo lo recobraré!",1,0,-1,8,"",0,4,"e",-1,0,-1,0,422,422,"5408","",0,"","","",1,0,0,[],""],["rm_t3-n5411",1,"Soy una pobre donseya\nQue no me meto con náide,\nY por mor de malas lenguas\nTengo mi honor en el aire.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,422,422,"5411","",0,"","","",1,0,0,[],""],["rm_t3-n5412",1,"Los pasitos que yo doy,\n¡Qué murmuraitos son!\n¡Cuántos trompiesan y caen\nY no los murmuro yo!",1,0,-1,8,"",0,4,"o",-1,0,-1,0,422,422,"5412","",0,"","","",1,0,0,[],""],["rm_t3-n5414",1,"¡Bárgame Undebé, que tengo\nOjitos e beriera:\nAonde quiera que los pongo,\nBiene 'r biento y me los quiebra!",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,422,423,"5414","",0,"","","",1,0,0,[],""],["rm_t3-n5416",1,"Rosa me puso mi madre,\nPara ser más desgraciada;\nQue no hay rosa en el rosal\nQue no muera deshojada.",1,0,-1,8,"",0,4,"aa",49,0,-1,0,423,423,"5416","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n5417",1,"¡Válgame Dios de los cielos,\nQué desgraciado nací,\nQue cuando me bautizaron,\nFaltó la sal para mí!",1,0,-1,8,"",0,4,"i",23,0,-1,0,423,423,"5417","",0,"","","",32,0,0,[],""],["rm_t3-n5418",1,"¡Válgame Dios de los cielos,\nQué desgraciado he nacido!\nPara todos sale el sol,\nY para mí no ha salido.",1,0,-1,8,"",0,4,"io",101,0,-1,0,423,423,"5418","",0,"palau_cantares, lafuente_madrid","","",32,0,0,[],""],["rm_t3-n5419",1,"Diendo por er mueye alante\nMe s' apagaron las belas:\nPara mí siempre es de noche;\n¡Bárgame la Madalena!",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,423,423,"5419","",0,"","","",1,0,0,[],""],["rm_t3-n5420",1,"Con el dolor que yo vivo,\nNo vivirán criaturas:\nSiendo mi padre cerero,\nTengo de morir á oscuras.",1,0,-1,8,"",0,4,"ua",238,0,-1,0,423,423,"5420","",0,"","","",5,0,0,[],""],["rm_t3-n5421",1,"A mi madre le pregunto\nQue si yo he nacido en mártes,\nPorque mi malita suerte\nMe sigue por todas partes.",1,0,-1,8,"",0,4,"ae",239,0,-1,0,423,424,"5421","",0,"","","",1,0,0,[],""],["rm_t3-n5422",1,"Tôs mis hermanitos\nDuermen en mi casa\nY yo solito, - por mi mala suerte,\nAndo á sarto e mata.",1,0,-1,8,"",3,4,"aa",-1,0,-1,0,424,424,"5422","",0,"","","",1,0,0,[],""],["rm_t3-n5423",1,"Pâ toítos ha sío\nDia der Señó;\nPâ mí solito - ha sío er Juébes Santo\nBiérnes de Pasion.",1,0,-1,8,"",3,4,"ao",-1,0,-1,0,424,424,"5423","",0,"","","",1,0,0,[],""],["rm_t3-n5424",1,"Toítos s' arriman\nAr pinito berde,\nY yo m' arrimo - á los atunales,\nQu' espinitas tienen.",1,0,-1,8,"",3,4,"ee",-1,0,-1,0,424,424,"5424","",0,"","","",1,0,0,[],""],["rm_t3-n5425",1,"No sé qué l' he jecho á Dios,\nQue toíto me sale 'n contra;\nQue me tiro d' una oreja\nY no m' arcanso á la otra.",1,0,-1,8,"",0,4,"oa",-1,0,-1,0,424,424,"5425","",0,"","","",1,0,0,[],""],["rm_t3-n5426",1,"El demonio me lleva\nCuando recuerdo\nQue no consigo nada\nDe lo que intento.\nY más me lleva,\nAl Yer que otros consiguen\nLo que desean.",1,0,-1,8,"",4,7,"ea",-1,0,-1,0,424,424,"5426","",0,"","","",2,0,0,[],""],["rm_t3-n5428",1,"Si juego ar tresiyo, pierdo;\nSi juego ar cané, no gano;\nSijuego á la trentiuna,\nJ ago treinta y dos de mano.",1,0,-1,8,"",0,4,"ao",81,0,-1,0,425,425,"5428","",0,"","","",1,0,0,[],""],["rm_t3-n5429",1,"Soy desgrasiaíto\nJasta pâ 'l andá;\nQue los pasitos - que p' alante doy\nSe güerben p' atrás.",1,0,-1,8,"",3,4,"a",-1,0,-1,0,425,425,"5429","",0,"","","",1,0,0,[],""],["rm_t3-n5430",1,"Yo m' asomé á la muraya\nÁ ber las olas pasar,\nY se borbieron arenas\nLas agüitas de la mar.",1,0,-1,8,"",0,4,"a",21,0,-1,0,425,425,"5430","",0,"","","",1,0,0,[],""],["rm_t3-n5431",1,"Yo me metí álabrador,\nY se perdió la cosecha;\nSi me meto á sacristan,\nSe van á hundir las iglesias.",1,0,-1,8,"",3,4,"ea",-1,0,-1,0,425,425,"5431","",0,"","","",1,0,0,[],""],["rm_t3-n5432",1,"Vámonos de aquí, que corre\nLa mala fortuna nuestra;\nAyer se cayó la torre;\nMañana caerá la iglesia.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,425,425,"5432","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5433",1,"A mi corazon lo eché\nA pedir por esas calles,\nY como lo ven tan pobre,\nLimosna no le da nádie.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,425,425,"5433","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5435",1,"Tengo er corason más negro\nQu' er cuerbo tiene la pluma;\nCuando me parió mi mare\nMe tiraron á la Cuna.",1,0,-1,8,"",0,4,"ua",-1,0,-1,0,426,426,"5435","",0,"","","",1,0,0,[],""],["rm_t3-n5436",1,"Sola soy, sola nací;\nSola me parió mi madre;\nSola tengo de morir;\n¡La Soledad me acompañe!",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,426,426,"5436","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5437",1,"Ya no me asomo á la reja\nQue me solia asomar;\nQue me asomo á la bentana\nQue cae á la Soledá.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,426,426,"5437","",0,"","","",3,0,0,[],""],["rm_t3-n5438",1,"Vivo solito en el mundo\nY de mí nádie se acuerda;\nBusco en los árboles sombra\nY los árboles se secan.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,426,426,"5438","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5439",1,"No tengo quien por mí llore,\nSino la triste campana:\nSi yo me muero esta noche,\nMe entierran por la mañana.",1,0,-1,8,"",0,4,"aa",4,0,-1,0,426,426,"5439","",0,"","","",3,0,0,[],""],["rm_t3-n5440",1,"No tengo quien por mí llore,\nNi quien por mí pase pena:\nSi yo me muero esta noche,\nPor la mañana me entierran.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,426,426,"5440","",0,"","","",3,0,0,[],""],["rm_t3-n5441",1,"No tengo quien por mi llore,\nNi quien por mí pase pena,\nSino la triste campana\nQue doble cuando yo muera.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,426,426,"5441","",0,"","","",3,0,0,[],""],["rm_t3-n5442",1,"Me mató la confianza;\nLa ignorancia me cegó;\nCuando quise rescatarme,\nYa no tuve redencion.",1,0,-1,8,"",0,4,"o",-1,0,-1,0,427,427,"5442","",0,"","","",1,0,0,[],""],["rm_t3-n5446",1,"¡Mal haya mi poca edá\nY mi poco entendimiento:\nQue puse yo mi queré\nEn un molino de biento!",1,0,-1,8,"",0,4,"eo",94,0,-1,0,427,427,"5446","",0,"","","",1,0,0,[],""],["rm_t3-n5448",1,"Yo formé sobre espuma\nTorre de arena\nY mi triste esperanza\nLa puse en ella.\nFaltó el cimiento,\nY mi esperanza triste\nLa llevó el viento.",1,0,-1,8,"",4,7,"eo",94,0,-1,0,427,427,"5448","",0,"","","",1,0,0,[],""],["rm_t3-n5449",1,"En la torre de mis gustos,\nDonde tan alto me ví,\nPor ser los cimientes falsos,\nOtro subió y yo caí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,428,428,"5449","",0,"","","",4,0,0,[],""],["rm_t3-n5450",1,"Hise un castiyo de plumas\nY el aire se lo yebó:\n¡Mal haya quien s' enamora,\nPara bibir con dolor!",1,0,-1,8,"",0,4,"o",-1,0,-1,0,428,428,"5450","",0,"","","",1,0,0,[],""],["rm_t3-n5451",1,"Fuí sirguero desgrasiao\nQu'apénas salí der nío,\nMe cogieron los muchachos,\nPor dos cuartos fui bendío.",1,0,-1,8,"",0,4,"io",3,0,-1,0,428,428,"5451","",0,"","","",1,0,0,[],""],["rm_t3-n5452",1,"Como muchacho trabieso,\nPájaros salí á buscá;\nMetí la mano en un nío\nY me picó un alaclan.",1,0,-1,8,"",5,4,"aa",-1,0,-1,0,428,428,"5452","",0,"","","",1,0,0,[],""],["rm_t3-n5453",1,"Yo crié un cuerbo chiquito,\nCon intension que bolara;\nPero luégo me sacó\nLos ojitos e la cara.",1,0,-1,8,"",0,4,"aa",57,0,-1,0,428,428,"5453","",0,"","","",1,0,0,[],""],["rm_t3-n5454",1,"Mi corasonsito, mare,\nUn cuerbo se lo yebó,\nY enmedio d'aqueyos mares\nAbrió er pico y lo sortó.",1,0,-1,8,"",0,4,"o",2,0,-1,0,428,428,"5454","",0,"","","",1,0,0,[],""],["rm_t3-n5455",1,"Una escopeta en quien yo\nTenía mi confiansa,\nAr fin me dió gatillaso....\n¡Qué será las que son farsas!",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,428,428,"5455","",0,"","","",1,0,0,[],""],["rm_t3-n5456",1,"Una escopeta compré;\nLa llave me salió falsa;\nNi en mujer ni en escopeta\nHay que tener confianza.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,429,429,"5456","",0,"rm_t4","","",2,0,0,[],""],["rm_t3-n5459",1,"Maresita mía,\n¡Mir' usté por dónde\nAl espejito - donde me miraba\nSe le fué 'l asogue!",1,0,-1,8,"",3,4,"oe",-1,0,-1,0,429,429,"5459","",0,"","","",3,0,0,[],""],["rm_t3-n5460",1,"De lo más arto der sielo\nLa media luna cayó:\nYa se me quebró el espejo\nDonde me miraba yo.",1,0,-1,8,"",0,4,"o",2,0,-1,0,429,429,"5460","",0,"","","",2,0,0,[],""],["rm_t3-n5461",1,"Una granaíya abierta\nFué la causa de mi má:\nSin habérmela comío,\nMe la jisieron pagá.",1,0,-1,8,"",0,4,"a",9,0,-1,0,429,429,"5461","",0,"","","",1,0,0,[],""],["rm_t3-n5462",1,"Por comerme una breba\nBerde y sin gusto,\nM' ha yebao la Justisia\nSien rales justos.\nEso l' espera\nAr que de noche anda\nComiendo brebas.",1,0,-1,8,"",4,7,"ea",-1,0,-1,0,429,429,"5462","",0,"","","",1,0,0,[],""],["rm_t3-n5464",1,"La tierra, con ser la tierra,\nNo me comerá 'r doló:\nAr pié del armendro estube\nY no le cogí la fló.",1,0,-1,8,"",0,4,"o",2,0,-1,0,430,430,"5464","",0,"","","",1,0,0,[],""],["rm_t3-n5465",1,"Ar pié del armendro estube\nY no le cogí la fló,\nY asin que m' arretiré,\nOtro yegó y la cogió.",1,0,-1,8,"",0,4,"o",2,0,-1,0,430,430,"5465","",0,"","","",1,0,0,[],""],["rm_t3-n5466",1,"Arbolito, te secastes\nTeniendo 'l agüita ar pié,\nEn er tronco la firmesa\nY en la yemita er queré.",1,0,-1,8,"",0,4,"e",77,0,-1,0,430,430,"5466","",0,"","","",2,0,0,[],""],["rm_t3-n5467",1,"Yo tuve un árbol sembrado\nY regado con querer,\nY á lo mejor se ha secado;\n¡Mal haya quien quiere bien!",1,0,-1,8,"",0,4,"e",-1,0,-1,0,430,430,"5467","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5468",1,"Yo sembré en una maceta\nLa fundacion del querer,\nY aunque la regué con llanto,\nNo quiso prevalecer.",1,0,-1,8,"",0,4,"e",20,0,-1,0,430,430,"5468","",0,"","","",2,0,0,[],""],["rm_t3-n5469",1,"Me puse' ajondar un poso\nCon mucho gusto y plasé;\nMe salió amarguita 'l agua,\nL' eché tierra y lo segué.",1,0,-1,8,"",0,4,"e",77,0,-1,0,430,430,"5469","",0,"","","",1,0,0,[],""],["rm_t3-n5470",1,"A labrador de amores\nMe eché algun tiempo;\nSembré tiernas finezas;\nCogí desprecios.",1,0,-1,8,"",6,4,"eo",-1,0,-1,0,431,431,"5470","",0,"","","",1,0,0,[],""],["rm_t3-n5471",1,"Unos amores sembré\nY de vicio no granaron;\nLa simiente he de coger,\nPorque los sembré temprano.",1,0,-1,8,"",0,4,"ao",-1,0,-1,0,431,431,"5471","",0,"","","",1,0,0,[],""],["rm_t3-n5472",1,"Yo me metí á labradó;\nMi pensamiento fué bano:\nYo sembré 'n un peñascá,\nPensando qu' era en un yano.",1,0,-1,8,"",0,4,"ao",81,0,-1,0,431,431,"5472","",0,"","","",1,0,0,[],""],["rm_t3-n5473",1,"Yo tomé un cortijo á renta;\nLo tomé por tiempo largo;\nLa cuenta me salió mala,\nY tuve al fin que dejarlo.",1,0,-1,8,"",0,4,"ao",-1,0,-1,0,431,431,"5473","",0,"","","",2,0,0,[],""],["rm_t3-n5474",1,"Yo tenía una biñita,\nLa poaba y la cababa,\nLe daba su laborsita,\n¡Y otro me la bendimiaba!",1,0,-1,8,"",1,4,"aa",28,0,-1,0,431,431,"5474","",0,"","","",1,0,0,[],""],["rm_t3-n5477",1,"Yo sembré tierra morena\nCon intension de ser rico;\n¡Trigo, sebada y abena\nSe m' ha buerto á mí bayico!",1,0,-1,8,"",1,4,"io",141,0,-1,0,432,432,"5477","",0,"","","",1,0,0,[],""],["rm_t3-n5478",1,"En bista de lo que beo,\nYa no creo ni en mi madre:\nQu' el oro fino en la mano\nSe m' ha güerto á mí metales.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,432,432,"5478","",0,"","","",1,0,0,[],""],["rm_t3-n5479",1,"Me fié de la berdá,\nY la berdá m' engañó;\nCuando la berdá m' engaña,\n¿De quién me fiaré yo?",1,0,-1,8,"",0,4,"o",2,0,-1,0,432,432,"5479","",0,"","","",1,0,0,[],""],["rm_t3-n5480",1,"Aunque tengo mal color,\nNo te pienses cosas malas:\nSon penas del corazon\nQue me salen á la cara.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,432,432,"5480","",0,"","","",3,0,0,[],""],["rm_t3-n5481",1,"Aunque me ves amarilla,\nMi bien, no he comido tierra;\nTus amores y los mios\nMe tienen de esta manera.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,432,432,"5481","",0,"","","",1,0,0,[],""],["rm_t3-n5482",1,"-¿Qué has comido, que tienes\nPálido el color?\n-He comido cenizas\nDel fuego de amor.",1,0,-1,8,"",0,4,"o",72,0,-1,0,432,432,"5482","",0,"","","",1,0,0,[],""],["rm_t3-n5484",1,"Desde que te conosí,\nTubo mi cuerpo más pérdia\nQue tubo aquer montañés\nQue se le quemó la tienda.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,433,433,"5484","",0,"","","",2,0,0,[],""],["rm_t3-n5485",1,"Sin bida tu amor me tiene;\nSin salú boy por la tierra;\nCuando la muerte me busque,\nDe juro que no m' encuentra.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,433,433,"5485","",0,"","","",1,0,0,[],""],["rm_t3-n5486",1,"Como er panar de la sera\nTengo yo mis propias carnes;\nQue m' ha puesto tu queré,\nQue no me conose nádie.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,433,433,"5486","",0,"","","",1,0,0,[],""],["rm_t3-n5487",1,"Conoserás por las señas\nQue traigo difunto er rostro;\nQue m' ha puesto tu queré,\nQue yo mismo me conosco.",1,0,-1,8,"",0,4,"oo",-1,0,-1,0,433,433,"5487","",0,"","","",1,0,0,[],""],["rm_t3-n5488",1,"No sé cómo no estoy loco\nCon esta pena que tengo;\nQue me ha puesto tu querer\nTonto, sordo, mudo y ciego.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,433,433,"5488","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5489",1,"Ya mi mar no tiene cura,\nComo der sielo no benga;\nQue m' ha puesto tu querer,\nQue me ba á tragar la tierra.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,433,433,"5489","",0,"","","",1,0,0,[],""],["rm_t3-n5490",1,"No me mires ála cara,\nQue no tengo más que güesos:\nMira tus malas partías\nDe la suerte que m' han puesto.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,433,433,"5490","",0,"","","",1,0,0,[],""],["rm_t3-n5491",1,"Por tus quereles, serrana,\nMe boy quedando en la espina:\nEstoy, que me yeba 'r biento\nAr reborbé d' una esquina.",1,0,-1,8,"",0,4,"ia",11,0,-1,0,434,434,"5491","",0,"","","",2,0,0,[],""],["rm_t3-n5493",1,"Si me encuentras en la calle,\nNo me debes conocer;\nQue estoy hecho un esqueleto,\nDe pensar en tu querer.",1,0,-1,8,"",0,4,"e",20,0,-1,0,434,434,"5493","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n5494",1,"Si me encuentras en la calle,\nYa no me conocerás;\nQue acaba más una pena\nQue una larga enfermedad.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,434,434,"5494","",0,"","","",4,0,0,[],""],["rm_t3-n5496",1,"Una bela de dos onsas\nParese este cuerpo mio,\nQue de puro sentir penas,\nS' ha quedao consumío.",1,0,-1,8,"",0,4,"io",3,0,-1,0,434,434,"5496","",0,"","","",1,0,0,[],""],["rm_t3-n5497",1,"Si en la calle me encontrares\nY me quisieres hablar,\nRepara y mira mi sombra;\nQue ella te responderá.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,434,434,"5497","",0,"","","",1,0,0,[],""],["rm_t3-n5498",1,"Como pases por mi puerta\nY m' eches una mirâ,\nSi tienes sangre en las benas,\nTe tienes qu' echá á yorá.",1,0,-1,8,"",5,4,"a",-1,0,-1,0,435,435,"5498","",0,"","","",1,0,0,[],""],["rm_t3-n5499",1,"Ya no soy yo quien he sido\nNi quien yo solia ser:\nSoy un cuadro de tristezas,\nArrimado á la paré.",1,0,-1,8,"",0,4,"e",-1,0,-1,0,435,435,"5499","",0,"","","",2,0,0,[],""],["rm_t3-n5500",1,"Ya yo no bibo en er mundo,\nQue lo que bibe es mi sombra;\nTengo mi cuerpo metío\nEn una oscura masmorra.",1,0,-1,8,"",0,4,"oa",-1,0,-1,0,435,435,"5500","",0,"","","",1,0,0,[],""],["rm_t3-n5501",1,"Pare mio Jesús,\nDarbos por contento;\nQue no le quean - á este cuerpo mio\nNâ más que los güesos.",1,0,-1,8,"",3,4,"eo",-1,0,-1,0,435,435,"5501","",0,"","","",1,0,0,[],""],["rm_t3-n5502",1,"Hasta la cama en que duermo\nTiene lástima de mí,\nAl ver que suspiro y lloro\nCuando me acuerdo de tí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,435,435,"5502","",0,"","","",7,0,0,[],""],["rm_t3-n5503",1,"Hasta la cama en que duermo\nSe queja de mi dolor;\nSiendo madera y lo siente,\n¡Qué será mi corazon!",1,0,-1,8,"",0,4,"o",-1,0,-1,0,435,435,"5503","",0,"","","",7,0,0,[],""],["rm_t3-n5505",1,"Ar pié de una crus bendita\nDe rodiyas me jinqué;\nLas lágrimas que yoraba\nSe quejaban ar caé.",1,0,-1,8,"",0,4,"e",77,0,-1,0,436,436,"5505","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t3-n5506",1,"A un Santo Cristo de acero\nLe hice yo que llorara;\nSiendo de acero y lloró,\n¡Qué fuera de carne humana!",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,436,436,"5506","",0,"","","",4,0,0,[],""],["rm_t3-n5507",1,"A un Santo Cristo de acero\nLe conté yo mi dolor;\n¡Mira qué dolor sería,\nQue el Santo Cristo lloró!",1,0,-1,8,"",0,4,"o",-1,0,-1,0,436,436,"5507","",0,"","","",4,0,0,[],""],["rm_t3-n5508",1,"A los montes me pasé\nA llorar mis desengaños,\nY eran tan grandes mis penas,\nQue hasta las fieras lloraron.",1,0,-1,8,"",0,4,"ao",-1,0,-1,0,436,436,"5508","",0,"","","",1,0,0,[],""],["rm_t3-n5509",1,"En la soledá der campo\nMe puse á yorar mis penas,\nY fué tan grande mi yanto,\nQue floresieron las yerbas.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,436,436,"5509","",0,"","","",1,0,0,[],""],["rm_t3-n5510",1,"¿Cómo quieres que yo vaya\nAl jardin de la alegría,\nSi se marchitan las flores\nAl ver esta pena mia?",1,0,-1,8,"",0,4,"ia",0,0,-1,0,436,436,"5510","",0,"","","",3,0,0,[],""],["rm_t3-n5511",1,"De noche me sargo ar campo\nY en er sitio aonde me siento,\nJasta las yerbas que piso\nSe secan de sentimiento.",1,0,-1,8,"",3,4,"eo",94,0,-1,0,436,436,"5511","",0,"","","",2,0,0,[],""],["rm_t3-n5512",1,"Me puse á llorar mis penas\nEn un monte de espesura,\nY se secaron las ramas,\nQuedando raíces puras.",1,0,-1,8,"",0,4,"ua",-1,0,-1,0,437,437,"5512","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5513",1,"Ayer tarde salí ar campo\nA yorar por mi sentir,\nY á un árbo que m' escuchaba\nSe le secó la raís.",1,0,-1,8,"",0,4,"i",-1,0,-1,0,437,437,"5513","",0,"","","",1,0,0,[],""],["rm_t3-n5514",1,"Yo me arrimé á un árbol verde\nY se le secó la flor;\n¡Mal haya quien se enamora,\nPara vivir con dolor!",1,0,-1,8,"",0,4,"o",72,0,-1,0,437,437,"5514","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t3-n5515",1,"Ar pié d' un pinito berde\nCon sentimiento yoraba,\nPor ber si con er yantito\nLas hojas se le secaban.\nY á fuersa de tanto yanto,\nSe l' ha secaíyo er tronco.\n¡Mal haya quien yora tanto!",1,0,-1,8,"",4,7,"ao",30,0,-1,0,437,437,"5515","",0,"","","",1,0,0,[],""],["rm_t3-n5516",1,"Ebajo ' un armendro\nMe puse cantando;\nLas armendritas - qu' arribita habia\nBinieron abajo.",1,0,-1,8,"",3,4,"ao",-1,0,-1,0,437,437,"5516","",0,"","","",1,0,0,[],""],["rm_t3-n5517",1,"Ebajo ' un olibo\nMe puse á yorá,\nY olibarito - más esgrasiaíto\nNi lo hay ni lo habrá.",1,0,-1,8,"",3,4,"a",9,0,-1,0,437,437,"5517","",0,"","","",1,0,0,[],""],["rm_t3-n5518",1,"Yo m' arrimé á un pino berde\nPor ber si me consolaba,\nY er pino, como era berde,\nDe berme yorar yoraba.",1,0,-1,8,"",1,4,"aa",28,0,-1,0,437,438,"5518","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t3-n5519",1,"Si las piedras de tu calle\nTuvieran conocimiento,\nCuando me vieran venir\nLloraran de sentimiento.",1,0,-1,8,"",0,4,"eo",94,0,-1,0,438,438,"5519","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t3-n5520",1,"Jasta las piedras más jondas\nQue tiene 'r mar en su sentro\nTienen de salí á la oriya\nA yorá mi sentimiento.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,438,438,"5520","",0,"","","",1,0,0,[],""],["rm_t3-n5521",1,"De noche no caigo en cama,\nY hago las piedras yorar,\nDe ber con las fatiguiyas\nCon que t' empieso á yamá.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,438,438,"5521","",0,"","","",1,0,0,[],""],["rm_t3-n5522",1,"Desde que paso tu calle\nEnamorado de ti,\nEstán llorando las piedras,\nDe verme llorar á mí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,438,438,"5522","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5523",1,"A una piedra de la calle\nLe conté yo mi dolor;\n¡Mira tú qué le diria,\nQue la piedra se partió!",1,0,-1,8,"",0,4,"o",-1,0,-1,0,438,438,"5523","",0,"","","",5,0,0,[],""],["rm_t3-n5525",1,"Yo tomé la caye arriba,\nBí una piedra y me senté;\nDe la pena que yebaba,\nLa piedra la quebranté.",1,0,-1,8,"",0,4,"e",77,0,-1,0,438,439,"5525","",0,"","","",1,0,0,[],""],["rm_t3-n5526",1,"Ar campo yo me salí\nMis penitas á yorá,\nY una piedra que ayí habia\nSe partió por la mitá.",1,0,-1,8,"",0,4,"a",9,0,-1,0,439,439,"5526","",0,"","","",1,0,0,[],""],["rm_t3-n5528",1,"La piedra, con ser la piedra,\nAl golpe del eslabon\nEcha lágrimas de fuego;\n¿Qué será mi corazon?",1,0,-1,8,"",0,4,"ao",-1,0,-1,0,439,439,"5528","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5529",1,"Cuando me meto en mi cuarto\nPâ lamentar mis penitas,\nDe los suspiros que pego\nLas paeres s' escalichan.",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,439,439,"5529","",0,"","","",1,0,0,[],""],["rm_t3-n5530",1,"Cuando en er patio me siento\nY en tí comienso á pensá,\nLas paeres s' escalichan,\nDe fatigas que le dan.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,439,439,"5530","",0,"","","",1,0,0,[],""],["rm_t3-n5531",1,"A yorar me sargo ar campo\nY en un bayao me siento;\nDe fatigas que le dan\nSe menean los simientos.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,439,439,"5531","",0,"","","",1,0,0,[],""],["rm_t3-n5532",1,"Yo me subí á la muraya\nA yorar mi sentimiento;\nFueron tan grandes mis ducas,\nQue temblaron los simientos.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,439,440,"5532","",0,"","","",2,0,0,[],""],["rm_t3-n5533",1,"A una murayita firme\nLe conté yo mi doló,\nY la muraya al oirme\nA peasos se cayó.",1,0,-1,8,"",1,4,"o",2,0,-1,0,440,440,"5533","",0,"","","",1,0,0,[],""],["rm_t3-n5535",1,"Si estas ducas mias\nMucho me duraran,\nNo quearia -murayita en tierra\nQue yo no erribara.",1,0,-1,8,"",3,4,"aa",-1,0,-1,0,440,440,"5535","",0,"","","",1,0,0,[],""],["rm_t3-n5536",1,"Los ejes der mundo tiemblan\nAl oirme suspirá;\nLas campanas clamorean:\n«¡Muera quien mar pago da!»",1,0,-1,8,"",0,4,"a",9,0,-1,0,440,440,"5536","",0,"","","",1,0,0,[],""],["rm_t3-n5537",1,"Er sielo se bistió e luto;\nLa tierras' echó á temblá;\nLas campanas reoblaron;\n¡Muera quien mar pago da!",1,0,-1,8,"",0,4,"a",9,0,-1,0,440,440,"5537","",0,"","","",2,0,0,[],""],["rm_t3-n5538",1,"La tierra sintió mi muerte;\nLas campanas reoblaron;\nLas seporturas s'abrieron;\nLos muertos resusitaron.",1,0,-1,8,"",0,4,"ao",41,0,-1,0,440,440,"5538","",0,"","","",1,0,0,[],""],["rm_t3-n5539",1,"¡Muchachos, apedrearme;\nSalir, perros, y morderme;\nQue una niña d'esta caye\nM'ha dicho que no me quiere!",1,0,-1,8,"",0,4,"ee",-1,0,-1,0,440,441,"5539","",0,"","","",1,0,0,[],""],["rm_t3-n5541",1,"Ya no tengo yo en mi pecho\nPaciencia para sufrir;\nSiempre me estoy acordando\nDe quien se olvida de mí.",1,0,-1,8,"",0,4,"i",-1,0,-1,0,441,441,"5541","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5544",1,"Empecemos, corazon,\nA padecer y penar;\nPues adoro un imposible\nQue no he de poder lograr.",1,0,-1,8,"",0,4,"a",21,0,-1,0,441,441,"5544","",0,"palau_cantares, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["rm_t3-n5545",1,"¿Qué saco yo de quererte\nNi vivir por tí penando,\nSi tú no puedes ser mia,\nComo Dios no haga un milagro?",1,0,-1,8,"",0,4,"ao",-1,0,-1,0,441,441,"5545","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5546",1,"Yo sé que contigo\nNo m'he de lográ;\nAsí mis ducas - nunca ban á ménos;\nSiempre ban á más.",1,0,-1,8,"",3,4,"a",-1,0,-1,0,441,441,"5546","",0,"","","",1,0,0,[],""],["rm_t3-n5547",1,"¿Qué importa que tú me quieras\nY que yo te quiera á tí,\nSi lo que yo solicito\nNo lo puedo conseguir?",1,0,-1,8,"",0,4,"i",-1,0,-1,0,442,442,"5547","",0,"palau_cantares, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["rm_t3-n5548",1,"¿Cuándo querrá Dios del cielo\nQue mis deseos se cumplan?\nSegun lo que yo voy viendo,\nSerá tarde, mal y nunca.",1,0,-1,8,"",0,4,"ua",-1,0,-1,0,442,442,"5548","",0,"","","",11,0,0,[],""],["rm_t3-n5549",1,"El librito de mi sino\nTodas las noches lo leo,\nY en el primer renglon dice:\n«Morirás con el deseo.»",1,0,-1,8,"",0,4,"eo",66,0,-1,0,442,442,"5549","",0,"","","",1,0,0,[],""],["rm_t3-n5550",1,"Por una María muero\nY no me la quieren dar;\nLa que me dan, no la quiero;\nLa que quiero, no me dan.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,442,442,"5550","",0,"","","",1,0,0,[],""],["rm_t3-n5551",1,"Dentro de mi pecho habita\nUna penita mortal,\nPorque quiero á una rubita\nY no me la quieren dar.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,442,442,"5551","",0,"","","",2,0,0,[],""],["rm_t3-n5552",1,"Tengo una pena conmigo\nY una congoja mortal;\nMe encuentro con dos caminos,\nSin saber por cuál tomar.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,442,442,"5552","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t3-n5553",1,"¡En qué confusion me veo,\nTriste y sin saber qué hacer!\nOlvidarla es imposible;\nQuererla no puede ser.",1,0,-1,8,"",0,4,"e",20,0,-1,0,442,442,"5553","",0,"","","",1,0,0,[],""],["rm_t3-n5554",1,"El quererte es imposible;\nOlvidarte no lo haré;\nVerte en manitas de otro,\nNo lo permita Undebé.",1,0,-1,8,"",0,4,"e",77,0,-1,0,443,443,"5554","",0,"","","",1,0,0,[],""],["rm_t3-n5555",1,"Mi corazon y mi alma\nDentro de mí tienen guerra;\nMi corazon, que te olvide;\nY mi alma, que te quiera.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,443,443,"5555","",0,"","","",1,0,0,[],""],["rm_t3-n5556",1,"Mal haya quien me dió á mí\nTanto amor para quererte;\nQue ahora para olvidarte\nSon mis fatigas de muerte.",1,0,-1,8,"",0,4,"ee",134,0,-1,0,443,443,"5556","",0,"","","",3,0,0,[],""],["rm_t3-n5557",1,"Nacimos para querernos;\nCon mala estrella nacimos;\nNi tú puedes olvidarme,\nNi yo olvidarte consigo.",1,0,-1,8,"",0,4,"io",-1,0,-1,0,443,443,"5557","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5558",1,"No me digas que te olvide,\nQue me lo dices llorando;\nToma tú misma el consejo\nY podrás venir á darlo.",1,0,-1,8,"",0,4,"ao",-1,0,-1,0,443,443,"5558","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n5559",1,"Quisiera que Dios me diera\nUn olvidar cariñoso;\nQue yo te fuera olvidando\nY tú quedaras gustoso.",1,0,-1,8,"",0,4,"oo",160,0,-1,0,443,443,"5559","",0,"","","",3,0,0,[],""],["rm_t3-n5560",1,"Quisiera verte y no verte;\nQuisiera hablarte y no hablarte;\nQuisiera no conocerte,\nPara poder olvidarte.",1,0,-1,8,"",1,4,"ae",8,0,-1,0,443,443,"5560","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",12,0,0,[],""],["rm_t3-n5561",1,"¡Ay de mí, que siendo niña\nLe dí palabra á un mancebo,\nY por temor á mi padre,\nA cumplirla no me atrevo!",1,0,-1,8,"",0,4,"eo",240,0,-1,0,444,444,"5561","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5563",1,"Por donde quiera que boy\nYebo puesto un bigilante;\nUna palabrita que hablo,\nDosientas ban á contarte.",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,444,444,"5563","",0,"","","",1,0,0,[],""],["rm_t3-n5564",1,"Si me quitan el verte,\nQue es mi alimento,\nSuban al campanario,\nToquen á muerto.",1,0,-1,8,"",6,4,"eo",-1,0,-1,0,444,444,"5564","",0,"rm_t2, preciso_coleccion","","",3,0,0,[],""],["rm_t3-n5565",1,"Devoto de San Antonio\nToda mi vida lo he sido,\nY ahora me quieren quitar\nTu devocion, santo mio.",1,0,-1,8,"",3,4,"o",-1,0,-1,0,444,444,"5565","",0,"","","",1,0,0,[],""],["rm_t3-n5566",1,"Me quieren quitar á mí\nEl ir á misa por verte;\nNo le echo la culpa á nádie,\nSino es á mi mala suerte.",1,0,-1,8,"",0,4,"ee",134,0,-1,0,444,444,"5566","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t3-n5567",1,"Ya se acabó para mí\nGusto, placer y alegría;\nRatos de conversacion\nQue yo contigo tenía.",1,0,-1,8,"",0,4,"ia",0,0,-1,0,444,444,"5567","",0,"","","",1,0,0,[],""],["rm_t3-n5568",1,"Quédate con Dios, salada;\nMucho me duele el dejarte;\nPero tambien considero\nQue siempre no puedo hablarte.",1,0,-1,8,"",0,4,"ae",8,0,-1,0,445,445,"5568","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t3-n5569",1,"De aquí tengo que ausentarme;\nMi querer está en peligro;\nRaices va ya criando,\nComo en el suelo el olivo.",1,0,-1,8,"",0,4,"io",-1,0,-1,0,445,445,"5569","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t3-n5570",1,"A esos montes me he de ir,\nAunque me coman las fieras;\nPorque ojitos que no ven\nCorazoncito no quiebran.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,445,445,"5570","",0,"","","",2,0,0,[],""],["rm_t3-n5571",1,"A esos montes me he de ir\nA tratar con animales;\nQue puede ser que aunque fieras,\nObren como racionales.",1,0,-1,8,"",0,4,"ae",26,0,-1,0,445,445,"5571","",0,"","","",2,0,0,[],""],["rm_t3-n5572",1,"Más valia que mis ojos\nNunca te hubieran mirado;\nCon eso no viviria\nEn sino tan desgraciado.",1,0,-1,8,"",0,4,"ao",14,0,-1,0,445,445,"5572","",0,"","","",1,0,0,[],""],["rm_t3-n5573",1,"Ar barrio de la Bitoria\nSel' han corrío los belos; (?)\nQuiero entrar y no me dejan;\nQuiero salir y no pueo.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,445,445,"5573","",0,"","","",1,0,0,[],""],["rm_t3-n5575",1,"No me tires chinitos\nA la ventana;\n¡Me ha quitado mi madre\nDe allí la cama!",1,0,-1,8,"",6,4,"aa",-1,0,-1,0,446,446,"5575","",0,"","","",2,0,0,[],""],["rm_t3-n5576",1,"El cielo está nublado\nCon varias nubes;\nOcasion para hablarte\nNunca la tuve.",1,0,-1,8,"",6,4,"ue",-1,0,-1,0,446,446,"5576","",0,"","","",1,0,0,[],""],["rm_t3-n5577",1,"Muchas fatigas me dieron,\nMuchas ganas e yorá,\nCuando te bie 'n la caye\nY no te pue naquerá.",1,0,-1,8,"",0,4,"a",9,0,-1,0,446,446,"5577","",0,"","","",1,0,0,[],""],["rm_t3-n5578",1,"¡Desgraciado el labrador\nQue siembra y no coge trigo!\nMás desgraciado soy yo,\nQue no puedo hablar contigo.",1,0,-1,8,"",0,4,"io",106,0,-1,0,446,446,"5578","",0,"","","",1,0,0,[],""],["rm_t3-n5579",1,"Este vivir no es vivir:\n¡Verte y no poderte hablar...!\nEsto, mi bien, es morir.\n¿Para qué tanto penar?",1,0,-1,8,"",1,4,"a",21,0,-1,0,446,446,"5579","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5580",1,"Tengo pleito con mi madre,\nSi no lo gano me muero,\nPorque quiere que me case\nCon uno que yo no quiero.",1,0,-1,8,"",0,4,"eo",38,0,-1,0,446,446,"5580","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t3-n5582",1,"Cada vez que paso y miro\nDonde mi amante vivió,\nMe contento con la jaula,\nQue ya el pájaro voló.",1,0,-1,8,"",0,4,"o",2,0,-1,0,448,448,"5582","",0,"carrizo_salta","","",24,0,0,[],""],["rm_t3-n5583",1,"El corazon se me parte\nDe pena y de sentimiento,\nAl ver que estás en el mundo\nY ya para mí te has muerto.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,448,448,"5583","",0,"","","",6,0,0,[],""],["rm_t3-n5585",1,"Las telas del corazon\nSe me cubren de tristeza,\nDe ver que estás en el mundo\nY ya para mí estás muerta.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,448,448,"5585","",0,"","","",2,0,0,[],""],["rm_t3-n5587",1,"En er sielo se formó\nUna nube muy escura;\nYa para mí s' acabó\nEr difrutá tu hermosura.",1,0,-1,8,"",1,4,"ua",17,0,-1,0,448,448,"5587","",0,"","","",1,0,0,[],""],["rm_t3-n5588",1,"Ya se acabó mi querer;\nYa se acabó mi alegría;\nNo hay una pena en el mundo\nQue se iguale con la mia.",1,0,-1,8,"",0,4,"ia",0,0,-1,0,449,449,"5588","",0,"","","",1,0,0,[],""],["rm_t3-n5589",1,"Ya para mí las glorias\nEn este mundo\nSe volvieron pavesas,\nCeniza y humo.\nSiendo tan cierto,\nQue aumenta más mis penas\nEl pensamiento.",1,0,-1,8,"",4,7,"eo",-1,0,-1,0,449,449,"5589","",0,"","","",2,0,0,[],""],["rm_t3-n5590",1,"«¡Esperanzas amantes!»\nMi voz repite,\nCuando mis esperanzas\nMiro imposibles.\nPues mi desgracia\nSólo para perderlas\nPudiera hallarlas.",1,0,-1,8,"",4,7,"aa",-1,0,-1,0,449,449,"5590","",0,"","","",1,0,0,[],""],["rm_t3-n5591",1,"Murieron mis esperansas;\nYa s' acabó mi alegría;\nYa no tengo que perdé,\nComo no pierda la bía.",1,0,-1,8,"",0,4,"ia",0,0,-1,0,449,449,"5591","",0,"","","",1,0,0,[],""],["rm_t3-n5592",1,"Aguarda, caminante;\nDetén el paso\nY enjuga de mis ojos\nEl triste llanto.\nPorque aquí yace\nLa fúnebre esperanza\nDe un triste amante.",1,0,-1,8,"",4,7,"ae",-1,0,-1,0,449,449,"5592","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],""],["rm_t3-n5593",1,"Hoy se hacen las exequias\nDe una esperanza,\nQue murió cuando ménos\nElla pensaba.\nY en este en ti erro\nSu mismo desengaño\nSirve de duelo.",1,0,-1,8,"",4,7,"eo",-1,0,-1,0,450,450,"5593","",0,"","","",2,0,0,[],""],["rm_t3-n5594",1,"¡Bírgen der Cármen, balerme,\nQue yo me muero de pena;\nQue perdí las esperansas,\nComo aquer que se condena!",1,0,-1,8,"",0,4,"ea",59,0,-1,0,450,450,"5594","",0,"","","",2,0,0,[],""],["rm_t3-n5595",1,"Mal haya er dinero;\nQu' er dinero es causa\nQue los ojitos- e quien bien yo quiero\nNo estén en mi casa.",1,0,-1,8,"",3,4,"aa",-1,0,-1,0,450,450,"5595","",0,"","","",1,0,0,[],""],["rm_t3-n5596",1,"¡Ay, mal haya, mal haya\nMi cobardía;\nQue por ser yo cobarde,\nNo eres tú mia!",1,0,-1,8,"",6,4,"a",0,0,-1,0,450,450,"5596","",0,"","","",1,0,0,[],""],["rm_t3-n5597",1,"Sale la cruz de la iglesia,\nVestida de luto negro;\n¡Harta cruz tiene el que quiere\nPrenda que tiene otro dueño!",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,450,450,"5597","",0,"","","",3,0,0,[],""],["rm_t3-n5598",1,"Sale la cruz de la iglesia,\nVestida de negro luto;\n¡Harto trabajito tiene\nEl que no logra su gusto!",1,0,-1,8,"",0,4,"uo",-1,0,-1,0,450,450,"5598","",0,"","","",3,0,0,[],""],["rm_t3-n5599",1,"¡Ay de mí, que me han quitado\nUna rosa siendo mia,\nY la veo en otras manos,\nMarchita y descolorida!",1,0,-1,8,"",0,4,"ia",-1,0,-1,0,450,451,"5599","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5600",1,"No siento haber perdido\nTanto una alhaja\nComo que ya'no brille\nComo brillaba.\nQue en otra mano\nEl color de sus perlas\nEstá empañado.",1,0,-1,8,"",4,7,"ao",-1,0,-1,0,451,451,"5600","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5601",1,"Cada vez que considero\nQue te has casado por fin,\nLlamo á la muerte y le digo:\n-¿Cuándo has de venir por mí?",1,0,-1,8,"",0,4,"i",-1,0,-1,0,451,451,"5601","",0,"palau_cantares, lafuente_madrid","","",14,0,0,[],""],["rm_t3-n5602",1,"Yo no deseo la muerte,\nPorque es pecado mortal;\nPero sé que hasta que muera\nDescanso no he de encontrar.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,451,451,"5602","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t3-n5603",1,"Entre las sombras tristes\nDe oscura noche\nBusca mi triste pecho\nQuien le devore.\nPero mi suerte,\nPor no darme consuelo,\nNo halla la muerte.",1,0,-1,8,"",4,7,"ee",134,0,-1,0,451,451,"5603","",0,"","","",2,0,0,[],""],["rm_t3-n5605",1,"Horitas tengo en el dia\nDe sentimiento y de pena;\nSi la muerte me llevara,\nCreo que no lo sintiera.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,451,452,"5605","",0,"","","",3,0,0,[],""],["rm_t3-n5606",1,"De noche me sargo ar campo\nA yorar mi mala suerte;\nHoritas tengo en er dia\nQu' á boses yamo á la muerte.",1,0,-1,8,"",0,4,"ee",134,0,-1,0,452,452,"5606","",0,"","","",2,0,0,[],""],["rm_t3-n5607",1,"Más balia que mi madre\nAr punto que me parió\nMe hubiera dado la muerte,\nY no padesiera yo.",1,0,-1,8,"",0,4,"o",2,0,-1,0,452,452,"5607","",0,"","","",1,0,0,[],""],["rm_t3-n5608",1,"Más valia que mi madre\nMe hubiera dado la muerte;\nCon éso mi corazon\nNo sintiera lo que siente.",1,0,-1,8,"",0,4,"ee",-1,0,-1,0,452,452,"5608","",0,"","","",1,0,0,[],""],["rm_t3-n5609",1,"A Dios le diera mi arma,\nY er cuerpo á la mar serena,\nY er corason á la Bígen\nDe Consolasion d' Utrera.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,452,452,"5609","",0,"","","",1,0,0,[],""],["rm_t3-n5610",1,"Yo quisiera morirme\nY oir el doble,\nA ver quién me decía:\n-Dios te perdone.",1,0,-1,8,"",6,4,"oe",-1,0,-1,0,452,452,"5610","",0,"","","",2,0,0,[],""],["rm_t3-n5611",1,"Quisiera morirme hoy mismo,\nSin esperar á mañana,\nPorque las penas me ahogan\nY los pesares me matan.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,452,452,"5611","",0,"","","",1,0,0,[],""],["rm_t3-n5612",1,"La soledad me acompaña,\nLa música me entristece,\nPues aborrezco la vida,\nPues apetezco la muerte.",1,0,-1,8,"",0,4,"ee",-1,0,-1,0,452,453,"5612","",0,"","","",4,0,0,[],""],["rm_t3-n5613",1,"Ya yo he perdío er sentío;\nS' acabó er mundo pâ mí;\nPâ bibí con tanta pena,\nMás bien quisiera morí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,453,453,"5613","",0,"","","",1,0,0,[],""],["rm_t3-n5614",1,"Desdichada pasion mia,\nMátame con tu rigor;\nNo atormentes mi memoria\nNi recuerdes mi dolor.",1,0,-1,8,"",0,4,"o",72,0,-1,0,453,453,"5614","",0,"","","",1,0,0,[],""],["rm_t3-n5615",1,"Acaba, penita, acaba;\nDame muerte de una vez;\nQue con el morir se acaba\nLa pena y el padecer.",1,0,-1,8,"",0,4,"e",-1,0,-1,0,453,453,"5615","",0,"","","",3,0,0,[],""],["rm_t3-n5619",1,"Ábreme la seportura,\nQue me quió yo meté dentro:\nQue una mujé 'sgrasiaíta\nLa comparo con los muertos.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,453,453,"5619","",0,"","","",1,0,0,[],""],["rm_t3-n5620",1,"¡Cuántas personiyas reales\nBiene la muerte y se lleba,\nY á mi no me quiê yebá,\nQue se lo pío de béras!",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,454,454,"5620","",0,"","","",1,0,0,[],""],["rm_t3-n5621",1,"De pena y de sentimiento\nNo me trato con la gente;\nEn los rincones me meto\nY á voces llamo á la muerte.",1,0,-1,8,"",0,4,"ee",-1,0,-1,0,454,454,"5621","",0,"","","",4,0,0,[],""],["rm_t3-n5622",1,"A la muerte le digo:\n-Dame tu mano,\nQue de andar por la vida\nYa estoy cansado.-\nPero la muerte\nNunca va á quien la llama:\nVa á quien la teme.",1,0,-1,8,"",4,7,"ee",-1,0,-1,0,454,454,"5622","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5623",1,"Y amé á la muerte y le dij e\nQue biniera y me yebara,\nY me contestó la muerte\nQue sufriera y esperara.",1,0,-1,8,"",3,4,"aa",57,0,-1,0,454,454,"5623","",0,"","","",1,0,0,[],""],["rm_t3-n5624",1,"¿No hay quien me pegue un tirito\nQue me parta er corason...?\nEstoy bibiendo en er mundo\nCon munchísima esason.",1,0,-1,8,"",0,4,"ao",241,0,-1,0,454,454,"5624","",0,"","","",3,0,0,[],""],["rm_t3-n5625",1,"Si en la muerte descansara,\nYo mismo me la daria;\nQu' er que nase desgrasiao,\n¿Para qué quiere la bía?",1,0,-1,8,"",0,4,"ia",0,0,-1,0,454,454,"5625","",0,"","","",1,0,0,[],""],["rm_t3-n5626",1,"Quisiera tener la vida\nQue tienen todos los hombres,\nPara estar solo en el mundo\nY tirarme de la torre.",1,0,-1,8,"",0,4,"oe",-1,0,-1,0,454,455,"5626","",0,"","","",1,0,0,[],""],["rm_t3-n5627",1,"A la mar fuera y me echara;\nPero ¿qué dirá la gente?\nQue vivo desesperado\nY ando buscando la muerte.",1,0,-1,8,"",0,4,"ee",-1,0,-1,0,455,455,"5627","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5628",1,"Estando solita y triste,\nEn un poso me iba á echar;\nLlegó la Bírgen der Cármen\nY m' agarró por detrás.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,455,455,"5628","",0,"","","",1,0,0,[],""],["rm_t3-n5630",1,"Hermanita mia,\nPor Dios, no me yores,\nY las faitigas - grandes que terelo\nNo me las reobles.",1,0,-1,8,"",3,4,"oe",-1,0,-1,0,455,455,"5630","",0,"","","",1,0,0,[],""],["rm_t3-n5632",1,"A las rejas de la cárse\nNo me bengas á yorá;\nYa que no me quitas penas,\nNo me las bengas á da.",1,0,-1,8,"",0,4,"a",9,0,-1,0,455,455,"5632","",0,"","","",1,0,0,[],""],["rm_t3-n5633",1,"Dil' usté á mi bata,\nPor amor de Dios,\nComo en prisiones - se yeban al hijo\nE su corason.",1,0,-1,8,"",3,4,"ao",-1,0,-1,0,455,455,"5633","",0,"","","",2,0,0,[],""],["rm_t3-n5634",1,"Dígale usté á mi serrana\nQue se consuele y no yore;\nQue algun dia querrá Dios\nQue se acaben mis prisiones.",1,0,-1,8,"",0,4,"oe",-1,0,-1,0,456,456,"5634","",0,"","","",1,0,0,[],""],["rm_t3-n5635",1,"Mi marío tengo preso;\nYo 'stoy en el hospitá;\nÉr ruega por mi salú\nY yo por su libertá.",1,0,-1,8,"",0,4,"a",9,0,-1,0,456,456,"5635","",0,"","","",1,0,0,[],""],["rm_t3-n5636",1,"Debajo de la hoja\nDe la verbena(?)\nEstá mi amante preso;\n¡Jesús, qué pena!\n¡Ay, verbenita!\nEcha á mi amante fuera,\nQue estoy solita.",1,0,-1,8,"",4,7,"ia",50,0,-1,0,456,456,"5636","",0,"","","",2,0,0,[],""],["rm_t3-n5637",1,"En la torre más alta\nQue tiene el moro\nEstá mi amante preso;\nPor éso lloro.\nY yo le digo:\n-Rompe tú las cadenas;\nVénte conmigo.",1,0,-1,8,"",4,7,"io",106,0,-1,0,456,456,"5637","",0,"","","",3,0,0,[],""],["rm_t3-n5638",1,"¡Mal haya quien puso piedras\nEn la cárse de Jerés;\nQue tengo mi amante preso\nY no lo puedo ir á ber!",1,0,-1,8,"",0,4,"e",-1,0,-1,0,456,456,"5638","",0,"","","",1,0,0,[],""],["rm_t3-n5639",1,"Subí á la sala der Crimen\nA pedir tu libertá;\nLos señores de l' Audensia\nNo me la quisieron dá.",1,0,-1,8,"",0,4,"a",9,0,-1,0,456,456,"5639","",0,"","","",4,0,0,[],""],["rm_t3-n5640",1,"Muchas penas me han dicho\nQue estás pasando;\nSentimiento te tengo,\nPorque te amo.\nSi no te amara,\nNo sintiera las penas\nQue tú pasaras.",1,0,-1,8,"",4,7,"aa",-1,0,-1,0,457,457,"5640","",0,"","","",1,0,0,[],""],["rm_t3-n5641",1,"¡Bien sabe Dios, compañera,\nLa lástima que te tengo!\nComo sé lo que es querer,\nSé lo que estás padeciendo.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,457,457,"5641","",0,"","","",1,0,0,[],""],["rm_t3-n5642",1,"Ar pié d' una crus me hinqué\nA pedirle á Dios por tí,\nY fueron tantas mis penas,\nQue ar pié de la crus caí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,457,457,"5642","",0,"","","",1,0,0,[],""],["rm_t3-n5643",1,"Toíto er mundo traigo andao,\nBuscando tu bienestá,\nY á una puerta no m' arrimo\nQue no esté clabeteá.",1,0,-1,8,"",0,4,"a",9,0,-1,0,457,457,"5643","",0,"","","",1,0,0,[],""],["rm_t3-n5645",1,"Las estrellitas del cielo\nSe visten de colorado,\nY yo me visto de negro,\nPorque mi amante es soldado.",1,0,-1,8,"",0,4,"ao",14,0,-1,0,457,457,"5645","",0,"lafuente_madrid","","",25,0,0,[],""],["rm_t3-n5647",1,"Al otro lado del Ebro\nTiran fuertes cañonazos;\nArtillero de mi vida,\n¡Si te habrán hecho pedazos!",1,0,-1,8,"",0,4,"ao",132,0,-1,0,458,458,"5647","",0,"","","",3,0,0,[],""],["rm_t3-n5648",1,"Más quisiera verte, niña,\nEmbarcadita en el Ebro,\nQue nó verte en la ventana\nCon ese pañuelo negro.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,458,458,"5648","",0,"","","",6,0,0,[],""],["rm_t3-n5649",1,"Dime por quién tienes luto,\nPara echarlo yo tambien;\nPorque tú triste y yo alegre,\nÉso no parece bien.",1,0,-1,8,"",0,4,"e",242,0,-1,0,458,458,"5649","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5650",1,"¡Mal haya la ropa negra\nY el sastre que la cortó:\nQue está mi niña de luto,\nSin haberme muerto yo!",1,0,-1,8,"",0,4,"o",2,0,-1,0,458,458,"5650","",0,"palau_cantares","","",5,0,0,[],""],["rm_t3-n5652",1,"Quítate ese lutito,\nQue me da pena;\nGuárdalo para el dia\nQue yo me muera.\nQue me da dolor;\nGuárdalo para el dia\nQue me muera yo.",1,0,-1,8,"",4,7,"o",-1,0,-1,0,458,458,"5652","",0,"","","",1,0,0,[],""],["rm_t3-n5653",1,"Cada vez que paso y miro\nLa puerta del hospital,\nLe digo á mi cuerpecito:\n—Aquí vendrás á parar.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,459,459,"5653","",0,"lafuente_madrid, palau_cantares","","",24,0,0,[],""],["rm_t3-n5654",1,"Cada vez que paso y miro\nLa puerta del camposanto,\nLe digo á mi cuerpecito:\n-Aquí tendrás tu descanso.",1,0,-1,8,"",0,4,"ao",-1,0,-1,0,459,459,"5654","",0,"","","",24,0,0,[],""],["rm_t3-n5655",1,"En er sementerio entré;\nLe dije ar sepurturero\nSi hay un sitio señalao\nPâ los que mueren queriendo.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,459,459,"5655","",0,"","","",4,0,0,[],""],["rm_t3-n5661",1,"¿Para qué vas y vienes,\nDoctor confuso,\nSi el mal que á mí me aqueja\nNo sale al pulso?",1,0,-1,8,"",6,4,"uo",-1,0,-1,0,460,460,"5661","",0,"palau_cantares, fernan_caballero","","",6,0,0,[],""],["rm_t3-n5662",1,"Me han dicho que estás mala;\nDios te dé salú;\nYo no puedo ir á berte:\n¡Bien lo sabes tú!",1,0,-1,8,"",0,4,"u",73,0,-1,0,460,460,"5662","",0,"","","",4,0,0,[],""],["rm_t3-n5663",1,"Me han dicho que estás malita\nY que te sangran mañana;\nA tí te sangran del pié\nY á mí me sangran del alma.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,460,460,"5663","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",6,0,0,[],""],["rm_t3-n5664",1,"¿Quién ha sido el cirujano\nQue te ha mandado sangrar?\nSiendo tú un ángel humano,\n¿Qué sangre tienes de dar?",1,0,-1,8,"",1,4,"a",21,0,-1,0,460,460,"5664","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5665",1,"M' han dicho qu' estás malita\nY á Dios le pío yorando\nQue me quite la salú\nY á tí te la baya dando.",1,0,-1,8,"",0,4,"ao",33,0,-1,0,460,460,"5665","",0,"","","",2,0,0,[],""],["rm_t3-n5666",1,"De los güesos de mi cuerpo\nTengo d' haser una crus\nY m' he d' enclabar en eya,\nPâ que Dios te dé salú.",1,0,-1,8,"",0,4,"u",-1,0,-1,0,460,460,"5666","",0,"","","",2,0,0,[],""],["rm_t3-n5667",1,"Un hábito de sayal\nY un cordon de seda azul\nMe tengo de echar al cuello,\nComo Dios te dé salú.",1,0,-1,8,"",0,4,"u",-1,0,-1,0,460,461,"5667","",0,"","","",1,0,0,[],""],["rm_t3-n5668",1,"Sé que has estado mala\nDe gran cuidado;\nPero á verte no he ido,\nPor no aumentarlo.\nQue el mal que tienes\nNi tú ni yo ignoramos\nDe qué procede.",1,0,-1,8,"",4,7,"ee",-1,0,-1,0,461,461,"5668","",0,"","","",1,0,0,[],""],["rm_t3-n5670",1,"Cuando tú estabas malito,\nYo me eché sobre tu cama\nY á mi corason de ducas\nSe le cayeron las alas.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,461,461,"5670","",0,"","","",2,0,0,[],""],["rm_t3-n5671",1,"Cuando tú estabas malito\nSobre tu cama m' echaba;\nCon lágrimas e mis ojos\nTu carita la regaba.",1,0,-1,8,"",0,4,"aa",28,0,-1,0,461,461,"5671","",0,"","","",2,0,0,[],""],["rm_t3-n5672",1,"A mi pobre corazon\nTengo de ponerle un velo,\nPara que no sepa nádie\nDe la enfermedad que muero.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,461,461,"5672","",0,"","","",1,0,0,[],""],["rm_t3-n5673",1,"Aquer que tenga alegría\nQue no s' arrime á mi bera;\nQue yo estoy costituía\nA que me trague la tierra.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,461,461,"5673","",0,"","","",1,0,0,[],""],["rm_t3-n5674",1,"Nádie se arrime á mi cama,\nQue estoy ético de pena;\nY al que muere de este mal\nHasta la ropa le queman.",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,461,462,"5674","",0,"","","",1,0,0,[],""],["rm_t3-n5675",1,"S' acabaron mis purmones;\nNo los pueo reponé;\nEstoy ética y me muero\nPor causa de tu queré.",1,0,-1,8,"",0,4,"e",77,0,-1,0,462,462,"5675","",0,"","","",1,0,0,[],""],["rm_t3-n5677",1,"Cuando yo me muera\nTendrás que yorá\nMunchas gotiyas, - gotiyas e sangre\nPor la Cariá.",1,0,-1,8,"",3,4,"a",9,0,-1,0,462,462,"5677","",0,"","","",3,0,0,[],""],["rm_t3-n5678",1,"Enmedio de mis fatigas,\nEl morirme estoy sintiendo,\nPor no dejar en el mundo\nPersona que estoy queriendo.",1,0,-1,8,"",0,4,"eo",52,0,-1,0,462,462,"5678","",0,"","","",3,0,0,[],""],["rm_t3-n5679",1,"Para todos sale el sol;\nPara mí, salga ó no salga;\nMañana me muero yo;\nPara mí el mundo se acaba.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,462,462,"5679","",0,"","","",1,0,0,[],""],["rm_t3-n5680",1,"Señó serujano,\n'Sengáñem' usté\nSi mis chorreles se quean sin bata,\nSin bato tamié.",1,0,-1,8,"",3,4,"e",77,0,-1,0,462,462,"5680","",0,"","","",1,0,0,[],""],["rm_t3-n5681",1,"'L hospitar me boy;\nPor Dios, compañera,\nQue no t' apartes - e la bera mia\nJasta que yo muera.",1,0,-1,8,"",3,4,"ea",44,0,-1,0,462,463,"5681","",0,"","","",1,0,0,[],""],["rm_t3-n5682",1,"Si acasito muero,\nMira que t' encargo\nQue con las trensas - e tu pelo negro\nMe ates las manos.",1,0,-1,8,"",3,4,"ao",-1,0,-1,0,463,463,"5682","",0,"","","",2,0,0,[],""],["rm_t3-n5683",1,"Si acasito muero,\nMira que t' encargo\nEr que te pongas - un lutito negro,\nSiquiera po' un año.",1,0,-1,8,"",3,4,"ao",-1,0,-1,0,463,463,"5683","",0,"","","",2,0,0,[],""],["rm_t3-n5685",1,"Si bendes la ropa\nPâ pagá mi entierro,\nMia que no bendas - esa chaquetita\nD' aramales negros.",1,0,-1,8,"",3,4,"eo",-1,0,-1,0,463,463,"5685","",0,"","","",1,0,0,[],""],["rm_t3-n5686",1,"Si entras en er sementerio,\nPon un pié en mi losa y dí:\n-Aquí yase una flamenca\nQue pasó ducas por mí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,463,463,"5686","",0,"","","",1,0,0,[],""],["rm_t3-n5688",1,"Al pié de la sepultura\nTe tengo de ir á rezar;\nSi es mentira lo que digo,\nQue muera del mismo mal.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,463,463,"5688","",0,"","","",5,0,0,[],""],["rm_t3-n5689",1,"El corazon de mi amante\nLo van á sacramentar,\nY el mio se está muriendo\nDe la misma enfermedad.",1,0,-1,8,"",0,4,"a",-1,0,-1,0,464,464,"5689","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5690",1,"Dicen que estoy muy malito\nY que me voy á morir;\n¡Los que se mueren no sufren\nLo que yo sufro por tí!",1,0,-1,8,"",0,4,"i",-1,0,-1,0,464,464,"5690","",0,"","","",1,0,0,[],""],["rm_t3-n5692",1,"Gitana, si oyes doblar,\nNo preguntes quién ha muerto;\nQue ha sío mi corason,\nDe peniya y sentimiento.",1,0,-1,8,"",0,4,"eo",-1,0,-1,0,464,464,"5692","",0,"","","",3,0,0,[],""],["rm_t3-n5693",1,"Si pasares por la iglesia,\nDile ar sacristan que doble\nY ponga cortinas negras,\nPorque ya murió aquel hombre.",1,0,-1,8,"",0,4,"oe",-1,0,-1,0,464,464,"5693","",0,"","","",2,0,0,[],""],["rm_t3-n5694",1,"Cuando vayas á la iglesia,\nDí que doblen las campanas;\nQue ya se murió aquel hombre\nQue tanto tormento daba.",1,0,-1,8,"",0,4,"aa",-1,0,-1,0,464,464,"5694","",0,"","","",2,0,0,[],""],["rm_t3-n5695",1,"Dile al sacristan que doble\nY ponga negras cortinas;\nQue ya se murió aquel hombre\nQue rondaba tus esquinas.",1,0,-1,8,"",0,4,"ia",243,0,-1,0,464,464,"5695","",0,"","","",3,0,0,[],""],["rm_t3-n5696",1,"Ar yegá 'r Santolio\nLos ojos abrió;\nDe las duquitas - qu' ar probe le dieron,\nMás' pronto meró.",1,0,-1,8,"",3,4,"o",2,0,-1,0,465,465,"5696","",0,"","","",1,0,0,[],""],["rm_t3-n5699",1,"Ya bienen los frailes,\nY a bienen los curas;\nBan á yebarse - ' la mia compañera\nA la seportura.",1,0,-1,8,"",3,4,"ua",-1,0,-1,0,465,465,"5699","",0,"","","",1,0,0,[],""],["rm_t3-n5700",1,"Faitigas me dieron,\nGanas e yorá,\nCuando yo bie - qu' á mi compañera\nLa iban á enterrá.",1,0,-1,8,"",3,4,"a",9,0,-1,0,465,465,"5700","",0,"","","",2,0,0,[],""],["rm_t3-n5701",1,"En er carro delos muertos\nHa pasado por aquí;\nLlebaba una mano fuera:\nPor éso la conosí.",1,0,-1,8,"",0,4,"i",23,0,-1,0,465,465,"5701","",0,"","","",1,0,0,[],""],["rm_t3-n5702",1,"'N er carro e los muertos\nPasó por aquí;\nComo yebaba - tapâ la carita,\nNo la conosí.",1,0,-1,8,"",3,4,"i",23,0,-1,0,465,465,"5702","",0,"","","",1,0,0,[],""],["rm_t3-n5703",1,"Como no la ví difunta,\nMentira me parecia,\nY en la iglesia daba voces,\nY nádie me respondia.",1,0,-1,8,"",0,4,"ia",0,0,-1,0,466,466,"5703","",0,"","","",1,0,0,[],""],["rm_t3-n5705",1,"Ya se murió mi marío;\nYa se murió mi consuelo;\nYa no tengo quien me diga:\n«Ojiyos e tersiopelo.»",1,0,-1,8,"",0,4,"eo",10,0,-1,0,466,466,"5705","",0,"","","",1,0,0,[],""],["rm_t3-n5707",1,"M' acuesto toítos los lúnes,\nM' alebanto tôs los martes,\nY me boy ar simenterio,\nA recorré funerales. (?)",1,0,-1,8,"",0,4,"ae",-1,0,-1,0,466,466,"5707","",0,"","","",1,0,0,[],""],["rm_t3-n5708",1,"Se lo peí yorando\nAr seporturero,\nQue me dijera - la seporturita\nOnde la metieron.",1,0,-1,8,"",3,4,"eo",-1,0,-1,0,466,466,"5708","",0,"","","",2,0,0,[],""],["rm_t3-n5709",1,"Seporturerito,\nLe dije yorando,\nQue m' enseñara - la seporturita\nOnde la enterraron.",1,0,-1,8,"",3,4,"ao",-1,0,-1,0,466,466,"5709","",0,"","","",1,0,0,[],""],["rm_t3-n5710",1,"Toíto er simenterio\nLo traigo ya andao;\nLa seportura - ' mi compañerita\nYo no l' h' 'ncontrao.",1,0,-1,8,"",3,4,"ao",98,0,-1,0,466,467,"5710","",0,"","","",1,0,0,[],""],["rm_t3-n5711",1,"¡Ay, pobresita de mí,\nQue no tengo quien me quiera,\nPorque el que á mí me queria\nSe lo ha tragado la tierra!",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,467,467,"5711","",0,"","","",2,0,0,[],""],["rm_t3-n5712",1,"De llorar me quedé ciego\nCuando supe que era muerta;\n¿Para qué quiero los ojos,\nSi no he de volver á verla?",1,0,-1,8,"",0,4,"ea",-1,0,-1,0,467,467,"5712","",0,"","","",3,0,0,[],""],["rm_t3-n5713",1,"Yo no sé por qué cosiya\nLa muerte se la yebó.\n¡Y yo, con tanta peniya...!\n¡De mí no s' acuerda Dios!",1,0,-1,8,"",0,4,"o",-1,0,-1,0,467,467,"5713","",0,"","","",1,0,0,[],""],["rm_t3-n5714",1,"A nádie l' he dicho yo\nQu' he d' orbidar tu querer,\nPorque si me dan duquiyas,\nNo sé si te buscaré.",1,0,-1,9,"",0,4,"e",-1,0,-1,0,498,498,"5714","",0,"","","",1,0,0,[],""],["rm_t3-n5715",1,"Después de haberte olvidado,\nPasé por tu puerta y dije:\n-Aquí vive una serrana\nQue en algun tiempo yo quise.",1,0,-1,9,"",0,4,"ie",-1,0,-1,0,498,498,"5715","",0,"","","",1,0,0,[],""],["rm_t3-n5719",1,"Yo enterré mi amor un dia,\nCreyendo que estaba muerto,\nY de sus secas raíces\nOtras plantas florecieron.",1,0,-1,9,"",0,4,"eo",-1,0,-1,0,499,499,"5719","",0,"","","",1,0,0,[],""],["rm_t3-n5720",1,"Si mi corazon pudiera\nHablar con tu corazon,\nEn breve rato le diera\nDe todo satisfaccion.",1,0,-1,9,"",1,4,"ao",31,0,-1,0,499,499,"5720","",0,"","","",4,0,0,[],""],["rm_t3-n5721",1,"Dije que no te queria,\nY otra vez vuelvo á buscarte,\nCon el corazon partido,\nLlorando gotas de sangre.",1,0,-1,9,"",0,4,"ae",-1,0,-1,0,499,499,"5721","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5722",1,"Apesar del mundo todo,\nHe de pasar por aquí,\nY darle agua á mi caballo,\nY buscar lo que perdí.",1,0,-1,9,"",0,4,"i",23,0,-1,0,499,499,"5722","",0,"","","",1,0,0,[],""],["rm_t3-n5723",1,"Por entre espinas y abrojos\nDescarso m' atrebo á entrá,\nPor quitarte los enojos,\nY borber á tu amistá\n[Clabeyina de mis ojos].",1,0,-1,9,"",7,5,"oo",99,0,-1,0,499,499,"5723","",0,"","","",2,0,0,[],""],["rm_t3-n5724",1,"Cada vez que yo en tí pienso\nRenace mi muerto amor;\nPorque donde fuego hubo\nSiempre ceniza quedó.",1,0,-1,9,"",0,4,"o",-1,0,-1,0,499,499,"5724","",0,"","","",1,0,0,[],""],["rm_t3-n5725",1,"El carbon que ha sido ascua,\nAl ver la lumbre se enciende;\nSiempre me ha gustado á mí\nPlaticar con quien me entiende.",1,0,-1,9,"",0,4,"ee",233,0,-1,0,499,499,"5725","",0,"","","",1,0,0,[],""],["rm_t3-n5726",1,"Cuando intenté el olvidarte\nSe me previno la muerte;\nComo la vida es amable,\nVolví de nuevo á quererte.",1,0,-1,9,"",0,4,"ee",134,0,-1,0,500,500,"5726","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5728",1,"A tus piés estoy postrado;\nMira que tu amante he sido;\nDame la carta de pago,\nQue yo te daré el recibo.",1,0,-1,9,"",0,4,"io",-1,0,-1,0,501,501,"5728","",0,"","","",1,0,0,[],""],["rm_t3-n5729",1,"Desde que me olvidaste,\nYo no me quise,\nPor no querer yo cosa\nQue aborreciste.\nVuelve á quererme,\nY verás como dejo\nDe aborrecerme.",1,0,-1,9,"",4,7,"ee",245,0,-1,0,501,501,"5729","",0,"","","",1,0,0,[],""],["rm_t3-n5730",1,"Permita Dios de los sielos\nQue te buerbas ' acordá\nDe la que te quiere tanto\nComo los peses ar má.",1,0,-1,9,"",0,4,"a",9,0,-1,0,501,501,"5730","",0,"","","",2,0,0,[],""],["rm_t3-n5731",1,"Si te ves aborrecida\nDel galan que te adoraba,\nVuelve, vuelve á mi querer,\nOveja descarriada.",1,0,-1,9,"",0,4,"aa",-1,0,-1,0,501,501,"5731","",0,"","","",2,0,0,[],""],["rm_t3-n5734",1,"Por querer á un serafin,\nOlvidé un hermoso cielo;\nDos glorias no puede haber;\nVolvamos á lo primero.",1,0,-1,9,"",0,4,"eo",-1,0,-1,0,502,502,"5734","",0,"","","",3,0,0,[],""],["rm_t3-n5735",1,"Así como el muchacho,\nQue cuando salta,\nCuanto más se retira\nMejor avanza,\nDel mismo modo,\nSi me retiro, vuelvo\nMás animoso.",1,0,-1,9,"",4,7,"oo",-1,0,-1,0,502,502,"5735","",0,"palau_cantares","","",2,0,0,[],""],["rm_t3-n5736",1,"Piedra fuí, perdí mi centro\nY me tiraron al mar;\nMas con la fuerza del tiempo,\nMi centro volví á buscar.",1,0,-1,9,"",0,4,"a",21,0,-1,0,502,502,"5736","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5737",1,"No serás tú el primer hombre\nNi yo la primer mujer\nQue se quieran y se olviden\nY se vuelvan á querer.",1,0,-1,9,"",0,4,"e",20,0,-1,0,502,502,"5737","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5738",1,"Si me quisieras de nuevo,\nNo me habias de conocer;\nTengo ya distinto genio\nY otro modo de querer.",1,0,-1,9,"",0,4,"e",20,0,-1,0,502,502,"5738","",0,"","","",2,0,0,[],""],["rm_t3-n5739",1,"Si de árboles vedados\nCogiste fruta,\nDate un golpe en el pecho;\nDí: «Por mi culpa.»\nQue los pecados\nCon arrepentimiento\nSon perdonados.",1,0,-1,9,"",4,7,"ao",18,0,-1,0,503,503,"5739","",0,"","","",1,0,0,[],""],["rm_t3-n5740",1,"De la flor de la canela\nPoco fruto sacaremos; (?)\nS' acaben nuestros enojos;\nDe nuebo nos hablaremos.",1,0,-1,9,"",0,4,"eo",127,0,-1,0,503,503,"5740","",0,"","","",1,0,0,[],""],["rm_t3-n5742",1,"¡Qué amariyita qu' estás\nY qué yenita d' ojeras!\nYo te borberé á queré,\nQue no quiero que te mueras.",1,0,-1,9,"",0,4,"ea",103,0,-1,0,503,503,"5742","",0,"","","",1,0,0,[],""],["rm_t3-n5743",1,"Se acabaron las prisiones\nQue tanto me molestaban;\nSe unieron los corazones,\nComo antiguamente estaban.",1,0,-1,9,"",1,4,"aa",39,0,-1,0,503,503,"5743","",0,"","","",1,0,0,[],""],["rm_t3-n5744",1,"Por tí y por mí lo dijeron\nQu' ar cabo e los años mir\nBan otra bes las agüitas\nPor donde solian dir.",1,0,-1,9,"",0,4,"i",157,0,-1,0,503,503,"5744","",0,"","","",2,0,0,[],""],["rm_t3-n5745",1,"San Antonio bendito,\nTres cosas pido:\nSalvacion y dinero\nY un buen marido.",1,0,-1,10,"",6,4,"io",101,0,-1,0,508,508,"5745","",0,"","","",4,0,0,[],""],["rm_t3-n5746",1,"En llegándome el pelo\nA la cintura\nPuede decir mi madre\nQue no soy suya.\nMe va llegando,\nY mi madre sin hija\nSe va quedando.",1,0,-1,10,"",4,7,"ao",33,0,-1,0,508,508,"5746","",0,"","","",1,0,0,[],""],["rm_t3-n5748",1,"Todo el mundo se casa;\nYo no me caso:\n¿No hay quien me parta el alma.\nDe un ladrillazo?",1,0,-1,10,"",6,4,"ao",43,0,-1,0,508,509,"5748","",0,"","","",1,0,0,[],""],["rm_t3-n5749",1,"Câ bes que jago la cama\nMardigo la suerte mía;\n¡Ay, cama! ¿pâ qué tejago,\nSi no tengo compañía?",1,0,-1,10,"",0,4,"ia",0,0,-1,0,509,509,"5749","",0,"","","",1,0,0,[],""],["rm_t3-n5750",1,"Como tortoliya triste\nToa mi bía he de pasá;\n¡Siempre sola! ¡Siempre sola...!\n¡Bárgame la Soleá!",1,0,-1,10,"",0,4,"a",9,0,-1,0,509,509,"5750","",0,"","","",1,0,0,[],""],["rm_t3-n5751",1,"¡Ay, pobresita de mí,\nQue no tengo quien me quiera!\nPor éso me boy quedando\nComo er paná de la sera.",1,0,-1,10,"",0,4,"ea",44,0,-1,0,509,509,"5751","",0,"","","",2,0,0,[],""],["rm_t3-n5752",1,"Entré en la iglesia moza,\nSali casada;\nNo hay quien desate el nudo\nDe esta lazada.\nNudo tan fuerte,\nQue nádie lo desata\nSino la muerte.",1,0,-1,10,"",4,7,"ee",134,0,-1,0,509,509,"5752","",0,"","","",2,0,0,[],""],["rm_t3-n5753",1,"Estando en la mar pescando,\nMetí la mano y saqué\nUna niña e quinse años,\nY con eya me casé.",1,0,-1,10,"",0,4,"e",77,0,-1,0,509,509,"5753","",0,"","","",1,0,0,[],""],["rm_t3-n5754",1,"Tengo oro, tengo plata,\nTengo un barquito en el mar;\nTengo la mujer bonita;\n¿Qué más puedo desear?",1,0,-1,10,"",0,4,"a",21,0,-1,0,509,509,"5754","",0,"","","",3,0,0,[],""],["rm_t3-n5756",1,"Anoche á las doce y media,\nCuando el sereno pasó,\nEstaba yo dormidita\nEn los brazos de mi amor.",1,0,-1,10,"",0,4,"o",-1,0,-1,0,510,510,"5756","",0,"","","",1,0,0,[],""],["rm_t3-n5757",1,"Si el casarse fuera un dia,\nUna semaniya ó dos....\nPero por toda la bida,\nEso no lo paso yo.",1,0,-1,10,"",0,4,"o",-1,0,-1,0,510,510,"5757","",0,"","","",3,0,0,[],""],["rm_t3-n5758",1,"Yo me casé por un año,\nPor saber la vida que era;\nEl año se va acabando;\nMás quisiera estar soltera.",1,0,-1,10,"",0,4,"ea",44,0,-1,0,510,510,"5758","",0,"","","",1,0,0,[],""],["rm_t3-n5759",1,"Cásate, niña, á gusto,\nY á nádie temas;\nYo me casé á disgusto\nY paso penas.",1,0,-1,10,"",6,4,"ea",-1,0,-1,0,510,510,"5759","",0,"","","",1,0,0,[],""],["rm_t3-n5760",1,"Mi marido es un celoso\nY á puros celos me mata:\nCelos si me voy á misa;\nCelos si me quedo en casa.",1,0,-1,10,"",0,4,"aa",-1,0,-1,0,510,510,"5760","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t3-n5761",1,"El que se casa verás\nAl principio muy gustoso;\nVosotros no lo entendeis;\n¡Ay de mí, quién fuera mozo!",1,0,-1,10,"",0,4,"oo",156,0,-1,0,510,510,"5761","",0,"","","",1,0,0,[],""],["rm_t3-n5762",1,"Te casastes, te enterrastes;\n¿No te lo decia yo?\nEl que se casa se entierra,\nComo á mí me sucedió.",1,0,-1,10,"",0,4,"o",2,0,-1,0,511,511,"5762","",0,"","","",1,0,0,[],""],["rm_t3-n5763",1,"¿Cómo quieres que tenga\nGusto y contento,\nCasaíta d' un año,\nMi niño muerto?",1,0,-1,10,"",6,4,"eo",-1,0,-1,0,511,511,"5763","",0,"","","",14,0,0,[],""],["rm_t4-n5764",2,"Una niña á su madre\nLe preguntaba:\n—¿Qué es esto que entre gentes\nAmor se llama?—\nY ella le dice:\n—Dios te guarde, hija mia,\nQue te lo explique.",2,0,-1,11,"",4,7,"ie",-1,0,-1,0,11,11,"5764","",0,"","","",1,0,0,[],""],["rm_t4-n5765",2,"El amor es una cosa\n¡Dios nos libre y Dios nos guarde!\nQue hace perder los sentidos\nAl que los tiene cabales.",2,0,-1,11,"",0,4,"ae",-1,0,-1,0,11,11,"5765","",0,"lafuente_madrid, palau_cantares","","",5,0,0,[],""],["rm_t4-n5766",2,"Dicen que hay una cosa\nQue amor se llama,\nQue si se entra en el pecho,\nPica y abrasa.\n¡Jesús, qué miedo\nAl amor le he cobrado\nSin conocerlo!",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,11,11,"5766","",0,"","","",1,0,0,[],""],["rm_t4-n5767",2,"Al amor lo pintan niño,\nCon los ojitos vendados;\nPor éso viven á oscuras\nTodos los enamorados.",2,0,-1,11,"",0,4,"ao",18,0,-1,0,12,12,"5767","",0,"","","",4,0,0,[],""],["rm_t4-n5768",2,"Es el amor un niño\nQue, cuando nace,\nCon poquito que coma\nSe satisface.\nPero en creciendo,\nCuanto más le van dando,\nMás va queriendo.",2,0,-1,11,"",4,7,"eo",52,0,-1,0,12,12,"5768","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5769",2,"El amor es un bichito\nQue por los ojos se mete,\nY en llegando al corazón\nDa fatiguillas de muerte.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,12,12,"5769","",0,"lafuente_madrid, palau_cantares","","",10,0,0,[],""],["rm_t4-n5770",2,"Es el amor un bicho\nQue cuando pica,\nNo se encuentra remedio\nNi en la botica.",2,0,-1,11,"",6,4,"ia",174,0,-1,0,12,12,"5770","",0,"","","",2,0,0,[],""],["rm_t4-n5772",2,"Es de amor la polilla\nMuy semejante,\nPues sólo se alimenta\nDe lo que nace.\nPorque royendo\nEstá siempre la causa\nQue fué su engendro.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,12,13,"5772","",0,"","","",1,0,0,[],""],["rm_t4-n5773",2,"Es el amor gusano\nQue el alma anima,\nEl corazon engendra\nY el pecho abriga.\nY el que le tiene\nSuele vivir muriendo\nDe lo que quiere.",2,0,-1,11,"",4,7,"ee",-1,0,-1,0,13,13,"5773","",0,"preciso_coleccion","","",2,0,0,[],""],["rm_t4-n5774",2,"Es el amor araña\nQue, cuando nace,\nCon su mismo veneno\nSe satisface.\nCuyo alimento\nNo es mucho que nos haga\nVivir muriendo.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,13,13,"5774","",0,"","","",1,0,0,[],""],["rm_t4-n5775",2,"Es amor una araña\nQue con cautela\nEn un rincon del alma\nForma su tela,\nCon tal sigilo,\nQue ningun sabio pudo\nCortar el hilo.",2,0,-1,11,"",4,7,"io",247,0,-1,0,13,13,"5775","",0,"palau_cantares, frenk_t2","","",3,0,0,[],""],["rm_t4-n5776",2,"Es el amor pescado,\nY en su comida\nEncuentran los amantes\nMuchas espinas.\nPero las pasan,\nPor los dulces bocados\nQue á veces hallan.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,13,13,"5776","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5778",2,"Es amor una senda\nTan sin camino,\nQue el que va más derecho\nVa más perdido.",2,0,-1,11,"",6,4,"io",-1,0,-1,0,14,14,"5778","",0,"carrizo_salta, palau_cantares","","",3,0,0,[],""],["rm_t4-n5779",2,"Es el amor un prado\nTan divertido,\nQue el que no lo pasea\nSe halla aburrido.\nPorque este prado\nDivierte corazones\nAtribulados.",2,0,-1,11,"",4,7,"ao",-1,0,-1,0,14,14,"5779","",0,"","","",1,0,0,[],""],["rm_t4-n5780",2,"El amor y los campos\nSon casi iguales;\nQue los dos se marchitan\nCon sequedades.\nPero en lloviendo.\nEl amor y los campos\nVan floreciendo.",2,0,-1,11,"",4,7,"eo",52,0,-1,0,14,14,"5780","",0,"","","",2,0,0,[],""],["rm_t4-n5781",2,"El amor es un fuego\nCuya materia\nCuanto más se consume,\nMás se fomenta.",2,0,-1,11,"",6,4,"ea",-1,0,-1,0,14,14,"5781","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n5782",2,"Es el amor un fuego\nQue alumbra el alma,\nCuando en dos corazones\nPrenden sus llamas.\nY es negro humo,\nCuando tan sólo siente\nLa pena uno.",2,0,-1,11,"",4,7,"uo",-1,0,-1,0,15,15,"5782","",0,"","","",3,0,0,[],""],["rm_t4-n5783",2,"Es amor una llama\nQue no la entiendo,\nPues sin salir el humo\nSe ve el incendio.",2,0,-1,11,"",6,4,"eo",-1,0,-1,0,15,15,"5783","",0,"","","",1,0,0,[],""],["rm_t4-n5784",2,"Amor es como el agua,\nSegun se toma:\nQue á muchos los refresca\nY á otros sofoca.\nBebed con tiento,\nQue hay mil enfermedades\nPor el exceso.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,15,15,"5784","",0,"","","",2,0,0,[],""],["rm_t4-n5785",2,"Es el amor un dulce\nQue no empalaga;\nPero en aborreciendo,\nMás que retama.\nY aunque parece\nQue no empalaga nunca,\nSon las más veces.",2,0,-1,11,"",4,7,"ee",-1,0,-1,0,15,15,"5785","",0,"","","",1,0,0,[],""],["rm_t4-n5786",2,"El bocado del amor\nEs más dulce que la miel;\nPero en ciertas ocasiones\nAmarga más que la hiel.",2,0,-1,11,"",0,4,"e",32,0,-1,0,15,15,"5786","",0,"","","",2,0,0,[],""],["rm_t4-n5787",2,"Es el amor un libro\nQue al primer folio\nTodos son sobresaltos,\nSustos y asombros.\nPero en llegando\nA las hojas de enmedio,\nYa no hay cuidado.",2,0,-1,11,"",4,7,"ao",-1,0,-1,0,16,16,"5787","",0,"","","",1,0,0,[],""],["rm_t4-n5788",2,"Es amor una rueda\nQue nunca pára;\nA unos los sube mucho\nY á otros los baja.\nTengan cuidado,\nPorque tiene esta rueda\nMuchos rodando.",2,0,-1,11,"",4,7,"ao",-1,0,-1,0,16,16,"5788","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5789",2,"Es el amor, señores,\nComo el cigarro:\nNádie lo deja y todos\nQuieren dejarlo.\nY el que lo deja\nEs para volver luégo\nCon mayor fuerza.",2,0,-1,11,"",4,7,"ea",-1,0,-1,0,16,16,"5789","",0,"palau_cantares","","",4,0,0,[],""],["rm_t4-n5790",2,"El amor es un juego\nDe treinta y una,\nSegun los plantos que hacen\nMuchos y muchas.\nY si hay mal juego,\nTan sólo barajando\nSe pasa el tiempo.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,16,16,"5790","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5792",2,"Amores son monedas\nImaginarias,\nQue aunque no las ve nadie,\nTodos las pasan.\nDe tal manera,\nQue el comercio se hace\nCon ofrecerlas.",2,0,-1,11,"",4,7,"ea",-1,0,-1,0,17,17,"5792","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5793",2,"Es amor un comercio\nDe tantas quiebras,\nQue en él aquel que gana\nPerdido queda.\nY al fin y al cabo,\nSi hay alguna ganancia,\nLa lleva el diablo.",2,0,-1,11,"",4,7,"ao",-1,0,-1,0,17,17,"5793","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5794",2,"Aunque amor es oficio,\nNo tiene exámen;\nPorque viejos y niños,\nTodos lo saben.\nY en sus talleres\nLas mejores lecciones\nDan las mujeres.",2,0,-1,11,"",4,7,"ee",55,0,-1,0,17,17,"5794","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5795",2,"Amor es un enredo,\nDicen los sabios;\nPero yo veo á muchos\nMuy enredados.\nDe lo que infiero\nQue son muy dulces lazos\nLos de ese enredo.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,17,18,"5795","",0,"","","",3,0,0,[],""],["rm_t4-n5796",2,"Es el amor comedia,\nSegun infiero;\nMás se quiere al segundo\nQue nó al primero.\nPorque reparo\nQue no hay buena comedia\nSi no hay ensayo.",2,0,-1,11,"",4,7,"ao",-1,0,-1,0,18,18,"5796","",0,"","","",1,0,0,[],""],["rm_t4-n5797",2,"Es amor un embuste\nTan bien dispuesto.\nQue le hacen las mujeres\nTener por cierto.\nY con engaños\nTienen á muchos hombres\nEmbolismados.",2,0,-1,11,"",4,7,"ao",-1,0,-1,0,18,18,"5797","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n5798",2,"Amor es como un pleito\nQue se defiende\nY con vista y revista\nSuele perderse.",2,0,-1,11,"",6,4,"ee",-1,0,-1,0,18,18,"5798","",0,"","","",1,0,0,[],""],["rm_t4-n5799",2,"El amor es un pleito;\nPero en su audiencia\nLas mujeres son parte\nY ellas sentencian.\nY aunque lo ganen,\nCondenados en costas\nLos hombres salen.",2,0,-1,11,"",4,7,"ae",-1,0,-1,0,18,18,"5799","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5800",2,"Que el amor es la vida\nDicen los sabios;\nY yo digo lo mismo,\nSólo al contrario.\nQue es de tal suerte,\nQue al que lo experimenta\nLe da la muerte.",2,0,-1,11,"",4,7,"ee",134,0,-1,0,19,19,"5800","",0,"","","",1,0,0,[],""],["rm_t4-n5801",2,"A la vida parece\nNuestro amor loco:\nMuchos años de afanes\nY al cabo, un soplo.\nSu fin funesto\nEs siempre el desengaño\nY el escarmiento.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,19,19,"5801","",0,"","","",1,0,0,[],""],["rm_t4-n5802",2,"Es amor una pena\nLlena de ardores,\nSi no encuentra en lo amado\nSatisfacciones.\nMas si las halla,\nCon los gustos que logra,\nLa pena pasa.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,19,19,"5802","",0,"","","",1,0,0,[],""],["rm_t4-n5803",2,"Es amor un deseo\nQue durar suele\nEl tiempo que se goza\nLo que se quiere.\nPero en logrando,\nLo que ántes agradaba\nVa fastidiando.",2,0,-1,11,"",4,7,"ao",33,0,-1,0,19,19,"5803","",0,"preciso_coleccion","","",2,0,0,[],""],["rm_t4-n5804",2,"Raro es aquel que en el mundo\nMal de amores no ha tenido;\nQue el amor es la epidemia\nMás grande que he conocido.",2,0,-1,11,"",0,4,"io",101,0,-1,0,19,20,"5804","",0,"","","",1,0,0,[],""],["rm_t4-n5805",2,"Los amores y la luna\nSon en todo semejantes:\nEntran en cuarto creciente;\nSalen en cuarto menguante.",2,0,-1,11,"",0,4,"ae",-1,0,-1,0,20,20,"5805","",0,"","","",1,0,0,[],""],["rm_t4-n5806",2,"El amor y la naranja\nSe parecen infinito\nEn que por dulces que sean,\nDe agrio tienen su poquito.",2,0,-1,11,"",0,4,"io",119,0,-1,0,20,20,"5806","",0,"rm_t2","","",3,0,0,[],""],["rm_t4-n5807",2,"Amores al principio\nSon muy ardientes;\nMas luégo, con el tiempo,\nToman su temple.\nSi así no fuera,\nCon amores tan vivos\nNádie viviera.",2,0,-1,11,"",4,7,"ea",44,0,-1,0,20,20,"5807","",0,"","","",2,0,0,[],""],["rm_t4-n5808",2,"De los delirios de amor\nNádie se debe fiar,\nPorque éstos se desvanecen\nComo la espuma en el mar.",2,0,-1,11,"",0,4,"a",21,0,-1,0,20,20,"5808","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t4-n5809",2,"Hay quereles de capricho,\nHay quereles de ilusiones,\nHay quereles que s' arquilan,\nComo las habitasiones.",2,0,-1,11,"",0,4,"oe",34,0,-1,0,20,20,"5809","",0,"","","",1,0,0,[],""],["rm_t4-n5810",2,"Una pena quita pena;\nUn dolor quita dolor;\nUn clavo saca otro clavo;\nPero amor no quita amor.",2,0,-1,11,"",0,4,"o",72,0,-1,0,20,21,"5810","",0,"palau_cantares, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["rm_t4-n5812",2,"El querer es mucho y nada,\nY lo digo de verdad:\nMucho, si se quiere bien;\nNada, si se quiere mal.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,21,21,"5812","",0,"","","",1,0,0,[],""],["rm_t4-n5813",2,"A la luna tiro perlas\nY al sol dorado corales;\nAl amor tirarle fuego;\nQue es causa de muchos males.",2,0,-1,11,"",0,4,"ae",26,0,-1,0,21,21,"5813","",0,"","","",2,0,0,[],""],["rm_t4-n5814",2,"Tan cabal como el reló\nNingun amor puede ser;\nEl reló tiene gobierno,\nLo que no tiene el querer.",2,0,-1,11,"",0,4,"e",20,0,-1,0,21,21,"5814","",0,"","","",1,0,0,[],""],["rm_t4-n5815",2,"Preguntó un novio á su novia\nQue en qué consiste el amor,\nY ella dijo que en tener\nUn alma para los dos.",2,0,-1,11,"",0,4,"o",-1,0,-1,0,21,21,"5815","",0,"","","",1,0,0,[],""],["rm_t4-n5818",2,"Entra el amor por los ojos,\nSe deposita en el pecho,\nLo alimentan los oidos\nY lo matan los desprecios.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,22,22,"5818","",0,"","","",4,0,0,[],""],["rm_t4-n5819",2,"Nace amor como una planta\nEn amante corazón;\nLo alimenta la esperanza;\nDespués lo seca el rigor.",2,0,-1,11,"",0,4,"o",-1,0,-1,0,22,22,"5819","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5820",2,"Nace amor como planta\nEn el corazon;\nEl cariño lo riega;\nLo seca el rigor.\nY si se arraiga,\nSe arranca al apartarlo\nTambien el alma.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,22,22,"5820","",0,"","","",4,0,0,[],""],["rm_t4-n5821",2,"Nace amor de la vista;\nCrece del trato;\nSe alimenta de celos;\nMuere de agravios.\nY en el entierro\nLo lleva á sepultarlo\nUn amor nuevo.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,22,22,"5821","",0,"","","",3,0,0,[],""],["rm_t4-n5822",2,"Amor con amor se paga,\nQue con otra cosa nó;\nLo que no tuviere cuenta,\nOlvidarlo es lo mejor.",2,0,-1,11,"",0,4,"o",-1,0,-1,0,23,23,"5822","",0,"","","",5,0,0,[],""],["rm_t4-n5823",2,"De cera son las puertas\nDe los amores;\nCuenta que á la salida\nYa son de bronce.\nY que á la entrada\nSuelen estar abiertas;\nDespués, cerradas.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,23,23,"5823","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5824",2,"Cupido anda por el monte,\nEn traje de cazador,\nDiciendo que muera, muera,\nEl que no entiende de amor.",2,0,-1,11,"",0,4,"o",72,0,-1,0,23,23,"5824","",0,"","","",1,0,0,[],""],["rm_t4-n5825",2,"—¿Te quieres poner conmigo?\n(Le dijo el tiempo al querer.)\nEsa soberbia que tienes\nYo te la castigaré.",2,0,-1,11,"",0,4,"e",-1,0,-1,0,23,23,"5825","",0,"fernan_caballero","","",4,0,0,[],""],["rm_t4-n5826",2,"El tiempo con el querer\nHicieron una contrata\nY lo que el querer dispone\nEl tiempo lo desbarata.",2,0,-1,11,"",0,4,"aa",74,0,-1,0,23,23,"5826","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n5827",2,"El querer y el no querer\nTuvieron una porfía\nY el querer, como es tan firme,\nAl no querer lo vencia.",2,0,-1,11,"",5,4,"ea",-1,0,-1,0,23,23,"5827","",0,"","","",1,0,0,[],""],["rm_t4-n5828",2,"Er pimiento ha de ser berde\nY er tomate, colorao;\nLa berengena, espinosa;\nY los amores cayaos.",2,0,-1,11,"",0,4,"ao",-1,0,-1,0,23,24,"5828","",0,"","","",1,0,0,[],""],["rm_t4-n5829",2,"Una pasion amante\nQue es cuerda y sabia\nCon todo se conforma;\nNada la agravia.\nQue amor perfecto\nEs solícito, sabio,\nSolo y secreto.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,24,24,"5829","",0,"preciso_coleccion","","",2,0,0,[],""],["rm_t4-n5830",2,"Cuatro SSSS componen\nAmor perfecto:\nSer solícito, sabio,\nSolo y secreto.\nQuien celos tiene,\nDe fiero, flaco y fácil\nTiene las FFF.",2,0,-1,11,"",4,7,"",-1,0,-1,0,24,24,"5830","",0,"","","",1,0,0,[],""],["rm_t4-n5832",2,"Yo he bisto raso yobé,\nY claro ponerse oscuro;\nYo he bisto acabá un queré\nCuando estaba más seguro.",2,0,-1,11,"",1,4,"uo",248,0,-1,0,24,24,"5832","",0,"","","",2,0,0,[],""],["rm_t4-n5833",2,"Es amor como el pleitista\nCuando dinero no tiene:\nNi el escribano le escucha,\nNi el abogado le atiende.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,24,24,"5833","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n5834",2,"El amor del hombre pobre\nEs como el del gallo enano,\nQue en querer y no alcanzar\nSe le pasa todo el año.",2,0,-1,11,"",0,4,"ao",-1,0,-1,0,25,25,"5834","",0,"","","",6,0,0,[],""],["rm_t4-n5835",2,"Es el amor del pobre\nSermon en Argel,\nQue nádie que lo oye\nHace caso de él.\nPor lo que vemos\nQue si un pobre enamora,\nSufre desprecios.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,25,25,"5835","",0,"","","",2,0,0,[],""],["rm_t4-n5836",2,"No enamore quien tenga\nPoco dinero,\nQue aunque sea buen mozo,\nQuedará feo.\nPues las mujeres\nHuyen como del diablo\nDe quien no tiene.",2,0,-1,11,"",4,7,"ee",-1,0,-1,0,25,25,"5836","",0,"","","",3,0,0,[],""],["rm_t4-n5837",2,"Antes Amor hería\nCon duras flechas;\nPero ya sólo hiere\nCon las pesetas.\nY no hay muralla\nEn que no se abra brecha\nCon tal metralla.",2,0,-1,11,"",4,7,"aa",249,0,-1,0,25,25,"5837","",0,"","","",1,0,0,[],""],["rm_t4-n5838",2,"A razones de plata\nRindense al punto\nDe las plazas más firmes\nLos fuertes muros.\nMucho persuaden,\nPorque más que de peso\nTienen de graves.",2,0,-1,11,"",4,7,"ae",-1,0,-1,0,25,26,"5838","",0,"","","",1,0,0,[],""],["rm_t4-n5839",2,"La mujer que del hombre\nRecibe alhaja\nIndica que con algo\nQuiere pagarla.\nQue en este tiempo\nNinguno da regalos\nSino al descuento.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,26,26,"5839","",0,"","","",1,0,0,[],""],["rm_t4-n5840",2,"No quiero que me dé nádie\nValía de un alfiler,\nPorque todo en este mundo\nSe da por el interés.",2,0,-1,11,"",0,4,"e",-1,0,-1,0,26,26,"5840","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n5841",2,"Reniego yo de aquel hombre\nQue se lleva del dinero\nY no se deja llevar\nDe unos grandes ojos negros.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,26,26,"5841","",0,"","","",1,0,0,[],""],["rm_t4-n5842",2,"Mar fin tenga la persona\nQue se yeba der dinero;\nSi se le istingue 'r linaje,\nRasa tiene de gayego.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,26,26,"5842","",0,"","","",1,0,0,[],""],["rm_t4-n5843",2,"Entre dos que bien se quieren\nNo hacen falta las palabras;\n¿Cómo quieres que la boca\nHable como las miradas?",2,0,-1,11,"",0,4,"aa",-1,0,-1,0,26,26,"5843","",0,"","","",3,0,0,[],""],["rm_t4-n5844",2,"Cuando dos se quieren bien\nY no se pueden hablar,\nLos ojos sirven de lengua,\nPara más disimular.",2,0,-1,11,"",0,4,"a",21,0,-1,0,26,27,"5844","",0,"","","",8,0,0,[],""],["rm_t4-n5845",2,"Cuando dos se quieren bien\nCon los ojos se saludan;\nQue tambien los ojos hablan\nCuando la lengua está muda.",2,0,-1,11,"",0,4,"ua",-1,0,-1,0,27,27,"5845","",0,"palau_cantares, lafuente_madrid","","",8,0,0,[],""],["rm_t4-n5846",2,"Si acaso saber quieres\nSi dos se aman,\nRepara si se miran\nMás que se hablan.",2,0,-1,11,"",6,4,"aa",-1,0,-1,0,27,27,"5846","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n5847",2,"Si los ojos callasen\nLo que los labios,\nAlgunos encubrieran\nMás sus cuidados.\nMas son ventanas\nLos ojos y por ellos\nSe asoma el alma.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,27,27,"5847","",0,"","","",1,0,0,[],""],["rm_t4-n5848",2,"Los afectos amantes\nDe un pecho firme\nHablan más cuando calla\nQue cuando dice.\nPorque los ojos\nInsinúan conceptos\nMás amorosos.",2,0,-1,11,"",4,7,"oo",-1,0,-1,0,27,27,"5848","",0,"","","",1,0,0,[],""],["rm_t4-n5849",2,"Es de tal modo el amor\nY son sus efectos tales,\nQue lo declaran los ojos,\nAunque la boca lo calle.",2,0,-1,11,"",0,4,"ae",-1,0,-1,0,27,27,"5849","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5851",2,"Las palabras amorosas\nSon las cuentas de un collar;\nQue en saliendo la primera,\nSalen todas las demás.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,28,28,"5851","",0,"suspiros_amor","","",5,0,0,[],""],["rm_t4-n5854",2,"El que enferma de amores\nSin declararse\nEn la convalecencia\nQuiere quedarse.",2,0,-1,11,"",6,4,"ae",250,0,-1,0,28,28,"5854","",0,"","","",3,0,0,[],""],["rm_t4-n5855",2,"Quien ama y no se explica\nSin duda es muerto;\nPues sabiendo la causa,\nCalla el remedio.",2,0,-1,11,"",6,4,"eo",-1,0,-1,0,28,28,"5855","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5856",2,"El que su amor no dice\nDe comedido\nTendrá un amor discreto,\nMas nó entendido.\nRompa el silencio;\nPorque no es amor sordo,\nAunque está ciego.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,28,29,"5856","",0,"","","",1,0,0,[],""],["rm_t4-n5857",2,"El que quiere y no logra\nLo que desea\nPor ser corto de genio,\nCorto se queda.\nPorque, á la verdad,\nNo sabe el que no pide\nQue no le han de dar.",2,0,-1,11,"",4,7,"a",-1,0,-1,0,29,29,"5857","",0,"","","",1,0,0,[],""],["rm_t4-n5858",2,"En contiendas amorosas\nAconseja cierto autor\nHerrar ó quitar el banco,\nY yo sigo su opinion.",2,0,-1,11,"",0,4,"o",-1,0,-1,0,29,29,"5858","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5859",2,"La pasion oprimida\nEs como el rayo:\nCuanto más resistencia,\nMayor estrago.",2,0,-1,11,"",6,4,"ao",-1,0,-1,0,29,29,"5859","",0,"","","",3,0,0,[],""],["rm_t4-n5860",2,"El amor que se oculta\nBajo el silencio\nHace mayor estrago\nDentro del pecho.\nPorque sus llamas,\nComo no hallan salida,\nQueman el alma.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,29,29,"5860","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5861",2,"Amores escondidos\nPor tiempo largo,\nSi en tragedia no acaban,\nSerá milagro.",2,0,-1,11,"",6,4,"ao",-1,0,-1,0,29,29,"5861","",0,"carrizo_salta, palau_cantares, preciso_coleccion","","",4,0,0,[],""],["rm_t4-n5862",2,"La primera sentencia\nQue dió Cupido\nEs que sean los amantes\nAlgo atrevidos.\nQue si son cortos,\nLuégo dicen las damas:\n—¡Jesús, qué tontos!",2,0,-1,11,"",4,7,"oo",-1,0,-1,0,30,30,"5862","",0,"","","",1,0,0,[],""],["rm_t4-n5863",2,"El que teniendo novia\nNo la visita\nNo debe tener pena\nSi se la quitan.",2,0,-1,11,"",6,4,"ia",-1,0,-1,0,30,30,"5863","",0,"","","",1,0,0,[],""],["rm_t4-n5864",2,"Amor, no pongas amor\nDonde no hay correspondencia;\nMira que te quedarás\nA la luna de Valencia.",2,0,-1,11,"",0,4,"ea",46,0,-1,0,30,30,"5864","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n5865",2,"Amar sin que el amado\nNos corresponda\nNo hay duda que es fineza;\nPero muy tonta.\nQue estas finezas,\nEn lugar de estimarse,\nSe menosprecian.",2,0,-1,11,"",4,7,"ea",-1,0,-1,0,30,30,"5865","",0,"","","",1,0,0,[],""],["rm_t4-n5866",2,"El que ama no siendo\nCorrespondido\nTiene carta de tonto;\nNo la ha leido.\nPorque es simpleza\nAmar á quien no otorga\nCorrespondencia.",2,0,-1,11,"",4,7,"ea",-1,0,-1,0,30,30,"5866","",0,"","","",2,0,0,[],""],["rm_t4-n5868",2,"Desde aquel primer instante\nQue abre el corazon sus puertas,\nAunque las burle un amante,.\nLas suele tener abiertas.",2,0,-1,11,"",1,4,"ea",251,0,-1,0,31,31,"5868","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5869",2,"Dejad llorar á las nubes;\nDejad alumbrar al sol;\nDejad al viejo quejarse\nY al mozo gozar su amor.",2,0,-1,11,"",0,4,"o",-1,0,-1,0,31,31,"5869","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5870",2,"En la venta de amores\nParar no quiero;\nQue hay ladrones que roban\nA los viajeros.\nNo es de mi agrado,\nTras de parar en venta,\nSalir robado.",2,0,-1,11,"",4,7,"ao",14,0,-1,0,31,31,"5870","",0,"","","",1,0,0,[],""],["rm_t4-n5871",2,"No fies en amores;\nQue es desvarío\nTener seguridades\nDe otro albedrío.",2,0,-1,11,"",6,4,"io",3,0,-1,0,31,31,"5871","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n5872",2,"No fies en amores,\nNiña, no fies;\nQue llorarás un tiempo\nLo que ahora ries.",2,0,-1,11,"",6,4,"e",218,0,-1,0,31,31,"5872","",0,"","","",3,0,0,[],""],["rm_t4-n5873",2,"No de muchos obsequios,\nNiña, te fies;\nQue se ven muchos hombres\nQue el amor fingen,\nSiendo su agrado\nExterior sobrescrito\nDe un doble trato.",2,0,-1,11,"",4,7,"ao",-1,0,-1,0,31,32,"5873","",0,"","","",1,0,0,[],""],["rm_t4-n5874",2,"Cupido, como niño,\nHizo diabluras,\nY ahora todos pagamos\nSus travesuras.",2,0,-1,11,"",3,4,"ua",238,0,-1,0,32,32,"5874","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n5875",2,"Cuando de amor el fuego\nDevora el alma,\nLos reflejos que salen\nDan en la cara.\nPorque este humo\nSe sale haciendo burla\nDel disimulo.",2,0,-1,11,"",4,7,"uo",-1,0,-1,0,32,32,"5875","",0,"","","",1,0,0,[],""],["rm_t4-n5876",2,"Cuando baja el empacho\nY el amor sube\nSe acaban los ustedes\nY entran los tues.\nPero en riñendo,\nVuelven como al principio\nLos cumplimientos.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,32,32,"5876","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5877",2,"Cuando servir se quiere\nCon vida y alma\nLa intencion generosa\nDicen que basta.",2,0,-1,11,"",6,4,"aa",-1,0,-1,0,32,32,"5877","",0,"","","",1,0,0,[],""],["rm_t4-n5878",2,"Cuando se quiere de véras\nNo se mira el qué dirán:\nQuien tiene fé en un camino\nNo vuelve la cara atrás.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,32,33,"5878","",0,"rm_t2","","",3,0,0,[],""],["rm_t4-n5879",2,"Cuando dos quieren á una\nY los dos están presentes,\nEl uno cierra los ojos\nY el otro aprieta los dientes.",2,0,-1,11,"",0,4,"ee",252,0,-1,0,33,33,"5879","",0,"palau_cantares, frenk_t2, lafuente_madrid","","",8,0,0,[],""],["rm_t4-n5880",2,"Cuando dos quieren á una\nY ésta á uno nada más,\nAnda el otro, que parece\nZorra que ha comido agraz.",2,0,-1,11,"",0,4,"a",253,0,-1,0,33,33,"5880","",0,"","","",8,0,0,[],""],["rm_t4-n5881",2,"Cuando uno quiere á una\nY esta una no lo quiere,\nEs lo mismo que si un calvo\nSe encuentra en la calle un peine.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,33,33,"5881","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t4-n5882",2,"Cuando en la calle se encuentran\nPersonas que se han querido,\nÓ se les muda el color,\nÓ se les quita el sentido.",2,0,-1,11,"",0,4,"io",101,0,-1,0,33,33,"5882","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5883",2,"Cuando dos se están queriendo\nY se encuentran en la calle,\nSe dicen bajito adios,\nSin que pueda oirlos nádie.",2,0,-1,11,"",0,4,"ae",-1,0,-1,0,33,33,"5883","",0,"","","",2,0,0,[],""],["rm_t4-n5884",2,"Cuando dos que se quieren\nSe ven solitos,\n¡Qué de cargos se hacen\nLos pobrecitos!",2,0,-1,11,"",6,4,"io",254,0,-1,0,33,33,"5884","",0,"","","",2,0,0,[],""],["rm_t4-n5885",2,"Cuando están los amantes\nAlgo enojados\nSe mira el uno al otro\nDe medio lado.\n¡Con qué cautela\nEl rabillo del ojo\nAnda que vuela!",2,0,-1,11,"",4,7,"ea",167,0,-1,0,33,34,"5885","",0,"","","",1,0,0,[],""],["rm_t4-n5886",2,"El amante enojado\nEs como el niño;\nQue en haciéndole halagos,\nVuelve al cariño.\nY así, el retrato\nDel amor es un niño\nFácil y vario.",2,0,-1,11,"",4,7,"ao",-1,0,-1,0,34,34,"5886","",0,"","","",1,0,0,[],""],["rm_t4-n5889",2,"¡Qué bonito está un granado\nCon las granadas abiertas!\n¡Qué bonita está una dama\nCon su galan á la puerta!",2,0,-1,11,"",0,4,"ea",-1,0,-1,0,34,34,"5889","",0,"","","",1,0,0,[],""],["rm_t4-n5890",2,"¡Qué bien canta una calandria!\n¡Qué bien canta un ruiseñor!\nMás bien canta una doncella\nCuando está junto á su amor.",2,0,-1,11,"",0,4,"o",72,0,-1,0,34,35,"5890","",0,"","","",2,0,0,[],""],["rm_t4-n5891",2,"Aquel si viene ó no viene,\nAquel si sale ó no sale,\nEn los amores no tiene\nContento que se le iguale.",2,0,-1,11,"",1,4,"ae",202,0,-1,0,35,35,"5891","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5892",2,"Cuando se oculta la luna\nY se presenta la aurora\nEs la ocasion oportuna\nPara hablar con quien se adora.",2,0,-1,11,"",1,4,"oa",107,0,-1,0,35,35,"5892","",0,"","","",1,0,0,[],""],["rm_t4-n5893",2,"A eso de la media noche,\nCuando la luna va en calma,\nSe dan las satisfacciones\nLos amantitos del alma.",2,0,-1,11,"",0,4,"aa",125,0,-1,0,35,35,"5893","",0,"","","",2,0,0,[],""],["rm_t4-n5894",2,"Dos corazones heridos\nDe la misma enfermedad,\nAmbos se quitan la vida,\nPor no decir la verdad.",2,0,-1,11,"",0,4,"a",16,0,-1,0,35,35,"5894","",0,"palau_cantares","","",4,0,0,[],""],["rm_t4-n5895",2,"Mucho se quieren dos primos,\nPorque la sangre les tira;\nMás se quieren dos amantes;\nNádie me lo contradiga.",2,0,-1,11,"",0,4,"ia",-1,0,-1,0,35,35,"5895","",0,"","","",1,0,0,[],""],["rm_t4-n5897",2,"¡Qué gustosa va un alma\nCuando la llevan\nDesde las falsedades\nÁ las finezas!",2,0,-1,11,"",6,4,"ea",-1,0,-1,0,36,36,"5897","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n5898",2,"¡Qué feliz es el dia\nQue dos amantes\nCeden á un mismo tiempo\nLas voluntades!",2,0,-1,11,"",6,4,"ae",-1,0,-1,0,36,36,"5898","",0,"","","",1,0,0,[],""],["rm_t4-n5899",2,"Si apesar de desdenes\nDura el afecto,\nPasion es incurable\nY amor perfecto.",2,0,-1,11,"",6,4,"eo",256,0,-1,0,36,36,"5899","",0,"","","",1,0,0,[],""],["rm_t4-n5900",2,"Para olvidar finezas,\nPensar agravios;\nÉste ha sido un consejo\nQue me dió un sabio.",2,0,-1,11,"",6,4,"ao",-1,0,-1,0,36,36,"5900","",0,"","","",1,0,0,[],""],["rm_t4-n5901",2,"Disimular quereres\nSe usa ahora\nY hablar mal del sujeto\nQue bien se adora.",2,0,-1,11,"",6,4,"oa",107,0,-1,0,36,36,"5901","",0,"","","",1,0,0,[],""],["rm_t4-n5902",2,"El corazon que sólo\nDe esperar vive,\nCuanto más se dilata,\nMás se comprime.\nY muchas veces\nSi la posesion tarda,\nEl amor crece.",2,0,-1,11,"",4,7,"ee",-1,0,-1,0,36,36,"5902","",0,"","","",1,0,0,[],""],["rm_t4-n5903",2,"No sirven esperanzas,\nDicen autores;\nNo sirven esperanzas\nSin posesiones.",2,0,-1,11,"",6,4,"oe",-1,0,-1,0,37,37,"5903","",0,"","","",1,0,0,[],""],["rm_t4-n5904",2,"Esperanza entretiene,\nPosesion cansa,\nApetecer desvela,\nNo lograr mata.\nY lo adquirido,\nCuando alguno lo pierde,\nPierde el sentido.",2,0,-1,11,"",4,7,"io",101,0,-1,0,37,37,"5904","",0,"","","",1,0,0,[],""],["rm_t4-n5905",2,"Yo no sé quién se fíe\nDe la esperanza:\nBasta que sea hembra\nPara ser falsa.\nPues mucho ofrece,\nMas hace, no cumpliendo,\nQue desespere.",2,0,-1,11,"",4,7,"ee",-1,0,-1,0,37,37,"5905","",0,"","","",1,0,0,[],""],["rm_t4-n5906",2,"Son los enamorados\nComo las bestias;\nPues sólo se mantienen\nDe lo que piensan.",2,0,-1,11,"",6,4,"ea",-1,0,-1,0,37,37,"5906","",0,"","","",3,0,0,[],""],["rm_t4-n5907",2,"Muchos con la esperanza\nViven alegres;\nMuchos son los borricos\nQue comen verde.",2,0,-1,11,"",6,4,"ee",-1,0,-1,0,37,37,"5907","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],""],["rm_t4-n5908",2,"El que quisiere amando\nVivir sin pena\nHa de tomar el tiempo\nConforme venga.\nQuiera querido,\nY cuando le desprecien,\nHaga lo mismo.",2,0,-1,11,"",4,7,"io",-1,0,-1,0,37,38,"5908","",0,"","","",3,0,0,[],""],["rm_t4-n5909",2,"Para curar heridas\nDe un amor necio\nNo hay cosa como un parche\nDe menosprecio.\nY si no pega,\nUngüento de mal pago,\nQue al alma llega.",2,0,-1,11,"",4,7,"ea",257,0,-1,0,38,38,"5909","",0,"","","",2,0,0,[],""],["rm_t4-n5910",2,"No te enamores, niña,\nDe forasteros;\nQue, cuando ménos pienses,\nTomarán vuelo.",2,0,-1,11,"",6,4,"eo",-1,0,-1,0,38,38,"5910","",0,"","","",4,0,0,[],""],["rm_t4-n5911",2,"No te enamores, serrana,\nDe mocito forastero;\nQue en volviendo las espaldas,\nSi te vide no me acuerdo.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,38,38,"5911","",0,"","","",5,0,0,[],""],["rm_t4-n5912",2,"El amor del forastero\nEs como la golondrina;\nQue así que llega el verano,\nA su tierra se encamina.",2,0,-1,11,"",0,4,"ia",11,0,-1,0,38,38,"5912","",0,"lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["rm_t4-n5914",2,"La verdadera prueba\nDe un fino afecto\nNo consiste en los dichos,\nSino en los hechos.\nQue es positivo\nSer mucha la distancia\nDel hecho al dicho.",2,0,-1,11,"",4,7,"io",-1,0,-1,0,39,39,"5914","",0,"","","",1,0,0,[],""],["rm_t4-n5915",2,"El hablar quiere gracia\nY el cantar, brío;\nY el pelar la pavita,\nMucho sentido.",2,0,-1,11,"",6,4,"io",-1,0,-1,0,39,39,"5915","",0,"","","",2,0,0,[],""],["rm_t4-n5916",2,"Nádie pele la paba,\nPorque está bisto\nQue de pelar la paba\nSalen pabitos.\nSalen con pluma,\nPegan un boletío,\nBan á la Cuna.",2,0,-1,11,"",4,7,"ua",-1,0,-1,0,39,39,"5916","",0,"","","",1,0,0,[],""],["rm_t4-n5917",2,"Bentanas á la caye\nSon peligrosas\nPá las madres que tienen\nSus hijas mosas.\nY al estribiyo,\nPorque pelan la paba\nCon los poyiyos.",2,0,-1,11,"",4,7,"io",-1,0,-1,0,39,39,"5917","",0,"","","",2,0,0,[],""],["rm_t4-n5918",2,"No juegues con doncellas;\nMira que pasa\nQue aquel que no la hace,\nEse la paga.\nRepara, jóven,\nQue suelen pagar justos\nPor pecadores.",2,0,-1,11,"",4,7,"oe",-1,0,-1,0,39,40,"5918","",0,"","","",1,0,0,[],""],["rm_t4-n5919",2,"Tambien Cupido tiene\nSu calendario;\nPara un dia de fiesta,\nMil de trabajo.\nY aunque haya muchos\nEn que se come carne,\nHay más de ayuno.",2,0,-1,11,"",4,7,"uo",-1,0,-1,0,40,40,"5919","",0,"","","",1,0,0,[],""],["rm_t4-n5920",2,"El amarse ó no amarse\nNo es más que un juego\nQue unos ganan favores\nY otros, desprecios.",2,0,-1,11,"",6,4,"eo",-1,0,-1,0,40,40,"5920","",0,"","","",1,0,0,[],""],["rm_t4-n5921",2,"Todos dicen que aman;\nTodos que adoran;\nPero todos olvidan\nCuando no logran.\nY en tal mudanza,\nLos hombres y mujeres\nTodos se igualan.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,40,40,"5921","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5922",2,"Los mayores trabajos\nDe los amores\nSon las impertinencias\nDe los mirones.\nPero éstos mismos\nNo tienen poca pena\nCon ser testigos.",2,0,-1,11,"",4,7,"io",-1,0,-1,0,40,40,"5922","",0,"","","",1,0,0,[],""],["rm_t4-n5923",2,"A la mar parecidos\nSon los amantes,\nPorque tienen sus calmas\nY tempestades.",2,0,-1,11,"",6,4,"ae",-1,0,-1,0,41,41,"5923","",0,"","","",1,0,0,[],""],["rm_t4-n5924",2,"Los amantes más tibios\nY más ingratos\nSuelen ser comunmente\nMás estimados.\nQue el Amor, niño,\nPerderá mil finezas\nPor un capricho.",2,0,-1,11,"",4,7,"io",-1,0,-1,0,41,41,"5924","",0,"","","",1,0,0,[],""],["rm_t4-n5925",2,"Tan sólo por una cosa\nLe tengo tirria al amor:\nPorque siempre el más malito\nSe ha de llevar lo mejor.",2,0,-1,11,"",0,4,"o",72,0,-1,0,41,41,"5925","",0,"","","",1,0,0,[],""],["rm_t4-n5927",2,"Lástima les tengo yo\nA toditas las mujeres:\nMientras más bonitas son,\nMás mala fortuna tienen.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,41,41,"5927","",0,"","","",3,0,0,[],""],["rm_t4-n5929",2,"Disputaban dos sabios\nQué era más muerte:\nSi ser aborrecido,\nO estar ausente.\nY han definido\nQue la ausencia es más muerte\nQue aborrecido.",2,0,-1,11,"",4,7,"io",101,0,-1,0,42,42,"5929","",0,"","","",2,0,0,[],""],["rm_t4-n5930",2,"Quien diga que los amantes\nEstán divertidos siempre\nNo debió de tener celos,\nNi estuvo jamás ausente.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,42,42,"5930","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5931",2,"¡Probe der que se ba léjos,\nQue náide s' acuerda d' é;\nPorque 'r corason orbía\nCuando los ojos no ben.",2,0,-1,11,"",0,4,"e",-1,0,-1,0,42,42,"5931","",0,"","","",1,0,0,[],""],["rm_t4-n5932",2,"Para el dolor de un ausente\nNo hay alivio ni consuelo,\nPorque tiene cérca el daño\nY distantes los remedios.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,42,42,"5932","",0,"lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["rm_t4-n5933",2,"La pena mayor de un hombre\nEs no ver á quien bien quiere;\nAl que le toca esa china,\nÉse no vive, que muere.",2,0,-1,11,"",0,4,"ee",115,0,-1,0,42,42,"5933","",0,"","","",1,0,0,[],""],["rm_t4-n5934",2,"Se engaña aquel que dice\nQue el que está ausente\nOlvida lo pasado\nPor lo presente.",2,0,-1,11,"",6,4,"ee",15,0,-1,0,42,43,"5934","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5935",2,"El que dice que la ausencia\nQuita del amor los males\nNi sabe lo que es querer\nNi ha querido nunca á nádie.",2,0,-1,11,"",0,4,"ae",-1,0,-1,0,43,43,"5935","",0,"","","",1,0,0,[],""],["rm_t4-n5936",2,"Entre dos que bien se quieren\nNo hay ausencia ni distancia;\nQue los pensamientos vuelan\nY los suspiros se alcanzan.",2,0,-1,11,"",0,4,"aa",-1,0,-1,0,43,43,"5936","",0,"","","",3,0,0,[],""],["rm_t4-n5937",2,"Los besos y los suspiros,\nLas lágrimas y las quejas,\nSe sabe de dónde salen;\nNádie sabe adónde llegan.",2,0,-1,11,"",0,4,"ea",-1,0,-1,0,43,43,"5937","",0,"","","",1,0,0,[],""],["rm_t4-n5938",2,"Es amor en la ausencia\nComo la sombra,\nQue mientras más se aleja,\nMás cuerpo toma.\nAusencia es aire\nQue apaga el fuego chico\nY aviva el grande.",2,0,-1,11,"",4,7,"ae",-1,0,-1,0,43,43,"5938","",0,"","","",1,0,0,[],""],["rm_t4-n5939",2,"Entre ceniza envuelta\nLa lumbre vive;\nCuanto más retirado,\nAmor más firme.",2,0,-1,11,"",6,4,"ie",-1,0,-1,0,43,43,"5939","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5940",2,"¡Cuántas veces testigo\nHa sido ausencia\nQue declara lo falso\nDe las finezas!\nY ¡cuántas veces\nAcreditó constantes\nA los ausentes!",2,0,-1,11,"",4,7,"ee",-1,0,-1,0,43,44,"5940","",0,"","","",1,0,0,[],""],["rm_t4-n5941",2,"Los que juran amarse\nEternamente\nJuzgan de lo futuro\nPor lo presente.\nMas es lo cierto\nQue la distancia rompe\nLos juramentos.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,44,44,"5941","",0,"","","",1,0,0,[],""],["rm_t4-n5943",2,"Todo el mundo me lo dice;\nYo lo afirmo por verdad:\nEn estando un hombre ausente,\nOtro ocupa su lugar.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,44,44,"5943","",0,"","","",14,0,0,[],""],["rm_t4-n5944",2,"Se oyeran los suspiros\nDel que se ausenta,\nSi no hicieran más eco\nLos que están cérca.",2,0,-1,11,"",6,4,"ea",-1,0,-1,0,44,44,"5944","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n5945",2,"No gastes tus finezas\nCon un ausente,\nQue ese sufragio pide\nCuerpo presente.\nY es muy seguro\nQue debe ser el llanto\nSobre el difunto.",2,0,-1,11,"",4,7,"uo",-1,0,-1,0,44,45,"5945","",0,"","","",1,0,0,[],""],["rm_t4-n5946",2,"Ausencia de dos almas\nQue bien se quieren\nEs bastante motivo\nPara que enfermen.\nMas siendo larga,\nEl olvido se sigue\nY al cabo sanan.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,45,45,"5946","",0,"","","",1,0,0,[],""],["rm_t4-n5947",2,"El que se ausenta y deja\nA su querida\nLuégo no forma queja\nSi ella le olvida.\nPues será fijo\nQue se verá obsequiada\nDe sus amigos.",2,0,-1,11,"",4,7,"io",-1,0,-1,0,45,45,"5947","",0,"","","",1,0,0,[],""],["rm_t4-n5948",2,"Es en amor la ausencia\nComo la muerte,\nY el olvido es la losa\nDel que está ausente.\nAusencia es hielo,\nQue enfria cuanto toca\nY apaga el fuego.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,45,45,"5948","",0,"","","",1,0,0,[],""],["rm_t4-n5954",2,"Fuí al campo á preguntarle\nA la violeta\nSi para mal de amores\nHabia receta.\nMe ha respondido\nQue para mal de amores\nNunca la ha habido.",2,0,-1,11,"",4,7,"io",101,0,-1,0,46,46,"5954","",0,"","","",2,0,0,[],""],["rm_t4-n5955",2,"El mal de amor tiene cura,\nEn sabiéndolo curar:\nTodo consiste en querer\nOlvidar ó no olvidar.",2,0,-1,11,"",0,4,"a",21,0,-1,0,47,47,"5955","",0,"","","",3,0,0,[],""],["rm_t4-n5956",2,"El que quiera á una muchacha,\nComo la quiera de véras,\nQue se encomiende á la Vírgen\nDe Consolacion de Utrera.",2,0,-1,11,"",0,4,"ea",-1,0,-1,0,47,47,"5956","",0,"","","",1,0,0,[],""],["rm_t4-n5957",2,"El que quisiere saber\nDe qué color es la pena,\nDe una jembra s' enamore\nY esta jembra no lo quiera.",2,0,-1,11,"",0,4,"ea",-1,0,-1,0,47,47,"5957","",0,"","","",5,0,0,[],""],["rm_t4-n5958",2,"¡Qué de estrellas en el cielo,\nY de estrellas menuditas!\nPero más hombres se mueren\nPor las muchachas bonitas.",2,0,-1,11,"",0,4,"ia",258,0,-1,0,47,47,"5958","",0,"","","",1,0,0,[],""],["rm_t4-n5959",2,"Yo he bisto á un hombre bibí\nCon más e sien puñalâs\nY aluégo lo bí morí\nCon una sola mirâ.",2,0,-1,11,"",5,4,"i",-1,0,-1,0,47,47,"5959","",0,"","","",1,0,0,[],""],["rm_t4-n5960",2,"Entre la tierra y el cielo\nSe oyó una voz por el aire:\n—Quien quiera vivir tranquilo,\nNo ponga su amor en nádie.",2,0,-1,11,"",0,4,"ae",-1,0,-1,0,47,47,"5960","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n5961",2,"En lo profundo del mar\nSuspiraba una ballena\nY en los suspiros decia:\n—Quien tiene amor, tiene penas.",2,0,-1,11,"",0,4,"ea",-1,0,-1,0,47,47,"5961","",0,"","","",6,0,0,[],""],["rm_t4-n5962",2,"No hay amante sin amante;\nNo hay amor sin pena fuerte;\nNo hay firmeza sin amor,\nNi vida sin tener muerte.",2,0,-1,11,"",0,4,"ee",134,0,-1,0,48,48,"5962","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5963",2,"Las fatigas de la muerte\nGrandes fatiguillas son;\nPero con las del querer\nNo tienen comparacion.",2,0,-1,11,"",0,4,"o",31,0,-1,0,48,48,"5963","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n5964",2,"Quien diga que ha enamorado\nSin sufrir ni padecer,\nÓ siempre ha sido muy necio,\nÓ nunca ha querido bien.",2,0,-1,11,"",0,4,"e",-1,0,-1,0,48,48,"5964","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n5965",2,"Se levanta el rey furioso,\nToma la pluma y escribe,\nY en el primer renglón pone:\n«Quien tiene amores, no vive.»",2,0,-1,11,"",0,4,"ie",190,0,-1,0,48,48,"5965","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5967",2,"Disputan dos autores\nDe grande fama\nCuál es la mayor pena\nDel que bien ama.\nY en su dictámen\nAmar un imposible\nDan por más grande.",2,0,-1,11,"",4,7,"ae",-1,0,-1,0,48,48,"5967","",0,"","","",1,0,0,[],""],["rm_t4-n5968",2,"¿Cuál será el dolor más fuerte\nÓ la pena más sensible:\nEl batallar con la muerte,\nÓ el querer un imposible?",2,0,-1,11,"",1,4,"ie",259,0,-1,0,49,49,"5968","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5970",2,"Querer por sólo querer,\nSin esperanza de premio,\nEs un querer desdichado,\nPero es querer verdadero.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,49,49,"5970","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n5971",2,"No ama mucho quien lo dice,\nSino quien mucho padece;\nQue amor sin penas y obras\nDe amor sólo el nombre tiene.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,49,49,"5971","",0,"","","",4,0,0,[],""],["rm_t4-n5972",2,"A la luz de la razón\nHe venido á comprender\nQue son fatigas de muerte ° 8\nEl querer y no poder.",2,0,-1,11,"",0,4,"e",20,0,-1,0,49,49,"5972","",0,"","","",3,0,0,[],""],["rm_t4-n5973",2,"Las fatigas del querer\nSon las fatigas más grandes,\nPorque se lloran cantando\nY las lágrimas no salen.",2,0,-1,11,"",0,4,"ae",-1,0,-1,0,49,49,"5973","",0,"","","",1,0,0,[],""],["rm_t4-n5974",2,"Cuando un hombre que es muy hombre\nLas lágrimas deja ver,\nAllá en el fondo del alma\n¡Qué pena debe tener!",2,0,-1,11,"",0,4,"e",20,0,-1,0,49,50,"5974","",0,"","","",1,0,0,[],""],["rm_t4-n5975",2,"Las lágrimas del que llora\nSon alivio de sus penas;\nPero queman en la cara\nLo mismo que la candela.",2,0,-1,11,"",0,4,"ea",-1,0,-1,0,50,50,"5975","",0,"","","",1,0,0,[],""],["rm_t4-n5977",2,"Poco de amor suspira\nQuien ama y duerme;\nQue al sueño los pesares\nDestierran siempre.\nQuien duerme y ama\nTiene amor en la boca,\nMas nó en el alma.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,50,50,"5977","",0,"","","",1,0,0,[],""],["rm_t4-n5978",2,"Si duermes con amores,\nDigo que tienes\nDistintos sentimientos\nQue otras mujeres.\nPues es un hecho\nQue siempre los amores\nQuitan el sueño.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,50,50,"5978","",0,"","","",1,0,0,[],""],["rm_t4-n5979",2,"A aquel que quiere de véras\nUn tiro le habian de dar:\nNi come ni bebe á gusto,\nNi lo dejan sosegar.",2,0,-1,11,"",0,4,"a",21,0,-1,0,50,50,"5979","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n5980",2,"Hay hombre que por queré\nAborrese la comía;\n¡Qué hombre no sería aqué\nQu' er queré lo mantenia!",2,0,-1,11,"",1,4,"ea",0,0,-1,0,50,50,"5980","",0,"","","",1,0,0,[],""],["rm_t4-n5981",2,"Un amante novicio\nDijo á un profeso:\n—En materia de amores,\n¿Se pierde el seso?—\nY él le responde:\n—El seso no se pierde;\nPero se esconde.",2,0,-1,11,"",4,7,"oe",260,0,-1,0,51,51,"5981","",0,"","","",1,0,0,[],""],["rm_t4-n5982",2,"No vayas á la tienda\nDel dios Cupido,\nQue por cualquier deleite\nLleva un sentido.\nVé con cautela;\nNo cambies los sentidos\nPor bagatelas.",2,0,-1,11,"",4,7,"ea",-1,0,-1,0,51,51,"5982","",0,"","","",3,0,0,[],""],["rm_t4-n5983",2,"Cualquier hombre que jura\nDe enamorado\nNo debe ser creido\nNi castigado.\nPorque es lo propio\nUn hombre enamorado\nQue un hombre loco.",2,0,-1,11,"",4,7,"oo",-1,0,-1,0,51,51,"5983","",0,"","","",1,0,0,[],""],["rm_t4-n5984",2,"Enamorado un loco,\nDijo con afan:\n—Si una locura mata,\nEn mí, dos, ¿qué harán?\nNo me sujeten;\nQue con amar ya tengo\nPrision más fuerte.",2,0,-1,11,"",4,7,"ee",-1,0,-1,0,51,51,"5984","",0,"","","",1,0,0,[],""],["rm_t4-n5985",2,"El más sabio se atribula;\nQuien tiene razon, la pierde;\nPrevarica del sentido\nAquel que quiere y no puede.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,51,52,"5985","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t4-n5988",2,"El hombre que está queriendo\nNo está en su cabal sentido;\nLo digo por experiencia,\nPorque á mí me ha sucedido.",2,0,-1,11,"",0,4,"io",101,0,-1,0,52,52,"5988","",0,"","","",1,0,0,[],""],["rm_t4-n5989",2,"Cinco sentidos tenemos;\nTodos los necesitamos;\nTodos cinco los perdemos\nCuando nos enamoramos.",2,0,-1,11,"",1,4,"ao",116,0,-1,0,52,52,"5989","",0,"isaacs_colombia, pacifico_colombia","","",7,0,0,[],""],["rm_t4-n5990",2,"A toda mujer que vieres\nAmarilla y con ojeras,\nNo le preguntes qué tiene,\nQue está queriendo de véras.",2,0,-1,11,"",0,4,"ea",103,0,-1,0,52,52,"5990","",0,"","","",3,0,0,[],""],["rm_t4-n5992",2,"La cadena del amor\nLlévala contigo un año,\nY verás qué peso tiene\nEl que vive enamorado.",2,0,-1,11,"",0,4,"ao",-1,0,-1,0,52,53,"5992","",0,"lafuente_madrid, palau_cantares","","",8,0,0,[],""],["rm_t4-n5993",2,"La sombra de la jiguera\nEs mala para dormir;\nSiempre Pedro s' enamora;\nPoco pretende bibir.",2,0,-1,11,"",0,4,"i",157,0,-1,0,53,53,"5993","",0,"","","",1,0,0,[],""],["rm_t4-n5994",2,"En la cárcel del alma\nAmor se encierra;\nCausa cuidados preso,\nY al salir, pena.\nPorque quien ama\nLe da siempre que olvida\nTormento al alma.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,53,53,"5994","",0,"","","",3,0,0,[],""],["rm_t4-n5995",2,"Si el amor procediera\nDe entendimiento,\nMucho ménos se amara\nY más á tiempo.\nVoluntad ciega\nEs la que nos conduce\nY así tropieza.",2,0,-1,11,"",4,7,"ea",-1,0,-1,0,53,53,"5995","",0,"","","",1,0,0,[],""],["rm_t4-n5996",2,"Corazones heridos\nDe amor, discurro\nConvalecen muy pocos;\nSana ninguno.\nQue estas heridas\nEn tan principal parte\nNo se mitigan.",2,0,-1,11,"",4,7,"ia",-1,0,-1,0,53,53,"5996","",0,"","","",1,0,0,[],""],["rm_t4-n5997",2,"El que siente de amores\nQuemarse el pecho\nA matarse de un tiro\nTiene derecho.\nPorque la muerte\nEs de grandes desgracias\nLa mejor suerte.",2,0,-1,11,"",4,7,"ee",134,0,-1,0,53,54,"5997","",0,"","","",1,0,0,[],""],["rm_t4-n6000",2,"—¿Qué son celos?—pregunta\nUn hombre sabio;\nY un rústico responde:\n—Ama y sabráslo.\nPues sus efectos\nEs más fácil sentirlos\nQue conocerlos.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,54,54,"6000","",0,"","","",3,0,0,[],""],["rm_t4-n6001",2,"Celos son unos recelos\nDe la mente acalorada;\nSi son algo, no son celos;\nSi son celos, no son nada.",2,0,-1,11,"",1,4,"aa",49,0,-1,0,54,54,"6001","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6002",2,"Los celos no son nada\nMás que sospechas;\nSi es algo, no son celos:\nSon evidencias.\nY así, el amante\nNo confunda aprensiones\nCon realidades.",2,0,-1,11,"",4,7,"ae",-1,0,-1,0,54,55,"6002","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6003",2,"Los celos se parecen\nA la pimienta,\nQue si es poca, da gusto;\nSi es mucha, quema.\nY el que es machaca\nMás bien atiza el fuego\nQue nó lo apaga.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,55,55,"6003","",0,"","","",2,0,0,[],""],["rm_t4-n6004",2,"Los celos y las olas\nHacen á una;\nQue parecen montañas\nY son espumas.\nY olas y celos\nSe aplacan al instante\nQue cambia el viento.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,55,55,"6004","",0,"","","",3,0,0,[],""],["rm_t4-n6005",2,"Son los celos á veces\nCristal de aumento\nQue hace penar al alma\nSin fundamento.\nPorque los hombres\nSuelen no ver agravios,\nSino visiones.",2,0,-1,11,"",4,7,"oe",-1,0,-1,0,55,55,"6005","",0,"","","",1,0,0,[],""],["rm_t4-n6006",2,"El amor y los celos\nForman tal union,\nQue no hay amor sin celos,\nCelos sin amor.",2,0,-1,11,"",6,4,"o",-1,0,-1,0,55,55,"6006","",0,"","","",2,0,0,[],""],["rm_t4-n6007",2,"¡Qué bien dijo aquel que dijo,\nQuejándose de los celos:\n—No hay cosa para el olvido\nQue otro amor, ó tierra enmedio!",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,55,56,"6007","",0,"","","",3,0,0,[],""],["rm_t4-n6008",2,"El leon en su cueva\nMuere de celos,\nDe ver que su leona\nTiene otro dueño.\nQue en casos tales\nTambien de celos mueren\nLos animales.",2,0,-1,11,"",4,7,"ae",26,0,-1,0,56,56,"6008","",0,"","","",1,0,0,[],""],["rm_t4-n6009",2,"El que lo quieren de balde C1\nNo venga pidiendo celos;\nQue harto favor se le hace\nCon quererle pelo á pelo.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,56,56,"6009","",0,"","","",1,0,0,[],""],["rm_t4-n6010",2,"Celos siempre ignorantes,\n¿Quién os entiende,\nPues andais codiciosos\nDe lo que os duele?",2,0,-1,11,"",6,4,"ee",-1,0,-1,0,56,56,"6010","",0,"","","",1,0,0,[],""],["rm_t4-n6011",2,"Al que fuere celoso\nCuando hay motivo\nNo le llamen celoso,\nSino advertido.\nPorque los celos,\nEn habiendo motivo,\nDejan de serlo.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,56,56,"6011","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6012",2,"Si te ves competida\nDe otra hermosura,\nProcura que los celos\nVenguen tu injuria:\nQue en competencia,\nLos hombres que bien aman\nFinos se ostentan.",2,0,-1,11,"",4,7,"ea",-1,0,-1,0,56,57,"6012","",0,"","","",1,0,0,[],""],["rm_t4-n6014",2,"Por mucho que un celoso\nGuarde su hacienda,\nBeberá aguado el vino\nDe su bodega.\nBien que en el mundo\nSon pocos los que beben\nEl vino puro.",2,0,-1,11,"",4,7,"uo",-1,0,-1,0,57,57,"6014","",0,"","","",1,0,0,[],""],["rm_t4-n6015",2,"Tiene quien de sus celos\nBusca la causa,\nCon ansia de saberla,\nTemor de hallarla.\nY sus recelos\nHacen que entre las dudas\nViva muriendo.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,57,57,"6015","",0,"","","",1,0,0,[],""],["rm_t4-n6016",2,"Cuando pican los celos,\nClaro se infiere\nQue tiene más cariño\nQuien más los siente.",2,0,-1,11,"",6,4,"ee",-1,0,-1,0,57,57,"6016","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6017",2,"En amantes dolencias\nSuelen los celos\nSer á veces sangrías\nHechas á tiempo.",2,0,-1,11,"",6,4,"eo",-1,0,-1,0,57,58,"6017","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6019",2,"El amor ha de ser uno;\nEso bien lo sabeis vos;\nNo tiene amor con ninguno\nLa mujer que quiere á dos.",2,0,-1,11,"",1,4,"o",87,0,-1,0,58,58,"6019","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6020",2,"El árbol del cariño\nTiene una rama;\nNo puede subir uno\nSin que otro caiga.",2,0,-1,11,"",6,4,"aa",-1,0,-1,0,58,58,"6020","",0,"","","",2,0,0,[],""],["rm_t4-n6021",2,"El árbol del querer bien\nNo tiene más que una rama;\nY para subir á él\nEs preciso que otro caiga.",2,0,-1,11,"",0,4,"aa",-1,0,-1,0,58,58,"6021","",0,"","","",2,0,0,[],""],["rm_t4-n6025",2,"No te enamores, mozuela,\nDe pájaro volantón,\nQue anda de olivo en olivo,\nBuscando la mejor flor.",2,0,-1,11,"",0,4,"o",-1,0,-1,0,59,59,"6025","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t4-n6026",2,"Querer una no es ninguna;\nQuerer dos es falsedad;\nQuerer tres y engañar cuatro,\nEso es gracia que Dios da.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,59,59,"6026","",0,"palau_cantares","","",7,0,0,[],""],["rm_t4-n6027",2,"La dama que quiere á dos\nNo es tonta, que es advertida:\nSi una vela se le apaga,\nOtra le queda encendida.",2,0,-1,11,"",0,4,"ia",37,0,-1,0,59,59,"6027","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6028",2,"La niña que tiene uno\nY pretende tener dos,\nSe quedará sin ninguno,\nQue así lo dispone Dios.",2,0,-1,11,"",1,4,"o",87,0,-1,0,59,59,"6028","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6030",2,"La dama que con muchos\nLa pava pela\nPasa la vida alegre\nY al fin se queda....",2,0,-1,11,"",6,4,"ea",-1,0,-1,0,60,60,"6030","",0,"","","",1,0,0,[],""],["rm_t4-n6031",2,"La que con muchos trata\nY es retrechera\nQuedará para tía,\nAunque no quiera.\nCuadre ó no cuadre,\nSólo si fuere monja\nSe dirá madre.",2,0,-1,11,"",4,7,"ae",166,0,-1,0,60,60,"6031","",0,"","","",2,0,0,[],""],["rm_t4-n6032",2,"Cuando una tiene muchos\nQue la enamoran,\nSe hacen unos á otros\nMuy mala obra.",2,0,-1,11,"",6,4,"oa",-1,0,-1,0,60,60,"6032","",0,"","","",1,0,0,[],""],["rm_t4-n6033",2,"Tanto entrante y saliente,\nTanta visita,\nEs causa que las damas\nNo hallen salida.",2,0,-1,11,"",6,4,"ia",-1,0,-1,0,60,60,"6033","",0,"","","",1,0,0,[],""],["rm_t4-n6034",2,"Pasan las dichas del mundo;\nPasa la vida y el tiempo;\nLo que no pasa jamás\nEs el amor verdadero.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,60,60,"6034","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6035",2,"Amores de largo tiempo,\n¡Qué malos de olvidar son,\nPorque han echado raíces\nEnmedio del corazon!",2,0,-1,11,"",0,4,"o",31,0,-1,0,60,61,"6035","",0,"","","",3,0,0,[],""],["rm_t4-n6036",2,"Salomon, con ser tan sabio,\nLe preguntó al rey Dabí\nSi amor que pasa de un año\nHabrá criado raiz.",2,0,-1,11,"",0,4,"i",-1,0,-1,0,61,61,"6036","",0,"","","",2,0,0,[],""],["rm_t4-n6037",2,"El primer amor que tuve\nSe me llevó el corazon;\nNo hay amor como el primero,\nQue se lleva lo mejor.",2,0,-1,11,"",0,4,"o",-1,0,-1,0,61,61,"6037","",0,"palau_cantares","","",6,0,0,[],""],["rm_t4-n6038",2,"No hay amor como er primero,\nY los demás son fingíos:\nEr primer amor que tube\nSe yebó er corason mio.",2,0,-1,11,"",0,4,"io",-1,0,-1,0,61,61,"6038","",0,"","","",1,0,0,[],""],["rm_t4-n6039",2,"El primer amor es cosa\nQue dura toda la vida,\nY lo demás son raíces\nQue con el tiempo se olvidan.",2,0,-1,11,"",0,4,"ia",-1,0,-1,0,61,61,"6039","",0,"","","",1,0,0,[],""],["rm_t4-n6040",2,"Los primeros amores\nNo sé qué tienen:\nSe meten en el alma,\nSalir no pueden.",2,0,-1,11,"",6,4,"ee",-1,0,-1,0,61,61,"6040","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6041",2,"No hay fruta como la uba,\nNi tener como er dinero;\nNáide me lo contradiga:\n¡No hay amor como er primero!",2,0,-1,11,"",0,4,"eo",38,0,-1,0,61,61,"6041","",0,"","","",1,0,0,[],""],["rm_t4-n6042",2,"Aunque algunos autores\nLo contradigan,\nLos primeros amores\nSon los que privan.\nSi no se logran,\nSiempre quedan impresos\nEn la memoria.",2,0,-1,11,"",4,7,"oa",-1,0,-1,0,61,62,"6042","",0,"suspiros_amor","","",2,0,0,[],""],["rm_t4-n6044",2,"Al que quiere y aborrese\nHabia de querer Dios\nQue le dieran er Santolio\nEn la boca d' un cañon.",2,0,-1,11,"",5,4,"ao",-1,0,-1,0,62,62,"6044","",0,"","","",1,0,0,[],""],["rm_t4-n6049",2,"Quien bien quiso, tarde olvida,\nY si olvida, no aborrece;\nY al mirar lo que ha querido,\nVuelve á querer, si se ofrece.",2,0,-1,11,"",0,4,"ee",64,0,-1,0,63,63,"6049","",0,"","","",1,0,0,[],""],["rm_t4-n6050",2,"La mujer que quiso á un hombre,\nCuando lo ha querido bien,\nAunque la amistá se acabe,\nSiempre hace memoria de él.",2,0,-1,11,"",0,4,"e",-1,0,-1,0,63,63,"6050","",0,"","","",1,0,0,[],""],["rm_t4-n6051",2,"El que se retira y vuelve\nNo tiene ningun delito;\nQue el águila se remonta\nY vuelve á su mismo sitio.",2,0,-1,11,"",0,4,"io",-1,0,-1,0,63,63,"6051","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6052",2,"El amor que se va y vuelve\nLo tengo yo comparado\nCon los niños de la escuela,\nQue siempre van disgustados.",2,0,-1,11,"",0,4,"ao",-1,0,-1,0,63,63,"6052","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6053",2,"Carbon que ha sido lumbre,\nTengo entendido\nQue luégo á poco soplo\nQueda encendido.",2,0,-1,11,"",6,4,"io",101,0,-1,0,63,63,"6053","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6054",2,"El amor desunido\nEs como zarza;\nQue mientras más se corta,\nBrota con ansia.",2,0,-1,11,"",6,4,"aa",-1,0,-1,0,63,63,"6054","",0,"","","",1,0,0,[],""],["rm_t4-n6055",2,"Cuando dos que se quieren\nHacen las paces,\nRenuevan las ofertas\nDe ser constantes.",2,0,-1,11,"",6,4,"ae",-1,0,-1,0,63,63,"6055","",0,"","","",2,0,0,[],""],["rm_t4-n6056",2,"Quien desata la cuerda,\nMas no la rompe,\nEn los segundos nudos\nAprieta doble.",2,0,-1,11,"",6,4,"oe",-1,0,-1,0,64,64,"6056","",0,"","","",1,0,0,[],""],["rm_t4-n6057",2,"¿De qué sirve la riña\nDe dos amantes,\nSi el corazon entónces\nEs más constante?",2,0,-1,11,"",6,4,"ae",-1,0,-1,0,64,64,"6057","",0,"","","",2,0,0,[],""],["rm_t4-n6058",2,"El que compra un desengaño\nEn los amores primeros,\nEn los amores segundos\nDesengaños va vendiendo.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,64,64,"6058","",0,"suspiros_amor","","",2,0,0,[],""],["rm_t4-n6059",2,"A hombre que quiso á otra\nLe tengo miedo,\nNo sea yo segunda,\nLlore primero.\nNunca hago empresa\nDe manjares ningunos\nDe última mesa.",2,0,-1,11,"",4,7,"ea",201,0,-1,0,64,64,"6059","",0,"","","",1,0,0,[],""],["rm_t4-n6060",2,"Amor resucitado\nYo no lo quiero,\nPorque siempre á mortaja\nMe estará oliendo.\nY yo me asusto\nDe las cosas que vienen\nDel otro mundo.",2,0,-1,11,"",4,7,"uo",-1,0,-1,0,64,64,"6060","",0,"","","",2,0,0,[],""],["rm_t4-n6061",2,"No te cases con viudo,\nQue luégo suelen decir\nDonde quiera que se ponen:\n—¡Mujer, la que yo perdí!",2,0,-1,11,"",0,4,"i",-1,0,-1,0,64,65,"6061","",0,"","","",1,0,0,[],""],["rm_t4-n6064",2,"Cuando va por la calle\nLa viuda rica,\nUn ojo dice «nones»\nY otro repica.\nPero si es pobre,\nPor honrar al difunto\nBusca á los hombres.",2,0,-1,11,"",4,7,"oe",-1,0,-1,0,65,65,"6064","",0,"","","",1,0,0,[],""],["rm_t4-n6065",2,"La viuda hermosa es rosa\nQue á todas gana,\nPorque no tiene espinas,\nNi tiene guarda.\nY á quien la obsequia\nAgradece el alivio\nDe sus tristezas.",2,0,-1,11,"",4,7,"ea",-1,0,-1,0,65,65,"6065","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6066",2,"No quiero amor con doncellas;\nQue las casadas me dan\nTodo lo que necesito;\nMe dicen si quiero más.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,65,66,"6066","",0,"","","",1,0,0,[],""],["rm_t4-n6067",2,"No quiero amor con doncella;\nQue me ha dicho una casada\nQue es oficio de ladrones\nAbrir una arca cerrada.",2,0,-1,11,"",0,4,"aa",49,0,-1,0,66,66,"6067","",0,"","","",2,0,0,[],""],["rm_t4-n6068",2,"No quiero amor con casada;\nQue me ha dicho una vïuda\nQue á quien de ajeno se viste\nEn la calle lo desnudan.",2,0,-1,11,"",0,4,"ua",-1,0,-1,0,66,66,"6068","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t4-n6069",2,"Enamoré á una casada\nY luégo me arrepentí;\nComo olvidó á su marido\nMe olvidará luégo á mí.",2,0,-1,11,"",0,4,"i",23,0,-1,0,66,66,"6069","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6070",2,"En casada no pongas\nMucho cariño;\nQue si olvida á su esposo,\n¿Qué hará contigo?\nY al fin, te expones\nPor mujer que disfruta\nDos diversiones.",2,0,-1,11,"",4,7,"oe",34,0,-1,0,66,66,"6070","",0,"","","",1,0,0,[],""],["rm_t4-n6071",2,"Más vale una casada\nQue nó cien mozas,\nPorque las casaditas\nSon cariñosas.\nLa llevo errada:\nMás vale una soltera\nQue cien casadas.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,66,66,"6071","",0,"","","",1,0,0,[],""],["rm_t4-n6075",2,"Llegando las mujeres\nAl cuatro y cero,\nSe quedan para dueñas,\nPor no haber dueño.\nQue las mujeres\nNó cuando quieren logran;\nSí cuando pueden.",2,0,-1,11,"",4,7,"ee",-1,0,-1,0,67,67,"6075","",0,"","","",1,0,0,[],""],["rm_t4-n6079",2,"Limosna pidió á Vénus\nUn pobre anciano,\nY respondió la diosa:\n—Perdone, hermano.\nQue en esta hermandad\nLa juventud se admite,\nNó la ancianidad.",2,0,-1,11,"",4,7,"a",16,0,-1,0,68,68,"6079","",0,"","","",1,0,0,[],""],["rm_t4-n6080",2,"Si en los hombres no hubiera\nExtravagancias,\nLas feas vivirian\nSin esperanza.",2,0,-1,11,"",6,4,"aa",-1,0,-1,0,68,68,"6080","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6081",2,"Dicen que tiene gracia\nLa mujer fea;\nMas yo no quiero gracia\nQue no se vea.",2,0,-1,11,"",6,4,"ea",54,0,-1,0,68,68,"6081","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6082",2,"Viendo una mujer sosa\nCon hermosura,\nDigo:—¡Qué buena pieza\nPara escultura!—\nPorque yo infiero\nQue sólo será buena\nPara modelo.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,68,69,"6082","",0,"","","",1,0,0,[],""],["rm_t4-n6084",2,"Más la quiero pobre y fea\nQue bonita y con dinero;\nLa pobre me mira á mí\nY la bonita al espejo.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,69,69,"6084","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6088",2,"Al hombre que se enamora\nY tiene poca prudencia\nLe vienen luégo á dejar\nA la luna de Valencia.",2,0,-1,11,"",0,4,"ea",46,0,-1,0,69,70,"6088","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6089",2,"Si se te apaga el cigarro,\nNo lo vuelvas á encender;\nSi te despide la novia,\nNo la vuelvas á querer.",2,0,-1,11,"",0,4,"e",20,0,-1,0,70,70,"6089","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6090",2,"Si los hombres se calaran\nComo se cala el melon,\nMás de cuatro muchachitas\nNo vivieran con dolor.",2,0,-1,11,"",0,4,"o",-1,0,-1,0,70,70,"6090","",0,"lafuente_madrid, palau_cantares","","",5,0,0,[],""],["rm_t4-n6091",2,"Alto lo quiero y buen mozo,\nQue le acompañe el talento;\nQue los hombres chiquitillos\nTienen malos pensamientos.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,70,70,"6091","",0,"","","",1,0,0,[],""],["rm_t4-n6092",2,"No me case mi madre\nCon hombre chico,\nQue lo lleve y lo traiga\nComo abanico.",2,0,-1,11,"",6,4,"io",141,0,-1,0,70,70,"6092","",0,"","","",2,0,0,[],""],["rm_t4-n6093",2,"El hombre chico no es hombre,\nQue es un escupo de Adan,\nGarrapata con calzones\nY el pecado original.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,70,70,"6093","",0,"","","",3,0,0,[],""],["rm_t4-n6094",2,"El hombre chico no es hombre,\nQue es figurilla del diablo;\nEl hombre chico parece\nMuñeco desgalichado.",2,0,-1,11,"",0,4,"ao",-1,0,-1,0,70,70,"6094","",0,"","","",3,0,0,[],""],["rm_t4-n6098",2,"Es el amor de los hombres\nParecido á la quincalla;\nQue entre tantos relumbrones\nCosa buena no se halla.",2,0,-1,11,"",0,4,"aa",249,0,-1,0,71,71,"6098","",0,"","","",2,0,0,[],""],["rm_t4-n6099",2,"El amor de los hombres\nEs como el vaso;\nQue, al menor movimiento,\nSe hace pedazos.\nY es evidente\nQue el más fino se quiebra\nMás fácilmente.",2,0,-1,11,"",4,7,"ae",-1,0,-1,0,71,71,"6099","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6100",2,"No te fies del hombre,\nDe mí el primero;\nEsto te digo, niña,\nPorque te quiero.",2,0,-1,11,"",6,4,"eo",38,0,-1,0,71,71,"6100","",0,"","","",1,0,0,[],""],["rm_t4-n6101",2,"No te fies de los hombres,\nAunque te juren las cruces;\nQue lo ménos que se encienden\nEn un altar son dos luces.",2,0,-1,11,"",0,4,"ue",194,0,-1,0,71,71,"6101","",0,"","","",16,0,0,[],""],["rm_t4-n6102",2,"No te fies de los hombres,\nAunque digan «bien te quiero;»\nQue en volviendo las espaldas,\nSi te he visto no me acuerdo.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,72,72,"6102","",0,"palau_cantares","","",16,0,0,[],""],["rm_t4-n6103",2,"No te fies de los hombres,\nQue tienen poca firmeza\nY se mudan la camisa,\nLo mismo que las culebras.",2,0,-1,11,"",0,4,"ea",-1,0,-1,0,72,72,"6103","",0,"palau_cantares, lafuente_madrid","","",16,0,0,[],""],["rm_t4-n6104",2,"No te fies de los hombres,\nAunque lloren á tus plantas;\nQue son como los pepinos,\nQue vienen á temporadas.",2,0,-1,11,"",0,4,"aa",-1,0,-1,0,72,72,"6104","",0,"palau_cantares","","",16,0,0,[],""],["rm_t4-n6105",2,"El hombre que quiere á dos\nUn castigo meresia;\nEr corgarlo d' un chaparro,\nQue pagara con su bía.",2,0,-1,11,"",5,4,"ia",-1,0,-1,0,72,72,"6105","",0,"","","",2,0,0,[],""],["rm_t4-n6106",2,"La mujer, con ser muy frágil,\nEs firme roca en querer;\nLos hombres, con ser tan fuertes,\nAdoran á cuantas ven.",2,0,-1,11,"",0,4,"e",-1,0,-1,0,72,72,"6106","",0,"","","",1,0,0,[],""],["rm_t4-n6107",2,"No fies en los hombres\nAunque prometan,\nQue ellos tiran la caña,\nPor ver si pescan.\nPero en pescando,\nEllos salen riendo\nY ellas llorando.",2,0,-1,11,"",4,7,"ao",33,0,-1,0,72,72,"6107","",0,"","","",1,0,0,[],""],["rm_t4-n6108",2,"A la mar tiré un chino;\nCayó en la arena;\nConfianza en los hombres\nNádie la tenga.\nPorque los hombres,\nEn viéndose queridos,\nNo corresponden.",2,0,-1,11,"",4,7,"oe",-1,0,-1,0,73,73,"6108","",0,"","","",1,0,0,[],""],["rm_t4-n6109",2,"Aunque quieras á un hombre\nMás que á la vida,\nNo le muestres cariño,\nQue eres perdida.\nPues luégo dicen:\n—Fulana fué mi novia;\nYo no la quise.",2,0,-1,11,"",4,7,"ie",-1,0,-1,0,73,73,"6109","",0,"","","",1,0,0,[],""],["rm_t4-n6110",2,"Al hombre falso y sin ley\nTrátalo con segundilla;\nPor si acaso te echa el rey,\nÉchale tú la malilla.",2,0,-1,11,"",1,4,"ia",162,0,-1,0,73,73,"6110","",0,"","","",2,0,0,[],""],["rm_t4-n6111",2,"Todo el que no fuere hombre\nPara cumplir su palabra\nQue se quite los calzones\nY que se ponga unas naguas.",2,0,-1,11,"",0,4,"aa",-1,0,-1,0,73,73,"6111","",0,"","","",1,0,0,[],""],["rm_t4-n6112",2,"Muchachas, vivir alerta,\nQue el hombre no sufre daño;\nQue en sacudiendo la capa,\nSe va el polvo y-queda el paño.",2,0,-1,11,"",0,4,"ao",40,0,-1,0,73,73,"6112","",0,"","","",1,0,0,[],""],["rm_t4-n6113",2,"No complazcas á los hombres,\nAunque los veas llorar;\nQue cuanto más consiguieren,\nMénos pueden desear.",2,0,-1,11,"",0,4,"a",21,0,-1,0,73,74,"6113","",0,"","","",1,0,0,[],""],["rm_t4-n6115",2,"El demonio son los hombres\nCuando empiezan á querer;\nQue con palabritas dulces\nEngañan á la mujer.",2,0,-1,11,"",0,4,"e",20,0,-1,0,74,74,"6115","",0,"","","",7,0,0,[],""],["rm_t4-n6116",2,"Los hombres son el demonio,\nParientes del Antecristo,\nY nosotras las mujeres\nSomos unos angelitos.",2,0,-1,11,"",0,4,"io",-1,0,-1,0,74,74,"6116","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6117",2,"El demonio son los hombres\nDesde nuestro padre Adan,\nY nosotras las mujeres\nNo nos quedamos atrás.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,74,74,"6117","",0,"","","",7,0,0,[],""],["rm_t4-n6118",2,"Malditos sean los hombres\nY el demonio se los lleve,\nEn sacando yo á mi padre\nY al moreno que me quiere.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,74,74,"6118","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t4-n6119",2,"Son los hombres arcas nuevas\nCon su cerraja y mi llave;\nPor de fuera muy bonitos,\nY por dentro, ¡Dios lo sabe!",2,0,-1,11,"",0,4,"ae",131,0,-1,0,74,74,"6119","",0,"","","",2,0,0,[],""],["rm_t4-n6127",2,"La palabra de los hombres\nEs como la caña vana;\nQue de lo que dicen hoy\nYa no se acuerdan mañana.",2,0,-1,11,"",0,4,"aa",4,0,-1,0,76,76,"6127","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6129",2,"La vara de San José\nTodos los años florece;\nLa palabra de los hombres\nSe ha perdido y no parece.",2,0,-1,11,"",0,4,"ee",64,0,-1,0,76,76,"6129","",0,"lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["rm_t4-n6131",2,"Todos los hombres son falsos,\nTramoyistas y embusteros;\nAl que le toque esa china,\nQue se la eche en el sombrero.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,77,77,"6131","",0,"","","",2,0,0,[],""],["rm_t4-n6132",2,"Los mocitos de hoy en dia\nSon como los alfileres;\nQue no se ven en el suelo\nY engañan á las mujeres.",2,0,-1,11,"",0,4,"ee",55,0,-1,0,77,77,"6132","",0,"","","",3,0,0,[],""],["rm_t4-n6133",2,"Como maestra en amores,\nPondré un letrero en mi escuela:\n«Nádie se fie de hombres,\nPorque á lo mejor la pegan.»",2,0,-1,11,"",0,4,"ea",-1,0,-1,0,77,77,"6133","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6134",2,"En una sala cuadrada,\nLlena de iluminaciones,\nMe puse á considerar\nLo falsos que son los hombres.",2,0,-1,11,"",0,4,"oe",-1,0,-1,0,77,77,"6134","",0,"","","",1,0,0,[],""],["rm_t4-n6135",2,"Al pié de la yerbabuena\nMe puse á considerar\nLo falsos que son los hombres\nCuando van á enamorar.",2,0,-1,11,"",0,4,"a",21,0,-1,0,77,77,"6135","",0,"","","",2,0,0,[],""],["rm_t4-n6136",2,"Al limon quítale el agrio\nY al agrio la fortaleza;\nA los hombres no quererlos,\nPorque no tienen firmeza.",2,0,-1,11,"",0,4,"ea",108,0,-1,0,77,77,"6136","",0,"","","",1,0,0,[],""],["rm_t4-n6137",2,"Yo sembré un peregilar\nY se me volvió culantro;\nQue son capaces los hombres\nDe pegarle un palo á un santo.",2,0,-1,11,"",0,4,"ao",-1,0,-1,0,77,77,"6137","",0,"","","",1,0,0,[],""],["rm_t4-n6138",2,"Tan fásil es ber á un hombre\nQue tenga buenas partías\nComo el haser un bautismo\nEn tierra de morería.",2,0,-1,11,"",0,4,"ia",-1,0,-1,0,78,78,"6138","",0,"","","",1,0,0,[],""],["rm_t4-n6139",2,"Si la mar fuera de tinta\nY el cielo de papel doble,\nNo se pudiera escribir\nLo falsos que son los hombres.",2,0,-1,11,"",0,4,"oe",-1,0,-1,0,78,78,"6139","",0,"palau_cantares, lafuente_madrid","","",11,0,0,[],""],["rm_t4-n6140",2,"Más vale querer á un perro,\nAunque sea un animal,\nQue nó querer á los hombres,\nPor el mal pago que dan.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,78,78,"6140","",0,"","","",5,0,0,[],""],["rm_t4-n6141",2,"Las mujeres al mundo\nPerdido tienen,\nY los hombres al mundo\nY á las mujeres.\nY de este modo,\nHombres, mujeres, mundo,\nPerdido todo.",2,0,-1,11,"",4,7,"oo",261,0,-1,0,78,78,"6141","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6142",2,"En tu vida te enamores\nDe mozo que no ha rondado;\nQue el que no ronda de mozo,\nRonda después de casado.",2,0,-1,11,"",0,4,"ao",14,0,-1,0,78,78,"6142","",0,"lafuente_madrid, palau_cantares","","",7,0,0,[],""],["rm_t4-n6143",2,"No te enamores, serrana,\nDe niño de poca edad;\nQue como le falta el tiempo,\nLe falta la voluntad.",2,0,-1,11,"",0,4,"a",16,0,-1,0,78,78,"6143","",0,"carrizo_salta, palau_cantares","","",5,0,0,[],""],["rm_t4-n6144",2,"No vayas sólita al campo\nCuando sople el aire recio;\nPorque las niñas son flores\nQue hasta las deshoja el viento.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,79,79,"6144","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t4-n6147",2,"La mujer que quiere á un hombre\nCon el corazon lëal\nEs más firme su palabra\nQue el peñon de Gibraltar.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,79,79,"6147","",0,"","","",1,0,0,[],""],["rm_t4-n6148",2,"Mujer, llora y vencerás,\nSi tu amante te desdeña;\nQue hay un adagio que dice:\n«Lágrimas quebrantan peñas.»",2,0,-1,11,"",0,4,"ea",-1,0,-1,0,79,79,"6148","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6150",2,"La dama, por esquiva,\nNo hay que dejarla;\nQue en el hierro más frío\nMás se machaca.\nY golpe á golpe,\nAun la piedra más dura\nBlanda se pone.",2,0,-1,11,"",4,7,"oe",-1,0,-1,0,79,80,"6150","",0,"","","",3,0,0,[],""],["rm_t4-n6151",2,"Mañanita de San Juan\nMadruga, niña, temprano,\nPara darle el corazon\nAl galan que puso el ramo.",2,0,-1,11,"",0,4,"ao",-1,0,-1,0,80,80,"6151","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6152",2,"Mañanita de San Juan\nCuaja la almendra y la nuez;\nAsí cuajan los amores\nCuando dos se quieren bien.",2,0,-1,11,"",0,4,"e",-1,0,-1,0,80,80,"6152","",0,"","","",4,0,0,[],""],["rm_t4-n6155",2,"Es tanto lo qu' apasiona\nUna mujer con salero,\nQu' al hombre más arbertío\nLe liase quitarse 'r sombrero.",2,0,-1,11,"",0,4,"eo",38,0,-1,0,80,80,"6155","",0,"","","",1,0,0,[],""],["rm_t4-n6156",2,"Es tanto lo que apasiona\nUna mujer de trapío,\nQue al hombre de más balor\nSe le quitan los sentios.",2,0,-1,11,"",0,4,"io",-1,0,-1,0,80,80,"6156","",0,"","","",4,0,0,[],""],["rm_t4-n6158",2,"La dama que rompe el plato\nSin ser hora de comer,\nPor muy bonita que sea,\nNunca encuentra mercader.",2,0,-1,11,"",0,4,"e",20,0,-1,0,81,81,"6158","",0,"","","",1,0,0,[],""],["rm_t4-n6159",2,"Hay mujer que, por salir\nA la calle bien portada,\nSe pasa el dia y la noche\nBuscando ropa prestada.",2,0,-1,11,"",0,4,"aa",49,0,-1,0,81,81,"6159","",0,"","","",1,0,0,[],""],["rm_t4-n6160",2,"La mujer que se enamora\nDe la ropa y nó del hombre\nNo tiene vergüenza en cara,\nPorque la ropa se rompe.",2,0,-1,11,"",0,4,"oe",-1,0,-1,0,81,81,"6160","",0,"lafuente_madrid, fernan_caballero, palau_cantares","","",5,0,0,[],""],["rm_t4-n6161",2,"La mujer que se co m pone\nCon demasiado artificio\nNo será por agradar\nSolamente á su marido.",2,0,-1,11,"",0,4,"io",-1,0,-1,0,81,81,"6161","",0,"","","",1,0,0,[],""],["rm_t4-n6162",2,"Si fueres á buscar novia,\nQue no sea en romería,\nSino en casa de sus padres,\nConropita de aquel dia.",2,0,-1,11,"",0,4,"ia",0,0,-1,0,81,81,"6162","",0,"","","",4,0,0,[],""],["rm_t4-n6163",2,"Si fueres á comprar paño,\nMira primero la muestra;\nPorque en el paño hay engaño,\nComo en la dama compuesta\n[Que por dentro tiene el daño].",2,0,-1,11,"",7,5,"ao",40,0,-1,0,81,82,"6163","",0,"","","",2,0,0,[],""],["rm_t4-n6164",2,"No elijas mujer ni tela\nA la luz artificial,\nPorque la una y la otra\nGrandes chascos suelen dar.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,82,82,"6164","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t4-n6165",2,"Ninguna por ser bonita\nA ningun galan desprecie;\nQue un cordon de oro torcido\nDa una vuelta y se destuerce.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,82,82,"6165","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t4-n6166",2,"Más quisiera en una plaza\nA un toro bravo esperar\nQue nó á una mujer que diga:\n«¿Qué cuidado se me da?»",2,0,-1,11,"",0,4,"a",-1,0,-1,0,82,82,"6166","",0,"lafuente_madrid, fernan_caballero, palau_cantares","","",4,0,0,[],""],["rm_t4-n6169",2,"Desde que vino la moda\nDe los pañolitos blancos,\nSe parecen las mujeres\nPalomitas en el campo.",2,0,-1,11,"",0,4,"ao",-1,0,-1,0,82,82,"6169","",0,"","","",1,0,0,[],""],["rm_t4-n6172",2,"A la mujer la comparo\nCon el águila rëal:\nEn acercándose á ella,\nElla se remonta más.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,83,83,"6172","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["rm_t4-n6173",2,"La mujer y la sombra\nTienen un símil:\nQue buscadas, se alejan;\nDejadas, siguen.",2,0,-1,11,"",6,4,"ie",-1,0,-1,0,83,83,"6173","",0,"","","",1,0,0,[],""],["rm_t4-n6174",2,"Lo mismo que la sombra\nSon las mujeres:\nHuyen del que las sigue,\nY al que huye quieren.\nYo las entiendo:\nSi me siguen, aguardo;\nSi huyen, las dejo.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,83,83,"6174","",0,"","","",3,0,0,[],""],["rm_t4-n6175",2,"Como las cañas huecas\nSon las mujeres;\nQue se llenan de aire\nCuando las quieren.",2,0,-1,11,"",6,4,"ee",-1,0,-1,0,83,83,"6175","",0,"palau_cantares, murciano_antiguo, fernan_caballero","","",4,0,0,[],""],["rm_t4-n6176",2,"Las mujeres y cuerdas\nDe la guitarra\nEs menester talento\nPara templarlas.\nFlojas no suenan,\nY suelen saltar muchas\nSi las aprietan.",2,0,-1,11,"",4,7,"ea",-1,0,-1,0,83,84,"6176","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6177",2,"Primero hizo Dios al hombre\nY después á la mujer:\nPrimero se hace la torre\nY la veleta después.",2,0,-1,11,"",0,4,"e",-1,0,-1,0,84,84,"6177","",0,"","","",1,0,0,[],""],["rm_t4-n6178",2,"De una costilla de Adan\nHizo Dios á la mujer,\nPara dejarle á los hombres\nEse hueso que roer.",2,0,-1,11,"",0,4,"e",20,0,-1,0,84,84,"6178","",0,"","","",4,0,0,[],""],["rm_t4-n6179",2,"La primera la hizo Dios\nY ésa engañó al padre Adan;\nCuando á ésa Dios la hizo,\n¿Cómo serán las demás?",2,0,-1,11,"",0,4,"a",-1,0,-1,0,84,84,"6179","",0,"","","",4,0,0,[],""],["rm_t4-n6180",2,"Una mujer fué la causa\nDe la perdicion primera;\nNo hay perdicion en el mundo\nQue por mujeres no venga.",2,0,-1,11,"",0,4,"ea",-1,0,-1,0,84,84,"6180","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t4-n6181",2,"La mujer y el perro dogo\nSon de la misma manera;\nQue cuando sienten halagos,\nSe van detrás de cualquiera.",2,0,-1,11,"",0,4,"ea",44,0,-1,0,84,84,"6181","",0,"","","",2,0,0,[],""],["rm_t4-n6182",2,"Tengo yo comparaíta\nLa mujé con er cabayo;\nQu' es menester buen ginete\nPâ quitarle los resabios.",2,0,-1,11,"",0,4,"ao",-1,0,-1,0,84,85,"6182","",0,"","","",1,0,0,[],""],["rm_t4-n6183",2,"Comparo á las mujeres\nCon las sardinas:\nMientras más resaladas,\nSon más dañinas.",2,0,-1,11,"",6,4,"ia",243,0,-1,0,85,85,"6183","",0,"","","",1,0,0,[],""],["rm_t4-n6184",2,"A la mujé la comparo\nCon una mardita liebre:\nSale un gargo, salen dos,\nSi no la cogen, la muerden.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,85,85,"6184","",0,"","","",1,0,0,[],""],["rm_t4-n6187",2,"Muchas veces siguiendo\nLa liebre un galgo,\nOtro llega y la coge\nPor el atajo.\nCalla y no ladres,\nPara que no te sigan\nA los alcances.",2,0,-1,11,"",4,7,"ae",-1,0,-1,0,85,85,"6187","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6188",2,"Un cazador se queja,\nDiciendo á voces:\n— Quien á dos liebres sigue\nNinguna coge.\nY es cosa rara\nQue unos siguen la liebre\nY otros la agarran.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,86,86,"6188","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6189",2,"Las mocitas de hoy en dia\nSon como las avellanas:\nParten una, parten dos,\nY toditas salen vanas.",2,0,-1,11,"",0,4,"aa",263,0,-1,0,86,86,"6189","",0,"","","",2,0,0,[],""],["rm_t4-n6191",2,"Las damas y las uvas\nDe nobles parras,\nMuchas suelen quedarse,\nPor estar altas.\nLos moscardones\nSe las comen y dejan\nLos cascarones.",2,0,-1,11,"",4,7,"oe",34,0,-1,0,86,86,"6191","",0,"","","",1,0,0,[],""],["rm_t4-n6192",2,"La mujer y las flores\nSon parecidas:\nMucha gala á los ojos,\nY al tacto, espinas.\nY yo, que tengo\nEl corazon llagado,\nNunca escarmiento.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,86,86,"6192","",0,"","","",1,0,0,[],""],["rm_t4-n6194",2,"Las mujeres y el vino\nSon semejantes:\nCon el aire solano\nSuelen picarse.\nAunque se hallan\nMuchas que á todos aires\nEstán picadas.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,87,87,"6194","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6195",2,"La mujer y la moneda\nTienen mucha semejanza:\nAlgunas de oro parecen,\nY resulta que son falsas.",2,0,-1,11,"",0,4,"aa",-1,0,-1,0,87,87,"6195","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6196",2,"Las mujeres de ahora\nSon como libros,\nQue por nuevos se compran\nY están leidos.\nY muchos de ellos,\nEstando remendados,\nPasan por nuevos.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,87,87,"6196","",0,"palau_cantares, suspiros_amor","","",3,0,0,[],""],["rm_t4-n6197",2,"Comparaíta la tengo\nLa mujé con la tormenta:\nDespués que pierden á un hombre,\nLuégo le dan la contenta.",2,0,-1,11,"",0,4,"ea",229,0,-1,0,87,87,"6197","",0,"","","",1,0,0,[],""],["rm_t4-n6200",2,"La mujer es una nave\nQue á todo el mundo atropella;\nMuy poco del mundo sabe\nAquel que se embarca en ella.",2,0,-1,11,"",1,4,"ea",6,0,-1,0,88,88,"6200","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6201",2,"Con el gobierno de España\nComparo yo á la mujer:\nNi nacidos ni que nazcan\nLa han llegado á comprender.",2,0,-1,11,"",0,4,"e",20,0,-1,0,88,88,"6201","",0,"","","",1,0,0,[],""],["rm_t4-n6202",2,"Como las papeleras\nSon las mujeres:\nNada se encuentra en ellas\nMás que papeles.\nLleva cuidado\nY huye de las mujeres\nDesconfiado.",2,0,-1,11,"",4,7,"ao",14,0,-1,0,88,88,"6202","",0,"","","",1,0,0,[],""],["rm_t4-n6203",2,"Es la mujer conjunto\nDe malo y bueno;\nEn su postrera obra\nDios echó el resto.\nNádie le gana\nCuando es la mujer buena\nNi cuando es mala.",2,0,-1,11,"",4,7,"aa",-1,0,-1,0,88,89,"6203","",0,"","","",2,0,0,[],""],["rm_t4-n6204",2,"Las mujeres son ladronas,\nQue les quitan á los hombres\nLa luz del entendimiento\nY sin sentido los ponen.",2,0,-1,11,"",0,4,"oe",-1,0,-1,0,89,89,"6204","",0,"","","",3,0,0,[],""],["rm_t4-n6205",2,"Es amor en mujeres\nCauta sirena,\nQue, prometiendo gustos,\nSólo da penas.\nPues siempre vemos\nQue emplean sus halagos\nPara perdernos.",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,89,89,"6205","",0,"","","",1,0,0,[],""],["rm_t4-n6206",2,"El amor de la mujer\nEs como el de la gallina;\nQue en faltándole su gallo,\nA cualquier pollo se arrima.",2,0,-1,11,"",0,4,"ia",-1,0,-1,0,89,89,"6206","",0,"","","",4,0,0,[],""],["rm_t4-n6207",2,"El amor de las mujeres\nSuele ser como el del perro;\nQue aunque le sacudan palos,\nNunca desampara al dueño.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,89,89,"6207","",0,"palau_cantares, lafuente_madrid","","",17,0,0,[],""],["rm_t4-n6208",2,"El querer de las mujeres\nEs como dia nublado;\nQue tienen más pareceres\nQue leyes un abogado.",2,0,-1,11,"",1,4,"ao",14,0,-1,0,89,89,"6208","",0,"","","",1,0,0,[],""],["rm_t4-n6209",2,"El amor de las mujeres\nLo comparo á la pajuela;\nQue arde mucho, dura poco,\nY no alumbra, ¡pero quema!",2,0,-1,11,"",0,4,"ea",-1,0,-1,0,89,90,"6209","",0,"","","",17,0,0,[],""],["rm_t4-n6210",2,"Ya no hay Padre Santo en Roma,\nNi en España cristiandad,\nNi en las mujeres firmeza,\nNi en los hombres lëaltad.",2,0,-1,11,"",0,4,"a",16,0,-1,0,90,90,"6210","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6212",2,"Una mujer salió buena\nPor una casualidad,\nY la llevaron al punto\nA la Historia Natural.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,90,90,"6212","",0,"","","",1,0,0,[],""],["rm_t4-n6213",2,"Hombre que tan ciego vas,\nPor las mujeres revuelto,\nEllas te darán el pago;\nMira á mí cómo me han puesto.",2,0,-1,11,"",0,4,"eo",-1,0,-1,0,90,90,"6213","",0,"","","",1,0,0,[],""],["rm_t4-n6214",2,"El hilo para coser\nHa de ser fino y parejo;\nLa mujer, para ser buena,\nHa de mudar el pellejo.",2,0,-1,11,"",0,4,"eo",264,0,-1,0,90,90,"6214","",0,"","","",1,0,0,[],""],["rm_t4-n6216",2,"La misma resistencia\nLa mujer tiene\nQue una gasa prendida\nCon alfileres.",2,0,-1,11,"",6,4,"ee",-1,0,-1,0,91,91,"6216","",0,"palau_cantares, suspiros_amor","","",3,0,0,[],""],["rm_t4-n6219",2,"En la regla primera\nDice Cupido\nQue hay mujer que se agarra\nDe un enlucido.\nY en la segunda,\nQue mujer que se agarra\nNo suelta nunca.",2,0,-1,11,"",4,7,"ua",-1,0,-1,0,91,91,"6219","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6221",2,"Quien cariño en mujeres\nPusiere loco\nPierde amor y cariño;\nLo pierde todo.\nQue las mujeres,\nMientras más las queremos,\nMénos nos quieren.",2,0,-1,11,"",4,7,"ee",-1,0,-1,0,92,92,"6221","",0,"","","",2,0,0,[],""],["rm_t4-n6222",2,"Al amor lo pintan niño\nY á la firmeza mujer;\nEntre una mujer y un niño,\n¿Qué amor firme puede haber?",2,0,-1,11,"",1,4,"e",20,0,-1,0,92,92,"6222","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6224",2,"A un sabio le pregunté,\nY no supo contestarme,\nPor qué no hay amor sin celos\nNi mujer que sea constante.",2,0,-1,11,"",0,4,"ae",-1,0,-1,0,92,92,"6224","",0,"","","",2,0,0,[],""],["rm_t4-n6225",2,"Compadezco á los hombres,\nPorque á la fuerza\nTienen que estar sujetos\nA una veleta.\nPorque no hay mujer\nQue no sea veleta,\nTocante al querer.",2,0,-1,11,"",4,7,"e",20,0,-1,0,92,92,"6225","",0,"","","",1,0,0,[],""],["rm_t4-n6226",2,"El llanto en las mujeres\nEs una alhaja;\nPara usarla la tienen\nComo en un arca.\nAbren y lloran,\nLa cierran y se rien\nCuando acomoda.",2,0,-1,11,"",4,7,"oa",-1,0,-1,0,92,93,"6226","",0,"","","",1,0,0,[],""],["rm_t4-n6227",2,"Papeles son papeles;\nCartas son cartas;\nPalabras de mujeres\nTodas son falsas.",2,0,-1,11,"",6,4,"aa",-1,0,-1,0,93,93,"6227","",0,"frenk_t2","","",2,0,0,[],""],["rm_t4-n6231",2,"No te fies de ojos negros,\nPorque tiran á matar;\nUnos ojos negros fueron\nCausa de todo mi mal.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,93,93,"6231","",0,"","","",5,0,0,[],""],["rm_t4-n6232",2,"En mujer y en caballo\nNo fies, Roque;\nQue al mejor tiempo pegan\nUn par de coces.\nY es un ganado\nQue al que mejor lo trata\nLe da peor pago.",2,0,-1,11,"",4,7,"ao",-1,0,-1,0,94,94,"6232","",0,"","","",2,0,0,[],""],["rm_t4-n6235",2,"Quien se fie de las hembras\nY en sus halagos creyere;\nSi no se ahorcare á sí mismo,\nSerá porque ellas lo hicieren.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,94,94,"6235","",0,"","","",4,0,0,[],""],["rm_t4-n6242",2,"Cuando intentan las mujeres\nConquistar algun galan,\nHumildes se manifiestan;\nPero después, Dios dirá.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,95,95,"6242","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6243",2,"Más vale querer á un perro\nQue querer á una mujer;\nEl perro busca á su amo;\nLa mujer, el interés.",2,0,-1,11,"",0,4,"e",-1,0,-1,0,95,95,"6243","",0,"","","",5,0,0,[],""],["rm_t4-n6246",2,"Yo he bisto ar demonio un dia\nPerder piés po una mujé;\nMientras mas tuno es un hombre\nMás pronto se quean con é.",2,0,-1,11,"",0,4,"e",77,0,-1,0,96,96,"6246","",0,"","","",1,0,0,[],""],["rm_t4-n6251",2,"La mujer que sale mala\nNi reñirle ni pegarle;\nMeterla en un barco roto\nY que la mar se la trague.",2,0,-1,11,"",0,4,"ae",-1,0,-1,0,96,96,"6251","",0,"","","",7,0,0,[],""],["rm_t4-n6253",2,"La mujer que sale mala,\nNi reñirle ni pegarle;\nAgarrarla de la mano\nY llevársela á su madre.",2,0,-1,11,"",0,4,"ae",-1,0,-1,0,97,97,"6253","",0,"palau_cantares","","",7,0,0,[],""],["rm_t4-n6254",2,"La mujer que sale mala,\nEr pegarle es un engaño;\nYebarla ar Monte e Piedá\nY empeñarla por sien años\n[Y no boberla á sacar].",2,0,-1,11,"",7,5,"a",-1,0,-1,0,97,97,"6254","",0,"","","",7,0,0,[],""],["rm_t4-n6257",2,"Con su capa el torero\nManeja al bicho,\nY la mujer al hombre\nCon su abanico.",2,0,-1,11,"",6,4,"io",-1,0,-1,0,97,97,"6257","",0,"","","",2,0,0,[],""],["rm_t4-n6258",2,"Los hombres son el demonio,\nSegun dicen las mujeres,\nY siempre están deseando\nQue el demonio se las lleve.",2,0,-1,11,"",0,4,"ee",-1,0,-1,0,97,97,"6258","",0,"","","",4,0,0,[],""],["rm_t4-n6259",2,"Si las mujeres tuvieran\nLa libertad de los hombres,\nA los caminos salieran\nA robar los corazones.",2,0,-1,11,"",0,4,"oe",-1,0,-1,0,98,98,"6259","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6261",2,"Si quieres que te caiga\nLa lotería,\nCorteja á una andaluza\nPobre y bonita.\n¡Verás qué terno\nTe sale de desdichas,\nTrampas y enredos!",2,0,-1,11,"",4,7,"eo",-1,0,-1,0,98,98,"6261","",0,"","","",2,0,0,[],""],["rm_t4-n6262",2,"No hay mejor lotería\nPara una moza\nQue el encontrar un tonto\nQue quiera boda.",2,0,-1,11,"",6,4,"oa",-1,0,-1,0,98,98,"6262","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6263",2,"Aprovecha el tiempo, niña,\nY no juegues con la suerte;\nQue la vejez viene luégo\nY luégo viene la muerte.",2,0,-1,11,"",0,4,"ee",134,0,-1,0,98,98,"6263","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6264",2,"Goza del sol mientras dure;\nSiempre no ha de ser verano;\nAprovecha la ocasion,\nQue la tienes en la mano.",2,0,-1,11,"",0,4,"ao",-1,0,-1,0,98,98,"6264","",0,"","","",2,0,0,[],""],["rm_t4-n6265",2,"La aceituna en el olivo,\nSi no la cogen, se pasa;\nEso te sucede á tí,\nChiquilla, si no te casas.",2,0,-1,11,"",0,4,"aa",-1,0,-1,0,98,99,"6265","",0,"","","",2,0,0,[],""],["rm_t4-n6266",2,"La siruela y la mujé\nTienen la mesmita farta:\nNo cogiéndolas á tiempo,\nSiruela y mujé se pasan.",2,0,-1,11,"",0,4,"aa",-1,0,-1,0,99,99,"6266","",0,"","","",1,0,0,[],""],["rm_t4-n6267",2,"Todos quieren á la Antonia;\nLa Antonia no quiere á nádie;\nA lo mejor quedará\nComo pájaro en el aire.",2,0,-1,11,"",0,4,"ae",-1,0,-1,0,99,99,"6267","",0,"","","",2,0,0,[],""],["rm_t4-n6268",2,"El olibo bien plantado\nSiempre parese olibera,\nY la mujer bien casada\nSiempre parese sortera.",2,0,-1,11,"",0,4,"ea",44,0,-1,0,99,99,"6268","",0,"","","",1,0,0,[],""],["rm_t4-n6269",2,"Cuando se presentare\nDecente novio,\nLos padres den las hijas\nEn matrimonio.\nPues por sí solas,\nSi no les dan maridos,\nEllas los toman.",2,0,-1,11,"",4,7,"oa",-1,0,-1,0,99,99,"6269","",0,"","","",1,0,0,[],""],["rm_t4-n6271",2,"El que enferma de amores\nSin calentura,\nQue vaya á la parroquia,\nQue el cura, cura.\nPorque esos males,\nSi el cura no los cura,\nSon incurables.",2,0,-1,11,"",4,7,"ae",-1,0,-1,0,99,100,"6271","",0,"","","",3,0,0,[],""],["rm_t4-n6272",2,"Un hombre es un pollino\nDe marca y media,\nSi ántes de los contratos\nNo mira y piensa.\nQue no es prudente\nAlquilar una casa\nQue tenga duendes.",2,0,-1,11,"",4,7,"ee",-1,0,-1,0,100,100,"6272","",0,"","","",1,0,0,[],""],["rm_t4-n6274",2,"Al juego de lotería\nComparo yo el matrimonio;\nQue el que acierta la mujer,\nHa sacado el premio gordo.",2,0,-1,11,"",0,4,"oo",-1,0,-1,0,100,100,"6274","",0,"","","",1,0,0,[],""],["rm_t4-n6276",2,"No quieras casa caída,\nNi paderes arrumbadas,\nNi casamiento á disgusto;\nDonde hay disgusto no hay nada.",2,0,-1,11,"",0,4,"aa",-1,0,-1,0,100,101,"6276","",0,"","","",4,0,0,[],""],["rm_t4-n6277",2,"Compañero, si te casas,\nBusca una mujer morena;\nQue de las blancas y rubias\nDe ciento sale una buena.",2,0,-1,11,"",0,4,"ea",59,0,-1,0,101,101,"6277","",0,"carrizo_salta","","",5,0,0,[],""],["rm_t4-n6278",2,"Toda la mujer que es moza\nY se pretende casar,\nAlgo le debe al demonio\nY se lo quiere pagar.",2,0,-1,11,"",0,4,"a",21,0,-1,0,101,101,"6278","",0,"","","",1,0,0,[],""],["rm_t4-n6281",2,"Cásate, bella madama,\nY te dirán parabienes\nY luégo irás á comer\nA tu casa, si la tienes.",2,0,-1,11,"",0,4,"ee",120,0,-1,0,101,101,"6281","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6282",2,"Cásate, Juan, en domingo;\nLúnes estarás casado,\nY el mártes preguntarás\nDónde dan el pan fiado.",2,0,-1,11,"",0,4,"ao",14,0,-1,0,101,101,"6282","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6283",2,"Para no ser soldados\nMuchos se casan,\nY es más crüel la guerra\nQue luégo pasan.\nY así, hay casados\nQue dieran una oreja\nPor ser soldados.",2,0,-1,11,"",4,7,"ao",18,0,-1,0,101,102,"6283","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6286",2,"Cásate y disfrutarás\nDe los tres meses primeros;\nY luégo desearás\nLa vida de los solteros.",2,0,-1,11,"",1,4,"eo",22,0,-1,0,102,102,"6286","",0,"carrizo_salta, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6287",2,"Todo el hombre que se casa\nSe parese ar caracó;\nQue se echa una casa á cuestas,\nCon más fatigas que Dios.",2,0,-1,11,"",0,4,"o",-1,0,-1,0,102,102,"6287","",0,"","","",5,0,0,[],""],["rm_t4-n6289",2,"Todo el hombre que se casa\nCon una mujer bonita,\nHasta que no llega á vieja\nEl susto no se le quita.",2,0,-1,11,"",0,4,"ia",50,0,-1,0,102,103,"6289","",0,"","","",5,0,0,[],""],["rm_t4-n6290",2,"De los mayores trabajos\nQue el hombre puede tener\nEs tener la mujer fea\nY no tener qué comer.",2,0,-1,11,"",0,4,"e",20,0,-1,0,103,103,"6290","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6291",2,"Yo le pregunté á un casado:\n— Casado, ¿qué tal te va?—\nY él me respondió: — Soltero,\nCásate tú y lo verás.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,103,103,"6291","",0,"","","",3,0,0,[],""],["rm_t4-n6292",2,"Al pié de la yerbabuena\nMe puse á considerar\nLa sujecion de un casado;\nDe un mozo la libertad.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,103,103,"6292","",0,"","","",2,0,0,[],""],["rm_t4-n6293",2,"El que tiene mujer guapa\nÓ viña en camino real,\nSi quiere cogerle el fruto\nMucho tiene que guardar.",2,0,-1,11,"",0,4,"a",-1,0,-1,0,103,103,"6293","",0,"","","",1,0,0,[],""],["rm_t4-n6294",2,"El viejo que se casa\nCon mujer niña,\nÉl mantiene la cepa\nY otro vendimia.",2,0,-1,11,"",6,4,"ia",-1,0,-1,0,103,103,"6294","",0,"fernan_caballero","","",3,0,0,[],""],["rm_t4-n6295",2,"La que con viejo rico\nNiña se casa,\nAjenos gustos compra,\nY el pobre paga.\nY con halagos\nTrae al viejo contento,\nPero engañado.",2,0,-1,11,"",4,7,"ao",-1,0,-1,0,103,103,"6295","",0,"","","",1,0,0,[],""],["rm_t4-n6296",2,"No te cases con viejo\nPor la moneda:\nLa moneda se acaba\nY el viejo queda.",2,0,-1,11,"",6,4,"ea",266,0,-1,0,104,104,"6296","",0,"","","",4,0,0,[],""],["rm_t4-n6298",2,"De puerta en puerta un pobre\nCoge más cuartos\nQue quedándose en una\nSiempre parado.\nPor esa cuenta\nAndo yo en mis amores\nDe puerta en puerta.",2,0,-1,11,"",4,7,"ea",-1,0,-1,0,104,104,"6298","",0,"","","",3,0,0,[],""],["rm_t4-n6302",2,"Una rosa entró en la iglesia,\nCogida con el rocío;\nEntró libre y salió presa;\nCasada con su marido.",2,0,-1,11,"",0,4,"io",-1,0,-1,0,105,105,"6302","",0,"","","",2,0,0,[],""],["rm_t4-n6303",2,"Comparito mió,\nmi mare,\nPor los ojitos - qu' en la cara tiene,\nQue no m' esampare.",2,0,-1,12,"",3,4,"ae",175,0,-1,0,131,131,"6303","",0,"","","",2,0,0,[],""],["rm_t4-n6304",2,"Dil' usté á mi bata\nQue si no echa é menos\nAquer hijito de las sus entrañas,\nCuando está comiendo.",2,0,-1,12,"",3,4,"eo",-1,0,-1,0,131,131,"6304","",0,"","","",2,0,0,[],""],["rm_t4-n6305",2,"Faitigas yo tengo\nPor la mare mía;\nSe 1' han yebao - los moritos malos\nA la Berbería.",2,0,-1,12,"",3,4,"ia",0,0,-1,0,131,131,"6305","",0,"","","",1,0,0,[],""],["rm_t4-n6307",2,"Penas tié mi mare,\nPenas tengo yo;\nY las que siento son las e mi mare,\nY las mias nó.",2,0,-1,12,"",3,4,"o",2,0,-1,0,131,131,"6307","",0,"","","",1,0,0,[],""],["rm_t4-n6311",2,"Se lo peí yorando\n' La Bínge der Cárme,\nEr que me quite - á mí la salusita,\nSe la dé á mi pare.",2,0,-1,12,"",3,4,"ae",-1,0,-1,0,132,132,"6311","",0,"","","",2,0,0,[],""],["rm_t4-n6314",2,"Queítos los gorpes;\nQueítos por Dios;\nComo está mala la batita mia\nDer mió corason.",2,0,-1,12,"",3,4,"ao",-1,0,-1,0,132,132,"6314","",0,"","","",1,0,0,[],""],["rm_t4-n6315",2,"'N el hespitalito,\nA manita erecha,\nAyí tenía la batita mia\nLa camita jecha.",2,0,-1,12,"",3,4,"ea",269,0,-1,0,132,133,"6315","",0,"","","",1,0,0,[],""],["rm_t4-n6318",2,"Mataon ' á mi hermano\nDer mio corason,\nY los chorreles que l'han queaíto\nLos mantengo yo.",2,0,-1,12,"",3,4,"o",-1,0,-1,0,133,133,"6318","",0,"","","",1,0,0,[],""],["rm_t4-n6319",2,"La Bínge de Regla\nYo se lo he rogao\nDe que me libre un hermanito mio\nDe salí sordao.",2,0,-1,12,"",3,4,"ao",98,0,-1,0,133,133,"6319","",0,"","","",2,0,0,[],""],["rm_t4-n6320",2,"Jincarse e roíyas,\nQue ya biene Dios;\nBa ' resibirlo - la mare e mi arma\nDer mio corason.",2,0,-1,12,"",3,4,"ao",-1,0,-1,0,133,133,"6320","",0,"","","",2,0,0,[],""],["rm_t4-n6323",2,"Er sielo se bistió e luto,\nLa tierra s'echó á temblá,\nPorque s'ha muerto mi mare\nY no la güerbo á ber más.",2,0,-1,12,"",0,4,"a",-1,0,-1,0,134,134,"6323","",0,"","","",2,0,0,[],""],["rm_t4-n6325",2,"Ya se me murió mi madre;\nYa quedó el mundo vacío;\nPor éso va el viento lleno\nDe los suspiritos mios.",2,0,-1,12,"",0,4,"io",-1,0,-1,0,134,134,"6325","",0,"","","",5,0,0,[],""],["rm_t4-n6326",2,"Ya se me murió mi madre;\nYa no tengo quien me quiera;\nQue sólo el querer de madre\nEs grande sobre la tierra.",2,0,-1,12,"",0,4,"ea",-1,0,-1,0,134,134,"6326","",0,"","","",5,0,0,[],""],["rm_t4-n6333",2,"Más desgrasiao que yo\nNo lo parirán las madres:\nQue una camisa que tengo,\nNo tengo quien me la labe.",2,0,-1,12,"",0,4,"ae",-1,0,-1,0,135,135,"6333","",0,"","","",1,0,0,[],""],["rm_t4-n6334",2,"No tengo padre ni madre;\n¿A quién m' arrimaré yo?\nM' arrimaré á un arbolito\nQu' eche fruto y no eche flor.",2,0,-1,12,"",3,4,"o",-1,0,-1,0,135,135,"6334","",0,"","","",4,0,0,[],""],["rm_t4-n6336",2,"No tengo pare ni mare\nNi quien s' acuerde de mí:\nM' arrimo á los mulaares,\nLas moscas juyen de mí.",2,0,-1,12,"",0,4,"i",-1,0,-1,0,135,135,"6336","",0,"","","",1,0,0,[],""],["rm_t4-n6337",2,"Aquel que no tenga madre\nQue no pare de llorar;\nPara llorarla son pocas\nLas agüitas de la mar.",2,0,-1,12,"",0,4,"a",21,0,-1,0,136,136,"6337","",0,"","","",2,0,0,[],""],["rm_t4-n6341",2,"Cuando te beo yorando,\nGanas me dan de reí:\nQuien tiene madre y se queja\nNo es hombre, que es un mandí.",2,0,-1,12,"",0,4,"i",23,0,-1,0,136,136,"6341","",0,"","","",1,0,0,[],""],["rm_t4-n6348",2,"Si la madre de mi alma\nViera lo que estoy pasando,\nCon lágrimas de sus ojos\nLas calles fuera regando.",2,0,-1,12,"",0,4,"ao",33,0,-1,0,137,137,"6348","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6352",2,"Tôs los simenterios\nLos traigo yo andaos:\nLa seportura - er pare e mi arma\nYo no la he jayao.",2,0,-1,12,"",3,4,"ao",-1,0,-1,0,138,138,"6352","",0,"","","",1,0,0,[],""],["rm_t4-n6353",2,"Si supiera er sitio\nAonde la enterraron,\nYo sacaria tôs sus güesesitos\nPara embarsamarlos.",2,0,-1,12,"",0,4,"ao",-1,0,-1,0,138,138,"6353","",0,"","","",2,0,0,[],""],["rm_t4-n6354",2,"Nochesita escura,\nEstaba yobiendo;\nAcompañaba ar batito mio\nJasta er simenterio.",2,0,-1,12,"",3,4,"eo",-1,0,-1,0,138,138,"6354","",0,"","","",1,0,0,[],""],["rm_t4-n6355",2,"Ayá 'n Puerta e Tierra,\nEn aquer rincón,\nEstán los güesos - e la maresita\nQu' á mí me parió.",2,0,-1,12,"",3,4,"o",-1,0,-1,0,138,138,"6355","",0,"","","",1,0,0,[],""],["rm_t4-n6356",2,"Seporturerito nuebo,\nToma una monea e dies rales,\nY ábreme la sepurtura\nDonde 'stá enterrá mi mare.",2,0,-1,12,"",0,4,"ae",-1,0,-1,0,138,138,"6356","",0,"","","",2,0,0,[],""],["rm_t4-n6357",2,"Yo m' asomo á la muraya\nY á boses yamo á mi madre;\nBiendo que no me responde,\nYamo á la Bírgen der Cármen.",2,0,-1,12,"",0,4,"ae",-1,0,-1,0,138,138,"6357","",0,"","","",1,0,0,[],""],["rm_t4-n6358",2,"La mano me duele\nDe tanto yamá;\nM' ha respondío la mare e mi arma\nPor la madrugâ.",2,0,-1,12,"",3,4,"u",-1,0,-1,0,139,139,"6358","",0,"","","",2,0,0,[],""],["rm_t4-n6362",2,"Al pié de Sierra Nevada\nTengo de hacer un convento,\nTodo de piedra labrada,\nPara el Santo Sacramento.",2,0,-1,13,"",1,4,"eo",94,0,-1,0,145,145,"6362","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6365",2,"A San Antonio le pido\nQue me dé conformidad;\nQue los bienes de este mundo\nDios los quita y Dios los da.",2,0,-1,13,"",0,4,"a",-1,0,-1,0,146,146,"6365","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",6,0,0,[],""],["rm_t4-n6366",2,"San Antonio bendito,\nRamo de flores,\nA las descoloridas\nDales colores.",2,0,-1,13,"",6,4,"oe",5,0,-1,0,146,146,"6366","",0,"palau_cantares","","",4,0,0,[],""],["rm_t4-n6367",2,"La primera verbena\nQue Dios envía\nEs la de San Antonio\nDe la Florida.",2,0,-1,13,"",6,4,"ia",-1,0,-1,0,146,146,"6367","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6368",2,"¿Qué tienes con San Antonio,\nQue tanto te acuerdas de él?\nSan Antonio está en el cielo.\n¡Quién estuviera con él!",2,0,-1,13,"",0,4,"e",-1,0,-1,0,146,146,"6368","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6369",2,"Los profetas y patriarcas\nY los mártires queremos,\nQue son nuestros protectores\nY de Dios los mensajeros.",2,0,-1,13,"",0,4,"eo",-1,0,-1,0,146,146,"6369","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n6372",2,"Todos los santos son buenos\nY San Juan es el mejor,\nPorque ése tuvo la dicha\nDe bautizar al Señor.",2,0,-1,13,"",0,4,"o",72,0,-1,0,147,147,"6372","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6373",2,"A los cielos se sube\nSan Ildefonso,\nCapellan de los cielos,\nSanto glorioso.",2,0,-1,13,"",6,4,"oo",-1,0,-1,0,147,147,"6373","",0,"","","",1,0,0,[],""],["rm_t4-n6374",2,"San Francisco es más que Dios,\nEn cuanto á las llagas digo;\nQue al santo se las dió Dios\nY á Dios un perro judío.",2,0,-1,13,"",0,4,"io",-1,0,-1,0,147,147,"6374","",0,"","","",3,0,0,[],""],["rm_t4-n6378",2,"Señor San Benito,\nPatron de Sarteras,\nMándanos el agua\nPá las sementeras.",2,0,-1,13,"",0,4,"ea",103,0,-1,0,148,148,"6378","",0,"","","",1,0,0,[],""],["rm_t4-n6380",2,"Los niños por esas calles\nAndan llorando por pan,\nPorque no tienen sus padres\nDónde ganar un jornal.",2,0,-1,13,"",0,4,"a",-1,0,-1,0,148,148,"6380","",0,"","","",1,0,0,[],""],["rm_t4-n6382",2,"¿Qué es aquello que reluce\nPor cima de la custodia?\nSerá la Virgen María,\nQue va por agua á la gloria.",2,0,-1,13,"",0,4,"oa",-1,0,-1,0,148,148,"6382","",0,"","","",8,0,0,[],""],["rm_t4-n6384",2,"Labrador perezoso,\nVístete aprisa,\nQue después del rosario\nSaldrá la misa.",2,0,-1,13,"",6,4,"ia",68,0,-1,0,149,149,"6384","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6385",2,"Los que van al rosario\nNo tienen frio;\nQue la Virgen María\nLes da su abrigo.",2,0,-1,13,"",6,4,"io",-1,0,-1,0,149,149,"6385","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6386",2,"Ya no quiero más fandango\nPara mi condenacion;\nPor la mañana, mi misa;\nPor la tarde, mi sermon.",2,0,-1,13,"",0,4,"o",31,0,-1,0,149,150,"6386","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6387",2,"Los sacerdotes en misa\nDicen:—Ite, misa est.—\nLos ángeles en el cielo\nDicen:—Deo gratias, amen.",2,0,-1,13,"",0,4,"e",-1,0,-1,0,150,150,"6387","",0,"","","",6,0,0,[],""],["rm_t4-n6388",2,"Los sacerdotes en misa\nDicen:—¡Santo, santo, santo!—\nLos ángeles en el cielo\nRepiten el mismo canto.",2,0,-1,13,"",0,4,"ao",30,0,-1,0,150,150,"6388","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t4-n6389",2,"Todos los biérnes del año\nSe dise una misa en Roma,\nQue la dise 'r Padre Santo\nY l' ayúa una paloma\n[Qu' es el Espíritu Santo].",2,0,-1,13,"",7,5,"ao",-1,0,-1,0,150,150,"6389","",0,"","","",1,0,0,[],""],["rm_t4-n6390",2,"Tienes la cara alegre,\nDifunta el alma,\nPorque no te confiesas\nComo Dios manda.",2,0,-1,13,"",6,4,"aa",-1,0,-1,0,150,150,"6390","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t4-n6391",2,"¿Cómo pecando quieres\nNo condenarte,\nSi los justos apénas\nLogran salvarse?",2,0,-1,13,"",6,4,"ae",-1,0,-1,0,150,150,"6391","",0,"","","",1,0,0,[],""],["rm_t4-n6392",2,"Si fueres á confesar,\nDesamínate primero;\nQue confesion sin desámen\nEs leña para el infierno.",2,0,-1,13,"",0,4,"eo",-1,0,-1,0,150,150,"6392","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6394",2,"Mira, mira, pecador,\nQue si vives en pecado,\nPuedes anochecer bueno\nY amanecer condenado.",2,0,-1,13,"",0,4,"ao",14,0,-1,0,151,151,"6394","",0,"","","",1,0,0,[],""],["rm_t4-n6395",2,"¡Oh, Vírgen de las Angustias,\nConsoladora de tristes!\nConcédenos tu perdon,\nPor el hijo que perdistes\n[En tu sagrada pasion].",2,0,-1,13,"",7,5,"ao",31,0,-1,0,151,151,"6395","",0,"","","",1,0,0,[],""],["rm_t4-n6397",2,"Der pino sale la piña\nY de la piña er piñon;\nY de la flor de l' harina\nSacan á nuestro Señó\n[Para la hostia dibina].",2,0,-1,13,"",7,5,"ia",11,0,-1,0,151,151,"6397","",0,"","","",1,0,0,[],""],["rm_t4-n6398",2,"Mira que te mira Dios;\nMira que te está mirando;\nMira que te has de morir;\nMira que no sabes cuándo.",2,0,-1,13,"",0,4,"ao",33,0,-1,0,151,151,"6398","",0,"lafuente_madrid, fernan_caballero, palau_cantares","","",4,0,0,[],""],["rm_t4-n6399",2,"Desde el dia en que nacemos\nA la muerte caminamos;\nNo hay cosa que más se olvide\nNi que más cierta tengamos.",2,0,-1,13,"",0,4,"ao",116,0,-1,0,151,152,"6399","",0,"","","",3,0,0,[],""],["rm_t4-n6400",2,"Acuérdate, pecador,\nQue tu vida es una luz\nY que te puedes morir\nAntes de decir «Jesús.»",2,0,-1,13,"",0,4,"u",270,0,-1,0,152,152,"6400","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t4-n6406",2,"Yo no le temo á la muerte,\nQue morir es natural;\nSólo le temo á la cuenta\nQue á Dios le tengo que dar.",2,0,-1,13,"",0,4,"a",-1,0,-1,0,153,153,"6406","",0,"","","",12,0,0,[],""],["rm_t4-n6407",2,"Ya me están amortajando;\nYa para mí llegó el fin;\nMe están ajustando cuenta\nDe todo mi mal vivir.",2,0,-1,13,"",0,4,"i",-1,0,-1,0,153,153,"6407","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6408",2,"A las ánimas benditas\nNádie les cierre la puerta;\nCon decirles que perdonen\nVan las ánimas contentas.",2,0,-1,13,"",0,4,"ea",-1,0,-1,0,153,153,"6408","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6419",2,"Vírgen de Consolacion,\nQue estais en ese castillo,\n¡Oh, quien tuviera mi alma\nDonde vos teneis el Niño!",2,0,-1,13,"",0,4,"io",-1,0,-1,0,154,155,"6419","",0,"","","",2,0,0,[],""],["rm_t4-n6420",2,"Los pájaros del Castillo\nA voces bajan diciendo:\n—¿Dónde estará la paloma\nQue habitaba en este templo?",2,0,-1,13,"",0,4,"eo",-1,0,-1,0,155,155,"6420","",0,"","","",1,0,0,[],""],["rm_t4-n6428",2,"A la cabecera tengo\nUna Virgen del Pilar,\nA la que yo me encomiendo\nCuando estás en alta mar.",2,0,-1,13,"",0,4,"a",21,0,-1,0,156,156,"6428","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6429",2,"La Vírgen del Pilar lleva\nEncima de su corona\nDos claveles encarnados\nDel Padre Santo de Roma.",2,0,-1,13,"",0,4,"oa",-1,0,-1,0,156,156,"6429","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6430",2,"Morena es la Virgen de Arcos,\nMorena la del Pilar;\nPara morena y con gracia,\nLa Virgen del Tremedal.",2,0,-1,13,"",0,4,"a",-1,0,-1,0,156,156,"6430","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6431",2,"Morena es la Magdalena\nY la Vírgen del Pilar;\nYo digo que es más morena\nLa Vírgen del Olivar.",2,0,-1,13,"",1,4,"a",21,0,-1,0,156,156,"6431","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6432",2,"Adoro lo moreno,\nDesde que supe\nQue morena es la Vírgen\nDe Guadalupe.",2,0,-1,13,"",6,4,"ue",271,0,-1,0,156,156,"6432","",0,"","","",1,0,0,[],""],["rm_t4-n6434",2,"La Virgen de Covadonga\nEs un poco morenita.\nComo vino de la guerra,\nTiene la color marchita.",2,0,-1,13,"",0,4,"ia",50,0,-1,0,157,157,"6434","",0,"","","",3,0,0,[],""],["rm_t4-n6435",2,"La Vírgen de Covadonga\nTiene escalera de piedra;\nBien la pudiera tener\nDe plata, si la quisiera.",2,0,-1,13,"",0,4,"ea",-1,0,-1,0,157,157,"6435","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6436",2,"La Vírgen de los Dolores\nQuiere mucho á los Manueles,\nPorque se llama su hijo\nManolito de los Reyes.",2,0,-1,13,"",0,4,"ee",-1,0,-1,0,157,157,"6436","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6437",2,"Manuel se llama Cristo;\n¡Qué dulce nombre!\n¡Dichoso el que, naciendo,\nManuel le ponen!",2,0,-1,13,"",6,4,"oe",-1,0,-1,0,157,157,"6437","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t4-n6438",2,"No hay hombre como Manuel,\nNi mujer como María,\nNi amor como amor de madre,\nNi luz como la del dia.",2,0,-1,13,"",0,4,"ia",0,0,-1,0,157,157,"6438","",0,"carrizo_salta","","",4,0,0,[],""],["rm_t4-n6440",2,"Dicen que la golondrina\nTiene la pechuga blanca,\nY yo digo que María\nFué concebida sin mancha.",2,0,-1,13,"",0,4,"aa",-1,0,-1,0,157,157,"6440","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",12,0,0,[],""],["rm_t4-n6446",2,"Bendita seas, María,\nPorque tú bendita eres\nEn el cielo y en la tierra\nY entre todas las mujeres.",2,0,-1,13,"",0,4,"ee",55,0,-1,0,158,158,"6446","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6450",2,"En lo más alto del cielo\nSe pasea una doncella,\nQue se llama Encarnacion,\nPorque Dios encarnó en ella.",2,0,-1,13,"",0,4,"ea",6,0,-1,0,159,159,"6450","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6456",2,"Esta noche es Noche-buena\nY no es noche de dormir;\nQue está la Virgen de parto\nY á las doce ha de parir.",2,0,-1,13,"",0,4,"i",157,0,-1,0,160,160,"6456","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t4-n6457",2,"La Noche-buena se viene,\nLa Noche-buena se va,\nY nosotros nos iremos\nY no volveremos más.",2,0,-1,13,"",0,4,"a",-1,0,-1,0,160,160,"6457","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6459",2,"Esta noche nace el Niño,\nEntre la paja y el hielo;\n¡Quién pudiera, Niño mío,\nVestirte de terciopelo!",2,0,-1,13,"",0,4,"eo",10,0,-1,0,160,160,"6459","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",6,0,0,[],""],["rm_t4-n6460",2,"Esta noche ha de nacer\nManolito de Jesús,\nPara morir por el hombre,\nEnclavado en una cruz.",2,0,-1,13,"",0,4,"u",109,0,-1,0,160,160,"6460","",0,"lafuente_madrid, fernan_caballero, palau_cantares","","",4,0,0,[],""],["rm_t4-n6461",2,"Noche-buena y paridita\nPocas la suelen tener;\nLa Vírgen la tuvo buena:\nNoche-buena y varón fué.",2,0,-1,13,"",0,4,"e",-1,0,-1,0,161,161,"6461","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6462",2,"La Vírgen iba á Belen,\nLe dió el parto en el camino,\nY entre la mula y el buey\nNació el Cordero divino.",2,0,-1,13,"",3,4,"io",199,0,-1,0,161,161,"6462","",0,"frenk_t4, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["rm_t4-n6463",2,"En un portalito oscuro,\nLlenito de telarañas,\nEntre la muía y el buey,\nNació el Redentor de almas.",2,0,-1,13,"",3,4,"aa",-1,0,-1,0,161,161,"6463","",0,"","","",2,0,0,[],""],["rm_t4-n6464",2,"El Niño de María\nNo tiene cuna;\nSu padre es carpintero\nY le hará una.",2,0,-1,13,"",6,4,"ua",56,0,-1,0,161,161,"6464","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t4-n6465",2,"A las doce de la noche,\nQue más feliz no se vió,\nNació en un Ave-María,\nSin romper el alba, el sol.",2,0,-1,13,"",0,4,"o",-1,0,-1,0,161,161,"6465","",0,"fernan_caballero","","",7,0,0,[],""],["rm_t4-n6468",2,"En Belen tocan á fuego;\nDel portal salen las llamas,\nPorque dicen que ha nacido\nEl Redentor de las almas.",2,0,-1,13,"",0,4,"aa",-1,0,-1,0,162,162,"6468","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t4-n6469",2,"Por los campos del Oriente\nSale, dando envidia al sol,\nLa más bella criatura\nQue de mujeres nació.",2,0,-1,13,"",0,4,"o",-1,0,-1,0,162,162,"6469","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n6472",2,"En el portal de Belén\nHay estrellas, sol y luna,\nLa Virgen y San José\nY el Niño que está en la cuna.",2,0,-1,13,"",0,4,"ua",56,0,-1,0,162,162,"6472","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",31,0,0,[],""],["rm_t4-n6473",2,"En el portal de Belen\nHay un espejo dorado,\nDonde se mira María\nY Jesús Sacramentado.",2,0,-1,13,"",0,4,"ao",14,0,-1,0,162,162,"6473","",0,"","","",31,0,0,[],""],["rm_t4-n6475",2,"De la sacristía sale\nUn clérigo revestido,\nA darle la enhorabuena\nAl Niño reciennacido.",2,0,-1,13,"",0,4,"io",101,0,-1,0,163,163,"6475","",0,"","","",3,0,0,[],""],["rm_t4-n6476",2,"Un pastor comiendo sopas\nEn el aire divisó\nUn ángel que le decia:\n—Ya ha nacido el Redentor.",2,0,-1,13,"",0,4,"o",-1,0,-1,0,163,163,"6476","",0,"palau_cantares, frenk_t4, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["rm_t4-n6478",2,"Los pastores, que supieron\nQue el Niño estaba en Belén,\nSe dejaron las ovejas\nY apretaron á correr.",2,0,-1,13,"",0,4,"e",-1,0,-1,0,163,163,"6478","",0,"palau_cantares, lafuente_madrid","","",9,0,0,[],""],["rm_t4-n6479",2,"A Belen tengo que ir,\nAunque me riña mi amo;\nQue yo tambien quiero ver\nA ese Niño soberano.",2,0,-1,13,"",0,4,"ao",-1,0,-1,0,163,163,"6479","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n6480",2,"Ha nacido aqueste infante;\nVamos todos con teson,\nA que este Niño chiquito\nNos eche su bendicion.",2,0,-1,13,"",0,4,"o",-1,0,-1,0,163,163,"6480","",0,"","","",1,0,0,[],""],["rm_t4-n6482",2,"Un pastor que, por correr,\nSe le cayó la montera,\nEnmedio de aquellos campos\nEnseñó la calavera.",2,0,-1,13,"",0,4,"ea",44,0,-1,0,164,164,"6482","",0,"","","",3,0,0,[],""],["rm_t4-n6483",2,"Los pastores no son hombres,\nQue son ángeles del cielo;\nQue en el parto de María\nEllos fueron los primeros.",2,0,-1,13,"",0,4,"eo",-1,0,-1,0,164,164,"6483","",0,"","","",3,0,0,[],""],["rm_t4-n6488",2,"Una pastora con queja\nLe decia á su marido:\n—¡Mira qué bien me has llevado\nA ver al reciennacido!",2,0,-1,13,"",0,4,"io",101,0,-1,0,165,165,"6488","",0,"","","",1,0,0,[],""],["rm_t4-n6491",2,"Todos le llevan al Niño;\nYo no tengo que llevarle;\nLas alas del corazon\nQue le sirvan de pañales.",2,0,-1,13,"",0,4,"ae",-1,0,-1,0,165,165,"6491","",0,"palau_cantares, frenk_t4, lafuente_madrid","","",9,0,0,[],""],["rm_t4-n6493",2,"A la nana le cantaba\nLa Vírgen á sus amores:\n—Dulce hijo de mi vida,\nRuega por los pecadores.",2,0,-1,13,"",0,4,"oe",5,0,-1,0,166,166,"6493","",0,"","","",2,0,0,[],""],["rm_t4-n6494",2,"En el portal de Belen\nGitanillos han entrado\nY al Niño recien-nacido\nLos pañales le han robado.",2,0,-1,13,"",0,4,"ao",14,0,-1,0,166,166,"6494","",0,"","","",31,0,0,[],""],["rm_t4-n6496",2,"De Oriente salen tres Reyes\nPara adorar al Dios-niño;\nUna estrella los guiaba\nPara seguir su camino.",2,0,-1,13,"",0,4,"io",-1,0,-1,0,167,167,"6496","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6497",2,"Los Reyes Magos vinieron\nGuiados por una estrella,\nPara festejar al Niño\nQue nació la Noche-buena.",2,0,-1,13,"",0,4,"ea",-1,0,-1,0,167,167,"6497","",0,"","","",1,0,0,[],""],["rm_t4-n6499",2,"La Virgen hizo unas gachas\nDe pepitas de pimiento\nY San José le decia:\n—¡Bendito tu entendimiento!",2,0,-1,13,"",0,4,"eo",94,0,-1,0,168,168,"6499","",0,"","","",1,0,0,[],""],["rm_t4-n6500",2,"La Vírgen lava la ropa,\nSan José la está tendiendo,\nSanta Ana entretiene al Niño,\nY el agua se va riendo.",2,0,-1,13,"",0,4,"eo",52,0,-1,0,168,168,"6500","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6501",2,"La Vírgen está lavando\nY tendiendo en el romero;\nLos angelitos cantando,\nY el romero floreciendo.",2,0,-1,13,"",0,4,"eo",-1,0,-1,0,168,168,"6501","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6502",2,"La Bírgen está labando\nDebajo de una jiguera;\nLos pajaritos cantaban\nAr són de la labandera.",2,0,-1,13,"",0,4,"ea",44,0,-1,0,168,168,"6502","",0,"","","",1,0,0,[],""],["rm_t4-n6504",2,"El rey Heródes, que supo\nQue el Niño nacido habia,\nManda al punto que lo busquen,\nPara quitarle la vida.",2,0,-1,13,"",0,4,"ia",-1,0,-1,0,169,169,"6504","",0,"","","",1,0,0,[],""],["rm_t4-n6506",2,"La Vírgen va caminando,\nVa caminando solita,\nY no lleva más compaña\nQue el Niño de la manita.",2,0,-1,13,"",0,4,"ia",50,0,-1,0,169,169,"6506","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",12,0,0,[],""],["rm_t4-n6507",2,"La Virgen va caminando\nEn la mula de los moños,\nY San José va delante,\nDándole al Niño madroños.",2,0,-1,13,"",0,4,"oo",274,0,-1,0,169,169,"6507","",0,"","","",12,0,0,[],""],["rm_t4-n6509",2,"Lluvias y frios rodean\nA esa estrella tan divina,\nTostando el hermoso cielo\nDe su cara peregrina.",2,0,-1,13,"",0,4,"ia",11,0,-1,0,170,170,"6509","",0,"","","",1,0,0,[],""],["rm_t4-n6511",2,"La Bígen ba e tienda en tienda\nBuscando tinta y papé,\nPara escribirle una carta\nA su esposo San José.",2,0,-1,13,"",0,4,"e",77,0,-1,0,170,170,"6511","",0,"","","",1,0,0,[],""],["rm_t4-n6512",2,"Cuando la Vírgen fué á misa\nAl templo de Salomon,\nEl vestido que llevaba\nEra de rayos de sol.",2,0,-1,13,"",0,4,"o",-1,0,-1,0,170,170,"6512","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6513",2,"San José era carpintero\nY la Vírgen costurera,\nY el Niño labra la cruz,\nPorque ha de morir en ella.",2,0,-1,13,"",0,4,"ea",-1,0,-1,0,170,170,"6513","",0,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n6514",2,"¿Quién sería la madre\nQue parió á Júdas?\n¡Qué hijos tan indinos\nParen algunas",2,0,-1,13,"",6,4,"ua",-1,0,-1,0,170,171,"6514","",0,"","","",3,0,0,[],""],["rm_t4-n6515",2,"Viendo Jesús que su muerte\nLa tenía tan cercana,\nLlamó á su madre prudente\nY con discretas palabras\nLe dijo de aquesta suerte:\n—Madre mia de mi alma,\nVuestra bendicion espero,\nPorque ya ha llegado el dia\nQue, enclavado en un madero,\nSe cumplan las profecías.",2,0,-1,13,"",18,10,"ia",-1,0,-1,0,171,171,"6515","",0,"","","",1,0,0,[],""],["rm_t4-n6519",2,"Míralo, por allí viene\nEl mejor de los nacidos,\nAtado de piés y manos,\nCon el rostro denegrido.",2,0,-1,13,"",0,4,"io",-1,0,-1,0,172,172,"6519","",0,"","","",2,0,0,[],""],["rm_t4-n6520",2,"Ya bienen las tres Marías\nCon los tres cális de plata,\nArrecogiendo la sangre\nQue Jesucristo derrama.",2,0,-1,13,"",0,4,"aa",-1,0,-1,0,172,172,"6520","",0,"","","",1,0,0,[],""],["rm_t4-n6523",2,"En la caye e l' Amargura\nCristo á su Madre 'ncontró;\nNo se pudieron hablar,\nDe sentimiento y dolor.",2,0,-1,13,"",0,4,"o",-1,0,-1,0,172,172,"6523","",0,"","","",2,0,0,[],""],["rm_t4-n6525",2,"En la caye e l' Amargura\nSe cayó Su Majestá,\nY aqueyos perros judíos\nLo alebantan á patâs.",2,0,-1,13,"",0,4,"a",-1,0,-1,0,172,172,"6525","",0,"","","",2,0,0,[],""],["rm_t4-n6527",2,"El sol se vistió de luto\nY la luna se eclipsó;\nLas piedras se quebrantaron\nCuando el Señor espiró.",2,0,-1,13,"",0,4,"o",2,0,-1,0,173,173,"6527","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6528",2,"La tierra sintió su muerte\nY los cielos se nublaron;\nLas sepulturas se abrieron;\nLos muertos resucitaron.",2,0,-1,13,"",0,4,"ao",41,0,-1,0,173,173,"6528","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6529",2,"Ya bienen las golondrinas\nCon su pico muy sereno,\nPá quitarle las espinas\nA Jesús er Nasareno.",2,0,-1,13,"",1,4,"eo",76,0,-1,0,173,173,"6529","",0,"","","",1,0,0,[],""],["rm_t4-n6530",2,"En el monte Calvario\nLas golondrinas\nLe quitaron á Cristo\nTres mil espinas.\nLos gorriones\nLe quitaron á Cristo\nTres mil doblones.",2,0,-1,13,"",4,7,"oe",34,0,-1,0,173,173,"6530","",0,"","","",2,0,0,[],""],["rm_t4-n6532",2,"No volvamos á ofender\nA Cristo crucificado;\nA Aquel que por nuestro sér\nEs tanto lo que ha pasado.",2,0,-1,13,"",1,4,"ao",14,0,-1,0,173,174,"6532","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6534",2,"Un árbol hay en la iglesia\nCon espinas y sin flor;\nEn cada ramita un ángel\nY enmedio Nuestro Señor.",2,0,-1,13,"",0,4,"o",72,0,-1,0,174,174,"6534","",0,"","","",3,0,0,[],""],["rm_t4-n6535",2,"Es tan estrecha la cama\nDonde Jesucristo duerme,\nQue, por no caber en ella,\nUn pié sobre el otro tiene.",2,0,-1,13,"",0,4,"ee",-1,0,-1,0,174,174,"6535","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6537",2,"Anoche en el Sagrario\nVí un Hombre muerto,\nCoronado de espinas\nY el pecho abierto.\nY al lado estaba\nUna Mujer divina\nQue lo adoraba.",2,0,-1,13,"",4,7,"aa",28,0,-1,0,174,174,"6537","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6538",2,"Juéves santo murió Cristo;\nEl viérnes se hizo el entierro;\nSábado resucitó;\nDomingo subió á los cielos.",2,0,-1,13,"",0,4,"eo",-1,0,-1,0,174,175,"6538","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6539",2,"Viérnes santo murió Cristo;\nDomingo resucitó\nY un juéves subió á los cielos,\nQue es dia de la Ascension.",2,0,-1,13,"",0,4,"o",-1,0,-1,0,175,175,"6539","",0,"","","",1,0,0,[],""],["rm_t4-n6540",2,"En el portal de Belen\nHay una piedra redonda,\nDonde el Señor puso el pié\nPara subir á la gloria.",2,0,-1,13,"",0,4,"oa",-1,0,-1,0,175,175,"6540","",0,"","","",31,0,0,[],""],["rm_t4-n6542",2,"Todos los sabios del mundo\nVengan á tomar leccion,\nPorque tengo yo un librito\nQue me lo dió Salomon.",2,0,-1,14,"",0,4,"o",31,0,-1,0,187,187,"6542","",0,"","","",2,0,0,[],""],["rm_t4-n6543",2,"El hombre para ser hombre\nNesesita tres partías:\nJaser mucho, jablar poco\nY no alabarse en su bía.",2,0,-1,14,"",0,4,"ia",-1,0,-1,0,187,187,"6543","",0,"","","",7,0,0,[],""],["rm_t4-n6545",2,"Considera, considera,\nY siempre considerando,\nLos mayores imposibles\nSe suelen vencer callando.",2,0,-1,14,"",0,4,"ao",33,0,-1,0,187,187,"6545","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["rm_t4-n6546",2,"Todo aquel que no pone\nFreno á la lengua\nNo extrañe las desgracias\nQue le sucedan.\nPues las palabras\nNo pueden recogerse,\nYa pronunciadas.",2,0,-1,14,"",4,7,"aa",-1,0,-1,0,188,188,"6546","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6550",2,"Camino de Santander\nTropezó y cayó mi potro;\nNinguno que beba vino\nLe llame borracho á otro.",2,0,-1,14,"",0,4,"oo",275,0,-1,0,188,188,"6550","",0,"","","",2,0,0,[],""],["rm_t4-n6552",2,"Nádie murmure de nádie,\nQue somos de carne humana,\nY no hay pellejo de aceite\nQue no tenga su botana.",2,0,-1,14,"",0,4,"aa",4,0,-1,0,189,189,"6552","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t4-n6553",2,"No murmures de nádie,\nAunque mal vieres;\nDate una vuelta y mira\nLo que tú eres.\nDate una vuelta\nY repara aquel charco\nQue está en tu puerta.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,189,189,"6553","",0,"","","",1,0,0,[],""],["rm_t4-n6554",2,"La vecina de enfrente\nMira mi casa;\nPero no ve la suya,\nQue se le abrasa.",2,0,-1,14,"",6,4,"aa",123,0,-1,0,189,189,"6554","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6555",2,"Como soy escribano,\nSé lo que pasa:\nTodos quieren justicia,\nNó por su casa.",2,0,-1,14,"",6,4,"aa",123,0,-1,0,189,189,"6555","",0,"rm_t2","","",2,0,0,[],""],["rm_t4-n6556",2,"Hablas muy mal de lo bueno\nY Dios te ha de castigar;\nCuando hablas mal de lo bueno,\nDe lo malo, ¿qué será?",2,0,-1,14,"",0,4,"a",-1,0,-1,0,189,189,"6556","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6557",2,"—Fransisca, por tu tejao\nBa subiendo una culebra.\n—Madre, ¡cómo pica er sol!\n—Más pica una mala lengua.",2,0,-1,14,"",0,4,"ea",-1,0,-1,0,189,190,"6557","",0,"","","",1,0,0,[],""],["rm_t4-n6564",2,"Anda béte con er mundo,\nQu' er mundo te dará er pago;\nQue tambien er mundo arregla\nAr que anda desarreglao.",2,0,-1,14,"",0,4,"ao",-1,0,-1,0,191,191,"6564","",0,"","","",3,0,0,[],""],["rm_t4-n6565",2,"Un desnudo vende ropa;\nUn calvo vende los peines;\nUn ciego, los anteojos....\nEste mundo, ¿quién lo entiende?",2,0,-1,14,"",0,4,"ee",-1,0,-1,0,191,191,"6565","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n6568",2,"Dios te libre, libro mio,\nDe las manos del librero;\nQue cuando te está alabando,\nEntónces te está vendiendo.",2,0,-1,14,"",0,4,"eo",-1,0,-1,0,191,191,"6568","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n6570",2,"A veces el semblante\nMás halagüeño\nEs quien tiene escondido\nMayor veneno.\nHuye apariencias,\nQue las más veces suelen\nSernos funestas.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,192,192,"6570","",0,"","","",1,0,0,[],""],["rm_t4-n6572",2,"Nádie descubra su pecho\nPor dar alivio á su pena;\nQue el que su pecho descubre\nPor su boca se condena.",2,0,-1,14,"",0,4,"ea",59,0,-1,0,192,192,"6572","",0,"palau_cantares, machado_venezuela, andina_t2, lafuente_madrid","","",5,0,0,[],""],["rm_t4-n6573",2,"El secreto de tu pecho\nNo se lo digas á nádie:\nMejor te lo guardará\nAquel que no te lo sabe.",2,0,-1,14,"",0,4,"ae",-1,0,-1,0,192,192,"6573","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t4-n6574",2,"El secreto de tu pecho\nNo lo digas á tu amigo;\nQue si la amistad le falta,\nSerá contra tí un testigo.",2,0,-1,14,"",0,4,"io",106,0,-1,0,192,192,"6574","",0,"","","",7,0,0,[],""],["rm_t4-n6575",2,"Más reservado tienes\nLo que no has dicho\nQue aquello que confias\nAl más amigo.\nQue los secretos,\nCuando se comunican,\nNo son ya nuestros.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,192,193,"6575","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6576",2,"Amiga, la más amiga,\nAmiga del corazon,\nLa más amiga la pega\nEn llegando la ocasion.",2,0,-1,14,"",0,4,"ao",31,0,-1,0,193,193,"6576","",0,"fernan_caballero","","",5,0,0,[],""],["rm_t4-n6577",2,"Amigos, el más amigo,\nEl más amigo la pega;\nNo hay más amigo que Dios\nY un duro en la faltriquera.",2,0,-1,14,"",0,4,"ea",-1,0,-1,0,193,193,"6577","",0,"","","",1,0,0,[],""],["rm_t4-n6578",2,"No hay más amigo que Dios,\nY ésto es claro y evidente:\nEl más amigo es traidor\nY el más verdadero miente.",2,0,-1,14,"",3,4,"ee",15,0,-1,0,193,193,"6578","",0,"","","",4,0,0,[],""],["rm_t4-n6579",2,"A mi amigo lo llevé\nA casa de la que amaba,\nY tanto aprendió el camino,\nQue luégo á mí me llevaba.",2,0,-1,14,"",0,4,"aa",28,0,-1,0,193,193,"6579","",0,"","","",3,0,0,[],""],["rm_t4-n6580",2,"A casa de mi dama\nLlevé un amigo,\nY él se quedó por amo;\nYo, despedido.\nÉsto sucede\nPor llevar á los hombres\nDonde hay mujeres.",2,0,-1,14,"",4,7,"ee",-1,0,-1,0,193,193,"6580","",0,"","","",1,0,0,[],""],["rm_t4-n6582",2,"Tendrás, si feliz fueres,\nAmigos muchos;\nPero en los contratiempos\nNo hallarás uno.\nPorque sus miras\nSon el coger las rosas\nSin las espinas.",2,0,-1,14,"",4,7,"ia",-1,0,-1,0,194,194,"6582","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6583",2,"Tendrás muchos amigos\nSi gastas oro;\nPero si no lo gastas,\nAndarás solo.\nPorque ahora es moda\nApreciar el dinero,\nNó la persona.",2,0,-1,14,"",4,7,"oa",-1,0,-1,0,194,194,"6583","",0,"","","",2,0,0,[],""],["rm_t4-n6585",2,"Herodes y Pilatos\nSon enemigos;\nPara perder al Justo\nSe hacen amigos.\n¡Dios nos ampare\nSi Herodes y Pilatos\nSe hacen compadres!",2,0,-1,14,"",4,7,"ae",-1,0,-1,0,194,195,"6585","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n6586",2,"Si la amistad pretendes\nQue sea durable,\nVisita á tus amigos\nDe tarde en tarde.\nPues la más tierna\nSuele tal vez perderse\nCon la frecuencia.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,195,195,"6586","",0,"","","",1,0,0,[],""],["rm_t4-n6589",2,"Más bien en las acciones\nQue en las palabras\nSe descubre lo oculto\nQue hay en el alma.\nY así, no fíes\nDe ofertas que con obras\nNo se confirmen.",2,0,-1,14,"",4,7,"ie",-1,0,-1,0,195,196,"6589","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6591",2,"Hay algunos devotos\nDe ciertos santos,\nQue la devocion dura\nLo que el milagro.\nQuien necesita,\nPide y ofrece á todos\nY luégo olvida.",2,0,-1,14,"",4,7,"ia",-1,0,-1,0,196,196,"6591","",0,"","","",1,0,0,[],""],["rm_t4-n6592",2,"Bígen, si saco este pes,\nD' aseite ofresco un cuartiyo;\nPero así que lo saqué,\n«¡Bígen santa, pâ freiyo!»",2,0,-1,14,"",5,4,"eo",-1,0,-1,0,196,196,"6592","",0,"","","",1,0,0,[],""],["rm_t4-n6594",2,"Vicios hay en el hombre\nDe gran tamaño;\nPero el peor de todos\nEs ser ingrato.\nQue hasta las fieras\nReconocen la mano\nQue las sustenta.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,196,197,"6594","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6595",2,"No te guíes de consejos,\nAunque te los quieran dar;\nGuíate de lo que salga\nDe tu propio natural.",2,0,-1,14,"",0,4,"a",-1,0,-1,0,197,197,"6595","",0,"","","",1,0,0,[],""],["rm_t4-n6597",2,"No trates de imprudentes\nMis advertencias;\nQue las de los amigos\nSon siempre buenas.\nPorque es sabido\nQue el que advierte las faltas\nEs buen amigo.",2,0,-1,14,"",4,7,"io",-1,0,-1,0,197,197,"6597","",0,"","","",1,0,0,[],""],["rm_t4-n6599",2,"Si desvaríos llamas\nA mis consejos,\nSin nombre ya quedaron\nTodos tus hechos.\nPorque son tales,\nQue ya no hay en el mundo\nNombre que darles.",2,0,-1,14,"",4,7,"ae",-1,0,-1,0,198,198,"6599","",0,"","","",1,0,0,[],""],["rm_t4-n6600",2,"Si el amigo te oculta\nTus propias faltas,\nMás vale el enemigo\nQue te las tacha.\nQue éste te enmienda,\nY aquél, disimulando,\nTe las aumenta.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,198,198,"6600","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6601",2,"Si la verdad te digo,\nTe ofendes mucho;\nMas yo de no callarla\nTengo hecho estudio.\nPues las verdades,\nAunque amargas parezcan,\nSon saludables.",2,0,-1,14,"",4,7,"ae",-1,0,-1,0,198,198,"6601","",0,"","","",1,0,0,[],""],["rm_t4-n6602",2,"Las tertulias, que eran ántes\nPasatiempo regular,\nSon hoy alcahuetería\nY ocasion de murmurar.",2,0,-1,14,"",0,4,"a",21,0,-1,0,198,198,"6602","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6603",2,"Las nubes las destruye\nUn viento recio;\nLo mismo una tertulia\nLa acaba un necio.",2,0,-1,14,"",6,4,"eo",276,0,-1,0,198,198,"6603","",0,"","","",2,0,0,[],""],["rm_t4-n6604",2,"Siempre en la concurrencia\nQue sufrir tengo,\nYa con las presumidas,\nYa con los necios.\nY es fuerte cosa\nTolerar presumidas,\nNecios y monas.",2,0,-1,14,"",4,7,"oa",-1,0,-1,0,199,199,"6604","",0,"","","",1,0,0,[],""],["rm_t4-n6605",2,"Meten mucho ruïdo\nLos petimetres,\nPorque siempre lo hicieron\nLos cascabeles.\nY sus ruïdos\nSon á proporcion siempre\nDe sus vacíos.",2,0,-1,14,"",4,7,"io",-1,0,-1,0,199,199,"6605","",0,"","","",1,0,0,[],""],["rm_t4-n6606",2,"La conversación del necio\nEs el martirio del sabio;\nMas como el número es corto,\nPocos hay martirizados.",2,0,-1,14,"",0,4,"ao",-1,0,-1,0,199,199,"6606","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t4-n6607",2,"Tres años há que estudias\nY nada sabes;\nHasta que quince lleves\nNo hay que afanarte.\nQue en aquel tiempo\nPuede que enseñar sepas\nA tus maestros.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,199,199,"6607","",0,"","","",1,0,0,[],""],["rm_t4-n6608",2,"No te presumas sabio\nPorque lees mucho,\nPues ésto sirve poco\nSin otro estudio.\nQue en la lectura\nVes la conciencia de otro,\nMas nó la tuya.",2,0,-1,14,"",4,7,"ua",-1,0,-1,0,199,200,"6608","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6609",2,"Compañerito del alma,\n¿Sabe usté lo que yo digo?\nQue el que no sabe leer,\n¿Para qué quiere los libros?",2,0,-1,14,"",0,4,"io",-1,0,-1,0,200,200,"6609","",0,"","","",4,0,0,[],""],["rm_t4-n6610",2,"Por más que estudie un hombre,\nSiempre le queda\nEl saber más que sabe,\nPor más que sepa.\nCon el estudio\nSe labran las potencias\nAun del más duro.",2,0,-1,14,"",4,7,"uo",-1,0,-1,0,200,200,"6610","",0,"","","",1,0,0,[],""],["rm_t4-n6611",2,"Todo aquel que de sabio\nTiene el aprecio,\nSabio será si sabe\nFingirse necio.",2,0,-1,14,"",6,4,"eo",276,0,-1,0,200,200,"6611","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6612",2,"La espiga rica en fruto\nSe abate á tierra;\nLa que no tiene un grano\nSe empina tiesa.\nEs en su porte\nModesto el hombre sabio\nY altivo el zote.",2,0,-1,14,"",4,7,"oe",-1,0,-1,0,200,200,"6612","",0,"","","",1,0,0,[],""],["rm_t4-n6613",2,"Más importa del sabio\nTan sólo un dia\nQue del simple y el necio\nToda la vida.\nPorque más vale\nQue muchas piedras falsas\nSólo un diamante.",2,0,-1,14,"",4,7,"ae",-1,0,-1,0,200,201,"6613","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6614",2,"Se lamentaba un sabio\nDe su miseria,\nY al campo se ha salido\nA comer yerbas.\nVolvió la cara\nY vió que otro comía\nLas que él dejaba.",2,0,-1,14,"",4,7,"aa",-1,0,-1,0,201,201,"6614","",0,"","","",1,0,0,[],""],["rm_t4-n6616",2,"A todo el que trabaja\nPremiar es fuerza;\nPero muchos trabajan\nY no los premian.\nY en su tormento,\nVen premiar á otros muchos\nSin merecerlo.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,201,201,"6616","",0,"","","",2,0,0,[],""],["rm_t4-n6617",2,"No llames la fortuna,\nQue es mal mandada\nY jamás ella viene\nDonde la llaman.\nY áun es tan loca,\nQue el que ménos merece,\nMejor la logra.",2,0,-1,14,"",4,7,"oa",-1,0,-1,0,201,201,"6617","",0,"","","",1,0,0,[],""],["rm_t4-n6618",2,"No te enfades ni inquietes,\nAunque no puedas\nHallar en lo que buscas\nLo que deseas.\nPues la fortuna\nSuele siempre andar léjos\nDel que la busca.",2,0,-1,14,"",4,7,"ua",-1,0,-1,0,202,202,"6618","",0,"","","",1,0,0,[],""],["rm_t4-n6621",2,"En la tienda del barbero,\n¿Sabe usté lo que se dice?\nQue el Señor le da pañuelo\nAl que no tiene narices.",2,0,-1,14,"",0,4,"ie",-1,0,-1,0,202,202,"6621","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6623",2,"Más vale saber que haber,\nDice la comun sentencia;\nQue el pobre puede ser rico,\nY el rico no compra ciencia.",2,0,-1,14,"",0,4,"ea",46,0,-1,0,202,202,"6623","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6625",2,"El feliz y el desdichado\nSuspiran con diferencia:\nUno publica sus glorias,\nY otro publica sus penas.",2,0,-1,14,"",0,4,"ea",-1,0,-1,0,203,203,"6625","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6626",2,"Cuando camina un feliz,\nSe adorna con aparato\nToda la tierra de flores\nY todo el cielo de raso.",2,0,-1,14,"",0,4,"ao",-1,0,-1,0,203,203,"6626","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6629",2,"Mis amigos me desprecian,\nPorque me ven abatido:\nTodo el mundo corta leña\nDel árbol que está caido.",2,0,-1,14,"",0,4,"io",101,0,-1,0,203,203,"6629","",0,"palau_cantares, lafuente_madrid, preciso_coleccion","","",6,0,0,[],""],["rm_t4-n6630",2,"Si porque me ves caido\nMe señalas con el dedo,\nNo atiendas á lo que soy,\nSino á lo que fui primero.",2,0,-1,14,"",0,4,"eo",-1,0,-1,0,203,203,"6630","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t4-n6632",2,"Como ántes era rico\nY ahora soy pobre,\nAunque al rostro me miras,\nNo me conoces.\nNo extraño ésto,\nPues sé que la pobreza\nMuda de aspecto.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,204,204,"6632","",0,"","","",1,0,0,[],""],["rm_t4-n6633",2,"De rico me pasé á pobre,\nPor ber lo qu' er mundo daba,\nY ya beo que ar qu' es pobre\nNádie le mira á la cara.",2,0,-1,14,"",0,4,"aa",-1,0,-1,0,204,204,"6633","",0,"","","",1,0,0,[],""],["rm_t4-n6634",2,"Cuando tenía dinero,\nMe llamaban don Tomás;\nY ahora que no lo tengo,\nMe llaman Tomás no más.",2,0,-1,14,"",0,4,"a",51,0,-1,0,204,204,"6634","",0,"","","",3,0,0,[],""],["rm_t4-n6635",2,"Para hacerse invisible\nCualquiera hombre,\nNo hay medio más seguro\nQue hacerse pobre.\nPues el dinero\nEs lo que luce y hace\nLos caballeros.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,204,204,"6635","",0,"","","",1,0,0,[],""],["rm_t4-n6636",2,"Al pié de un árbol sin fruto\nMe puse á considerar\nLo poco que vale un hombre\nCuando no tiene que dar.",2,0,-1,14,"",0,4,"a",21,0,-1,0,204,205,"6636","",0,"carrizo_salta","","",5,0,0,[],""],["rm_t4-n6637",2,"Al que se ve colmado\nDe conveniencias\nLas ajenas desgracias\nPoco le inquietan.\nPorque es muy cierto\nQue el harto no se acuerda\nDel que está hambriento.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,205,205,"6637","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6638",2,"Cuando pides limosna\nMolestas tanto,\nQue la gana me quitas\nDe darte un cuarto.\nMarcha á otra parte;\nPorque al pobre y soberbio\nNo hay quien le aguante.",2,0,-1,14,"",4,7,"ae",-1,0,-1,0,205,205,"6638","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6639",2,"Más bale ser negro y rico\nQue pobre y de güeña sangre;\nPorque en este indino mundo\nEr dinero es lo que bale.",2,0,-1,14,"",0,4,"ae",-1,0,-1,0,205,205,"6639","",0,"","","",1,0,0,[],""],["rm_t4-n6640",2,"En el cielo manda Dios;\nLos diablos en el infierno;\nY en este picaro mundo\nEl que manda es el dinero.",2,0,-1,14,"",0,4,"eo",-1,0,-1,0,205,205,"6640","",0,"palau_cantares, machado_venezuela, lafuente_madrid","","",8,0,0,[],""],["rm_t4-n6641",2,"En el cielo manda Dios;\nEn el infierno quien puede;\nY en este pícaro mundo\nEl que más dinero tiene.",2,0,-1,14,"",0,4,"ee",-1,0,-1,0,205,205,"6641","",0,"","","",8,0,0,[],""],["rm_t4-n6650",2,"—Hombre pobre, ¿quién te ha muerto?\n—La propia necesidad;\nQue es capaz un hombre pobre\nDe apestar una ciudad.",2,0,-1,14,"",0,4,"a",16,0,-1,0,207,207,"6650","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6651",2,"Hombre pobre, no te estrañes\nDe que tó 'r mundo te deje;\nPorque la nesesiá\nTiene carita d' hereje.",2,0,-1,14,"",0,4,"ee",173,0,-1,0,207,207,"6651","",0,"","","",1,0,0,[],""],["rm_t4-n6652",2,"Er que no tiene parné\nCon er biento es comparao;\nQue tôs le juyen er burto,\nPor temor d' un resfriao.",2,0,-1,14,"",0,4,"ao",98,0,-1,0,207,207,"6652","",0,"","","",2,0,0,[],""],["rm_t4-n6654",2,"La araña pica en la mosca,\nLa mosca pica en la miel;\nY en el corazón del hombre\nSólo pica el interés.",2,0,-1,14,"",0,4,"e",-1,0,-1,0,207,207,"6654","",0,"","","",1,0,0,[],""],["rm_t4-n6655",2,"Ningun pobre puede ser\nHombre de bien aunque quiera;\nQu' en fartándole 'r parné\nEs un barquiyo sin bela.",2,0,-1,14,"",0,4,"ea",-1,0,-1,0,207,207,"6655","",0,"","","",1,0,0,[],""],["rm_t4-n6656",2,"¡Probesiyo der qu' es probé\nY come por mano ajena;\nQue anda mirando á la cara,\nQuién la tiene mala ó güena!",2,0,-1,14,"",3,4,"ea",59,0,-1,0,207,208,"6656","",0,"","","",1,0,0,[],""],["rm_t4-n6659",2,"Cuando un pobre se emborracha\nY un rico en su compañía,\nLa del pobre es borrachera;\nLa del rico es alegría.",2,0,-1,14,"",0,4,"ia",0,0,-1,0,208,208,"6659","",0,"carrizo_salta","","",5,0,0,[],""],["rm_t4-n6660",2,"La embriaguez en los ricos\nSólo es jaqueca,\nY el vahído en los pobres\nEs borrachera.\nQue en estos tiempos,\nGradúan las acciones\nPor los sujetos.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,208,208,"6660","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6661",2,"A l' Audensia ban dos pleitos\nUno berdá y otro nó;\nLa berdá perdió er juisio,\nQu' er dinero lo mandó.",2,0,-1,14,"",0,4,"o",2,0,-1,0,208,208,"6661","",0,"","","",1,0,0,[],""],["rm_t4-n6662",2,"Yo he visto en un tribunal\nCondenar á un inocente,\nY al mismo tiempo pasaba\nEl que habia hecho la muerte.",2,0,-1,14,"",0,4,"ee",-1,0,-1,0,208,208,"6662","",0,"","","",1,0,0,[],""],["rm_t4-n6663",2,"Cuando se muere argun pobre,\n¡Qué solito ba el entierro!\nY cuando se muere un rico,\nBa la música y er clero.",2,0,-1,14,"",0,4,"eo",-1,0,-1,0,209,209,"6663","",0,"","","",1,0,0,[],""],["rm_t4-n6665",2,"Hasta la leña en el monte\nTiene su separacion:\nUna sirve para santos,\nY otra para hacer carbon.",2,0,-1,14,"",0,4,"ao",-1,0,-1,0,209,209,"6665","",0,"carrizo_salta, palau_cantares","","",3,0,0,[],""],["rm_t4-n6666",2,"Los pobres más hambrientos\nSon los más ricos,\nPorque todo lo comen\nCon apetito.\nNó así los grandes;\nQue aunque todo les sobre,\nLes falta el hambre.",2,0,-1,14,"",4,7,"ae",-1,0,-1,0,209,209,"6666","",0,"","","",2,0,0,[],""],["rm_t4-n6667",2,"No fies en señores\nPor su grandeza,\nQue también los más grandes\nTienen flaquezas.\nPues en sus males,\nHace naturaleza\nTodos iguales.",2,0,-1,14,"",4,7,"ae",26,0,-1,0,209,209,"6667","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6670",2,"Ser rico y ser avariento\nUna misma cosa es;\nPorque nunca se separa\nLa codicia del tener.",2,0,-1,14,"",0,4,"e",-1,0,-1,0,210,210,"6670","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n6672",2,"Cercado de miserias\nUn avariento,\nSus desventuras llora\nSobre el talego.\nPorque no tiene\nValor para pedirle\nQue le remedie.",2,0,-1,14,"",4,7,"ee",-1,0,-1,0,210,210,"6672","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6673",2,"Hay persona que á un pobre\nNo da un ochavo,\nY en la comedia y toros\nGasta un ducado.\nPorque es grandeza\nQue se hagan los regalos\nEn donde suenan.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,210,210,"6673","",0,"","","",1,0,0,[],""],["rm_t4-n6674",2,"Estás lleno de bienes;\nPero te falta\nSaber distribuirlos\nComo Dios manda.\nPorque Él los pone\nEn manos de los ricos,\nPara los pobres.",2,0,-1,14,"",4,7,"oe",-1,0,-1,0,210,211,"6674","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6675",2,"¿Para qué quieres bienes,\nSi no los gastas?\nMira que hay muchos pobres\nQue los aguardan.\nAbre tus cofres\nY no guardes serpientes\nQue te devoren.",2,0,-1,14,"",4,7,"oe",-1,0,-1,0,211,211,"6675","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6676",2,"El que en sí solo piensa\nY á nádie quiere,\nSólo con los trabajos\nSu error advierte.\nSé para todos,\nSi en los trabajos quieres\nNo hallarte solo.",2,0,-1,14,"",4,7,"oo",-1,0,-1,0,211,211,"6676","",0,"","","",1,0,0,[],""],["rm_t4-n6679",2,"Al rico que á los pobres\nLes favorece\nNo le falta socorro\nCuando padece.\nQue en este mundo,\nQuien ajeno pretende,\nDé ántes lo suyo.",2,0,-1,14,"",4,7,"uo",-1,0,-1,0,212,212,"6679","",0,"","","",2,0,0,[],""],["rm_t4-n6680",2,"Rodando va el dinero;\nPero de modo\nQue, como va de prisa,\nSe escapa pronto.\nY en ocasiones,\nMuchos echan la mano,\nCaen y no cogen.",2,0,-1,14,"",4,7,"oe",-1,0,-1,0,212,212,"6680","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6681",2,"Yo no sé cómo vives\nTan sosegado,\nDebiendo lo que tienes\nY sin pagarlo.\nBien se evidencia\nQue duermen los tramposos\nA pierna suelta.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,212,212,"6681","",0,"","","",1,0,0,[],""],["rm_t4-n6682",2,"De tus apuros quieres\nQue yo te saque;\nPara meterte en ellos\nNo me buscaste.\nLa deuda, advierte\nQue no es justo la pague\nQuien no la debe.",2,0,-1,14,"",4,7,"ee",-1,0,-1,0,212,212,"6682","",0,"","","",1,0,0,[],""],["rm_t4-n6683",2,"Déjate de andar siempre\nBuscando enredos;\nDesata los que tienes,\nSi alcanza el tiempo.\nPues tus marañas,\nAunque mil años vivas,\nNo las aclaras.",2,0,-1,14,"",4,7,"aa",-1,0,-1,0,213,213,"6683","",0,"","","",1,0,0,[],""],["rm_t4-n6684",2,"Nunca pidas, nunca debas,\nNunca á nádie le hagas mal,\nSiempre mira, siempre calla.\nY las gracias me darás.",2,0,-1,14,"",0,4,"a",-1,0,-1,0,213,213,"6684","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n6685",2,"En tu vida de nádie\nDádivas tomes,\nY con éso te excusas\nDe obligaciones.",2,0,-1,14,"",6,4,"oe",-1,0,-1,0,213,213,"6685","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t4-n6686",2,"Al hombre los trabajos\nLe hacen humilde;\nMas las prosperidades\nSiempre le engríen.\nPues la riqueza\nRara vez se separa\nDe la soberbia.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,213,213,"6686","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6690",2,"El hombre más dichoso\nQue hay en el mundo\nEs el que no desea\nBienes algunos.\nPues todos ellos,\nSi cuesta el adquirirlos,\nDuele el perderlos.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,214,214,"6690","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6691",2,"Gran fortuna no quieras\nEn esta vida;\nPorque en ella los ojos\nPone la envidia.\nHuye de honores,\nSi quieres vivir libre\nDe emulaciones.",2,0,-1,14,"",4,7,"oe",-1,0,-1,0,214,214,"6691","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6692",2,"De lo colorado sale\nLa flor de la alcaparrera; (?)\nSi la envidia fuera tiña,\n¡Cuántos tiñosos hubiera!",2,0,-1,14,"",0,4,"ea",44,0,-1,0,214,215,"6692","",0,"","","",1,0,0,[],""],["rm_t4-n6693",2,"Lo que no tiene el hombre\nSiempre desea;\nPero así que lo logra,\nYa lo desprecia.\nÉsto ver hace\nQue los bienes terrenos\nNo satisfacen.",2,0,-1,14,"",4,7,"ae",-1,0,-1,0,215,215,"6693","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6694",2,"De los bienes que he perdido,\nCuando me llego á acordar,\nPor un lado, me da pena;\nPor otro, gusto me da.",2,0,-1,14,"",0,4,"a",-1,0,-1,0,215,215,"6694","",0,"","","",1,0,0,[],""],["rm_t4-n6695",2,"Si los honores mudan\nNuestras costumbres,\nVáyanse los honores;\nVengan virtudes.\nPorque sin ellas,\nLas pompas de este mundo\nSon muy funestas.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,215,215,"6695","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6696",2,"No dejes la inocencia,\nQue es buena amiga,\nY luégo has de echar ménos\nSu compañía.\nPorque es tan buena,\nQue hasta sus enemigos\nHablan bien de ella.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,215,215,"6696","",0,"","","",2,0,0,[],""],["rm_t4-n6697",2,"A una cabra inocente\nLa robó un lobo,\nY el cabrero, dormido,\nNo sintió el robo.\n¡Bien empleado!\n¿Quién le manda al cabrero\nSer descuidado?",2,0,-1,14,"",4,7,"ao",14,0,-1,0,215,216,"6697","",0,"","","",1,0,0,[],""],["rm_t4-n6698",2,"Para bailes y fiestas\nSiempre estás lista;\nPero muy perezosa\nPara ir á misa.\n¡Fuerte desgracia\nEs dejar lo que anima\nPor lo que mata!",2,0,-1,14,"",4,7,"aa",-1,0,-1,0,216,216,"6698","",0,"","","",2,0,0,[],""],["rm_t4-n6699",2,"Camina á paso largo;\nQue eres muy lerda,\nNó cuando vas al baile,\nSino á la iglesia.\nNo te descuides;\nQue te cuentan los pasos\nLos alguaciles.",2,0,-1,14,"",4,7,"ie",-1,0,-1,0,216,216,"6699","",0,"","","",1,0,0,[],""],["rm_t4-n6700",2,"Tus piés son muy ligeros\nPara la bulla,\nY tus dedos muy torpes\nPara la aguja.\n¡Fuerte desgracia\nEs tener ligereza\nMal colocada!",2,0,-1,14,"",4,7,"aa",-1,0,-1,0,216,216,"6700","",0,"","","",2,0,0,[],""],["rm_t4-n6701",2,"¿Sabes lo que consigues\nCon tus meneos?\nQue te miren los hombres\nCon menosprecio.\nSé más compuesta,\nQue son muy despreciables\nLas desenvueltas.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,216,217,"6701","",0,"","","",1,0,0,[],""],["rm_t4-n6702",2,"Con esas cruces, niña,\nQue traes al cuello,\nNi apartas á los malos,\nNi atraes los buenos.\nY ésto depende\nDe que fuera del pecho\nSiempre las tienes.",2,0,-1,14,"",4,7,"ee",-1,0,-1,0,217,217,"6702","",0,"","","",1,0,0,[],""],["rm_t4-n6703",2,"Nunca en secreto hagas\nAcciones tales,\nQue en público no puedan\nManifestarse.\nPues así logras\nQue salgan uniformes\nTodas tus obras.",2,0,-1,14,"",4,7,"oa",-1,0,-1,0,217,217,"6703","",0,"","","",1,0,0,[],""],["rm_t4-n6704",2,"No arrojes la cadena\nDe tus deberes,\nPues aunque pese mucho,\nLlevarla puedes.\nY si lo miras,\nHallarás que no pesa\nLo que imaginas.",2,0,-1,14,"",4,7,"ia",-1,0,-1,0,217,217,"6704","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6705",2,"Si cuesta repugnancia\nSer obediente,\nComo obediente seas,\nMérito tienes.\nQue es cosa cierta\nQue el mérito se alcanza\nCon la obediencia.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,217,217,"6705","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6706",2,"No corran tus acciones\nTras de la fama;\nDeja que ésta las busque\nPara ensalzarlas.\nPorque es bien cierto\nQue quien mendiga aplausos\nCoge desprecios.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,218,218,"6706","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6707",2,"Sé modesta, si aspiras,\nNiña, á casarte,\nNo sólo en la conducta,\nSino en el traje.\nQue por la muestra\nEl género se infiere\nQue hay en la tienda.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,218,218,"6707","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6708",2,"Al paño fino en la tienda\nUna mancha le cayó,\nY se vende más barato\nPorque perdió su valor.",2,0,-1,14,"",0,4,"o",-1,0,-1,0,218,218,"6708","",0,"","","",1,0,0,[],""],["rm_t4-n6709",2,"En el cielo no hay faroles;\nQue todas son estrellitas;\n¡Qué bien parece, señores,\nLa honestidá en las mocitas\n[Y la razon en los hombres]!",2,0,-1,14,"",7,5,"oe",-1,0,-1,0,218,218,"6709","",0,"","","",2,0,0,[],""],["rm_t4-n6710",2,"Tan delicada eres\nComo un espejo,\nQue para que se empañe\nBasta el aliento.\nSíguelo en todo,\nPues el honor fué siempre\nMuy vidrïoso.",2,0,-1,14,"",4,7,"oo",-1,0,-1,0,218,218,"6710","",0,"","","",1,0,0,[],""],["rm_t4-n6711",2,"El honor y los ojos\nBien se parecen,\nPues con cualquiera sombra\nSe les ofende.\nY así, advertida,\nSi el honor guardar quieres,\nGuarda la vista.",2,0,-1,14,"",4,7,"ia",-1,0,-1,0,219,219,"6711","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6712",2,"Guarda con gran cuidado\nTu honor, señora,\nQue es vidrio y si se rompe\nYa no se solda.\nVéte con tiento,\nPorque el vidrio se empaña\nCon el aliento.",2,0,-1,14,"",4,7,"eo",94,0,-1,0,219,219,"6712","",0,"","","",1,0,0,[],""],["rm_t4-n6716",2,"Cuando gentil Lucrecia\nSe dió la muerte\nPor verse deshonrada,\n¡Terrible suerte!\nAsí decía:\n—Quien no ha de vivir casta,\nNo es bien que viva.",2,0,-1,14,"",4,7,"ia",-1,0,-1,0,219,220,"6716","",0,"","","",1,0,0,[],""],["rm_t4-n6718",2,"A tus hijos no muestres\nRostro severo,\nQue el amor se conquista\nCon el afecto.\nY ya ganado,\nLograrás corregirlos\nSin espantarlos.",2,0,-1,14,"",4,7,"ao",-1,0,-1,0,220,220,"6718","",0,"","","",1,0,0,[],""],["rm_t4-n6719",2,"Espera de tus hijos\nCuando seas viejo\nLo mismo que á tus padres\nLes hayas hecho.\nPorque esta deuda\nLos hijos dejan siempre\nBien satisfecha.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,220,220,"6719","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6720",2,"Nunca el hijo se vuelva\nContra su padre,\nPues debe, aunque sea malo,\nReverenciarle.\nPorque así logra\nQue sus hijos le traten\nEn igual forma.",2,0,-1,14,"",4,7,"oa",-1,0,-1,0,220,221,"6720","",0,"","","",1,0,0,[],""],["rm_t4-n6722",2,"De padres á padrastros\nHay cuatro leguas;\nDe madres á madrastras\nHay cuatrocientas.",2,0,-1,14,"",6,4,"ea",-1,0,-1,0,221,221,"6722","",0,"","","",1,0,0,[],""],["rm_t4-n6723",2,"Escupistes contra er sielo\nY Undebé te castigó;\nAr que contra er sielo escupe,\nTamien lo castiga Dios.",2,0,-1,14,"",0,4,"o",-1,0,-1,0,221,221,"6723","",0,"","","",1,0,0,[],""],["rm_t4-n6724",2,"Tú merecias que Dios,\nPor su Providencia justa,\nNo te dejara llegar\nA la edad de que te burlas.",2,0,-1,14,"",0,4,"ua",-1,0,-1,0,221,221,"6724","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6727",2,"Antes de que ejecutes\nDebes bien pensar;\nPorque luégo las obras\nSe corrigen mal.",2,0,-1,14,"",0,4,"a",-1,0,-1,0,222,222,"6727","",0,"","","",1,0,0,[],""],["rm_t4-n6728",2,"Procura reflexionar\nLo que puede suceder,\nPorque es mejor precaver\nQue tener que remediar.",2,0,-1,14,"",11,4,"a",21,0,-1,0,222,222,"6728","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n6730",2,"Males que el tiempo acarrea,\n¡Quién pudiera penetrarlos,\nPara poner el remedio\nAntes que viniera el daño!",2,0,-1,14,"",0,4,"ao",-1,0,-1,0,222,222,"6730","",0,"","","",3,0,0,[],""],["rm_t4-n6731",2,"Registra bien el campo,\nSabio general;\nExamina el peligro,\nAntes de avanzar.\nQue los avances\nSuelen ser peligrosos\nEn ciertos lances.",2,0,-1,14,"",4,7,"ae",277,0,-1,0,222,222,"6731","",0,"","","",1,0,0,[],""],["rm_t4-n6732",2,"La escalera de la vida\nHay que subirla despacio;\nEl que de prisa la sube\nNo llega al segundo tramo.",2,0,-1,14,"",0,4,"ao",-1,0,-1,0,222,222,"6732","",0,"","","",2,0,0,[],""],["rm_t4-n6733",2,"Quien camina de prisa\nPoco adelanta;\nQue nada se hace bueno\nCon prisa tanta.\nPues se ha notado\nQue el que va más de prisa\nVa más despacio.",2,0,-1,14,"",4,7,"ao",-1,0,-1,0,223,223,"6733","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6735",2,"Sólo los necios viven\nMuy confiados;\nQue el que es discreto, siempre\nVa con cuidado.\nTén, pues, sabido\nQue todo el que confia\nSe ve perdido.",2,0,-1,14,"",4,7,"io",101,0,-1,0,223,223,"6735","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6738",2,"Si de nada te sirven\nLos escarmientos,\nEres mujer sin juicio\nNi entendimiento.\nQue hasta los asnos,\nEn tropezando, quedan\nEscarmentados.",2,0,-1,14,"",4,7,"ao",-1,0,-1,0,224,224,"6738","",0,"","","",1,0,0,[],""],["rm_t4-n6739",2,"Muy mal paga el aviso\nDel escarmiento\nQuien, pasado el naufragio,\nVuelve á su riesgo.\nCuando perezca,\nSerá de un temerario\nJusta la pena.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,224,224,"6739","",0,"","","",1,0,0,[],""],["rm_t4-n6740",2,"Ya me boy desengañando\nLo que da er mundo de sí;\nAquer qu' alante no mira\nNunca puê tener güen fin.",2,0,-1,14,"",0,4,"i",-1,0,-1,0,224,224,"6740","",0,"","","",1,0,0,[],""],["rm_t4-n6741",2,"En este mundo reondo\nQuien mar anda, mar acaba;\nY en casa der jabonero\nEr que no cae, resbala.",2,0,-1,14,"",0,4,"aa",-1,0,-1,0,224,224,"6741","",0,"","","",1,0,0,[],""],["rm_t4-n6742",2,"El que siembra alcachofas,\nEspinas coge;\nY el que cria colmenas,\nLa miel se come.",2,0,-1,14,"",6,4,"oe",-1,0,-1,0,224,225,"6742","",0,"rm_t3","","",3,0,0,[],""],["rm_t4-n6745",2,"Nádie siegue en tierra ajena,\nPorque á mí me sucedió\nQue estando en ella segando,\nVino el guarda y me cogió.",2,0,-1,14,"",0,4,"o",2,0,-1,0,225,225,"6745","",0,"","","",1,0,0,[],""],["rm_t4-n6746",2,"Arbol que no da fruto,\nFuera al instante;\nQue suelen sus raíces\nCausar mil males.",2,0,-1,14,"",6,4,"ae",-1,0,-1,0,225,225,"6746","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6747",2,"Nunca compres mula coja,\nPensando que sanará;\nPues si las sanas cojean,\nLas cojas, ¿qué es lo que harán?",2,0,-1,14,"",0,4,"a",-1,0,-1,0,225,225,"6747","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n6748",2,"No adelantes el discurso\nSino para pensar bien;\nPoi que á veces discurrimos\nLo que no ha sido ni es.",2,0,-1,14,"",0,4,"e",-1,0,-1,0,225,225,"6748","",0,"","","",4,0,0,[],""],["rm_t4-n6749",2,"Jamás tú te disculpes\nSi no te culpan,\nPues das de culpa indicio\nCon tu disculpa.\nQue la inocencia,\nElla misma, áun callando,\nSe manifiesta.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,226,226,"6749","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6750",2,"Dios nos libre de chismes\nY horas menguadas,\nPero principalmente\nDel agua mansa,\nCuyos estragos\nSon más irremediables\nCuanto más tardos.",2,0,-1,14,"",4,7,"ao",-1,0,-1,0,226,226,"6750","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6752",2,"Las malas compañías\nSon una peste\nQue sólo con el trato\nSe pega siempre.\nHuye, pues, de ellas,\nQue es el único medio\nDe precaverlas.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,226,226,"6752","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6753",2,"Ocúpate si quieres\nVivir contento,\nQue á los desocupados\nPersigue el tedio.\nFuera pereza,\nSi quieres verte libre\nDe esta dolencia.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,226,227,"6753","",0,"","","",1,0,0,[],""],["rm_t4-n6757",2,"Si un matrimonio riñe,\nNo metas paces;\nQuien armó la pendencia\nQue la desarme.\nQue en tales riñas,\nCon lo que al uno amansas\nAl otro irritas.",2,0,-1,14,"",4,7,"ia",-1,0,-1,0,227,227,"6757","",0,"","","",2,0,0,[],""],["rm_t4-n6758",2,"En mi casa hay un libro;\nDice á la letra:\n«En cuidados ajenos\nNádie se meta.»",2,0,-1,14,"",6,4,"ea",-1,0,-1,0,227,228,"6758","",0,"","","",3,0,0,[],""],["rm_t4-n6759",2,"En ajenos negocios\nNunca te mezcles,\nSi tus obligaciones\nNo lo exigieren.\nPorque es un necio\nEl que olvida los suyos\nPor los ajenos.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,228,228,"6759","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6760",2,"En materia de gustos\nNádie dispute;\nPues para ser de gusto\nBasta que guste.",2,0,-1,14,"",6,4,"ue",-1,0,-1,0,228,228,"6760","",0,"","","",1,0,0,[],""],["rm_t4-n6761",2,"Qué cosa sea el gusto\nNádie lo sabe,\nNi de dónde depende,\nNi de qué nace.\nPero se advierte\nQue se quiere por gusto\nLo que se quiere.",2,0,-1,14,"",4,7,"ee",-1,0,-1,0,228,228,"6761","",0,"","","",1,0,0,[],""],["rm_t4-n6763",2,"La soberbia que tuvo\nEl vano Absalon\nDe las ramas de un árbol\nColgada quedó.\nY sucedió así\nPor haber destronado\nAl gran rey David.",2,0,-1,14,"",4,7,"i",-1,0,-1,0,228,229,"6763","",0,"","","",1,0,0,[],""],["rm_t4-n6764",2,"Amán disimulado\nSufrió el sonrojo\nDe ver á su enemigo\nPuesto en el trono.\nEso le pasa\nA todo aquel que quiere\nTomar venganza.",2,0,-1,14,"",4,7,"aa",-1,0,-1,0,229,229,"6764","",0,"","","",1,0,0,[],""],["rm_t4-n6765",2,"Nunca podrás vengarte\nDe tu enemigo,\nPorque el mayor que tienes\nEres tú mismo.\nPues es notorio\nQue la venganza es hija\nDel amor propio.",2,0,-1,14,"",4,7,"oo",-1,0,-1,0,229,229,"6765","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6766",2,"La lumbre y las discordias\nSon dos hermanas,\nQue, si á encenderse llegan,\nTarde se apagan.\nY así, es preciso\nPara evitar el fuego\nSufrir el frio.",2,0,-1,14,"",4,7,"o",-1,0,-1,0,229,229,"6766","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6767",2,"Es lo peor de un pleito\nLos abogados;\nQue, áun perdiendo, ellos ganan\nLo que han robado.\nY al que lo gana\nLe dejan con justicia;\nPero sin blanca.",2,0,-1,14,"",4,7,"aa",-1,0,-1,0,229,230,"6767","",0,"","","",2,0,0,[],""],["rm_t4-n6768",2,"Los pleitos y las sangrías\nLo mismo vienen á ser;\nEvítalos cuanto puedas,\nSi no quieres padecer.",2,0,-1,14,"",0,4,"e",20,0,-1,0,230,230,"6768","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6769",2,"La libertad y salud\nSon prendas de gran valía;\nNinguno lo reconoce\nHasta que las ve perdidas.",2,0,-1,14,"",0,4,"ia",-1,0,-1,0,230,230,"6769","",0,"","","",3,0,0,[],""],["rm_t4-n6770",2,"Nunca acostumbres tu cuerpo\nA lo que no es menester,\nPues es una enfermedad\nCada vicio que le des.",2,0,-1,14,"",0,4,"e",-1,0,-1,0,230,230,"6770","",0,"","","",3,0,0,[],""],["rm_t4-n6771",2,"Las cuatro más necesarias\nUrgencias del hombre son,\nA mi corto parecer,\nHambre, sueño, sed y amor.",2,0,-1,14,"",0,4,"o",-1,0,-1,0,230,230,"6771","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6772",2,"Toma el huevo de una hora;\nEl pan de aquel mismo dia;\nEl vino que tenga un año\nY algo ménos la gallina.",2,0,-1,14,"",0,4,"ia",-1,0,-1,0,230,230,"6772","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6773",2,"Tabaco, vino y mujer\nMatan á la juventud;\nY en usándolos con regla,\nSon para el hombre salud.",2,0,-1,14,"",0,4,"u",278,0,-1,0,230,230,"6773","",0,"","","",1,0,0,[],""],["rm_t4-n6774",2,"En la tierra de los lobos,\nDonde no hay zorra ninguna,\nEl que con vino se acuesta,\nCon agua se desayuna.",2,0,-1,14,"",0,4,"ua",56,0,-1,0,231,231,"6774","",0,"","","",1,0,0,[],""],["rm_t4-n6775",2,"Si vieres á un tuerto bueno,\nEscríbelo por milagro;\nHazle la cruz á los cojos\nY no fíes de los calvos.",2,0,-1,14,"",0,4,"ao",-1,0,-1,0,231,231,"6775","",0,"","","",1,0,0,[],""],["rm_t4-n6776",2,"Busca el pobre su acomodo;\nBusca el borracho el cristal;\nEl jugador su tesoro\nY el ladrón donde robar.",2,0,-1,14,"",0,4,"a",-1,0,-1,0,231,231,"6776","",0,"","","",3,0,0,[],""],["rm_t4-n6777",2,"Nádie ponga su viña\nJunto á un camino,\nPorque todo el que pasa\nCorta un racimo.\nY de este modo\nSe la van vendimiando\nSin saber cómo.",2,0,-1,14,"",4,7,"oo",-1,0,-1,0,231,231,"6777","",0,"","","",3,0,0,[],""],["rm_t4-n6778",2,"Por grande que sea una viña\nY mucho fruto que dé,\nEn teniendo muchos amos,\nA poco podrán caber.",2,0,-1,14,"",0,4,"e",-1,0,-1,0,231,231,"6778","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6779",2,"Cántaro que á la fuente\nVa y viene mucho,\nQue salga con victoria\nLo dificulto.",2,0,-1,14,"",6,4,"uo",-1,0,-1,0,231,231,"6779","",0,"rm_t3, palau_cantares","","",3,0,0,[],""],["rm_t4-n6780",2,"Si en el mundo no hubiera\nQuien observara,\nMás de cuatro personas\nNo se enmendaran.\nQue muchos temen\nMás el juicio del mundo\nQue el de la muerte.",2,0,-1,14,"",4,7,"ee",-1,0,-1,0,231,232,"6780","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6784",2,"Un loquito del hospicio\nMe dijo en cierta ocasion:\nNi son todos los que están,\nNi están todos los que son.",2,0,-1,14,"",0,4,"o",31,0,-1,0,232,232,"6784","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t4-n6785",2,"El que quiera ser dichoso\nDos cosas ha de tener:\nLa conciencia muy tranquila\nY el amor de una mujer.",2,0,-1,14,"",0,4,"e",20,0,-1,0,233,233,"6785","",0,"","","",1,0,0,[],""],["rm_t4-n6786",2,"Si quieres que viva mucho,\nPídele á Dios que me muera;\nPorque siempre vive mucho\nA quien la muerte desean.",2,0,-1,14,"",0,4,"ea",-1,0,-1,0,233,233,"6786","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t4-n6787",2,"Le pueden quitar al rey\nSu corona y sus estados;\nPero no pueden quitarle\nLa gloria de haber reinado.",2,0,-1,14,"",0,4,"ao",-1,0,-1,0,233,233,"6787","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6788",2,"Aquel que se pasa al moro\nPor su propia voluntad\nY no procura rescate,\nEs que quiso renegar.",2,0,-1,14,"",0,4,"a",-1,0,-1,0,233,233,"6788","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6789",2,"Entre mi oficial y yo\nHicimos este retablo:\nSi está bueno lo hice yo,\nY mi oficial si está malo.",2,0,-1,14,"",0,4,"ao",-1,0,-1,0,233,233,"6789","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n6790",2,"Molino que estás moliendo\nEl trigo con tanto afan,\nTú estás haciendo la harina\nY otros se comen el pan.",2,0,-1,14,"",0,4,"a",147,0,-1,0,233,233,"6790","",0,"carrizo_salta, palau_cantares, andina_t2, lafuente_madrid","","",5,0,0,[],""],["rm_t4-n6791",2,"Unos cogen las mimbres,\nOtros las pelan,\nOtros hacen los cestos,\nY otros los llevan.",2,0,-1,14,"",6,4,"ea",-1,0,-1,0,233,233,"6791","",0,"","","",1,0,0,[],""],["rm_t4-n6792",2,"Lo han dicho varios autores,\nY entre ellos San Agustin:\nDonde no ha habido principio\nImposible es que haya fin.",2,0,-1,14,"",0,4,"i",211,0,-1,0,234,234,"6792","",0,"","","",1,0,0,[],""],["rm_t4-n6796",2,"El que bebe, se emborracha;\nEl que no jura, reniega;\nA aquel que se va, lo olvidan;\nY al que se muere, lo entierran.",2,0,-1,14,"",0,4,"ea",-1,0,-1,0,234,234,"6796","",0,"","","",1,0,0,[],""],["rm_t4-n6797",2,"Quien mal masca; mal digiere;\nQuien mal habla, mal persuade;\nQuien mal tose, mal escupe;\nQuien mal concibe, mal pare.",2,0,-1,14,"",0,4,"ae",-1,0,-1,0,234,234,"6797","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6799",2,"El castillito más fuerte,\nSi no le ponen puntales,\nSerá fácil que se caiga,\nA fuerza de temporales.",2,0,-1,14,"",0,4,"ae",26,0,-1,0,235,235,"6799","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6802",2,"La esperanza es un árbol\nEl más frondoso,\nY de sus bellas ramas\nDependen todos.",2,0,-1,14,"",6,4,"oo",-1,0,-1,0,235,235,"6802","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6803",2,"Er qu' espera, desespera;\nY ei que no espera, no arcansa;\nPor éso es bueno esperar,\nPara tener esperansa.",2,0,-1,14,"",0,4,"aa",177,0,-1,0,235,235,"6803","",0,"","","",1,0,0,[],""],["rm_t4-n6804",2,"La esperanza es el sueño\nDel desvelado\nY si este sueño pierde,\nPierde el descanso.\nQue el hombre vive\nDormido en la esperanza\nMientras existe.",2,0,-1,14,"",4,7,"ie",-1,0,-1,0,235,235,"6804","",0,"","","",1,0,0,[],""],["rm_t4-n6805",2,"Nace con la esperanza\nNuevo deseo,\nPues se acrecienta el daño\nCon el remedio.\nRemedio pronto\nSana en parte al enfermo,\nSi nó en el todo.",2,0,-1,14,"",4,7,"oo",-1,0,-1,0,235,236,"6805","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6807",2,"En el campo del mundo\nFlor es el alma,\nQue alimenta el rocío\nDe la esperanza.\nEspera, niña;\nConservarás el alma\nSiempre tranquila.",2,0,-1,14,"",4,7,"ia",-1,0,-1,0,236,236,"6807","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6808",2,"Como las esperanzas\nSon los laureles;\nQue sin dar fruto á nádie,\nSiempre están verdes.\nY en su verdura\nSe mantienen los bobos,\nPor lo que dura.",2,0,-1,14,"",4,7,"ua",17,0,-1,0,236,236,"6808","",0,"","","",3,0,0,[],""],["rm_t4-n6809",2,"Para buscar la dicha,\nValor constante;\nNunca se escribió nada\nDe los cobardes.\nPues hay fortunas\nQue no pueden hallarse\nSi no se buscan.",2,0,-1,14,"",4,7,"ua",-1,0,-1,0,236,237,"6809","",0,"","","",1,0,0,[],""],["rm_t4-n6810",2,"Si piensas de aburrido\nDesesperarte,\nSabe que te acreditas\nDe muy cobarde.\nQue está lo fuerte\nEn sufrir las desgracias\nCon rostro alegre.",2,0,-1,14,"",4,7,"ee",-1,0,-1,0,237,237,"6810","",0,"","","",2,0,0,[],""],["rm_t4-n6811",2,"Aquel que empieza una obra\nRazon será que la acabe,\nPara que nunca se diga\nQue la dejó por cobarde.",2,0,-1,14,"",0,4,"ae",-1,0,-1,0,237,237,"6811","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n6812",2,"El que vence un imposible\nDos coronas tiene iguales:\nEl salirse con su gusto\nY el vencer dificultades.",2,0,-1,14,"",0,4,"ae",-1,0,-1,0,237,237,"6812","",0,"","","",1,0,0,[],""],["rm_t4-n6813",2,"Corason, arriba, arriba,\nY si te cansas, descansa;\nQue las cosas d' este mundo,\nPasando tiempo s' arcansan.",2,0,-1,14,"",0,4,"aa",-1,0,-1,0,237,237,"6813","",0,"","","",1,0,0,[],""],["rm_t4-n6815",2,"Que mucho hayas llamado\nLo dificulto;\nPues pobre porfiado\nSaca mendrugo.\nY si te cansas,\nDe conseguirlo pierdes\nLas esperanzas.",2,0,-1,14,"",4,7,"aa",110,0,-1,0,237,238,"6815","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6817",2,"El que siendo dichoso\nDeja de serlo,\nEn su misma memoria\nLleva el tormento.\nPorque su pena,\nAl querer olvidarla,\nMás se le acuerda.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,238,238,"6817","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6818",2,"No hay tormento más grande\nQue la memoria,\nPorque pone presentes\nPasadas glorias.",2,0,-1,14,"",6,4,"oa",-1,0,-1,0,238,238,"6818","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6819",2,"De las potencias del alma\nLa memoria es la crüel,\nPorque causa el mayor mal\nRecordando el mayor bien.",2,0,-1,14,"",0,4,"e",-1,0,-1,0,238,238,"6819","",0,"","","",5,0,0,[],""],["rm_t4-n6820",2,"Er que bino siego ar mundo\nSin la esperansa de ber\nNo tiene tanta peniya\nComo er qu' ha bisto y no be.",2,0,-1,14,"",3,4,"e",-1,0,-1,0,238,238,"6820","",0,"","","",1,0,0,[],""],["rm_t4-n6821",2,"En la puerta de un molino\nMe puse á considerar\nLas vueltas que ha dado el mundo,\nY las que tiene que dar.",2,0,-1,14,"",0,4,"a",21,0,-1,0,238,239,"6821","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t4-n6822",2,"Nada contiene el mundo\nQue sea durable,\nExcepto la inconstancia,\nQue es la constante.\nSigue esta regla\nY no hallarás errada\nJamás tu cuenta.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,239,239,"6822","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6823",2,"Las glorias de este mundo\nSon transitorias,\nPues duran mientras pasan\nPor la memoria.",2,0,-1,14,"",6,4,"oa",-1,0,-1,0,239,239,"6823","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6824",2,"Por cosas de este mundo\nNunca te apures;\nQue no hay bien que no acabe\nNi mal que dure.",2,0,-1,14,"",6,4,"ue",-1,0,-1,0,239,239,"6824","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6825",2,"No hay cosa en este mundo\nQue no se mude;\nEl que hoy está abatido,\nMañana sube.\nQue la fortuna,\nComo viene de prisa,\nPronto se muda.",2,0,-1,14,"",4,7,"ua",-1,0,-1,0,239,239,"6825","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6826",2,"Las desgracias que sufres\nNo las extrañes;\nQue componen la vida\nBienes y males.\nYa has disfrutado\nEl buen tiempo; ahora resta\nSufrir el malo.",2,0,-1,14,"",4,7,"ao",-1,0,-1,0,239,240,"6826","",0,"","","",2,0,0,[],""],["rm_t4-n6828",2,"La carrera que llevas\nEs agitada\nY aquel que mucho corre,\nMás presto pára.\nVéte despacio,\nPorque estás ya muy cérca\nDel desengaño.",2,0,-1,14,"",4,7,"ao",-1,0,-1,0,240,240,"6828","",0,"","","",2,0,0,[],""],["rm_t4-n6829",2,"Aunque veas tu nave\nCérca del puerto,\nNo tengas confianza\nSi no estás- dentro.\nPorque en los mares\nSuele haber de improviso\nMil tempestades.",2,0,-1,14,"",4,7,"ae",-1,0,-1,0,240,240,"6829","",0,"","","",1,0,0,[],""],["rm_t4-n6831",2,"Ya pasaste el creciente,\nComo la luna;\nAhora estás en el lleno\nDe la fortuna.\nVéte con tiento;\nCuidado que al menguante\nNo mude el tiempo.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,240,241,"6831","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],""],["rm_t4-n6837",2,"Cuando pasé por aquí,\nCastillo, te ví caido;\nY ahora que vuelvo á pasar,\nTe hallo fortalecido.",2,0,-1,14,"",3,4,"io",101,0,-1,0,241,242,"6837","",0,"","","",1,0,0,[],""],["rm_t4-n6838",2,"Son tantas las marañas\nEn que te metes,\nQue si en ellas te enredas,\nHas de perderte.\nDeja las cimas,\nPorque si te resbalas,\nTe precipitas.",2,0,-1,14,"",4,7,"ia",-1,0,-1,0,242,242,"6838","",0,"","","",1,0,0,[],""],["rm_t4-n6839",2,"Deja los precipicios\nPor donde andas;\nMira que es más segura\nLa tierra llana.\nDeja tropiezos,\nPara no arrepentirte\nFuera de tiempo.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,242,242,"6839","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6840",2,"Desciende de esa cumbre,\nNiña, al instante,\nQue no baja el que baja,\nSino el que cae.\nBaja al momento,\nPorque sólo en los valles\nVive el sosiego.",2,0,-1,14,"",4,7,"eo",-1,0,-1,0,242,242,"6840","",0,"","","",1,0,0,[],""],["rm_t4-n6841",2,"La fortuna no envidies\nDe quien se eleva,\nPues siempre las alturas\nSon muy expuestas.\nY en tal peligro,\nLa más leve caida\nVa al precipicio.",2,0,-1,14,"",4,7,"io",-1,0,-1,0,242,242,"6841","",0,"","","",2,0,0,[],""],["rm_t4-n6843",2,"Si la memoria pierdes\nCuando estás alto,\nHaces ver que no vales\nLo que has logrado.\n¡Fortuna loca!\nSiempre eres enemiga\nDe la memoria.",2,0,-1,14,"",4,7,"oa",-1,0,-1,0,243,243,"6843","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6844",2,"Ya lograste la silla\nQue deseabas;\nTen cuidado con ella,\nMira no caigas.\nQue estando en alto,\nDarás si te cayeres\nMayor porrazo.",2,0,-1,14,"",4,7,"ao",-1,0,-1,0,243,243,"6844","",0,"","","",1,0,0,[],""],["rm_t4-n6845",2,"Aquel que más alto sube,\nMás grande porrazo da;\n¡Mira la puente de Arcos\nEn lo que vino á parar!",2,0,-1,14,"",0,4,"a",-1,0,-1,0,243,243,"6845","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",6,0,0,[],""],["rm_t4-n6847",2,"Yo bebí del agua clara\nY bebiendo la enturbié;\nNinguno puede decir\n«De este agua no beberé.»",2,0,-1,14,"",0,4,"e",77,0,-1,0,243,244,"6847","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6849",2,"Aunque lo mires ajado,\nNo desprecies el laurel;\nQue algún dia fué buen árbol\nY puede reverdecer.",2,0,-1,14,"",0,4,"e",-1,0,-1,0,244,244,"6849","",0,"","","",2,0,0,[],""],["rm_t4-n6850",2,"Si porque me ves caido\nMe señalas con el pié,\nPiensa que soy hombre y puedo\nVolver á prevalecer.",2,0,-1,14,"",0,4,"e",-1,0,-1,0,244,244,"6850","",0,"","","",4,0,0,[],""],["rm_t4-n6851",2,"Si de mis males te alegras,\nRuégale á Dios por salud;\nQue puede ser que algún dia\nMe ría yo y llores tú.",2,0,-1,14,"",0,4,"u",-1,0,-1,0,244,244,"6851","",0,"","","",2,0,0,[],""],["rm_t4-n6852",2,"Tanto valor tiene el pobre\nComo el que tiene caudal:\n¡A cuántos ricos se han visto\nDe puerta en puerta llegar!",2,0,-1,14,"",0,4,"a",-1,0,-1,0,244,244,"6852","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6853",2,"Dale la mano al caido\nY ayúdale á levantar;\nMira que estás en el mundo\nY algun dia tú caerás.",2,0,-1,14,"",0,4,"a",-1,0,-1,0,244,244,"6853","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6855",2,"No por muy rico que seas,\nArrolles al infeliz:\nYo he visto títulos grandes\nDe puerta en puerta pedir.",2,0,-1,14,"",0,4,"i",-1,0,-1,0,245,245,"6855","",0,"","","",1,0,0,[],""],["rm_t4-n6856",2,"Si quieres subir al cielo,\nTienes que subir bajando,\nHasta llegar al que sufre\nY darle al pobre la mano.",2,0,-1,14,"",0,4,"ao",-1,0,-1,0,245,245,"6856","",0,"","","",1,0,0,[],""],["rm_t4-n6857",2,"Muy arta bí yo subir\nUn águila palomera,\nY luégo la bí bajar\nMás humirde que la tierra.",2,0,-1,14,"",0,4,"ea",-1,0,-1,0,245,245,"6857","",0,"","","",1,0,0,[],""],["rm_t4-n6858",2,"' Aquer pajarito, madre,\nQue canta en er limon berde,\nSu dia l' ha de yegar\nQu' él esté triste y yo alegre.",2,0,-1,14,"",3,4,"ee",-1,0,-1,0,245,245,"6858","",0,"","","",1,0,0,[],""],["rm_t4-n6859",2,"Pajarito gilguero,\nNo cantes tanto,\nNo sea que la risa\nSe vuelva llanto.",2,0,-1,14,"",6,4,"ao",30,0,-1,0,245,245,"6859","",0,"","","",1,0,0,[],""],["rm_t4-n6860",2,"Desgraciada tortolilla,\nQue de todas aguas bebes,\nMira no bebas de alguna\nQue la corriente te lleve.",2,0,-1,14,"",0,4,"ee",-1,0,-1,0,245,245,"6860","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6861",2,"Fuentecilla, no corras\nTan fugitiva;\nCuanto más te apresures,\nMás te aniquilas.\nPues no reparas\nQue tu vida la dejas\nDesamparada.",2,0,-1,14,"",4,7,"aa",-1,0,-1,0,245,245,"6861","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6865",2,"Como la infeliz rosa\nEs la hermosura,\nQue complace y alegra\nMientras que dura.\nY estando ajada,\nPasa del pecho al suelo\nLa desdichada.",2,0,-1,14,"",4,7,"aa",49,0,-1,0,246,246,"6865","",0,"","","",1,0,0,[],""],["rm_t4-n6866",2,"Tôs los hombres cuando nasen\nTraen un letrero en la frente\nCon letras de fuego escrito,\nQue disen: «reo de muerte.»",2,0,-1,14,"",0,4,"ee",-1,0,-1,0,246,246,"6866","",0,"","","",1,0,0,[],""],["rm_t4-n6868",2,"Sufre si quieres\ngozar;\nBaja si quieres subir;\nPierde si quieres ganar;\nMuere si quieres vivir.",2,0,-1,14,"",7,5,"i",157,0,-1,0,247,247,"6868","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",1,0,0,[],""],["rm_t4-n6869",2,"No hay plazo que no se cumpla,\nNi deuda que no se pague,\nNi mal que dure cien años,\nNi un enfermo que lo aguante.",2,0,-1,14,"",0,4,"ae",-1,0,-1,0,247,247,"6869","",0,"","","",2,0,0,[],""],["rm_t4-n6870",2,"Todo lo vence el amor;\nTodo el dinero lo allana;\nTodo lo consume el tiempo;\nTodo la muerte lo acaba.",2,0,-1,14,"",0,4,"aa",-1,0,-1,0,247,247,"6870","",0,"rm_t2","","",5,0,0,[],""],["rm_t4-n6871",2,"Ya mi caballo no anda;\nYa mi caballo paró;\nTodo pára en este mundo\nY tambien pararé yo.",2,0,-1,14,"",0,4,"o",2,0,-1,0,247,247,"6871","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6872",2,"Por la senda de la vida\nVamos caminando siempre,\nY al fin y al cabo caemos\nEn el hoyo de la muerte.",2,0,-1,14,"",3,4,"ee",-1,0,-1,0,247,247,"6872","",0,"","","",1,0,0,[],""],["rm_t4-n6873",2,"Camino del cementerio\nSe encontraron dos amigos;\n—¡Adios!—dijo el vivo al muerto;\n—¡Hasta luégo!—el muerto al vivo.",2,0,-1,14,"",0,4,"io",-1,0,-1,0,247,248,"6873","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6875",2,"Cuando doblan las campanas\nNo doblan por los que mueren;\nDoblan por los que están vivos,\nPara que de ellos se acuerden.",2,0,-1,14,"",0,4,"ee",-1,0,-1,0,248,248,"6875","",0,"","","",2,0,0,[],""],["rm_t4-n6876",2,"No sé qué tienen las flores\nQue están en el camposanto,\nQue cuando las mueve el viento,\nParece que están rezando.",2,0,-1,14,"",0,4,"ao",-1,0,-1,0,248,248,"6876","",0,"","","",3,0,0,[],""],["rm_t4-n6877",2,"Mira que el tiempo corre\nRápidamente\nY que el tiempo pasado\nYa no le tienes.\nY así, aprovecha\nLas horas, los instantes\nDel que te queda.",2,0,-1,14,"",4,7,"ea",-1,0,-1,0,248,248,"6877","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6878",2,"La verdad con el tiempo\nFicciones vence;\nQue mejor quitacapas\nNo puede verse.\nY la mentira,\nCon quedar descubierta\nQueda vencida.",2,0,-1,14,"",4,7,"ia",-1,0,-1,0,248,248,"6878","",0,"","","",1,0,0,[],""],["rm_t4-n6879",2,"Dí al tiempo lo que callas,\nQue es el que sólo\nCuando no dice nada\nLo dice todo.\nY se ha notado\nQue hasta males ocultos\nSe han declarado.",2,0,-1,14,"",4,7,"ao",14,0,-1,0,249,249,"6879","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6880",2,"El tiempo y el desengaño\nSon dos amigos leales,\nQue despiertan al que duerme\nY enseñan al que no sabe.",2,0,-1,14,"",0,4,"ae",-1,0,-1,0,249,249,"6880","",0,"palau_cantares, lafuente_madrid, leonesas_diez","","",8,0,0,[],""],["rm_t4-n6881",2,"El tiempo y el desengaño\nSon dos amigos que suelen\nDesengañar engañando\nY despertar al que duerme.",2,0,-1,14,"",0,4,"ee",-1,0,-1,0,249,249,"6881","",0,"","","",8,0,0,[],""],["rm_t4-n6882",2,"Con el tiempo aprenderás\nA saber lo que es el tiempo;\nLo malo es que algunas veces\nViene muy tarde el remedio.",2,0,-1,14,"",0,4,"eo",-1,0,-1,0,249,249,"6882","",0,"","","",1,0,0,[],""],["rm_t4-n6883",2,"No te mates por saber;\nQue el tiempo te enseñará;\nQue no hay cosa más bonita\nQue saber sin preguntar.",2,0,-1,14,"",0,4,"a",-1,0,-1,0,249,249,"6883","",0,"","","",1,0,0,[],""],["rm_t4-n6889",2,"Er libro de la esperiensia\nNo le sirbe al hombre e nâ:\n¡Tiene ar finá la sentensia,\nY nádie yega ar finá!",2,0,-1,14,"",5,4,"a",-1,0,-1,0,250,250,"6889","",0,"","","",2,0,0,[],""],["rm_t4-n6890",2,"Empiezo la primera\nEn nombre de Dios;\nPerderé la vergüenza\nY alzaré la voz.",2,0,-1,15,"",0,4,"o",280,0,-1,0,271,271,"6890","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n6891",2,"No canto por que me escuchen,\nNi porque mi voz es buena;\nCanto por que no se junte\nLa amargura con la pena.",2,0,-1,15,"",0,4,"ea",59,0,-1,0,271,271,"6891","",0,"","","",3,0,0,[],""],["rm_t4-n6892",2,"Yo no canto porque sé,\nNi por que escuchen mi voz;\nCanto por que no se junte\nLa pena con el dolor.",2,0,-1,15,"",0,4,"o",-1,0,-1,0,271,271,"6892","",0,"","","",7,0,0,[],""],["rm_t4-n6893",2,"No canto por que me escuchen,\nNi por que suene mi voz;\nMe lo manda un amiguito\nY no le digo que nó.",2,0,-1,15,"",0,4,"o",-1,0,-1,0,271,271,"6893","",0,"","","",3,0,0,[],""],["rm_t4-n6895",2,"Boy á cantar las coplas\nQue m' han mandao;\nQue no quiero que digan:\n—Malo y rogao.",2,0,-1,15,"",6,4,"ao",98,0,-1,0,272,272,"6895","",0,"","","",1,0,0,[],""],["rm_t4-n6896",2,"Después de mucho escusarme,\nPor no hacerme de rogar,\nHe cantado malagueñas,\nAunque las canto muy mal.",2,0,-1,15,"",0,4,"a",-1,0,-1,0,272,272,"6896","",0,"","","",1,0,0,[],""],["rm_t4-n6897",2,"Si tubiera er pecho claro,\nTe cantara las rondeñas;\nPero como no lo tengo,\nTe canto las malagueñas.",2,0,-1,15,"",0,4,"ea",281,0,-1,0,272,272,"6897","",0,"","","",1,0,0,[],""],["rm_t4-n6900",2,"Si la grasia m' ayudara\nComo m' ayuda er deseo,\nA todo er mundo agradara;\nPero sin grasia, no pueo.",2,0,-1,15,"",1,4,"eo",66,0,-1,0,272,272,"6900","",0,"","","",1,0,0,[],""],["rm_t4-n6901",2,"En el campo nada importa\nCantar bien ó cantar mal;\nMás llegandodonde haygente,\nCantar bien, ó no cantar.",2,0,-1,15,"",0,4,"a",-1,0,-1,0,272,272,"6901","",0,"","","",3,0,0,[],""],["rm_t4-n6902",2,"Seguidillas manchegas\nSon las que canto;\nPorque las de mi tierra\nNo valen tanto.",2,0,-1,15,"",6,4,"ao",30,0,-1,0,273,273,"6902","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6903",2,"No se cantan manchegas\nLas seguidillas,\nPorque á lo valenciano\nSon más bonitas.",2,0,-1,15,"",6,4,"ia",-1,0,-1,0,273,273,"6903","",0,"","","",1,0,0,[],""],["rm_t4-n6904",2,"Copliyas y más copliyas;\nPara mí son escusadas;\nMe he dejado en casa er libro\nY no las traigo apuntadas.",2,0,-1,15,"",0,4,"aa",282,0,-1,0,273,273,"6904","",0,"","","",1,0,0,[],""],["rm_t4-n6905",2,"Cante usté, compañerito;\nCante usté; bamos cantando;\nQue si usté no sabe coplas,\nYo se las iré apuntando.",2,0,-1,15,"",0,4,"ao",33,0,-1,0,273,273,"6905","",0,"","","",1,0,0,[],""],["rm_t4-n6906",2,"Si quieres saber coplas,\nVénte á mi pecho;\nQue se ha vuelto pöeta\nMi pensamiento.",2,0,-1,15,"",6,4,"eo",-1,0,-1,0,273,273,"6906","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6907",2,"Pensaba mi compañero\nQue á coplas me iba á ganar;\n¡Tengo yo una jarda yena\nY un costal por desatar!",2,0,-1,15,"",0,4,"a",21,0,-1,0,273,273,"6907","",0,"","","",1,0,0,[],""],["rm_t4-n6908",2,"Tengo mi cuerpo de coplas,\nQue parese un abispero;\nS' empujan unas á otras,\nPor ber cuár sale primero.",2,0,-1,15,"",0,4,"eo",38,0,-1,0,273,273,"6908","",0,"","","",3,0,0,[],""],["rm_t4-n6909",2,"Si estuviera cantando\nUna semana,\nUna copla dos veces\nNo la cantara.",2,0,-1,15,"",6,4,"aa",-1,0,-1,0,274,274,"6909","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n6910",2,"Del polvo de la tierra\nSaco yo coplas:\nNo bien se acaba una,\nYa tengo otra.",2,0,-1,15,"",6,4,"oa",-1,0,-1,0,274,274,"6910","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n6913",2,"Madre mia del Cármen,\nDarme salero,\nQue el cantar quiere gracia,\nYo no la tengo.",2,0,-1,15,"",6,4,"eo",-1,0,-1,0,274,274,"6913","",0,"","","",2,0,0,[],""],["rm_t4-n6914",2,"Para cantar quiere gracia;\nPara bailar quiere brío;\nPara tocar la guitarra\nQuiere tener buen oïdo.",2,0,-1,15,"",5,4,"oo",-1,0,-1,0,274,275,"6914","",0,"","","",1,0,0,[],""],["rm_t4-n6916",2,"La guitarra sin la prima\nEs como un hijo sin madre;\nTodo er dia se le ba\nSuspirando y dando ayes.",2,0,-1,15,"",0,4,"ae",-1,0,-1,0,275,275,"6916","",0,"","","",2,0,0,[],""],["rm_t4-n6917",2,"Las cuerdas de mi guitarra\nYo te diré cuántas son:\nPrima, segunda y tersera,\nCuarto, quinto y er bordon.",2,0,-1,15,"",0,4,"o",31,0,-1,0,275,275,"6917","",0,"","","",3,0,0,[],""],["rm_t4-n6918",2,"Los gorpes de la guitarra\nSuenan en mi corason;\nLos gorpes de quien la toca:\nLos de la guitarra nó.",2,0,-1,15,"",5,4,"o",-1,0,-1,0,275,275,"6918","",0,"","","",1,0,0,[],""],["rm_t4-n6919",2,"Hasta la guitarra siente\nLos golpes del tocador;\nSiendo madera y lo siente,\n¿Qué será mi corazon?",2,0,-1,15,"",0,4,"o",-1,0,-1,0,275,275,"6919","",0,"","","",1,0,0,[],""],["rm_t4-n6920",2,"La que toca la guitarra,\nA ésa le digo yo\nQue tiene siya dorada\nDentro de mi corason.",2,0,-1,15,"",5,4,"ao",-1,0,-1,0,275,275,"6920","",0,"","","",1,0,0,[],""],["rm_t4-n6921",2,"La guitarra es de plata;\nLas cuerdas, de oro;\nY el que la está tocando\nVale un tesoro.",2,0,-1,15,"",6,4,"oo",85,0,-1,0,275,276,"6921","",0,"","","",1,0,0,[],""],["rm_t4-n6922",2,"La guitarra es de caoba\nY las cuerdas de marfil;\nEl que la toca es un ángel;\nLa que baila, un serafin.",2,0,-1,15,"",0,4,"i",-1,0,-1,0,276,276,"6922","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6923",2,"¡Atension, qu' ha salido\nLa reina á bailar!\n¡Qué hermoso cuerpo tiene\nSu real majestá!",2,0,-1,15,"",0,4,"a",-1,0,-1,0,276,276,"6923","",0,"","","",1,0,0,[],""],["rm_t4-n6924",2,"El mosito que baila\nBien puede desir\nQue baila con la reina,\nSin ir á Madrí.",2,0,-1,15,"",0,4,"i",-1,0,-1,0,276,276,"6924","",0,"","","",1,0,0,[],""],["rm_t4-n6925",2,"Pulido bailadorsito,\nCon berdá puedes desir\nQu' has bailado con la reina,\nSin haber ido á Madrí.",2,0,-1,15,"",0,4,"i",-1,0,-1,0,276,276,"6925","",0,"","","",4,0,0,[],""],["rm_t4-n6926",2,"Dicen que la reina ha muerto;\nTodos dicen que es verdad;\nY yo digo que es mentira,\nPorque ha salido á bailar.",2,0,-1,15,"",0,4,"a",-1,0,-1,0,276,276,"6926","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6927",2,"Ya está puesta en el baile\nLa que no quiere\nQue le digan la reina\nDe las mujeres.\nY yo le digo:\n—Reina de las mujeres,\nVénte conmigo.",2,0,-1,15,"",4,7,"io",106,0,-1,0,276,276,"6927","",0,"carrizo_salta","","",4,0,0,[],""],["rm_t4-n6928",2,"¡Ahora sí que canto yo\nCon contento y alegría,\nPorque ha salido á bailar\nLa prenda que yo queria!",2,0,-1,15,"",0,4,"ia",0,0,-1,0,277,277,"6928","",0,"","","",2,0,0,[],""],["rm_t4-n6929",2,"Ya salió mi niña al baile;\nYa salió la resalada;\nYa salió la que me tiene\nTodita el alma robada.",2,0,-1,15,"",0,4,"aa",49,0,-1,0,277,277,"6929","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6930",2,"Cuando sales á bailar\nCon los brazos extendidos,\nPareces águila real\nCuando sale de su nido.",2,0,-1,15,"",0,4,"io",-1,0,-1,0,277,277,"6930","",0,"palau_cantares","","",5,0,0,[],""],["rm_t4-n6931",2,"Esos pulidos zapatos\nCon que sales á bailar\nMerecian ser de plata\nLa suela y el cordoban.",2,0,-1,15,"",5,4,"oa",-1,0,-1,0,277,277,"6931","",0,"","","",1,0,0,[],""],["rm_t4-n6932",2,"Cuando sales á bailar\nCon ese garbo y salero,\nUna campana de plata\nPareces de pié en el suelo.",2,0,-1,15,"",0,4,"eo",-1,0,-1,0,277,277,"6932","",0,"palau_cantares","","",5,0,0,[],""],["rm_t4-n6934",2,"Con ese andar tan ligero\nY ese modo de bailar,\nHas revuelto á los mozuelos\nDe todito este lugar.",2,0,-1,15,"",0,4,"a",21,0,-1,0,277,278,"6934","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6935",2,"Cuando te veo bailar\nCon tanta gracia y salero,\nDigo: —¡Quién se llevará\nEse cuerpo sandunguero!",2,0,-1,15,"",0,4,"eo",38,0,-1,0,278,278,"6935","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6936",2,"La niña qu' está bailando\nParese un pimpoyo de oro;\nPregúntale, compañero,\nSi es casada ó tiene nobio.",2,0,-1,15,"",0,4,"oo",-1,0,-1,0,278,278,"6936","",0,"","","",1,0,0,[],""],["rm_t4-n6937",2,"La niña que está bailando\nParece una altramucera;\n¡Altramuces, dulces, dulces!\n¡Salada, quién te comiera!",2,0,-1,15,"",0,4,"ea",44,0,-1,0,278,278,"6937","",0,"","","",19,0,0,[],""],["rm_t4-n6938",2,"A la qu' está bailando,\nEcharle rosas,\nPorque se lo merese,\nPor güena mosa",2,0,-1,15,"",6,4,"oa",-1,0,-1,0,278,278,"6938","",0,"","","",1,0,0,[],""],["rm_t4-n6940",2,"La dama que está bailando\nSe parece á Santa Rita,\nY el galan que está cantando,\nErmitaño de su ermita.",2,0,-1,15,"",1,4,"ia",50,0,-1,0,278,278,"6940","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t4-n6941",2,"Si no fuera mi prima\nLa que bailara,\nNo fuera mi boquita\nLa que cantara.",2,0,-1,15,"",6,4,"aa",57,0,-1,0,278,278,"6941","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6942",2,"De las dos que están bailando,\nLas dos me parecen bien:\nUna parece una rosa\nY otra parece un clavel.",2,0,-1,15,"",0,4,"e",-1,0,-1,0,279,279,"6942","",0,"","","",1,0,0,[],""],["rm_t4-n6943",2,"La niña que está bailando\nParece una rosa fina,\nY el bailador que la baila\nParece una clavellina.",2,0,-1,15,"",0,4,"ia",11,0,-1,0,279,279,"6943","",0,"","","",19,0,0,[],""],["rm_t4-n6944",2,"Un clavel y una rosa\nEstán bailando;\nLa rosa es encarnada\nY el clavel, blanco.\nPorque la rosa,\nMientras más encarnada\nEs más hermosa.",2,0,-1,15,"",4,7,"oa",63,0,-1,0,279,279,"6944","",0,"","","",2,0,0,[],""],["rm_t4-n6945",2,"La bailadora es la luna\nY el bailador es el sol;\nA los rayos de la luna\nMe voy arrimando yo.",2,0,-1,15,"",0,4,"o",-1,0,-1,0,279,279,"6945","",0,"","","",3,0,0,[],""],["rm_t4-n6946",2,"Entre los dos que bailan\nQuisiera morir;\n¡Qué muerte tan dichosa\nFuera para mí!\nMorir quisiera;\n¡Qué muerte tan dichosa\nPara mí fuera!",2,0,-1,15,"",4,7,"ea",44,0,-1,0,279,279,"6946","",0,"","","",2,0,0,[],""],["rm_t4-n6947",2,"Entre los dos que bailan\nCaiga una nube\nDe confites y almendras;\nCosa que dure.\nLa nube caiga\nDe confites y almendras;\nCosa que valga.",2,0,-1,15,"",4,7,"aa",-1,0,-1,0,279,280,"6947","",0,"","","",2,0,0,[],""],["rm_t4-n6953",2,"Pulido bailadorsito,\nBáilala bien, que es mi hermana;\nY si no la bailas bien,\nSaldrá su hermano á bailarla.",2,0,-1,15,"",0,4,"aa",-1,0,-1,0,280,280,"6953","",0,"","","",4,0,0,[],""],["rm_t4-n6954",2,"Pulido bailadorsito,\nÁtate los arpargates,\nNo bayas á trompesar\nY á esa niña me la mates.",2,0,-1,15,"",0,4,"ae",283,0,-1,0,281,281,"6954","",0,"","","",4,0,0,[],""],["rm_t4-n6955",2,"Pulido bailadorsito,\nBáilala desentemente;\nQue puede ser qu' esa niña\nTenga aquí su pretendiente.",2,0,-1,15,"",0,4,"ee",15,0,-1,0,281,281,"6955","",0,"","","",4,0,0,[],""],["rm_t4-n6956",2,"Señor bailadorsito,\nMir' usté ar joyo,\nQue la niña que baila\nTiene su nobio.\nMir' usté ar suelo,\nQue la niña que baila\nTiene su dueño.",2,0,-1,15,"",4,7,"eo",-1,0,-1,0,281,281,"6956","",0,"","","",2,0,0,[],""],["rm_t4-n6957",2,"Una mudanza por bajo\nBaile usté, seo bailador,\nPorque, aunque cueste trabajo,\nSe la merece esa flor.",2,0,-1,15,"",1,4,"o",72,0,-1,0,281,281,"6957","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n6958",2,"¿Qué tiene ese bailador,\nQue no menea los brasos,\nY parese un abion\nQue l' han dado taramaso?",2,0,-1,15,"",0,4,"ao",-1,0,-1,0,281,281,"6958","",0,"","","",3,0,0,[],""],["rm_t4-n6959",2,"La niña que está bailando\nMe la comiera yo solo;\nY al bailador que la baila\nQue se lo coman los lobos.",2,0,-1,15,"",0,4,"oo",-1,0,-1,0,281,281,"6959","",0,"palau_cantares, lafuente_madrid","","",19,0,0,[],""],["rm_t4-n6960",2,"Esa señora que baila\nSe parece á San Miguel;\nY el bailador que la baila,\nAl que está debajo de él.",2,0,-1,15,"",1,4,"e",32,0,-1,0,281,282,"6960","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n6961",2,"Er mosito que baila\nLas seguiriyas\nS' ha dejado en su casa\nLas pantorriyas.\nSi no m' engaño,\nHa bendido arropías\nEn San Bernardo.",2,0,-1,15,"",4,7,"ao",-1,0,-1,0,282,282,"6961","",0,"","","",1,0,0,[],""],["rm_t4-n6962",2,"¿Para que ban ar baile\nTantos mirones,\nSi bailan las mositas,\nPor farta de hombres?",2,0,-1,15,"",6,4,"oe",-1,0,-1,0,282,282,"6962","",0,"","","",1,0,0,[],""],["rm_t4-n6963",2,"Una fiesta se arma\nCon tres figuras:\nUno canta, otro baila\nY otro murmura.\nY yo soy uno\nQue ni canto ni bailo;\nPero murmuro.",2,0,-1,15,"",4,7,"uo",-1,0,-1,0,282,282,"6963","",0,"","","",1,0,0,[],""],["rm_t4-n6964",2,"Esos dos que están bailando,\n¡Qué parejitos que son!\nSi yo fuera padre cura,\nLes diera la bendicion.",2,0,-1,15,"",0,4,"o",31,0,-1,0,282,282,"6964","",0,"lafuente_madrid, palau_cantares","","",5,0,0,[],""],["rm_t4-n6965",2,"La guitarra lo dice;\nYo no lo digo,\nPorque los dos que bailan\nSon prima y primo.\nYo no lo ignoro,\nPorque los dos que bailan\nSon novia y novio.",2,0,-1,15,"",4,7,"oo",-1,0,-1,0,282,283,"6965","",0,"","","",2,0,0,[],""],["rm_t4-n6966",2,"A la señora nobia\nSacarla á bailar,\nPara que se despida\nDe su mosedá.",2,0,-1,15,"",0,4,"a",-1,0,-1,0,283,283,"6966","",0,"","","",4,0,0,[],""],["rm_t4-n6967",2,"A la señora nobia\nDesirle argo;\nDesirle qu' es bonita;\nQue tiene garbo.",2,0,-1,15,"",6,4,"ao",-1,0,-1,0,283,283,"6967","",0,"","","",4,0,0,[],""],["rm_t4-n6968",2,"La nobia es chiquitita\nY er nobio chico;\nMira qué matrimonio\nTan igualito.",2,0,-1,15,"",6,4,"io",-1,0,-1,0,283,283,"6968","",0,"","","",1,0,0,[],""],["rm_t4-n6969",2,"Chiquitita la novia,\nChiquito el novio;\nChiquitita la sala\nY el dormitorio.\nPor eso quiero\nChiquitita la cama\nY el mosquitero.",2,0,-1,15,"",4,7,"eo",38,0,-1,0,283,283,"6969","",0,"","","",1,0,0,[],""],["rm_t4-n6971",2,"A la señora nobia\nPor Dios le pido\nQue no tenga cuestiones\nCon su marido.",2,0,-1,15,"",6,4,"io",101,0,-1,0,283,283,"6971","",0,"","","",4,0,0,[],""],["rm_t4-n6972",2,"A la señora nobia,\n¿Qué le diremos?\nQue pase buena noche\nCon su moreno.",2,0,-1,15,"",6,4,"eo",-1,0,-1,0,284,284,"6972","",0,"","","",4,0,0,[],""],["rm_t4-n6974",2,"Con ésta y no canto más,\nPorque me duelen los dientes;\nPorque no beo benir\nEr baso del aguardiente.",2,0,-1,15,"",0,4,"ee",-1,0,-1,0,284,284,"6974","",0,"","","",1,0,0,[],""],["rm_t4-n6975",2,"Con esta copla y otra\nSe acaba el baile;\nPor la puerta, señores,\nSe va á la calle.",2,0,-1,15,"",6,4,"ae",-1,0,-1,0,284,284,"6975","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n6977",2,"El columpio es un rosal;\nLa que está dentro, una rosa;\nLa que la mece, un capullo;\n¡Ay, qué cara tan hermosa!",2,0,-1,16,"",0,4,"oa",63,0,-1,0,293,293,"6977","",0,"","","",1,0,0,[],""],["rm_t4-n6978",2,"La que está en el columpio,\nSi se cayera,\n¡Qué buena mortajita\nQue yo le hiciera!",2,0,-1,16,"",6,4,"ea",44,0,-1,0,293,293,"6978","",0,"","","",1,0,0,[],""],["rm_t4-n6979",2,"La niña que está en la bamba\nParece un piñón de oro;\nLe quisiera preguntar\nSi es casada ó tiene novio.",2,0,-1,16,"",0,4,"oo",-1,0,-1,0,293,293,"6979","",0,"","","",1,0,0,[],""],["rm_t4-n6980",2,"La niña qu' está en la bamba\nSe lo quisiera desí,\nY me ocupa la bergüensa.\nDígaselo usté por mí.",2,0,-1,16,"",0,4,"i",23,0,-1,0,293,293,"6980","",0,"","","",6,0,0,[],""],["rm_t4-n6981",2,"La niña qu' está en la bamba\nDer sielo le caigan rosas;\nDiga usté, mosa de grasia,\nSi se le ofrese otra cosa.",2,0,-1,16,"",0,4,"oa",-1,0,-1,0,293,293,"6981","",0,"","","",6,0,0,[],""],["rm_t4-n6983",2,"La niña qu' está en la bamba\nCon la toquiya encarná\nEs la nobia de mi hermano;\nPronto será mi cuñá.",2,0,-1,16,"",0,4,"a",9,0,-1,0,294,294,"6983","",0,"","","",6,0,0,[],""],["rm_t4-n6984",2,"La niña qu' está en la bamba\nSe parese á San Antonio,\nY la que la está mesiendo,\nAr mismísimo demonio.",2,0,-1,16,"",0,4,"oo",169,0,-1,0,294,294,"6984","",0,"","","",6,0,0,[],""],["rm_t4-n6985",2,"Mosito qu' está 'n la puerta,\nEntr' usté y me meserá;\nQue los que m' están mesiendo\nHan comido poleás.",2,0,-1,16,"",0,4,"a",-1,0,-1,0,294,294,"6985","",0,"","","",1,0,0,[],""],["rm_t4-n6986",2,"Tira bien de los cordeles\nY remóntala bien arta;\nQue parese una Pastora\nEn su camarin sentada.",2,0,-1,16,"",0,4,"aa",-1,0,-1,0,294,294,"6986","",0,"","","",2,0,0,[],""],["rm_t4-n6987",2,"Tira bien de los cordeles\nY remóntalo ar tejao;\nQue parese un sapatero\nEn su banquiya sentao.",2,0,-1,16,"",0,4,"ao",98,0,-1,0,294,294,"6987","",0,"","","",2,0,0,[],""],["rm_t4-n6988",2,"La niña qu' está en la bamba\nParese una candileja,\nY las dos qu' están mesiendo\nSon dos arcusiyas biejas.",2,0,-1,16,"",0,4,"ea",-1,0,-1,0,294,295,"6988","",0,"","","",6,0,0,[],""],["rm_t4-n6989",2,"La qu' está en er columpio\nTiene unos piés,\nQue paresen escobas\nDe montañés.\nTiene unos ojos,\nQue paresen ochabos\nYenos de mojo.",2,0,-1,16,"",4,7,"oo",-1,0,-1,0,295,295,"6989","",0,"","","",1,0,0,[],""],["rm_t4-n6990",2,"Debajo del columpio\nTengo una estera\nDonde duerme mi amante\nLa borrachera.",2,0,-1,16,"",6,4,"ea",44,0,-1,0,295,296,"6990","",0,"","","",1,0,0,[],""],["rm_t4-n6991",2,"Quiero cantar ahora,\nQue tengo gana,\nPor si acaso me toca\nLlorar mañana.",2,0,-1,17,"",6,4,"aa",4,0,-1,0,299,299,"6991","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],""],["rm_t4-n6993",2,"Cantar quiero y divertirme\nLo que me queda de vida;\nQue después vendrá la muerte\nCon sus penas y agonías.",2,0,-1,17,"",0,4,"ia",-1,0,-1,0,299,299,"6993","",0,"","","",1,0,0,[],""],["rm_t4-n6994",2,"Tengo yo mi corason\nTan jechesito á mis mañas,\nQue le digo «yora» y yora,\nY le digo «canta» y canta.",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,299,299,"6994","",0,"","","",4,0,0,[],""],["rm_t4-n6995",2,"¡Salero, biba er coraje\nY muera la pena negra,\nY muera er que la tubiere,\nPorque yo bibo sin eya!",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,299,300,"6995","",0,"","","",1,0,0,[],""],["rm_t4-n6996",2,"Algun dia me apuraba;\nApúrese quien quisiere,\nPorque tengo conocido\nQue quien se apura se muere.",2,0,-1,17,"",0,4,"ee",115,0,-1,0,300,300,"6996","",0,"","","",1,0,0,[],""],["rm_t4-n6997",2,"Quiero gosar de mi tiempo,\nSupuesto qu' ahora me bale;\nPorque 'r dia de mañana,\nEse no lo ha bisto nádie.",2,0,-1,17,"",3,4,"ae",-1,0,-1,0,300,300,"6997","",0,"","","",1,0,0,[],""],["rm_t4-n6998",2,"¿No es una gran tontería\nEl estar siempre penando,\nPudiéndose divertir\nUna vez de cuando en cuando?",2,0,-1,17,"",0,4,"ao",33,0,-1,0,300,300,"6998","",0,"","","",1,0,0,[],""],["rm_t4-n6999",2,"Esta noche me ha tocado\nEr salirme á dibertir;\nPero mañana á la noche\nMe recojo ar buen bibir.",2,0,-1,17,"",0,4,"i",157,0,-1,0,300,300,"6999","",0,"","","",2,0,0,[],""],["rm_t4-n7000",2,"Yo me yamo Poca-pena,\nSobrino de Mala-gana,\nY por apeyido tengo\nA mí no se me da nada.",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,300,300,"7000","",0,"","","",1,0,0,[],""],["rm_t4-n7001",2,"Medio mundo se rie\nDel otro medio,\nY yo solo me rio\nDel mundo entero.",2,0,-1,17,"",6,4,"eo",-1,0,-1,0,300,300,"7001","",0,"","","",1,0,0,[],""],["rm_t4-n7002",2,"Yo no quiero sufrir más,\nQue estoy harto de sufrir;\nQue quiero tomar el tiempo\nComo lo vea venir.",2,0,-1,17,"",0,4,"i",157,0,-1,0,300,301,"7002","",0,"","","",1,0,0,[],""],["rm_t4-n7003",2,"Las cositas de este mundo\nMuchos las toman á pecho;\nYo las tomo con la mano\nY á la espalda me las echo.",2,0,-1,17,"",0,4,"eo",60,0,-1,0,301,301,"7003","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7004",2,"Más fresca que una lechuga\nEstoy bibiendo en er mundo;\nTomo er tiempo como biene\nY no me fío de ninguno.",2,0,-1,17,"",0,4,"uo",-1,0,-1,0,301,301,"7004","",0,"","","",1,0,0,[],""],["rm_t4-n7005",2,"Quien tiene penas no duerme\nY yo siempre estoy durmiendo;\nCon esto quiero decirte\nQue yo penitas no tengo.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,301,301,"7005","",0,"","","",1,0,0,[],""],["rm_t4-n7006",2,"Quien tiene penas, se muere;\nQuien no las tiene, tambien;\nYo quiero vivir alegre;\nMañana me moriré.",2,0,-1,17,"",0,4,"e",-1,0,-1,0,301,301,"7006","",0,"andina_t1, lafuente_madrid, leonesas_diez","","",4,0,0,[],""],["rm_t4-n7007",2,"Este mundo es una bola\nY el que se muere es un tonto;\nEl que se llega á morir\nDeja el mundo para otro.",2,0,-1,17,"",0,4,"oo",-1,0,-1,0,301,301,"7007","",0,"","","",3,0,0,[],""],["rm_t4-n7008",2,"Cada bes que considero\nQue me tengo de morir....\nTiendo la capa en er suelo\nY me jarto de dormir.",2,0,-1,17,"",0,4,"i",157,0,-1,0,301,301,"7008","",0,"","","",2,0,0,[],""],["rm_t4-n7009",2,"Cada bes que considero\nQue tengo un amor ingrato....\nNo sé cómo no me tiro\nContra un corchon y me mato.",2,0,-1,17,"",0,4,"ao",19,0,-1,0,301,302,"7009","",0,"","","",2,0,0,[],""],["rm_t4-n7010",2,"Estoy bibiendo en er mundo\nEl hombre más arreglado:\nSi me preguntan, contesto;\nY si nó, m' estoy cayado.",2,0,-1,17,"",0,4,"ao",14,0,-1,0,302,302,"7010","",0,"","","",1,0,0,[],""],["rm_t4-n7011",2,"¡Qué bonito es er dinero\nTeniendo blanco er coló!\nYo me rio y me dibierto\nY como de lo mejó.",2,0,-1,17,"",0,4,"o",2,0,-1,0,302,302,"7011","",0,"","","",1,0,0,[],""],["rm_t4-n7012",2,"Cuando me parió mi madre\nMe parió en un campanario;\nCuando bino la comadre\nEstaba yo repicando.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,302,302,"7012","",0,"","","",8,0,0,[],""],["rm_t4-n7013",2,"Er dia que yo nasí\nDijo una berdá mi agüela:\n—Mientras este niño biba,\nSeguro está que se muera.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,302,302,"7013","",0,"","","",1,0,0,[],""],["rm_t4-n7014",2,"Cuando salí de mi tierra\nS' echó mi agüela á yorar:\n—¡Qué lástima de mi niño,\nQue me lo ban á engañar!",2,0,-1,17,"",0,4,"a",21,0,-1,0,302,302,"7014","",0,"","","",9,0,0,[],""],["rm_t4-n7016",2,"Mi madre, porque soy tuno,\nA presidio quiere echarme;\nYo le digo: — Madre mia,\n¿Dónde irá el buey que no are?",2,0,-1,17,"",0,4,"ae",-1,0,-1,0,302,303,"7016","",0,"","","",1,0,0,[],""],["rm_t4-n7017",2,"Yo me metí en er querer\nComo niño en el escuela,\nY á las primeras lersiones\nMe pasaba de la regla.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,303,303,"7017","",0,"","","",1,0,0,[],""],["rm_t4-n7018",2,"Una rubia m' engañó\nPorque me piyó sensiyo;\n¡Ya no borberán las rubias\nA tener bromas conmigo!",2,0,-1,17,"",0,4,"io",-1,0,-1,0,303,303,"7018","",0,"","","",1,0,0,[],""],["rm_t4-n7019",2,"Jasta er puente fí con eya,\nPor ber si la camelaba,\nY eya me cameló á mí\nLos cuartiyos que yebaba.",2,0,-1,17,"",0,4,"aa",28,0,-1,0,303,303,"7019","",0,"","","",1,0,0,[],""],["rm_t4-n7020",2,"Una bieja bale un duro\nY una muchacha dos cuartos;\nYo, como soy pobresito,\nMe boy á lo más barato.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,303,303,"7020","",0,"","","",1,0,0,[],""],["rm_t4-n7021",2,"Yo tengo un cabayo bayo\nQue se muere por las yeguas,\nY yo, como soy su amo,\nMe muero por las mosuelas.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,303,303,"7021","",0,"","","",1,0,0,[],""],["rm_t4-n7022",2,"Cuando yo, pequeñito,\nLlorando estaba,\nLlegaban las mozuelas,\nBesos me daban.\nAhora digo yo:\n—Que vengan las mozuelas\nSe los daré yo.",2,0,-1,17,"",4,7,"o",-1,0,-1,0,303,303,"7022","",0,"","","",1,0,0,[],""],["rm_t4-n7024",2,"Si fuera gato montés,\nM' entrara por la gatera;\nA las biejas le arañara\nY con las mosas durmiera.",2,0,-1,17,"",0,4,"ea",44,0,-1,0,304,304,"7024","",0,"","","",1,0,0,[],""],["rm_t4-n7025",2,"Los hombres somos las moscas,\nY las mujeres la miel,\nY las suegras las avispas,\nQue no nos dejan comer.",2,0,-1,17,"",0,4,"e",-1,0,-1,0,304,304,"7025","",0,"","","",1,0,0,[],""],["rm_t4-n7026",2,"Er demonio son las purgas,\nQue no tienen religion;\nS' acuestan con las mosuelas,\nLo que no consigo yo.",2,0,-1,17,"",0,4,"o",-1,0,-1,0,304,304,"7026","",0,"rm_t2","","",2,0,0,[],""],["rm_t4-n7027",2,"Con un biscocho d' á cuarto\nY un buchito d' agua fria\nY un beso d' una muchacha\nTiene un hombre su comía.",2,0,-1,17,"",0,4,"ia",0,0,-1,0,304,304,"7027","",0,"","","",1,0,0,[],""],["rm_t4-n7028",2,"Supuesto que las viñas\nHan vendimiado,\nVamos á la rebusca,\nPor ver si hay algo.",2,0,-1,17,"",6,4,"ao",-1,0,-1,0,304,304,"7028","",0,"","","",1,0,0,[],""],["rm_t4-n7029",2,"No quiero amor con doncella;\nQue las casadas me dan\nTodo lo que necesito;\nMe dicen si quiero más.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,304,304,"7029","",0,"","","",2,0,0,[],""],["rm_t4-n7030",2,"A las mujeres no buscó,\nQue á las manos se me bienen;\nA lo sorruco me ando\nY caiga la que cayere.",2,0,-1,17,"",0,4,"ee",-1,0,-1,0,305,305,"7030","",0,"","","",1,0,0,[],""],["rm_t4-n7031",2,"Tengo mi amor repartido\nEntre cuatro ó cinco damas;\nYo me divierto con todas,\nY ellas conmigo se engañan.",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,305,305,"7031","",0,"","","",2,0,0,[],""],["rm_t4-n7032",2,"El lúnes me enamoro;\nMártes, lo digo;\nSoy miércoles y juéves\nCorrespondido.\nViérnes, doy celos,\nY sábado y domingo\nBusco amor nuevo.",2,0,-1,17,"",4,7,"eo",-1,0,-1,0,305,305,"7032","",0,"","","",3,0,0,[],""],["rm_t4-n7033",2,"Yo me queria casá\nCon una que no pariera,\nY que fuera muy bonita,\nSu madre la mantubiera.",2,0,-1,17,"",0,4,"ea",44,0,-1,0,305,305,"7033","",0,"","","",1,0,0,[],""],["rm_t4-n7034",2,"Una viuda me busca;\nPor Dios que yo no la busco;\nEl que se comió la uva,\nQue se coma los rebuscos.",2,0,-1,17,"",0,4,"uo",-1,0,-1,0,305,305,"7034","",0,"","","",1,0,0,[],""],["rm_t4-n7035",2,"Yo no sé cabar ni arar,\nNi tampoco coger yerba;\nLa que se case conmigo,\n¡Qué buena prenda se yeba!",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,305,305,"7035","",0,"","","",2,0,0,[],""],["rm_t4-n7037",2,"Mi abuela, que esté en gloria,\nMe lo decia:\nQue nunca hiciera caso\nDe un medio dia.\nY así lo hago,\nPues de dias enteros\nNunca hice caso.",2,0,-1,17,"",4,7,"ao",-1,0,-1,0,306,306,"7037","",0,"","","",1,0,0,[],""],["rm_t4-n7038",2,"Si me dibierto, soy tuno;\nSi bebo bino, borracho;\nSi boy á misa de onse,\nMe disen que soy beato.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,306,306,"7038","",0,"","","",1,0,0,[],""],["rm_t4-n7039",2,"Ya viene la cuaresma\nPara sermones;\nEn mi casa no faltan\nPredicaciones.",2,0,-1,17,"",6,4,"oe",34,0,-1,0,306,306,"7039","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n7040",2,"Pá las cuestas arriba\nQuiero mi mulo;\nQue las cuestas abajo\nYo me las subo.",2,0,-1,17,"",6,4,"uo",-1,0,-1,0,306,306,"7040","",0,"","","",1,0,0,[],""],["rm_t4-n7042",2,"Disen que m' has de matar\nCon un cuchiyo d' arrope;\n¡Jesús, qué muerte tan durse,\nSi lo clabas po' 'r gañote!",2,0,-1,17,"",0,4,"oe",-1,0,-1,0,306,307,"7042","",0,"","","",1,0,0,[],""],["rm_t4-n7043",2,"La cabesita me duele\nDer palo que m' han de dar;\nNo me lo han dao y me duele:\n¿Qué será si me lo dan?",2,0,-1,17,"",0,4,"a",-1,0,-1,0,307,307,"7043","",0,"","","",1,0,0,[],""],["rm_t4-n7044",2,"Yo me subí á lo arto e un serro\nA darle á un pastor dos palos,\nY se gorbieron las tornas:\nÉr me los dió y yo los traigo.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,307,307,"7044","",0,"","","",1,0,0,[],""],["rm_t4-n7045",2,"Como tú no me faltes,\nPan de mi alforja,\nComo tú no me faltes,\nTodo me sobra.",2,0,-1,17,"",6,4,"oa",-1,0,-1,0,307,307,"7045","",0,"fernan_caballero, palau_cantares","","",3,0,0,[],""],["rm_t4-n7047",2,"El que tuviere envidia\nLlame á Cachano; (?)\nQue cuando tengo rabia,\nTambien le llamo.",2,0,-1,17,"",6,4,"ao",-1,0,-1,0,307,307,"7047","",0,"","","",2,0,0,[],""],["rm_t4-n7048",2,"No hay madres que paran hijos\nMás desgraciados que yo;\nSin pretina en los calzones\nNi cuello en el camison.",2,0,-1,17,"",0,4,"o",-1,0,-1,0,307,307,"7048","",0,"","","",1,0,0,[],""],["rm_t4-n7049",2,"Dicen que he robado un cáliz;\n¡Jesús, qué mentira es ésa!\nDesde que me bautizaron\nNo he vuelto á entrar en la iglesia.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,307,307,"7049","",0,"","","",3,0,0,[],""],["rm_t4-n7050",2,"Soy galapaguito y traigo\nConcha para nabegar:\nConcha arriba, concha abajo,\nConcha alante, concha atrás.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,308,308,"7050","",0,"","","",1,0,0,[],""],["rm_t4-n7052",2,"En lo que me entretengo\nCuanto estoy solo.\nMe quito la peluca,\nMe pongo el gorro.",2,0,-1,17,"",6,4,"oo",-1,0,-1,0,308,308,"7052","",0,"","","",2,0,0,[],""],["rm_t4-n7054",2,"Como tengo este genio\nTan encogido,\nSi me lo dan, lo tomo;\nSi nó, lo pido.",2,0,-1,17,"",6,4,"io",101,0,-1,0,308,308,"7054","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n7055",2,"Mientras haya quien te dé,\nNo pases nesesidá;\nHarto trabajiyo tenga\nEr que tenga que cobrar.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,308,308,"7055","",0,"","","",1,0,0,[],""],["rm_t4-n7056",2,"Diga usté lo que se debe,\nPá ponerlo en er diario;\nPorque 'r deber es presiso\nY er pagar no es nesesario.",2,0,-1,17,"",0,4,"ao",25,0,-1,0,308,308,"7056","",0,"","","",1,0,0,[],""],["rm_t4-n7057",2,"En la calle me llaman\nPerico, Pedro,\nY en llegando á mi casa,\nSeñor don tengo.",2,0,-1,17,"",6,4,"eo",-1,0,-1,0,309,309,"7057","",0,"","","",1,0,0,[],""],["rm_t4-n7058",2,"En la calle soy Don Juan;\nEn en taller, zapatero;\nEn la escuela, el ayudante;\nY en la plaza, carnicero.",2,0,-1,17,"",0,4,"eo",38,0,-1,0,309,309,"7058","",0,"","","",1,0,0,[],""],["rm_t4-n7059",2,"Si quieres saber quién soy,\nCantando te lo diré:\nMi padre y mi madre fueron\nUn hombre y una mujer.",2,0,-1,17,"",0,4,"e",-1,0,-1,0,309,309,"7059","",0,"","","",3,0,0,[],""],["rm_t4-n7060",2,"Si quieres saber, señora,\nMi nombre y el de mi hermana,\nYo me yamo Yo-me-yamo\nY eya se yama Se-yama.",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,309,309,"7060","",0,"","","",3,0,0,[],""],["rm_t4-n7061",2,"Bibo en la caye Rebientes,\nEsquina Rómpete-'l-arma,\nDonde er demonio te yebe,\nMardita sea tu facha.",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,309,309,"7061","",0,"","","",1,0,0,[],""],["rm_t4-n7062",2,"A mí me yaman Calores\nY yo me muero de frio;\nY los chiquiyos me disen:\n—Calores, bamos ar rio.",2,0,-1,17,"",0,4,"o",3,0,-1,0,309,309,"7062","",0,"","","",1,0,0,[],""],["rm_t4-n7063",2,"A mí me yaman Trapiyo\nY á mi marido, Guiñapo;\n¡Er demonio que se yebe\nEr canasto de los trapos!",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,309,309,"7063","",0,"","","",1,0,0,[],""],["rm_t4-n7065",2,"A tu madre le yaman\nLa Berenjena,\nA tu padre el Pepino\nY á tí la Breva.",2,0,-1,17,"",6,4,"ea",-1,0,-1,0,310,310,"7065","",0,"","","",1,0,0,[],""],["rm_t4-n7066",2,"—A mí me llaman Peneque;\nSeñor alcalde, ¿qué haré?\n— Vaya usté con Dios, Peneque,\nQue yo lo remediaré.",2,0,-1,17,"",1,4,"e",77,0,-1,0,310,310,"7066","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7068",2,"A mí me llaman el tonto,\nEl tonto de mi lugar;\nTodos comen trabajando;\nYo como sin trabajar.",2,0,-1,17,"",0,4,"a",21,0,-1,0,310,310,"7068","",0,"palau_cantares, machado_venezuela, lafuente_madrid","","",8,0,0,[],""],["rm_t4-n7069",2,"A mí me llaman el tonto,\nPorque miro á los tejados;\nSoy tonto de conveniencia,\nPorque voy á mi cuidado.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,310,310,"7069","",0,"lafuente_madrid","","",8,0,0,[],""],["rm_t4-n7070",2,"A mí me yaman er tonto;\nYo digo que lo seré;\nPero no me chupo er deo\nComo no lo moje en mié.",2,0,-1,17,"",0,4,"e",77,0,-1,0,310,311,"7070","",0,"","","",2,0,0,[],""],["rm_t4-n7071",2,"A mí me yaman er tonto,\nPorque me farta un sentío,\nY á tí te farta otra cosa,\nQue er tonto se l' ha comío.",2,0,-1,17,"",0,4,"io",3,0,-1,0,311,311,"7071","",0,"","","",2,0,0,[],""],["rm_t4-n7072",2,"Soy maestro examinado\nDe las cucharas de pan;\nTengo el oficio parado,\nPor falta de material.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,311,311,"7072","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7073",2,"Aunque me ves que canto\nCon arrogancia,\nComo santo de iglesia\nTraigo la panza.",2,0,-1,17,"",6,4,"aa",-1,0,-1,0,311,311,"7073","",0,"","","",6,0,0,[],""],["rm_t4-n7074",2,"Tengo más jambre que Dios;\nEbajo d' este sombrero\nM' aterminaba á comerme\nA la hija er panaero.",2,0,-1,17,"",0,4,"eo",38,0,-1,0,311,311,"7074","",0,"","","",1,0,0,[],""],["rm_t4-n7075",2,"Mi camaraíta y yo\nSemos dos fuertes leones;\nMos mantenemos del aire,\nComo los camaleones.",2,0,-1,17,"",0,4,"oe",34,0,-1,0,311,311,"7075","",0,"","","",1,0,0,[],""],["rm_t4-n7076",2,"¡Cuando quedrá Dios der sielo\nQue se ponga er pan barato,\nPara que mi barriguita\nNo pase tan malos ratos!",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,311,311,"7076","",0,"","","",1,0,0,[],""],["rm_t4-n7077",2,"Si bieres á la carpanta,\nPégale un tiro por mí;\nQu' anoche estubo en mi casa\nY no me dejó dormí.",2,0,-1,17,"",0,4,"i",23,0,-1,0,311,312,"7077","",0,"","","",1,0,0,[],""],["rm_t4-n7078",2,"No me tires chinitos\nA la ventana;\nTírame panecillos,\nQue tengo gana.\nTírame nueces:\nTíramelas á pares,\nCinco en dos veces.",2,0,-1,17,"",4,7,"ee",196,0,-1,0,312,312,"7078","",0,"","","",2,0,0,[],""],["rm_t4-n7079",2,"Hágame usté una escopeta\nDe longanisa er cañon,\nDe pan blanco la baqueta\nY la caja de jamon\n[De bino la casoleta].",2,0,-1,17,"",7,5,"ea",200,0,-1,0,312,312,"7079","",0,"","","",3,0,0,[],""],["rm_t4-n7080",2,"He de hacer un castillo\nCon cien teleras;\nDoscientos veinte bollos,\nDe centinelas.\nDe consiguiente,\nVendrán para el relevo\nTrescientos veinte.",2,0,-1,17,"",4,7,"ee",-1,0,-1,0,312,312,"7080","",0,"","","",3,0,0,[],""],["rm_t4-n7081",2,"Una rosca y un boyo\nEstán bailando\nY una onsa de queso\nLo está mirando.\n¡Qué grasia fuera\nQu' un rasimo de ubas\nS' aparesiera!",2,0,-1,17,"",4,7,"ea",44,0,-1,0,312,312,"7081","",0,"","","",1,0,0,[],""],["rm_t4-n7082",2,"Si quieres que te quiera,\nDame doblones,\nQue es moneda que alegra\nLos corazones.",2,0,-1,17,"",6,4,"oe",34,0,-1,0,312,313,"7082","",0,"leonesas_diez","","",13,0,0,[],""],["rm_t4-n7083",2,"Si quieres que te quiera,\nMe has de dar ántes\nPañuelos y abanicos,\nBlondas y guantes.",2,0,-1,17,"",6,4,"ae",262,0,-1,0,313,313,"7083","",0,"","","",13,0,0,[],""],["rm_t4-n7084",2,"Si quieres que te quiera,\nDame confites;\nQue ya se me acabaron\nLos que me distes.",2,0,-1,17,"",6,4,"ie",-1,0,-1,0,313,313,"7084","",0,"","","",13,0,0,[],""],["rm_t4-n7085",2,"El amarte y quererte,\nEso es aparte;\nPero que te mantenga,\nNiña, tu madre.",2,0,-1,17,"",6,4,"ae",-1,0,-1,0,313,313,"7085","",0,"","","",1,0,0,[],""],["rm_t4-n7086",2,"Si quieres que te quiera,\nCompra un borrico,\nY andarás á caballo,\nComo un obispo.",2,0,-1,17,"",6,4,"io",-1,0,-1,0,313,313,"7086","",0,"","","",13,0,0,[],""],["rm_t4-n7087",2,"Si quieres que yo te quiera,\nHa de ser con condicion\nQue lo tuyo ha de ser mio\nY lo mio tuyo nó.",2,0,-1,17,"",0,4,"o",2,0,-1,0,313,313,"7087","",0,"palau_cantares, lafuente_madrid","","",23,0,0,[],""],["rm_t4-n7089",2,"Permita Dios, si me olvidas,\nQue te lleven los demonios;\nY si yo te olvido á tí,\nQue me lleve San Antonio.",2,0,-1,17,"",0,4,"oo",-1,0,-1,0,313,314,"7089","",0,"","","",5,0,0,[],""],["rm_t4-n7090",2,"Cuando paso por tu puerta,\nBoy corriendo y boy sartando,\nPâ que no diga tu madre:\n— Tengo un yerno patisambo.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,314,314,"7090","",0,"","","",17,0,0,[],""],["rm_t4-n7091",2,"Ar pasar por tu puerta\nPegué un sartete\nY me dijo tu madre:\n—¡Qué ligerete!",2,0,-1,17,"",6,4,"ee",285,0,-1,0,314,314,"7091","",0,"","","",3,0,0,[],""],["rm_t4-n7092",2,"Antier noche me caí\nEn la puerta de mi nobia,\nY eya dijo desde adentro:\n—¡Si fuera er tajo de Ronda!",2,0,-1,17,"",0,4,"oa",-1,0,-1,0,314,314,"7092","",0,"","","",1,0,0,[],""],["rm_t4-n7093",2,"Ar pasar por tu puerta\nBendiendo berros,\nTu madre, de coraje,\nM' asusó er perro.",2,0,-1,17,"",6,4,"eo",-1,0,-1,0,314,314,"7093","",0,"","","",3,0,0,[],""],["rm_t4-n7094",2,"Al pasar por tu puerta,\nMetí el hocico;\nTu padre, de coraje,\nMató al borrico.",2,0,-1,17,"",6,4,"io",141,0,-1,0,314,314,"7094","",0,"","","",3,0,0,[],""],["rm_t4-n7095",2,"Ar pasar por tu puerta,\nPegué un jardaso;\nMe lebantó tu padre\nDe un ladriyaso.",2,0,-1,17,"",6,4,"ao",145,0,-1,0,314,314,"7095","",0,"","","",3,0,0,[],""],["rm_t4-n7096",2,"Ayer tarde m' aserqué\nA tu puerta á darte un laso,\nY el animar de tu padre\nMe tronchó d' un estacaso.",2,0,-1,17,"",0,4,"ao",145,0,-1,0,314,315,"7096","",0,"","","",1,0,0,[],""],["rm_t4-n7097",2,"Una bes m' enamoré\nDe la hija de un casero;\nSalieron etrás e mí\nLos palos der gayinero.",2,0,-1,17,"",0,4,"eo",38,0,-1,0,315,315,"7097","",0,"","","",1,0,0,[],""],["rm_t4-n7098",2,"Antier noche mi agüela\nTiró un sapato;\nMi agüelo, que lo supo,\nTiró hasta cuatro.",2,0,-1,17,"",6,4,"ao",-1,0,-1,0,315,315,"7098","",0,"","","",1,0,0,[],""],["rm_t4-n7099",2,"Yo se lo dije á una prieta\nY eya me dijo que nó:\n¡Mira cómo se resierne\nLa sereta der carbon!",2,0,-1,17,"",0,4,"o",-1,0,-1,0,315,315,"7099","",0,"","","",1,0,0,[],""],["rm_t4-n7100",2,"Me dijistes qu' era ganso;\nBen á cortarme una pluma;\nQue las plumas de los gansos\nSon abanicos d' argunas.",2,0,-1,17,"",0,4,"ua",-1,0,-1,0,315,315,"7100","",0,"","","",1,0,0,[],""],["rm_t4-n7101",2,"Con esas naguas rajâs,\nToas yenitas e girones,\nPareses cochina jara,\nJarta de criar lechones.",2,0,-1,17,"",0,4,"oe",34,0,-1,0,315,315,"7101","",0,"","","",1,0,0,[],""],["rm_t4-n7102",2,"Premita Dios que te beas\nSin chaqueta y sin carsones,\nEn una jiguera chumba,\nEspantando gorriones.",2,0,-1,17,"",0,4,"oe",34,0,-1,0,315,315,"7102","",0,"","","",3,0,0,[],""],["rm_t4-n7103",2,"En er pilar de la baba\nLababa la prenda mia;\nComo lababa, lababa,\nLa baba se le caia.",2,0,-1,17,"",1,4,"a",-1,0,-1,0,315,316,"7103","",0,"","","",1,0,0,[],""],["rm_t4-n7104",2,"Todo el mundo me lo dice,\nY yo tambien que lo veo;\nQue te se cae la baba;\nToma, mi vida, un pañuelo.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,316,316,"7104","",0,"","","",14,0,0,[],""],["rm_t4-n7105",2,"Si quieres un pañuelo\nPara la baba,\nEn la calle de Atocha\nLos hay de á vara.",2,0,-1,17,"",6,4,"aa",-1,0,-1,0,316,316,"7105","",0,"","","",1,0,0,[],""],["rm_t4-n7106",2,"Dises que tienes buen pelo\nY te hases buen roete;\nY yo digo que es mentira:\nQue son trapos que te metes.",2,0,-1,17,"",0,4,"ee",-1,0,-1,0,316,316,"7106","",0,"","","",1,0,0,[],""],["rm_t4-n7107",2,"Tienes el pelo con trampa,\nPara que la gente diga:\n—¡Jesús, qué mata de pelo!\n¡El Señor te la bendiga!",2,0,-1,17,"",0,4,"ia",232,0,-1,0,316,316,"7107","",0,"","","",1,0,0,[],""],["rm_t4-n7109",2,"Parecen tus orejas\nAventadores,\nY tu boca portillo\nDe Embajadores.",2,0,-1,17,"",6,4,"oe",5,0,-1,0,316,316,"7109","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7110",2,"Son tus ojos tan brillantes\nQue parecen dos luceros;\nY como tienes lagañas,\nTe las limpias con el dedo.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,316,317,"7110","",0,"","","",1,0,0,[],""],["rm_t4-n7111",2,"La causa de ser yo chato,\n¿A que no la acierta usté?\nEstoy queriendo á una chata\nY yo me chatifiqué.",2,0,-1,17,"",0,4,"e",77,0,-1,0,317,317,"7111","",0,"","","",1,0,0,[],""],["rm_t4-n7112",2,"Chata, no tienes narices,\nPorque Dios no te las dió;\nA Roma se va por todo;\nPero por narices nó.",2,0,-1,17,"",0,4,"o",2,0,-1,0,317,317,"7112","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7113",2,"Chata, mírate al espejo,\nPara que te formalices,\nY verás la grande falta\nQue te hacen las narices.",2,0,-1,17,"",0,4,"ie",113,0,-1,0,317,317,"7113","",0,"","","",1,0,0,[],""],["rm_t4-n7114",2,"Tienes una boquita\nComo un anillo,\nQue te cabe una rosca\nY un panecillo.",2,0,-1,17,"",6,4,"io",228,0,-1,0,317,317,"7114","",0,"palau_cantares","","",4,0,0,[],""],["rm_t4-n7115",2,"Desde que te bí er cogote,\nMás negro que una salea,\nNo m' asusto de la noche,\nPor oscura que la bea.",2,0,-1,17,"",0,4,"ea",54,0,-1,0,317,317,"7115","",0,"","","",1,0,0,[],""],["rm_t4-n7116",2,"Son tus brazos tan hermosos,\nQue parecen dos morcillas\nDe aquellas que están colgadas\nEn invierno en las cocinas.",2,0,-1,17,"",0,4,"ia",-1,0,-1,0,317,317,"7116","",0,"","","",3,0,0,[],""],["rm_t4-n7117",2,"Al saltar el arroyo\nTe bí los bajos;\nYo pensé qu' eran flecos\nY eran pingajos.",2,0,-1,17,"",6,4,"ao",286,0,-1,0,317,318,"7117","",0,"","","",2,0,0,[],""],["rm_t4-n7119",2,"Cuatro patas tiene un banco\nY cuatro tiene tu gata;\nCuatro el rucho de tu padre;\n¡Vaya una gente con patas!",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,318,318,"7119","",0,"","","",1,0,0,[],""],["rm_t4-n7120",2,"¡Qué bonita que no eres!\n¡Qué gracia que no me haces!\nPor Dios te pido, morena,\nQue por mi puerta no pases.",2,0,-1,17,"",0,4,"ae",287,0,-1,0,318,318,"7120","",0,"","","",3,0,0,[],""],["rm_t4-n7121",2,"Bén á berme por las noches\nCuando la luna se ba;\nQue caras como la tuya\nPierden con la clariá.",2,0,-1,17,"",0,4,"a",9,0,-1,0,318,318,"7121","",0,"","","",1,0,0,[],""],["rm_t4-n7122",2,"Señores, tengo una novia,\nBonita, si Dios quisiera;\nBlanca, si la blanquearan;\nVestida, si la vistieran.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,318,318,"7122","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7123",2,"Señores, tengo una nobia\nQue parese un angelito....\nD' esos que bienen bolando\nCuando se muere un borrico.",2,0,-1,17,"",0,4,"io",-1,0,-1,0,318,318,"7123","",0,"","","",1,0,0,[],""],["rm_t4-n7124",2,"Bas disiendo por ahí\nQue no me quieres por fea,\nSiendo tú aquér qu' asombrastes\nAr lechon en la berea.",2,0,-1,17,"",0,4,"ea",54,0,-1,0,318,318,"7124","",0,"","","",1,0,0,[],""],["rm_t4-n7125",2,"La chimenea t' aplanche,\nPrima hermana der joyin;\n¿Eres más negra qu' un grajo,\nY jases burla de mí?",2,0,-1,17,"",5,4,"i",-1,0,-1,0,319,319,"7125","",0,"","","",1,0,0,[],""],["rm_t4-n7126",2,"En la calle en que vives\n¡Maldita sea!\nViven cuatro muchachas\nA cuál más fea.\nLa más bonita\nPecosa de viruelas,\nCorta de vista.",2,0,-1,17,"",4,7,"ia",-1,0,-1,0,319,319,"7126","",0,"","","",3,0,0,[],""],["rm_t4-n7127",2,"Eres más fea qu' er mengue;\nMás negra que la morsiya;\nEr dia que tú nasistes\nNasió la sarna y la tiña.",2,0,-1,17,"",0,4,"ia",-1,0,-1,0,319,319,"7127","",0,"","","",1,0,0,[],""],["rm_t4-n7128",2,"Eres más arta qu' un güebo;\nMás derecha que una jos;\nMás blanca que mi sombrero;\nMás fea qu' un boto á Dios.",2,0,-1,17,"",0,4,"o",87,0,-1,0,319,319,"7128","",0,"","","",1,0,0,[],""],["rm_t4-n7129",2,"Eres arta como er güebo;\nBonita como la jambre;\nColorâ como la sera,\nY gorda como el alambre.",2,0,-1,17,"",0,4,"ae",288,0,-1,0,319,319,"7129","",0,"","","",2,0,0,[],""],["rm_t4-n7130",2,"Eres arta como er güebo;\nDerecha como er josino;\nBlanca como la sarten\nJarta de freí tosino.",2,0,-1,17,"",0,4,"io",199,0,-1,0,319,319,"7130","",0,"","","",2,0,0,[],""],["rm_t4-n7132",2,"Tienes la cara de pana;\nLa narís de beregena;\nEl andar de burra enana\nY er cuerpo d' una cormena.",2,0,-1,17,"",1,4,"ea",59,0,-1,0,320,320,"7132","",0,"","","",1,0,0,[],""],["rm_t4-n7133",2,"Esta noche bengo bueno\nPara cantarle á mi nobia;\nTraigo la garganta clara,\nQu' he comido sanajoria.",2,0,-1,17,"",0,4,"oa",-1,0,-1,0,320,320,"7133","",0,"","","",1,0,0,[],""],["rm_t4-n7134",2,"Quítate d' esa bentana,\nCara de burra en ayunas,\nDorniyito de gaspacho\nY esportiya d' asitunas.",2,0,-1,17,"",0,4,"ua",289,0,-1,0,320,320,"7134","",0,"","","",5,0,0,[],""],["rm_t4-n7135",2,"Quítate d' esa bentana,\nCara de burro andalús;\nLa suela de mis sapatos\nTiene más honra que tú.",2,0,-1,17,"",0,4,"u",-1,0,-1,0,320,320,"7135","",0,"","","",5,0,0,[],""],["rm_t4-n7136",2,"Quítate d' esa bentana,\nCara de choriso frito;\nQue le puedes dar un susto\nA San Antonio bendito.",2,0,-1,17,"",0,4,"io",119,0,-1,0,320,320,"7136","",0,"","","",5,0,0,[],""],["rm_t4-n7137",2,"Quítate d' esa bentana,\nCara de sardina frita;\nQue cada bes que te beo\nSe me regüerben las tripas.",2,0,-1,17,"",0,4,"ia",-1,0,-1,0,320,320,"7137","",0,"","","",5,0,0,[],""],["rm_t4-n7138",2,"Quítate d' esa bentana,\nCara de corcho quemao;\nEr dia que tú nasistes\nNasieron los condenaos.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,320,321,"7138","",0,"","","",5,0,0,[],""],["rm_t4-n7139",2,"Quítate d' esa ventana,\nCara de medio candil,\nNarices de chimenea\nY cuerpo de tamboril.",2,0,-1,17,"",0,4,"i",290,0,-1,0,321,321,"7139","",0,"","","",1,0,0,[],""],["rm_t4-n7140",2,"Quítate de esa ventana,\nEstampa de la herejía;\nEl que madrugó por verte,\n¡Qué poco sueño tendria!",2,0,-1,17,"",0,4,"ia",0,0,-1,0,321,321,"7140","",0,"","","",6,0,0,[],""],["rm_t4-n7141",2,"Asómate á esa bergüensa,\nCara de poca bentana,\nY dame un jarro de sé,\nQue m' estoy muriendo de agua.",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,321,321,"7141","",0,"","","",1,0,0,[],""],["rm_t4-n7142",2,"Asómate á esa bentana\nY echa los brasos afuera,\nY jar como que te caes,\nBerás qué jardaso pegas.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,321,321,"7142","",0,"","","",4,0,0,[],""],["rm_t4-n7143",2,"La despedía te echo,\nLa que Cristo echó en la breña:\nQue te yeben más demonios\nQue borricos ban por leña.",2,0,-1,17,"",0,4,"ea",291,0,-1,0,321,321,"7143","",0,"","","",4,0,0,[],""],["rm_t4-n7144",2,"En tu puerta me c....\nPorque ayí me dió la gana;\nAhí tienes ese clabé\nPâ que lo güelas mañana\n[Cuando sargas á barré].",2,0,-1,17,"",7,5,"e",77,0,-1,0,321,322,"7144","",0,"","","",1,0,0,[],""],["rm_t4-n7145",2,"Er peñón de Gibartá\nLo tengo romaneao;\nAsín lo tubieras tú\nEn las narises corgao.",2,0,-1,17,"",0,4,"ao",98,0,-1,0,322,322,"7145","",0,"","","",1,0,0,[],""],["rm_t4-n7146",2,"Veinticuatro palillos\nTiene una silla;\n¿Quieres que te los rompa\nEn las costillas?",2,0,-1,17,"",6,4,"ia",-1,0,-1,0,322,322,"7146","",0,"","","",1,0,0,[],""],["rm_t4-n7147",2,"Er dia que tú te cases,\nQuiera Dios que no paresca\nEr cura ni er sacristan\nNi las yabes de la iglesia.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,322,322,"7147","",0,"","","",2,0,0,[],""],["rm_t4-n7148",2,"El dia que tú te cases,\nEl cura se vuelva loco,\nEl sacristan no parezca\nNi el monaguillo tampoco.",2,0,-1,17,"",0,4,"oo",152,0,-1,0,322,322,"7148","",0,"","","",2,0,0,[],""],["rm_t4-n7150",2,"Eres morena de gusto\nY eres blanca de regalo;\nEres Cógelas-al-tiento\nY eres Mátalas-callando.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,322,322,"7150","",0,"","","",1,0,0,[],""],["rm_t4-n7151",2,"¡Caramba contigo, niña,\nQue buena vuelta vas dando,\nQue las uvas de tu viña\nOtro las va vendimiando!",2,0,-1,17,"",1,4,"ao",33,0,-1,0,322,322,"7151","",0,"","","",2,0,0,[],""],["rm_t4-n7152",2,"Ayer tarde me dijeron\nQue era usté liebre corrida;\nA la liebre corredora,\nLa escopeta prevenida.",2,0,-1,17,"",0,4,"ia",37,0,-1,0,323,323,"7152","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7153",2,"Esa mujer que ayí biene\nDejarla pasar de largo;\nQu' es una liebre corría\nMordía de muchos gargos.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,323,323,"7153","",0,"","","",1,0,0,[],""],["rm_t4-n7154",2,"Una pata tengo aquí\nY otra tengo en er tejao;\nMira si por tus quereles\nMe jayo espatarracao.",2,0,-1,17,"",0,4,"ao",98,0,-1,0,323,323,"7154","",0,"","","",2,0,0,[],""],["rm_t4-n7155",2,"Te quiero como si fueras\nCuerda de mis arpárgatas;\nMira si te quiero bien,\nQue te quiero por las patas.",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,323,323,"7155","",0,"","","",3,0,0,[],""],["rm_t4-n7157",2,"Te quiero más que al dinero;\nMás que al dinero te amo;\n¡Mira si te quiero bien,\nQue rabio por un ochavo!",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,323,323,"7157","",0,"","","",2,0,0,[],""],["rm_t4-n7158",2,"Si tú me quieres á mí,\nTe tengo de regalar\nUn tintirintin con tinta,\nCon tinta un tirintintan.",2,0,-1,17,"",5,4,"ia",-1,0,-1,0,323,323,"7158","",0,"","","",3,0,0,[],""],["rm_t4-n7159",2,"Dicen que tú no me quieres,\nPorque no tengo dinero;\nVén á mi casa y verás\nUn cuarto en un agujero.",2,0,-1,17,"",0,4,"eo",38,0,-1,0,324,324,"7159","",0,"","","",11,0,0,[],""],["rm_t4-n7160",2,"Disen que tú no me quieres,\nPorque no tengo camisa;\nYa m' están jasiendo una\nDe peyejo de tomisa.",2,0,-1,17,"",0,4,"ia",68,0,-1,0,324,324,"7160","",0,"","","",1,0,0,[],""],["rm_t4-n7162",2,"Te pusistes y dijistes:\n—Ayá ba Carsones-rotos.—\n¡Y no te pones y dises\nQue por tí bendí los otros!",2,0,-1,17,"",0,4,"oo",-1,0,-1,0,324,324,"7162","",0,"","","",2,0,0,[],""],["rm_t4-n7163",2,"En mi casa me dicen\nCalzones rotos;\nY yo digo:— ¡Caramba,\nComprarme otros!",2,0,-1,17,"",6,4,"oo",-1,0,-1,0,324,324,"7163","",0,"","","",11,0,0,[],""],["rm_t4-n7164",2,"Una bes que te lo dije\nMe dijistes qu' era chico;\nOtra bes que te lo diga\nMe subiré en un borrico.",2,0,-1,17,"",0,4,"io",141,0,-1,0,324,324,"7164","",0,"","","",1,0,0,[],""],["rm_t4-n7165",2,"De color de canario\nTe ví yo un dia\nY por eso te digo:\n— ¡Canaria mia!",2,0,-1,17,"",6,4,"a",0,0,-1,0,324,324,"7165","",0,"","","",1,0,0,[],""],["rm_t4-n7166",2,"Un morenito, niña,\nMe dió un recado,\nPara que te dijera....\n¡Se me ha olvidado!\n¡Ay! que me muero\nPor uno que se llama....\n¡Ya no me acuerdo!",2,0,-1,17,"",4,7,"eo",-1,0,-1,0,325,325,"7166","",0,"","","",2,0,0,[],""],["rm_t4-n7167",2,"—Dame la mano, niña,\nPor la gatera.\n—Si fuera la del gato,\nYo te la diera.",2,0,-1,17,"",6,4,"ea",44,0,-1,0,325,325,"7167","",0,"","","",3,0,0,[],""],["rm_t4-n7168",2,"Comadre, yo soy el solo\nPara coger gorriones:\nMetí la mano en el nido\nY saqué tres volantones.",2,0,-1,17,"",0,4,"oe",34,0,-1,0,325,325,"7168","",0,"","","",1,0,0,[],""],["rm_t4-n7169",2,"Metió etrás e la pila\nToíta la noche me tienes,\nY en cuando en cuando me dises:\n—Juye, que mi madre biene.",2,0,-1,17,"",0,4,"ee",-1,0,-1,0,325,325,"7169","",0,"","","",1,0,0,[],""],["rm_t4-n7170",2,"Una siesta de Agosto\nTe pedí un favor\nY tú me respondiste\nQue hacía calor.\nTe enseñé plata:\nSe levantó un fresquito\nQue consolaba.",2,0,-1,17,"",4,7,"aa",-1,0,-1,0,325,325,"7170","",0,"","","",1,0,0,[],""],["rm_t4-n7171",2,"Vuélvete, niña, queso;\nYo seré el ratón,\nY tu marido el gato;\n¡Verás qué función!\nY en esta broma\nEs regular que el queso\nYo me lo coma.",2,0,-1,17,"",4,7,"oa",86,0,-1,0,325,326,"7171","",0,"","","",1,0,0,[],""],["rm_t4-n7172",2,"Dises que no te conosco,\nPorque m' hago er tonto y cayo;\nJúrgame á la ropa un poco\nY berás un papagayo.",2,0,-1,17,"",0,4,"ao",293,0,-1,0,326,326,"7172","",0,"","","",1,0,0,[],""],["rm_t4-n7173",2,"Esos carcos qu' abiyelas\nEn tus pulidos pinrés\nNo se los diñes á naide,\nQue m' han costao er parné.",2,0,-1,17,"",0,4,"e",-1,0,-1,0,326,326,"7173","",0,"","","",1,0,0,[],""],["rm_t4-n7174",2,"¡Ojalay ojalara\nMi niña ojales:\nMe ojalara una chupa\nCon alamares!",2,0,-1,17,"",6,4,"ae",-1,0,-1,0,326,326,"7174","",0,"","","",1,0,0,[],""],["rm_t4-n7175",2,"Una chupa, dos chupas,\nTres chupas, cuatro,\nCinco, seis, siete chupas\nTiene mi majo.",2,0,-1,17,"",6,4,"ao",-1,0,-1,0,326,326,"7175","",0,"","","",1,0,0,[],""],["rm_t4-n7177",2,"Cuando yo te camelaba\nEstaba la mar en leche;\nAhora que no te camelo,\nSardinas en escabeche.",2,0,-1,17,"",0,4,"ee",180,0,-1,0,326,326,"7177","",0,"","","",1,0,0,[],""],["rm_t4-n7178",2,"Anda, que no te quiero,\nQue estás besada....\nQue te besó tu madre\nCuando mamabas.",2,0,-1,17,"",6,4,"aa",-1,0,-1,0,327,327,"7178","",0,"rm_t3","","",4,0,0,[],""],["rm_t4-n7179",2,"Debajo de tu ventana\nTengo un ochavo escondido;\nNo se lo digas á nadie,\nMira que somos perdidos.",2,0,-1,17,"",0,4,"io",-1,0,-1,0,327,327,"7179","",0,"fernan_caballero","","",29,0,0,[],""],["rm_t4-n7180",2,"Debajo de tu ventana\nHay un puchero con miel;\nNo se lo digas á nadie;\nNos lo vamos á comer.",2,0,-1,17,"",0,4,"e",-1,0,-1,0,327,327,"7180","",0,"","","",29,0,0,[],""],["rm_t4-n7181",2,"En tu casa llora un niño\nY tú casada no estás;\nTu padre no tiene yerno....\nEl niño, ¿de quien será?",2,0,-1,17,"",0,4,"a",-1,0,-1,0,327,327,"7181","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7183",2,"Bénte conmigo á mi biña\nY comerás chicharrones\nDe un cochino que he matado\nQue pesa tres cuarterones.",2,0,-1,17,"",0,4,"oe",34,0,-1,0,327,327,"7183","",0,"","","",1,0,0,[],""],["rm_t4-n7185",2,"Desde aquí te estoy mirando\nY tú mirándome estás;\nOjitos de pillo tienes;\nPero no me pillarás.",2,0,-1,17,"",0,4,"a",51,0,-1,0,327,328,"7185","",0,"","","",19,0,0,[],""],["rm_t4-n7187",2,"Son como los mosquitos\nTus amores, Juan;\nQue pican, hacen roncha,\nCantan y se van.",2,0,-1,17,"",0,4,"a",147,0,-1,0,328,328,"7187","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n7188",2,"Un jóven á mi madre\nDicen que obsequia,\nPor que le dé su hija\nY hacerla suegra.\nCon fino obsequio,\nLe da muchos regalos,\nPor darle nietos.",2,0,-1,17,"",4,7,"eo",-1,0,-1,0,328,328,"7188","",0,"","","",1,0,0,[],""],["rm_t4-n7189",2,"Un alcalde de corte\nEntra en mi casa;\nMás se inclina á la alcoba\nQue nó á la sala.\nPorque en la alcoba\nImpone la sentencia\nQue le acomoda.",2,0,-1,17,"",4,7,"oa",-1,0,-1,0,328,328,"7189","",0,"","","",1,0,0,[],""],["rm_t4-n7190",2,"¡Confesion, que me muero;\nQue venga el Óleo,\nY ántes que venga el cura,\nVenga mi novio!\nPor si me muero,\nÁntes que venga el cura\nYo quiero verlo.",2,0,-1,17,"",4,7,"eo",-1,0,-1,0,328,329,"7190","",0,"","","",1,0,0,[],""],["rm_t4-n7191",2,"Dígale usté á mi madre\nQue no me riña;\nQue ella tambien jugaba\nCuando era niña.\nPorque yo pienso\nEl que estas diversiones\nVan con el tiempo.",2,0,-1,17,"",4,7,"eo",-1,0,-1,0,329,329,"7191","",0,"","","",1,0,0,[],""],["rm_t4-n7192",2,"Madre, dígale usté á padre\nQue le diga á Nicolás\nQue no juegue con candela;\nQue nos podemos quemar.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,329,329,"7192","",0,"","","",2,0,0,[],""],["rm_t4-n7193",2,"Cuando te beo benir\nCon uniforme completo,\nYo no sé lo que me da:\nJaleo me pide er cuerpo.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,329,329,"7193","",0,"","","",3,0,0,[],""],["rm_t4-n7194",2,"Esta noche bendrá usté\nY entrará por er postigo;\nMi madre estará durmiendo....\n¿Entiende usté lo que digo?",2,0,-1,17,"",0,4,"io",106,0,-1,0,329,329,"7194","",0,"","","",1,0,0,[],""],["rm_t4-n7195",2,"Cuando vengas á verme,\nVén con sigilo;\nQue el perro de mi padre\nEs muy sentido.\nNo vengas tarde,\nY luégo, mas que el perro\nLadre ó no ladre.",2,0,-1,17,"",4,7,"ae",-1,0,-1,0,329,330,"7195","",0,"","","",4,0,0,[],""],["rm_t4-n7197",2,"A mí m' ha salido un nobio\nCon la pierna tiritando;\nNo sé si quererlo ahora,\nO dejarlo pá er berano.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,330,330,"7197","",0,"","","",1,0,0,[],""],["rm_t4-n7198",2,"Un novio tenía yo\nHombre de bien y sin vicios;\nPero con la devocion\nDe rezarle á San Simplicio.",2,0,-1,17,"",0,4,"io",-1,0,-1,0,330,330,"7198","",0,"","","",1,0,0,[],""],["rm_t4-n7199",2,"Si te ha dejado tu novio,\nNo tengas pena por eso;\nA mí me ha dejado el mio\nY mira cuál me divierto.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,330,330,"7199","",0,"","","",1,0,0,[],""],["rm_t4-n7200",2,"Más lo quiero blanco y frio\nQue nó moreno y con grasia:\nNo quiero ántes de la noche\nTener la oscuridá en casa.",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,330,330,"7200","",0,"","","",1,0,0,[],""],["rm_t4-n7201",2,"En el andar conosco\nQu' eres der campo;\nEn los saparratones\nY en lo gabacho.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,330,330,"7201","",0,"","","",1,0,0,[],""],["rm_t4-n7202",2,"Al paso de los bueyes\nVan los gañanes;\n¡Qué lindo paso llevan\nLos animales!",2,0,-1,17,"",6,4,"ae",-1,0,-1,0,330,330,"7202","",0,"","","",2,0,0,[],""],["rm_t4-n7203",2,"Er sor se ba poniendo\nPor los terrones;\nEr pícaro del amo,\n¡Qué cara pone!",2,0,-1,17,"",6,4,"oe",-1,0,-1,0,331,331,"7203","",0,"","","",1,0,0,[],""],["rm_t4-n7204",2,"De aperaores y guardas\nEstaba el infierno yeno,\nY en er rincon más ocurto\nEstá el arma der casero.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,331,331,"7204","",0,"","","",1,0,0,[],""],["rm_t4-n7205",2,"Er Señó mos dé pasensia\nCon estos gansos der campo;\nQu' en metiendo la cuchara,\nSe quea er plato temblando.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,331,331,"7205","",0,"","","",1,0,0,[],""],["rm_t4-n7206",2,"De Madrid ha venido\nCarta cerrada;\nPara ricos y curas\nPaja y cebada.\nY á los del campo\nPavos y buen tocino,\nDinero largo.",2,0,-1,17,"",4,7,"ao",-1,0,-1,0,331,331,"7206","",0,"","","",1,0,0,[],""],["rm_t4-n7207",2,"Arrierito es mi amante\nDe cinco mulos;\nTres y dos son del amo;\nLos demás, suyos.",2,0,-1,17,"",6,4,"uo",-1,0,-1,0,331,331,"7207","",0,"","","",2,0,0,[],""],["rm_t4-n7208",2,"Contrabandista lo quiero,\nAunque lo maten mañana;\nQue si matan al ginete,\nMe queda caballo y carga.",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,331,331,"7208","",0,"","","",3,0,0,[],""],["rm_t4-n7209",2,"Todo er dia con la pleita\nY el aniyo, dale, dale;\nPero en yegando la noche,\nCuatro cuartos no cabales.",2,0,-1,17,"",0,4,"ae",-1,0,-1,0,331,332,"7209","",0,"","","",1,0,0,[],""],["rm_t4-n7210",2,"Ni caserita de cura,\nNi criada de meson,\nNi viña junto al camino\nNo la compraria yo.",2,0,-1,17,"",0,4,"o",-1,0,-1,0,332,332,"7210","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7211",2,"Gastan las taberneras\nCruz y pendientes,\nDe las escurriduras\nDel aguardiente.",2,0,-1,17,"",6,4,"ee",-1,0,-1,0,332,332,"7211","",0,"","","",1,0,0,[],""],["rm_t4-n7212",2,"Gasta la tabernera\nPendientes de oro\nY el agua de la fuente\nLo paga todo.",2,0,-1,17,"",6,4,"oo",-1,0,-1,0,332,332,"7212","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7213",2,"Un calderero fué á misa\nY no sabia rezar,\nY andaba por los altares:\n—¿Hay calderas que adobar?",2,0,-1,17,"",0,4,"a",21,0,-1,0,332,332,"7213","",0,"","","",1,0,0,[],""],["rm_t4-n7214",2,"No te cases con herrero,\nDama de cuerpo gentil;\nQue del golpe del martillo\nNo te dejará dormir.",2,0,-1,17,"",0,4,"i",-1,0,-1,0,332,332,"7214","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7215",2,"No te cases con herrero;\nQue te puede suceder\nTirarte con el martillo\nY hacerte coja de un pié.",2,0,-1,17,"",0,4,"e",-1,0,-1,0,332,332,"7215","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7217",2,"—Lo quiero carpintero,\nQue saque astillas.\n—Hija, sí, y que las saque\nDe tus costillas.",2,0,-1,17,"",6,4,"ia",294,0,-1,0,333,333,"7217","",0,"","","",3,0,0,[],""],["rm_t4-n7218",2,"Por uno de navajas,\nMadre, me muero.\n¿Quién ha visto morirse\nPor un barbero?",2,0,-1,17,"",6,4,"eo",38,0,-1,0,333,333,"7218","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7219",2,"¡Estas sí que son fatigas!\nCasarse con un barbero,\nAcostarse sin cenar,\nY amanecer sin dinero.",2,0,-1,17,"",0,4,"eo",38,0,-1,0,333,333,"7219","",0,"","","",1,0,0,[],""],["rm_t4-n7220",2,"Cásate, vida mia,\nCon un barbero\nY toda la semana\nTendrás puchero.\nPero se advierte\nQue el puchero está lleno\nDe agua caliente.",2,0,-1,17,"",4,7,"ee",-1,0,-1,0,333,333,"7220","",0,"","","",2,0,0,[],""],["rm_t4-n7221",2,"Un sapatero y un sastre\nY un ofisiar de barbero\nSon tres personas distintas\nY ninguno berdadero.",2,0,-1,17,"",0,4,"eo",38,0,-1,0,333,333,"7221","",0,"","","",1,0,0,[],""],["rm_t4-n7222",2,"De los sapateriyos\nNo digo nada;\nQue los dan á manojos,\nComo ensalada.",2,0,-1,17,"",6,4,"aa",49,0,-1,0,333,334,"7222","",0,"","","",1,0,0,[],""],["rm_t4-n7223",2,"Yeban los sapateros\nEn er cogote\nUn letrero que dise:\n«¡Biba er serote!»",2,0,-1,17,"",6,4,"oe",292,0,-1,0,334,334,"7223","",0,"","","",1,0,0,[],""],["rm_t4-n7224",2,"A la puerta de un sastre\nTodas son tiras;\nA la de un zapatero,\nTodas mentiras.",2,0,-1,17,"",6,4,"ia",295,0,-1,0,334,334,"7224","",0,"","","",3,0,0,[],""],["rm_t4-n7225",2,"Yo quiero á un zapatero,\nYo quiero á un sastre,\nPara que uno me vista\nY otro me calce.",2,0,-1,17,"",6,4,"ae",-1,0,-1,0,334,334,"7225","",0,"","","",3,0,0,[],""],["rm_t4-n7226",2,"Un zapatero y un sastre\nFueron al infierno juntos;\nEl uno se fué por varas\nY el otro se fué por puntos.",2,0,-1,17,"",0,4,"uo",296,0,-1,0,334,334,"7226","",0,"palau_cantares","","",9,0,0,[],""],["rm_t4-n7227",2,"Por si acaso me caso\nCon algun sastre,\nPor un cuarto de agujas\nVoy al instante.",2,0,-1,17,"",6,4,"ae",-1,0,-1,0,334,334,"7227","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7228",2,"Me casé con un sastre\nPor no estar mala,\nY el aire de la aguja\nMe resfriaba.",2,0,-1,17,"",6,4,"aa",-1,0,-1,0,334,334,"7228","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7229",2,"Soy sastre y tengo conciencia\nY tengo temor de Dios;\nA nádie le quito nada,\nSino de tres varas dos.",2,0,-1,17,"",0,4,"o",87,0,-1,0,334,335,"7229","",0,"","","",3,0,0,[],""],["rm_t4-n7230",2,"Las tijeras de los sastres\nVan diciendo:—Rapa, rapa;\nCon este pedazo y otro\nTenemos para una capa.",2,0,-1,17,"",0,4,"aa",297,0,-1,0,335,335,"7230","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7231",2,"Si me quieres, te arbierto\nQue soy arbañí;\nUna peseta gano\nY ésa es para mí.",2,0,-1,17,"",0,4,"i",23,0,-1,0,335,335,"7231","",0,"","","",1,0,0,[],""],["rm_t4-n7232",2,"Todos los arbañiles\nNasen encueros,\nY por eso les yaman\nTapa-bujeros.",2,0,-1,17,"",6,4,"eo",22,0,-1,0,335,335,"7232","",0,"","","",1,0,0,[],""],["rm_t4-n7233",2,"Con los musiquitos, niña,\nPoquita conversacion;\nPorque siempre están pensando\nEn el do, re, mi, fa, sol.",2,0,-1,17,"",0,4,"o",-1,0,-1,0,335,335,"7233","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7234",2,"Un escribano y un gato\nEn un pozo se cayeron,\nY, como ambos tenian uñas,\nArañando se salieron.",2,0,-1,17,"",0,4,"eo",105,0,-1,0,335,335,"7234","",0,"","","",5,0,0,[],""],["rm_t4-n7235",2,"Un escribano y un gato\nSe cayeron en un pozo,\nY, como ambos tenian uñas,\nLe arañaba el uno al otro.",2,0,-1,17,"",0,4,"oo",-1,0,-1,0,335,335,"7235","",0,"","","",5,0,0,[],""],["rm_t4-n7236",2,"El reloj y el escribano\nSon de un mismo movimiento;\nQue en faltándole la cuerda,\nLos dos se paran á un tiempo.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,335,336,"7236","",0,"","","",3,0,0,[],""],["rm_t4-n7237",2,"Un pájaro con cien plumas\nNo se puede mantener,\nY un escribano con una\nMantiene casa y mujer\n[Y dama si tiene alguna].",2,0,-1,17,"",7,5,"ua",56,0,-1,0,336,336,"7237","",0,"","","",5,0,0,[],""],["rm_t4-n7238",2,"La mujer del escribano\nLleva vestido de indiana;\n¡El demonio de la pluma,\nY cuánto dinero gana!",2,0,-1,17,"",0,4,"aa",4,0,-1,0,336,336,"7238","",0,"","","",3,0,0,[],""],["rm_t4-n7240",2,"Primero que suba al cielo\nEl alma de un escribano\nTintero, papel y pluma\nHan de bailar el fandango.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,336,336,"7240","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n7241",2,"La mujer del cirujano,\nMédico y enterrador,\nNo come con su marido,\nPorque le da asco y horror.",2,0,-1,17,"",0,4,"o",72,0,-1,0,336,336,"7241","",0,"","","",1,0,0,[],""],["rm_t4-n7242",2,"No te enamores, niña,\nDe lo barato;\nBeintisinco paquetes\nDan por un cuarto.",2,0,-1,17,"",6,4,"ao",-1,0,-1,0,336,336,"7242","",0,"","","",4,0,0,[],""],["rm_t4-n7243",2,"Se parece el señorito\nA aquel reló de Pamplona,\nQue estaba apunta que apunta,\nY nunca daba la hora.",2,0,-1,17,"",0,4,"oa",-1,0,-1,0,337,337,"7243","",0,"","","",1,0,0,[],""],["rm_t4-n7244",2,"Yo tube un nobio paquete\nY lo puse en er basar;\nSe lo comieron los gatos,\nPensando qu' era pescâ.",2,0,-1,17,"",5,4,"e",-1,0,-1,0,337,337,"7244","",0,"","","",2,0,0,[],""],["rm_t4-n7245",2,"Yo tube un nobio paquete\nY le atraqué la castora;\nTenía tiriya tiesa;\n¡Por poquito si se ajoga!",2,0,-1,17,"",0,4,"oa",-1,0,-1,0,337,337,"7245","",0,"","","",2,0,0,[],""],["rm_t4-n7246",2,"Mare, yo quiero á un flamenco,\nPorque yo soy flamenquiya;\nPorque yo no quiero cursis,\nQu' ensusian muchas tiriyas.",2,0,-1,17,"",0,4,"ia",-1,0,-1,0,337,337,"7246","",0,"","","",1,0,0,[],""],["rm_t4-n7247",2,"Un usía en Granada\nMurió de ahito;\nQue se cenó en tres noches\nUn huevo frito.",2,0,-1,17,"",6,4,"io",119,0,-1,0,337,337,"7247","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7248",2,"¿Que le sirbe á los usías\nCamelar á lo señó,\nSi le farta la sandunga\nA la mejor ocasion?",2,0,-1,17,"",0,4,"o",-1,0,-1,0,337,337,"7248","",0,"","","",1,0,0,[],""],["rm_t4-n7249",2,"Si andaran de cabesa\nLos lechuguinos,\n¿Caeria algun cuarto\nDe sus bolsillos?",2,0,-1,17,"",6,4,"io",-1,0,-1,0,337,337,"7249","",0,"","","",1,0,0,[],""],["rm_t4-n7250",2,"Iban tres señoritos\nPor la Campana,\nTapándose la jambre\nCon la gufanda.\nY uno desia:\n—Señores, yo no tengo\nPâ echar er dia.",2,0,-1,17,"",4,7,"a",-1,0,-1,0,338,338,"7250","",0,"","","",1,0,0,[],""],["rm_t4-n7251",2,"Fábrica de tabacos,\nBentanas pocas,\nRecreo de charranes,\nJardin de locas.\n¡Si te cayeras\nY cogieras debajo\nLas sigarreras!",2,0,-1,17,"",4,7,"ea",103,0,-1,0,338,338,"7251","",0,"","","",1,0,0,[],""],["rm_t4-n7252",2,"La primer sigarrera\nQue bino ar mundo\nLa parió una gitana,\nLa crió un mulo.\nTubo fortuna;\nQu' un borrico mojino\nMesió su cuna.",2,0,-1,17,"",4,7,"ua",56,0,-1,0,338,338,"7252","",0,"","","",1,0,0,[],""],["rm_t4-n7254",2,"Yo tengo un novio cadete,\nY otro novio capitan,\nY otro que ronda mi calle,\nY otro que á mi casa va.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,338,339,"7254","",0,"","","",3,0,0,[],""],["rm_t4-n7255",2,"Si quieres vivir alegre,\nCásate con un corneta;\nPor la mañana, ¡diana!\nY por la noche, ¡retreta!",2,0,-1,17,"",0,4,"ea",200,0,-1,0,339,339,"7255","",0,"","","",2,0,0,[],""],["rm_t4-n7256",2,"Cásate, vida mia,\nCon un corneta,\nY tendrás tururu\nSiempre á la puerta.",2,0,-1,17,"",6,4,"ea",-1,0,-1,0,339,339,"7256","",0,"","","",2,0,0,[],""],["rm_t4-n7257",2,"Cásate con un sargento;\nTodas las noches tendrás:\n—¡Compañía por er sentro!\n¡Por la derecha! ¡Aliniar!",2,0,-1,17,"",0,4,"a",-1,0,-1,0,339,339,"7257","",0,"","","",1,0,0,[],""],["rm_t4-n7258",2,"A mi amante lo han hecho\nCarabinero;\nSiempre á los buenos mozos\nLes dan empleo.",2,0,-1,17,"",6,4,"eo",-1,0,-1,0,339,339,"7258","",0,"","","",1,0,0,[],""],["rm_t4-n7259",2,"Un sacristan me quiere\nY un monaguillo;\nToda la sacristía\nTraigo conmigo.",2,0,-1,17,"",6,4,"io",-1,0,-1,0,339,339,"7259","",0,"","","",1,0,0,[],""],["rm_t4-n7260",2,"Al entrar en la iglesia,\nDije:—¡Aleluya!\nSacristan de mi alma,\nToda soy tuya.",2,0,-1,17,"",6,4,"ua",111,0,-1,0,339,339,"7260","",0,"","","",1,0,0,[],""],["rm_t4-n7261",2,"De mujer que habla poco,\nQue hace calceta\nY que reza en visita,\nDios nos defienda.\nY de beatas,\nQue son la quinta esencia\nDel agua mansa.",2,0,-1,17,"",4,7,"aa",-1,0,-1,0,339,340,"7261","",0,"","","",1,0,0,[],""],["rm_t4-n7262",2,"Yo me arrimé á una beata,\nPor tener algo de Dios;\nA ella se la llevó el diablo\nY á mí poco me faltó.",2,0,-1,17,"",0,4,"o",-1,0,-1,0,340,340,"7262","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7263",2,"Un fraile y una monja\nY una beata,\nTres personas distintas;\nNinguna santa.",2,0,-1,17,"",6,4,"aa",-1,0,-1,0,340,340,"7263","",0,"","","",1,0,0,[],""],["rm_t4-n7264",2,"A las oraciones\nCierran los conventos;\n¡Pobresitos frailes,\nQue se quedan dentro!",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,340,340,"7264","",0,"","","",1,0,0,[],""],["rm_t4-n7265",2,"Cuatro frailes franciscos,\nCuatro del Cármen,\nCuatro de la Victoria,\nSon doce frailes.",2,0,-1,17,"",6,4,"ae",-1,0,-1,0,340,340,"7265","",0,"carrizo_salta, leonesas_diez, palau_cantares","","",5,0,0,[],""],["rm_t4-n7266",2,"Todas las mujeres son\nMedrosas, como usté sabe;\nQue se asustan de un raton,\nY no se asustan de un fraile\n[Que es un animal mayor].",2,0,-1,17,"",7,5,"o",-1,0,-1,0,340,340,"7266","",0,"","","",3,0,0,[],""],["rm_t4-n7267",2,"Los frailes de San Francisco\nHan sembrado un melonar;\nEl demonio de los frailes,\n¡Qué melones no tendrán!",2,0,-1,17,"",0,4,"a",-1,0,-1,0,340,341,"7267","",0,"","","",2,0,0,[],""],["rm_t4-n7268",2,"De San Francisco salieron\nCuatro reverendos padres:\nFray Pimiento, fray Cebolla,\nFray Aceite y fray Vinagre.",2,0,-1,17,"",0,4,"ae",-1,0,-1,0,341,341,"7268","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7269",2,"Arrímate á los frailes,\nNiña, si puedes,\nPorque llevan corona,\nComo los reyes.",2,0,-1,17,"",6,4,"ee",-1,0,-1,0,341,341,"7269","",0,"","","",1,0,0,[],""],["rm_t4-n7270",2,"¿Eras tú la que decias\nQue en tu casa no entran frailes,\nY los han visto salir\nComo del campo las aves?",2,0,-1,17,"",0,4,"ae",-1,0,-1,0,341,341,"7270","",0,"","","",3,0,0,[],""],["rm_t4-n7271",2,"¿Qué te puede dar un fraile,\nGrandísima picarona,\nSi le hacen de por Dios\nEl cerquillo y la corona?",2,0,-1,17,"",0,4,"oa",7,0,-1,0,341,341,"7271","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7272",2,"Un fraile me pretende;\nYo no soy boba,\nPorque atranco la puerta\nCon una escoba.",2,0,-1,17,"",6,4,"oa",298,0,-1,0,341,341,"7272","",0,"","","",1,0,0,[],""],["rm_t4-n7273",2,"Un fraile me pidió un beso\nUn lúnes por la mañana;\nYo le dije:—Padre mio,\nBuen principio de semana.",2,0,-1,17,"",1,4,"aa",4,0,-1,0,341,341,"7273","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7274",2,"Un fraile me pidió un beso;\nYo no se lo quise dar;\nQue los besos de los frailes\nSaben á huevos sin sal.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,341,342,"7274","",0,"","","",4,0,0,[],""],["rm_t4-n7275",2,"Un fraile me dijo un dia:\n—Dame la mano, salero.—\nYo le dije: —Padre mio,\nCoja usté la del mortero.",2,0,-1,17,"",0,4,"eo",38,0,-1,0,342,342,"7275","",0,"","","",3,0,0,[],""],["rm_t4-n7276",2,"Tengo yo un tio en Roma,\nFraile agustino,\nQue le gustan las chicas,\nComo al sobrino.\nY es evidente\nQue le gustan las chicas\nDe quince á veinte.",2,0,-1,17,"",4,7,"ee",-1,0,-1,0,342,342,"7276","",0,"","","",1,0,0,[],""],["rm_t4-n7277",2,"Me enamoré de un fraile\nPor el silencio,\nY al instante lo supo\nTodo el convento.",2,0,-1,17,"",6,4,"eo",-1,0,-1,0,342,342,"7277","",0,"","","",1,0,0,[],""],["rm_t4-n7278",2,"Un fraile me dió voces\nDesde una huerta,\nQue si queria caña\nPara una rueca.\nYo le respondí:\n—No es usté mala caña,\nMe parece á mí.",2,0,-1,17,"",4,7,"i",23,0,-1,0,342,342,"7278","",0,"","","",1,0,0,[],""],["rm_t4-n7279",2,"Ayer tarde, pasando\nPor el Loreto,\nSalió un fraile y me dijo\nQue entrara dentro.\nMe enseñaria\nEl convento, la torre,\nLa sacristía.",2,0,-1,17,"",4,7,"ia",-1,0,-1,0,342,343,"7279","",0,"","","",1,0,0,[],""],["rm_t4-n7280",2,"Camino de Sevilla\nVan doce frailes;\nTodos llevan alforjas,\nChicas ó grandes.\nVan doce monjas,\nEn busca de los frailes\nDe las alforjas.",2,0,-1,17,"",4,7,"oa",-1,0,-1,0,343,343,"7280","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t4-n7281",2,"Ponle en el patio, niña,\nLa cama al padre;\nQue aunque es nuestro pariente,\nAl fin es fraile.",2,0,-1,17,"",6,4,"ae",-1,0,-1,0,343,343,"7281","",0,"","","",1,0,0,[],""],["rm_t4-n7282",2,"Si fueres á la iglesia,\nPonte en lo oscuro,\nPorque el padre fray Pedro\nNo es muy seguro.\nPero te advierto\nQue tan bueno es fray Pablo\nComo fray Pedro.",2,0,-1,17,"",4,7,"eo",-1,0,-1,0,343,343,"7282","",0,"","","",1,0,0,[],""],["rm_t4-n7283",2,"Se lamentaba un fraile\nDe dormir solo;\n¡Quién pudiera en su celda\nMeterle un toro!\nSu reverencia\nEn él encontraria\nLa penitencia.",2,0,-1,17,"",4,7,"ea",46,0,-1,0,343,343,"7283","",0,"","","",1,0,0,[],""],["rm_t4-n7284",2,"Para el obispo, la mitra;\nPara el notario, el tintero;\nPara los chicos, las chicas;\nPara los frailes, ¡un cuerno!",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,343,344,"7284","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7285",2,"Si los frailes comieran\nChinas der rio,\nNo estubieran tan gordos\nNi tan lusíos.",2,0,-1,17,"",6,4,"io",-1,0,-1,0,344,344,"7285","",0,"","","",1,0,0,[],""],["rm_t4-n7286",2,"¡Quién tubiera la dicha\nDe ber á un fraile\nEn er brocar d' un poso\nY arrempujarle!",2,0,-1,17,"",6,4,"ae",-1,0,-1,0,344,344,"7286","",0,"","","",1,0,0,[],""],["rm_t4-n7287",2,"El bonete del cura\nVa por el rio,\nY el cura va diciendo:\n— ¡Bonete mió!",2,0,-1,17,"",6,4,"o",2,0,-1,0,344,344,"7287","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n7288",2,"Siento sincuenta curas\nSe condenaron,\nPor unas naguas blancas\nQue dibisaron.",2,0,-1,17,"",6,4,"ao",41,0,-1,0,344,344,"7288","",0,"","","",1,0,0,[],""],["rm_t4-n7289",2,"Todo cuanto me pongo\nMe lo murmuran,\nHasta una cinta verde\nQue me dió un cura.",2,0,-1,17,"",6,4,"ua",-1,0,-1,0,344,344,"7289","",0,"","","",1,0,0,[],""],["rm_t4-n7290",2,"Me dijistes que era un gato\nEl que entró por tu ventana;\nEn mi vida he visto yo\nGato negro con sotana.",2,0,-1,17,"",0,4,"aa",4,0,-1,0,344,344,"7290","",0,"","","",1,0,0,[],""],["rm_t4-n7291",2,"Estaba un gato negro\nEn un tejao\nY le hasía á la gata:\n—Miau, miau.—\nY se asegura\nQue el gato negro era\nEl padre cura.",2,0,-1,17,"",4,7,"ua",17,0,-1,0,344,345,"7291","",0,"","","",1,0,0,[],""],["rm_t4-n7292",2,"¿De qué le sirve al cura\nLa librería,\nSi en visitar comadres\nSe le va el dia?",2,0,-1,17,"",6,4,"a",0,0,-1,0,345,345,"7292","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t4-n7293",2,"Señor cura, usté procura\nLlevar mi mujer al huerto;\nSeñor cura, usté procura\nQue yo le caliente el cuerpo.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,345,345,"7293","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7294",2,"El cura y el sacristan\nAndaban á bonetazos,\nPorque el cura se llevaba\nA la sacristana en brazos.",2,0,-1,17,"",0,4,"ao",132,0,-1,0,345,345,"7294","",0,"","","",1,0,0,[],""],["rm_t4-n7295",2,"Ya no dicen las madres:\n«Que viene el coco;»\nQue esta voz á los niños\nLe asusta poco.\nSi el caso apura,\nLe dicen:—Calla, niño,\nQue viene el cura.",2,0,-1,17,"",4,7,"ua",17,0,-1,0,345,345,"7295","",0,"","","",1,0,0,[],""],["rm_t4-n7296",2,"Mi amante está entenguerengue\nEn el úrtimo pimpoyo:\nEn biniendo un aire fuerte\nSe lo yeban los demonios.",2,0,-1,17,"",0,4,"oo",-1,0,-1,0,345,346,"7296","",0,"","","",1,0,0,[],""],["rm_t4-n7297",2,"Para cuando me case,\nYa tengo dote;\nQue me lo dió mi padre\nCon un garrote.",2,0,-1,17,"",6,4,"oe",292,0,-1,0,346,346,"7297","",0,"fernan_caballero, palau_cantares","","",6,0,0,[],""],["rm_t4-n7298",2,"Para cuando me case,\nYa tengo gato;\nYa no tiene mi padre\nQue darme tanto.\nTambien yo creo\nQue el que case conmigo\nLlevará perro.",2,0,-1,17,"",4,7,"eo",-1,0,-1,0,346,346,"7298","",0,"","","",6,0,0,[],""],["rm_t4-n7299",2,"Mi padre para casarme\nMandóme cuanto tenía:\nMandóme la perra á medias\nY la gata á media cria.",2,0,-1,17,"",0,4,"ia",0,0,-1,0,346,346,"7299","",0,"","","",1,0,0,[],""],["rm_t4-n7300",2,"Si me caso contigo,\nMe da mi madre\nUn olivar que tiene\nPuesto en el aire.",2,0,-1,17,"",6,4,"ae",-1,0,-1,0,346,346,"7300","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7301",2,"Más bale ser jaragan,\nManteneor de cantiyos\nQue nó que mos pian pan\nLa mujer y los chiquiyos.",2,0,-1,17,"",0,4,"io",299,0,-1,0,346,346,"7301","",0,"","","",1,0,0,[],""],["rm_t4-n7302",2,"Más valiera ser soldado\nÓ en algún convento fraile\nQue nó mantener mujer,\nAl precio que el trigo vale.",2,0,-1,17,"",0,4,"ae",-1,0,-1,0,346,346,"7302","",0,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["rm_t4-n7303",2,"Al año de casado\nTuve tres penas:\nHambre, poco dinero,\nDolor de muelas.",2,0,-1,17,"",6,4,"ea",-1,0,-1,0,346,347,"7303","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7304",2,"Yo me casé con un viejo,\nPor hartarme de reir;\nLe puse la cama en alto\nY no se podia subir.",2,0,-1,17,"",0,4,"i",157,0,-1,0,347,347,"7304","",0,"","","",2,0,0,[],""],["rm_t4-n7305",2,"Yo me casé con un viejo,\nPor comer algo caliente;\nLa hornilla estaba apagada\nY yo convidando gente.",2,0,-1,17,"",0,4,"ee",15,0,-1,0,347,347,"7305","",0,"","","",2,0,0,[],""],["rm_t4-n7307",2,"A mi mujer en la lengua\nLe mordió un perro rabioso;\nEnseguida busqué ar perro\nY lo atraqué de biscochos.",2,0,-1,17,"",0,4,"oo",-1,0,-1,0,347,347,"7307","",0,"","","",1,0,0,[],""],["rm_t4-n7308",2,"Al revés de los hombres\nEs mi marido:\nHoy le da la tersiana;\nMañana er frio.",2,0,-1,17,"",6,4,"o",-1,0,-1,0,347,347,"7308","",0,"","","",1,0,0,[],""],["rm_t4-n7309",2,"Mi marido me dice\nQue me componga;\n¿Qué querrá ese demonio\nQue yo me ponga?",2,0,-1,17,"",6,4,"oa",300,0,-1,0,347,347,"7309","",0,"fernan_caballero","","",3,0,0,[],""],["rm_t4-n7310",2,"Mi marido me dise\nQue no le ayudo;\nCuando se ba cayendo,\nYo lo arrempujo.",2,0,-1,17,"",6,4,"uo",-1,0,-1,0,347,348,"7310","",0,"","","",1,0,0,[],""],["rm_t4-n7312",2,"Mi marido y el tuyo\nSon dos maridos;\nCuando van á la plaza\nSon dos perdidos.",2,0,-1,17,"",6,4,"io",255,0,-1,0,348,348,"7312","",0,"","","",4,0,0,[],""],["rm_t4-n7313",2,"Mi marido fué á las Indias,\nY me trajo un delantal;\nCada vez que me lo pongo,\nMe dan ganas de bailar.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,348,348,"7313","",0,"","","",9,0,0,[],""],["rm_t4-n7314",2,"Mi marido fué á las Indias\nY me trajo una ventosa;\nPara oficial de barbero,\nPrincipio quieren las cosas.",2,0,-1,17,"",0,4,"oa",-1,0,-1,0,348,348,"7314","",0,"","","",9,0,0,[],""],["rm_t4-n7315",2,"Mi marido fué á las Indias\nEn busca de un capital;\nTrajo mucho que decir;\nPero poco que contar.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,348,348,"7315","",0,"","","",9,0,0,[],""],["rm_t4-n7316",2,"Mi marido está en la cama;\nYo estoy á su cabecera,\nCon el rosario en la mano,\nPidiendo á Dios que se muera.",2,0,-1,17,"",0,4,"ea",44,0,-1,0,348,348,"7316","",0,"","","",2,0,0,[],""],["rm_t4-n7317",2,"Mi marido se murió\nY lo enterré en la cosina;\nY, de pena que me dió,\nMe puse á bailar ensima.",2,0,-1,17,"",0,4,"ia",-1,0,-1,0,348,349,"7317","",0,"","","",12,0,0,[],""],["rm_t4-n7318",2,"Mi marido se murió;\nDios en el cielo le tenga\nY le tenga tan tenido,\nQue por acá nunca vuelva.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,349,349,"7318","",0,"","","",12,0,0,[],""],["rm_t4-n7319",2,"Si tu marido es celoso,\nDale á comer chicharrones;\nY verás, con la manteca,\nQué suavito que se pone.",2,0,-1,17,"",0,4,"oe",-1,0,-1,0,349,349,"7319","",0,"","","",7,0,0,[],""],["rm_t4-n7320",2,"Tengo un marío seloso\nQue no me deja bibir;\nDe ese mar que se resela,\nDe ese mesmo ha de morir.",2,0,-1,17,"",0,4,"i",157,0,-1,0,349,349,"7320","",0,"","","",1,0,0,[],""],["rm_t4-n7321",2,"Tu marido y el mio\nSe han peleado;\nSe dijeron cabrones\nY han acertado.",2,0,-1,17,"",6,4,"ao",14,0,-1,0,349,349,"7321","",0,"","","",1,0,0,[],""],["rm_t4-n7322",2,"Mi marido y el tuyo\nVan á Linares,\nA comprar cuatro bueyes;\nVendrán tres pares.",2,0,-1,17,"",6,4,"ae",164,0,-1,0,349,349,"7322","",0,"","","",4,0,0,[],""],["rm_t4-n7323",2,"Anoche soñé un ensueño;\nMal haya mi tontería:\nQue mi marido era sastre\nY con los cuernos cosia.",2,0,-1,17,"",5,4,"oa",-1,0,-1,0,349,349,"7323","",0,"","","",7,0,0,[],""],["rm_t4-n7324",2,"Me encontré á mi marido\nManos á boca;\nFuí corriendo y le dije:\n— Carnero, topa.",2,0,-1,17,"",3,4,"oa",-1,0,-1,0,349,350,"7324","",0,"","","",1,0,0,[],""],["rm_t4-n7325",2,"Mi marido en los toros\nBien se divierte;\nCada uno se alegra\nDe ver su gente.",2,0,-1,17,"",6,4,"ee",-1,0,-1,0,350,350,"7325","",0,"","","",1,0,0,[],""],["rm_t4-n7326",2,"Mi marido no es sabio,\nPero es prudente;\nNo es hombre de fortuna,\nPero es de suerte.\nTengo esperanza\nQue á la ocasion primera\nSalga á la plaza.",2,0,-1,17,"",4,7,"aa",-1,0,-1,0,350,350,"7326","",0,"","","",1,0,0,[],""],["rm_t4-n7327",2,"Mi marido es un santo,\nQue sube al cielo,\nCoronado de espinas....\nDel matadero.\nY estas espinas\nMi marido las tiene,\nNo le lastiman.",2,0,-1,17,"",4,7,"ia",-1,0,-1,0,350,350,"7327","",0,"","","",1,0,0,[],""],["rm_t4-n7328",2,"Si supiera que arabas\nCon bueyes negros,\nYo te daria moñas\nPara los cuernos.\nTe las doy á tí;\nPóntelas y conserva\nEste dón de mí.",2,0,-1,17,"",4,7,"i",23,0,-1,0,350,350,"7328","",0,"","","",1,0,0,[],""],["rm_t4-n7330",2,"Mi marido en la era,\nYo con un fraile;\n¡Aire porque no venga!\nAire y más aire!\nY el estribillo,\nPor andar en la era,\nLo cogió el trillo.",2,0,-1,17,"",4,7,"io",228,0,-1,0,351,351,"7330","",0,"","","",1,0,0,[],""],["rm_t4-n7331",2,"Mi marido en el monte\nGuardando ovejas,\nY yo con perendengues\nEn las orejas.\n¡Viva mi Marcos,\nQue me da lo que gana\nAllá en el campo!",2,0,-1,17,"",4,7,"ao",-1,0,-1,0,351,351,"7331","",0,"","","",1,0,0,[],""],["rm_t4-n7332",2,"Yo no me caso este año,\nPor no caer en la percha;\nPorque las lunas anuncian\nDe cuernos grandes cosechas.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,351,351,"7332","",0,"","","",1,0,0,[],""],["rm_t4-n7333",2,"Casarme, yo me casara;\nQue el casarse es cosa buena;\nPero le temo al camino\nQue va de Cabra á Lucena.",2,0,-1,17,"",0,4,"ea",59,0,-1,0,351,351,"7333","",0,"","","",1,0,0,[],""],["rm_t4-n7334",2,"Si te casas, llevarás\nDe San Marcos la bandera;\nQue es larga la cofradía\nY hay muchos cabos en ella.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,351,351,"7334","",0,"","","",2,0,0,[],""],["rm_t4-n7335",2,"La noche que me casé\nDí una vuelta por mi cuarto\nY en un rincón encontré\nLa bandera de San Marcos.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,352,352,"7335","",0,"","","",1,0,0,[],""],["rm_t4-n7336",2,"Yo conosí á un hombre e bien\nAcostarse bueno y sano,\nY amanesió al otro dia\nCon un cuerno en cada mano.",2,0,-1,17,"",0,4,"ao",81,0,-1,0,352,352,"7336","",0,"","","",2,0,0,[],""],["rm_t4-n7337",2,"El hombre que á su mujer\nNo l' entrega lo que gana,\nLo jasen luégo marqués\nDe la gran siudad de Cabra\n[Cabron, que m' equiboqué].",2,0,-1,17,"",7,5,"e",-1,0,-1,0,352,352,"7337","",0,"","","",1,0,0,[],""],["rm_t4-n7338",2,"Sin que me crezca el pelo,\n¡Ay, qué rareza!\nNo puedo con el peso\nDe la cabeza.\nY en tal infierno,\nMe dice mi chiquilla:\n—¡Jesús, qué cuerno!",2,0,-1,17,"",4,7,"eo",225,0,-1,0,352,352,"7338","",0,"","","",1,0,0,[],""],["rm_t4-n7339",2,"Tropecé con un cuerno;\nDijo una chusca:\n—En mi casa hay un árbol\nQue echa esa fruta.—\nDijo otra entónces:\nEn mi casa los tienen\nTodos los hombres.",2,0,-1,17,"",4,7,"oe",-1,0,-1,0,352,352,"7339","",0,"","","",1,0,0,[],""],["rm_t4-n7340",2,"A los toros corriendo\nVan con gran priesa\nMuchos que merecian\nQue los corrieran.\nTal vez va al lado\nQuien les hace la gracia\nDe convidados.",2,0,-1,17,"",4,7,"ao",-1,0,-1,0,352,353,"7340","",0,"","","",1,0,0,[],""],["rm_t4-n7341",2,"En la plasa de los toros\nUna mujer dió un chiyío,\nPorque un toro que salió\nLe paresió su marío.",2,0,-1,17,"",0,4,"io",3,0,-1,0,353,353,"7341","",0,"","","",1,0,0,[],""],["rm_t4-n7342",2,"Compadre, yo he bisto un toro\nEn la plasa de Jerés;\nCompadre, ¡si usté lo biera!\nTodo se parese á usté.",2,0,-1,17,"",0,4,"e",-1,0,-1,0,353,353,"7342","",0,"","","",1,0,0,[],""],["rm_t4-n7343",2,"En un dia de toros\nDijo un marido:\n—Por no tener un cuarto,\nMe hallo corrido.\nY así, no quiero\nIr á ver mis parientes\nSin el dinero.",2,0,-1,17,"",4,7,"eo",38,0,-1,0,353,353,"7343","",0,"","","",1,0,0,[],""],["rm_t4-n7344",2,"Lloraba un niño en la cuna\nY su madre le decía:\n—Calla, que te coge el toro;—\nY era el padre, que venía.",2,0,-1,17,"",0,4,"ia",0,0,-1,0,353,353,"7344","",0,"","","",1,0,0,[],""],["rm_t4-n7345",2,"Llora un niño en la cuna,\nDice su madre:\n—Calla, que viene el toro;—\nY era su padre.\nDice el marido:\n—O esta puerta ha menguado,\nO yo he crecido.",2,0,-1,17,"",4,7,"io",101,0,-1,0,353,354,"7345","",0,"","","",1,0,0,[],""],["rm_t4-n7346",2,"Un viejo recien-casado\nGuardaba mucho su viña;\nSe encontró con el rebusco,\nCuando fué á hacer la vendimia.",2,0,-1,17,"",0,4,"ia",-1,0,-1,0,354,354,"7346","",0,"","","",2,0,0,[],""],["rm_t4-n7347",2,"Una mujer no muy buena\nLlevó á su casa un carnero\nY le dijo á su marido:\n—Topa con tu compañero.",2,0,-1,17,"",0,4,"eo",38,0,-1,0,354,354,"7347","",0,"","","",1,0,0,[],""],["rm_t4-n7348",2,"Tiraba cierta dama\nUn cuerno al aire\nY el marido le dijo:\n— Mira lo que haces.\nNo andes con fiestas,\nPorque pegarme puedes\nEn la cabeza.",2,0,-1,17,"",4,7,"ea",-1,0,-1,0,354,354,"7348","",0,"","","",1,0,0,[],""],["rm_t4-n7349",2,"Un cuerno en una calle\nSe halló un usía\nY se quedó pensando\nDe quién sería.\nHecho una pieza,\nNo quitaba las manos\nDe su cabeza.",2,0,-1,17,"",4,7,"ea",108,0,-1,0,354,354,"7349","",0,"","","",1,0,0,[],""],["rm_t4-n7350",2,"A un médico muy sabio\nDijo un enfermo:\n—¿Por qué cuanto yo como\nMe sabe á cuerno?—\nY él con presteza\nLe dijo: —Eso procede\nDe la cabeza.",2,0,-1,17,"",4,7,"ea",108,0,-1,0,354,355,"7350","",0,"","","",1,0,0,[],""],["rm_t4-n7351",2,"Peinándose un casado,\nDijo á su esposa:\n—Mira qué es ese enredo\nQue tanto estorba.—\nY dijo ella:\n—Son las puas del peine\nLas que se enredan.",2,0,-1,17,"",4,7,"ea",-1,0,-1,0,355,355,"7351","",0,"","","",1,0,0,[],""],["rm_t4-n7352",2,"Un cazador famoso\nMal advertido,\nPor matar un venado,\nMató un marido.\nY dijo al verlo:\n—Le miré á la cabeza\nY ése fué el yerro.",2,0,-1,17,"",4,7,"eo",-1,0,-1,0,355,355,"7352","",0,"","","",1,0,0,[],""],["rm_t4-n7353",2,"El cazador casado\nNo mate ciervos;\nQue se quedan en casa\nLuégo los cuernos,\nY á los amigos\nSatisfecho les dice:\n—Estos son mios.",2,0,-1,17,"",4,7,"o",-1,0,-1,0,355,355,"7353","",0,"","","",1,0,0,[],""],["rm_t4-n7354",2,"Un zapatero y un sastre\nSe comieron un melon;\nEl sastre se volvió cabra\nY el zapatero cabron.",2,0,-1,17,"",0,4,"o",31,0,-1,0,355,355,"7354","",0,"","","",9,0,0,[],""],["rm_t4-n7355",2,"Un zapatero furioso\nLe decia á su mujer:\n—Como te pille\ncon otro,\nTe doy con el tirapié.",2,0,-1,17,"",7,5,"e",-1,0,-1,0,355,356,"7355","",0,"","","",1,0,0,[],""],["rm_t4-n7356",2,"El casado que logra\nSer bien sufrido\nViento en popa camina\nA Puerto-Rico.\nY aunque naufrague,\nUna mitra, á lo ménos,\nNo ha de faltarle.",2,0,-1,17,"",4,7,"ae",-1,0,-1,0,356,356,"7356","",0,"","","",1,0,0,[],""],["rm_t4-n7357",2,"Casados sin empleo\nComen y visten;\nYo no sé en que demonios\nEsto consiste.\nSin duda alguna\nQue, aunque no haya vergüenza,\nTendrán fortuna.",2,0,-1,17,"",4,7,"ua",56,0,-1,0,356,356,"7357","",0,"","","",1,0,0,[],""],["rm_t4-n7358",2,"Bastantes hermandades\nAquí encontramos;\nPero es la más completa\nLa de San Marcos.\nY con sus fondos\nSe mantienen á veces\nSus mayordomos.",2,0,-1,17,"",4,7,"oo",-1,0,-1,0,356,356,"7358","",0,"","","",1,0,0,[],""],["rm_t4-n7359",2,"El animal más fiero\nEs el marido;\nPero algunas le temen\nMénos que á un niño.\nPues los hay tales,\nQue de ser hombres pierden\nLos memoriales.",2,0,-1,17,"",4,7,"ae",26,0,-1,0,356,356,"7359","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n7360",2,"Riñen muchos maridos\nCon sus mujeres,\nCuando hablan con alguno\nQue oro no tiene.\nCon el que gasta,\nHacen la vista gorda,\nChupan y callan.",2,0,-1,17,"",4,7,"aa",-1,0,-1,0,357,357,"7360","",0,"","","",1,0,0,[],""],["rm_t4-n7361",2,"Parecidos á los dientes\n(Dijo un cabron) son los cuernos:\nQue incomodan al nacer\nY al fin se come con ellos.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,357,357,"7361","",0,"","","",1,0,0,[],""],["rm_t4-n7362",2,"Un perro con un cuerno\nHuye que rabia,\nY un hombre con doscientos\nSe aguanta y calla.",2,0,-1,17,"",6,4,"aa",-1,0,-1,0,357,357,"7362","",0,"","","",1,0,0,[],""],["rm_t4-n7363",2,"Dichoso puede llamarse\nEl que con cuernos tropieza;\nPorque mueve con los piés\nLo que otros con la cabeza.",2,0,-1,17,"",0,4,"ea",108,0,-1,0,357,357,"7363","",0,"","","",2,0,0,[],""],["rm_t4-n7364",2,"Tengo una tia y me quiere\nComo si fuera mi madre:\n¡Siempre que compra ensalada\nMe da las hojas más grandes!",2,0,-1,17,"",0,4,"ae",-1,0,-1,0,357,357,"7364","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7365",2,"Un ochabo de perro\nMe dió mi tio:\n—Toma, para que gastes\nLargo y tendío.\n¡Gasta ligero,\nQue pá las ocasiones\nSirbe er dinero!",2,0,-1,17,"",4,7,"eo",38,0,-1,0,357,358,"7365","",0,"","","",1,0,0,[],""],["rm_t4-n7366",2,"En Madrid tengo un tio\nQue es confitero\nY que me da confites....\nPor mi dinero.",2,0,-1,17,"",6,4,"eo",38,0,-1,0,358,358,"7366","",0,"","","",1,0,0,[],""],["rm_t4-n7367",2,"Yo tengo un tio cura,\nQue, si me muero,\nMe enterrará de balde....\nPor mi dinero.",2,0,-1,17,"",6,4,"eo",38,0,-1,0,358,358,"7367","",0,"","","",1,0,0,[],""],["rm_t4-n7368",2,"Cuchillos de dos filos\nSon las cuñadas;\n¡Ay de mí, que mi amante\nTiene una hermana!",2,0,-1,17,"",6,4,"aa",-1,0,-1,0,358,358,"7368","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n7370",2,"De suegras y cuñadas\nVa un barco lleno:\n¡Mira qué linda carga\nPara el infierno!",2,0,-1,17,"",6,4,"eo",-1,0,-1,0,358,358,"7370","",0,"","","",3,0,0,[],""],["rm_t4-n7371",2,"Mi suegro me quiere mucho\nY su hija mucho más;\nY á la indina de mi suegra\nNo la puedo contrastar.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,358,358,"7371","",0,"","","",1,0,0,[],""],["rm_t4-n7372",2,"Es tanto lo que me quiere\nLa madre de mi mujer,\nTanto la ciega el cariño....\nQue no me puede ni ver.",2,0,-1,17,"",0,4,"e",20,0,-1,0,358,359,"7372","",0,"","","",1,0,0,[],""],["rm_t4-n7373",2,"Si una suegra de azúcar\nDicen que amarga,\n¿Qué será al que la tenga\nDe carne humana?",2,0,-1,17,"",6,4,"aa",-1,0,-1,0,359,359,"7373","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7374",2,"¡Quién tuviera la dicha\nDe Adan y Eva,\nPorque nunca tuvieron\nSuegro ni suegra!\nTambien lograron\nLibrarse de cuñadas\nY de cuñados.",2,0,-1,17,"",4,7,"ao",-1,0,-1,0,359,359,"7374","",0,"palau_cantares","","",6,0,0,[],""],["rm_t4-n7375",2,"Quisiera estar tan cérca\nDe las mujeres\nComo están las estampas\nDe las paredes.\nY de mi suegra\nComo estamos nosotros\nDe las estrellas.",2,0,-1,17,"",4,7,"ea",-1,0,-1,0,359,359,"7375","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7377",2,"La vieja de mi suegra\nMe dió unas medias;\nCada vez que reñimos\nMe quedo en piernas.",2,0,-1,17,"",6,4,"ea",-1,0,-1,0,359,359,"7377","",0,"carrizo_salta, palau_cantares","","",7,0,0,[],""],["rm_t4-n7378",2,"La vieja de mi suegra\nMe dió unos cuadros;\nCada vez que reñimos\nLos descolgamos.\nDe esta manera,\nA cuestas siempre andamos\nCon la escalera.",2,0,-1,17,"",4,7,"ea",44,0,-1,0,360,360,"7378","",0,"palau_cantares","","",7,0,0,[],""],["rm_t4-n7379",2,"Una sarten sin rabo\nMe dió mi suegra;\nCada vez que reñimos\nLa sarten suena.\nPero es el caso\nQue siempre que reñimos\nHay sartenazo.",2,0,-1,17,"",4,7,"ao",43,0,-1,0,360,360,"7379","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7380",2,"Con mi suegra me reñí,\nPorque me dijo «tunante.»\nYo le dije:—Tía jilí,\nBamos cayando, y alante.",2,0,-1,17,"",1,4,"ae",47,0,-1,0,360,360,"7380","",0,"","","",1,0,0,[],""],["rm_t4-n7381",2,"No sé qué tiene mi suegra,\nQue cuando la miro llora;\n¿Con qué le pagaré yo\nEl cariño á esta señora?",2,0,-1,17,"",0,4,"oa",107,0,-1,0,360,360,"7381","",0,"","","",1,0,0,[],""],["rm_t4-n7382",2,"De cáscara de avellana\nTengo de hacer un baul,\nPara meter á mi suegra,\nQue no se la lleve el bú.",2,0,-1,17,"",0,4,"u",-1,0,-1,0,360,360,"7382","",0,"","","",1,0,0,[],""],["rm_t4-n7383",2,"Del hueso de una aceituna\nHe de hacer un barquichuelo,\nPara mandar á mi suegra\nA los profundos infiernos.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,360,360,"7383","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t4-n7384",2,"Más allá del infierno\nCincuenta leguas\nHay un infierno aparte\nPara las suegras.",2,0,-1,17,"",6,4,"ea",-1,0,-1,0,361,361,"7384","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n7385",2,"A mi suegra, de coraje,\nLe ha caido erisipela;\n¿Qué cuidado me da á mí\nQue ese demonio se muera?",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,361,361,"7385","",0,"","","",4,0,0,[],""],["rm_t4-n7386",2,"A mi suegra, de coraje,\nSe l' está cayendo el moño;\n¿Qué cuidado me da á mí\nQue se la yebe er demonio?",2,0,-1,17,"",0,4,"oo",-1,0,-1,0,361,361,"7386","",0,"","","",4,0,0,[],""],["rm_t4-n7387",2,"A mi suegra, de coraje,\nSe l' está cayendo er pelo;\n¿Qué cuidado me da á mí\nQue se la coman los perros?",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,361,361,"7387","",0,"","","",4,0,0,[],""],["rm_t4-n7388",2,"Glorioso San Sebastian,\nTodo yeno de saetas;\nMi arma, como la tuya;\nComo tu cuerpo, mi suegra.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,361,361,"7388","",0,"","","",9,0,0,[],""],["rm_t4-n7389",2,"Glorioso San Sebastian,\nSanto cabal y perfecto;\nMi alma, como la tuya;\nMi suegra, como tu cuerpo.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,361,361,"7389","",0,"","","",9,0,0,[],""],["rm_t4-n7390",2,"Veinticinco alfileres\nMe dió mi suegra;\n¡Veinticinco demonios\nCarguen con ella!",2,0,-1,17,"",6,4,"ea",-1,0,-1,0,361,361,"7390","",0,"","","",1,0,0,[],""],["rm_t4-n7391",2,"A mi suegra la quiero\nComo á las ubas;\nCorgaditas der techo\nLas asaduras.",2,0,-1,17,"",6,4,"ua",-1,0,-1,0,362,362,"7391","",0,"","","",1,0,0,[],""],["rm_t4-n7392",2,"¡Ay, quién viera á mi suegra\nEn una sima,\nCon aulagas debajo,\nPiedras encima!",2,0,-1,17,"",6,4,"ia",302,0,-1,0,362,362,"7392","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7393",2,"El dia que á mi suegra\nLe den el Óleo,\n¡Qué dia tan alegre\nTendrá el demonio!",2,0,-1,17,"",6,4,"oo",-1,0,-1,0,362,362,"7393","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7394",2,"El que quisiere mandar\nMemorias á los infiernos,\nLa ocasion la pintan calva:\nMi suegra se está muriendo.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,362,362,"7394","",0,"","","",2,0,0,[],""],["rm_t4-n7395",2,"Ya se murió mi suegra;\nVoy al entierro;\nUn casco de cebolla\nLlevo en el pecho.",2,0,-1,17,"",6,4,"eo",-1,0,-1,0,362,362,"7395","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n7397",2,"La fortuna me sigue,\nQue no me deja,\nPorque puse los ojos\nEn una vieja.",2,0,-1,17,"",6,4,"ea",165,0,-1,0,362,362,"7397","",0,"","","",1,0,0,[],""],["rm_t4-n7398",2,"Ciento cincuenta viejas\nMe dan que guarde;\nPor Jesús que las mato,\nAunque las pague.\nPorque nos quitan\nQue pelemos la pava\nCon las mocitas.",2,0,-1,17,"",4,7,"ia",-1,0,-1,0,363,363,"7398","",0,"","","",1,0,0,[],""],["rm_t4-n7399",2,"Una carga de viejas\nLlevé á Calañas;\nEn mi vida he tenido\nVenta más mala.",2,0,-1,17,"",6,4,"aa",-1,0,-1,0,363,363,"7399","",0,"","","",1,0,0,[],""],["rm_t4-n7400",2,"Una bieja y un candí,\nLa ruïna d' una casa:\nLa bieja por lo que gruñe\nY er candí por lo que mancha.",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,363,363,"7400","",0,"","","",2,0,0,[],""],["rm_t4-n7401",2,"Una vieja revieja\nDijo al pan duro:\n—Si te pillara en sopas,\nYo te aseguro....",2,0,-1,17,"",6,4,"uo",248,0,-1,0,363,363,"7401","",0,"","","",1,0,0,[],""],["rm_t4-n7402",2,"Una vieja barriendo\nSe encontró un cuarto;\nDe perilla le vino,\nPara tabaco.",2,0,-1,17,"",6,4,"ao",-1,0,-1,0,363,363,"7402","",0,"","","",1,0,0,[],""],["rm_t4-n7403",2,"Una bieja en Granada\nRebentó hilando,\nY por eso las biejas\nHilan temblando.",2,0,-1,17,"",6,4,"ao",33,0,-1,0,363,363,"7403","",0,"","","",1,0,0,[],""],["rm_t4-n7404",2,"Una vieja se murió\nY dejó en el testamento\nQue la enterraran de balde,\nPorque no llevaba suelto.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,363,364,"7404","",0,"","","",1,0,0,[],""],["rm_t4-n7405",2,"El que se quiera reir,\nVaya á la orilla del mar\nY verá cuatro gallegos\nMerendando queso y pan.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,364,364,"7405","",0,"","","",1,0,0,[],""],["rm_t4-n7407",2,"Los gallegos en Galicia\nCuando van en procesion,\nLlevan un gato por santo\nY una vieja por pendon.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,364,364,"7407","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t4-n7408",2,"Los gallegos en Galicia\nDicen que no beben vino;\nY con el vino que beben\nPuede moler un molino.",2,0,-1,17,"",0,4,"io",199,0,-1,0,364,364,"7408","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t4-n7411",2,"Para borrico, un gayego;\nPara borracho, un fransés;\nPara piyo, un seviyano;\nY ladron, un montañés.",2,0,-1,17,"",0,4,"e",218,0,-1,0,364,365,"7411","",0,"","","",1,0,0,[],""],["rm_t4-n7412",2,"En la bahía de Cádis\nUna negrita yoraba,\nQue queria ser blanquita,\nAunque fuera catalana.",2,0,-1,17,"",0,4,"aa",-1,0,-1,0,365,365,"7412","",0,"","","",2,0,0,[],""],["rm_t4-n7414",2,"Se parece al suizo\nDoña Rufina;\nQue al sol que más calienta,\nA ese se inclina.",2,0,-1,17,"",6,4,"ia",11,0,-1,0,365,365,"7414","",0,"","","",1,0,0,[],""],["rm_t4-n7415",2,"Un inglés bino á Sebiya\nA oir cantar las peteneras;\nD' embobao que se quedó,\nSe le perdió la chistera.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,365,365,"7415","",0,"","","",1,0,0,[],""],["rm_t4-n7416",2,"Más de cuatrosientos carbos\nSe fueron á confesar,\nY les dijo er padre cura:\n—¿S' ha buerto ésto un melonar?",2,0,-1,17,"",0,4,"a",21,0,-1,0,365,365,"7416","",0,"","","",1,0,0,[],""],["rm_t4-n7417",2,"Harto trabajo tiene\nLa legañosa;\nQue por abrir los ojos,\nAbre la boca.",2,0,-1,17,"",6,4,"oa",-1,0,-1,0,365,365,"7417","",0,"","","",1,0,0,[],""],["rm_t4-n7418",2,"Ojos de marinero\nTiene mi amante:\nUno mira al poniente\nY otro al levante.",2,0,-1,17,"",6,4,"ae",47,0,-1,0,365,366,"7418","",0,"","","",1,0,0,[],""],["rm_t4-n7419",2,"Toda mi vida andando\nTras de una tuerta;\n¡Ojos de ciquitroque,\nCuánto me cuestas!",2,0,-1,17,"",6,4,"ea",-1,0,-1,0,366,366,"7419","",0,"","","",1,0,0,[],""],["rm_t4-n7420",2,"¡Mire usté con la grasia\nQue mira un tuerto,\nCon un ojo serrado\nY el otro abierto!",2,0,-1,17,"",6,4,"eo",88,0,-1,0,366,366,"7420","",0,"","","",1,0,0,[],""],["rm_t4-n7421",2,"—La vista recogida\nMucho penetra.—\nEsto dijo una niña,\nPorque era tuerta.",2,0,-1,17,"",6,4,"ea",-1,0,-1,0,366,366,"7421","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n7422",2,"Jugando á la pelota\nEstaba un tuerto,\nY de un golpe le quitan\nEl ojo bueno.\nY él, muy conforme,\nDice:—Tengan ustedes\nMuy buenas noches.",2,0,-1,17,"",4,7,"oe",-1,0,-1,0,366,366,"7422","",0,"","","",3,0,0,[],""],["rm_t4-n7423",2,"Un jorobado me ronda\nLas tapias de mi corral.\n¿Qué querrá este jorobado?\n¡Si me querrá jorobar!",2,0,-1,17,"",0,4,"a",-1,0,-1,0,366,366,"7423","",0,"","","",4,0,0,[],""],["rm_t4-n7424",2,"Un cojo tropezó en Cádiz\nY en Sevilla se cayó;\nHasta Madrid fué rodando\nY en Francia se levantó.",2,0,-1,17,"",0,4,"o",2,0,-1,0,366,367,"7424","",0,"","","",1,0,0,[],""],["rm_t4-n7425",2,"En Cádis tropesó un cojo\nY en Madrí pegó er porraso;\nEn Fransia se lebantó\nY á Jaen yegó á pedasos.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,367,367,"7425","",0,"","","",1,0,0,[],""],["rm_t4-n7428",2,"Un cojo cayó en un poso,\nY otro cojo lo sacó,\nY otro cojo le desia:\n—Cojo, ¿quién t' arrempujó?",2,0,-1,17,"",0,4,"o",2,0,-1,0,367,367,"7428","",0,"","","",1,0,0,[],""],["rm_t4-n7429",2,"Un sordo le dijo á un siego:\n—Mira la liebre cuár ba.—\nY er siego le dijo ar sordo:\n—Escúchale las pisâs.",2,0,-1,17,"",5,4,"i",-1,0,-1,0,367,367,"7429","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t4-n7430",2,"Cantaba coplas un mudo\nA la puerta de un estanco;\nOyéndole estaba un sordo\nY un ciego estaba mirando.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,367,367,"7430","",0,"","","",1,0,0,[],""],["rm_t4-n7431",2,"Estaba un mudo cantando,\nY un sordo le estaba oyendo,\nY un ciego estaba mirando,\nY pasó un cojo corriendo.",2,0,-1,17,"",1,4,"eo",52,0,-1,0,367,368,"7431","",0,"","","",1,0,0,[],""],["rm_t4-n7432",2,"A la puerta de un sordo\nCantaba un mudo\nY un ciego le miraba\nCon disimulo.\nY dentro un cojo\nBailaba seguidillas\nCon desahogo.",2,0,-1,17,"",4,7,"oo",-1,0,-1,0,368,368,"7432","",0,"","","",2,0,0,[],""],["rm_t4-n7434",2,"Un manco escribió una carta;\nUn siego la está mirando;\nUn mudo la está leyendo\nY un sordo la está escuchando.",2,0,-1,17,"",0,4,"ao",33,0,-1,0,368,368,"7434","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t4-n7436",2,"Con el ruido de las nueces\nSalió un fraile del peral:\n—¿Quién manda coger las uvas,\nSiendo mio el melonar?",2,0,-1,17,"",0,4,"a",-1,0,-1,0,368,368,"7436","",0,"","","",1,0,0,[],""],["rm_t4-n7437",2,"M' embarqué en una abeyana\nPara ir á Berbería,\nA buscar pelo de rana,\nPorque en España no habia.",2,0,-1,17,"",1,4,"aa",-1,0,-1,0,369,369,"7437","",0,"","","",1,0,0,[],""],["rm_t4-n7438",2,"Yo he visto á un gato segar,\nY á un raton coger espigas,\nY á una gallina trillar....\nNo lo creas que es mentira.",2,0,-1,17,"",0,4,"ia",-1,0,-1,0,369,369,"7438","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7439",2,"Un águila y un leon\nY un escarabajo blanco\nSe pusieron á jugar\nA la sombra de un barranco.",2,0,-1,17,"",0,4,"ao",303,0,-1,0,369,369,"7439","",0,"","","",1,0,0,[],""],["rm_t4-n7440",2,"En Ronda perdí un sapato,\nEn Lebrija lo encontré,\nEn la Puebla me lo puse\nY en Sebiya me lo até.",2,0,-1,17,"",0,4,"e",77,0,-1,0,369,369,"7440","",0,"","","",1,0,0,[],""],["rm_t4-n7441",2,"En Sevilla soy francés,\nEn Francia soy sevillano,\nEn Valencia aragonés\nY en Aragon valenciano.",2,0,-1,17,"",1,4,"ao",81,0,-1,0,369,369,"7441","",0,"","","",1,0,0,[],""],["rm_t4-n7442",2,"En la calle no sé dónde\nMataron yo no sé á quién;\nEl vivo cayó en el suelo\nY el muerto se echó á correr.",2,0,-1,17,"",0,4,"e",-1,0,-1,0,369,369,"7442","",0,"","","",5,0,0,[],""],["rm_t4-n7443",2,"En un lugar, no sé dónde,\nHay un yo no sé qué santo,\nQue en rezando no sé qué,\nSe gana yo no sé cuánto.",2,0,-1,17,"",0,4,"ao",30,0,-1,0,369,369,"7443","",0,"","","",1,0,0,[],""],["rm_t4-n7444",2,"Allá arriba, no sé dónde,\nEn casa número tantos,\nSe vende yo no sé qué\nY vale yo no sé cuánto.",2,0,-1,17,"",0,4,"ao",-1,0,-1,0,370,370,"7444","",0,"","","",4,0,0,[],""],["rm_t4-n7446",2,"Tengo siento beinte años,\nQue los cumplí por Enero,\nY Margarita me yamo,\nComo lo dirá mi agüelo.",2,0,-1,17,"",0,4,"eo",-1,0,-1,0,370,370,"7446","",0,"","","",1,0,0,[],""],["rm_t4-n7447",2,"Se entristese el arma mida\nCuando paso y no te bedo;\nPorque m' ha dicho tu tida\nQue no me quieres, por fedo.",2,0,-1,17,"",1,4,"eo",304,0,-1,0,370,370,"7447","",0,"","","",1,0,0,[],""],["rm_t4-n7448",2,"Es cierto que te he quisido\nY siempre te estoy quisiendo;\nY el amor que te he tuvido,\nEl mismo te estoy tuviendo.",2,0,-1,17,"",1,4,"eo",52,0,-1,0,370,370,"7448","",0,"","","",2,0,0,[],""],["rm_t4-n7449",2,"Por mi puerta pasaste\nY estornudiste;\nSola estaba yo entónces;\n¿Por qué no entriste?\nNo me arrempijes;\nQue si me he equivoquido,\nYa así lo dije.",2,0,-1,17,"",4,7,"ie",-1,0,-1,0,370,371,"7449","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7450",2,"Cuando los cantitos gayan\nY cuando los ladros perran,\nTengo los tiesos tan dedos,\nQue hasta las tiemblas me piernan.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,371,371,"7450","",0,"","","",1,0,0,[],""],["rm_t4-n7451",2,"Desgranando habichuelas,\nDijo una dama:\n—Toíto esto lo jago\nDe mala gana.\nY es cosa triste\nJacer toíto aquello\nQue se resiste.",2,0,-1,17,"",4,7,"ie",153,0,-1,0,371,371,"7451","",0,"","","",1,0,0,[],""],["rm_t4-n7452",2,"El tocar la guitarra\nNo quiere cencia,\nSino fuerza en la mano\n' Perseverencia.",2,0,-1,17,"",6,4,"ea",46,0,-1,0,371,371,"7452","",0,"","","",3,0,0,[],""],["rm_t4-n7453",2,"Cuatro cosas bien dichas\nDice la gente:\nHespital, cerujano,\nJonega y juente.",2,0,-1,17,"",6,4,"ee",15,0,-1,0,371,371,"7453","",0,"","","",2,0,0,[],""],["rm_t4-n7454",2,"Tres dias tiene el año\nDe solemnicio:\nTreniá, Corpus Crisque\nY el Ascensicio.",2,0,-1,17,"",6,4,"io",305,0,-1,0,371,371,"7454","",0,"","","",1,0,0,[],""],["rm_t4-n7455",2,"Er profeta Jeremidas\nYa está en er monte Sidon,\nA cumplir las profesidas\nQue l' anunsió Simedon.",2,0,-1,17,"",5,4,"eo",-1,0,-1,0,371,371,"7455","",0,"","","",1,0,0,[],""],["rm_t4-n7456",2,"Una tarde á San Pedro\nLe dijo Cristo:\n—Ahi te entriego las llaves\nY abur, Perico.—\nY él le responde:\n—Vaya usté descudiao,\nQue aquí quea un hombre.",2,0,-1,17,"",4,7,"oe",-1,0,-1,0,372,372,"7456","",0,"","","",1,0,0,[],""],["rm_t4-n7457",2,"San Pedro, como era carbo,\nLe picaban los mosquitos,\nY su madre le desia:\n—Ponte 'r gorro, Periquito.",2,0,-1,17,"",0,4,"io",-1,0,-1,0,372,372,"7457","",0,"","","",1,0,0,[],""],["rm_t4-n7458",2,"San Juan y la Madalena\nJugaban al esconder;\nSan Juan le tiró un sapato,\nPorque no jugaba bien.",2,0,-1,17,"",0,4,"e",-1,0,-1,0,372,372,"7458","",0,"","","",1,0,0,[],""],["rm_t4-n7460",2,"¡Ay, bárgame San Crispin,\nSan Juan, San Pedro y San Roque,\nLa Bírgen der Trochipin\nY todos sus palitroques!",2,0,-1,17,"",0,4,"oe",-1,0,-1,0,372,372,"7460","",0,"","","",1,0,0,[],""],["rm_t4-n7462",2,"Glorioso San Sebastian,\nSiruelo te conosí;\nLos milagros que tú jagas\nQue me los claben aquí.",2,0,-1,17,"",0,4,"i",23,0,-1,0,373,373,"7462","",0,"","","",9,0,0,[],""],["rm_t4-n7464",2,"Hasta ayer no supe yo\nQue al que se muere lo entierran;\nYo creí que lo llevaban\nA beber á una taberna.",2,0,-1,17,"",0,4,"ea",-1,0,-1,0,373,373,"7464","",0,"","","",2,0,0,[],""],["rm_t4-n7465",2,"Quien pregunta no yerra;\nY yo pregunto\nSi se entierran los muertos\nCon los difuntos.",2,0,-1,17,"",6,4,"uo",-1,0,-1,0,373,373,"7465","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n7466",2,"La primer bes que te bí\nNo hay duda que te miré;\nY si no estabas sentado,\nEra que estabas de pié.",2,0,-1,17,"",0,4,"e",77,0,-1,0,373,373,"7466","",0,"","","",1,0,0,[],""],["rm_t4-n7467",2,"Si quieres que las damas\nTras de tí anden,\nCuando vayan andando,\nPonte delante.",2,0,-1,17,"",6,4,"ae",-1,0,-1,0,373,373,"7467","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7470",2,"Veinticinco pesetas\nSon cien rëales;\nEn faltando un ochavo,\nNo están cabales.",2,0,-1,17,"",6,4,"ae",26,0,-1,0,374,374,"7470","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n7471",2,"En mi tierra se dice\nPor cosa cierta\nDe que tres y tres hacen\nMedia docena.\nY no lo dudo;\nQue allí todos sabemos\nDe cuentas mucho.",2,0,-1,17,"",4,7,"uo",-1,0,-1,0,374,374,"7471","",0,"","","",1,0,0,[],""],["rm_t4-n7472",2,"El tabaco de polvo,\nSegun se dice,\nSe toma en todas partes\nPor las narices.",2,0,-1,17,"",6,4,"ie",-1,0,-1,0,374,374,"7472","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n7474",2,"En mi casa hay un patio\nTan particular,\nQue en lloviendo, se moja,\nComo los demás.",2,0,-1,17,"",0,4,"a",-1,0,-1,0,374,374,"7474","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n7477",2,"Estudiante soy tunante,\nQue voy corriendo la tuna,\nEngañando á las mujeres,\nSin casarme con ninguna.",2,0,-1,18,"",0,4,"ua",56,0,-1,0,391,391,"7477","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7478",2,"La sotana y el manteo\nMorena, yo te daré;\nPero en tocando á casaca,\nLiberanos, Domine.",2,0,-1,18,"",5,4,"ie",-1,0,-1,0,391,391,"7478","",0,"","","",2,0,0,[],""],["rm_t4-n7479",2,"La mujer que no ha tenido\nAmor con un estudiante,\nNo sabe lo que es canela\nNi tampoco chocolate.",2,0,-1,18,"",0,4,"ae",-1,0,-1,0,391,391,"7479","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7480",2,"Vale más un estudiante\nQue estudia filosofía\nQue todos los mequetrefes\nQue están en las oficinas.",2,0,-1,18,"",0,4,"ia",-1,0,-1,0,391,391,"7480","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7481",2,"El primer amor que tenga\nHa de ser un estudiante,\nQue aunque no tenga dinero,\nGaste fachenda bastante.",2,0,-1,18,"",0,4,"ae",47,0,-1,0,392,392,"7481","",0,"","","",6,0,0,[],""],["rm_t4-n7482",2,"Si el amor del estudiante\nFuera cosa permanente,\nNo hubiera nada en el mundo\nQue fuera tan excelente.",2,0,-1,18,"",0,4,"ee",15,0,-1,0,392,392,"7482","",0,"","","",1,0,0,[],""],["rm_t4-n7483",2,"El amor del estudiante\nEs un amor muy profundo;\nEs como la leña verde:\nPoca lumbre y mucho humo.",2,0,-1,18,"",0,4,"uo",-1,0,-1,0,392,392,"7483","",0,"","","",2,0,0,[],""],["rm_t4-n7484",2,"A los estudiantes, niña,\nCompara con las sardinas:\nSaladitas, con escamas,\nPoca carne y mucha espina.",2,0,-1,18,"",0,4,"ia",-1,0,-1,0,392,392,"7484","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n7486",2,"Los estudiantes en clase\nSe dicen unos á otros:\n—Todas las niñas bonitas\nSe crian para nosotros.",2,0,-1,18,"",0,4,"oo",306,0,-1,0,392,392,"7486","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7487",2,"Los estudiantillos, madre,\nCuando salen del estudio,\nSe van á los arrabales\nY allí la juegan de puño.",2,0,-1,18,"",0,4,"uo",-1,0,-1,0,392,392,"7487","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7488",2,"Contra el nó de las muchachas\nEsta receta aprendí:\nCuézase en agua de olvido\nFlor de ¿qué se me da á mí?",2,0,-1,19,"",0,4,"i",23,0,-1,0,393,393,"7488","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7489",2,"Un estudiante á una niña\nLe estaba dando besitos,\nY su madre les decia:\n—¡Miren qué par de angelitos!",2,0,-1,19,"",0,4,"io",254,0,-1,0,393,393,"7489","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7490",2,"El otro dia en paseo\nSe ha perdido un estudiante,\nY ha venido á parecer\nDebajo de un miriñaque.",2,0,-1,19,"",0,4,"ae",-1,0,-1,0,393,393,"7490","",0,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["rm_t4-n7491",2,"Cinco estudiantes venimos\nY uno se ha quedado atrás,\nA desatarle á una niña\nLa cinta del delantal.",2,0,-1,19,"",0,4,"a",-1,0,-1,0,393,393,"7491","",0,"","","",2,0,0,[],""],["rm_t4-n7492",2,"Cinco estudiantes venimos\nDe Salamanca sin padre\nY venimos predicando\nEl evangelio del hambre.",2,0,-1,19,"",0,4,"ae",-1,0,-1,0,393,393,"7492","",0,"","","",2,0,0,[],""],["rm_t4-n7493",2,"Si en mi libro hubiera damas\nComo la que estoy mirando,\nToda la noche y el dia\nMe los pasara estudiando.",2,0,-1,19,"",0,4,"ao",33,0,-1,0,393,393,"7493","",0,"","","",3,0,0,[],""],["rm_t4-n7494",2,"Señorita del balcon,\nDígale usté á su papá\nQue nos eche medio duro\nPara esta noche cenar.",2,0,-1,19,"",0,4,"a",-1,0,-1,0,393,393,"7494","",0,"","","",3,0,0,[],""],["rm_t4-n7495",2,"Señorita del balcon,\nNo corra usté la cortina,\nQue la viene á visitar\nEsta pobre estudiantina.",2,0,-1,19,"",0,4,"ia",11,0,-1,0,394,394,"7495","",0,"","","",3,0,0,[],""],["rm_t4-n7496",2,"Caballero generoso,\nDénos usté una peseta,\nQue tenemos la barriga\nComo cañon de escopeta.",2,0,-1,19,"",0,4,"ea",200,0,-1,0,394,394,"7496","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7497",2,"A estos pobres estudiantes\nDe cuchara y aceituna,\nDéles usté una peseta,\nQue van corriendo la tuna.",2,0,-1,19,"",0,4,"ua",56,0,-1,0,394,394,"7497","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7498",2,"Señor mio Jesucristo,\nDios y hombre verdadero,\nA mí me llegan las trampas\nHasta el mismo tragadero.",2,0,-1,19,"",0,4,"eo",38,0,-1,0,394,394,"7498","",0,"","","",2,0,0,[],""],["rm_t4-n7499",2,"Padre mio, castigadme\nCon un pan y dos perdices,\nUna botella de vino\nY una muchacha de á quince.",2,0,-1,19,"",0,4,"ie",-1,0,-1,0,394,394,"7499","",0,"","","",1,0,0,[],""],["rm_t4-n7500",2,"Cuando un estudiante llega\nA la esquina de una plaza,\nDicen las revendedoras:\n—¡Fuera ese perro de caza!",2,0,-1,19,"",0,4,"aa",307,0,-1,0,394,394,"7500","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n7501",2,"De una cuchara de palo\nQue tenía un estudiante\nSe fabricaron las puertas\nDel castillo de Alicante.",2,0,-1,19,"",0,4,"ae",47,0,-1,0,394,394,"7501","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7502",2,"Las armas del estudiante\nYo te diré cuáles son:\nLa sotana y el manteo,\nLa cuchara y el perol.",2,0,-1,19,"",0,4,"o",-1,0,-1,0,395,395,"7502","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7503",2,"¿No hay quien me compre una cosa\nDe tres que traigo á vender?\nUna hambre, una cuchara\nY unas ganas de comer.",2,0,-1,19,"",0,4,"e",20,0,-1,0,395,395,"7503","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7504",2,"La capa del estudiante\nParece un jardin de flores,\nToda llena de remiendos\nDe veinticinco colores.",2,0,-1,19,"",0,4,"oe",5,0,-1,0,395,395,"7504","",0,"","","",3,0,0,[],""],["rm_t4-n7505",2,"Si queréis saber, señores,\nLa vida del estudiante,\nComer poco y andar mucho,\nLa miseria por delante.",2,0,-1,19,"",0,4,"ae",47,0,-1,0,395,395,"7505","",0,"","","",9,0,0,[],""],["rm_t4-n7506",2,"Desde que soy estudiante,\nDesde que llevo manteos,\nNo he comido más que sopas\nCon suelas de zapatero.",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,395,395,"7506","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7507",2,"Es tanta la hambre que tengo,\nQue me apura y me sofoca;\nDesde que soy estudiante\nNo he comido más que sopas.",2,0,-1,19,"",0,4,"oa",-1,0,-1,0,395,395,"7507","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7508",2,"Es tanta la hambre que tengo,\nQue ahora mismo me comiera\nLos poyos de ese balcon\nY el cuerpo de esa morena.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,395,395,"7508","",0,"","","",4,0,0,[],""],["rm_t4-n7509",2,"Me comiera, me comiera,\nMe comiera sin sentir\nLos poyos de la Carrera,\nPlaza Nueva y Zacatín.",2,0,-1,19,"",0,4,"i",-1,0,-1,0,396,396,"7509","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7510",2,"De la mucha hambre que tengo,\nSantísima Encarnacion,\nTengo las tripas torcidas\nComo cuerdas de violon.",2,0,-1,19,"",0,4,"o",31,0,-1,0,396,396,"7510","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7511",2,"Tres meses há que no como;\nMe tiene abatido el hambre;\nMe pongo en las piernas plomo\nPor que no me lleve el aire.",2,0,-1,19,"",0,4,"ae",-1,0,-1,0,396,396,"7511","",0,"","","",4,0,0,[],""],["rm_t4-n7512",2,"Un estudiante tunante\nSe puso á pintar la luna\nY, de hambre que tenía,\nPintó un plato de aceitunas.",2,0,-1,19,"",0,4,"ua",-1,0,-1,0,396,396,"7512","",0,"lafuente_madrid, fernan_caballero","","",6,0,0,[],""],["rm_t4-n7513",2,"Un estudiante tunante\nSe puso á pintar el sol\nY, de hambre que tenía,\nPintó un pan de municion.",2,0,-1,19,"",0,4,"o",-1,0,-1,0,396,396,"7513","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t4-n7514",2,"Primer domingo de Abril,\n¡Qué dia tan señalado!\nMetí la mano y saqué\nEl número de soldado.",2,0,-1,19,"",0,4,"ao",14,0,-1,0,396,396,"7514","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7515",2,"A la guerra me lleva\nMi necesidad;\nSi tuviera dinero,\nNo fuera, en verdad.",2,0,-1,19,"",0,4,"a",16,0,-1,0,397,397,"7515","",0,"","","",1,0,0,[],""],["rm_t4-n7516",2,"En Málaga senté plaza\nEn una hermosa bandera,\nRegimiento de Borbon,\nCaballería ligera.",2,0,-1,19,"",0,4,"ea",44,0,-1,0,397,397,"7516","",0,"","","",3,0,0,[],""],["rm_t4-n7517",2,"Senté plaza de soldado\nSólo por no trabajar,\nY ahora me están fastidiando\nCon el paso regular.",2,0,-1,19,"",3,4,"a",21,0,-1,0,397,397,"7517","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7518",2,"El que quisiere saber\nDe qué color es la pena\nSiente plaza de soldado\nY se ausente de su tierra.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,397,397,"7518","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t4-n7519",2,"Soldadito soy del rey\nY aquí traigo mi registro;\nY si muero en la batalla,\nMuero por la fé de Cristo.",2,0,-1,19,"",3,4,"io",-1,0,-1,0,397,397,"7519","",0,"","","",3,0,0,[],""],["rm_t4-n7520",2,"¡Qué bien parece un soldado\nEn la puerta del cuartel,\nCon el cigarro en la mano,\nAguardando al coronel!",2,0,-1,19,"",0,4,"e",32,0,-1,0,397,397,"7520","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7521",2,"¡Qué bonito está un soldado\nA la puerta de un cuartel,\nCon corbatin estirado\nY sin tener que comer!",2,0,-1,19,"",0,4,"e",-1,0,-1,0,397,397,"7521","",0,"","","",2,0,0,[],""],["rm_t4-n7522",2,"La boca me huele á rancho,\nEl pescuezo á corbatin,\nLas espaldas á mochila\nY las manos á fusil.",2,0,-1,19,"",0,4,"i",-1,0,-1,0,398,398,"7522","",0,"","","",1,0,0,[],""],["rm_t4-n7523",2,"La vida de los soldados\nEs andar por los lugares,\nDormir en cama prestada,\nMorir en los hospitales.",2,0,-1,19,"",0,4,"ae",-1,0,-1,0,398,398,"7523","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["rm_t4-n7524",2,"Tres fincas tengo en Madrid,\nSiendo un pobre militar:\nLa cárcel, el cementerio\nY tambien el hospital.",2,0,-1,19,"",0,4,"a",-1,0,-1,0,398,398,"7524","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7525",2,"Si el comer poco es salud,\nComo dice aquel refran,\nLos pobrecitos soldados,\n¡Cuántos años vivirán!",2,0,-1,19,"",0,4,"a",147,0,-1,0,398,398,"7525","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7526",2,"De los caballos del rey\nNinguno como mi potro,\nQue para mover un pié\nLe pide licencia al otro.",2,0,-1,19,"",0,4,"oo",275,0,-1,0,398,398,"7526","",0,"carrizo_salta, palau_cantares","","",3,0,0,[],""],["rm_t4-n7527",2,"Yo no quiero más campaña\nEn el bajo de Aragon,\nPorque la racion de etapa\nSe ha vuelto conversacion.",2,0,-1,19,"",0,4,"ao",31,0,-1,0,398,398,"7527","",0,"","","",1,0,0,[],""],["rm_t4-n7528",2,"Cruz se llamaba mi cabo;\nCruz mi sargento mayor;\n¡Dios quiera que de estas cruces\nNo sea el Calvario yo!",2,0,-1,19,"",0,4,"o",-1,0,-1,0,398,398,"7528","",0,"","","",1,0,0,[],""],["rm_t4-n7529",2,"Para borracho, un francés;\nPara ladron, un ventero;\nPara mandar y dar palos,\nUn cabo de escuadra nuevo.",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,399,399,"7529","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7530",2,"El cuartel es una venta,\nEl sargento es el ventero,\nLos soldados son los burros,\nLos cabos, los arrieros.",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,399,399,"7530","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7531",2,"Los cuarteles son iglesias,\nLos soldados son los santos\nY los cabos los faroles\nQue alumbran de cuando en cuando.",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,399,399,"7531","",0,"","","",3,0,0,[],""],["rm_t4-n7532",2,"Estando de cuartelero,\nFué y me s' apagó er faró;\nYegó er sargento de guardia\nY á dambos mos alumbró.",2,0,-1,19,"",0,4,"o",2,0,-1,0,399,399,"7532","",0,"","","",2,0,0,[],""],["rm_t4-n7533",2,"Ya no me quiere mi cabo,\nMi sargento ni mi alférez,\nPorque soy aficionado\nUn poquillo á las mujeres.",2,0,-1,19,"",0,4,"ee",55,0,-1,0,399,399,"7533","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7534",2,"—Soldadito, soldadito,\n¿Qué llevas en la mochila?\n—Llevo las armas del rey\nY el corazon de una niña.",2,0,-1,19,"",0,4,"ia",-1,0,-1,0,399,399,"7534","",0,"fernan_caballero","","",4,0,0,[],""],["rm_t4-n7535",2,"Er pañuelo que me distes\nCon puntas, para llorar,\nYa sabes que soy sordado\nY no lo puedo pagar.",2,0,-1,19,"",0,4,"a",21,0,-1,0,399,399,"7535","",0,"","","",2,0,0,[],""],["rm_t4-n7536",2,"¿Cómo quieres que vaya\nDe noche á verte,\nSi salgo de la guardia\nY entro en piquete?",2,0,-1,19,"",6,4,"ee",-1,0,-1,0,400,400,"7536","",0,"","","",2,0,0,[],""],["rm_t4-n7537",2,"Sordado soy de á cabayo;\nCuanto quieras te daré;\nPero en tocando á casaca,\nNo quiere mi coroné.",2,0,-1,19,"",0,4,"e",77,0,-1,0,400,400,"7537","",0,"","","",1,0,0,[],""],["rm_t4-n7538",2,"Soldado tengo de ser\nMientras pueda mascar agua;\nQue no quiero más mujer\nQue el fusil y la canana.",2,0,-1,19,"",0,4,"aa",-1,0,-1,0,400,400,"7538","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7539",2,"Estando de sentinela\nEsta mañana en la Biña,\nSi no agacho la cabesa,\nUna bala me bendimia.",2,0,-1,19,"",0,4,"ia",-1,0,-1,0,400,400,"7539","",0,"","","",1,0,0,[],""],["rm_t4-n7540",2,"Estando de centinela\nEn la garita del campo,\nVinieron á relevarme\nCuatro soldados y un cabo.",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,400,400,"7540","",0,"lafuente_madrid","","",5,0,0,[],""],["rm_t4-n7541",2,"Si te preguntan: «¿Quién vive?»\nResponde con ligereza:\n—Los quintos de Pinos-Puente,\nVoluntarios á la fuerza.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,400,400,"7541","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7542",2,"Por un pan de municion\nQue el rey de España me da,\nToda la noche me tiene:\n—¡Centinela...! ¡Alerta está!",2,0,-1,19,"",0,4,"a",9,0,-1,0,400,400,"7542","",0,"","","",2,0,0,[],""],["rm_t4-n7543",2,"Cuatro cuartos me da el rey\nY con ellos como y bebo,\nLe pago á la lavandera,\nY me sobran tres y medio.",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,401,401,"7543","",0,"","","",6,0,0,[],""],["rm_t4-n7544",2,"Cuatro cuartos me da el rey,\nY cuatro me da la reina,\nY cuatro mi coronel,\nY cuatro mi coronela.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,401,401,"7544","",0,"fernan_caballero","","",6,0,0,[],""],["rm_t4-n7545",2,"El pan y los cuatro cuartos\nNunca me podrán faltar,\nEn Melilla, en el Peñón,\nO en los presidios de Orán.",2,0,-1,19,"",0,4,"a",-1,0,-1,0,401,401,"7545","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7546",2,"Más vale servir al rey\nY ganar los cuatro cuartos,\nQue nó que me pidan pan\nLa mujer y los muchachos.",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,401,401,"7546","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7547",2,"Es tanta la fantesía\nDe mi sargento primero,\nQue le pido unos sapatos\nY me da un bestío nuebo.",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,401,401,"7547","",0,"","","",1,0,0,[],""],["rm_t4-n7548",2,"Regimiento de Saboya,\n¡Qué sólo te vas quedando!\nA unos les dan la licencia\nY otros se la van tomando.",2,0,-1,19,"",0,4,"ao",33,0,-1,0,401,401,"7548","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7549",2,"Adelante, batidores;\nDar ejemplo al batallon;\nQue la gente de bigotes\nDebe ser gente de pró.",2,0,-1,19,"",0,4,"o",-1,0,-1,0,401,401,"7549","",0,"","","",4,0,0,[],""],["rm_t4-n7550",2,"En la plaza se oyen tiros;\nEn la plaza se ha de entrar:\nPena de la vida tiene\nAquel que se vuelva atrás.",2,0,-1,19,"",0,4,"a",-1,0,-1,0,402,402,"7550","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7551",2,"Vírgen del Cármen querida,\nDarme vuestra intercesion,\nY que no rompan las balas\nMi amoroso corazon.",2,0,-1,19,"",5,4,"ao",-1,0,-1,0,402,402,"7551","",0,"","","",1,0,0,[],""],["rm_t4-n7552",2,"¡Ay, mi padre, y ay, mi madre!\n¡Ay, mi humirde corason,\nQue lo matan á balasos\nEnmedio der batayon!",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,402,402,"7552","",0,"","","",1,0,0,[],""],["rm_t4-n7553",2,"Preso al moro me llevaron\nY, al subir por la escalera,\nVolví la carita á España,\nPara despedirme de ella.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,402,402,"7553","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7554",2,"¿Qué es aquello que relumbra\nPor aquellos olivares?\nSerá la guardia civil,\nEn busca de criminales.",2,0,-1,19,"",0,4,"ae",-1,0,-1,0,402,402,"7554","",0,"","","",8,0,0,[],""],["rm_t4-n7555",2,"Viva la media naranja;\nViva la naranja entera;\nViva la guardia civil,\nQue no tiene compañera.",2,0,-1,19,"",0,4,"ea",44,0,-1,0,402,402,"7555","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n7556",2,"La española infantería,\nPor lo brava y lo gentil,\nEn batallas y en amores\nSabe el triunfo conseguir.",2,0,-1,19,"",0,4,"i",-1,0,-1,0,402,402,"7556","",0,"","","",1,0,0,[],""],["rm_t4-n7557",2,"Dicen que la golondrina\nPasa la mar en un vuelo;\nAsí la pasaré yo\nEn cumpliendo, si no muero.",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,403,403,"7557","",0,"palau_cantares","","",12,0,0,[],""],["rm_t4-n7558",2,"Si Dios me deja salir\nDe Cataluña y su reino,\nHaré cuenta que he salido\nDe los profundos infiernos.",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,403,403,"7558","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7559",2,"Si Dios me saca con bien\nDel servicio militar,\nHaré cuenta que me he muerto\nY he vuelto á resucitar.",2,0,-1,19,"",0,4,"a",21,0,-1,0,403,403,"7559","",0,"lafuente_madrid, fernan_caballero","","",6,0,0,[],""],["rm_t4-n7560",2,"Ya he cumplido con mi rey,\nY aquí llevo la licencia;\nVoy á cumplir con mi padre,\nQue es mi Dios sobre la tierra.",2,0,-1,19,"",3,4,"ea",-1,0,-1,0,403,403,"7560","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7561",2,"A la sombra de un navío\nMe puse á considerar\nLas fatiguitas que pasa\nUn marinero en el mar.",2,0,-1,19,"",0,4,"a",21,0,-1,0,403,403,"7561","",0,"carrizo_salta","","",2,0,0,[],""],["rm_t4-n7562",2,"El que no sepa rezar,\nQue vaya por esos mares\nY verá qué pronto aprende,\nSin enseñárselo nádie.",2,0,-1,19,"",0,4,"ae",-1,0,-1,0,403,403,"7562","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7563",2,"En el cielo está mi Dios,\nEn el mar está mi dicha,\nEn el aire mi esperanza\nY en tierra quedó mi vida.",2,0,-1,19,"",0,4,"ia",-1,0,-1,0,404,404,"7563","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7564",2,"¡Ay del pobre marinero\nQue en tierra se deja el alma,\nY pasa un mes y otro mes\nCruzando la mar salada!",2,0,-1,19,"",0,4,"aa",-1,0,-1,0,404,404,"7564","",0,"","","",1,0,0,[],""],["rm_t4-n7565",2,"Marinero soy, señora;\nEn el gorro llevo el ancla,\nY en perdiéndose el barquillo,\nDoy fondo con mi esperanza.",2,0,-1,19,"",0,4,"aa",-1,0,-1,0,404,404,"7565","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7566",2,"¡Con qué pena vivirá\nLa mujer de un marinero,\nQue al pié del palo mayor\nTiene pagado el entierro!",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,404,404,"7566","",0,"","","",4,0,0,[],""],["rm_t4-n7567",2,"Al pié del palo mayor\nDel navío soberano\nLloraba un marinerito\nLa muerte de un primo hermano.",2,0,-1,19,"",0,4,"ao",81,0,-1,0,404,404,"7567","",0,"","","",1,0,0,[],""],["rm_t4-n7568",2,"Barrenero, sube al palo,\nY asegura bien tu vida;\nMira que vas enganchado\nEn una soga podrida.",2,0,-1,19,"",0,4,"ia",37,0,-1,0,404,404,"7568","",0,"","","",1,0,0,[],""],["rm_t4-n7569",2,"Marinero, sube al palo\nY dile á la madre mia\nQue si se acuerda de un hijo\nQue en la marina tenía.",2,0,-1,19,"",0,4,"ia",0,0,-1,0,404,404,"7569","",0,"palau_cantares","","",6,0,0,[],""],["rm_t4-n7571",2,"Al marinero en el mar\nNunca le faltan gabelas:\nYa se le rompe el timon,\nYa se le rifa la vela.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,405,405,"7571","",0,"","","",4,0,0,[],""],["rm_t4-n7572",2,"Er marinero en er mar\nNabega de noche y dia\nA la lus de la farola\nQu' en er mueve 'stá ensendía.",2,0,-1,19,"",0,4,"ia",0,0,-1,0,405,405,"7572","",0,"","","",1,0,0,[],""],["rm_t4-n7573",2,"¿Qué navío será aquel\nQue viene por altas mares?\n¡Si será la Capitana,\nQue viene de Buenos-Aires!",2,0,-1,19,"",0,4,"ae",-1,0,-1,0,405,405,"7573","",0,"","","",1,0,0,[],""],["rm_t4-n7574",2,"¿De quién es aquel barquito\nQue por el muelle se asoma?\nSerá la fragata Anita,\nQue viene de la Colonia.",2,0,-1,19,"",0,4,"oa",-1,0,-1,0,405,405,"7574","",0,"","","",1,0,0,[],""],["rm_t4-n7575",2,"Por allí viene mi barco,\nQue lo conozco en la vela,\nY en el palo mayor trae\nLos rizos de mi morena.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,405,405,"7575","",0,"","","",2,0,0,[],""],["rm_t4-n7577",2,"¿Cómo quieres que navegue,\nSi no está aquí mi velera?\n¿Quieres que á la mar me arroje\nY desesperado muera?",2,0,-1,19,"",0,4,"ea",44,0,-1,0,406,406,"7577","",0,"","","",6,0,0,[],""],["rm_t4-n7578",2,"Para los marineritos\nSe crian las buenas mozas;\nPara la gente del campo,\nLas calabazas pecosas.",2,0,-1,19,"",0,4,"oa",61,0,-1,0,406,406,"7578","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7580",2,"¡Viva la real marina!\n¡Viva el marino español!\n¡Viva la Isla y el Puerto,\nQue ya Cádiz se rindió!",2,0,-1,19,"",0,4,"o",-1,0,-1,0,406,406,"7580","",0,"","","",1,0,0,[],""],["rm_t4-n7581",2,"¡Pobresitos los mineros,\nQué desgrasiaítos son!\nPasan su bida en las minas\nY mueren sin confesion.",2,0,-1,19,"",0,4,"o",31,0,-1,0,406,406,"7581","",0,"","","",1,0,0,[],""],["rm_t4-n7582",2,"Hermosa Virgen de Gádor,\nQue estás al pié de la sierra,\nRuega por los mineritos\nQue están debajo de tierra.",2,0,-1,19,"",0,4,"ea",80,0,-1,0,406,406,"7582","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7583",2,"A la boca de la mina\nS' asomaba mi queré;\nComo la bia tan profunda,\nS' encomendaba á Undebé.",2,0,-1,19,"",0,4,"e",77,0,-1,0,407,407,"7583","",0,"","","",1,0,0,[],""],["rm_t4-n7584",2,"En diciendo: «¡Gente al torno!»\nTodos los mineros tiemblan,\nViendo que se han de poner\nA voluntad de una cuerda.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,407,407,"7584","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7585",2,"Los torneros son los guapos;\nLos picadores, valientes;\nY los pobres de la gavia\nSon los que aprietan los dientes.",2,0,-1,19,"",0,4,"ee",252,0,-1,0,407,407,"7585","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7587",2,"Guardillon y sal de lobo\nEs la seña del metal,\nY la piedra franciscana\nEs dura de barrenar.",2,0,-1,19,"",0,4,"a",-1,0,-1,0,407,407,"7587","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7588",2,"Dame machota y barrena,\nAguja y atacador,\nCartuchos, pajuela y mecha,\nQue voy á echar un boton.",2,0,-1,19,"",0,4,"o",-1,0,-1,0,407,407,"7588","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7589",2,"De capataces de gavia\nEstaba el infierno lleno\nY en el último rincon\nEstaban los cocineros.",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,407,407,"7589","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7590",2,"Mi marío es un minero\nQue saca plomo en la mina\nY m' entrega los dineros,\nPorque soy canela fina.",2,0,-1,19,"",0,4,"ia",11,0,-1,0,408,408,"7590","",0,"","","",1,0,0,[],""],["rm_t4-n7591",2,"¡Valiente ignorante es\nEl que á las minas se va,\nCuando las minas mejores\nSe quedan en el lugar!",2,0,-1,19,"",0,4,"a",-1,0,-1,0,408,408,"7591","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7592",2,"Todos los contrabandistas\nSon hombres de corazon;\nLo cargan en Cataluña;\nLo venden en Aragon.",2,0,-1,19,"",0,4,"ao",31,0,-1,0,408,408,"7592","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7593",2,"Los hombres de corazon\nSe aficionan al tabaco;\nPonen su administracion\nY lo venden sin estanco.",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,408,408,"7593","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7594",2,"Es mucho lo que me gusta\nUna canana corrida;\nQue aunque falte algun cartucho,\nSiempre queda prevenida.",2,0,-1,19,"",0,4,"ia",37,0,-1,0,408,408,"7594","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7597",2,"Dicen los contrabandistas\nCuando salen al Barranco:\n—Vámonos de aquí á Bayona\nPor muselina y tabaco.",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,409,409,"7597","",0,"lafuente_madrid","","",7,0,0,[],""],["rm_t4-n7598",2,"Dicen los contrabandistas\nCuando salen der barranco:\n—Bamos á España la yana\nA bender nuestro tabaco.",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,409,409,"7598","",0,"","","",7,0,0,[],""],["rm_t4-n7599",2,"Dicen los contrabandistas\nCuando salen á la playa:\n—Dios nos libre de soplones,\nCarabineros y guardas.",2,0,-1,19,"",0,4,"aa",-1,0,-1,0,409,409,"7599","",0,"palau_cantares","","",7,0,0,[],""],["rm_t4-n7600",2,"Disen los contrabandistas\nCuando salen der Peñón:\n— Dios nos libre y aquer santo\nDe la boca de un soplón.",2,0,-1,19,"",0,4,"o",31,0,-1,0,409,409,"7600","",0,"","","",1,0,0,[],""],["rm_t4-n7601",2,"Rio de Benamejí,\nDeja pasar á un serrano\nQue biene de lejas tierras,\nCargao de contrabando.",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,409,409,"7601","",0,"","","",1,0,0,[],""],["rm_t4-n7602",2,"Camino de Grasalema,\n¡Qué caminito tan triste:\nQue no pasa una carguita\nQue la guardia no registre!",2,0,-1,19,"",0,4,"ie",-1,0,-1,0,409,409,"7602","",0,"","","",1,0,0,[],""],["rm_t4-n7603",2,"Tabaco de contrabando,\nLa muselina y la pana;\nY tambien es contrabando\nEl hablar con esta dama.",2,0,-1,19,"",0,4,"aa",-1,0,-1,0,410,410,"7603","",0,"","","",1,0,0,[],""],["rm_t4-n7604",2,"Tu sandunga y un sigarro\nY una caña de Jerés,\nMi jamergo y un trabuco,\n¿Qué más gloria puede haber?",2,0,-1,19,"",0,4,"e",-1,0,-1,0,410,410,"7604","",0,"","","",1,0,0,[],""],["rm_t4-n7605",2,"A los piés de mi cabayo\nTengo yo la muerte mia;\n¡Benga tela de berano\nY rica pañolería!",2,0,-1,19,"",0,4,"ia",0,0,-1,0,410,410,"7605","",0,"","","",1,0,0,[],""],["rm_t4-n7606",2,"En montando en mi cabayo,\nNo temo á ningun baliente:\nUn retaco, dos pistolas,\nUn cuchiyo, y ¡benga gente!",2,0,-1,19,"",0,4,"ee",15,0,-1,0,410,410,"7606","",0,"","","",1,0,0,[],""],["rm_t4-n7607",2,"Mientras mi cabayo bebe,\nÉchame, niña, un cantar.\nBebe, cabayito mio,\nQu' está serenito er mar.",2,0,-1,19,"",0,4,"a",21,0,-1,0,410,410,"7607","",0,"","","",1,0,0,[],""],["rm_t4-n7608",2,"A la reja de la cárse\nTengo mi cabayo atao,\nPara darle lo que pía\nA la niña qu' ha cantao.",2,0,-1,19,"",0,4,"ao",98,0,-1,0,410,410,"7608","",0,"","","",2,0,0,[],""],["rm_t4-n7609",2,"¡Arriba, cabayo moro!\nSácame d' este barranco;\nQue me biene persiguiendo\nEr der cabayito blanco.",2,0,-1,19,"",0,4,"ao",303,0,-1,0,410,410,"7609","",0,"","","",3,0,0,[],""],["rm_t4-n7610",2,"¡Arriba, cabayo moro!\nSácame de este arenal;\nQue me bienen persiguiendo\nLos del águila imperial.",2,0,-1,19,"",0,4,"a",1,0,-1,0,411,411,"7610","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t4-n7611",2,"Cabayo mio careto,\nSácame d' esta laguna,\nDonde m' estoy ajogando,\nSin tener agua ninguna.",2,0,-1,19,"",0,4,"ua",56,0,-1,0,411,411,"7611","",0,"","","",2,0,0,[],""],["rm_t4-n7612",2,"Cabayo mio careto,\nYo no te pueo entendé;\nSi comes mucho t' ajitas;\nSi comes poco, tambien.",2,0,-1,19,"",0,4,"e",-1,0,-1,0,411,411,"7612","",0,"","","",2,0,0,[],""],["rm_t4-n7613",2,"Cuando me dieron er tiro\nEn los montes de Jimena,\nMe mataron er cabayo;\nMi cuerpo cayó en l' arena.",2,0,-1,19,"",0,4,"ea",59,0,-1,0,411,411,"7613","",0,"","","",1,0,0,[],""],["rm_t4-n7614",2,"—Contrabandista valiente,\n¿Qué tienes que tanto lloras?\n—Que se me ha muerto el caballo;\nYa se acabaron mis glorias.",2,0,-1,19,"",0,4,"oa",-1,0,-1,0,411,411,"7614","",0,"","","",3,0,0,[],""],["rm_t4-n7616",2,"Me metí á contrabandista\nDe tabaco y aguardiente,\nY me pillaron los guardias;\n¡Ahora sí que sale fuerte!",2,0,-1,19,"",0,4,"ee",-1,0,-1,0,412,412,"7616","",0,"","","",6,0,0,[],""],["rm_t4-n7617",2,"Me metí á contrabandista,\nPor ver si ganaba algo,\nY he perdido el corazon\nY tambien el contrabando.",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,412,412,"7617","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t4-n7618",2,"¡Mal haya el contrabandista\nQue á mí me enseñó á fumar;\nQue por un triste cigarro\nMe llevan á Gibraltar!",2,0,-1,19,"",0,4,"a",21,0,-1,0,412,412,"7618","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7619",2,"¿Dónde están los cuerpos buenos,\nQue los busco y no los hallo?\nUnos están en presidio;\nLos otros, al contrabando.",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,412,412,"7619","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7620",2,"Ya mataron á Frangoyo,\nEr guapo d' Ensinas Reales,\nAquer que benía bendiendo\nTabaco por los lugares.",2,0,-1,19,"",0,4,"ae",-1,0,-1,0,412,412,"7620","",0,"","","",1,0,0,[],""],["rm_t4-n7622",2,"Yo soy el hombre más fuerte\nDe cuantos hay en el mundo;\nHe corrido muchas tierras\nY no le tiemblo á ninguno.",2,0,-1,19,"",0,4,"uo",-1,0,-1,0,413,413,"7622","",0,"","","",3,0,0,[],""],["rm_t4-n7623",2,"Yo no le temo á trabucos\nNi á navajas ni á puñales,\nNi á hombres de vara y media,\nNi de á dos varas cabales.",2,0,-1,19,"",0,4,"ae",26,0,-1,0,413,413,"7623","",0,"","","",1,0,0,[],""],["rm_t4-n7624",2,"Yo me doy dies puñalâs\nCon el hombre más baliente;\nQu' este peyejito mio\nNo ha de serbir para aseite.",2,0,-1,19,"",0,4,"ee",-1,0,-1,0,413,413,"7624","",0,"","","",1,0,0,[],""],["rm_t4-n7625",2,"Sansón dicen fué valiente,\nY Oliveros y Roldan:\n¡A todos les diera muerte\nSi pudieran pelear!",2,0,-1,19,"",5,4,"a",-1,0,-1,0,413,413,"7625","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7626",2,"Yo fuí subiendo y subí\nHasta el último elemento\nY puse la fama mia\nDonde ninguno la ha puesto.",2,0,-1,19,"",3,4,"eo",-1,0,-1,0,413,413,"7626","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7627",2,"Pâ que no escale la groria\nUndebé me tiene preso\nY este mundiyo es mi jaula\nY la má mi bebeero.",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,413,413,"7627","",0,"","","",1,0,0,[],""],["rm_t4-n7628",2,"Esta noche va á salir\nLa fiera que nunca sale:\nAl revolver de una esquina,\nCapa en tierra y mano al sable.",2,0,-1,19,"",0,4,"ae",-1,0,-1,0,413,413,"7628","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n7630",2,"Esta noche va á llover\nSin haber nublo ninguno;\nQue he de hacer un San Miguel\nEn las costillas de alguno.",2,0,-1,19,"",0,4,"uo",230,0,-1,0,414,414,"7630","",0,"lafuente_madrid","","",6,0,0,[],""],["rm_t4-n7631",2,"Esta noche es la ronda\nDe los pastores;\nSalgan, si quieren algo,\nLos labradores.",2,0,-1,19,"",6,4,"oe",5,0,-1,0,414,414,"7631","",0,"","","",1,0,0,[],""],["rm_t4-n7632",2,"Dígale usté á aquel majo\nDe la montera\nQue si busca camorra,\nSalga aquí fuera.",2,0,-1,19,"",6,4,"ea",44,0,-1,0,414,414,"7632","",0,"","","",2,0,0,[],""],["rm_t4-n7633",2,"¡A la cama, chabaliyos!\nEsta noche no rondáis;\nEsta noche rondo yo\nY no rondan los chabales.",2,0,-1,19,"",5,4,"ae",-1,0,-1,0,414,414,"7633","",0,"","","",1,0,0,[],""],["rm_t4-n7634",2,"Esta noche voy de tuna,\nCon mi capa y mi zamarra;\nEl que quisiere cañé,\nQue salga por la guitarra.",2,0,-1,19,"",0,4,"aa",308,0,-1,0,414,414,"7634","",0,"","","",5,0,0,[],""],["rm_t4-n7635",2,"Salir, mozos, á rondar,\nLos de la guitarra nueva,\nY vereis qué gusto tienen\nLos palos de avellanera.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,414,414,"7635","",0,"","","",1,0,0,[],""],["rm_t4-n7636",2,"Cuatro chabales benimos,\nTodos sin pelo de barba;\nPero el que fuere capás,\nQue sarga por la guitarra.",2,0,-1,19,"",0,4,"aa",-1,0,-1,0,415,415,"7636","",0,"","","",1,0,0,[],""],["rm_t4-n7638",2,"El mozo que está cantando\nNo tiene pelo de barba;\nPero si se ofrece un lance,\nTiene pelos en el alma.",2,0,-1,19,"",0,4,"aa",-1,0,-1,0,415,415,"7638","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7639",2,"En este pueblo hay un guapo\nQue presume de valiente,\nCon una espada en la mano,\nEn una calle sin gente.",2,0,-1,19,"",0,4,"ee",15,0,-1,0,415,415,"7639","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7640",2,"El que no quiera morir\nAl tiro de mi pistola,\nMe deje la calle libre,\nQue la necesito toda.",2,0,-1,19,"",0,4,"oa",-1,0,-1,0,415,415,"7640","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7641",2,"Para pasear tu caye\nNo nesesito cuchiyo;\nQue los mosos d' esta tierra\nMe los meto en er borsiyo.",2,0,-1,19,"",0,4,"io",221,0,-1,0,415,415,"7641","",0,"","","",1,0,0,[],""],["rm_t4-n7642",2,"Salir, mositos, salir\nA la esquina de la plasa,\nY ayí bereis relusir\nLa punta de mi nabaja.",2,0,-1,19,"",0,4,"aa",-1,0,-1,0,415,415,"7642","",0,"","","",1,0,0,[],""],["rm_t4-n7643",2,"Dígal' usté á ese mosito\nQue anda por la cayejuela\nQue, si no se quita pronto,\nL' he de romper la montera.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,416,416,"7643","",0,"","","",1,0,0,[],""],["rm_t4-n7644",2,"En la esquina de mi casa\nTengo de hacer un farol\nCon las costillas de un guapo,\nLa lengua de un hablador.",2,0,-1,19,"",0,4,"o",-1,0,-1,0,416,416,"7644","",0,"","","",1,0,0,[],""],["rm_t4-n7646",2,"¡Cuánto vale un mozo bueno\nPuesto en una boca calle,\nCon un retaco en la mano:\n«Por aquí no pasa nádie!»",2,0,-1,19,"",0,4,"ae",-1,0,-1,0,416,416,"7646","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7647",2,"¡Qué peniya será er ber\nLa prenda que un hombre estima\nEn manos de otro gaché,\nPor ser un hombre gayina!",2,0,-1,19,"",0,4,"ia",-1,0,-1,0,416,416,"7647","",0,"","","",1,0,0,[],""],["rm_t4-n7648",2,"Si Málaga tiene un mueye,\nMi nabaja tiene sinco;\nAr que se yegue á arrimar\nNo le bale San Fransisco.",2,0,-1,19,"",0,4,"io",-1,0,-1,0,416,416,"7648","",0,"","","",1,0,0,[],""],["rm_t4-n7650",2,"Si me s' ajuma er pescao\nY desembaino er flamenco,\nCon cuarenta puñalâs\nSe ba á rematar er cuento.",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,417,417,"7650","",0,"","","",1,0,0,[],""],["rm_t4-n7651",2,"¡Sujétame, que me pierdo!\nComo me yegue á enfaar,\nA los hombres rebaneo,\nComo rebaneo er pan.",2,0,-1,19,"",0,4,"a",-1,0,-1,0,417,417,"7651","",0,"","","",3,0,0,[],""],["rm_t4-n7652",2,"Apúntame bien al pecho;\nMira que si no me das,\nTengo de hacerte más chispas\nQue arenas tiene la mar.",2,0,-1,19,"",0,4,"a",-1,0,-1,0,417,417,"7652","",0,"","","",3,0,0,[],""],["rm_t4-n7653",2,"En la esquina d' esta caye\nMe quisieron dar la muerte;\nYo metí mano ar cuchiyo....\n¡Biban los hombres balientes!",2,0,-1,19,"",0,4,"ee",-1,0,-1,0,417,417,"7653","",0,"","","",1,0,0,[],""],["rm_t4-n7654",2,"Me llamo Félix Pastor,\nCapitan de bandoleros,\nY á nádie tengo temor,\nAunque vengan granaderos.",2,0,-1,19,"",1,4,"eo",22,0,-1,0,417,417,"7654","",0,"","","",4,0,0,[],""],["rm_t4-n7655",2,"Me llamo Félix Pastor;\nSoy capitan de ladrones,\nY á nádie tengo temor,\nAunque vengan batallones.",2,0,-1,19,"",1,4,"oe",34,0,-1,0,417,417,"7655","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7656",2,"Aya ba Diego Corriente\nCon su cabayo cuatrarbo,\nSu jembra en er pensamiento,\nY su trabuco en la mano.",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,417,417,"7656","",0,"","","",1,0,0,[],""],["rm_t4-n7657",2,"Por la Sierra Morena\nBa una partía;\nAr capitan le yaman\nJosé María.\nSus compañeros,\nFrasquito er de la Turre,\nJuan Cabayero.",2,0,-1,19,"",4,7,"eo",-1,0,-1,0,418,418,"7657","",0,"","","",4,0,0,[],""],["rm_t4-n7658",2,"La muerte no bebe bino\nNi registra fardiquera;\nAr que se pone borracho,\nLa muerte no se lo yeba.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,418,418,"7658","",0,"","","",1,0,0,[],""],["rm_t4-n7659",2,"Dijo er sabio Salomon\nHablando con San Alejo,\nQue el hombre, para ser hombre,\nHa de beber bino aniejo.",2,0,-1,19,"",0,4,"eo",264,0,-1,0,418,418,"7659","",0,"","","",3,0,0,[],""],["rm_t4-n7660",2,"El hombre, para ser hombre,\nNesesita tres partías:\nSer borracho, jugaó,\nY no casarse en su bía.",2,0,-1,19,"",0,4,"ia",-1,0,-1,0,418,418,"7660","",0,"","","",7,0,0,[],""],["rm_t4-n7661",2,"A la mar maera\nY á la tierra güesos;\nY pá los hombres - las mujeres barbis\nY er binito resio.",2,0,-1,19,"",3,4,"eo",-1,0,-1,0,418,418,"7661","",0,"","","",1,0,0,[],""],["rm_t4-n7662",2,"Los ángeles en el cielo\nAdoran á Dios divino,\nY nosotros en la tierra\nA las mujeres y al vino.",2,0,-1,19,"",0,4,"io",199,0,-1,0,419,419,"7662","",0,"","","",10,0,0,[],""],["rm_t4-n7664",2,"Dicen que el apio es caliente\nY el rábano y el pepino;\nY yo digo que es mentira:\nQue más caliente es el vino.",2,0,-1,19,"",3,4,"io",199,0,-1,0,419,419,"7664","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7665",2,"¡Qué bien canta una calandria!\n¡Qué bien canta un ruiseñor!\nMás bien canta una botella,\nEn quitándole el tapón.",2,0,-1,19,"",0,4,"o",-1,0,-1,0,419,419,"7665","",0,"","","",2,0,0,[],""],["rm_t4-n7666",2,"Cuando Jesucristo vino\nSe vino por un lagar;\nVino repartiendo vino....\nPero el vino, ¿dónde está?",2,0,-1,19,"",0,4,"a",-1,0,-1,0,419,419,"7666","",0,"","","",2,0,0,[],""],["rm_t4-n7667",2,"Un gato subió á una parra\nY la parra abajo vino;\nY vino sobre nosotros,\nY sobre nosotros, vino.",2,0,-1,19,"",0,4,"io",-1,0,-1,0,419,419,"7667","",0,"","","",1,0,0,[],""],["rm_t4-n7668",2,"Dicen que del cielo vino\nLa semilla de la cepa;\nY siendo el vino divino,\nBebamos mientras nos quepa.",2,0,-1,19,"",1,4,"ea",309,0,-1,0,419,419,"7668","",0,"","","",1,0,0,[],""],["rm_t4-n7671",2,"El aguardiente me gusta\nY el vino tambien lo bebo;\nPero en llegando al resoli,\n¡Eche usté rom, que me pierdo!",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,420,420,"7671","",0,"","","",4,0,0,[],""],["rm_t4-n7672",2,"Al aguardiente anisao\nYo no sé lo que l' han hecho:\nLo han rebajao de graos\nY l' han subió er derecho.",2,0,-1,19,"",0,4,"eo",60,0,-1,0,420,420,"7672","",0,"","","",1,0,0,[],""],["rm_t4-n7673",2,"¡Bárgame San Bargamé!\n¡Bárgame la Mardalena!\n¡Antes de beber er bino\nM' están temblando las piernas!",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,420,420,"7673","",0,"","","",1,0,0,[],""],["rm_t4-n7676",2,"Si el vino no me pusiera\nUn poco calamocano,\nPareciera mi gaznate\nUn embudo sevillano.",2,0,-1,19,"",0,4,"ao",81,0,-1,0,421,421,"7676","",0,"","","",1,0,0,[],""],["rm_t4-n7677",2,"Para que yo me pusiera\nUn poco calamocano,\nNecesitaba mi cuerpo\nUn embudo sevillano.",2,0,-1,19,"",0,4,"ao",81,0,-1,0,421,421,"7677","",0,"","","",1,0,0,[],""],["rm_t4-n7678",2,"¿Dónde hay gusto como entrar\nCuatro amiguitos leales\nEn casa de un montañés:\n—Enjuague usté esos cristales?",2,0,-1,19,"",0,4,"ae",26,0,-1,0,421,421,"7678","",0,"","","",1,0,0,[],""],["rm_t4-n7679",2,"Echa bino, montañés,\nY enjuaga bien los cristales,\nPorque bienen á beber\nTres amiguitos leales.",2,0,-1,19,"",0,4,"ae",26,0,-1,0,421,421,"7679","",0,"","","",2,0,0,[],""],["rm_t4-n7680",2,"Echa bino, montañés,\nQu' el agua me jase mar;\nMás quiero morir borracho\nQue oir las ranas cantar.",2,0,-1,19,"",0,4,"a",21,0,-1,0,421,421,"7680","",0,"","","",2,0,0,[],""],["rm_t4-n7681",2,"Ya no me quiere mi novia,\nPorque bebo mucho vino;\n¡Vaya mi novia con Dios!\n¡Eche usté medio cuartillo!",2,0,-1,19,"",0,4,"io",-1,0,-1,0,421,421,"7681","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7682",2,"Benga tela, benga tela,\nBenga tela de berano;\nA mí me gusta la tela\nPor la mañana temprano.",2,0,-1,19,"",1,4,"ao",81,0,-1,0,421,421,"7682","",0,"","","",2,0,0,[],""],["rm_t4-n7683",2,"Benga tela, benga tela;\nBenga otro medio cuartiyo;\nQu' el aguardiente es lo solo\nPá matar er gusaniyo.",2,0,-1,19,"",0,4,"io",221,0,-1,0,422,422,"7683","",0,"","","",2,0,0,[],""],["rm_t4-n7685",2,"Bén acá, bino, binito,\nHijo de la sepa tuerta;\n¡Tú, que te quieres meter;\nY yo, que te abro la puerta!",2,0,-1,19,"",0,4,"ea",267,0,-1,0,422,422,"7685","",0,"","","",1,0,0,[],""],["rm_t4-n7686",2,"Tomaré una calabaza\nY un Santo Cristo de pino,\nY me iré á hacer penitencia\nA una bodega de vino.",2,0,-1,19,"",0,4,"io",199,0,-1,0,422,422,"7686","",0,"","","",1,0,0,[],""],["rm_t4-n7687",2,"Mi compadre s' ajogó\nEn una cuba de bino;\n¡Compadre del arma mia,\nQuién s' ajogara contigo!",2,0,-1,19,"",0,4,"io",-1,0,-1,0,422,422,"7687","",0,"","","",1,0,0,[],""],["rm_t4-n7688",2,"¡Si el rio de Sevilla\nFuera de vino\nY la torre del Oro\nFuera el cuartillo...!",2,0,-1,19,"",6,4,"io",-1,0,-1,0,422,422,"7688","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7689",2,"Madre mia, si me muero,\nEnterradme en la bodega;\nAbridme la sepultura\nAl pié de la cuba nueva.",2,0,-1,19,"",0,4,"ea",-1,0,-1,0,422,422,"7689","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t4-n7690",2,"Un borracho se murió\nY dejó en su testamento\nQue lo enterraran en viña,\nPara chupar los sarmientos.",2,0,-1,19,"",0,4,"eo",-1,0,-1,0,423,423,"7690","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["rm_t4-n7691",2,"Lúnes y martes, de chispa;\nMiércoles, la estoy durmiendo;\nJuéves, viérnes, mala gana;\nY el sábado entra el estruendo.",2,0,-1,19,"",0,4,"eo",52,0,-1,0,423,423,"7691","",0,"","","",2,0,0,[],""],["rm_t4-n7692",2,"Mi madre estará diciendo:\n—¿Dónde estará ese muchacho?—\nY yo estoy en la taberna,\nPoco ménos que borracho.",2,0,-1,19,"",0,4,"ao",310,0,-1,0,423,423,"7692","",0,"","","",1,0,0,[],""],["rm_t4-n7693",2,"Cualesquiera bebe bino;\nCualesquiera s' emborracha;\nCualesquiera s' echa nobia,\nY cualesquiera se casa.",2,0,-1,19,"",0,4,"aa",-1,0,-1,0,423,423,"7693","",0,"","","",1,0,0,[],""],["rm_t4-n7694",2,"La guitarra está borracha\nY el que la toca tambien;\nY los dos qu' están bailando\nNo se pueden mantener.",2,0,-1,19,"",0,4,"e",-1,0,-1,0,423,423,"7694","",0,"carrizo_salta","","",3,0,0,[],""],["rm_t4-n7695",2,"Me convidas á correr,\nPorque tengo los piés malos;\nConvídame á beber vino,\nQue tengo el gaznate sano.",2,0,-1,19,"",0,4,"ao",-1,0,-1,0,423,423,"7695","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],""],["rm_t4-n7696",2,"Esta noche es Noche-buena,\nY mañana Navidad;\nDame la bota, morena,\nQue me quiero emborrachar.",2,0,-1,19,"",0,4,"a",-1,0,-1,0,423,423,"7696","",0,"","","",5,0,0,[],""],["rm_t4-n7699",2,"De borrachiyo qu' estoy\nYa no me pueo tener;\nEchem' usté otra cañita,\nQue quisas m' alibiaré.",2,0,-1,19,"",0,4,"e",-1,0,-1,0,424,424,"7699","",0,"","","",1,0,0,[],""],["rm_t4-n7701",2,"Maresita e mi arma,\nSi preso me quieres bé,\nPreso y jerío me tienes\nEn la cárse de Jerés.",2,0,-1,20,"",0,4,"e",-1,0,-1,0,433,433,"7701","",0,"","","",1,0,0,[],""],["rm_t4-n7702",2,"¿Quién le llevará la nueva\nA la triste de mi madre\nQue en un calabozo oscuro\nMe están echando la llave?",2,0,-1,20,"",0,4,"ae",-1,0,-1,0,433,433,"7702","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7703",2,"Ministriles y alguaciles,\nToda la justicia plena,\nMe vinieron á prender\nEn casa de mi morena.",2,0,-1,20,"",0,4,"ea",59,0,-1,0,433,433,"7703","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7704",2,"A las doce de la noche,\nNiña, me llevaron preso,\nY para mayor dolor,\nMe ataron con tu pañuelo.",2,0,-1,20,"",0,4,"eo",-1,0,-1,0,433,433,"7704","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t4-n7705",2,"¡Maldita sea la cárcel\nY el que la labró de piedra;\nA las doce de la noche\nMe metieron dentro de ella!",2,0,-1,20,"",0,4,"ea",-1,0,-1,0,434,434,"7705","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7706",2,"A aquel que quiere y no puede\nGozar de su libertad,\nNo es menester que lo entierren;\nQue enterrado en vida está.",2,0,-1,20,"",0,4,"a",-1,0,-1,0,434,434,"7706","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7707",2,"¿De qué le sirve al cautivo\nTener los grillos de plata\nY las cadenas de oro,\nSi la libertad le falta?",2,0,-1,20,"",0,4,"aa",-1,0,-1,0,434,434,"7707","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t4-n7709",2,"En er patio de la cárse\nEché un boto y miré ar sielo:\n—¿Dónde está mi libertá?\n¿Dónde está, que no la beo?",2,0,-1,20,"",0,4,"eo",-1,0,-1,0,434,434,"7709","",0,"","","",2,0,0,[],""],["rm_t4-n7710",2,"En er patio de la cárse\nMiré ar sielo y dije así:\n—¿Dónde está mi libertá,\nQue tan niño la perdí?",2,0,-1,20,"",0,4,"i",23,0,-1,0,434,434,"7710","",0,"","","",2,0,0,[],""],["rm_t4-n7711",2,"Salí al patio de la cárcel,\nMiré al cielo y dí un suspiro:\n¿Dónde está mi libertad,\nQue tan pronto la he perdido?",2,0,-1,20,"",0,4,"io",-1,0,-1,0,434,434,"7711","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7712",2,"Madre, no es usté mi madre;\nQue si usté mi madre fuera,\nEcharía un empeñito\nY de la cárcel saliera.",2,0,-1,20,"",0,4,"ea",44,0,-1,0,435,435,"7712","",0,"","","",1,0,0,[],""],["rm_t4-n7713",2,"Dil' usté á mi mare\nQue no yore más;\nSino que ande - toítos los pasos\nPâ mi libertá.",2,0,-1,20,"",3,4,"a",-1,0,-1,0,435,435,"7713","",0,"","","",1,0,0,[],""],["rm_t4-n7714",2,"Dígal' usté á mi parino\nQue benga corriendo acá,\nY en un papelito fino\nQue firme mi libertá.",2,0,-1,20,"",1,4,"a",9,0,-1,0,435,435,"7714","",0,"","","",1,0,0,[],""],["rm_t4-n7715",2,"Estaré siempre llorando\nMi triste cautividad,\nHasta que del cielo baje\nMi carta de libertad.",2,0,-1,20,"",0,4,"a",16,0,-1,0,435,435,"7715","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7716",2,"¿Qué duas son éstas,\nSeñon Paulo Olabe?\nLa biuita ha daíto er perdón;\nEcharme á la caye.",2,0,-1,20,"",3,4,"ae",-1,0,-1,0,435,435,"7716","",0,"","","",1,0,0,[],""],["rm_t4-n7717",2,"Si hubiera arguno en er mundo\nQue la libertá me diera,\nM' echara un jierro en la cara\nY esclabito suyo fuera.",2,0,-1,20,"",0,4,"ea",44,0,-1,0,435,435,"7717","",0,"","","",1,0,0,[],""],["rm_t4-n7718",2,"Pulidita carcelera.\nSácame de esta prision;\nTe daré el anillo de oro\nQue me dió el bien de mi amor.",2,0,-1,20,"",0,4,"o",-1,0,-1,0,435,435,"7718","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7720",2,"Jasta la sinta der pelo\nSe la dí á la carselera,\nPor una taya de agua\nY un ascuita de candela.",2,0,-1,20,"",0,4,"ea",-1,0,-1,0,436,436,"7720","",0,"","","",1,0,0,[],""],["rm_t4-n7721",2,"A un oscuro calaboso\nMe yebaban la comía;\nMás suspiritos pegaba\nQue bocaítos comia.",2,0,-1,20,"",0,4,"ia",-1,0,-1,0,436,436,"7721","",0,"","","",1,0,0,[],""],["rm_t4-n7724",2,"A la reja de la cárse\nNo me benga 'sté con llantos;\nBengam' usté con monises,\nPara alibiar mi quebranto.",2,0,-1,20,"",0,4,"ao",-1,0,-1,0,436,436,"7724","",0,"","","",2,0,0,[],""],["rm_t4-n7725",2,"Er pajarito en la jaula\nSe dibierte en el alambre,\nY yo m' estoy dibirtiendo\nCon las rejas de mi cárse.",2,0,-1,20,"",0,4,"ae",-1,0,-1,0,436,436,"7725","",0,"","","",1,0,0,[],""],["rm_t4-n7727",2,"Cuando yo estaba en prisiones\nSolito me entretenía\nEn contar los eslabones\nQue mi cadena tenía.",2,0,-1,20,"",1,4,"ia",0,0,-1,0,437,437,"7727","",0,"rm_t2","","",10,0,0,[],""],["rm_t4-n7728",2,"La probesita e mi mare\nA on Antonio le jabló,\nPâ que me quiten los griyos,\nM' echen al patio mayó.",2,0,-1,20,"",0,4,"o",2,0,-1,0,437,437,"7728","",0,"","","",1,0,0,[],""],["rm_t4-n7729",2,"Estas rejas son de bronce,\nY estas paredes, de piedra;\nMis amigos son de vidrio:\nPor no quebrarse no llegan.",2,0,-1,20,"",0,4,"ea",-1,0,-1,0,437,437,"7729","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7730",2,"Mardita sea la cárse,\nSepurtura d' hombres bibos,\nDonde se amansan los guapos\nY se pierden los amigos.",2,0,-1,20,"",0,4,"io",-1,0,-1,0,437,437,"7730","",0,"","","",1,0,0,[],""],["rm_t4-n7731",2,"Jasta los hombres más guapos\nToítos se güerben chiquiyos,\nCuando ensima del ayunque\nSe le remachan los griyos.",2,0,-1,20,"",0,4,"io",299,0,-1,0,437,437,"7731","",0,"","","",1,0,0,[],""],["rm_t4-n7732",2,"De tôs los males der mundo\nDime cuár será er peor;\nEr casarse, ó er morirse,\nO estar en una prision.",2,0,-1,20,"",0,4,"o",-1,0,-1,0,437,437,"7732","",0,"","","",1,0,0,[],""],["rm_t4-n7733",2,"Maldita sea la cárcel\nY tambien el carcelillo:\nEl que no lleva cadena,\nLleva dos pares de grillos.",2,0,-1,20,"",0,4,"io",-1,0,-1,0,438,438,"7733","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7734",2,"¡Ay, cárcel, qué mala eres!\n¡Siempre te maldeciré!\nEntré sin pelo de barba\nY capuchino saldré.",2,0,-1,20,"",0,4,"e",77,0,-1,0,438,438,"7734","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7735",2,"Calabosiyo de piedra,\n¡Mal haya de tí y de mí!\nEntré sin pelo de barba\nY capuchino salí.",2,0,-1,20,"",0,4,"i",23,0,-1,0,438,438,"7735","",0,"","","",1,0,0,[],""],["rm_t4-n7736",2,"Como el aguardiente claro\nQue sale del alambique\nMe voy yo purificando\nEn esta cárser de Ubrique.",2,0,-1,20,"",0,4,"ie",311,0,-1,0,438,438,"7736","",0,"","","",3,0,0,[],""],["rm_t4-n7737",2,"Bentisinco calabosos\nTiene la cárse de Utrera;\nBenticuatro yebo andaos\nY er más oscuro me quea.",2,0,-1,20,"",0,4,"ea",-1,0,-1,0,438,438,"7737","",0,"","","",1,0,0,[],""],["rm_t4-n7738",2,"Cuando yega la requisa\nAr cuarto donde 'stoy yo\nEchan en abrí la puerta\nDos horitas po 'r reló.",2,0,-1,20,"",0,4,"o",2,0,-1,0,438,438,"7738","",0,"","","",1,0,0,[],""],["rm_t4-n7740",2,"Estoy en un calabozo\nLleno de abominaciones;\nYa me suben, ya me bajan,\nA tomar declaraciones.",2,0,-1,20,"",0,4,"oe",34,0,-1,0,439,439,"7740","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7741",2,"Si el rey de España supiera\nLo que á los presos les pasa,\nDe cárcel en cárcel fuera,\nEchándolos á sus casas.",2,0,-1,20,"",0,4,"aa",-1,0,-1,0,439,439,"7741","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7742",2,"Señó arcarde mayó\nY demás señores,\nEstas penitas - d' este cuerpo mió\nNo le corresponden.",2,0,-1,20,"",3,4,"oe",-1,0,-1,0,439,439,"7742","",0,"","","",1,0,0,[],""],["rm_t4-n7743",2,"Porque le dije á una niña:\n«¡Ay, lo que te ví, Jesús!»\nMe metieron en la cárcel,\nDonde no viera la luz.",2,0,-1,20,"",0,4,"u",109,0,-1,0,439,439,"7743","",0,"lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7744",2,"Porque le dije á una niña:\n«¡Jolé, biba tu salero!»\nMe metieron en la cárse,\nDond' estube prisionero.",2,0,-1,20,"",0,4,"eo",38,0,-1,0,439,439,"7744","",0,"","","",4,0,0,[],""],["rm_t4-n7745",2,"Porque dije: «¡Biba er lujo!»\nMe metieron en la cárse;\n¡Biba er lujo y quien lo trujo!\n¡No fartará quien me saque!",2,0,-1,20,"",0,4,"ae",-1,0,-1,0,439,439,"7745","",0,"","","",1,0,0,[],""],["rm_t4-n7746",2,"Mi madre me lo decia\nQue me tenía que ver\nEn la cárcel de Almería,\nPreso por una mujer.",2,0,-1,20,"",1,4,"e",20,0,-1,0,439,439,"7746","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7747",2,"Dame la mano y saldré\nDe este oscuro calabozo;\nQue me están acumulando\nUn casamiento forzoso.",2,0,-1,20,"",0,4,"oo",160,0,-1,0,440,440,"7747","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7748",2,"Por decirle al señor juez:\n«¡Baje usté, que yo no subo,»\nMe metieron en la cárcel\nY me costó quince duros.",2,0,-1,20,"",0,4,"uo",-1,0,-1,0,440,440,"7748","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7750",2,"Caminito de Antequera\nPreso llevan á un gitano,\nPorque se encontró una capa,\nAntes de perderla el amo.",2,0,-1,20,"",0,4,"ao",-1,0,-1,0,440,440,"7750","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7751",2,"Me metieron en la cárse,\nPor jaser un San Migué;\nY asín que me echaron fuera,\nJise un San Bartolomé.",2,0,-1,20,"",0,4,"e",77,0,-1,0,440,440,"7751","",0,"","","",1,0,0,[],""],["rm_t4-n7752",2,"Tú no me quiés perdoná,\nPâ que yo pase fatigas;\nPor eso está tu marío\nArdiendo en las yamas bibas.",2,0,-1,20,"",0,4,"ia",-1,0,-1,0,440,440,"7752","",0,"","","",1,0,0,[],""],["rm_t4-n7753",2,"Yo he bisto un preso cantar\nY en sus cantares desia:\n—Yo me yamaré ar silensio;\nQue ya yegará la mia.",2,0,-1,20,"",5,4,"a",-1,0,-1,0,440,440,"7753","",0,"","","",1,0,0,[],""],["rm_t4-n7754",2,"Poique me bes probe y preso\nPiensas que m' he muerto yo;\nPuê sé qu' argun dia digas:\n—Er muerto resusitó.",2,0,-1,20,"",0,4,"o",2,0,-1,0,441,441,"7754","",0,"","","",1,0,0,[],""],["rm_t4-n7755",2,"Para los hombres se han hecho\nLos grillos y las cadenas,\nY para las buenas mozas\nSan Fernando y la Galera.",2,0,-1,20,"",0,4,"ea",-1,0,-1,0,441,441,"7755","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t4-n7757",2,"Preso en la cárcel estoy;\nNo tengas pena por eso;\nNi dejo de ser quien soy,\nNi yo soy el primer preso.",2,0,-1,20,"",1,4,"eo",48,0,-1,0,441,441,"7757","",0,"","","",9,0,0,[],""],["rm_t4-n7758",2,"Soy hombre: ¡vengan fatigas!\nNací para padecer;\nLos grillos y las cadenas\nNo me caben en los piés.",2,0,-1,20,"",0,4,"e",-1,0,-1,0,441,441,"7758","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7759",2,"Echa grillos, carcelero,\nY aprieta bien los candados,\nPara que paguen mis piés\nLos malos pasos que han dado.",2,0,-1,20,"",0,4,"ao",-1,0,-1,0,441,441,"7759","",0,"","","",1,0,0,[],""],["rm_t4-n7760",2,"Echa griyos, carselero,\nY aprieta bien las chapetas;\nQue soy muchachiyo nuebo\nY er jierro no m' atormenta.",2,0,-1,20,"",0,4,"ea",-1,0,-1,0,441,441,"7760","",0,"","","",2,0,0,[],""],["rm_t4-n7761",2,"Dos años estuve preso\nEn la cárcel de Antequera,\nY á la calle no salí....\nHasta que me echaron fuera.",2,0,-1,20,"",0,4,"ea",44,0,-1,0,442,442,"7761","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7762",2,"Otras beses los gitanos\nGastaban medias e sea,\nY ahora, por su desgrasia,\nGastan griyos y caenas.",2,0,-1,20,"",0,4,"ea",-1,0,-1,0,442,442,"7762","",0,"","","",1,0,0,[],""],["rm_t4-n7764",2,"En la torre de Serranos,\nEn la segunda escalera,\nHay un letrero que dice:\n«Aquí la verdad se niega.»",2,0,-1,20,"",0,4,"ea",-1,0,-1,0,442,442,"7764","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7765",2,"Si acaso te preguntaren,\nNunca niegues la mentira:\nLa berdá por las es pardas,\nY el escribano, qu' escriba.",2,0,-1,20,"",3,4,"ia",-1,0,-1,0,442,442,"7765","",0,"","","",1,0,0,[],""],["rm_t4-n7766",2,"Aquel que entrare en la cárcel,\nNunca diga la verdad;\nPorque á buena confesion,\nMala penitencia dan.",2,0,-1,20,"",0,4,"a",-1,0,-1,0,442,442,"7766","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7768",2,"Toma, gachí, estas dos jaras;\nDíñasela' 'r libanó,\nPâ que ponga en los papires\nDe que no abiyelo yo.",2,0,-1,20,"",0,4,"o",2,0,-1,0,443,443,"7768","",0,"","","",1,0,0,[],""],["rm_t4-n7769",2,"Cuando er jues me preguntó\nQue de qué me man tenia,\nYo le contesté: — Robando,\nComo se mantiene usía.",2,0,-1,20,"",0,4,"ia",0,0,-1,0,443,443,"7769","",0,"","","",1,0,0,[],""],["rm_t4-n7770",2,"Asómate á esa bentana,\nBerás pasá la consensia:\nMenistros, precuraores\nY escribanos de l' Audensia.",2,0,-1,20,"",0,4,"ea",187,0,-1,0,443,443,"7770","",0,"","","",4,0,0,[],""],["rm_t4-n7771",2,"La cárcel es el infierno,\nEl carcelero es el diablo,\nLos jueces los que condenan,\nY ellos son los condenados.",2,0,-1,20,"",0,4,"ao",-1,0,-1,0,443,443,"7771","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7772",2,"Las doce acaban de dar\nEn el reló de la Audiencia;\nEntre jueces y escribanos\nMe han leido la sentencia.",2,0,-1,20,"",0,4,"ea",46,0,-1,0,443,443,"7772","",0,"","","",1,0,0,[],""],["rm_t4-n7773",2,"Morenita, tú que vives\nEnfrentito de la Audiencia,\nDime si oiste leer\nEl papel de mi sentencia.",2,0,-1,20,"",0,4,"ea",46,0,-1,0,443,443,"7773","",0,"","","",1,0,0,[],""],["rm_t4-n7774",2,"Ya no sirben memoriales\nNi papeles á l' Audensia;\nEntre cuatro tribunales (?)\nM' han leío mi sentensia.",2,0,-1,20,"",1,4,"ea",187,0,-1,0,443,443,"7774","",0,"","","",1,0,0,[],""],["rm_t4-n7775",2,"Toítos los sabios combienen\nQue castiguen á mi cuerpo;\nNo sé qué delito tiene,\nPorque yo no se lo encuentro.",2,0,-1,20,"",0,4,"eo",-1,0,-1,0,444,444,"7775","",0,"","","",1,0,0,[],""],["rm_t4-n7777",2,"Mi causa ya se acabó;\nYa se cerraron mis autos,\nY ha salido la sentencia\nDe presidio por diez años.",2,0,-1,20,"",0,4,"ao",-1,0,-1,0,444,444,"7777","",0,"","","",3,0,0,[],""],["rm_t4-n7780",2,"Camino de Cartagena\nMuchos pobrecitos van,\nDesterrados hijos de Eva,\nPor las hijitas de Adan.",2,0,-1,20,"",0,4,"a",147,0,-1,0,444,444,"7780","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7781",2,"¡Pobrecitos de la cárcel,\nYa tendreis algun consuelo;\nPero yo, triste de mi,\nNi lo tengo ni lo espero!",2,0,-1,20,"",0,4,"eo",-1,0,-1,0,444,444,"7781","",0,"","","",3,0,0,[],""],["rm_t4-n7782",2,"En la puerta del presidio\nHay escrito con carbon:\n«Aquí el bueno se hace malo,\nY el malo se hace peor.»",2,0,-1,20,"",0,4,"o",-1,0,-1,0,445,445,"7782","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7783",2,"Si Dios me saca con bien\nDe la Alhambra y su gobierno,\nHaré cuenta que he salido\nDe los profundos infiernos.",2,0,-1,20,"",0,4,"eo",-1,0,-1,0,445,445,"7783","",0,"","","",6,0,0,[],""],["rm_t4-n7784",2,"Veinticinco calabozos\nTiene la cárcel de Oran;\nVeinticuatro llevo andados\nY uno me falta que andar.",2,0,-1,20,"",5,4,"a",-1,0,-1,0,445,445,"7784","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7786",2,"Ya me sacan de la cárse\nA cajitas estemplâs;\nMe ponen á sacá piedras\nDe las oriyas er má.",2,0,-1,20,"",5,4,"a",-1,0,-1,0,445,445,"7786","",0,"","","",1,0,0,[],""],["rm_t4-n7787",2,"A siento sincuenta hombres\nMos yeban á la Carraca;\nMos yeban á currelá\nY á sacá piedras del agua.",2,0,-1,20,"",0,4,"aa",-1,0,-1,0,445,445,"7787","",0,"","","",1,0,0,[],""],["rm_t4-n7788",2,"Caminito e la Isla,\nAnte' e yegá á los pinares,\nGorbí la carita atrás\nY á boses yamo á mi mare.",2,0,-1,20,"",0,4,"ae",-1,0,-1,0,445,445,"7788","",0,"","","",1,0,0,[],""],["rm_t4-n7789",2,"Mi mare no yoró agua;\nQue lo que yoró fué sangre,\nCaminito e la Isla,\nAnte' e yegá á los pinares.",2,0,-1,20,"",0,4,"ae",-1,0,-1,0,446,446,"7789","",0,"","","",1,0,0,[],""],["rm_t4-n7790",2,"Si me guipara mi bata,\nNo m' habia e conosé,\nCon la chaquetiya 'l hombro\nY con la caeniya 'r pié.",2,0,-1,20,"",0,4,"e",77,0,-1,0,446,446,"7790","",0,"","","",1,0,0,[],""],["rm_t4-n7791",2,"Si algun mortal por aquí\nPasa por casualidad,\nSocorra á los infelices\nQue en este desierto están.",2,0,-1,20,"",0,4,"a",-1,0,-1,0,446,446,"7791","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7792",2,"El que quiera ver penitas,\nVaya al campillo de Arenas,\nY verá á los presidiarios\nCargaditos de cadenas.",2,0,-1,20,"",0,4,"ea",62,0,-1,0,446,446,"7792","",0,"","","",3,0,0,[],""],["rm_t4-n7795",2,"Señó cabito de bara,\nPor Dios, no me pegu' usté,\nQu' estoy aquí enserraíto\nPo una pícara mujé.",2,0,-1,20,"",3,4,"e",77,0,-1,0,446,446,"7795","",0,"","","",1,0,0,[],""],["rm_t4-n7796",2,"Señó cabito primero,\nPor Dios no me pegu' usté;\n¡Que me quean cuatro meses!\n¿Me ba usté á comprometé....?",2,0,-1,20,"",0,4,"e",77,0,-1,0,447,447,"7796","",0,"","","",1,0,0,[],""],["rm_t4-n7798",2,"Lo sacan der calaboso;\nLo yeban enmedio er má;\nD' ayí lo yeban ar moro,\nY en er moro morirá.",2,0,-1,20,"",0,4,"a",9,0,-1,0,447,447,"7798","",0,"","","",2,0,0,[],""],["rm_t4-n7799",2,"Lo mismo me importa á mí\nComer pan en esta tierra\nQue comerlo en el presidio,\nArrastrando una cadena.",2,0,-1,20,"",0,4,"ea",-1,0,-1,0,447,447,"7799","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7800",2,"Entre dos piedras nasí,\nLas águilas me criaron,\nEnmedio der mar me bí,\nLos moros me cautibaron\n[España no es para mí].",2,0,-1,20,"",7,5,"i",23,0,-1,0,447,447,"7800","",0,"","","",1,0,0,[],""],["rm_t4-n7801",2,"Los suspiros de un cautivo\nNo pueden llegar á España,\nPorque está la mar por medio\nY se ahogan en el agua.",2,0,-1,20,"",0,4,"aa",-1,0,-1,0,447,447,"7801","",0,"","","",3,0,0,[],""],["rm_t4-n7802",2,"La Bínge de Regla\nBenga en mi compaña;\nComo me beo - esmamparaíto\nEn tierras estrañas.",2,0,-1,20,"",3,4,"aa",-1,0,-1,0,447,447,"7802","",0,"","","",2,0,0,[],""],["rm_t4-n7803",2,"Cuando te bidé bení,\nBarquito e la redension,\nDe faitigas que me dieron\nMe s' arrancó er corason.",2,0,-1,20,"",5,4,"ao",-1,0,-1,0,448,448,"7803","",0,"","","",2,0,0,[],""],["rm_t4-n7804",2,"Tôs le píen á Dios\nSalú y libertá,\nY yo le pío - una güeña muerte,\nNo me la quiê dá.",2,0,-1,20,"",3,4,"a",9,0,-1,0,448,448,"7804","",0,"","","",1,0,0,[],""],["rm_t4-n7805",2,"Dicen que me han de matar\nY me han de sacar al campo;\n¡Vírgen de la Soledad,\nCubridme con vuestro manto!",2,0,-1,20,"",0,4,"ao",-1,0,-1,0,448,448,"7805","",0,"palau_cantares","","",19,0,0,[],""],["rm_t4-n7806",2,"Dile á la triste e mi mare,\nCompañero, por tu bía,\nQue hoy me sacan de la cárse\nY me meten en capiya.",2,0,-1,20,"",0,4,"ia",-1,0,-1,0,448,448,"7806","",0,"","","",1,0,0,[],""],["rm_t4-n7807",2,"Los presos cuentan los dias;\nLos presidiarios, los años;\nY los que están en capilla,\nLas horas que van pasando.",2,0,-1,20,"",0,4,"ao",-1,0,-1,0,448,448,"7807","",0,"palau_cantares","","",5,0,0,[],""],["rm_t4-n7809",2,"Er reló e la Audensia\nAcaba de dá;\nComo le dije - á mi compañerita:\n—Me ban á merá.",2,0,-1,20,"",3,4,"a",9,0,-1,0,448,448,"7809","",0,"","","",1,0,0,[],""],["rm_t4-n7810",2,"A la rejita e la cárse\nYamó Curro y bino Pepe;\n¡Qué fatiguitas serán\nLas fatigas e la muerte!",2,0,-1,20,"",0,4,"ee",-1,0,-1,0,449,449,"7810","",0,"","","",1,0,0,[],""],["rm_t4-n7812",2,"Ya los sacan de la cárse,\nLos yeban ar Baratiyo;\nDe sentimiento yoraban\nHombres, mujeres y niños.",2,0,-1,20,"",0,4,"io",-1,0,-1,0,449,449,"7812","",0,"","","",1,0,0,[],""],["rm_t4-n7813",2,"Ar subí la escala,\nLe dijo ar berdugo\nQue le quitara - la túnica blanca,\nLo pusiera e luto.",2,0,-1,20,"",3,4,"uo",-1,0,-1,0,449,449,"7813","",0,"","","",1,0,0,[],""],["rm_t4-n7815",2,"Cuando Felipe Quinto\nMontó á caballo,\nLa Reina de los cielos\nLe dió la mano.\n—Toma esta rosa;\nToma, Felipe Quinto,\nPara tu esposa.",2,0,-1,21,"",4,7,"oa",63,0,-1,0,457,457,"7815","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7816",2,"La mar, cubierta de sangre;\nLos montes, echando humo;\nEl inglés, tirando bombas;\nY España, ¡rumbo que rumbo!",2,0,-1,21,"",0,4,"uo",-1,0,-1,0,457,457,"7816","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7817",2,"Napoleon Bonaparte,\n¿Qué tal te parece España?\nYa tienes en tu presencia\nAl marqués de la Romana.",2,0,-1,21,"",0,4,"aa",-1,0,-1,0,457,458,"7817","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7818",2,"La Vírgen del Pilar dice\nQue no quiere ser francesa;\nQue quiere ser capitana\nDe la gente aragonesa.",2,0,-1,21,"",0,4,"ea",201,0,-1,0,458,458,"7818","",0,"","","",3,0,0,[],""],["rm_t4-n7819",2,"Napoleon subió al cielo\nA pedirle á Dios la España,\nY le respondió San Pedro:\n—¿Quieres que te rompa el alma?",2,0,-1,21,"",0,4,"aa",-1,0,-1,0,458,458,"7819","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7820",2,"Todos le temen á Francia,\nComo si en la Francia hubiera\nAlgun animal feroz\nQue la gente se comiera.",2,0,-1,21,"",0,4,"ea",44,0,-1,0,458,458,"7820","",0,"","","",2,0,0,[],""],["rm_t4-n7822",2,"Doblen las campanas,\nDoblen con doló;\nComo mataron - á Riego er baliente;\n¡Mira y qué doló!",2,0,-1,21,"",3,4,"o",-1,0,-1,0,458,458,"7822","",0,"","","",2,0,0,[],""],["rm_t4-n7824",2,"Ciento cincuenta cartuchos\nTengo yo en mi cartuchera,\nPara matar las facciones\nQue defienden á Cabrera.\nPara gobernar la España,\nDon Baldomero Espartero.",2,0,-1,21,"",9,6,"eo",-1,0,-1,0,458,458,"7824","",0,"","","",3,0,0,[],""],["rm_t4-n7825",2,"Para sabio, Salomon;\nPaquiro, para torero;\nPara gobernar la España,\nDon Baldomero Espartero.",2,0,-1,21,"",0,4,"eo",38,0,-1,0,459,459,"7825","",0,"","","",1,0,0,[],""],["rm_t4-n7826",2,"A Cáis le tiran bombas;\nA Sebiya, las granâs,\nY á Luis Felipe le tiran\nCamisiyas embreâs.",2,0,-1,21,"",5,4,"ee",-1,0,-1,0,459,459,"7826","",0,"","","",1,0,0,[],""],["rm_t4-n7827",2,"Los rusos vienen por tierra\nY los ingleses por agua;\nY yo, que soy español,\nMe estoy tumbado en la cama.",2,0,-1,21,"",0,4,"aa",-1,0,-1,0,459,459,"7827","",0,"","","",3,0,0,[],""],["rm_t4-n7829",2,"La Habana se va á perder;\nLa culpa tiene el dinero;\nLos negros se vuelven blancos,\nY los blancos, aduaneros.",2,0,-1,21,"",0,4,"eo",-1,0,-1,0,459,459,"7829","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7830",2,"Al pié de Sierra Bullones,\nUna morita decia:\n—¡Ya viene la flor de España!\n¡Ya dió fin la morería!",2,0,-1,21,"",0,4,"ia",0,0,-1,0,459,459,"7830","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7831",2,"A un corneta muy chiquito\nUn moro se lo llevó;\nY sacó la navajilla\nY el pescuezo le cortó.",2,0,-1,21,"",0,4,"o",2,0,-1,0,459,459,"7831","",0,"","","",1,0,0,[],""],["rm_t4-n7832",2,"De las patillas de un moro\nTengo de hacer una escoba,\nPara que barra el cuartel\nLa infantería española.",2,0,-1,21,"",0,4,"oa",-1,0,-1,0,460,460,"7832","",0,"","","",3,0,0,[],""],["rm_t4-n7833",2,"Del pellejo del rey moro\nTengo de hacer un sofá,\nPara que se siente en él\nEl capitan general.",2,0,-1,21,"",0,4,"a",-1,0,-1,0,460,460,"7833","",0,"","","",1,0,0,[],""],["rm_t4-n7834",2,"De las costillas de un moro\nMe atrevo á formar un puente,\nPara que pase la España\nY su ejército valiente.",2,0,-1,21,"",0,4,"ee",15,0,-1,0,460,460,"7834","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7835",2,"En la plaza de Tetuan\nHay un caballo de caña;\nCuando el caballo relinche\nEntrará el moro en España.",2,0,-1,21,"",0,4,"aa",213,0,-1,0,460,460,"7835","",0,"","","",1,0,0,[],""],["rm_t4-n7836",2,"Centinela, centinela,\nCentinela del Serrallo,\n¡Alerta, alerta, que vienen\nLos moritos de á caballo!",2,0,-1,21,"",0,4,"ao",102,0,-1,0,460,460,"7836","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7837",2,"¿Qué importa que los moros\nTengan pingardas,\nSi luego se las quitan\nCon la metraya?",2,0,-1,21,"",6,4,"aa",-1,0,-1,0,460,460,"7837","",0,"","","",2,0,0,[],""],["rm_t4-n7840",2,"Del dia seis de Febrero\nNos tenemos que acordar;\nQue entraron los españoles\nEn la plaza de Tetuan.",2,0,-1,21,"",5,4,"ea",-1,0,-1,0,461,461,"7840","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7841",2,"¿Quién me compra una chinela\nDel hermano del sultan,\nQue se le cayó al salir\nHuyendo de Tetuan?",2,0,-1,21,"",5,4,"ea",-1,0,-1,0,461,461,"7841","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7842",2,"Estaba la reina mora\nSentadita en su balcon,\nEsperando que pasara\nEl segundo batallon.",2,0,-1,21,"",0,4,"ao",31,0,-1,0,461,461,"7842","",0,"","","",2,0,0,[],""],["rm_t4-n7843",2,"Estaba la reina mora\nSentadita en un sofá,\nEsperando que pasara\nEl capitan general.",2,0,-1,21,"",0,4,"a",-1,0,-1,0,461,461,"7843","",0,"","","",2,0,0,[],""],["rm_t4-n7844",2,"Ya no se estila desir\n«Biba Prim, biba Serrano;»\nQue lo que se estila ahora:\n«¡Biban los republicanos!»",2,0,-1,21,"",0,4,"ao",-1,0,-1,0,461,461,"7844","",0,"","","",1,0,0,[],""],["rm_t4-n7845",2,"Republicana es la luna,\nRepublicano es el sol,\nRepublicana es la tierra,\nRepublicano soy yo.",2,0,-1,21,"",0,4,"o",-1,0,-1,0,461,461,"7845","",0,"","","",1,0,0,[],""],["rm_t4-n7847",2,"Una gayina cantaba\nRepública federá,\nY bino un gayo carlino\nY le dió tres puñalâs.",2,0,-1,21,"",5,4,"ua",-1,0,-1,0,462,462,"7847","",0,"","","",1,0,0,[],""],["rm_t4-n7848",2,"Pensaron los sebiyanos\nQue las tropas no benian;\nBinieron cuatro mil hombres\nCon er generar Pabia.",2,0,-1,21,"",5,4,"aa",-1,0,-1,0,462,462,"7848","",0,"","","",1,0,0,[],""],["rm_t4-n7850",2,"La república se ha muerto\nY la yeban á enterrar:\nEn er panteón no cabe\nLa gente que ba detrás.",2,0,-1,21,"",0,4,"a",-1,0,-1,0,462,462,"7850","",0,"","","",1,0,0,[],""],["rm_t4-n7851",2,"Monte-Jurra, Monté-Jurra,\n¡Quien te ha visto y quien te ve!\nAyer boinas coloradas,\nY hoy gorrillas de cuartel.",2,0,-1,21,"",0,4,"e",-1,0,-1,0,462,464,"7851","",0,"","","",2,0,0,[],""],["rm_t4-n7853",2,"A las Indias van los hombres;\nA las Indias, por ganar;\nLas Indias aquí las tienen,\nSi quisieran trabajar.",2,0,-1,22,"",0,4,"a",21,0,-1,0,467,467,"7853","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7854",2,"Por esos aires subia\nUn serafin de los cielos,\nY al ver esta tierra dijo:\n—No subo, que aquí me quedo.",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,467,467,"7854","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n7855",2,"Entre la tierra y er sielo\nNo hay mujeres con más sal\nQue las mujeres de España\nCon la mantiya tersiâ.",2,0,-1,22,"",5,4,"ei",-1,0,-1,0,467,467,"7855","",0,"","","",1,0,0,[],""],["rm_t4-n7856",2,"Si me pierdo, que me busquen\nEn el sol del mediodia,\nDonde lo moreno nace\nY donde la sal se cria.",2,0,-1,22,"",0,4,"ia",0,0,-1,0,467,467,"7856","",0,"palau_cantares","","",4,0,0,[],""],["rm_t4-n7857",2,"El cielo de Andalucía\nEstá vestido de azul;\nPor eso la sal abunda\nEn todo el suelo andaluz.",2,0,-1,22,"",0,4,"u",-1,0,-1,0,468,468,"7857","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n7858",2,"En Francia disen Mon Diú\nY en Italia yiusto chelo;\nY aquí desimos ¡caramba!\nY se junde 'r mundo entero.",2,0,-1,22,"",3,4,"eo",-1,0,-1,0,468,468,"7858","",0,"","","",1,0,0,[],""],["rm_t4-n7859",2,"¡Sebiya del arma mia!\n¡Sebiya de mi consuelo!\n¡Quién estubiera en Sebiya,\nAunque durmiera en er suelo!",2,0,-1,22,"",0,4,"eo",10,0,-1,0,468,468,"7859","",0,"","","",1,0,0,[],""],["rm_t4-n7860",2,"La torre de Sebiya\nS' está cayendo;\nSanta Justa y Rufina\nLa están teniendo.\nMira, Rufina,\nMira no te se caiga\nLa torre ensima.",2,0,-1,22,"",4,7,"ia",-1,0,-1,0,468,468,"7860","",0,"","","",1,0,0,[],""],["rm_t4-n7861",2,"Santa Justa y Rufina\nSon dos hermanas\nQue con una camisa\nSe bisten ambas.",2,0,-1,22,"",6,4,"aa",-1,0,-1,0,468,468,"7861","",0,"","","",1,0,0,[],""],["rm_t4-n7863",2,"Llevan las sevillanas\nEn la mantilla\nUn letrero que dice:\n«¡Viva Sevilla!»",2,0,-1,22,"",6,4,"ia",162,0,-1,0,469,469,"7863","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n7864",2,"Biba la Sestería,\nPorqu' es mi barrio,\nLa Puerta de Triana,\nCaye San Pablo.\nY el estribiyo,\nBiba caye Galera\nY er Baratiyo.",2,0,-1,22,"",4,7,"io",221,0,-1,0,469,469,"7864","",0,"","","",1,0,0,[],""],["rm_t4-n7865",2,"Para caras bonitas,\nLa Macarena;\nPara cuerpos garbosos,\nLas trianeras.\nPara buen pelo,\nSan Roque, San Bernardo\nY er Barresuelo.",2,0,-1,22,"",4,7,"eo",10,0,-1,0,469,469,"7865","",0,"","","",1,0,0,[],""],["rm_t4-n7866",2,"Todos disen que muera\nLa Macarena,\nY yo solita digo:\n—¡Biba, y nó muera!\n¡Biba la grasia!\n¡Biba la Bírgen pura\nDe la Esperansa!",2,0,-1,22,"",4,7,"aa",-1,0,-1,0,469,469,"7866","",0,"","","",1,0,0,[],""],["rm_t4-n7867",2,"En la Macarenita\nMe dieron agua\nMás fria que la niebe,\nEn una taya.",2,0,-1,22,"",6,4,"aa",-1,0,-1,0,469,469,"7867","",0,"","","",1,0,0,[],""],["rm_t4-n7870",2,"A la bajâ der puente,\n'N el Artosano,\nHan jecho una 'lamea\nPara los bagos.\nAl estribiyo,\nHan jecho una 'lamea\nPâ los chiquiyos.",2,0,-1,22,"",4,7,"io",-1,0,-1,0,470,470,"7870","",0,"","","",1,0,0,[],""],["rm_t4-n7871",2,"Primero que te orbide,\nCaye Castiya,\nEcharán los olibos\nNaranjas chinas.\nCaye 'r Rosario,\nEcharán los olibos\nLimones agrios.",2,0,-1,22,"",4,7,"ao",-1,0,-1,0,470,470,"7871","",0,"","","",1,0,0,[],""],["rm_t4-n7872",2,"Cantiyana la yana\nLa están arando;\nDe clabeles y rosas\nLa están sembrando.",2,0,-1,22,"",6,4,"ao",33,0,-1,0,470,470,"7872","",0,"","","",1,0,0,[],""],["rm_t4-n7873",2,"Adiós, Guârcaná dichoso;\nBien te lo puedes yamar,\nPorque por patrona tienes\nA la Bírgen der lunar.",2,0,-1,22,"",0,4,"a",21,0,-1,0,470,471,"7873","",0,"","","",1,0,0,[],""],["rm_t4-n7874",2,"Casaya y Guadarcaná\nTienen los pastos comunes,\nY yo los tengo contigo\nSábado, domingo y lúnes.",2,0,-1,22,"",0,4,"ue",312,0,-1,0,471,471,"7874","",0,"","","",1,0,0,[],""],["rm_t4-n7875",2,"Casaya, tierra de Dios;\nCostantina, de galanes;\nGuârcaná, de güeñas mosas;\nY er Pedroso, de olibares.",2,0,-1,22,"",0,4,"ae",-1,0,-1,0,471,471,"7875","",0,"","","",1,0,0,[],""],["rm_t4-n7876",2,"En Costantina selebran\nA la Bírgen de Robledo;\nEn Casaya á la der Monte\nY en San Nicolás, San Diego.",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,471,471,"7876","",0,"","","",1,0,0,[],""],["rm_t4-n7877",2,"Sebiya me da boses,\nCádis me yama,\nY Carmona me dise\nQue no me baya.",2,0,-1,22,"",6,4,"aa",-1,0,-1,0,471,471,"7877","",0,"","","",1,0,0,[],""],["rm_t4-n7878",2,"Ésija, la gran solina,\nSale 'l sol por el Oriente;\nPor eso las esijanas\nTienen el sol en la frente.",2,0,-1,22,"",0,4,"ee",15,0,-1,0,471,471,"7878","",0,"","","",1,0,0,[],""],["rm_t4-n7879",2,"Ésija, sibitas solis,\nTiene un paseo salado,\nUna gran plasa de toros\nY un matadero pintado.",2,0,-1,22,"",0,4,"ao",14,0,-1,0,471,471,"7879","",0,"","","",1,0,0,[],""],["rm_t4-n7881",2,"Yo nasí en Fuente Parmera\nY me crié en la Luisiana\nY me bine á enamorar\nDe una pulida esijana.",2,0,-1,22,"",0,4,"aa",4,0,-1,0,472,472,"7881","",0,"","","",1,0,0,[],""],["rm_t4-n7882",2,"Esabesindado bengo\nDe la biya de Morón,\nY aquí traigo los papeles\nDe la esabesindasion.",2,0,-1,22,"",3,4,"ao",-1,0,-1,0,472,472,"7882","",0,"","","",1,0,0,[],""],["rm_t4-n7883",2,"Sinco nobios tengo en Fuentes,\nY sinco en la Lantejuela,\nCuarenta y sinco en la Puente\nY siente y pico en Utrera.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,472,472,"7883","",0,"","","",1,0,0,[],""],["rm_t4-n7884",2,"Estepiya está en un serro,\nGileniya está en un baye,\nY la triste de Pedrera\nNo tiene más que una caye.",2,0,-1,22,"",0,4,"ae",313,0,-1,0,472,472,"7884","",0,"","","",1,0,0,[],""],["rm_t4-n7885",2,"San Bartolomé bendito,\nDel Aguadurse patron,\nDíme cuantos campusinos\nYebas en tu prosesion.",2,0,-1,22,"",5,4,"eo",-1,0,-1,0,472,472,"7885","",0,"","","",1,0,0,[],""],["rm_t4-n7886",2,"Biba Campiyos y Ardales,\nRonda, Pruna y Arcalá,\nEr Sausejo y los Corrales,\nCañete y Benarrabá\n[Osuna, Puebla y Casares].",2,0,-1,22,"",7,5,"ae",-1,0,-1,0,472,472,"7886","",0,"","","",1,0,0,[],""],["rm_t4-n7887",2,"En Osuna, San Arcadio;\nEn Campiyos, San Benito;\nY en el Aguadurse, madre,\nSan Bartolomé bendito.",2,0,-1,22,"",0,4,"io",119,0,-1,0,473,473,"7887","",0,"","","",2,0,0,[],""],["rm_t4-n7888",2,"En Osuna, San Arcadio;\nEn Biyanueba, San Juan;\nEn er Sausejo, San Marcos,\nY San Roque en Arcalá.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,473,473,"7888","",0,"","","",2,0,0,[],""],["rm_t4-n7889",2,"Esta luna y la de Osuna\nY la de Puerto-Reá\nAlumbran á mi moreno\nPor donde quiera que ba.",2,0,-1,22,"",0,4,"a",9,0,-1,0,473,473,"7889","",0,"","","",1,0,0,[],""],["rm_t4-n7890",2,"Si te casas en Osuna,\nMira primero con quién,\nMira no dés con arguna\nQue te jaga coroné\n[De los cuernos de la luna].",2,0,-1,22,"",7,5,"ua",56,0,-1,0,473,473,"7890","",0,"","","",1,0,0,[],""],["rm_t4-n7891",2,"En Osuna no hay cristianos,\nQue toda es tierra de moros:\n¿Quién ha bisto en la Cuaresma\nHaber corrías de toros?",2,0,-1,22,"",0,4,"oo",314,0,-1,0,473,473,"7891","",0,"","","",1,0,0,[],""],["rm_t4-n7892",2,"En Osuna está, señores,\nLa imágen más pelegrina\nQue pueden pintar pintores\nCon paper y tinta fina\n[La Bírgen de los Dolores].",2,0,-1,22,"",7,5,"oe",5,0,-1,0,473,473,"7892","",0,"","","",1,0,0,[],""],["rm_t4-n7893",2,"La imágen más pelegrina\nEstá en Osuna la yana,\nEn un combento sagrado\nQue la Bitoria le yaman.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,473,474,"7893","",0,"","","",1,0,0,[],""],["rm_t4-n7894",2,"Aunque soy der barrio bajo,\nMira no soy de la Cuna;\nTengo mi padre y mi madre\nEn la colegiar de Osuna.",2,0,-1,22,"",0,4,"ua",56,0,-1,0,474,474,"7894","",0,"","","",1,0,0,[],""],["rm_t4-n7895",2,"La mejor caye de Osuna\nEs la caye de Aguilar,\nDonde 'stá er sor y la luna\nY el Arforí de la sá.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,474,474,"7895","",0,"","","",1,0,0,[],""],["rm_t4-n7896",2,"En la caye Antequera\nLas hay bonitas;\nPero tienen mar fario\nLas pobresitas.\nLas de mi barrio,\nAunque chatas y feas,\nTienen buen fario.",2,0,-1,22,"",4,7,"ao",-1,0,-1,0,474,474,"7896","",0,"","","",1,0,0,[],""],["rm_t4-n7897",2,"Bengo de Osuna la yana,\nDe bé á San Arcario er biejo,\nY está su mersé tan gordo,\nQue no cabe 'n er peyejo.",2,0,-1,22,"",0,4,"eo",264,0,-1,0,474,474,"7897","",0,"","","",1,0,0,[],""],["rm_t4-n7899",2,"Biba er lejío de Osuna\nY su bendita 'lameda;\nBiban los cuerpos gayardos\nQue por eya se pasean.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,474,474,"7899","",0,"","","",1,0,0,[],""],["rm_t4-n7900",2,"Er que jiso l' alameda\nEnfrente de San Arcadio,\nEse merese un castigo,\nComo un santo un nobenario.",2,0,-1,22,"",0,4,"ao",-1,0,-1,0,475,475,"7900","",0,"","","",1,0,0,[],""],["rm_t4-n7901",2,"Topete-cano está malo;\nCarderon s' está muriendo;\nLa Turquiya agonisando\nY er Rubio s' está riendo.",2,0,-1,22,"",0,4,"eo",52,0,-1,0,475,475,"7901","",0,"","","",1,0,0,[],""],["rm_t4-n7902",2,"Er Nuño s' está muriendo;\nJornía está agonisando;\nConsuegra s' está riendo;\nFelipe Sanches, yorando.",2,0,-1,22,"",1,4,"ao",33,0,-1,0,475,475,"7902","",0,"","","",1,0,0,[],""],["rm_t4-n7903",2,"Biba Trigueros y Buerba\nY Moguer con su buen bino,\nY San Juan d' Asnarfarache\nCon su rio cristalino.",2,0,-1,22,"",0,4,"io",199,0,-1,0,475,475,"7903","",0,"","","",1,0,0,[],""],["rm_t4-n7904",2,"Del Alosno florido\nSon mis amores,\nY yo bibo en la caye\nDe los Mesones.",2,0,-1,22,"",6,4,"oe",-1,0,-1,0,475,475,"7904","",0,"","","",1,0,0,[],""],["rm_t4-n7905",2,"En el pueblo de Calañas\nNasió Júdas el traidor;\nY en El Cerro, segun dicen,\nLa madre que lo parió.",2,0,-1,22,"",0,4,"o",-1,0,-1,0,475,475,"7905","",0,"","","",1,0,0,[],""],["rm_t4-n7907",2,"Quien quisiere comprar grasia,\nEn cuatro puntos la hay:\nEn la Isla e San Fernando,\nSebiya, Córdoba y Cáis.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,476,476,"7907","",0,"","","",1,0,0,[],""],["rm_t4-n7908",2,"Las mositas de Sebiya\nLe disen á las de Cáis:\n—¿A cómo bale la libra\nDe la sar que derramais?",2,0,-1,22,"",5,4,"aa",-1,0,-1,0,476,476,"7908","",0,"","","",1,0,0,[],""],["rm_t4-n7909",2,"¡Biba Cádis, porque tiene\nLas murayas á la mar!\n¡Biban los cuerpos bonitos!\n¡Biban las jembras salâs!",2,0,-1,22,"",0,4,"a",-1,0,-1,0,476,476,"7909","",0,"","","",2,0,0,[],""],["rm_t4-n7910",2,"Biba Cádis, porque tiene\nLas murayas hásia er mar,\nY bentisinco cañones\nApuntando á Gibrartar.",2,0,-1,22,"",0,4,"a",21,0,-1,0,476,476,"7910","",0,"","","",2,0,0,[],""],["rm_t4-n7911",2,"Cádis no seyama Cádis,\nQue se yama relicario,\nPorque tiene por patrona\nA la Bírgen del Rosario.",2,0,-1,22,"",0,4,"ao",25,0,-1,0,476,476,"7911","",0,"","","",1,0,0,[],""],["rm_t4-n7913",2,"En la mar se crian peses\nY en la oriya caracoles;\nY en el barrio de la Biña,\nMuchachitas como flores.",2,0,-1,22,"",0,4,"oe",-1,0,-1,0,476,476,"7913","",0,"","","",1,0,0,[],""],["rm_t4-n7914",2,"Adios, barrio de la Biña,\nPlasuela der Mentiero,\nDonde pára Bocanegra\nCon toítos sus toreros.",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,477,477,"7914","",0,"","","",1,0,0,[],""],["rm_t4-n7915",2,"En la bahía de Cádis\nMataron á un andalus,\nPorque le dijo á una niña:\n—¡Biba la sar de Jesús!",2,0,-1,22,"",5,4,"u",-1,0,-1,0,477,477,"7915","",0,"","","",2,0,0,[],""],["rm_t4-n7916",2,"A Cádis le yaman Cádis;\nA la bahía, bahía;\nY ar Puerto le yaman Puerto,\nPuerto de Santa María.",2,0,-1,22,"",0,4,"ia",0,0,-1,0,477,477,"7916","",0,"","","",1,0,0,[],""],["rm_t4-n7917",2,"Biba Cádis, biba er Puerto,\nBiban las jembras y er bino,\nY biban los mosos buenos\nQue ban por esos caminos.",2,0,-1,22,"",0,4,"io",-1,0,-1,0,477,477,"7917","",0,"","","",1,0,0,[],""],["rm_t4-n7918",2,"Amor mio, si fueres\nA la Carraca,\nDe la mejor madera\nCómprame un arca.",2,0,-1,22,"",6,4,"aa",-1,0,-1,0,477,477,"7918","",0,"","","",1,0,0,[],""],["rm_t4-n7919",2,"En la mar hay un pescao\nQue le yaman el inglés,\nCon un letrero que dise:\n«¡Para bino, er de Jerés!»",2,0,-1,22,"",0,4,"e",218,0,-1,0,477,477,"7919","",0,"","","",1,0,0,[],""],["rm_t4-n7920",2,"Biba Medina Sidonia\nY Jerés de la Frontera\nY tambien digo que biba\nSanlúcar de Barrameda.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,477,477,"7920","",0,"","","",1,0,0,[],""],["rm_t4-n7921",2,"Adios, Medina Sidonia;\n¡Cuántos paseos me debes!\n¡Cuántas beses he pisado\nLa sombra de tus paredes!",2,0,-1,22,"",0,4,"ee",-1,0,-1,0,478,478,"7921","",0,"","","",1,0,0,[],""],["rm_t4-n7922",2,"Sanlúcar de Barrameda,\n¡Quién te pudiera traer\nMetido en la fartriquera,\nComo un pliego de papé!",2,0,-1,22,"",0,4,"e",-1,0,-1,0,478,478,"7922","",0,"","","",1,0,0,[],""],["rm_t4-n7923",2,"A Roma se ba por bulas,\nPor tabaco á Gibrartar,\nPor mansaniya á Sanlúcar,\nY á Cádis se ba por sal.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,478,478,"7923","",0,"","","",1,0,0,[],""],["rm_t4-n7924",2,"Si á Rota le apuntaran\nLas baterías,\nEya con sus tomates\nLas jundiría.",2,0,-1,22,"",6,4,"ia",-1,0,-1,0,478,478,"7924","",0,"","","",1,0,0,[],""],["rm_t4-n7925",2,"Un hombre sabio de Rota\nEstaba pensando un dia\nQue si no hubiera tomates,\nEl mundo se acabaría.",2,0,-1,22,"",0,4,"ia",0,0,-1,0,478,478,"7925","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7927",2,"No se ha podido saber\nNi se sabrá á punto fijo\nLos borricos que hay en Rota,\nPorque llega á lo infinito.",2,0,-1,22,"",0,4,"io",-1,0,-1,0,478,478,"7927","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7928",2,"De Sebiya, sebiyano;\nDe Málaga, malagueño;\nYo, para serbir á usté,\nSoy de Orberita, orbereño.",2,0,-1,22,"",0,4,"eo",138,0,-1,0,479,479,"7928","",0,"","","",1,0,0,[],""],["rm_t4-n7929",2,"Camino de Grazalema,\nEnmedio de un olibar,\nHay una fuente que mana\nAgua de amor natural.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,479,479,"7929","",0,"","","",3,0,0,[],""],["rm_t4-n7930",2,"Grazalema entre dos lomas,\nEntre dos lomas y tajos,\nDonde habitan las palomas,\nTortoliyas y arrendajos.",2,0,-1,22,"",1,4,"ao",286,0,-1,0,479,479,"7930","",0,"","","",1,0,0,[],""],["rm_t4-n7931",2,"Grazalema es buena tierra,\nQue es tierra de mucho paño,\nMuchas muchachas bonitas\nY agua fresca en el berano.",2,0,-1,22,"",0,4,"ao",-1,0,-1,0,479,479,"7931","",0,"","","",1,0,0,[],""],["rm_t4-n7932",2,"Ubrique es er primer cielo,\nGrazalema es el portal,\nBiyaluenga el purgatorio,\nY el infierno Benaocaz.",2,0,-1,22,"",3,4,"a",-1,0,-1,0,479,479,"7932","",0,"","","",1,0,0,[],""],["rm_t4-n7933",2,"No sé si me baya á Ubrique,\nO me baya á Grazalema,\nO más bien á Argodonales,\nO á Sebiya, qu' es mi tierra.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,479,479,"7933","",0,"","","",1,0,0,[],""],["rm_t4-n7935",2,"A San Roque lo comparo\nCon el rebés de una tasa;\nTodas son cuestas arriba\nHasta llegar á la plasa.",2,0,-1,22,"",0,4,"aa",123,0,-1,0,480,480,"7935","",0,"","","",3,0,0,[],""],["rm_t4-n7936",2,"En Tarifa no hay justicia,\nNi ménos corregidor,\nNi niña que tenga nobio,\nNi caye que haga á dos.",2,0,-1,22,"",0,4,"o",-1,0,-1,0,480,480,"7936","",0,"","","",1,0,0,[],""],["rm_t4-n7937",2,"Cuatro cosas tiene Ceuta\nQue no las tiene Madrid:\nEl bonito, la caballa,\nEl Hacho y el Rebellin.",2,0,-1,22,"",5,4,"ei",-1,0,-1,0,480,480,"7937","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7938",2,"A Málaga me he de ir\nA comer las abeyanas,\nPorque m' achacan á mí\nLa muerte de una serrana.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,480,480,"7938","",0,"","","",3,0,0,[],""],["rm_t4-n7939",2,"A Málaga me he de ir\nAunque no tenga dinero,\nQue ayí no me ha de fartar\nRopa para andar encueros.",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,480,480,"7939","",0,"","","",3,0,0,[],""],["rm_t4-n7940",2,"En Málaga m' embarqué\nEn un casco de ceboya,\nY bine á desembarcar\nEn la puerta de mi nobia.",2,0,-1,22,"",0,4,"oa",-1,0,-1,0,480,480,"7940","",0,"","","",1,0,0,[],""],["rm_t4-n7941",2,"Málaga, fuerte muralla\nQue contiene al mar soberbio;\nEl mejor puerto de mar\nQue tiene el rey en su reino.",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,480,480,"7941","",0,"","","",2,0,0,[],""],["rm_t4-n7942",2,"Malaguiya, Malaguiya,\nEl rey te quiere bender; (?)\nEr que á Málaga comprare\nDinerito ha de tener.",2,0,-1,22,"",0,4,"e",20,0,-1,0,481,481,"7942","",0,"","","",1,0,0,[],""],["rm_t4-n7944",2,"Pensaban los granadinos\nQue Málaga no tenía\nUn zacatin como el suyo,\nPero tiene mejoría.",2,0,-1,22,"",0,4,"ia",0,0,-1,0,481,481,"7944","",0,"","","",1,0,0,[],""],["rm_t4-n7945",2,"Málaga tiene la fama\nDer bino y del aguardiente,\nDe las muchachas bonitas\nY de los hombres balientes.",2,0,-1,22,"",0,4,"ee",-1,0,-1,0,481,481,"7945","",0,"","","",6,0,0,[],""],["rm_t4-n7947",2,"En Málaga los serenos\nBan disiendo por la caye:\n—Duerma quien tubiere sueño,\nQue yo no dispierto á nádie.",2,0,-1,22,"",0,4,"ae",-1,0,-1,0,481,481,"7947","",0,"","","",4,0,0,[],""],["rm_t4-n7949",2,"Er castiyo e Gibrarfaro\nS' está muriendo de risa,\nDe ber á las malagueñas\nCon peineta y sin camisa.",2,0,-1,22,"",0,4,"ia",68,0,-1,0,482,482,"7949","",0,"","","",1,0,0,[],""],["rm_t4-n7950",2,"En Málaga, amigo mio,\nCome el chico, come el grande,\nCome el rico, come el pobre,\nY ninguno pasa hambre.",2,0,-1,22,"",0,4,"ae",-1,0,-1,0,482,482,"7950","",0,"","","",2,0,0,[],""],["rm_t4-n7951",2,"En Málaga, amigo mio,\nCome el que tiene dinero;\nEl que quiere vaca, vaca;\nY el que carnero, carnero.",2,0,-1,22,"",0,4,"eo",38,0,-1,0,482,482,"7951","",0,"","","",2,0,0,[],""],["rm_t4-n7952",2,"Málaga está en cuatro barrios,\nY sinco con la siudá,\nY ninguno me ha gustado\nComo er de la Trinidá.",2,0,-1,22,"",0,4,"a",9,0,-1,0,482,482,"7952","",0,"","","",4,0,0,[],""],["rm_t4-n7953",2,"Málaga está en cuatro barrios,\nY sinco con los Molinos,\nY ninguno me ha gustado\nComo er de los Capuchinos.",2,0,-1,22,"",0,4,"io",206,0,-1,0,482,482,"7953","",0,"","","",4,0,0,[],""],["rm_t4-n7954",2,"Málaga está en cuatro barrios,\nY sinco con la Mersé,\nY ninguno me ha gustado\nComo er barrio der Perché.",2,0,-1,22,"",0,4,"e",77,0,-1,0,482,482,"7954","",0,"","","",4,0,0,[],""],["rm_t4-n7955",2,"En er barrio der Perché\nDisen que no hay percheleras;\nLa que á mí me percheló,\nMás que perchelera era.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,483,483,"7955","",0,"","","",1,0,0,[],""],["rm_t4-n7957",2,"Más bale una bitoriana\nQue dosientas percheleras;\nQue las bitorianas tienen\nLa sandunga de la tierra.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,483,483,"7957","",0,"","","",1,0,0,[],""],["rm_t4-n7958",2,"Málaga no me consiente,\nNi tampoco sus murayas;\nLas niñas der Mundo Nuebo\nMe disen que no me baya.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,483,483,"7958","",0,"","","",1,0,0,[],""],["rm_t4-n7959",2,"Adios, Mundo Nuebo alegre,\nPlasuela de la Mersé,\nBarrio de los Capuchinos,\n¡Cuándo te borberé á ber!",2,0,-1,22,"",0,4,"e",-1,0,-1,0,483,483,"7959","",0,"","","",1,0,0,[],""],["rm_t4-n7960",2,"Adiós, Málaga la beya,\nLa tierra de los encantos;\nAquer que te yega á ber\nTiene que pensar sien años.",2,0,-1,22,"",0,4,"ao",-1,0,-1,0,483,483,"7960","",0,"","","",4,0,0,[],""],["rm_t4-n7961",2,"Adiós, Málaga la beya,\nTierra donde yo nasí;\nPara todos fuistes madre\nY madrasta para mí.",2,0,-1,22,"",0,4,"i",23,0,-1,0,483,484,"7961","",0,"","","",4,0,0,[],""],["rm_t4-n7962",2,"Adios, Málaga la beya;\nÁ popa te boy mirando,\nCon er trinquete á la bela\nY la berga mareando.",2,0,-1,22,"",0,4,"ao",33,0,-1,0,484,484,"7962","",0,"","","",4,0,0,[],""],["rm_t4-n7963",2,"Fué mi nasimiento en Ronda\nY fué mi madre serrana;\nPor esa rason no cabe\nEn mi pecho una arsion mala.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,484,484,"7963","",0,"rm_t3","","",2,0,0,[],""],["rm_t4-n7964",2,"De la raís del olibo\nNasió mi madre serrana;\nY yo, como soy su hijo,\nNasí de la misma rama.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,484,484,"7964","",0,"","","",1,0,0,[],""],["rm_t4-n7965",2,"Á Ronda, que es tierra jonda\nY tierra de regadío;\nBámonos, serrana, á Ronda,\nQue en Ronda tengo yo un tio.",2,0,-1,22,"",1,4,"o",3,0,-1,0,484,484,"7965","",0,"","","",1,0,0,[],""],["rm_t4-n7966",2,"Tiene la siudá de Ronda\nTres cosas particulares:\nL' alameda, er puente nuebo\nY la esquinita en el aire.",2,0,-1,22,"",0,4,"ae",-1,0,-1,0,484,484,"7966","",0,"","","",1,0,0,[],""],["rm_t4-n7967",2,"En la plaza e la siudá\nEstá laiglesia mayor,\nY másabajito está\nLa cárse y San Juan de Dios.",2,0,-1,22,"",0,4,"o",-1,0,-1,0,484,484,"7967","",0,"","","",1,0,0,[],""],["rm_t4-n7968",2,"Á Ronda se ba por peros,\nA Argônales por mansanas,\nA las Indias por dinero,\nY á la sierra por serranas.",2,0,-1,22,"",0,4,"aa",263,0,-1,0,484,484,"7968","",0,"","","",2,0,0,[],""],["rm_t4-n7969",2,"A Ronda se ba por peros,\nÁ Málaga por batatas,\nY á Guârcaná de mi bida\nSe ba por güenas muchachas.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,485,485,"7969","",0,"","","",2,0,0,[],""],["rm_t4-n7970",2,"De Torrox la caña dulce,\nY de Nerja las batatas;\nDe Yelez el boquerón;\nDe Málaga las muchachas.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,485,485,"7970","",0,"","","",3,0,0,[],""],["rm_t4-n7971",2,"En Málaga benden ubas,\nEn Torremolino peros,\nEn La Pisarra limones\nY en Armogía sombreros.",2,0,-1,22,"",0,4,"eo",22,0,-1,0,485,485,"7971","",0,"","","",1,0,0,[],""],["rm_t4-n7972",2,"Agárrate d' esa rama,\nAunque sea de jiguera;\nBale más un perotiyo\nQue la Pisarriya entera.",2,0,-1,22,"",0,4,"ea",44,0,-1,0,485,485,"7972","",0,"","","",2,0,0,[],""],["rm_t4-n7973",2,"Agárrate d' esa rama,\nAunque sea d' arbarcoque;\nBale más un pisarreño\nQue bentisinco perotes.",2,0,-1,22,"",0,4,"oe",-1,0,-1,0,485,485,"7973","",0,"","","",2,0,0,[],""],["rm_t4-n7974",2,"En Málaga está la planta,\nEn Antequera el rosal,\nY en Archidona la rosa\nQue me tengo de llevar.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,485,485,"7974","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7975",2,"Biba la feria de Beles,\nDonde ban las andalusas,\nY con todos sus caireles\nLos mursianitos de Mursia.",2,0,-1,22,"",0,4,"ua",-1,0,-1,0,485,485,"7975","",0,"","","",1,0,0,[],""],["rm_t4-n7976",2,"Si yo tubiera un ochabo,\nTe compraba medio Rute,\nY las güertas de la Granja,\nY los cortijos der Duque.",2,0,-1,22,"",0,4,"ue",-1,0,-1,0,486,486,"7976","",0,"","","",1,0,0,[],""],["rm_t4-n7978",2,"Tres cosas tiene Hinojosa,\nQue no las tiene Sevilla:\nEl Jagarzal y la Trampa\nY fuente de la Navilla.",2,0,-1,22,"",0,4,"ia",162,0,-1,0,486,486,"7978","",0,"","","",1,0,0,[],""],["rm_t4-n7981",2,"Á los cármenes del Darro\nMe tengo que ir á vivir,\nPorque dicen que se goza\nLa gloria ántes de morir.",2,0,-1,22,"",0,4,"i",157,0,-1,0,486,486,"7981","",0,"","","",3,0,0,[],""],["rm_t4-n7982",2,"Quiero bibir en Granada,\nPorque me gusta el oír\nLa campana de la Bela\nCuando me boy á dormir.",2,0,-1,22,"",0,4,"i",157,0,-1,0,487,487,"7982","",0,"","","",1,0,0,[],""],["rm_t4-n7983",2,"A la entrada de Granada,\nCaye de los Herradores,\nEstá la Bírgen del Triunfo\nCon beintisinco faroles.",2,0,-1,22,"",0,4,"oe",-1,0,-1,0,487,487,"7983","",0,"","","",4,0,0,[],""],["rm_t4-n7984",2,"Pensamiento tiene Darro\nDe casarse con Genil,\nY le ha de llevar en dote\nPlaza Nueva y Zacatin.",2,0,-1,22,"",0,4,"i",-1,0,-1,0,487,487,"7984","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7985",2,"Mira si he corrido tierras,\nQue he estado en el Albaicin,\nEn la carrera del Darro\nY en la puente de Genil.",2,0,-1,22,"",5,4,"i",-1,0,-1,0,487,487,"7985","",0,"","","",15,0,0,[],""],["rm_t4-n7986",2,"Vámonos al Avellano,\nÁ beber agua fresquita,\nPorque dicen que allí está\nLa flor de la canelita.",2,0,-1,22,"",0,4,"ia",50,0,-1,0,487,487,"7986","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n7987",2,"¡Qué buena noche que hace\nPara ir al Algibillo,\nCon una buena guitarra\nY tres pares de palillos!",2,0,-1,22,"",0,4,"io",-1,0,-1,0,487,487,"7987","",0,"","","",5,0,0,[],""],["rm_t4-n7988",2,"Barrio de San Nicolás,\nBarrio de las Comuneras,\nQue debajo de los poyos\nEstá puesta la bandera.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,487,487,"7988","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7989",2,"Adios, calle de Mesones,\nConsuelo de mi barriga,\nQue por cuatro cuartos dan\nCaldo, chanfaina y morcilla.",2,0,-1,22,"",0,4,"ia",-1,0,-1,0,488,488,"7989","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7990",2,"El sacristan de Albolote\nY el cura de Maracena\nIban cantando y diciendo:\n—Dios nos las depare buena.",2,0,-1,22,"",0,4,"ea",59,0,-1,0,488,488,"7990","",0,"","","",3,0,0,[],""],["rm_t4-n7991",2,"En Granada están las flores;\nEn Motril las malas lenguas;\nY en llegando á laAlpujarra,\n¡Viva la gente morena!",2,0,-1,22,"",3,4,"ea",-1,0,-1,0,488,488,"7991","",0,"","","",3,0,0,[],""],["rm_t4-n7992",2,"No te fies de Motril,\nAunque digan «bien te quiero;»\nPues por una caña dulce\nMataron á un artillero.",2,0,-1,22,"",0,4,"eo",38,0,-1,0,488,488,"7992","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n7995",2,"Buena vega tiene Lújar,\nY buen zacatín Rubite,\nY buenas muchachas rubias\nOlíar y Fregenite.",2,0,-1,22,"",0,4,"ie",315,0,-1,0,489,489,"7995","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n7996",2,"Buena vega tiene Loja;\nMejor zacatín Granada;\nPara alamedas, Guadix;\nY para pinares, Baza.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,489,489,"7996","",0,"","","",1,0,0,[],""],["rm_t4-n7997",2,"Mira si he corrido tierras,\nCuando he estado en la Raijana,\nEn el barranco del Negro\nY en la ramblita del Agua.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,489,489,"7997","",0,"palau_cantares, lafuente_madrid","","",15,0,0,[],""],["rm_t4-n7998",2,"Alcázar y los Bargises\nSon pueblos de mi respeto;\nPero le temo á los nabos,\nPorque ¡son tan indigestos!",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,489,489,"7998","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n7999",2,"Mañana voy á Jolúcar,\nA ver á San Cayetano,\nA que me preste dinero\nPara casarme el verano.",2,0,-1,22,"",0,4,"ao",81,0,-1,0,489,489,"7999","",0,"","","",2,0,0,[],""],["rm_t4-n8000",2,"Sabrás que vengo de Dílar\nY te traigo un estadal\nY unos garbanzos tostados;\nPero no los probarás.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,489,489,"8000","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8001",2,"Viva Gualchos, que es mi tierra,\nSan Miguel, que es mi patrón;\nViva la gente morena,\nQue morenita soy yo.",2,0,-1,22,"",0,4,"o",-1,0,-1,0,489,489,"8001","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n8002",2,"A la entrada del Padul\nY á la salida de Dúrcal\nHay un letrero que dice:\n«La cosa está como nunca.»",2,0,-1,22,"",0,4,"ua",-1,0,-1,0,490,490,"8002","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n8003",2,"Almejijar y Notaez,\nCástaras y Torviscon\nY la santa cruz de Murtas\nNos echen su bendicion.",2,0,-1,22,"",0,4,"io",-1,0,-1,0,490,490,"8003","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n8004",2,"En Olíar y Fregenite,\nAlcázar y Torviscon;\nEn estos cuatro lugares\nTengo yo mi corazon.",2,0,-1,22,"",5,4,"ao",-1,0,-1,0,490,490,"8004","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8005",2,"Yo tenía unos amores\nDe pepitas de melón,\nY vino un aire solano\nY se los llevó á Albuñol.",2,0,-1,22,"",0,4,"o",-1,0,-1,0,490,490,"8005","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8006",2,"Antes brujo que gallego;\nAntes gallego que fraile;\nAntes fraile que de Pitres,\nPorque de Pitres no hay ántes.",2,0,-1,22,"",0,4,"ae",-1,0,-1,0,490,490,"8006","",0,"","","",2,0,0,[],""],["rm_t4-n8007",2,"El Tocon, corral de vacas,\nY Brácana, retamar;\nQuien quisiere buenas mozas\nVaya á Alomarte á buscar.",2,0,-1,22,"",0,4,"a",21,0,-1,0,490,490,"8007","",0,"","","",1,0,0,[],""],["rm_t4-n8008",2,"En Castril de la Peña\nDieron una voz,\nY en los Almiceranes\nRespondieron dos.",2,0,-1,22,"",0,4,"o",87,0,-1,0,490,490,"8008","",0,"","","",1,0,0,[],""],["rm_t4-n8009",2,"Quédate con Dios, Jaen,\nY tambien Puerta barrera;\nQue me voy á Leganés\nÁ batallar con Cabrera.",2,0,-1,22,"",0,4,"ea",44,0,-1,0,491,491,"8009","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8010",2,"Tres cosas tiene Cazorla\nQue no las tiene Baeza:\nSan Icisio, Monte Sion,\nLa Vírgen de la Cabeza.",2,0,-1,22,"",0,4,"ea",108,0,-1,0,491,491,"8010","",0,"","","",3,0,0,[],""],["rm_t4-n8011",2,"Villanueva se quema;\nTorafe arde;\nSopla, Villacarrillo,\nQue no se apague.",2,0,-1,22,"",6,4,"ae",-1,0,-1,0,491,491,"8011","",0,"","","",1,0,0,[],""],["rm_t4-n8012",2,"Almería, ¡quién te viera,\nY tus calles paseara,\nY á Santo Domingo fuera,\nÁ oir la misa de alba!",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,491,491,"8012","",0,"","","",1,0,0,[],""],["rm_t4-n8013",2,"A Ribera me fuera\nDe buena gana,\nSi hubiera un extremeño\nQue me llevara.",2,0,-1,22,"",6,4,"aa",-1,0,-1,0,491,491,"8013","",0,"","","",1,0,0,[],""],["rm_t4-n8014",2,"En La Haba, venden habas;\nEn Don Benito, melones;\nEn Villanueva, sandías;\nEn Campanario, serones.",2,0,-1,22,"",0,4,"oe",34,0,-1,0,491,491,"8014","",0,"","","",1,0,0,[],""],["rm_t4-n8015",2,"Don Benito, melones;\nLa Haba, habas;\nVillanueva, panizo;\nNabos, Quintana.",2,0,-1,22,"",6,4,"aa",-1,0,-1,0,491,491,"8015","",0,"","","",1,0,0,[],""],["rm_t4-n8019",2,"No quiero mujer de Herrera,\nAunque me la den de balde;\nLa que no es carabinera\nTiene amistad con un fraile.",2,0,-1,22,"",0,4,"ae",-1,0,-1,0,492,492,"8019","",0,"","","",1,0,0,[],""],["rm_t4-n8020",2,"Vivan los aires morenos\nQue vienen de Guadalupe,\nY pasan por Castilblanco,\nY van á Herrera del Duque.",2,0,-1,22,"",0,4,"ue",-1,0,-1,0,492,492,"8020","",0,"","","",3,0,0,[],""],["rm_t4-n8021",2,"En Peloche no hagas noche;\nEn Herrera, lo que quieras;\nY en Valdecaballeritos\nTe anochezca y no amanezca.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,492,492,"8021","",0,"","","",1,0,0,[],""],["rm_t4-n8023",2,"En la Puebla dicen macho;\nEn Talarrubias, machete;\nEn las Casas de Don Pedro,\n¿Dónde vas, compañerete?",2,0,-1,22,"",0,4,"ee",285,0,-1,0,493,493,"8023","",0,"","","",1,0,0,[],""],["rm_t4-n8024",2,"En Talarrubias hay mozos\nTiradores de la barra;\nY en la Puebla de Alcocer,\nTripones de mala cara.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,493,493,"8024","",0,"","","",1,0,0,[],""],["rm_t4-n8025",2,"Tres cosas tiene este pueblo\nQue no las tiene Sevilla:\nEl alcalde, los potriles\nY la fuente de la villa.",2,0,-1,22,"",0,4,"ia",162,0,-1,0,493,493,"8025","",0,"","","",1,0,0,[],""],["rm_t4-n8026",2,"Valdeganga es la gloria;\nJorquera, el cielo;\nAlcalá, el purgatorio;\nVes, el infierno.",2,0,-1,22,"",6,4,"eo",-1,0,-1,0,493,493,"8026","",0,"","","",1,0,0,[],""],["rm_t4-n8027",2,"Vámonos á Cartagena,\nA ver el mar y sus olas;\nA ver los barcos del rey\nCon banderas españolas.",2,0,-1,22,"",0,4,"oa",317,0,-1,0,493,493,"8027","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n8028",2,"A la una me embarqué;\nA las dos me hice á la vela;\nA las tres, en Alicante;\nA las cuatro, en Cartagena.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,493,493,"8028","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8029",2,"Cartagena de Levante,\nPuerto de mar venturoso,\nDescanso de los navíos\nY de los hombres reposo.",2,0,-1,22,"",0,4,"oo",160,0,-1,0,493,493,"8029","",0,"palau_cantares, lafuente_madrid","","",7,0,0,[],""],["rm_t4-n8030",2,"Adios, Cartagena hermosa,\nPlazuela de la Merced,\nCalle de los Cuatro Santos,\n¡Cuándo te volveré á ver!",2,0,-1,22,"",0,4,"e",-1,0,-1,0,494,494,"8030","",0,"","","",2,0,0,[],""],["rm_t4-n8031",2,"Cartagena de Levante,\nBien te puedes alabar;\nQue Murcia, con ser tan grande,\nNo tiene puerto de mar.",2,0,-1,22,"",0,4,"a",21,0,-1,0,494,494,"8031","",0,"","","",7,0,0,[],""],["rm_t4-n8032",2,"Cartagena me da pena\nY Murcia me da dolor;\n¡Cartagena de mi vida!\n¡Murcia de mi corazon!",2,0,-1,22,"",0,4,"o",-1,0,-1,0,494,494,"8032","",0,"carrizo_salta, palau_cantares, lafuente_madrid, murciano_antiguo","","",5,0,0,[],""],["rm_t4-n8033",2,"En la huerta de Murcia\nPor un chaviquio\nLlenan una capacha\nDe pimentiquios.",2,0,-1,22,"",6,4,"io",-1,0,-1,0,494,494,"8033","",0,"","","",4,0,0,[],""],["rm_t4-n8034",2,"El pantano de Lorca\nSe ha reventado\nY la huerta de Murcia\nSe la ha llevado.",2,0,-1,22,"",6,4,"ao",14,0,-1,0,494,494,"8034","",0,"","","",1,0,0,[],""],["rm_t4-n8037",2,"Son las niñas valencianas\nEstrellitas de la mar,\nQue hacen la guerra á los hombres\nCon su gracioso mirar.",2,0,-1,22,"",0,4,"a",21,0,-1,0,495,495,"8037","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8038",2,"Dicen que Valencia es\nSepultura de cristianos;\nYo digo que la que es\nEs la torre de Serranos.",2,0,-1,22,"",1,4,"ao",318,0,-1,0,495,495,"8038","",0,"","","",4,0,0,[],""],["rm_t4-n8039",2,"Buena tierra es Cartagena,\nPorque tiene cérca el monte;\nPero es mejor Alicante,\nPor el barrio de San Roque.",2,0,-1,22,"",0,4,"oe",-1,0,-1,0,495,495,"8039","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8040",2,"En el muelle de Alicante\nHay mucho que discurrir:\nHan hecho una puerta nueva\nPara entrar y no salir.",2,0,-1,22,"",0,4,"i",157,0,-1,0,495,495,"8040","",0,"palau_cantares","","",5,0,0,[],""],["rm_t4-n8041",2,"En el muelle de Alicante\nHay una hermosa farola,\nPara alumbrar á mi amante,\nQue viene de Barcelona.",2,0,-1,22,"",0,4,"oa",-1,0,-1,0,495,495,"8041","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["rm_t4-n8042",2,"Alicante, por su muelle;\nMúrcia, por sus arrabales;\nOrihuela, por su huerta;\nElche, por sus palmerales.",2,0,-1,22,"",0,4,"ae",26,0,-1,0,495,495,"8042","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8043",2,"Soy de Alicante, señores;\nDe Alicante, y no lo niego;\nComo soy alicantino,\nPor una de Elche me muero.",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,495,495,"8043","",0,"","","",1,0,0,[],""],["rm_t4-n8044",2,"En Elche está Calandura;\nEn Villena, el Orejon; (?)\nY en Caudate está la mona\nPara tocar el reloj.",2,0,-1,22,"",5,4,"o",-1,0,-1,0,496,496,"8044","",0,"","","",3,0,0,[],""],["rm_t4-n8045",2,"Las muchachitas de Alcoy,\nCuando van por agua al rio,\nSe dicen unas á otras:\n—¿Cuándo tendremos marido?",2,0,-1,22,"",0,4,"io",-1,0,-1,0,496,496,"8045","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8046",2,"La plaza del Progreso\nNo tiene flores;\nPero tiene palomas\nY ruiseñores.",2,0,-1,22,"",6,4,"oe",5,0,-1,0,496,496,"8046","",0,"","","",1,0,0,[],""],["rm_t4-n8047",2,"La Fuente Castellana\nTriste suspira,\nCuando pasa algún tiempo\nSin ver las niñas.",2,0,-1,22,"",6,4,"ia",-1,0,-1,0,496,496,"8047","",0,"","","",1,0,0,[],""],["rm_t4-n8048",2,"En la plaza de Oriente\nY en el Retiro\nSe canta por las tardes\nEl pío, pío.",2,0,-1,22,"",6,4,"io",-1,0,-1,0,496,496,"8048","",0,"","","",1,0,0,[],""],["rm_t4-n8049",2,"Con una buena media\nY un buen zapato\nHace una madrileña\nPecar á un santo.",2,0,-1,22,"",6,4,"ao",-1,0,-1,0,496,496,"8049","",0,"palau_cantares","","",2,0,0,[],""],["rm_t4-n8050",2,"Desde aquí te estoy viendo,\nTorre de Humanes,\nQue pareces cabaña\nDe melonares.",2,0,-1,22,"",6,4,"ae",-1,0,-1,0,496,496,"8050","",0,"","","",1,0,0,[],""],["rm_t4-n8051",2,"Carabanchel de Arriba\nDijo al de Abajo:\n—No hay mujer que no tenga\nMarido y majo.",2,0,-1,22,"",6,4,"ao",168,0,-1,0,497,497,"8051","",0,"","","",1,0,0,[],""],["rm_t4-n8052",2,"En Cubas son borrachos,\nY en Griñon, micos;\nY en Carranque rebuznan\nComo borricos.",2,0,-1,22,"",6,4,"io",319,0,-1,0,497,497,"8052","",0,"","","",1,0,0,[],""],["rm_t4-n8053",2,"El aguardiente de Ocaña\nLo llevan á Puerto-Rico;\nLe repican las campanas,\nComo si fuera el obispo.",2,0,-1,22,"",0,4,"io",-1,0,-1,0,497,497,"8053","",0,"","","",3,0,0,[],""],["rm_t4-n8055",2,"Si fueres á Caudilla,\nMira y repara:\nCon el cingolondango\nSacan el agua.",2,0,-1,22,"",6,4,"aa",-1,0,-1,0,497,497,"8055","",0,"","","",1,0,0,[],""],["rm_t4-n8056",2,"Á la Mancha, manchego,\nQue es mala tierra;\nQue la Vírgen no quiso\nPasar por ella.",2,0,-1,22,"",6,4,"ea",-1,0,-1,0,497,497,"8056","",0,"","","",1,0,0,[],""],["rm_t4-n8057",2,"Aunque la Mancha tenga\nDos mil lugares,\nNo hay otro más alegre\nQue Manzanares.",2,0,-1,22,"",6,4,"ae",164,0,-1,0,498,498,"8057","",0,"","","",1,0,0,[],""],["rm_t4-n8058",2,"Desde Manzanaritos\nÁ La Solana\nHay una legüecita\nDe tierra llana.",2,0,-1,22,"",6,4,"aa",4,0,-1,0,498,498,"8058","",0,"","","",1,0,0,[],""],["rm_t4-n8059",2,"Santa Cruz de Mudela,\n¡Cómo reluces!\n¡Cómo suben y bajan\nLos andaluces!",2,0,-1,22,"",6,4,"ue",194,0,-1,0,498,498,"8059","",0,"","","",1,0,0,[],""],["rm_t4-n8060",2,"¿Cómo quieres que en Sigüenza\nSean todos liberales,\nCuando son hijos de curas,\nDe canónigos y frailes?",2,0,-1,22,"",0,4,"ae",-1,0,-1,0,498,498,"8060","",0,"","","",1,0,0,[],""],["rm_t4-n8062",2,"Aunque veis á Castillejo\nEntre romeros y peñas,\nLa cabeza es Castillejo\nY anejo Valdecolmenas.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,498,498,"8062","",0,"","","",1,0,0,[],""],["rm_t4-n8063",2,"En Barajas pepinos,\nEn Belinchon sal,\nY en Tarancon borrachos,\nNo pueden faltar.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,499,499,"8063","",0,"","","",1,0,0,[],""],["rm_t4-n8064",2,"Desde Santoña á Laredo\nMe tengo de pasear,\nPorque tengo una morena\nEn cada puerto de mar.",2,0,-1,22,"",0,4,"a",21,0,-1,0,499,499,"8064","",0,"","","",1,0,0,[],""],["rm_t4-n8065",2,"De Villaviciosa vengo\nDe recoger la manzana,\nY ahora me voy para Oviedo,\nÁ aquella triste montaña.",2,0,-1,22,"",3,4,"aa",-1,0,-1,0,499,499,"8065","",0,"","","",1,0,0,[],""],["rm_t4-n8067",2,"Por un lado tiene el Duero,\nPor otro Peña Tapada,\nPor otro cincuenta cubos,\nPor otro la barbacana.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,499,499,"8067","",0,"","","",1,0,0,[],""],["rm_t4-n8068",2,"Á Galdames le dijo\nSopuerta un dia:\n—Si no es por Montellano,\nTú, ¿qué serías?",2,0,-1,22,"",6,4,"ia",-1,0,-1,0,499,499,"8068","",0,"","","",1,0,0,[],""],["rm_t4-n8069",2,"Las Casas y Seldortun,\nAvellanal y Acabajo\nForman un ramo de flores\nQue se llama Montellano.",2,0,-1,22,"",0,4,"ao",-1,0,-1,0,499,499,"8069","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n8070",2,"Para fuentes, Montellano;\nMontellano para sol;\nMontellano para todo\nLo bueno que Dios crió.",2,0,-1,22,"",0,4,"o",-1,0,-1,0,500,500,"8070","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n8071",2,"El cielo de la Navarra\nEstá vestido de azul;\nPor eso los navarritos\nTienen la sal de Jesús.",2,0,-1,22,"",0,4,"u",-1,0,-1,0,500,500,"8071","",0,"","","",3,0,0,[],""],["rm_t4-n8072",2,"Madre, por una navarra\nDiera todo cuanto tengo,\nSólo por tener amores\nAl otro lado del Ebro.",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,500,500,"8072","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8073",2,"Navarritos son mis ojos;\nNavarritos han de ser;\nHan salido de Navarra\nY á Navarra han de volver.",2,0,-1,22,"",0,4,"e",20,0,-1,0,500,500,"8073","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8075",2,"Aragonés soy, señora;\nYo mi patria no la niego;\nMás vale un aragonés\nQue veinticinco gallegos.",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,500,500,"8075","",0,"","","",1,0,0,[],""],["rm_t4-n8077",2,"Dicen que Valencia es\nJardin de todas las flores;\nYo digo que en Aragon\nSe crian más y mejores.",2,0,-1,22,"",0,4,"oe",5,0,-1,0,501,501,"8077","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n8078",2,"Al otro lado del Ebro\nTengo mis amores, madre,\nY á la Vírgen del Pilar\nLe pido que me los guarde.",2,0,-1,22,"",0,4,"ae",-1,0,-1,0,501,501,"8078","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8079",2,"No me gusta el rigodon\nNi la galop ni la polka;\nComo soy aragonés,\nSólo me gusta la jota.",2,0,-1,22,"",0,4,"oa",-1,0,-1,0,501,501,"8079","",0,"lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8080",2,"Todos los navarros, madre,\nCantan la jota navarra;\nY yo, como aragonés,\nCanto la zaragozana.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,501,501,"8080","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8081",2,"¡Qué gusto es en Zaragoza\nOir á un niño cantar,\nCon la bandurria tocando,\nSi serena noche está!",2,0,-1,22,"",0,4,"a",-1,0,-1,0,501,501,"8081","",0,"palau_cantares","","",5,0,0,[],""],["rm_t4-n8082",2,"Todos los aragoneses\nLlevan al pecho colgada\nLa imágen de su patrona,\nCon una cinta morada.",2,0,-1,22,"",0,4,"aa",49,0,-1,0,501,501,"8082","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],""],["rm_t4-n8083",2,"Bárbaros aragoneses,\nQue habéis querido cambiar\nUn Santo Cristo de asero\nPor la Bírgen der Pilar.",2,0,-1,22,"",0,4,"a",21,0,-1,0,501,501,"8083","",0,"","","",1,0,0,[],""],["rm_t4-n8086",2,"Gallo de la Magdalena,\nCuida de la plaza un rato,\nQue nos vamos á rondar\nA la parroquia del Gancho.",2,0,-1,22,"",0,4,"ao",-1,0,-1,0,502,502,"8086","",0,"","","",5,0,0,[],""],["rm_t4-n8090",2,"Zaragoza, Zaragoza,\nZaragoza de los diablos;\nUna vez que estuve en ella,\n¡Qué bien me enzaragozaron!",2,0,-1,22,"",0,4,"ao",-1,0,-1,0,503,503,"8090","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8091",2,"Adios, noble Zaragoza,\nAdios, los siete portales,\nAdios, la calle del Coso,\nQue es paseo de galanes.",2,0,-1,22,"",0,4,"ae",-1,0,-1,0,503,503,"8091","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8092",2,"Adiós, Zaragoza noble,\nCon castillos y banderas;\nAdiós, Virgen del Pilar;\nAdios, puente de Tudela.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,503,503,"8092","",0,"","","",4,0,0,[],""],["rm_t4-n8093",2,"Adios, Zaragoza noble,\nAdios, pulido arrabal,\nAdios, Cristo de la Seo,\nAdios, Vírgen del Pilar.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,503,503,"8093","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n8094",2,"Mucho vale Zaragoza\nCon su Coso y su arrabal;\nPero más vale Daroca\nCon su hermosa colegial.",2,0,-1,22,"",0,4,"a",1,0,-1,0,503,503,"8094","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8095",2,"Plaza de la Colegial,\nCon tu cárcel y tu cambra,\nEres de Daroca encanto\nY de sus hermosas sala.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,503,503,"8095","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8096",2,"Cobertizos de la plaza,\nFrente de la colegial,\nPor algo Daroca os puso\nTan cérca el santo hospital.",2,0,-1,22,"",0,4,"a",1,0,-1,0,503,503,"8096","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8099",2,"Muro rajado que miras\nDe escolapios el colegio,\nDí á una rubia de estos barrios\nQue de amor por ella muero.",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,504,504,"8099","",0,"","","",2,0,0,[],""],["rm_t4-n8100",2,"Anento tiene agua-llueve\nY laguna Gallo-canta;\nDaroca tiene su mina\nY cien muros que la ensalzan.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,504,504,"8100","",0,"","","",2,0,0,[],""],["rm_t4-n8101",2,"Fuente de los veinte caños,\nDonde tanto se murmura,\n¿Has oido si me quiere\nLa sobrinica del cura?",2,0,-1,22,"",0,4,"ua",17,0,-1,0,504,504,"8101","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8102",2,"Sólo quiero que te vuelvas\nComo el Mambrú de la fuente,\nSi me dejaras por otro,\nCuando tanto sé quererte.",2,0,-1,22,"",0,4,"ee",-1,0,-1,0,504,504,"8102","",0,"","","",2,0,0,[],""],["rm_t4-n8103",2,"Como aquel hombre de piedra\nQue en la Trinidad está\nQuiero que te vuelvas tú\nSi no dices la verdad.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,504,504,"8103","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8104",2,"En la plaza de San Pedro\nSe crian los ababoles;\nEn la plaza de Santiago\nUnas chicas como soles.",2,0,-1,22,"",0,4,"oe",27,0,-1,0,505,505,"8104","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8105",2,"En la plaza de Santiago\nTiene un mercado Daroca\nY una fuente donde abrasan\nSus corazones las mozas.",2,0,-1,22,"",0,4,"oa",-1,0,-1,0,505,505,"8105","",0,"","","",4,0,0,[],""],["rm_t4-n8106",2,"Mucho me quiere Daroca;\nSu puerta baja me llama\nY sus muchachas hermosas\nMe dicen que no me vaya.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,505,505,"8106","",0,"palau_cantares","","",3,0,0,[],""],["rm_t4-n8107",2,"Santa Ana está en el Pozuelo;\nSan Severino en Ainzon;\nLos capuchinos en Borja;\nLa cruz en Fuendejalon.",2,0,-1,22,"",0,4,"ao",-1,0,-1,0,505,505,"8107","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n8108",2,"En la Villa está San Marcos;\nEn Montón, San Agustín;\nEn Fuentes, Santa Quiteria;\nY en Morata, San Martin.",2,0,-1,22,"",0,4,"i",211,0,-1,0,505,505,"8108","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n8109",2,"Calatorao tiene un Cristo\nY otro Cristo Balaguer;\nDaroca sus corporales\nY sus amantes Teruel.",2,0,-1,22,"",0,4,"e",-1,0,-1,0,505,505,"8109","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8110",2,"En Burbáguena hay hermosas;\nEn Báguena, bullangueras;\nEn San Martin, salerosas;\nEn Daroca, retrecheras.",2,0,-1,22,"",1,4,"ea",103,0,-1,0,505,505,"8110","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n8111",2,"Vega hermosa del Jiloca,\nCon tus sombríos nogales,\nNo envidies á la del Ebro;\nMás que ella mil veces vales.",2,0,-1,22,"",0,4,"ae",26,0,-1,0,506,506,"8111","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8112",2,"No te cases, niña, en Córtes,\nNi en Fréscano, ni en Mallen;\nCásate, niña, en Tabuenca,\nQue es lugar de mucha miel.",2,0,-1,22,"",5,4,"e",-1,0,-1,0,506,506,"8112","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8113",2,"No compres leña en Cosuenda,\nNi en Aguaron compres pan,\nNi mujer en Cariñena,\nQue todo te saldrá mal.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,506,506,"8113","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8114",2,"Zaragoza, Burgo y Fuentes,\nQuinto, la Zayda y Samper;\nAlcañiz y Valdealgorfa,\n¿Cuándo os volveré yo á ver?",2,0,-1,22,"",0,4,"e",20,0,-1,0,506,506,"8114","",0,"","","",2,0,0,[],""],["rm_t4-n8115",2,"En Calanda venden cocios;\nEn Alcorisa, pucheros;\nEn Alcañiz, buenas chicas;\nY en Caspe, buenos mancebos.",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,506,506,"8115","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n8116",2,"Aunque me gusta Alcañiz\nPor su calle de Vicente,\nPrefiero á Castelserás,\nPor su placica del Puente.",2,0,-1,22,"",0,4,"ee",15,0,-1,0,506,506,"8116","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n8117",2,"No compres mula en Teruel,\nNi en Albarracín ganado,\nNi en Francia tomes mujer,\nQue todo te saldrá malo.",2,0,-1,22,"",0,4,"ao",-1,0,-1,0,506,506,"8117","",0,"lafuente_madrid","","",2,0,0,[],""],["rm_t4-n8118",2,"Adios, Tortosa famosa,\nRodeada de balcones,\nEnmedio una rica fuente,\nEncima un ángel de amores.",2,0,-1,22,"",0,4,"oe",-1,0,-1,0,507,507,"8118","",0,"","","",3,0,0,[],""],["rm_t4-n8119",2,"Dicen que las andaluzas\nVan derramando la sal;\nNosotras las catalanas,\nCanela pura, que es más.",2,0,-1,22,"",0,4,"a",-1,0,-1,0,507,507,"8119","",0,"","","",1,0,0,[],""],["rm_t4-n8120",2,"Para aceitunas, Sevilla;\nPara turrón, Alicante;\nPara flores, Barcelona;\nY para muchachas, Cádiz.",2,0,-1,22,"",5,4,"ai",-1,0,-1,0,507,507,"8120","",0,"","","",1,0,0,[],""],["rm_t4-n8121",2,"Sevilla, para el regalo;\nMadrid, para la nobleza;\nPara tropas. Barcelona;\nPara jardines, Valencia.",2,0,-1,22,"",0,4,"ea",-1,0,-1,0,507,507,"8121","",0,"","","",3,0,0,[],""],["rm_t4-n8122",2,"Tres Cádiz tiene Sevilla,\nY tres Sevillas Madrid,\nY tres Madrid Barcelona,\nTres Barcelonas París.",2,0,-1,22,"",0,4,"i",-1,0,-1,0,507,507,"8122","",0,"","","",1,0,0,[],""],["rm_t4-n8123",2,"De torres, la de Sevilla;\nDe villas, la de Requena;\nDe puentes, el de Segovia;\nY de puertos, Cartagena.",2,0,-1,22,"",0,4,"ea",59,0,-1,0,507,507,"8123","",0,"","","",1,0,0,[],""],["rm_t4-n8125",2,"Málaga tiene un castillo,\nGranada tiene su Alhambra,\nY Zaragoza su Coso,\nY Sevilla su Giralda.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,508,508,"8125","",0,"","","",3,0,0,[],""],["rm_t4-n8126",2,"Para granadas, Alcira;\nDe vinos, el Jerez seco;\nRicas guindas, las de Toro;\nY pan sabroso, el de Meco.",2,0,-1,22,"",0,4,"eo",320,0,-1,0,508,508,"8126","",0,"","","",1,0,0,[],""],["rm_t4-n8127",2,"De Candelario, chorizos;\nContrabando, en Ceclavin;\nDe Villalon, rico queso;\nY buen salchichon, en Vich.",2,0,-1,22,"",5,4,"i",-1,0,-1,0,508,508,"8127","",0,"","","",1,0,0,[],""],["rm_t4-n8129",2,"En teniendo el castellano\nVino, ajos, trigo y cebada,\nNo deja la plaza en Julio\nNi en el Enero la capa.",2,0,-1,22,"",0,4,"aa",-1,0,-1,0,508,508,"8129","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8130",2,"Venga el gallego á segar,\nMiserable jornalero;\nQue los hombres de Castilla\nTienen el trabajo á ménos.",2,0,-1,22,"",0,4,"eo",-1,0,-1,0,508,508,"8130","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["rm_t4-n8131",2,"Castellano, castellano,\nNo te vayas á Castilla;\nQue tienes en Aragon\nQuien te quiere y quien te estima.",2,0,-1,22,"",0,4,"ia",-1,0,-1,0,508,508,"8131","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["rm_t4-n8132",2,"Todas las flores del campo\nLas cautiva el mes de Enero,\nY en llegando Abril y Mayo\nSalen de su cautiverio.",2,0,-1,23,"",0,4,"eo",-1,0,-1,0,535,535,"8132","",0,"","","",1,0,0,[],""],["rm_t4-n8133",2,"Junio es un mes de infortunio;\nPalabras que en él se dan\nVienen con San Juan en Junio\nY con San Pedro se van.",2,0,-1,23,"",1,4,"a",147,0,-1,0,535,535,"8133","",0,"","","",1,0,0,[],""],["rm_t4-n8134",2,"Tiene Junio tres verbenas\nQue empiezan con San Antonio;\nY son tres noches muy buenas\nPara dar gusto al demonio\n[Comprar un saco de penas\nY hacer un mal matrimonio.]",2,0,-1,23,"",9,6,"oo",169,0,-1,0,535,535,"8134","",0,"","","",1,0,0,[],""],["rm_t4-n8137",2,"El sol se va poniendo;\nDicen las flores:\n—Ya se va quien nos daba\nBellos colores.",2,0,-1,23,"",6,4,"oe",5,0,-1,0,536,536,"8137","",0,"fernan_caballero","","",2,0,0,[],""],["rm_t4-n8139",2,"—Cuando la perdiz canta,\nNublado viene.\n—No hay más señal de agua\nQue cuando llueve.",2,0,-1,23,"",6,4,"ee",-1,0,-1,0,536,536,"8139","",0,"fernan_caballero","","",4,0,0,[],""],["rm_t4-n8140",2,"Por San Juan y San Pedro\nPintan las uvas;\nPara el quince de Agosto\nYa están maduras.",2,0,-1,23,"",6,4,"ua",-1,0,-1,0,536,536,"8140","",0,"","","",2,0,0,[],""],["rm_t4-n8141",2,"Ya salen las galeras\nDel puerto, madre,\nCon las velas tendidas\nY en popa el aire.",2,0,-1,23,"",6,4,"ae",-1,0,-1,0,536,536,"8141","",0,"","","",1,0,0,[],""],["rm_t4-n8142",2,"Aunque soy tan chiquitita,\nYa vengo de trabajar:\nVengo de sacar las vacas\nQue van al campo á pastar.",2,0,-1,23,"",0,4,"a",21,0,-1,0,537,537,"8142","",0,"","","",1,0,0,[],""],["rm_t4-n8144",2,"Un canario afligido\nFué á un tintorero,\nY le dijo cantando:\n—Mi color quiero.—\nY él le respondió:\n—Ese color tan fino\nNo lo tengo yo.",2,0,-1,23,"",4,7,"o",2,0,-1,0,537,537,"8144","",0,"","","",1,0,0,[],""],["rm_t4-n8145",2,"A la sombra de un pino\nMe senté un viérnes,\nA contarle las piñas\nQue un pino tiene.\nSegun mi cuenta,\nTenía el pino piñas\nCiento cincuenta.",2,0,-1,23,"",4,7,"ea",229,0,-1,0,537,537,"8145","",0,"","","",1,0,0,[],""],["rm_t4-n8149",2,"¿Quién te ha hecho esas medias,\nRico torero,\nQu' en las cuchiyas yebas\nTodo el ensierro,\n[Picadores, chuliyos,\nBanderiyeros]?",2,0,-1,23,"",9,6,"eo",-1,0,-1,0,538,538,"8149","",0,"","","",1,0,0,[],""],["rm_t4-n8150",2,"Ya murió Sirineo;\nMe pongo luto;\nYa no boy á la plasa\nCon tanto gusto.\nPorque tenía\nRemuchísima grasia\nCuando salia.",2,0,-1,23,"",4,7,"aa",-1,0,-1,0,538,538,"8150","",0,"","","",1,0,0,[],""],["rm_t4-n8152",2,"Er barquito der bapó\nEstá jecho con idea;\nQu' en echándole carbon,\nNabega contra marea.",2,0,-1,23,"",0,4,"ea",54,0,-1,0,538,538,"8152","",0,"","","",1,0,0,[],""],["rm_t4-n8153",2,"Er barquiyo der bapó\nNo tiene bela ni remo;\nQue le jase chasnelá\nLa maquiniya der fuego.",2,0,-1,23,"",0,4,"eo",-1,0,-1,0,538,539,"8153","",0,"","","",1,0,0,[],""],["rm_t4-n8155",2,"Cuando la máquina sale\nDe Sebiya para Utrera,\nSi no fuera por er pito,\n¡Cuántas desgrasias hubiera!",2,0,-1,23,"",0,4,"ea",44,0,-1,0,539,539,"8155","",0,"","","",1,0,0,[],""],["rm_t4-n8156",2,"Las gitana' y los gitanos\nCuando tienen un sentí\nLo manifiestan cantando,\nY eso te susede á tí.",2,0,-1,23,"",0,4,"i",23,0,-1,0,539,539,"8156","",0,"","","",1,0,0,[],""],["rm_t4-n8158",2,"La gloria de los gitanos\nEs un cochino á la puerta,\nUna oya de frijones\nY la fragua siempre alerta.",2,0,-1,23,"",0,4,"ea",267,0,-1,0,539,539,"8158","",0,"","","",1,0,0,[],""],["rm_t4-n8160",2,"Ar pan le yaman manró,\nAr tosino, bale-bale,\nA la iglesia, la cangrí,\nY el estaribé á la cárse.",2,0,-1,23,"",0,4,"ae",-1,0,-1,0,539,539,"8160","",0,"","","",1,0,0,[],""],["rm_t4-n8163",2,"Por la caye ba un tio\nQue dise, dise:\n—Componer abanicos\nY echar países.—\nQu' ha dicho, ha dicho:\n—Componer las sombriyas,\nLos abanicos.",2,0,-1,23,"",4,7,"io",-1,0,-1,0,540,540,"8163","",0,"","","",1,0,0,[],""],["rm_t4-n8166",2,"A clabo y canela\nGüele mi jarmin;\nY er que no güela - 'canelita y clabo,\nNo sabe istinguí.",2,0,-1,23,"",3,4,"i",-1,0,-1,0,540,540,"8166","",0,"","","",1,0,0,[],""],["rm_t4-n8169",2,"Asitunas partías;\nTres por un cuarto;\nY á tí, por ser bonita,\nTe boy á dar cuatro.",2,0,-1,23,"",6,4,"ao",-1,0,-1,0,541,541,"8169","",0,"","","",1,0,0,[],""],["rm_t4-n8171",2,"En el mar hay una torre,\nY en la torre una bentana,\nY en la bentana una niña\nQue á los marineros yama.",2,0,-1,23,"",0,4,"aa",-1,0,-1,0,541,541,"8171","",0,"","","",2,0,0,[],""],["rm_t4-n8172",2,"La sirenita del mar\nEs una pulida dama,\nQue, por una maldición,\nLa tiene Dios en el agua.",2,0,-1,23,"",0,4,"aa",-1,0,-1,0,541,541,"8172","",0,"","","",2,0,0,[],""],["rm_t4-n8173",2,"De la oriya der mar bengo,\nDe oir cantá á la sirena;\n¡Bárgame Dios, qué bien canta\nUna cosa tan pequeña!",2,0,-1,23,"",0,4,"ea",-1,0,-1,0,541,541,"8173","",0,"","","",1,0,0,[],""],["rm_t4-n8174",2,"Las sirenitas del mar\nCantan muy pulidamente;\nEl que las oye cantar\nCercana tiene la muerte.",2,0,-1,23,"",0,4,"ee",-1,0,-1,0,541,545,"8174","",0,"","","",1,0,0,[],""],["carrizo_salta-p0012-01",3,"De Peralta el regimiento,\nY este bien templado acero,\nSostuvo el Desaguadero,\nY dio la Amiraya escarmiento.",3,1,0,24,"CAPITULO PRIMERO",11,4,"eo",-1,0,-1,0,12,12,"","",0,"","","",1,0,0,[],""],["carrizo_salta-p0015-03",3,"Mama se llama Apacheta,\nY mi padre Cerro Negro,\nYo me llamo Cachipampa,\nMi apellido es Hervidero.",3,1,0,24,"CAPITULO PRIMERO",0,4,"eo",-1,0,-1,0,15,15,"","",0,"","","",2,0,0,[],""],["carrizo_salta-p0018-06",3,"Tres, cuatro, son las Marías,\nCinco, seis, los elementos,\nSiete, ocho, son las cabrillas,\nNueve, diez, los mandamientos.",3,1,0,24,"CAPITULO PRIMERO",0,4,"eo",234,0,-1,0,18,19,"","",0,"","","",1,0,0,[],""],["carrizo_salta-p0023-03",3,"No sigas ese camino,\nNo seas orgulloso y terco,\nNo te vayas a perder,\nComo la ciudad de Esteco.",3,1,0,24,"CAPITULO PRIMERO",3,4,"eo",-1,0,-1,0,23,23,"","",0,"","","",1,0,0,[],""],["carrizo_salta-p0026-02",3,"No como y doy de comer,\nNo visto y doy de vestir,\nSoy libre y he de servir,\n¿Esto, cómo puede ser?",3,1,0,24,"CAPITULO PRIMERO",11,4,"e",20,0,-1,0,26,26,"","",0,"","","",1,0,0,[],""],["carrizo_salta-p0028-03",3,"¡Canta nomás, jiuguerito!\nCanta nomás, tu canción,\nDespedite de tus cantos,\nQue ya te llega el halcón.",3,1,0,24,"FORMA ESPAÑOLA",0,4,"o",31,0,-1,0,28,28,"","",0,"","","",1,0,0,[],""],["carrizo_salta-p0031-01",3,"Do Tolombón hi venío,\nEn un caballo lobuno,\nHi visto animales gordos,\nPero como Vd. ninguno.",3,1,0,24,"CAPITULO SEGUNDO",0,4,"uo",230,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["carrizo_salta-p0032-02",3,"Carnaval alegre,\nTriste para mí,\nBien haiga la tierra,\nDonde yo nací.",3,1,0,24,"CAPITULO SEGUNDO",0,4,"i",23,0,-1,0,32,32,"","",0,"","","",2,0,0,[],""],["carrizo_salta-p0034-02",3,"De la falda de aquel cerro,\nViene una piedra rodando,\nHacete a lao de la güella,\nQue no te pegue en la frente.",3,1,0,24,"CAPITULO SEGUNDO",5,4,"ee",-1,0,-1,0,34,34,"","",0,"","","",2,0,0,[],""],["carrizo_salta-p0053-01",3,"Un padre que niega a un hijo\nPor una deuda de herencia,\nJamás descansará su alma\nSin descargar la conciencia.",3,1,0,24,"CAPITULO CUARTO",0,4,"ea",46,0,-1,0,53,53,"","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0002-02",3,"Se me ha perdido una niña,\nSe me ha perdido una niña,\nQue Catalina se llama, sí, si\nQue Catalina se llama.\nTodos los días de fiesta,\nTodos los días de fiesta\nSu padre la castigaba, sí, sí\nSu padre la castigaba,\nPorque no quería hacer,\nPorque no quería hacer",3,1,0,25,"SE ME HA PERDIDO UNA NIÑA",18,10,"e",-1,0,-1,0,56,56,"R-2","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0004-a-01",3,"Estaba la niña linda\nSentada al pie de un laurel,\nCon los pies a la frescura,\nViendo las aguas correr;",3,1,0,25,"ESTABA LA NIÑA LINDA",0,4,"e",-1,0,-1,0,58,58,"R-4-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nr0006-a-01",3,"Entre San Pedro y San Pablo\nHicieron un barco nuevo,\nEl barco era de bronce,\nY los remuebles de acero.",3,1,0,25,"ENTRE SAN PEDRO Y SAN PABLO",0,4,"eo",-1,0,-1,0,60,60,"R-6-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0010-03",3,"Le ofrezco alimento,\nDe migas de pan;\nPara que se abrigue\nTambién l'hi de dar,\nUna frazadita,\nNo la tengo acá,\nCorriendo a mi casa,\nLa voy a buscar,\nLa cuna, la almohada,\nLe voy a mandar.",3,1,0,25,"SEÑORA YO HE VISTO UN NIÑO >C",18,10,"a",21,0,-1,0,63,63,"R-10","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0012-01",3,"Estaba la Liona, estaba,\nEntre la paz y la guerra,\nCon sus dos hijas doncellas,\nBlanca Flor y Filomena.\nDe allá sale Don Leonardo\nSe enamoró de una de ellas.\nSe casó con Blanca Flor",3,1,0,25,"ESTABA LA LIONA ESTABA",4,7,"o",-1,0,-1,0,63,63,"R-12","",0,"","","",3,0,0,[],""],["carrizo_salta-nr0012-03",3,"Ya lo iban a fusilar,\nDon León bajó la cabeza\nY díjo: ¿cómo ha de ser?\n¿Me van a quitar la vida?\n¡Dejaré de padecer!",3,1,0,25,"ESTABA LA LIONA ESTABA",7,5,"e",20,0,-1,0,64,64,"R-12","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0012-c-01",3,"Ya bajó un pastor de vella\nSe apasionó de una de ellas,\nSe bajó por Filomena\nSe casó con Blanca Flor.\nEl año que se casó,",3,1,0,25,"YA BAJO UN PASTOR DE VELLA",7,5,"o",-1,0,-1,0,64,64,"R-12-c","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0014-b-01",3,"Estaba un pastor un día,\nDeleitado en su ganado;\nSalió una dama y le dice:\n—De tí vivo enamorado.\nResponde el pastor y dice:",3,1,0,25,"ESTABA UN PASTOR UN DÍA",7,5,"ie",-1,0,-1,0,67,67,"R-14-b","",0,"","","",2,0,0,[],""],["carrizo_salta-nr0015-02",3,"A la orilla de un río,\nUna doncella,\nBordaba pañitos de oro\nPara la reina.\nEn lo mejor del bordado\nLe faltó seda.\nPasó un vendedor de sedas\n¿Quién compra seda?\n—¿De qué color es la seda?\n—Azul y blanca.",3,1,0,26,"A LA ORILLA DE UN RIO",18,10,"aa",-1,0,-1,0,69,69,"R-15","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0017-01",3,"A la rueda la batata,\nComeremos ensalada,\nComo comen los señores,\nNaranjitas y limones,\nArropé, arropé,\nSentaditos tomando café.",3,1,0,26,"A LA RUEDA LA BATATA",9,6,"e",77,0,-1,0,69,69,"R-17","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0018-01",3,"Al pasar la barca\nMe dijo el barquero:\n—Las niñas bonitas\nNo pagan dinero.\n—Yo no soy bonita\nNi lo quiero ser,\nPorque las bonitas\nSuelen padecer.\n¡Arriba, abajo\nLa barca de San José!",3,1,0,26,"AL PASAR LA BARCA",18,10,"e",-1,0,-1,0,69,69,"R-18","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0021-02",3,"¿Para qué tantas flores\nSi no son para mí?\nYo me muero de amores\nYo me muero por tí.",3,1,0,26,"BAJO UN ÁNGEL DEL CIELO",1,4,"i",23,0,-1,0,70,70,"R-21","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0027-01",3,"Es la melindrosa\nDe tal condición\nQue le dio un insulto\nAl ver un ratón.",3,1,0,26,"ES LA MELINDROSA",0,4,"o",31,0,-1,0,72,72,"R-27","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0027-02",3,"Al estar cosiendo\nEn el pasadizo,\nCon el aire el hilo,\nLe dió el romadizo.",3,1,0,26,"ES LA MELINDROSA",0,4,"io",-1,0,-1,0,72,72,"R-27","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0027-03",3,"Al tomar un libro\nSe le cayó una hoja\nLe pegó en el pie\nY la dejó coja.",3,1,0,26,"ES LA MELINDROSA",0,4,"oa",146,0,-1,0,72,72,"R-27","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0027-04",3,"Ella está en la cama\nMuy de gravedad,\nPor haberse puesto\nMedias sin sahumar.",3,1,0,26,"ES LA MELINDROSA",0,4,"a",-1,0,-1,0,72,72,"R-27","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0027-05",3,"Está muy enferma\nDe mucho cuidado,\nPor haberse puesto\nUn botín helado.",3,1,0,26,"ES LA MELINDROSA",0,4,"ao",14,0,-1,0,72,72,"R-27","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0027-06",3,"Ella sigue enferma\nY de muchos días,\nPor haberse puesto\nLa sortija fría.",3,1,0,26,"ES LA MELINDROSA",0,4,"ia",-1,0,-1,0,72,72,"R-27","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0027-07",3,"Al tomar el té\nEn una tazuela,\nPorque estaba tibia\nSe cayó una mula.",3,1,0,26,"ES LA MELINDROSA",5,4,"ua",-1,0,-1,0,72,72,"R-27","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0028-01",3,"Gallinita ciega\n—¿Qué has perdido?\n—Una aguja y un dedal\nEn el campo el totoral.\n—Yo te la tengo\nY no te la hi de entregar.\nBusque, si la puede hallar.",3,1,0,26,"GALLINITA CIEGA",4,7,"a",21,0,-1,0,72,72,"R-28","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0030-02",3,"¡San Sinforoso!\nDe encontrar esposo.\n¡San Miguel!\nQue me sea fiel.\n¡San Bonifacio!\nQue tenga palacio.\n¡San Gabino!\nQue no beba vino.\n¡San Julián!\nQue no sea haragán.",3,1,0,26,"KYRIE, YO QUISIERA",18,10,"a",147,0,-1,0,73,73,"R-30","",0,"","","",1,0,0,[],""],["carrizo_salta-nr0034-01",3,"Lori, vilori,\nVicente colori,\nLori virín,\nContra virín\nPícaro choti\n¡Fuera chicoti!",3,1,0,26,"LORI VILORI",9,6,"oi",331,0,-1,0,74,74,"R-34","",0,"","","",1,0,0,[],""],["carrizo_salta-p0080-02",3,"Y nada quisiste oír,\nNada quisiste escuchar,\nY el plazo te iba a llegar,\nLa hora se iba a cumplir,\nEn que debías morir,\nEn el lecho del placer\nSin que puedas merecer,",3,1,0,27,"^ . ^ T-,.WX-»T^ NO SIGAS ESE CAMINO",4,7,"e",20,0,-1,0,80,80,"","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0001-01",3,"Don Juan Facundo Quiroga,\nGeneral de mucho bando,\nQue tuvo tropas de líneas,\nMuchos pueblos a su mando.",3,1,0,27,"",0,4,"ao",33,0,-1,0,88,88,"C-1","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0004-01",3,"Salta, Tucumán, Santiago,\nSe hallaban desavenidos,\nMarchó Quiroga a arreglarlos\nPara dejarlos unidos.",3,1,0,27,"",0,4,"io",255,0,-1,0,88,88,"C-4","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0005-01",3,"Al partir le dice al pueblo\nComo algo que ya presiente:\nSi salgo bien, volveré,\nSi no ¡Adiós, para siempre!",3,1,0,27,"",0,4,"ee",-1,0,-1,0,88,88,"C-5","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0006-01",3,"Al ausentarse Quiroga\nYa le anunciaba el destino,\nQue había de perder la vida,\nEn ese largo camino.",3,1,0,27,"",0,4,"io",199,0,-1,0,88,88,"C-6","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0006-02",3,"Llevaba por compañero\nA su secretario Ortíz\nY apuraba la galera\nEn aquel viaje infeliz.",3,1,0,27,"",0,4,"i",335,0,-1,0,88,88,"C-6","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0008-01",3,"A pocas horas de andar\nEn un arroyo fangoso,\nSe le agarró la galera,\nY allí se puso penoso.",3,1,0,27,"",0,4,"oo",160,0,-1,0,88,88,"C-8","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0009-01",3,"Acude el maestro de posta,\nMás no pudiendo salir,\nAl maistro mismo, Quiroga,\nA las varas lo hizo uñir.",3,1,0,27,"",0,4,"i",157,0,-1,0,88,88,"C-9","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0010-01",3,"Al fin pudieron zafar,\nY como una exhalación\nCruzaba el coche la pampa,\nSin hallar interrupción.",3,1,0,27,"",0,4,"o",31,0,-1,0,88,88,"C-10","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0011-01",3,"En cada posta que llega,\nPregunta muy afligido;\nLa hora que ha pasado un chasqui\nDe Buenos Aires venido.",3,1,0,27,"",0,4,"io",101,0,-1,0,88,88,"C-11","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0012-01",3,"Le contestan que hará una hora,\nEntonces, con duro acento,\n¡Caballos! les pega el grito,\n¡Sin pérdida de momento!",3,1,0,27,"",0,4,"eo",94,0,-1,0,88,88,"C-12","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0013-01",3,"Y su marcha continúa,\nMás quiso también el cielo,\nMolestar a ese bandido\nQue había ensangrentado el suelo.",3,1,0,27,"",0,4,"eo",10,0,-1,0,88,89,"C-13","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0014-01",3,"Durante tres días seguidos\nLe hace llover permanente;\nSe pone el camino horrible\nConvertido en un torrente.",3,1,0,27,"",0,4,"ee",15,0,-1,0,89,89,"C-14","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0015-01",3,"Al entrar en Santa Fe,\nSe le aumenta su inquietud\nY en desesperada angustia,\nSe pone con prontitud.",3,1,0,27,"",0,4,"u",278,0,-1,0,89,89,"C-15","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0017-01",3,"Sufre una horrible agonía\nAl preveer una parada,\nY grita ¡Traigan caballos!\nCon una voz angustiada.",3,1,0,27,"",0,4,"aa",49,0,-1,0,89,89,"C-17","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0018-01",3,"Causaba asombro de ver\nEn este hombre tan terrible,\nEse extraño sobresalto\nDonde el miedo era visible.",3,1,0,27,"",0,4,"ie",259,0,-1,0,89,89,"C-18","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0019-01",3,"Después que logran marchar\nDice, viendo para atrás:\n—\"Si salgo de Santa Fe\nNo temo por lo demás\".",3,1,0,27,"",0,4,"a",51,0,-1,0,89,89,"C-19","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0020-01",3,"Al pasar el río Tercero\nTodos los gauchos acuden,\nA ver a ese hombre famoso,\nTal vez que en algo le ayuden.",3,1,0,27,"",0,4,"ue",336,0,-1,0,89,89,"C-20","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0021-01",3,"De allí lo hicieron pasar\nCasi alzando la galera,\nPor último, llega a Córdoba,\nDonde Reinafé lo espera.",3,1,0,27,"",0,4,"ea",44,0,-1,0,89,89,"C-21","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0022-01",3,"Estando en la posta ya,\nPidiendo a gritos, caballos,\nHa llegado Reinafé,\nSolícito a saludarlo.",3,1,0,27,"",0,4,"ao",-1,0,-1,0,89,89,"C-22","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0023-01",3,"Quiroga a las nueve y media\nHabía a este punto llegado,\nNo encontró caballo pronto\nPor su arribo inesperado.",3,1,0,27,"",0,4,"ao",14,0,-1,0,89,89,"C-23","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0024-01",3,"Muy amable Reinafé\nLo invitaba atentamente:\n—Pase en la ciudad la noche\nLo atenderé dignamente.",3,1,0,27,"",0,4,"ee",15,0,-1,0,89,89,"C-24","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0025-01",3,"Pero el salvaje Quiroga,\nSin ninguna educación,\nDice: ¡Caballos preciso!\nPara mejor atención.",3,1,0,27,"",0,4,"o",31,0,-1,0,89,89,"C-25","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0026-01",3,"Viéndose así Reinafé\nPor este hombre, despreciado,\nSe regresó a la ciudad\nEnteramente humillado.",3,1,0,27,"",0,4,"ao",14,0,-1,0,89,89,"C-26","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0027-01",3,"Le llevaron los caballos\nA las doce de la noche,\nHora en que siguió su viaje\nCon Ortíz dentro del coche.",3,1,0,27,"",0,4,"oe",337,0,-1,0,89,89,"C-27","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0028-01",3,"Al fin Quiroga llegó,\nA Tucumán y Santiago,\nArregló todas las cosas\nY emprende su viaje aciago.",3,1,0,27,"",0,4,"ao",207,0,-1,0,89,89,"C-28","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0029-01",3,"¡A Córdoba! pega el grito,\nY los postillones tiran,\nResuenan los latigazos\nY los caballos se estiran.",3,1,0,27,"",0,4,"ia",338,0,-1,0,89,89,"C-29","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0030-01",3,"Quiroga lo sabe todo,\nHasta el peligro salvado,\nSabe el grande que le espera\nDel enemigo burlado.",3,1,0,27,"",0,4,"ao",14,0,-1,0,89,89,"C-30","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0031-01",3,"Mientras tanto Reinafé\nLe prepara los puñales,\nQue habían de acabar con él\nEn desiertas soledades.",3,1,0,27,"",0,4,"ae",-1,0,-1,0,89,89,"C-31","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0032-01",3,"Proponen los Reinafé,\nComo hombres muy advertidos,\nLlamar a un tal Santos Pérez\nY a otros gauchos pervertidos.",3,1,0,27,"",0,4,"io",255,0,-1,0,89,89,"C-32","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0033-01",3,"Santos Pérez se presenta,\nComo mozo de obediencia\nY santas noches, le dice,\n¿Cómo se halla Vuecelencia?",3,1,0,27,"",0,4,"ea",46,0,-1,0,89,89,"C-33","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0034-01",3,"Allí mismo le proponen\nEl matar a Don Facundo,\nHaciéndole ver el bien\nQue hará a la patria y al mundo.",3,1,0,27,"",0,4,"uo",179,0,-1,0,90,90,"C-34","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0035-01",3,"Y le dice Santos Pérez:\n— \"Yo he de rendir obediencia\nPero si lleva la firma\nDe manos de Vuecelencia.\"",3,1,0,27,"",0,4,"ea",46,0,-1,0,90,90,"C-35","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0036-01",3,"Al escritorio se entraron,\nEstos hombres ya entendidos,\nA trabajar este plan,\nSin que puedan ser sentidos.",3,1,0,27,"",0,4,"io",255,0,-1,0,90,90,"C-36","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0037-01",3,"Y le dice Santos Pérez:\nAl acabar de firmar,\nPreciso en este momento\nUn chasqui para mandar.",3,1,0,27,"",0,4,"a",21,0,-1,0,90,90,"C-37","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0038-01",3,"Y manda al Totoral Grande\nQue vuelvan por El Chiquito,\nQue le llamen a su gente,\nYaques, Juncos y Benito.",3,1,0,27,"",0,4,"io",119,0,-1,0,90,90,"C-38","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0039-01",3,"Yaques, Juncos y Benito,\nEstos eran los bomberos,\nQue marchaban adelante\nSeñalando el derrotero.",3,1,0,27,"",0,4,"eo",-1,0,-1,0,90,90,"C-39","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0040-01",3,"Hacia al sud de \"El Ojo de Agua\"\nAl correo habían topado\nLe preguntaron del coche\nQue a dónde lo había dejado.",3,1,0,27,"",0,4,"ao",14,0,-1,0,90,90,"C-40","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0041-01",3,"Y les responde el correo,\nHablando por sus cabales:\nEn la posta \"El Ojo de Agua\"\nQuedan mudando animales.",3,1,0,27,"",0,4,"ae",26,0,-1,0,90,90,"C-41","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0042-01",3,"Quiroga seguía su viaje\nSin mayor inconveniente,\nFía en el terror de su nombre\nY su orgullo de valiente.",3,1,0,27,"",3,4,"ee",15,0,-1,0,90,90,"C-42","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0043-01",3,"Un poco antes de llegar,\nA la posta \"El Ojo de Agua\"\nUn joven salió del monte,\nPidiendo que se pararan.",3,1,0,27,"",0,4,"aa",-1,0,-1,0,90,90,"C-43","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0044-01",3,"Quiroga asomó primero\nPreguntando: ¿qué se ofrece?\n—\"Señor, quiero hablar a Ortíz,\nSi inconveniente no hubiese\".",3,1,0,27,"",0,4,"ee",65,0,-1,0,90,90,"C-44","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0045-01",3,"Baja Ortíz de adentro el coche\nPara saber lo siguiente:\n\"Deben matarlos a ustedes\n\"Santos Pérez con su gente.",3,1,0,27,"",0,4,"ee",-1,0,-1,0,90,90,"C-45","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0046-01",3,"\"Se hallan en Barranco Yaco\n\"Aguardando a la galera,\n\"Del camino a los dos lados\n\"Se han colocado de espera.",3,1,0,27,"",0,4,"ea",44,0,-1,0,90,90,"C-46","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0047-01",3,"\"Tienen orden de matar\n\"De postillones ariba,\n\"Ninguno debe salvar\n\"Ni los caballos con vida.",3,1,0,27,"",0,4,"ia",-1,0,-1,0,90,90,"C-47","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0048-01",3,"\"Aquí tiene este caballo\n\"Que le traigo para usted,\n\"Con el deseo de salvarlo\n\"A casa lo llevaré.\"",3,1,0,27,"",0,4,"e",-1,0,-1,0,90,90,"C-48","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0049-01",3,"Era un joven Sandivaras\nCon un caballo ensillado\nQue quiere salvar a Ortíz,\nPor un servicio prestado.",3,1,0,27,"",0,4,"ao",14,0,-1,0,90,90,"C-49","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0050-01",3,"Con semejante noticia\nOrtíz se puso a temblar\nY manifestó a Quiroga:\nNo debían de continuar.",3,1,0,27,"",0,4,"a",21,0,-1,0,90,90,"C-50","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0051-01",3,"Entonces dijo Quiroga:\n—No tenga ningún cuidado,\nMañana mismo esos hombres,\nEstarán a mí mandado.",3,1,0,27,"",0,4,"ao",14,0,-1,0,90,90,"C-51","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0053-01",3,"¡Madre mía del Rosario!\nCon su licencia, Señora,\nVoy a referir la muerte\nDe Dn. Facundo Quiroga.",3,1,0,27,"MADRE MÍA DEL ROSARIO",0,4,"oa",-1,0,-1,0,93,93,"C-53","",0,"","","",5,0,0,[],""],["carrizo_salta-nc0053-02",3,"Dispuso ir para Santiago\nA pasiar, a su familia.\nDesde el día que salió\nYa le anunciaba el destino\nQue iba a perder la vida.\nEn ese largo camino.",3,1,0,27,"MADRE MÍA DEL ROSARIO",9,6,"io",199,0,-1,0,94,94,"C-53","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0053-03",3,"Pedro Junque y Roque Junque\nEllos fueron los bomberos\nLe llevaron a la vista,\nLlegaron junto con ellos.\nYa vieron rodar el coche,\nRodaba por el camino\nY Santos Pérez le dijo:",3,1,0,27,"MADRE MÍA DEL ROSARIO",4,7,"io",-1,0,-1,0,94,94,"C-53","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0053-04",3,"—Quiero yo antes de morir\nPocas palabras hablar.\n—¡Por Dios, Santos, te lo pido!\n¿Qué no me libra la vida\nPor la leche que mamó?\nY Santos le contestó:\n—En este Barranco Yaco\nNo conozco que haiga Dios.\nY allí le quita la vida\nA quien la vida quitó.",3,1,0,27,"MADRE MÍA DEL ROSARIO",18,10,"o",-1,0,-1,0,94,94,"C-53","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0053-04-e2",3,"General Quiroga\nCon su correntino\nEn Barranca Yaco,\nAhí fué su destino.",3,1,0,27,"MADRE MÍA DEL ROSARIO",0,4,"io",199,0,-1,0,94,94,"C-53","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0054-01",3,"Le peor gente que tenemos\nSon los collas de Bolivia,\nPues son la mayor polilla\nQue invaden nuestros terrenos.",3,1,0,27,"LA PEOR GENTE QUE TENEMOS",5,4,"eo",-1,0,-1,0,94,94,"C-54","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0054-02",3,"Son muchos los extranjeros\nQue vienen a la Argentina,\nLos collas nos traen la ruina\nDándolas de caballeros,\nY son viles, traicioneros,\nDe borrachos son enfermos\nY flojos ya lo sabemos;\nSon la mayor indecencia,\nEllos son por experiencia\nLa peor gente que tenemos.",3,1,0,27,"LA PEOR GENTE QUE TENEMOS",18,10,"eo",127,0,-1,0,94,94,"C-54","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0054-03",3,"De su país vienen desnudos,\nHambrientos y desgreñados,\nPerseguidos y ultrajados,\nCoqueros y cabelludos.\nAsí se vienen peludos\nA ver si su mal se alivia\nEn esta tierra más tibia\nQue \"La Puna\" en que han vivido,\nComo zorros que han huído\nSon los collas de Bolivia.",3,1,0,27,"LA PEOR GENTE QUE TENEMOS",18,10,"ia",339,0,-1,0,94,94,"C-54","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0054-04",3,"Salta es el pueblo que paga\nCon la maldad de esta gente\nY ella desgraciadamente\nEs la que sufre esta plaga,\nY no hay poder que los haga\nAbandonar la gavilla,\nSe prenden como ladilla\nChupando sangres ajenas,\nSin dejar nada en las venas,\nPues son la mayor polilla.",3,1,0,27,"LA PEOR GENTE QUE TENEMOS",18,10,"ia",162,0,-1,0,95,95,"C-54","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0054-05",3,"Cobardes por excelencia,\nGeneralmente ellos son,\nNo tienen ni corazón\nY mucho menos conciencia.\nDicen que tienen la ciencia\nPara robar los dineros,\nPorque ellos como los vemos\nSon doctores y escribanos,\nSiendo estos los más villanos\nQue invaden nuestros terrenos.",3,1,0,27,"LA PEOR GENTE QUE TENEMOS",18,10,"eo",-1,0,-1,0,95,95,"C-54","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0055-01",3,"No hay vida más regalada\nQue la de los mendocinos,\nPorque viven de contínuo\nEnsayando su tonada.\nEllos jamás hacen nada,\nTodo lo hace la mujer,\nElla tiene que tejer\nY manejar el arado,\nMientras él está ocupado\nEn barajar y beber.",3,1,0,27,"NO HAY VIDA MAS REGALADA",18,10,"e",20,0,-1,0,95,95,"C-55","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0055-02",3,"No les falta de la mano\nLa inseparable guitarra,\nPasan como la chicharra\nCantando todo el verano.\nPor la noche bien temprano\nPreparan el esquinazo\nY aseguran el bolsazo\nQue es su objeto principal\nY se cierran a brindar\nHasta secarse los vasos.",3,1,0,27,"NO HAY VIDA MAS REGALADA",18,10,"ao",-1,0,-1,0,95,95,"C-55","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0055-03",3,"¡Desgraciada la mujer\nQue da con un emigrado!\nNo obstante quererlo al fiado\nLo tiene que mantener\nY darle bien de comer,\nVestirlo con elegancia\nY se da tanta importancia\nQue parece pavo real.\nY haciéndose de rogar\nTodo lo cuenta por gracia.",3,1,0,27,"NO HAY VIDA MAS REGALADA",18,10,"aa",-1,0,-1,0,95,95,"C-55","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0055-04",3,"Desde que pisó esta flota\nEl territorio chileno,\nNi el trigo se ha dado bueno\nCon esta plaga i langosta.\nSi se fueran a la costa\nA aprender a mariscar,\nAllí lo podrían pasar\nPellizcando cualquier cosa,\nDonde no los podrá hallar\nNi el fraile Aldao ni Rozas.",3,1,0,27,"NO HAY VIDA MAS REGALADA",18,10,"oa",-1,0,-1,0,95,95,"C-55","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0055-05",3,"Recibirán, caballeros...\nLa historia de sus paisanos,\nDios los lleve de la mano\nDonde no los pueda ver.\nEllos no respetan ley,\nPatria ni Constitución,\nDesgraciada la nación\nQue los almite gustosa,\nPor eso es que le gaucho Rozas\nLes ha meneado cañón.",3,1,0,27,"NO HAY VIDA MAS REGALADA",18,10,"o",31,0,-1,0,95,95,"C-55","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0055-a-01",3,"No hay vida más regalada\nQue la de los argentinos,\nEllos viven de contínuo\nEnsayando sus tonadas.\nEllos jamás hacen nada,\nTodo lo hace la mujer,\nElla tiene que tejer\nY manejar el arado,\nMientras él vive ocupado\nEn barajar y beber.",3,1,0,27,"NO HAY VIDA MAS REGALADA",18,10,"e",20,0,-1,0,96,96,"C-55-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0055-a-02",3,"No les falta de la mano\nLa inseparable guitarra,\nPasan como la chicharra\nCantando todo el verano;\nPor la noche bien temprano\nPreparan el esquinazo\nY aseguran el bolsazo,\nQue es objeto principal,\nY se cierran en brindar\nHasta secarse los vasos.",3,1,0,27,"NO HAY VIDA MAS REGALADA",18,10,"ao",-1,0,-1,0,96,96,"C-55-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0055-a-03",3,"Desde que pisó esta flota\nEl territorio chileno,\nNi el trigo se ha dado bueno\nCon tal plaga de langosta,\nSi se fueran a la costa\nAprender a mariscar,\nAllí lo podrían pasar\nPellizcando cualquier cosa,\nDonde no los podrá hallar\nAquel fraile Aldao ni Rozas.",3,1,0,27,"NO HAY VIDA MAS REGALADA",18,10,"oa",-1,0,-1,0,96,96,"C-55-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0055-a-04",3,"¡Desgraciada la mujer\nQue da con un emigrado!\nNo obstante quererlo al fiado\nLo tiene que mantener,\nDarle muy bien de comer,\nVestirlo con elegancia,\nY él se da tanta importancia",3,1,0,27,"NO HAY VIDA MAS REGALADA",4,7,"aa",340,0,-1,0,96,96,"C-55-a","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0055-a-06",3,"Recibirán, caballeros,\nLa historia de sus paisanos,\nDios los lleve de la mano\nDonde no los puedan ver.\nEllos no respetan ley,\nPatria ni Constitución,\nSi los admiten gustosos\nDesgraciada es la nación,\nPor esto es que el gaucho Rozas\nLes ha meneado cañón.",3,1,0,27,"NO HAY VIDA MAS REGALADA",18,10,"o",31,0,-1,0,96,96,"C-55-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0056-01",3,"Al santiagueñazo Ibarra,\nDe Rozas gran adulón,\nDiga Ud. que sí, si él dice que no.\nLo van a llevar los diablos\nPara taco de cañón.",3,1,0,27,"AL SANTIAGUEÑAZO IBARRA",7,5,"o",-1,0,-1,0,96,96,"C-56","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0056-02",3,"Una espada al gaucho Rosas\nLe ha llegado del Japón,\nDiga Ud. que sí, si él dice 'que no,\nPara defender con ella\nSu santa federación.",3,1,0,27,"AL SANTIAGUEÑAZO IBARRA",7,5,"o",-1,0,-1,0,96,96,"C-56","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0056-03",3,"Montado en un elefante\nViene \"el fraile renegón,\nDiga Ud. que sí, si él dice que no,\nDió una feroz costalada\nY se le rompió el cordón.",3,1,0,27,"AL SANTIAGUEÑAZO IBARRA",7,5,"o",-1,0,-1,0,96,96,"C-56","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0057-01",3,"En la más florida edad\nMi vida se va cansando,\nY en este abismo de penas\nConozco que voy pagando.",3,1,0,27,"EN LA MAS FLORIDA EDAD",0,4,"ao",33,0,-1,0,96,96,"C-57","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0059-01",3,"¡Oh! madre tan desgraciada,\n¿Para qué habrás dado fruto,\nCausando el mayor disgusto\nA una familia ilustrada?\nSiendo la justicia airada\nEl crimen no se olvidó,\nContra mí se declaró\nUn fallo en el tribunal,\nY a mí me van a juzgar\nSin haber nacido yo.",3,1,0,27,"¡OH! MADRE TAN DESGRACIADA",18,10,"o",2,0,-1,0,97,97,"C-59","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0059-02",3,"¡Ay! mundo, aunque no te he visto\nDebo al presente llorar,\nSin nacer voy a pagar\nCon tan diforme delito\nAnte un tribunal escrito\nDe un gran poderoso Dios,\nDándole un vuelo veloz\nSin llegar a ser profundo,\nMi muerte ha sido en el mundo\nSin haber nacido yo.",3,1,0,27,"¡OH! MADRE TAN DESGRACIADA",18,10,"o",-1,0,-1,0,97,97,"C-59","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0059-03",3,"¡Oh! madre, en tan triste estado\nHoy me despido sin verte,\nHoy me ha privado la muerte\nDe que yo te haya mirado,\nYo soy fruto desgraciado\nDel mundo al que no llegué,\nPero a tan poco alcancé\nEn mi infausta formación\nQue al principiar mi creación\nSin ver la luz acabé.",3,1,0,27,"¡OH! MADRE TAN DESGRACIADA",18,10,"e",77,0,-1,0,97,97,"C-59","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0059-04",3,"Un Dios supremo, el divino,\nOfendido en sus decretos,\nSin ignorar los secretos\nMe ha fijado mi destino\nY ahora muero en mi camino\nCon mi madre en un suplicio,\nCumpliéndose el alto juicio\nDe morir afusilado,\nEstando ella embarazada\nMuero sin haber nacido.",3,1,0,27,"¡OH! MADRE TAN DESGRACIADA",18,10,"io",-1,0,-1,0,97,98,"C-59","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0060-02",3,"Al grito del centinela\nRecorre el Jefe su línea,\nVé su vanguardia perdida\nY casi la tropa entera;\nCon 50 hombres que quedan\nManda un escuadrón formar:\n—Vamos — les dijo; — a pelear\nAl enemigo formado\nPorque nos han traicionado\nEn la orilla, \"el Manantial\".",3,1,0,27,"EL SOL QUE AL MUNDO ILUMINA",18,10,"a",-1,0,-1,0,98,98,"C-60","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0060-03",3,"El sol que al mundo ilumina\nSe estaba para perder;\nConfiamos en un papel\nEn el campo de Arenillas;\nAl cantar las avecillas,\nMarchamos con mucho ardor,\nDe nuestra patria al clamor,\nPor la culpa de un tirano,\nQue vende a un patriota hermano.\nRecordemos con dolor.",3,1,0,27,"",18,10,"o",72,0,-1,0,98,98,"C-60","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0060-04",3,"Llegó la noche y el cielo\nArmado con su poder,\nA sus hijos hacía ver\nQue perecían sin remedio,\nMas, del patriota, el denuedo\nNada llegó a embarazar;\nRayos se veían cruzar\nPor detener al valiente\nQue le iban a dar la muerte\nEn su cuna, Tucumán.",3,1,0,27,"",18,10,"a",-1,0,-1,0,98,98,"C-60","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0060-05",3,"Al amanecer el día,\nCuando las aves trinaban,\nLuto y dolor anunciaban.\n—¿Quién vive? — dijo un espía.\nEra el velo que cubría\nEl alma de un traicionero,\nYa se descubre el guerrero,\nMira su tropa perdida,\n¡Oh, qué terrible traición!\nDe tan pérfidos malvados.",3,1,0,27,"",18,10,"ao",-1,0,-1,0,98,98,"C-60","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0060-06",3,"Cargó la caballería\nY con la espada señala\nAl enemigo, que en alas\nDaba fuego con porfía;\nEntonces, con bizarría,\nMandó a su tropa cargar,\nNo pudieron soportar\nLa bravura del valiente,\nQue con esa poca gente\nA la infantería fué a dar.",3,1,0,27,"",18,10,"a",21,0,-1,0,98,98,"C-60","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0060-07",3,"Con un costado en derrota,\nAvergonzados huyeron,\nMas, los infantes que vieron\nQue nuestra tropa era poca,\nNos tiran a quemarropa.\nNosotros, entreverados,\n¡Sable a las manos, soldados!\nPor no tener munición..\n¡Oh, qué terrible traición!\nDe tan pérfidos malvados.",3,1,0,27,"",18,10,"ao",18,0,-1,0,98,98,"C-60","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0060-08",3,"Salimos del entrevero,\nNos volvimos a formar,\nNueva carga fuimos a dar\nCon más terrible denuedo.\nEra superior el fuego\nPara tan pocas espadas,\nQue ayer fueron respetadas\nY hoy lo serían con razón.\nPor una feroz traición\nNuestra fuerza es derrotada.",3,1,0,27,"",18,10,"aa",-1,0,-1,0,98,99,"C-60","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0060-09",3,"Los cielos fueron testigos\nCuando ya con tierna voz\nTodos decíamos: ¡Adiós!\n¡Adiós, queridos amigos!\nTodos estamos perdidos!\nVamos al Jefe a salvar!\nSu sangre se ha de vengar,\nSu vida es interesante,\nEs un patriota constante\nQue nos vino a libertar.",3,1,0,27,"",18,10,"a",21,0,-1,0,99,99,"C-60","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0060-10",3,"Oficiales y soldados,\nTodos, juntos, reunidos,\nDecíamos afligidos:\n—A Alvarez ya lo han tomado\nY lo tienen desarmado\nEn medio del enemigo.\nNosotros fuimos testigos\nDe tan infame maldad,\nLe mandaron remachar\nPesadas barras de grillos.",3,1,0,27,"",18,10,"io",-1,0,-1,0,99,99,"C-60","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0060-14",3,"Yo muero sin más delito\nQue haber venido a pelear,\nPor buscar la libertad\nDel suelo donde he nacido,\nPero tengan entendido,\nDe que la posteridad\nMi muerte sabrá vengar\nSi hay justicia en lo que digo.\nTu desgraciado marido,\nQue en la tumba te ha de amar.",3,1,0,27,"",18,10,"a",21,0,-1,0,99,99,"C-60","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0061-01",3,"Varios cargos de conciencia.\nAhora vamos pagando\nSin tener apelación,\nSólo Dios sabe hasta cuándo.",3,1,0,27,"VARIOS CARGOS DE CONCIENCIA",0,4,"ao",33,0,-1,0,99,99,"C-61","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0061-03",3,"Antes se pagaba el diezmo\nQue justamente alcanzaba,\nPuntualmente se pagaba\nSin agraviarnos por eso.\nHoy nos recargan un censo\nQue nos va sacrificando\nY anualmente va aumentando\nAunque no haiga capital,\nQue el grito de libertad\nAhora vamos pagando.",3,1,0,27,"VARIOS CARGOS DE CONCIENCIA",18,10,"ao",33,0,-1,0,99,99,"C-61","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0061-04",3,"Antes al General Rozas\nLlamaban tigre sangriento,\nMas no fué tan avariento\nEn ésta ni en otras cosas.\nLa Constitución famosa\nHoy nos trata con rigor,\nY al pobre con más razón,\nQue no entiende la malicia,\nLo despide la justicia\nSin tener apelación.",3,1,0,27,"VARIOS CARGOS DE CONCIENCIA",18,10,"o",31,0,-1,0,100,100,"C-61","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0061-05",3,"Una viuda fué a apelar\nAl señor Gobernador,\nY él dijo: —Tenis razón,\nMas no puedo remediar;\nVolvete luego a pagar,\nQue ya te están aguardando\nY yo estoy necesitando\nRentas para trabajar.\nQue así nos van a robar\nSólo Dios sabe hasta cuándo.",3,1,0,27,"VARIOS CARGOS DE CONCIENCIA",18,10,"ao",33,0,-1,0,100,100,"C-61","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0062-01",3,"Me voy a la guerra,\nVidalita,\nSi vuelvo no sé.\nPues allá me manda,\nVidalita,\nLa voz del deber.",3,1,0,27,"ME VOY A LA GUERRA",9,6,"e",-1,0,-1,0,100,100,"C-62","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0062-02",3,"Mañana a cien leguas,\nVidalita,\nDe ti me verás.\n¡No llores, mi negra!\nVidalita,\nMe voy a luchar.",3,1,0,27,"ME VOY A LA GUERRA",9,6,"a",-1,0,-1,0,100,100,"C-62","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0062-03",3,"Si un plomo maldito,\nVidalita,\nDa en mi corazón.\nMatará mi cuerpo,\nVidalita,\nPero mi alma no.",3,1,0,27,"ME VOY A LA GUERRA",9,6,"o",-1,0,-1,0,100,100,"C-62","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0062-04",3,"Cuando la metralla,\nVidalita,\nSuene y el cañón.\nVos serás escudo,\nVidalita,\nDe mi salvación.",3,1,0,27,"ME VOY A LA GUERRA",9,6,"o",31,0,-1,0,100,100,"C-62","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-01",3,"¡Ay, año sesenta y siete!\nLos pueblos se han desolado,\nMuchas madres han llorado\nDe ver tantos contingentes.",3,1,0,27,"AY ASO SESENTA Y SIETE",5,4,"ee",-1,0,-1,0,100,100,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-02",3,"Ya no se vé compasión\nNi por ser hombre de bien,\nY nos tratan con desdén\nY nos cargan de prisión.\nLa garantía, el honor\nSe ha acabado para siempre,\nAsí el pobre y el pudiente\nEs cosa tan desigual,\nA todos nos ha ido mal.\n¡Ay, año sesenta y siete!",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"ee",-1,0,-1,0,100,101,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-03",3,"En las calles de Salta\nSe oyen los ayes,\nPorque Don Peque Frías\nVendió los Valles.",3,1,0,27,"AY ASO SESENTA Y SIETE",6,4,"ae",341,0,-1,0,101,101,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-09",3,"or la mañana ensillaba\nn caballo colorado,\nue mi jefe había ordenado\nver si se lo domaba",3,1,0,27,"AY ASO SESENTA Y SIETE",11,4,"aa",28,0,-1,0,101,101,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-10",3,"Por Humanao me pasiaba\nHasta casi medio día\nEn seguida me volvía\nA lo Don Bachí el pansaco,\nEchaba al pecho un buen taco,\nDesensillaba y dormía.",3,1,0,27,"AY ASO SESENTA Y SIETE",9,6,"ia",0,0,-1,0,101,101,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-11",3,"Un jefe en un buen platiao\nDe allí para acá venía,\nY sus galones lucía,\nCon un sable medio usao,\nDijeron que era mentao,\nPa defender una plaza,\nY aunque la gente era escasa\nY municiones no había,\nJuró que no dentraría\nVarela como en su casa.",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"aa",123,0,-1,0,101,101,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-13",3,"¡Eh pucha la gente loca!\nCuando lo vieron a Plaza\nComo si fuera saraza\nSe les despintó la boca.\nMascando apenas la coca\nSalieron pa tuitos laos\nY entre esos cerros pelaos\nLos vide de uno por uno\nComo ganado cabruno,\nAmarillar de asustaos.",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"ao",342,0,-1,0,101,101,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-14",3,"Sobre el overo subí,\nAmigo al ver la derrota,\nY aunque con la lanza rota,\nAl enemigo me juí.\nAl chileno Cruz lo ví\nMontao en su pingo bayo\nY con la juerza de un rayo\nHasta su lao me ladié\nY tan lindo lo topé\nQue lo saqué del caballo.",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"ao",102,0,-1,0,101,101,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-15",3,"Entre los pueblos hermanos,\nEl remar entre sus manos\nDe pechos tan desgraciados.\nNos llevan acollarados\nY eso nos causa ternura.\nDe ver tantas amarguras\nLos pueblos se han desolado.",3,1,0,27,"AY ASO SESENTA Y SIETE",4,7,"ao",-1,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-17",3,"Si hubiera visto mi amigo\nAquella chura lanzada,\nTan lindamente acertada,\nEn la mitad del ombligo,\nTan solamente le digo\nSi si el tal Cruz no murió\nFué porque al punto llegó\nEl comandante Aguilar\nCon tanta gente a peliar\nQue hasta por fin lo libró.",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"o",2,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-18",3,"A don ................ le hicimos\nPedir perdón de rodillas,\nLe quitamos las chinchillas,\nQue tenía amontonadas\nY rompimos las espadas\nSobre sus mesmas costillas.",3,1,0,27,"AY ASO SESENTA Y SIETE",9,6,"ia",294,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-19",3,"Ya cerca del otro día\nTocó el jefe retirada,\nY con su gente fogiada,\nApenas se defendía,\nMedio peliaba y huyía,\nCuando al llegar a Humanao\nRecibió un expreso enviao\nPor don Cornelio Ybarbán\nDiciendo que güelva atrás,\nQue el Jefe me había entregao.",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"ao",98,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-20",3,"En esto el gaucho Salcedo,\nComo mi bien compañero,\nMe regaló el parejero\nQue le quitó a Miguel Boedo.\nMe dijo: sólo yo puedo\nLibrarlo de esa polilla\nChupemos una cuartilla\nY cuando estemos mamaos,\nNos iremos resertaos\nPal pago \"La Lagunilla\".",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"ia",162,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-21",3,"Arriesgada era la empresa,\nPero al fin me concerté,\nY mi facón afilé\nPal caso de una sorpresa,\nY una noche, con presteza,\nSalimos Salcedo y yo,\nSin que el guardia que durmió\nCon el jusil en el brazo,\nSintiera nada amigaso,\nHasta que el sol apuntó.",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"o",2,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-22",3,"Cuando punteaba el lucero\nLlegamos a \"La Apacheta\"\nAhí abrimos la maleta\nQue traiba mi compañero,",3,1,0,27,"AY ASO SESENTA Y SIETE",11,4,"eo",38,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-23",3,"Jujuy, Salta y Tucumán\nSon los pueblos que han sufrido,\nTantas viudas sin marido\nQue han perdido el bienestar.\nLa guerra vino a enlutar\nAl hogar más encumbrado,\nNo había derecho sagrado,\nLas vidas no respetaban,\nPor los hijos que marchaban\nMuchas madres han llorado.",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"ao",14,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-24",3,"Con mi mesmito yesquero\nPrendimos una fogata\nSe calentamos las patas\nCharqui y harina cenamos,\nY luego que descansamos,\nCaimos pa lo i Zapata.",3,1,0,27,"AY ASO SESENTA Y SIETE",9,6,"aa",-1,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-25",3,"Ansina anduve amigaso,\nEn esa mesma ocasión,\nLibre de todo patrón\nY más bravo que un torazo,\nExtrañando sólo el lazo,\nDe esa mentada Frontera\nY de la gente aparcera\nQue se juntaba en montón\nA chuparse de un tirón\nLa plata de una carrera.",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"ea",44,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-26",3,"En los campos de Pulares\nTopamos una avanzada,\nPor un mulato mandada,\nLlamado José Pomares,\nLos milicos dos a pares\nMarchaban medio apiñaos\nTemblequiando de asustaos,\nCon sus jusiles rabones,\nChaqueta, kepí y calzones\nDe piel mezclilla rayaos.",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"ao",342,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-27",3,"Un tal Don José Manuel\nMás atrasito venía,\nCon tuita su polecía\nAl galope y en tropel.\nLigero leyó un papel\nQue un milico le alcanzó\nY cuando de leer acabó\nNos dijo: ¡güelvan hermanos\nChicotiemos a dos manos\nQue don Peque nos vendió!",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"o",2,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-28",3,"Comenzaron los barullos,\nEl susto y el alboroto\nY hasta un petisito coto\nQue andaba liao en sus puyos,\nDespués de darle dos grullos\nA cada saldao, se jué,\nY a un sargento pregunté:\n¿De ande sale ese aparcero?\nEs su ecelencia, Ovejero,\nMe contestó, y callesé.",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"e",77,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0063-28-e2",3,"En Cerrillos recalamos\nPoblando las pulperías,\nDonde al tuerto ño Cruz Díaz\nVeinte gauchos lo topamos,\nSalcedo y yo le contamos\nTuitas nuestras aventuras,\nNos hizo cambiar monturas,\nNos preguntó ¿qué les falta?\nY entramos de noche a Salta\nEntre trincheras y a oscuras.",3,1,0,27,"AY ASO SESENTA Y SIETE",18,10,"ua",238,0,-1,0,102,102,"C-63","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0064-02",3,"Temblemos los argentinos,\nPobres gauchos inservibles,\nDe miedo de esos fusiles\nEn manos de esos cochinos,\nQue apuntan con todo tino,\nQue quedaremos ahogados.\nY estando así sofocados\nSe nos vendrán a corneta,\nCalando la bayoneta\nY los cañones cargados.",3,1,0,27,"",18,10,"ao",18,0,-1,0,103,103,"C-64","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0064-03",3,"Muy horrible será aquello,\nMe horrorizo de pensarlo,\nY de sólo imaginarlo\nSe me suspende el resuello,\nY estiro bien largo el cuello\nY elevo al cielo mis votos\nComo lo hacen los devotos,\nCon fe me pongo a implorar\nQue no nos deje matar\nCon metrallas de porotos.",3,1,0,27,"YA SE NOS VIENEN LOS ROTOS",18,10,"oo",343,0,-1,0,103,103,"C-64","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0064-04",3,"a se nos vienen los rotos\non los rifles preparados\nlos cañones cargados\n'on metrallas de porotos.",3,1,0,27,"",11,4,"oo",343,0,-1,0,103,103,"C-64","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0064-06",3,"Oigan sonar los clarines\nY redoblar los tambores,\nYa se ven los resplandores\nDe pulidos espadines,\nAquí al ruido de espolines\nDe nuestros pobres soldados,\nQue aunque a caballo formados\nTiritan tanto sufrir\nDe miedo al verlos venir\nCon los rifles preparados.",3,1,0,27,"",18,10,"ao",18,0,-1,0,103,103,"C-64","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0064-a-01",3,"Ya se nos vienen \"los rotos\"\nCon los rifles preparados\nY los fusiles cargados\nCon metrallas de porotos.",3,1,0,27,"YA SE NOS VIENEN LOS ROTOS",11,4,"oo",343,0,-1,0,103,103,"C-64-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0064-a-02",3,"Oigan sonar los clarines,\nY redoblar los tambores,\nYa se ven los resplandores\nDe pulidos espadines,\nAquí al ruido de espolines\nDe nuestros pobres soldados,\nAunque a caballo formados,\nTiritan tanto sufrir,\nDe miedo al verlos venir\nCon los rifles preparados.",3,1,0,27,"YA SE NOS VIENEN LOS ROTOS",18,10,"ao",18,0,-1,0,103,104,"C-64-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0064-a-04",3,"Temblemos los argentinos,\nPobres gauchos inservibles,\nDelante de esos fusiles\nEn manos de esos cochinos,\nQue apuntan con tanto tino\nQue quedaremos ahogados,\nEstando allí sofocados,\nSe nos vendrán a corneta\nCalando las bayonetas\nY los fusiles cargados.",3,1,0,27,"YA SE NOS VIENEN LOS ROTOS",18,10,"ao",18,0,-1,0,104,104,"C-64-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0064-a-05",3,"¡Oh, qué horrible será aquello!\nQue me horroriza pensarlo\nY de sólo imaginarlo\nSe me suspende el resuello,\nSe me estira largo el cuello,\nY al cielo mando mis votos,\nY como hacen los devotos,\nA Dios me pongo a implorar\nQue no nos deje matar\nCon metrallas de porotos.",3,1,0,27,"YA SE NOS VIENEN LOS ROTOS",18,10,"oo",343,0,-1,0,104,104,"C-64-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0065-01",3,"¡Oiga el rotaje chileno!,\nPalanganas, bulliciosos,\nAsesinos alevosos\nComo el reptil con veneno.",3,1,0,27,"OIGA EL ROTAJE CHILENO",11,4,"eo",76,0,-1,0,104,104,"C-65","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0065-02",3,"Presumen de muy valientes\nPor descender de araucanos\nY han sacado lo villano\nDe esa raza solamente,\nPor eso son insolentes\nY ambiciosos de lo ajeno,\nQueriendo tomar terreno,\nCon su bravura impotente,\nSe van a pelar la frente.\nOiga el rotaje chileno.",3,1,0,27,"OIGA EL ROTAJE CHILENO",18,10,"eo",76,0,-1,0,104,104,"C-65","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0065-03",3,"Nos deben la libertad,\nRotos desagradecidos,\nPero de puros bandidos,\nDesconocen la verdad,\nY hacen la barbaridad\nDe creerse muy valerosos,\nPensando los muy rotosos\nCorrernos con su maldad,\nSiendo sólo, en realidad,\nPalanganas bulliciosos.",3,1,0,27,"OIGA EL ROTAJE CHILENO",18,10,"oo",186,0,-1,0,104,104,"C-65","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0065-04",3,"Para robar son audaces;\nPara bandidos, feroces;\nDegüellan dando de voces\nComo lobos de voraces,\nPara el bien son incapaces\nY para el mal son furiosos.\nSon salvajes espantosos,\nQue nada los satisface,\nTodos ellos son rapaces,\nAsesinos alevosos.",3,1,0,27,"OIGA EL ROTAJE CHILENO",18,10,"oo",186,0,-1,0,104,104,"C-65","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0065-05",3,"Si en un combate por suerte\nLlegan ellos a triunfar,\nSe entusiasman en robar\nPorque es su intento más fuerte.\nLe dan al herido muerte\nCon un placer muy ameno,\nSe entregan con desenfreno\nAl saqueo más indecente,\nPor la espalda son valientes\nComo el reptil con veneno.",3,1,0,27,"OIGA EL ROTAJE CHILENO",18,10,"eo",76,0,-1,0,104,104,"C-65","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0066-01",3,"¡Trece de agosto sin par!,\nA las cinco de la tarde,\nParece que el globo se abre.\nEl mundo se iba a acabar.",3,1,0,27,"TRECE DE AGOSTO SIN PAR",5,4,"a",21,0,-1,0,104,104,"C-66","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0066-02",3,"Brama el océano agitado,\nSangrando espumosas olas,\nHuyen las criaturas todas\nY el cielo se halla irritado,\nCorre el hombre apresurado,",3,1,0,27,"TRECE DE AGOSTO SIN PAR",7,5,"ao",14,0,-1,0,104,104,"C-66","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0066-03",3,"Lleno de angustia y pesar.\nTerremoto, incendio y mar\nContra el pueblo se conjura,\nVengar la ofensa procura,\nTrece de agosto, sin par.",3,1,0,27,"TRECE DE AGOSTO SIN PAR",7,5,"a",21,0,-1,0,105,105,"C-66","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0066-04",3,"Los montes más elevados\nY las rocas más distantes\nSe extremecen por instantes\nY quedan desmoronados.\nCaen pedrones rodados\nY el fuego parece que arde.\n¡Si habrá entonces quien nos guarde\nDe la justicia divina!\n¡Qué confusión nos domina!\nA las cinco de la tarde.",3,1,0,27,"TRECE DE AGOSTO SIN PAR",18,10,"ae",344,0,-1,0,105,105,"C-66","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0066-05",3,"Iquique con Mejillones;\nJunín, Pisagua y Arica,\nNuestras desgracias se explican\nEn todos los corazones,\nSólo escombros a montones\nEl contemplar nos es dable,\nTantas huérfanas sin padre,\nTantos maridos y esposas,\nTriste llorando quejosas\nParece que el mundo se abre.",3,1,0,27,"TRECE DE AGOSTO SIN PAR",18,10,"ae",-1,0,-1,0,105,105,"C-66","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0066-06",3,"Brillando razón ardiente\nEl astro hermoso del día,\nParece se despedía\nCon dolor, de los vivientes.\nSeñales veo evidentes,\nDice: Me voy a ocultar,\nVolveré sólo a alumbrar\nCadáveres insepultos,\nDecretos de Dios ocultos,\nEl mundo se iba a acabar.",3,1,0,27,"TRECE DE AGOSTO SIN PAR",18,10,"a",21,0,-1,0,105,105,"C-66","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0067-01",3,"Anta con terror y espanto\nLlora abatida su suerte,\nAl ver que le dieron muerte\nAl hombre que 'quiso tanto.",3,1,0,27,"ANTA CON TERROR Y ESPANTO",11,4,"ao",30,0,-1,0,105,105,"C-67","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0067-02",3,"Jesús Matorras murió,\nHombre honrado y generoso;\nAldazábal alevoso\nEn dormido lo mató.",3,1,0,27,"ANTA CON TERROR Y ESPANTO",11,4,"o",2,0,-1,0,105,105,"C-67","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0067-03",3,"Y después lo desnudó,\nRobándolo con encanto\nA ese pobre varón santo\nQue fué de Salta en mal hora.\nPor eso se encuentra ahora\nAnta con terror y espanto.",3,1,0,27,"ANTA CON TERROR Y ESPANTO",9,6,"ao",30,0,-1,0,105,105,"C-67","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0067-04",3,"Averrategui hizo el mal\nPor ser bandido famoso,\nPues dió para calabozo\nA la casa parroquial\nY allí fué el crimen fatal.\n¡Oh! ¡Caso terrible y fuerte!\nDormido, al hombre, la muerte,\nLo llevó a la sepultura,\nAnta por causa de un cura\nLlora abatida su suerte.",3,1,0,27,"ANTA CON TERROR Y ESPANTO",18,10,"ee",134,0,-1,0,105,105,"C-67","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0067-05",3,"Un tal Máximo Saravia,\nEl ladrón más acabado,\nQue hasta a su hermana ha arañado\nCon la más bárbara rabia,\nDió aquella sentencia sabia\nDe dejar al preso inerte\nPara hacerse el inocente\nYéndose a un punto apartado,\nDe donde se hubo alejado\nAl ver que le dieron muerte.",3,1,0,27,"ANTA CON TERROR Y ESPANTO",18,10,"ee",-1,0,-1,0,105,105,"C-67","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0067-06",3,"El otro, Pedro Rufino,\nCriminal desvergonzado,\nQue debía estar enjaulado\nEn un presidio argentino,\nHoy anda como el zorrino\nCon su crimen apestando,\nSe anda en la calle paseando\nEsa asquerosa morralla.\nLlora Anta por tal canalla\nAl hombre que quiso tanto.",3,1,0,27,"ANTA CON TERROR Y ESPANTO",18,10,"ao",-1,0,-1,0,105,105,"C-67","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0067-07",3,"En Pocitos se juntaron\nLos cobardes asesinos\nAldazábal y Rufino;\nEnsangrentados llegaron\nCon todo lo que robaron\nAl finao, y muy ligeros\nSe llevaron el apero\nQue de almohada le servía\nY todo cuanto tenía,\nSin dejarle ni el sombrero.",3,1,0,27,"ANTA CON TERROR Y ESPANTO",18,10,"eo",38,0,-1,0,105,105,"C-67","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0068-01",3,"Ya se acabó Ramón Rosa,\nEl héroe de \"Las Cañadas\",\nYa cesaron las gauchadas\nY las muertes horrorosas.",3,1,0,27,"YA SE ACABO RAMÓN ROSA",5,4,"oa",-1,0,-1,0,106,106,"C-68","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0068-02",3,"¿Quién sentirá más por él?\n¿Quién será ese buen cristiano\nQue se le demuestre hermano\nPor un recuerdo tan cruel?\nPerjudicial supo ser\nPor su conducta espantosa,\nY sus manos impiadosas\nQue no cesaban de herir,\nA todos se oía decir:\n¡Ya se acabó Ramón Rosa!",3,1,0,27,"YA SE ACABO RAMÓN ROSA",18,10,"oa",-1,0,-1,0,106,106,"C-68","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0068-03",3,"Su nombre resonará.\nSalta, Tucumán, Santiago\nY hasta San Luis que lo ha amado\nCon más calma vivirá,\nAnta ya respirará\nCon el alma descansada,\nNo tendrá temor de nada.\n¡Ya se fué ese malhechor,\nAl cabo murió el ladrón!\nEl héroe de \"Las Cañadas\".",3,1,0,27,"YA SE ACABO RAMÓN ROSA",18,10,"aa",-1,0,-1,0,106,106,"C-68","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0068-04",3,"A gritos podrán llorar\nA los que les haga falta.\nTambién sentirán en Salta\nPor lo que supo robar,\nEl no ha dejado lugar\nSin que pegue sus salteadas.\nLa justicia coaligada\nDe ladrones en compaña,\nAcabando esta cizaña,\nYa cesarán las gauchadas.",3,1,0,27,"YA SE ACABO RAMÓN ROSA",18,10,"aa",-1,0,-1,0,106,106,"C-68","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0068-05",3,"Antes se veían los caminos\nLlenos de estos malhechores,\nPorque los gobernadores\nApañan al asesino.\nRamón Rosa su destino\nLloró con voz lastimosa,\nPorque su suerte engañosa\nLa despidió a una inclemencia\nPor sus cargos de conciencia\nY sus muertes horrorosas.",3,1,0,27,"YA SE ACABO RAMÓN ROSA",18,10,"oa",-1,0,-1,0,106,106,"C-68","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0069-01",3,"Ya la pagó el criminal,\nFeliz año ochenta y siete,\nEn la villa de \"El Piquete\",\nEl martes de Carnaval.",3,1,0,27,"YA LA PAGO EL CRIMINAL",11,4,"a",1,0,-1,0,106,106,"C-69","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0069-02",3,"Ya murió Pedro Rufino,\nNadie le rece siquiera,\nAlégrense en \"La Frontera\"\nQue se acabó el asesino.\nYa se le cumplió el destino\nA ese malvado infernal.\nYa no saldrá a hacer el mal,\nHoy estará en el infierno,\nNo lo salvará el gobierno.\nYa la pagó el criminal.",3,1,0,27,"YA LA PAGO EL CRIMINAL",18,10,"a",1,0,-1,0,106,106,"C-69","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0069-03",3,"De ochenta y seis tristemente,\nLa gente estaba enlutada\nPor la muerte desgraciada\nDe Matorras el valiente.\nPero al año casualmente\nTodo el pueblo se divierte,\nAl ver que le han dado muerte\nAl miserable bandido\nQue un fin tan cruel ha tenido.\n¡Feliz año ochenta y siete!",3,1,0,27,"YA LA PAGO EL CRIMINAL",18,10,"ee",-1,0,-1,0,106,106,"C-69","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0069-04",3,"Mientras lloraban en masa,\nDe Matorras los parientes,\nLos de aquél con aguardiente\nSe divertían en su casa.\nHoy al contrario les pasa,\nQue en todo el diablo se mete,\nLloran el ochenta y siete\nLa muerte de aquel malvado\nQue murió apuñaleado\nEn la villa de \"El Piquete\".",3,1,0,27,"YA LA PAGO EL CRIMINAL",18,10,"ee",285,0,-1,0,106,106,"C-69","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0069-05",3,"Algunos tendrán coraje\nDe llorar a aquel bribón,\nPorque apañaba al ladrón\nQue robaba terneraje.\nYa se fué ese gran salvaje,\nLe llegó su hora fatal,\nNo volverá ese animal\nA dárselas de gran cosa.\nAcabó su vida odiosa,\nEl martes de Carnaval.",3,1,0,27,"YA LA PAGO EL CRIMINAL",18,10,"a",1,0,-1,0,106,106,"C-69","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0070-01",3,"Atención, señores, pido,\nEste caso es muy profundo.\nVoy a decirles cantando\nLo que somos en el mundo.",3,1,0,28,"ATENCIÓN AÑORES PIDO",0,4,"uo",179,0,-1,0,108,108,"C-70","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0070-02",3,"En este mundo traidor\nTodo nos parece nada,\nSólo sabemos que hay Dios\nCuando estamos en la cama.",3,1,0,28,"ATENCIÓN AÑORES PIDO",0,4,"aa",-1,0,-1,0,108,108,"C-70","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0070-03",3,"Cuando estamos en la cama\nLlorando la poca suerte,\nPor ir a dar cuenta a Dios\nAcompañao de la muerte.",3,1,0,28,"ATENCIÓN AÑORES PIDO",0,4,"ee",134,0,-1,0,108,108,"C-70","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0070-04",3,"El alma le dice al cuerpo:\n—Mira, te voy a dejar,\nEs tiempo que Dios me llama\nA su santo tribunal.",3,1,0,28,"ATENCIÓN AÑORES PIDO",0,4,"a",-1,0,-1,0,108,108,"C-70","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0070-05",3,"El alma le dice al cuerpo:\n—Ya pronto voy a dejarte.\n¡Adiós, compañera, hermana!\n¡Quién pudiera acompañarte!",3,1,0,28,"ATENCIÓN AÑORES PIDO",0,4,"ae",8,0,-1,0,108,108,"C-70","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0070-06",3,"El cuerpo le dice al alma:\n—Rogale a mi padre Dios\nQue nos perdone las culpas\nQue hemos hecho entre los dos.",3,1,0,28,"ATENCIÓN AÑORES PIDO",0,4,"o",87,0,-1,0,108,108,"C-70","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0070-07",3,"Nuestro Señor le decía:\n—¡Qué tarde que habéis venido!\n¿Por qué no te has enmendado\nTodo el tiempo que has vivido?",3,1,0,28,"ATENCIÓN AÑORES PIDO",0,4,"io",101,0,-1,0,108,108,"C-70","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0070-08",3,"De allá salió el maldito\nCon un papel en la mano,\nLeyendo está de corrida\nTodo lo que había pecado.",3,1,0,28,"ATENCIÓN AÑORES PIDO",0,4,"ao",-1,0,-1,0,108,108,"C-70","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0070-09",3,"Pero San Miguel decía:\n—Quítate, perro ladrón.\nEs pedido de mi Madre\nQue esta alma alcance perdón.",3,1,0,28,"ATENCIÓN AÑORES PIDO",0,4,"o",31,0,-1,0,108,108,"C-70","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0070-10",3,"Aquí termina la historia\nDe un caso que sucedió,\nPor respetar el domingo\nEsta alma fué y se salvó.",3,1,0,28,"ATENCIÓN AÑORES PIDO",0,4,"o",2,0,-1,0,108,108,"C-70","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0071-01",3,"¡Ay de mí, que no pensaba\nQue al cabo había de llegar\nEl día en que había de llorar\nTodas mis glorias pasadas!",3,1,0,28,"AY DE MI QUE NO PENSABA",3,4,"aa",-1,0,-1,0,108,108,"C-71","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0071-02",3,"Así decía un condenado\nEn un infierno metido,\nLloraba el tiempo perdido,\nEl no haber aprovechado,\nY de tormentos rodeado,\nArdiendo en tan vivas llamas,\nLo que más le atormentaba\nEl ver su mal sin remedio,\nY decía con llanto tierno:\nAy de mí, que no pensaba.",3,1,0,28,"AY DE MI QUE NO PENSABA",18,10,"aa",28,0,-1,0,108,108,"C-71","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0071-03",3,"Allí maldecía a su padre\nLa enseñanza que le dio,\nY la leche que mamó\nDe los pechos de la madre.\n¡Ay de mí! — decía — qué, tarde,\nHe conocido mi mal.\n¿De qué me sirve el llorar\nAunque conozca mi error,\nSi nunca lo pensé yo\nQue al cabo había de llegar?",3,1,0,28,"AY DE MI QUE NO PENSABA",18,10,"a",21,0,-1,0,108,109,"C-71","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0071-04",3,"Llega el trance de mi muerte.\n¡Qué confusión para mí!\nDonde rodeado me ví\nDe enemigos solamente.\n¡Ay! de mí — decía — qué fuerte\nEs así el bien descuidar,\nY sin poder remediar\nEste mi pecho afligido,\nPero ahora lo veo conmigo\nEl día en que había de llorar.",3,1,0,28,"AY DE MI QUE NO PENSABA",18,10,"a",21,0,-1,0,109,109,"C-71","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0071-05",3,"Quien me vió ayer triunfar\nEn este mundo engañoso,\nMe miraba victorioso\nCon tanta felicidad,\nY sin presumir mi mal\nDe las penas que esperaba\nYo solo las desechaba,\nTan sólo seguía mi humor,\nHoy me sirven de dolor\nTodas mis glorias pasadas.",3,1,0,28,"AY DE MI QUE NO PENSABA",18,10,"aa",-1,0,-1,0,109,109,"C-71","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0072-01",3,"Con licencia del Señor\nY los amos de la casa,\nVamos a cantar los Reyes\nEsta pequeña comparsa.",3,1,0,28,"CON LICENCIA DEL SEÑOR",0,4,"aa",-1,0,-1,0,109,109,"C-72","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0072-03",3,"¡Pastorcillo! ¿Vos has visto\nAlguna estrella alumbrar?\n—Sí, señora, sí he visto\nAntes del gallo cantar.",3,1,0,28,"CON LICENCIA DEL SEÑOR",1,4,"a",21,0,-1,0,109,109,"C-72","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0072-04",3,"En el portal de Belén\nHay estrella, sol y luna,\nLa Virgen y San José\nY el niño que está en la cuna.",3,1,0,28,"CON LICENCIA DEL SEÑOR",0,4,"ua",56,0,-1,0,109,109,"C-72","",0,"fernan_caballero","","",31,0,0,[],""],["carrizo_salta-nc0072-04-e2",3,"La Virgen lava pañales,\nLos extiende en el romero\nY los bambolea el aire\nEn el portal de San Pedro.",3,1,0,28,"CON LICENCIA DEL SEÑOR",0,4,"eo",-1,0,-1,0,109,109,"C-72","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0072-05",3,"En el portal de Belén\nPonen lumbre los pastores\nPara calentar al Niño\nQue ha nacido entre las flores.",3,1,0,28,"CON LICENCIA DEL SEÑOR",0,4,"oe",5,0,-1,0,109,109,"C-72","",0,"","","",31,0,0,[],""],["carrizo_salta-nc0073-01",3,"Cuatro son las tres Marías,\nCinco los cuatro elementos,\nOcho las siete cabrillas,\nOnce los diez mandamientos.",3,1,0,28,"CUATRO SON LAS TRES MARÍAS",0,4,"eo",234,0,-1,0,110,110,"C-73","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0073-02",3,"Entre raras luces bellas\nComo relucente aurora,\nCrió Dios a nuestra Señora\nEn un palacio de estrellas,\nDejó sus gracias en ella,\nDe que nos llena a porfía.\nDe las altas jerarquías,\nEl mejor consuelo vemos,\nCon la Reina de los cielos\nCuatro son las tres Marías.",3,1,0,28,"CUATRO SON LAS TRES MARÍAS",18,10,"ia",214,0,-1,0,110,110,"C-73","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0073-03",3,"Cuando el Salvador murió,\nSan Bernardo predicaba\nQue entre las aguas andaba\nEl espíritu de Dios,\nOyó del cielo esa voz\nCon tan claro y dulce acento",3,1,0,28,"CUATRO SON LAS TRES MARÍAS",9,6,"eo",-1,0,-1,0,110,110,"C-73","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0073-05",3,"Cuando el Redentor nació\nUna estrella reluciente\nA los reyes de \"El Oriente\"\nHasta los portales guió,\nPara nacer eligió\nUna morada sencilla,\nHizo tantas maravillas\nCon tan divina luz bella,\nY con su fúlgida estrella\nOcho las siete cabrillas.",3,1,0,28,"CUATRO SON LAS TRES MARÍAS",18,10,"ia",294,0,-1,0,110,110,"C-73","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0073-06",3,"Pecó Adán con Eva en Asia,\nTentados por la serpiente,\nY en su culpa trasparente\nPerdieron de Dios la gracia.\nCayendo en mortal desgracia\nPor no cumplir el precepto\nQue el Señor les tuvo puesto.\nSe perdieron en su afán,\nCon el precepto de Adán,\nOnce los diez mandamientos.",3,1,0,28,"CUATRO SON LAS TRES MARÍAS",18,10,"eo",-1,0,-1,0,110,110,"C-73","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0074-01",3,"Estando el cuerpo en la cama\nDe esta manera decía:\nLloraré mi alma perdida\nPor ser el último día.",3,1,0,28,"ESTANDO EL CUERPO EN LA CAMA",0,4,"ia",-1,0,-1,0,111,111,"C-74","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0074-02",3,"El alma le dice al cuerpo:\n—Soy de las estrellas parte,\nYa me voy para los cielos\nYa no quiero acompañarte.",3,1,0,28,"ESTANDO EL CUERPO EN LA CAMA",0,4,"ae",8,0,-1,0,111,111,"C-74","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0074-03",3,"Ya se va el alma a los cielos\nToda llena de dolor,\nVa y se le presenta a Cristo,\n—¡Perdóname gran Señor!",3,1,0,28,"ESTANDO EL CUERPO EN LA CAMA",0,4,"o",72,0,-1,0,111,111,"C-74","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0074-04",3,"Y Cristo le dice al alma:\n—Mirá qué tarde has venido,\n¿Cómo no te has enmendado\nTodo el tiempo que has vivido?",3,1,0,28,"ESTANDO EL CUERPO EN LA CAMA",0,4,"io",101,0,-1,0,111,111,"C-74","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0074-05",3,"La Virgen le dice a Cristo:\n—Te hice un pedido, hoy te hago otro,\nHijo, perdónale a esta alma,\nMira que fué mi devoto.",3,1,0,28,"ESTANDO EL CUERPO EN LA CAMA",0,4,"oo",-1,0,-1,0,111,111,"C-74","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0074-06",3,"Y Cristo le dice al alma:\n—Ven a gozar de mis glorias,\nEs pedido de mi madre,\nVen que te perdono ahora.",3,1,0,28,"ESTANDO EL CUERPO EN LA CAMA",0,4,"oa",-1,0,-1,0,111,111,"C-74","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0074-07",3,"El diablo le dice a Cristo:\n—¿Es posible, angel varón,\nQue alma que te ofendió tanto\nHaya alcanzado perdón?",3,1,0,28,"ESTANDO EL CUERPO EN LA CAMA",0,4,"o",31,0,-1,0,111,111,"C-74","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0074-08",3,"Y Cristo le dice al diablo:\n—¡Retira feliz sayón,\nEs pedido de mi madre\nQue esta alma alcance perdón!",3,1,0,28,"ESTANDO EL CUERPO EN LA CAMA",0,4,"o",31,0,-1,0,111,111,"C-74","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0074-09",3,"Y se va el diablo al infierno\nMuy furioso y encendido,\nAl ver que esta alma no lleva,\nQue por suya la ha tenido.",3,1,0,28,"ESTANDO EL CUERPO EN LA CAMA",0,4,"io",101,0,-1,0,111,111,"C-74","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0075-01",3,"Estos dobles de campana\nNo son por el que murió\nSino porque sepa yo\nQue puedo morir mañana.",3,1,0,28,"ESTOS DOBLES DE CAMPANA",11,4,"aa",4,0,-1,0,111,111,"C-75","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0075-02",3,"El morir es muy preciso\nY es muy cierto el purgatorio\nComo el infierno es notorio\nQue para los malos se hizo,\nYo no quiero ser remiso\nDejo mi esperanza vana.\nComo la culpa mundana,\nReconozco que me pierdo,\nDios me manda por recuerdo\nEstos dobles de campana.",3,1,0,28,"ESTOS DOBLES DE CAMPANA",18,10,"aa",4,0,-1,0,111,111,"C-75","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0075-03",3,"Mucho siento el mal logrado,\nDejaré a mi precipicio\nPor tirar la rienda al vicio\nPara ser de Dios premiado,\nYo estoy muerto y sentenciado,\nQue a esta alma Dios me la dió,\nDios con gran amor la crió,\nYo en un rato la ofendí\nLuego este doble es por mí,\nNo son por el que murió.",3,1,0,28,"ESTOS DOBLES DE CAMPANA",18,10,"o",2,0,-1,0,111,111,"C-75","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0076-02",3,"Ya se acaba la lealtad\nLa avaricia y la riqueza,\nLa soberbia y la grandeza,\nLa pompa y la vanidad,\nSe acaba toda maldad\nEl garbo y la compostura,\nNo hay permanente hermosura\nDe cuantas el mundo halaga\nAl fin la muerte lo acaba\nNada de esta vida dura.",3,1,0,28,"NADA DE ESTA \\ DURA",18,10,"ua",17,0,-1,0,112,112,"C-76","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0076-03",3,"Muere el justo, el pecador,\nMuere el grande, muere el chico,\nMuere el pobre, muere el rico,\nEl esclavo y su señor,\nY todo mundano amor,\nGustos, honores, caudales,\nMueren bienes temporales,\nTodos por la misma suerte,\nPorque en llegando la muerte,\nFallecen bienes y males.",3,1,0,28,"NADA DE ESTA \\ DURA",18,10,"ae",26,0,-1,0,112,113,"C-76","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0076-04",3,"Muere el galán más ufano\nLa dama más reluciente,\nMuere el joven más valiente,\nMuere el corazón más sano,\nAbrid los ojos cristianos,\nNo pequéis que esto es locura,\nEsta es clara conjetura\nQue todos han de morir,\nY que nos ha de cubrir\nUna triste sepultura.",3,1,0,28,"NADA DE ESTA \\ DURA",18,10,"ua",17,0,-1,0,113,113,"C-76","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0076-05",3,"Al fin muere el abogado,\nAguaciles y soplones,\nComisarios y ladrones,\nAlcaldes y prebendados,\nMueren solteros, casados,\nPapas, Reyes, Cardenales,\nArzobispos, Generales,\nTodos de morir no yerran,\nY bajo un manto la tierra\nA todos nos cubre iguales.",3,1,0,28,"NADA DE ESTA \\ DURA",18,10,"ae",26,0,-1,0,113,113,"C-76","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0077-01",3,"Piadoso lector y amigo,\nLeyendo estás desengaños,\nTiende la vista a tus años\nY mira cómo has vivido,\nNo sea que estando dormido\nEn el lecho de tu cama,\nDe la noche a la mañana\nPases derecho a lo eterno,\nPorque no sólo el enfermo\nTiene la muerte cercana.",3,1,0,28,"PIADOSO LECTOR Y AMIGO",18,10,"aa",4,0,-1,0,113,113,"C-77","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0077-02",3,"No faltará un accidente\nPara matarnos con pausa,\nO alguna contraria causa,\nPara morir de repente.\n¡Qué casos tan afligentes!\nCuando todo ande turbado,\nMe veré desamparado\nDe toditos mis amigos,\nY tan sólo de enemigos,\nAllí seré circulado.",3,1,0,28,"PIADOSO LECTOR Y AMIGO",18,10,"ao",14,0,-1,0,113,113,"C-77","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0077-03",3,"Me sacarán de mi lecho,\nEn funesta procesión\nY mudando de mansión,\nSerá mi cuerpo deshecho.\n¿Y quién verá con despecho\nLa gravedad de este asunto\nCuando al tocar este punto,\nHasta los Santos temieron,\nCuando obligados se vieron\nA descender al sepulcro?",3,1,0,28,"PIADOSO LECTOR Y AMIGO",18,10,"uo",-1,0,-1,0,113,113,"C-77","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0078-01",3,"Yo no oigo misa, ni rezo\nYo no quiero confesarme,\nYo peco si me confieso,\nY es imposible salvarme.",3,1,0,28,"YO NO OIGO MISA NI REZO",1,4,"ae",35,0,-1,0,113,113,"C-78","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0078-03",3,"Dicen que la confesión\nPara el alma es un remedio,\nPero ha de llevar primero\nLa buena preparación,\nCon dolor y contrición\nHa de ser hecho el examen,\nCon la intención de enmendarse\nY cumplir la penitencia,\nY sin esta diligencia\nYo no quiero confesarme.",3,1,0,28,"YO NO OIGO MISA NI REZO",18,10,"ae",-1,0,-1,0,114,114,"C-78","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0078-04",3,"Muchos sin preparación\nSuelen irse confesando,\nY al mismo tiempo callando\nCulpas en la confesión.\nPara mayor perdición\nMantienen este tropiezo,\nVan cometiendo un exceso,\nProfanan la comunión,\nAsí por esta razón\nYo peco si me confieso.",3,1,0,28,"YO NO OIGO MISA NI REZO",18,10,"eo",48,0,-1,0,114,114,"C-78","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0078-05",3,"Muchos madrugan al alba\nDicen que se van a misa,\nVuelven del camino a prisa,\nDicen: la intención me valga,\nDe este modo no se salva\nPorque a Dios no es agradable\nY el engañarlo no es dable\nPorque bien lo sabe Dios.\nY si otro tanto hago yo,\nEs imposible salvarme.",3,1,0,28,"YO NO OIGO MISA NI REZO",18,10,"ae",-1,0,-1,0,114,114,"C-78","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0079-01",3,"Un lucido regimiento\nEn la Gloria se ha formado.\nDan por arma la oración\nY andan buscando soldado.",3,1,0,28,"UN LUCIDO REGIMIENTO",0,4,"ao",14,0,-1,0,114,114,"C-79","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0079-02",3,"De teniente va San Juan\nAl costado de su armada,\nSan Diego, cabo de escuadra,\nSan Miguel, de capitán,\nCadete San Sebastián,\nSan Andrés, habilitado,\nVa de valiente soldado\nEse lucero Domingo,\nEse regimiento lindo\nEn la Gloria se ha formado.",3,1,0,28,"UN LUCIDO REGIMIENTO",18,10,"ao",14,0,-1,0,114,114,"C-79","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0080-01",3,"Yo digo que no hay infierno\nNi misericordia en Dios,\nTambién digo que no hay cielo\nTan fijo como el reloj.",3,1,0,28,"YO DIGO QUE NO HAY INFIERNO",0,4,"o",-1,0,-1,0,114,114,"C-80","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0080-02",3,"¡Hombre, llora tus pecados,\nMira que no eres eterno,\nAllí como en el infierno\nSe lamenta un condenado,\nUn Jesús es agraviado,\nUn serafín sempiterno,\nY también el Padre Eterno.\nRecuerda si estás dormido\nQue para un arrepentido\nYo digo que no hay infierno.",3,1,0,28,"YO DIGO QUE NO HAY INFIERNO",18,10,"eo",225,0,-1,0,114,114,"C-80","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0080-04",3,"Si vivís en el pecado\nY no te separas de él,\nEn el tormento más cruel,\nAllí serás condenado,\nVivirás desesperado\nEn el tormento mayor,\nY dirás con tierna voz:\nHoy me separo del cielo,\nNi espero tener consuelo\nNi misericordia en Dios.",3,1,0,28,"YO DIGO QUE NO HAY INFIERNO",18,10,"o",87,0,-1,0,115,115,"C-80","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0080-05",3,"Mira al que murió en la cruz,\nEcha la culpa en olvido,\nPorque fuísteis redimido\nCon la sangre de Jesús,\nPedile una eterna luz",3,1,0,28,"YO DIGO QUE NO HAY INFIERNO",7,5,"u",109,0,-1,0,115,115,"C-80","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0081-01",3,"A las seis y medio día\nY al golpe de la oración,\nres sin comparación\nComo el pan de cada día.",3,1,0,29,"A LAS SEIS T MEDIO DÍA",11,4,"ia",-1,0,-1,0,117,117,"C-81","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0081-04",3,"Ya el pintor está parado,\nSe le ha turbado el pincel,\nDice que no puede hacer\nEse tu muslo agraciado,\nMás, mirándote al soslayo,\nTu línea es la perfección,\nTalle, piernas y talón,\nEs un retrato tan bueno.\nComo la estrella de Venus\nEres sin comparación.",3,1,0,29,"A LAS SEIS T MEDIO DÍA",18,10,"o",31,0,-1,0,117,117,"C-81","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0081-05",3,"Más lo mejor está en duda,\nY eso no se encontrará\nAquel que te igualará\nA tu retrato en pintura,\nLa fama de tu hermosura\nEstará en Andalucía,\nEsto te digo, alma mía,\nLo que en tu retrato veo\nQue para mí te deseo\nComo el pan de cada día.",3,1,0,29,"A LAS SEIS T MEDIO DÍA",18,10,"ia",0,0,-1,0,117,117,"C-81","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0082-01",3,"Al silencio de la noche\nY a la luz de vuestra luna,\nAl dirigirme a tu casa\nSentí que me daba la una.",3,1,0,29,"AL SILENCIO DE LA NOCHE",0,4,"ua",56,0,-1,0,117,117,"C-82","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0082-02",3,"Acompañaba mis pasos\nA los golpes de un reloj,\nY al pisar en tus umbrales\nSentí que daban las dos.",3,1,0,29,"AL SILENCIO DE LA NOCHE",0,4,"o",-1,0,-1,0,117,117,"C-82","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0082-03",3,"Recuerda, pues, vida mía,\nSi sabes querer tal vez\nO si no desengañame,\nMira que ya dan las tres.",3,1,0,29,"AL SILENCIO DE LA NOCHE",0,4,"e",218,0,-1,0,117,117,"C-82","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0082-04",3,"En mi pecho apasionado\nTraigo mi bien, tu retrato,\nTe suplico una esperanza,\nMira que ya dan las cuatro.",3,1,0,29,"AL SILENCIO DE LA NOCHE",0,4,"ao",-1,0,-1,0,117,117,"C-82","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0082-05",3,"Por último, vida mía,\nYa se ha callado el reloj,\nAl estar en tus caricias\nEn las cinco se paró.",3,1,0,29,"AL SILENCIO DE LA NOCHE",0,4,"o",-1,0,-1,0,117,117,"C-82","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0082-a-01",3,"En el silencio la noche\nY a los claros de la luna,\nAtienda vidita mía,\nSienta que han dado la una.",3,1,0,29,"EN EL SILENCIO LA NOCHE",0,4,"ua",56,0,-1,0,117,117,"C-82-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0082-a-02",3,"Atienda vidita mía\nA la hora del reloj,\nEn el silencio la noche\nSienta que han dado las dos.",3,1,0,29,"EN EL SILENCIO LA NOCHE",0,4,"o",-1,0,-1,0,117,117,"C-82-a","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0082-a-03",3,"Atienda vidita mía\nY no se duerma otra vez.\nEn el silencio la noche\nSienta que ya dan las tres.",3,1,0,29,"EN EL SILENCIO LA NOCHE",0,4,"e",218,0,-1,0,117,117,"C-82-a","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0083-01",3,"Antes que mude de intento,\nFaltarán al campo flores,\nA los astros resplandores,\nY estrellas al firmamento,\nEl sol mudar á de asiento\nY el mar quedará extinguido,\nY en abismo sumergido\nDejará de arder el fuego.\nPor lo tanto yo te ruego\nQue no me eches en olvido.",3,1,0,29,"ANTES QUE MUDE DE INTENTO",18,10,"io",101,0,-1,0,118,118,"C-83","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0084-01",3,"Atención pido al silencio\nY al silencio la atención,\nCon esta mi poca ciencia\nVoy a darle explicación.",3,1,0,29,"ATENCIÓN PIDO AL SILENCIO",0,4,"o",31,0,-1,0,118,118,"C-84","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0084-02",3,"El primero será ver,\nPrenda que tanto deseo\nDurmiendo en la cama estoy,\nSiempre sueño que te veo.",3,1,0,29,"ATENCIÓN PIDO AL SILENCIO",0,4,"eo",66,0,-1,0,118,118,"C-84","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0084-03",3,"El segundo será oir\nSuspiros del corazón,\nYo no sé por qué, bien mío,\nTe tomé tanta afición.",3,1,0,29,"ATENCIÓN PIDO AL SILENCIO",0,4,"o",31,0,-1,0,118,118,"C-84","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0084-04",3,"El tercero será oler\nRico ramo de alhelí,\nLo que te encargo, bien mío,\nQue no te olvides de mí.",3,1,0,29,"ATENCIÓN PIDO AL SILENCIO",0,4,"i",23,0,-1,0,118,118,"C-84","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0084-05",3,"El cuarto será gustar,\n¿Qué gusto podré tener\nDe ver mi querida prenda\nAjena en otro poder?",3,1,0,29,"ATENCIÓN PIDO AL SILENCIO",0,4,"e",20,0,-1,0,118,118,"C-84","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0084-06",3,"El quinto será palpar,\nVenga mi bien, palparé\nEn esos brazos de flores\nEn ellos me arrojaré.",3,1,0,29,"ATENCIÓN PIDO AL SILENCIO",0,4,"e",77,0,-1,0,118,119,"C-84","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0084-08",3,"Hoy que me alejo por siempre,\nTe dejo como una historia,\nFlores de mi amor ardiente,\nQue dedico a tu memoria.",3,1,0,29,"ATENCIÓN PIDO AL SILENCIO",0,4,"oa",126,0,-1,0,119,119,"C-84","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0084-a-01",3,"Cinco sentidos tenemos,\nTodos los necesitamos,\nY a los cinco los perdemos\nCuando nos enamoramos.",3,1,0,29,"CINCO SENTIDOS TENEMOS",1,4,"ao",116,0,-1,0,119,119,"C-84-a","",0,"","","",7,0,0,[],""],["carrizo_salta-nc0084-a-03",3,"El segundo será oír\nSuspiros del corazón,\nYo no sé de qué manera\nTe tomé tanta afición.",3,1,0,29,"CINCO SENTIDOS TENEMOS",0,4,"o",31,0,-1,0,119,119,"C-84-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0084-a-05",3,"El cuarto será gustar\n¿Qué gusto puedo tener,\nAl ver a mi cara prenda\nEn tan ajeno poder?",3,1,0,29,"CINCO SENTIDOS TENEMOS",0,4,"e",20,0,-1,0,119,119,"C-84-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0084-a-06",3,"El quinto será palpar,\nVení, mi bien, palparé,\nY en esos brazos de flores,\nEn ellos me abrazaré.",3,1,0,29,"CINCO SENTIDOS TENEMOS",0,4,"e",77,0,-1,0,119,119,"C-84-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0085-01",3,"¡Atención, señores, pido!\nPara empezar a cantar,\nPorque quiero preguntar\nSi es que alguno ha conocido\nLa prenda que yo he perdido,\nY no la puedo encontrar.\nEs una niña sin par,\nDe mirada que fascina.\nPara hacerla más divina\nTiene en la cara un lunar.",3,1,0,29,"ATENCIÓN SEÑORES PIDO",18,10,"a",21,0,-1,0,119,119,"C-85","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0085-02",3,"Es una niña trigueña\nCon ojos grandes y bellos,\nDe renegrido cabello\nY de boquita risueña,\nTiene nariz aguileña,\nLindo modo de tratar,\nElegancia al caminar\nY en sus palabras dulzura.\nPara aumentar su lindura\nTiene en la cara un lunar.",3,1,0,29,"ATENCIÓN SEÑORES PIDO",18,10,"a",21,0,-1,0,119,119,"C-85","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0085-03",3,"Lleva una cinta azulina\nPendiente en la cabellera,\nLa batita y la pollera\nEs verde de seda fina.\nSu media de muselina\nY zapatos que al pisar\nLa vereda quiere hablar\nAl saber que son de ella,\nY para hacerla más bella\nTiene en la cara un lunar.",3,1,0,29,"ATENCIÓN SEÑORES PIDO",18,10,"a",21,0,-1,0,119,119,"C-85","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0085-04",3,"En fin, señores, termino,\nTodas las señas les dí\nDe la prenda que perdí,\nPor capricho del destino.\nA solas sigo el camino\nBuscándola sin cesar,\nMás si la llego a encontrar,\nLes juro que de alegría,\nA besos le arrancaría\nDe la cara ese lunar.",3,1,0,29,"ATENCIÓN SEÑORES PIDO",18,10,"a",21,0,-1,0,119,119,"C-85","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0086-01",3,"A tu ventana he llegado\nVengo a turbar tu reposo\nCon el eco quejumbroso\nDe un amante apasionado.\nTemo te halla despertado\nDe ese sueño encantador,\nSiento y no tengo valor\nDe retirarme en seguida,\nPerdona, prenda querida,\nEste triste trovador.",3,1,0,29,"A TU VENTANA HE LLEGADO",18,10,"o",72,0,-1,0,120,120,"C-86","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0086-02",3,"Quizás que en este momento,\nEn tu ventura soñabas\nY mi voz te despertaba,\nDueña de mi pensamiento.\nPerdona el atrevímiento\nDe haber venido a turbar\nEse sueño virginal,\nDonde una dicha futura\nEncierra tanta ventura\nQue se pierde al despertar.",3,1,0,29,"A TU VENTANA HE LLEGADO",18,10,"a",-1,0,-1,0,120,120,"C-86","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0086-03",3,"Los pajarillos al alba,\nAlegres sus nidos dejan\nMientras yo al pié de tu reja\nCanto las penas de mi alma.\nEn estas horas de calma\nDe una noche placentera.\nA tu ventana hechicera\nVengo con voz dolorida\nPara decirte, querida,\nCuánto mi amor te venera.",3,1,0,29,"A TU VENTANA HE LLEGADO",18,10,"ea",44,0,-1,0,120,120,"C-86","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0086-04",3,"Perdonarás, dulce encanto,\nYa que tu sueño turbé,\nPerdona, que todo fué\nDe un pecho herido el quebranto,\nUna gota de mi llanto\nEn tu reja encontrarás,\nY mañana, cuando veas,\nY el sol alumbre tus rejas,\nMirarás que aquí te deja\nMi amor todo su pesar.",3,1,0,29,"A TU VENTANA HE LLEGADO",18,10,"a",-1,0,-1,0,120,120,"C-86","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0086-a-01",3,"A tu ventana he llegado,\nVengo a turbar tu reposo\nCon el eco quejumbroso\nDe un amante apasionado,\nTal vez te habré despertado\nDe este sueño encantador,\nSiento y no tengo valor\nDe retirarme en seguida,\nPerdona, prenda querida,\nA este triste trovador.",3,1,0,29,"A TU VENTANA HE LLEGADO",18,10,"o",72,0,-1,0,120,120,"C-86-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0086-a-02",3,"Quizás que en este momento\nEn tus delicias soñabas,\nY mi voz te despertaba,\nNiña de mi pensamiento,\nPerdona el atrevímiento\nDe haber venido a turbar\nEse sueño virginal,\nDonde la dicha futura\nEncierra tanta ventura\nQue se pierde al despertar.",3,1,0,29,"A TU VENTANA HE LLEGADO",18,10,"a",-1,0,-1,0,120,120,"C-86-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0086-a-03",3,"Los pajarillos al alba\nAlegres sus nidos dejan,\nMientras yo al pié de tu reja\nCanto las penas de mi alma,\nEn esas horas de calma,\nDe la noche placentera,\nA tu ventana hechicera\nVengo con voz dolorida\nPara decirte, querida,\nCuánto mi amor te venera.",3,1,0,29,"A TU VENTANA HE LLEGADO",18,10,"ea",44,0,-1,0,120,120,"C-86-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0087-01",3,"Bien sé que dormida estás,\nPero a recordarte vengo,\nPara que sepas, mi cielo,\nQue tu amor me quita el sueño.",3,1,0,29,"BIEN SE QUE DORMIDA ESTAS",0,4,"eo",-1,0,-1,0,120,120,"C-87","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0087-02",3,"A deshora de la noche\nSalgo con el instrumento,\nPriva del sueño, no duermas,\nOye mis tristes lamentos.",3,1,0,29,"BIEN SE QUE DORMIDA ESTAS",0,4,"eo",-1,0,-1,0,120,121,"C-87","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0087-03",3,"Pon atención a las cuerdas,\nOye mi triste concierto,\nPorque no es dable que duermas,\nAndando por tí despierto.",3,1,0,29,"BIEN SE QUE DORMIDA ESTAS",0,4,"eo",88,0,-1,0,121,121,"C-87","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0087-04",3,"A fe que si tú pagaras\nA mi amorosa pasión,\nNo te hallaras tan dormida\nSino en vela como yo.",3,1,0,29,"BIEN SE QUE DORMIDA ESTAS",0,4,"o",-1,0,-1,0,121,121,"C-87","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0087-05",3,"Pues mi constancia amorosa,\nQue vigilante padezca\nPor tu amor mientras tú duermes\nSin que un alivio merezca.",3,1,0,29,"BIEN SE QUE DORMIDA ESTAS",0,4,"ea",346,0,-1,0,121,121,"C-87","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0087-06",3,"El que te canta soy yo,\nLa que me dicta es el alma,\nEl que te quiere y te estima,\nBien sabes cómo se llama.",3,1,0,29,"BIEN SE QUE DORMIDA ESTAS",0,4,"aa",-1,0,-1,0,121,121,"C-87","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0088-01",3,"Cautivo tuyo, mi bien,\nHe de ser mientras yo viva,\nY todos han de tener\nDe mi cautiverio envidia.",3,1,0,29,"CAUTIVO TUYO MI BIEN",0,4,"ia",-1,0,-1,0,121,121,"C-88","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0088-02",3,"Siendo tu pecho la cárcel\nDe mi prisión venturosa,\nGlorias serán los pesares,\nY mi suerte muy dichosa.",3,1,0,29,"CAUTIVO TUYO MI BIEN",0,4,"oa",63,0,-1,0,121,121,"C-88","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0088-03",3,"Como vuestros brazos sean\nLas cadenas que me oprimen,\nNo habrá mal que me atormente\nNi tormento que me aflija.",3,1,0,29,"CAUTIVO TUYO MI BIEN",5,4,"ia",-1,0,-1,0,121,121,"C-88","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0088-04",3,"Si en lo posible el penar\nSe junta con el vivir,\nHaré la prueba de amarte,\nRubricaré con sufrir.",3,1,0,29,"CAUTIVO TUYO MI BIEN",0,4,"i",157,0,-1,0,121,121,"C-88","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0088-05",3,"Los padecimientos todos\nQue tu cielo me atormentan,\nHaré empeño de buscarlos\nPara que más permanezcan.",3,1,0,29,"CAUTIVO TUYO MI BIEN",0,4,"ea",-1,0,-1,0,121,121,"C-88","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0089-01",3,"Ciego quisiera haber sido,\nMi vida, para no verte,\nPorque de verte me nace\nLa inclinación a quererte.",3,1,0,29,"CIEGO QUISIERA HABER SIDO",0,4,"ee",134,0,-1,0,121,121,"C-89","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0089-02",3,"La inclinación a quererte\nMe tiene fuera de mí,\nYo te adoro sin hablarte\nDesde el día en que te ví.",3,1,0,29,"CIEGO QUISIERA HABER SIDO",0,4,"i",23,0,-1,0,121,121,"C-89","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0089-03",3,"Desde el día en que te ví,\nEn tí puse mi afición\nMostrándote por los suelos\nA mi triste corazón.",3,1,0,29,"CIEGO QUISIERA HABER SIDO",0,4,"o",31,0,-1,0,121,121,"C-89","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0089-04",3,"A mi triste corazón\nNo le pagues mal su amor,\nMirá que se ha de perder\nSi más dura tu rigor.",3,1,0,29,"CIEGO QUISIERA HABER SIDO",0,4,"o",72,0,-1,0,121,121,"C-89","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0089-05",3,"Si más dura tu rigor\nBuscaré por donde verte,\nAblandá ese duro pecho,\nMi bien, dejame quererte.",3,1,0,29,"CIEGO QUISIERA HABER SIDO",0,4,"ee",134,0,-1,0,121,121,"C-89","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0089-a-03",3,"Desde la hora en que te ví\nEn tí puse mi afición,\nPostrándose por los suelos\nEste humilde corazón.",3,1,0,29,"CIEGO QUISIERA HABER SIDO",0,4,"o",31,0,-1,0,122,122,"C-89-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0089-a-04",3,"A este humilde corazón\nNo le pagues mal su amor,\nPorque temo que se pierda\nSi más dura tu rigor.",3,1,0,29,"CIEGO QUISIERA HABER SIDO",0,4,"o",72,0,-1,0,122,122,"C-89-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0089-a-05",3,"Hasta el alma tengo triste\nY abatido el corazón,\nPorque tengo una pasión\nQue a todas horas me asiste.",3,1,0,29,"CIEGO QUISIERA HABER SIDO",11,4,"ie",153,0,-1,0,122,122,"C-89-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0090-01",3,"Como árbol marchito estoy\nCuando no te puedo ver,\nCon el riego de tu vista\nVolveré a reverdecer.",3,1,0,29,"COMO ÁRBOL MARCHITO ESTOY",0,4,"e",20,0,-1,0,122,122,"C-90","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0090-02",3,"Volveré a reverdecer\nSi tú me das un consuelo,\nQue para mí tus palabras\nSon un rocío del cielo.",3,1,0,29,"COMO ÁRBOL MARCHITO ESTOY",0,4,"eo",10,0,-1,0,122,122,"C-90","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0090-03",3,"Son un rocío del cielo\nY las espero muriendo,\nQue no es vida sino muerte\nLa vida que estoy viviendo.",3,1,0,29,"COMO ÁRBOL MARCHITO ESTOY",0,4,"eo",52,0,-1,0,122,122,"C-90","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0091-01",3,"Con el mayor rendimiento\nY la mejor cortesía,\nHaré esta letra presente\nPara saludar a Usía.",3,1,0,29,"COAT EL MAYOR RENDIMIENTO",0,4,"ia",0,0,-1,0,122,122,"C-91","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0091-02",3,"A Usía quiero saludar\nComo hablar a lo postrero,\nPara Vd. rindo primero\nMi afecto que es nacional.\nA su generosidad\nLe ayudaré en sentimiento,\nMuy vigilante y atento.\nY serviré a vuecelencia\nCon cordura y con prudencia,\nCon el mayor rendimiento.",3,1,0,29,"COAT EL MAYOR RENDIMIENTO",18,10,"eo",94,0,-1,0,122,122,"C-91","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0092-01",3,"Con el naipe de tu amor\nMi bien, quisiera jugar,\nHoy me quiero desquitar,\nMe has ganado el corazón.\nJuguemos al truquiflor\nPor ser el juego más fuerte,\nMano a mano quiero verte\nPara ver mi desengaño,\nPor ver si pierdo o te gano,\nQue hoy comienzo a pretenderte.",3,1,0,29,"CON EL NAIPE DE TU AMOR",18,10,"ee",134,0,-1,0,122,122,"C-92","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0092-02",3,"A la biscamabra jugara\nMi vida, si tu quisieras.\nPor bien empleado lo diera\nMi vida, si me ganara,\nDiez puntos te regalara\nAunque acuses las cuarenta,\nEn mi punto no hay ni treinta,\nBien conozco que me ganas,\nComo veo que te afanas\nMe gusta que estés contenta.",3,1,0,29,"CON EL NAIPE DE TU AMOR",18,10,"ea",-1,0,-1,0,122,122,"C-92","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0092-03",3,"A redondillas juguemos,\nEnvídame tu primero\nPara decir que te quiero\nCon toda el alma y la vida,\nTan sólo con relancina\nO con primera me matas\nMás como eres tan ingrata,\nTú para ganarme a mí\nComo yo te gane el sí\nAunque me ganes la plata.",3,1,0,29,"CON EL NAIPE DE TU AMOR",18,10,"aa",74,0,-1,0,122,122,"C-92","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0092-04",3,"Considera que el que pierde\nHa de buscar el desquite,\nEntonces lo verás triste\nHasta encontrar lo que quiere.\nMás, si qué jugar no tiene,\nLo verás desesperar,\nAllí lo verás estar\nLlorando su mala suerte.\nTan sólo por merecerte\nQuiero dejarme ganar.",3,1,0,29,"CON EL NAIPE DE TU AMOR",18,10,"a",21,0,-1,0,123,123,"C-92","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0093-01",3,"¡Consuelo de mi esperanza,\nDeleite de mi placer!\nTu dueño pretendo ser\nBuscando al tiempo bonanza,\nSin que me quepa mudanza,\nA tus pies me he de rendir\nHasta conseguir el sí\nDe tus labios reducidos,\nHoy me hallo sin sentido\nDesde el día en que te ví.",3,1,0,29,"CONSUELO DE MI ESPERANZA",18,10,"i",23,0,-1,0,123,123,"C-93","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0093-02",3,"Desde el día en que te ví,\nDe tu amor quedé prendado,\nY me ha puesto en tal estado\nQue no pienso más que en tí.\n¡Ay, infeliz; ay de mí!\nQue ya de todo recelo,\nY con razón me desvelo\nA causa de tus sonrojos,\nQuieren negarme tus ojos\nLa hermosa luz de tu cielo.",3,1,0,29,"CONSUELO DE MI ESPERANZA",18,10,"eo",10,0,-1,0,123,123,"C-93","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0093-04",3,"Ai bien, no es ponderación\nLo que te voy a decir,\nQue yo deseo vivir\nPara darte el corazón",3,1,0,29,"CONSUELO DE MI ESPERANZA",11,4,"o",31,0,-1,0,123,123,"C-93","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0093-05",3,"Y mostrarte la pasión\nQue yo te tengo, alma mía.\nMi vida vas acabando\nY así me vas aumentando\nMás y más la voluntad,\nYa que sólo tu deidad\nVivo en de veras amando.",3,1,0,29,"CONSUELO DE MI ESPERANZA",4,7,"ao",33,0,-1,0,123,123,"C-93","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0093-a-02",3,"Mi bien, no es ponderación\nSi yo te quiero decir\nQue dejaré de vivir\nPor darte mi corazón.\nEsta amorosa pasión\nLa vida me va costando\nPorque se va acrecentando\nPara tí mi voluntad,\nQue tan sólo tu deidad\nVivo en de veras pensando.",3,1,0,29,"DESDE EL DÍA EN QUE TE VI",18,10,"ao",33,0,-1,0,123,123,"C-93-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0093-a-03",3,"Lo que más me martiriza\nEs, mi bien, el no saber\nSi me has sabido querer.\nEl saberlo me precisa,\nPorque el corazón me avisa\nQue tú me estás engañando.\nY si me estás dilatando\nYa sabes lo que pretendo.\nSi he de vivir padeciendo\nQuiero saber hasta cuándo.",3,1,0,29,"DESDE EL DÍA EN QUE TE VI",18,10,"ao",33,0,-1,0,123,123,"C-93-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0094-01",3,"Cuando el mundo se acabare\nY el sol mude resplandor,\nYo te dejaré de amar\nSi deja de haber amor.",3,1,0,29,"CUANDO EL MUNDO SE ACABARE",0,4,"o",72,0,-1,0,123,123,"C-94","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0094-03",3,"Cuando la ley de Cupido\nSe niegue a mi pecho amante,\nDejaré de ser constante\nComo tengo prometido,\nY si en mí vez un querido\nQue colme el gusto a tu amor\nReinarás preciosa flor,\nY de mí serás querida\nHasta que pierda la vida\nY el sol mude resplandor.",3,1,0,29,"CUANDO EL MUNDO SE ACABARE",18,10,"o",72,0,-1,0,124,124,"C-94","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0094-04",3,"Cuando la furiosa mar\nSe ensoberbezca en su centro,\nCuando el aire turbulento\nEstorbe la luz del sol,\nY con hervoroso ardor\nQuieran las piedras bramar.\nTal vez te pueda olvidar\nCuando se extinga mi vida,\nSólo así, prenda querida,\nYo te dejaré de amar.",3,1,0,29,"CUANDO EL MUNDO SE ACABARE",18,10,"a",21,0,-1,0,124,124,"C-94","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0094-05",3,"Cuando la mar de repente\nSe troque en los altos montes\nY los claros horizontes\nNieguen la luz al viviente;\nY cuando en el fuego ardiente\nMe abrasara con furor,\nConsumiéndome el dolor,\nSólo así no te amaré\nPues sólo te olvidaré\nSi deja de haber amor.",3,1,0,29,"CUANDO EL MUNDO SE ACABARE",18,10,"o",72,0,-1,0,124,124,"C-94","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0095-01",3,"Cuando en el sepulcro esté\nDonde los muertos están,\nDejaré de ser de Vd.\nFalleciendo yo en mi afán.",3,1,0,29,"CUANDO EN EL SEPULCRO ESTE",0,4,"a",147,0,-1,0,124,124,"C-95","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0095-02",3,"Cuando el suelo brote estrellas\nY el cielo se pueda arar,\nCuando del centro del mar\nSalgan rayos y centellas,\nTe he de amar a pesar de ellas,\nAunque perezca mi fé;\nEsta es la razón por qué\nMuerto dejaré de amar.\nAsí te podré olvidar\nCuando en el sepulcro esté.",3,1,0,29,"CUANDO EN EL SEPULCRO ESTE",18,10,"e",77,0,-1,0,124,124,"C-95","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0095-03",3,"Cuando los árboles canten\nY arraiguen los pajaritos\nY las piedras dando gritos\nTodas ellas se levanten,\nY los fierros se quebranten\nCon las aguas de un volcán.\nCuando violento huracán\nDe la vida me privara,\nAsí sólo te olvidara\nDonde los muertos están.",3,1,0,29,"CUANDO EN EL SEPULCRO ESTE",18,10,"a",-1,0,-1,0,124,124,"C-95","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0095-04",3,"Cuando en las aguas se escriba\nY en el papel naden peces,\nCuando de años se hagan meses\nY la muerte se haga vida.\nCuando el aire hablando diga\nQue el mar se muere de sed\nY que puede perecer\nAunque del cielo le llueva.\nCuando todo esto suceda\nDejaré de ser de Vd.",3,1,0,29,"CUANDO EN EL SEPULCRO ESTE",18,10,"",-1,0,-1,0,124,124,"C-95","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0095-05",3,"Cuando una veloz corriente\nRetroceda y se desvíe,\nCuando el fuego nos enfríe\nY la nieve nos caliente,",3,1,0,29,"CUANDO EN EL SEPULCRO ESTE",11,4,"ee",15,0,-1,0,124,124,"C-95","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0095-06",3,"Cuando el sol vuelva a su oriente\nY el mar descubra su plán\nUon otras cosas que van\nCausando más novedad,\nDejaré de ser de Vd.\nFalleciendo yo en mi afán.",3,1,0,29,"CUANDO EN EL SEPULCRO ESTE",9,6,"a",-1,0,-1,0,125,125,"C-95","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0096-01",3,"Cuando oigas decir, mi vida,\nQue mi cuerpo es un cadáver,\nDirás, prenda apetecida,\nSe acabó un amante estable,\nQue nunca me fué variable\nCuando conmigo existió;\nTe pido que digas vos,\nLo siento y lo he de sentir,\nY llorando has de decir:\nQuien me amaba, se acabó.",3,1,0,29,"CUANDO OIGAS DECIR MI VIDA",18,10,"o",-1,0,-1,0,125,125,"C-96","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0096-02",3,"Bien sabes, cielo adorado,\nCuándo debes de llorar,\nCuando me veas colocar\nDentro de un sepulcro helado\nDirás con llanto angustiado:\nSe acabó quien me quería,\nSe acabó quien me decía\nQue no me había de olvidar.\nEntonces podrás llorar,\nRegalada prenda mía.",3,1,0,29,"CUANDO OIGAS DECIR MI VIDA",18,10,"ia",0,0,-1,0,125,125,"C-96","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0096-03",3,"Tú sabes, cielo querido,\nQue faltando mi existencia\nSe acaban correspondencias\nQue en este mundo han habido,\nTambién, mi bien, es sabido,\nQue ni a vos he de llorarte,\nPorque ya no podré amarte\nEn este mundo por cierto,\nPero si mi alma no ha muerto\nNo dejaré de adorarte.",3,1,0,29,"CUANDO OIGAS DECIR MI VIDA",18,10,"ae",8,0,-1,0,125,125,"C-96","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0097-01",3,"Cuando sepa, prenda amada,\nQue la existencia he perdido\nY en el sepulcro ya hundido\nMi inerme cuerpo reposa,\nSabrás que bajé a la fosa\nPensando en quien tanto amé.\nPero si el destino fué\nSufrir esta desventura,\nEn la humilde sepultura\nMi amor te consagraré.",3,1,0,29,"CUANDO SEPAS PRENDA AMADA",18,10,"e",77,0,-1,0,125,125,"C-97","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0097-03",3,"Tu corazón algún día\nHas de sentir palpitar,\nY de abatido pesar\nO de dicha y alegría.\nSerá la memoria mía\nQue en tu pecho ha de vivir\nY nunca podrás destruir\nEse recuerdo sagrado\nQue en tu corazón grabado\nEn tu pecho ha de existir.",3,1,0,29,"CUANDO SEPAS PRENDA AMADA",18,10,"i",157,0,-1,0,125,125,"C-97","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0097-04",3,"Puedes, con seguridad,\nGozar de mi amor en calma,\nPorque yo con toda mi alma\nTe amaré en la eternidad.\nDe mi amor la intensidad\nSentirás a cada instante,\nY si en vida fuí constante,\nJamás morirá mi fé,\nSi en polvo me volveré\nSeré polvo y siempre amante.",3,1,0,29,"CUANDO SEPAS PRENDA AMADA",18,10,"ae",47,0,-1,0,125,125,"C-97","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0098-01",3,"En vano te estoy mirando\nCara a cara y frente a frente,\nY no te puedo decir\nLo que mi corazón siente.",3,1,0,29,"EN VANO TE ESTOY MIRANDO",0,4,"ee",15,0,-1,0,126,126,"C-98","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0098-02",3,"Tú eres la preciosa flor\nQue entre mil se alza triunfante,\nTú eres la flor más fragante.\nMás bella por su color,\nYo, pequeño picaflor\nA tu alrededor volando\nY eternamente anhelando\nHasta tu cáliz llegar,\nY no te puedo alcanzar,\nEn vano te estoy mirando.",3,1,0,29,"EN VANO TE ESTOY MIRANDO",18,10,"ao",33,0,-1,0,126,126,"C-98","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0098-03",3,"Tú eres luz esplendorosa\nQue al que te mira enceguese,\nTu bella sombra parece\nLa estrella más luminosa;\nYo, ligera mariposa,\nQuiero en ella febricente,\nConsumirme de repente,\nPero no ha de ser así,\nAunque me encuentre de tí\nCara a cara y frente a frente.",3,1,0,29,"EN VANO TE ESTOY MIRANDO",18,10,"ee",15,0,-1,0,126,126,"C-98","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0098-04",3,"Tú eres la hermosa sirena\nQue con su canto enamora\nDe sonrisa seductora\nY mirada que enajena;\nTú, mujer de encantos llena,\nNo sabes lo que es sufrir.\nSin poderlo resistir\nLloro perdida la calma,\nPero lo que siente mi alma\nYo no te puedo decir.",3,1,0,29,"EN VANO TE ESTOY MIRANDO",18,10,"i",157,0,-1,0,126,126,"C-98","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0098-05",3,"Tú eres el ángel divino\nQue allá en la imaginación\nHa forjado la ilusión\nQue endulzará mi destino,\nHoy te encuentro en mi camino",3,1,0,29,"EN VANO TE ESTOY MIRANDO",7,5,"io",199,0,-1,0,126,126,"C-98","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0098-06",3,"Y suspiro tristemente\nAl mirar que inútilmente,\nPor tí sufre el alma mía,\nTal vez sepas algún día\nLo que mi corazón siente.",3,1,0,29,"EN VANO TE ESTOY MIRANDO",7,5,"ee",15,0,-1,0,126,126,"C-98","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0098-07",3,"De balde te estoy mirando\nCara a cara y frente a frente,\nY no te puedo decir\nLo que mi corazón siente.",3,1,0,29,"DE BALDE TE ESTOY MIRANDO",0,4,"ee",15,0,-1,0,126,126,"C-98","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0098-08",3,"Eres la preciosa flor\nQue entre mil se alza triunfante,\nPor su aroma más fragante,\nMás bella por su color.\nYo soy triste picaflor\nQue a tu alrededor volando\nVa eternamente anhelando\nHasta tu cáliz llegar.\nMás no te puedo alcanzar,\nDe balde te estoy mirando.",3,1,0,29,"DE BALDE TE ESTOY MIRANDO",18,10,"ao",33,0,-1,0,126,126,"C-98","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0098-09",3,"Eres luz esplendorosa,\nEl que te mira enceguece,\nY ante tí, sombra parece\nLa estrella más luminosa;\nYo, ligera mariposa,\nQuiero en ella febricente\nConsumirme de repente,\nMás no puede ser así,\nAunque me encuentro de tí\nCara a cara, frente a frente.",3,1,0,29,"DE BALDE TE ESTOY MIRANDO",18,10,"ee",15,0,-1,0,126,126,"C-98","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0098-10",3,"Eres la hermosa sirena\nQue con su canto enamora,\nDe sonrisa seductora,\nDe mirada que enajena,\nTú, mujer de encantos llena,\nNo sabes lo que es sufrir\nSin poderlo resistir\nLloro perdida la calma,\nPero lo que siente mi alma\nYo no te puedo decir.",3,1,0,29,"DE BALDE TE ESTOY MIRANDO",18,10,"i",157,0,-1,0,126,126,"C-98","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0099-01",3,"De los jardines de Diana\nCinco flores le traeré,\nAzucena y margarita,\nRosa, jazmín y clavel.",3,1,0,29,"DE LOS JARDINES DE DIANA",0,4,"e",-1,0,-1,0,127,127,"C-99","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0099-02",3,"Le traeré un lindo jilguero\nQue cante por las mañanas\nPara su divertimiento,\nDe los jardines de Diana.",3,1,0,29,"DE LOS JARDINES DE DIANA",0,4,"aa",-1,0,-1,0,127,127,"C-99","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0099-03",3,"También le traeré una jarra\nSi acaso la necesita,\nPara que tenga en su casa\nAzucena y margarita.",3,1,0,29,"DE LOS JARDINES DE DIANA",0,4,"ia",50,0,-1,0,127,127,"C-99","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0100-01",3,"De San Agustín la pluma,\nDe Carlos V el poder,\nDe un rey David la fortuna,\nDe un Salomón el saber.",3,1,0,29,"DE SAN AGUSTÍN LA PLUMA",0,4,"e",20,0,-1,0,127,127,"C-100","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0100-02",3,"Quisiera con dulce anhelo\nTener un sonoro canto\nPara poderle cantar,\nEn el día de su santo.\nPara su mayor encanto\nCantaré sus días, en suma.\nPara que no se apersuma,\nLe venimos a cantar,\nAl mismo tiempo a dejar\nDe San Agustín la pluma.",3,1,0,29,"DE SAN AGUSTÍN LA PLUMA",18,10,"ua",347,0,-1,0,127,127,"C-100","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0100-03",3,"Arpas, trompas y violines\nTraer quisiera a su casa,\nAunque de fortuna escasa\nCantarían los querubines\nAngeles y serafines.\nA todos quisiera ver\nCumpliráse su placer,\nSi lo diera por hazaña,\nY la corona de España\nDe Carlos V el poder.",3,1,0,29,"DE SAN AGUSTÍN LA PLUMA",18,10,"e",20,0,-1,0,127,127,"C-100","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0101-01",3,"Desde que te ví te quise,\nY desde entonces te amé,\nMi corazón sobre el tuyo\nComo flor lo deshojé.",3,1,0,29,"DESDE QUE TE VI TE QUISE",0,4,"e",77,0,-1,0,128,128,"C-101","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0101-02",3,"En fin, mi vida es tan triste,\nQue sin tí no puedo estar,\nTan solamente en llorar\nPaso las horas del día,\n¡Ven en mi ayuda, alma mís!\nYa que tan firme te amé,\nYa que mi amor te entregué\nY que por amarte tanto.\nMi corazón en quebranto\nComo flor lo deshojé.",3,1,0,29,"DESDE QUE TE VI TE QUISE",18,10,"e",77,0,-1,0,128,128,"C-101","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0102-01",3,"Desde que te ví Covís,\nAl punto te empecé a amar,\nY el Cristo de mis ansias\nTe lo voy a cantar.",3,1,0,29,"DESDE QUE TE VI COVIS",0,4,"a",21,0,-1,0,128,128,"C-102","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0102-07",3,"Después que aprendí el Cristo\nMe puse a deletrear,\nY a mi amada la divierto\nCantándole el b, á.",3,1,0,29,"DESDE QUE TE VI COVIS",0,4,"a",-1,0,-1,0,128,128,"C-102","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0102-08",3,"B,a vení para acá.\nB,e yo me acercaré,\nB,i si me quieres dí,\nB,o no me digas que no,\nB,u de mi afecto eres tú,\nBa, be, bi, bo, bu,\nDe mi afecto eres tú.",3,1,0,29,"DESDE QUE TE VI COVIS",4,7,"u",73,0,-1,0,128,128,"C-102","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0103-01",3,"El lunes amaneció\nPara mí brillante el día,\nMe encontré con el lucero\nQue andaba en ausencias mía,",3,1,0,29,"EL LUNES AMANECIÓ",0,4,"ia",0,0,-1,0,128,128,"C-103","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0103-02",3,"Que andaba en ausencias mía,\nPor ser el caso forzoso\n¿Dónde está que no me alumbra\nEl lucero de tus ojos?",3,1,0,29,"EL LUNES AMANECIÓ",0,4,"oo",-1,0,-1,0,128,128,"C-103","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0103-03",3,"El lucero de tus ojos\nHoy me tiene de esta suerte,\nHe de pagar con la vida\nSi no llego a merecerte.",3,1,0,29,"EL LUNES AMANECIÓ",0,4,"ee",134,0,-1,0,128,128,"C-103","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0103-04",3,"Si merecerte pudiera,\nNo hallara donde ponerte\nEn mis brazos te pusiera,\nDicha fuera merecerte.",3,1,0,29,"EL LUNES AMANECIÓ",1,4,"ee",134,0,-1,0,128,128,"C-103","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0104-01",3,"El lunes por un instante,\nEl hablar con tí quería,\nPara decirte mis penas\nPor quién lloro noche y día.",3,1,0,29,"EL LUNES POR UN INSTANTE",0,4,"ia",0,0,-1,0,128,128,"C-104","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0104-02",3,"El martes también diré,\nPor ser día desgraciado,\nPorque mi amor se ausentó\nPor un tiempo dilatado.",3,1,0,29,"EL LUNES POR UN INSTANTE",0,4,"ao",14,0,-1,0,129,129,"C-104","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0104-03",3,"Miércoles, para otras tierras,\nVide correr una nube;\nQué gusto pude tener\nCuando consuelo no tuve.",3,1,0,29,"EL LUNES POR UN INSTANTE",0,4,"ue",348,0,-1,0,129,129,"C-104","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0104-04",3,"El jueves recién sentí,\nY le lloraba a la ausencia,\nQué gusto podía tener\nSin hallarme en su presencia.",3,1,0,29,"EL LUNES POR UN INSTANTE",0,4,"ea",46,0,-1,0,129,129,"C-104","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0104-05",3,"El viernes amanecí\nQue parecía un encanto,\nSi no fueras tan ingrata,\nNo me hicieras sufrir tanto.",3,1,0,29,"EL LUNES POR UN INSTANTE",0,4,"ao",30,0,-1,0,129,129,"C-104","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0104-06",3,"El sábado reducí\nToda mi pena y mi gloria,\nLos trabajos que me distes\nLos borré de mi memoria.",3,1,0,29,"EL LUNES POR UN INSTANTE",0,4,"oa",126,0,-1,0,129,129,"C-104","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0104-07",3,"El domingo amanecí\nQue era todo una hermosura,\nTeniendo mi dicha cerca\nY mi prendita segura.",3,1,0,29,"EL LUNES POR UN INSTANTE",0,4,"ua",17,0,-1,0,129,129,"C-104","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0105-01",3,"En el jardín más ameno,\nDe mirarte tan bonita,\nYo te elegí para dueña\nDe mi pecho, margarita.",3,1,0,29,"EN EL JARDÍN MAS AMENO",0,4,"ia",50,0,-1,0,129,129,"C-105","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0105-02",3,"Fué tan grande mi pasión,\nSin declarar mi sentir,\nQue me puse a discurrir\nCómo lograr la ocasión\nDe tener introducción,\nEn tu cielo siendo ajeno,\nPero al fin hallé lo bueno\nCuando menos lo esperaba.\nDecirte lo que pensaba\nEn el jardín más ameno.",3,1,0,29,"EN EL JARDÍN MAS AMENO",18,10,"eo",76,0,-1,0,129,129,"C-105","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0105-03",3,"Entre las flores buscaba\nSi hallaba otra más hermosa\nY sólo vi que la rosa\nEn un punto te ganaba,\nEl color no desmayaba,\nMás luego el sol la marchita,\nLo que a tí jamás te quita\nY te llevas la victoria.\nEl quererte sea mi gloria\nDe mirarte, margarita.",3,1,0,29,"EN EL JARDÍN MAS AMENO",18,10,"ia",50,0,-1,0,129,129,"C-105","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0105-04",3,"Hice un ramo de claveles,\nDe azucenas y jazmines,\nDe violetas y espolines,\nAmapolas y laureles,\nRetamas y lirios crueles,\nTacones, azahar del bueno,\nY quedó el ramo tan pleno,\nNo se podía mejorar,\nEn señas de voluntad\nYo te elegí para dueña.",3,1,0,29,"EN EL JARDÍN MAS AMENO",18,10,"ea",-1,0,-1,0,129,129,"C-105","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0105-05",3,"El jardinero de amor\nQue cultiva con empeño\nCuando viene a ser el dueño\nDe su trabajo y sudor,\nSiempre alcanza alguna flor\nQue el tiempo no la marchita,\nMuestra el fruto a su vidita.\nY también con arrogancia\nQuiero mostrar la constancia\nDe mi pecho, margarita.",3,1,0,29,"EN EL JARDÍN MAS AMENO",18,10,"ia",50,0,-1,0,129,129,"C-105","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0106-01",3,"En el palacio más bello\nEres lucero brillante\nY clavel apetecido\nDel jardín más elegante.",3,1,0,29,"EN EL PALACIO MAS BELLO",0,4,"ae",47,0,-1,0,129,129,"C-106","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0106-02",3,"Eres de luna el reflejo,\nEres bello sol del cielo,\nDe mi tristeza consuelo,\nDe la noche oscura, espejo\nResplandeciente de lejos,\nHilo de oro tus cabellos,\nQue yo me muero por ellos\nAunque por necio me acusen,\nSon señales que dan luces\nEn el palacio más bello.",3,1,0,29,"EN EL PALACIO MAS BELLO",18,10,"eo",-1,0,-1,0,129,129,"C-106","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0106-03",3,"Vivo tan apasionado\nDe su hermosura, señora,\nQue es tan linda como aurora,\nMás bella que el sol dorado;\nNo sé si vivo engañado\nCon tu risueño semblante,\nTus ojos son dos diamantes\nY mi pasión te asegura\nQue para la noche oscura\nEres lucero brillante.",3,1,0,29,"EN EL PALACIO MAS BELLO",18,10,"ae",-1,0,-1,0,130,130,"C-106","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0106-04",3,"La amo con una pasión\nY con tal amor la adoro,\nQue le diera todo el oro\nCon todo mi corazón;\nSi oro tuviera en montón,\nTodo suyo hubiera sido,\nMás, soy un pobre abatido,\nNo tengo fama ni honores,\nVd. es lirio entre las flores\nY clavel apetecido.",3,1,0,29,"EN EL PALACIO MAS BELLO",18,10,"io",101,0,-1,0,130,130,"C-106","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0106-05",3,"Al fin, perla guarnecida\nDe mil rubíes y esmeraldas,\nQue el sol mismo no la iguala\nSu belleza esclarecida.\nEs suya toda mi vida,\nQuiero halagarla bastante,\nYo quiero que se levante\nComo la más alta estrella,\nVd. es la rosa más bella\nDel jardín más elegante.",3,1,0,29,"EN EL PALACIO MAS BELLO",18,10,"ae",47,0,-1,0,130,130,"C-106","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0107-01",3,"En el retiro andi estado,\nHoy por ser constante vuelvo,\nVengo a hacerle un gran recuerdo,\nAunque de mí se ha olvidado.",3,1,0,29,"EN EL RETIRO ANDI ESTADO",5,4,"ao",14,0,-1,0,130,130,"C-107","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0107-02",3,"Aunque la mala fortuna\nMe haiga batido en el día,\nPero la constancia mía\nEs mejor que una escritura,\nSabrás que vuestra hermosura\nHoy me tiene dislocado,\nAún cuando se haigan trocado\nPor otras recesas glorias,\nDe mí no habrá hecho memoria\nEn el retiro andi estado.",3,1,0,29,"EN EL RETIRO ANDI ESTADO",18,10,"ao",14,0,-1,0,130,130,"C-107","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0108-01",3,"En esta mi sencillez\nEres mi prenda adorada\nTe pregunto si podré\nGozar de ti, bella amada.",3,1,0,29,"EN ESTA MI SENCILLEZ",0,4,"aa",49,0,-1,0,130,130,"C-108","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0108-03",3,"Si de tí llego a gozar,\nMe portaré muy decente,\nY así delante de gente\nNo te sabré conversar;\nAsí te sabré tratar\nComo niña delicada,\nComo señorita honrada\nTe solicitaré así\nPara no dar a decir\nEres mi prenda adorada.",3,1,0,29,"EN ESTA MI SENCILLEZ",18,10,"aa",49,0,-1,0,130,130,"C-108","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0108-04",3,"El no de tí no quisiera,\nPorque si llega este caso,\nHa de ser como un balazo\nQue en mi pecho recibiera,\nY no permitas que muera.\nSi tú me niegas la entrada,\nA mi voluntad probada,\nQuisiera que tú la vieras,\nQue sólo así consiguiera\nGozar de tí, bella amada.",3,1,0,29,"EN ESTA MI SENCILLEZ",18,10,"aa",49,0,-1,0,130,130,"C-108","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0109-04",3,"Hago esta letra al morir,\nPara que de mí se acuerden\nLos que amorosos pretenden\nPor una deidad gemir,\nVoy a dejar de existir\nY también voy a dejar\nDe mi muerte un ejemplar,\nPara que conozca el mundo\nQue no hay dolor más profundo\nQue un mal pago a tanto amar.",3,1,0,29,"ENFERMO DE UNA PASIÓN",18,10,"a",21,0,-1,0,131,131,"C-109","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0110-01",3,"Enfermo estoy, no sé cómo,\nNacido de un no sé qué,\nSanaré yo bien sé cuando,\nSi me cura quien yo sé.",3,1,0,29,"ENFERMO ESTOY NO SE COMO",0,4,"e",77,0,-1,0,131,131,"C-110","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0110-02",3,"Tan amargamente lloro\nY me pongo a contemplar\nSi podré algún día llegar\nAl consuelo que yo adoro.\nTanta es la piedad que imploro,\nTanto el veneno que tomo,\nQue siento en el alma un plomo\nSin saber mi mal cuál es,\nAsí de esta suerte, pues,\nEnfermo estoy, no sé cómo.",3,1,0,29,"ENFERMO ESTOY NO SE COMO",18,10,"oo",349,0,-1,0,131,131,"C-110","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0110-03",3,"Yo jamás podré decir\nQuién me causó este quebranto,\nPero veo que peno tanto\nEn este triste existir,\nQue más bien quiero morir,\nPorque así descansaré,\nSolamente sanaré\nDe este mal que estoy sufriendo,\nQue va cada vez corriendo\nNacido de un no sé qué.",3,1,0,29,"ENFERMO ESTOY NO SE COMO",18,10,"e",77,0,-1,0,131,131,"C-110","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0110-04",3,"Yo bien puedo asegurar,\nDoliéndome de tal modo,\nQue no sanaré del todo\nSi no me viene a curar,\nLa que sin ningún pesar",3,1,0,29,"ENFERMO ESTOY NO SE COMO",7,5,"a",21,0,-1,0,131,131,"C-110","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0110-05",3,"Me tiene en rigor penando,\nY cada vez aumentando\nEl daño que me ha causado,\nY exclamo desconsolado:\nSanaré yo bien sé cuando,",3,1,0,29,"ENFERMO ESTOY NO SE COMO",7,5,"ao",-1,0,-1,0,132,132,"C-110","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0110-06",3,"Mi pecho desesperado\nA cada instante me dice:\nQue este pesar que me aflije\nSerá en algún día curado,\nNo por médico afamado\nNi por milagro de fé,\nYa padeciendo estaré\nHasta que de mí se duela\nDe este mal que me desvela\nSi me cura quien yo sé.",3,1,0,29,"ENFERMO ESTOY NO SE COMO",18,10,"e",77,0,-1,0,132,132,"C-110","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0111-01",3,"En pensar cómo gozarte\nEstoy tan fuera de mí\nQue no sé si vivo o muero\nDesde el día en que te ví.",3,1,0,29,"EN PENSAR COMO GOZARTE",0,4,"i",23,0,-1,0,132,132,"C-111","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0111-02",3,"Con el alma puesta en calma\nVine, mi bien, por amarte,\nY sin alivio a mi llanto\nEn pensar cómo gozarte.",3,1,0,29,"EN PENSAR COMO GOZARTE",0,4,"ae",8,0,-1,0,132,132,"C-111","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0111-03",3,"Si mi corazón no ignora\nQue para amarte nací,\nYo no sé por qué motivo\nEstoy tan fuera de mí.",3,1,0,29,"EN PENSAR COMO GOZARTE",0,4,"i",23,0,-1,0,132,132,"C-111","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0111-04",3,"En contemplar si tu cielo\nConoce lo que yo quiero,\nEs tanta mi confusión\nQue no sé si vivo o muero.",3,1,0,29,"EN PENSAR COMO GOZARTE",0,4,"eo",38,0,-1,0,132,132,"C-111","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0111-05",3,"Porque mis dichosos ojos\nFueron con los que te ví,\nTe quiero más que a mis ojos\nDesde el día en que te ví.",3,1,0,29,"EN PENSAR COMO GOZARTE",1,4,"i",-1,0,-1,0,132,132,"C-111","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0112-01",3,"Es tan grande mi pasión\nY tanta mi voluntad,\nQue no te puedo avisar\nPorque no hallo la ocasión;\nTestigo es mi corazón,\nPorque me ayuda a llorar,\nBien puedes considerar\nSi sabes lo que es querer.\nTeniéndote en mi poder\nSólo en tí había de pensar.",3,1,0,29,"ES TAN GRANDE MI PASIÓN",18,10,"a",21,0,-1,0,132,132,"C-112","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0112-02",3,"Por tu amor vivo llorando,\nNingún consuelo hallo en mí,\nEn despierto pienso en tí,\nSi duermo te estoy soñando,\nAsí me voy acabando\nY se acrecienta mi llanto,\nEres tú sola mi encanto,\nY por tí no hallo consuelo,\nNo pasaría ni un desvelo\nSi no te quisiera tanto.",3,1,0,29,"ES TAN GRANDE MI PASIÓN",18,10,"ao",30,0,-1,0,132,132,"C-112","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0112-03",3,"Tú eres mi prenda querida,\nEn quién pongo todo anhelo,\nPorque,es gozar de tu cielo\nMi ambición apetecida,\nAunque perdiera la vida.\nPara mí todo es pensar,\nEn sólo considerar\nLo que me dice Cupido,\nLa pasión que te he tenido\nLa vida me va a costar.",3,1,0,29,"ES TAN GRANDE MI PASIÓN",18,10,"a",21,0,-1,0,132,132,"C-112","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0112-04",3,"Todo mi fin es amarte,\nAunque es tan poca mi suerte,\nHasta me deseo la muerte\nSin poder mi amor gozarte,\nSi yo pudiera olvidarte,\nFuera mi grande consuelo,\nY cuando de tí me acuerdo,\nAhoga mi pecho un suspiro,\nY me cuesta un gran delirio\nEsta pasión que no pierdo.,",3,1,0,29,"ES TAN GRANDE MI PASIÓN",18,10,"eo",350,0,-1,0,132,132,"C-112","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0113-01",3,"Hace tiempo que quería\nPedirte un beso, mi ñata,\nPero nunca me atrevía\nPorque el valor me hacía falta.",3,1,0,29,"HACE TIEMPO QUE QUERÍA",0,4,"aa",-1,0,-1,0,132,132,"C-113","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0113-04",3,"Si es cierto que soy tu dueño,\nVení a mi lado, ñañita,\nQue es lo único que te pido,\nUn beso de tu boquita.",3,1,0,29,"HACE TIEMPO QUE QUERÍA",0,4,"ia",50,0,-1,0,133,133,"C-113","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0114-01",3,"Hacia tí, humildemente,\nSe dirige un corazón,\nQue espera con impaciencia\nRecompenses su pasión.",3,1,0,29,"HACIA TI HUMILDEMENTE",0,4,"o",31,0,-1,0,133,133,"C-114","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0115-03",3,"Un amargo sentimiento\nMantengo en el corazón,\nCon una suma aflicción\nVivo en tanto desacierto,\nEspero que en corto tiempo\nYa cese mi padecer\nO que reine mi placer\nDe esta pasión tan cegada,\nQue no quedará en la nada\nO he de morir o vencer.",3,1,0,29,"HE DE SEGUIR MI PORFÍA",18,10,"e",20,0,-1,0,133,133,"C-115","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0115-04",3,"Pocas hay en mi favor\nY muchas hay en mi contra,\nPero eso nada me importa\nSi tú me tienes amor\nY no me uses de traición\nComo suele suceder,\nNi mudes de parecer,\nDuélate mi alma abatida\nPorque he de perder la vida\nO en tus brazos me he de ver.",3,1,0,29,"HE DE SEGUIR MI PORFÍA",18,10,"e",20,0,-1,0,133,133,"C-115","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0115-05",3,"Dueña mía, ten paciencia,\nYa sabes que por ti muero,\nAsí conforme te quiero\nTe pido la resistencia.\nYa está escrita la sentencia\nPara un no lejano día\nEn que tendré una alegría,\nDespués que tanto he penado,\nMe voy a verme a tu lado\nHaciéndote prenda mía.",3,1,0,29,"HE DE SEGUIR MI PORFÍA",18,10,"ia",0,0,-1,0,133,133,"C-115","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0116-01",3,"Herido de vuestro amor\nAndo mi bien, padeciendo\nComo ciega mariposa\nEn vivas llamas ardiendo.",3,1,0,29,"HERIDO DE VUESTRO AMOR",0,4,"eo",52,0,-1,0,133,133,"C-116","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0116-02",3,"Ten compasión de mis penas,\nDuélete de mi dolor,\nCurame, pues que me ves\nHerido de vuestro amor.",3,1,0,29,"HERIDO DE VUESTRO AMOR",0,4,"o",72,0,-1,0,133,134,"C-116","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0116-03",3,"Mis ojos tienen la culpa,\nPues te vieron tan hermosa,\nPor cuya causa padezco\nComo ciega mariposa.",3,1,0,29,"HERIDO DE VUESTRO AMOR",0,4,"oa",63,0,-1,0,134,134,"C-116","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0116-04",3,"A tus fingidos halagos\nSiempre vivo yo creyendo\nComo que estoy y estaré\nEn vivas llamas ardiendo.",3,1,0,29,"HERIDO DE VUESTRO AMOR",0,4,"eo",52,0,-1,0,134,134,"C-116","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0116-05",3,"¿Es posible que permitas\nVayan mis males creciendo,\nSabiendo que por tí sola\nAndo mi bien padeciendo?",3,1,0,29,"HERIDO DE VUESTRO AMOR",0,4,"eo",52,0,-1,0,134,134,"C-116","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0117-01",3,"Humilde y agradecida\nVengo, mi dueña, a tus pies,\nA que me des el alivio\nO me mates de una vez.",3,1,0,29,"HUMILDE Y AGRADECIDO",0,4,"e",150,0,-1,0,134,134,"C-117","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0117-02",3,"Me ha obligado la pasión\nHablarte por un papel,\nPara decirte por él\nQue en tí pongo mi afición,\nHoy se halla mi corazón\nPrisionero por Cupido,\nA vuestras plantas rendido\nTe pido con gran fervor,\nQue no desprecies mi amor\nHumilde y agradecido.",3,1,0,29,"HUMILDE Y AGRADECIDO",18,10,"io",101,0,-1,0,134,134,"C-117","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0117-03",3,"Ya bien puedes conocer\nLo mucho que yo te quiero,\nTan sólo a tí te venero,\nEncanto de mi placer.\n—Dime si me has de querer\nSiquiera por una vez,\nY seré feliz tal vez\nHallando refugio en tí,\nSólo a que me des el sí\nVengo mi dueña a tus pies.",3,1,0,29,"HUMILDE Y AGRADECIDO",18,10,"e",218,0,-1,0,134,134,"C-117","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0117-06",3,"Si entre tus brazos me viera,\nComo la muerte me espera,\nCreédmelo, como te digo\nDescansará un afligido\nDe penas tan lamentables,\nY vengo con tristes ayes\nA que me des el alivio.",3,1,0,29,"HUMILDE Y AGRADECIDO",4,7,"io",-1,0,-1,0,134,134,"C-117","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0117-07",3,"Al fin, deidad primorosa,\nResuelve lo que ha de ser,\nDime si me has de querer,\nMuéstrate siempre piadosa\nDe mi pena dolorosa,\nTe solicito con fe\nY como claro se vé,\nEstoy postrada de veras,\nAguardando a que me quieras\nO me mates de una vez.",3,1,0,29,"HUMILDE Y AGRADECIDO",18,10,"e",-1,0,-1,0,134,134,"C-117","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0118-01",3,"Las voces de mis clamores\nLlegaron a tus umbrales,\nLa fuerza de mi dolor\nMe hace reventar en ayes.",3,1,0,29,"LAS VOCES DE MIS CLAMORES",0,4,"ae",-1,0,-1,0,134,134,"C-118","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0118-02",3,"Deja tu sueño un momento\nY fijando la atención\nOirás mi tierna canción\nCon su melodioso acento.\nCual sellado documento\nQue te presenta mi amor.\nY con empeño mayor\nTe suplico amada prenda\nQue nunca más desatiendas\nLas voces de mi clamor.",3,1,0,29,"LAS VOCES DE MIS CLAMORES",18,10,"o",72,0,-1,0,134,134,"C-118","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0118-03",3,"Si contemplas las distancias\nQue he caminado por verte\nVerás que para quererte\nPongo todo empeño y ansias,\nMi cariño y mi constancia\nVenciendo dificultades.\nNo pienso en acerbos males.\nMi pecho y mi voluntad\nAtraído por tu deidad\nLlegaron a tus umbrales.",3,1,0,29,"LAS VOCES DE MIS CLAMORES",18,10,"ae",26,0,-1,0,134,134,"C-118","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0119-01",3,"Le pusiera una corona,\nLe trajera al sol cautivo,\nLa hiciera dueña del mundo\nY es nada lo que le digo.",3,1,0,29,"LE PUSIERA UNA CORONA",0,4,"io",-1,0,-1,0,135,135,"C-119","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0119-02",3,"La pusiera en un jardín\nComo a reina de las flores\nLa adornara con primores\nComo a bello serafín;\nAl son de dulce clarín\nQue suave música entona\nSubiera a vuestra persona\nAl trono más elevado\nY con superior agrado\nLe pusiera una corona.",3,1,0,29,"LE PUSIERA UNA CORONA",18,10,"oa",7,0,-1,0,135,135,"C-119","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0119-03",3,"Con gusto y con ligereza\nY un afecto singular\nLa pusiera en un altar\nPra adorar su belleza;\nLe traería la luna presa\nY en servirla seré activo.\nPues quiero tener motivo\nPara gozar de su cielo;\nSiquiera para consuelo\nLe trajera al sol cautivo.",3,1,0,29,"LE PUSIERA UNA CORONA",18,10,"io",351,0,-1,0,135,135,"C-119","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0119-04",3,"Con gusto yo recorriera\nDe un polo hasta el otro polo.\nA vuestro mandato sólo\nTodo el orbe le rindiera.\nA todo el mar revolviera\nDe un extremo al más profundo;\nAl bruto más iracundo\nLe enseñara a obedecerte\nY con fuego activo y fuerte\nLa hiciera dueña del mundo.",3,1,0,29,"LE PUSIERA UNA CORONA",18,10,"uo",179,0,-1,0,135,135,"C-119","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0119-05",3,"Por amarla no dejara\nEmpresa dificultosa\nNi dejara oculta cosa\nQue a Ud. no manifestara;\nLa blanca luna eclipsara\nEstando en unión contigo\nY si cualquier enemigo\nUn pelo suyo ofendiera\nEn polvo lo convirtiera\nY es nada lo 'que le digo.",3,1,0,29,"LE PUSIERA UNA CORONA",18,10,"io",106,0,-1,0,135,135,"C-119","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0120-01",3,"Los astros del firmamento\nResplandecen en el cielo\nAlumbrando el mundo entero\nCon su tan grande portento,\nPero pierden su elemento\nEn el día que viene ya.\nY del sol la claridad\nHace desaparecer\nDe estos astros el poder,\nEn toda la inmensidad.",3,1,0,29,"LOS ASTROS DEL FIRMAMENTO",18,10,"a",16,0,-1,0,135,135,"C-120","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0120-02",3,"Sólo mi amor, alma mía,\nNo se extingue en este mundo\nPorque es del alma fecundo\nY del corazón la guía.\nAmor que en la tumba fría\nSiempre vivo encontrarás.\nAunque el destino fugaz\nMi dicha en el mundo tuerza\nTodo perderá su fuerza\nPero mi amor, no, jamás.",3,1,0,29,"LOS ASTROS DEL FIRMAMENTO",18,10,"a",51,0,-1,0,135,135,"C-120","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0120-03",3,"El mismo sol que el poder\nSobre tantos astros tiene\nCuando obscureciendo viene\nVuelve a desaparecer,\nEntonces es de creer\nQue ningún astro es estable\nY en su poder sólo el aire\nTiene fuerza suficiente.\nY sólo él es permanente\nSin que pueda ser mudable.",3,1,0,29,"LOS ASTROS DEL FIRMAMENTO",18,10,"ae",-1,0,-1,0,135,135,"C-120","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0120-04",3,"Por eso, hermosa deidad,\nMi amor sólo es comparable\nCon la firmeza del aire\nQue no se extingue jamás.\nAsí, en mi amor hallarás\nEterna dicha y ventura\nY si mi estrella futura\nViene a cortar mi existencia,\nMi amor cual la dulce esencia\nBajará a la sepultura.",3,1,0,29,"LOS ASTROS DEL FIRMAMENTO",18,10,"ua",17,0,-1,0,135,135,"C-120","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0121-01",3,"Los mayores imposibles\nHacen a mi amor más fino,\nAsí tengo que adorarte\nAunque me arriesgue al peligro.",3,1,0,29,"LOS MAYORES IMPOSIBLES",0,4,"io",-1,0,-1,0,136,136,"C-121","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0121-02",3,"Aunque me arriesgue al peligro\nY me persigan trabajos\nNada importa vida mía\nSi me he de ver en tus brazos.",3,1,0,29,"LOS MAYORES IMPOSIBLES",0,4,"ao",-1,0,-1,0,136,136,"C-121","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0121-03",3,"Yo me he de ver en tus brazos\nAunque el mundo me lo impida.\nY he de ser tu fino amante\nAunque me cueste la vida.",3,1,0,29,"LOS MAYORES IMPOSIBLES",0,4,"ia",37,0,-1,0,136,136,"C-121","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0121-04",3,"Aunque me cueste la vida\nYo no temo al padecer.\nNi hay cosa que me acobarde\nPues siempre te he de querer.",3,1,0,29,"LOS MAYORES IMPOSIBLES",0,4,"e",20,0,-1,0,136,136,"C-121","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0121-05",3,"Yo siempre te he de querer\nNo hallando mudanza en vos\nY si prosigues constante\nPadeceremos los dos.",3,1,0,29,"LOS MAYORES IMPOSIBLES",0,4,"o",87,0,-1,0,136,136,"C-121","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0121-06",3,"Es imposible mi dueña\nQue sin tu deidad resista\nLas penas que me combaten\nAl privarme de tu vista.",3,1,0,29,"LOS MAYORES IMPOSIBLES",0,4,"ia",352,0,-1,0,136,136,"C-121","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0122-01",3,"Matar y favorecer\nLo haces vos en cada instante.\nY es tan variable tu ser\nQue adorándote constante\nNo te acabo de entender.",3,1,0,29,"MATAR Y FAVORECER",7,5,"e",20,0,-1,0,136,136,"C-122","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0122-02",3,"Aunque tu rigor voy viendo\nYo me precipito al fuego.\nPorque como vivo ciego\nYo a mi mismo no me entiendo.",3,1,0,29,"MATAR Y FAVORECER",11,4,"eo",-1,0,-1,0,136,136,"C-122","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0122-03",3,"Ni el rigor me hace temer\nNi busco a mi mal partido.\nTú me has llegado a vencer\nY para haberme rendido\nAlgo debes de tener.",3,1,0,29,"MATAR Y FAVORECER",7,5,"e",20,0,-1,0,136,136,"C-122","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0122-04",3,"Así vivo padeciendo\nEn manos de tu rigor.\nAunque ya me veis muriendo,\nCon gusto muero de amor\nPues siempre te voy queriendo.",3,1,0,29,"MATAR Y FAVORECER",7,5,"eo",52,0,-1,0,136,136,"C-122","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0122-05",3,"La vida he de perder\nEn tan rigurosa calma.\nTú eres dueña de mi ser,\nDe mi vida y aún del alma\nAunque me haces padecer.",3,1,0,29,"MATAR Y FAVORECER",7,5,"e",20,0,-1,0,136,136,"C-122","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0123-01",3,"Mi bien, el amor me obliga\nA decirte mi sentir\nPorque no puedo vivir\nEn tan crecida fatiga.",3,1,0,29,"MI BIEN EL AMOR ME OBLIGA",11,4,"ia",232,0,-1,0,136,136,"C-123","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0123-02",3,"Con el alma te venero\nY con la vista te adoro.\nCuando no te miro lloro\nY por quererte me muero.\nDe vuestra hermosura espero\nDe que la dicha consiga.\nEspero que tú me digas\nDe la obligación de amarte.\nYo el alma voy a dejarte\nMi bien, el amor me obliga.",3,1,0,29,"MI BIEN EL AMOR ME OBLIGA",18,10,"ia",-1,0,-1,0,136,136,"C-123","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0123-03",3,"¡Qué importa que la esperanza\nLe dé a mi pecho el sustento,\nSi temo que en algún tiempo\nHalle en tí alguna mudanza!\nAsí quiero sin tardanza\nDe aqueste empeño salir;\nQue yo estoy pronto a morir\nSi no gozo tu hermosura,\nPues esta razón me apura\nA decirte mi sentir.",3,1,0,29,"MI BIEN EL AMOR ME OBLIGA",18,10,"i",157,0,-1,0,136,136,"C-123","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0124-01",3,"Mi bien, para declararme\nY aliviar mi corazón,\nQuisiera que me señales\nTiempo, lugar y ocasión.",3,1,0,29,"MI BIEN PARA DECLARARME",0,4,"o",31,0,-1,0,137,137,"C-124","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0124-02",3,"Viéndome ciego de amor\nY de una pasión crecida\nQuisiera, bien de mi vida,\nMerecer de tí un favor,\nPara calmar mi dolor.\n¿Qué saco yo con quejarme\nSi no quieres escucharme\nPara aminorar mi mal?\nA solas te quiero hablar\nMi bien, para declararme.",3,1,0,29,"MI BIEN PARA DECLARARME",18,10,"ae",35,0,-1,0,137,137,"C-124","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0124-03",3,"Dime mi bien ¿de qué suerte\nA solas te podré ver,\nPara darte a conocer\nMi penalidad tan fuerte?\nYo padezco por quererte.\nY es mi única pretensión\nHacerte una explicación\nDe mis penas por extenso\nPorque tan sólo en tí pienso\nAliviar mi corazón.",3,1,0,29,"MI BIEN PARA DECLARARME",18,10,"o",31,0,-1,0,137,137,"C-124","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0124-04",3,"Es mi dolor tan violento,\nMi bien, si llego a mirarte,\nTe quiero y no puedo hablarte\nPara mayor sentimiento,\nSufro y callo mi tormento\nHasta dar fin a mis males\nPidiéndote que me ampares\nEn tan terrible agonía,\nAquel tan hermoso día\nQuisiera que me señales.",3,1,0,29,"MI BIEN PARA DECLARARME",18,10,"ae",-1,0,-1,0,137,137,"C-124","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0124-05",3,"Y por último, alma mía,\nAquí declaro mi intento,\nDispensa el atrevimiento\nDe quien se halla en la agonía.\nQuiero ser dueño algún día\nDe tu noble corazón,\nQuiero me des la razón\nSi por fortuna me admites\nEsperaré que me cites\nTiempo, lugar y ocasión.",3,1,0,29,"MI BIEN PARA DECLARARME",18,10,"o",31,0,-1,0,137,137,"C-124","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0125-01",3,"Mi bien, tres cosas te pido\nY esta ha de ser la primera,\nQue para cuando yo muera\nNunca me eches en olvido.\nPrenda que tanto he querido\nCorazón que entre amargura\nYo no quise a otra ninguna\nCon el extremo que a tí.\nTú no te olvides de mí\nMi alma, mi bien, mi hermosura.",3,1,0,29,"MI BIEN, TRES COSAS TE PIDO",18,10,"ua",-1,0,-1,0,138,138,"C-125","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0125-02",3,"La segunda es, cielo amado,\nQue cuando me esté muriendo\nNo estés donde te esté viendo\nQue es morir desesperado.\nCuando yo esté amortajado\nMe veas con hábito y velo\nLlorarás si tienes duelo\nAl ver mi triste desvío,\nAsí, no llores mi bien mío,\nTrata de tener consuelo.",3,1,0,29,"MI BIEN, TRES COSAS TE PIDO",18,10,"eo",10,0,-1,0,138,138,"C-125","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0125-03",3,"Ultimamente te pido\nQue en el momento en que muera,\nPor Dios me beses siquiera\nPor tanto que te he querido.\nTu corazón afligido\nNo lo tengas vida mía.\nSiempre mostrad alegría\nNo te acabes en llorar,\nAumentando así el pesar\nDe quién tanto te quería.",3,1,0,29,"MI BIEN, TRES COSAS TE PIDO",18,10,"ia",0,0,-1,0,138,138,"C-125","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0125-04",3,"Desde el mundo en que resida\nSiempre he de velar por vos\nNo quiero quieras a dos\nEn el resto de tu vida.\nEsta ya es mi despedida\nPorque la muerte me apura\n¡Adiós, mi bien, mi hermosura!\n¡Adiós, para siempre adiós!\nNos despidamos los dos\n¡Se acabó ya mi ventura!",3,1,0,29,"MI BIEN, TRES COSAS TE PIDO",18,10,"ua",17,0,-1,0,138,138,"C-125","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0127-01",3,"No extrañes de que mi amor\nTe lo venga a declarar;\nCon cariño sin igual\nCautiva mi corazón,\nY no puedo en la ocasión\nEn silencio sostener\nUn afecto que el deber\nNo puede ocultar más tiempo.\nDe cuya fé un juramento\nA tu presencia lo haré.",3,1,0,29,"NO EXTRAÑES DE QUE MI AMOR",18,10,"e",-1,0,-1,0,138,138,"C-127","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0127-02",3,"Si algún obstáculo tienes\nPara poderme querer,\nDímelo y sabré vencer\nTodo, si es que tú me quieres.",3,1,0,29,"NO EXTRAÑES DE QUE MI AMOR",5,4,"ee",-1,0,-1,0,138,138,"C-127","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0127-03",3,"A mí nada me detiene\nPara poder alcanzar\nTu mano y el disfrutar\nDe una pasión amorosa.\nY poder llamarte esposa\nAl pie del sagrado altar.",3,1,0,29,"NO EXTRAÑES DE QUE MI AMOR",9,6,"a",21,0,-1,0,139,139,"C-127","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0127-04",3,"Por fin si nada te priva\nUnir nuestros corazones,\nDe todas mis afecciones\nDispone, dueña querida,\nOrdena y obedecida\nLo serás sin dilación.\nY verás que el fino amor\nQue te ofrezco eternamente,\nEs un amor puramente\nNacido del corazón.",3,1,0,29,"NO EXTRAÑES DE QUE MI AMOR",18,10,"o",-1,0,-1,0,139,139,"C-127","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0127-05",3,"Yo he visto ni espero ver\nHermosura semejante,\nMás hermosa que el lucero\nY más fina que un diamante.",3,1,0,29,"NO HE VISTO NI ESPERO VER",0,4,"ae",47,0,-1,0,139,139,"C-127","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0127-06",3,"Perla de tanto valor\nClavel de tanta hermosura,\nNo le iguala en su ternura\nEl armiño superior.\nNi el resplandeciente sol\nQue brilla en el alto cielo\nDando luces a este suelo;\nDigo con admiración:\nQuién merezca vuestro amor\nYo he visto, ni espero ver.",3,1,0,29,"NO HE VISTO NI ESPERO VER",18,10,"e",-1,0,-1,0,139,139,"C-127","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0127-07",3,"Eres ángel adorado,\nVuestra fama es inmortal,\nQue ha reinado y reinará\nMientras dure el mundo criado,\nY después de éste acabado\nPasará más adelante.\nDios poderoso y constante\nTres mil mundos puede hacer,\nPero en ninguno ha de haber\nHermosura semejante.",3,1,0,29,"NO HE VISTO NI ESPERO VER",18,10,"ae",47,0,-1,0,139,139,"C-127","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0127-08",3,"Encantas con tu mirar\nPorque eres diosa divina.\nCual la perla cristalina\nQue nace a orillas del mar;",3,1,0,29,"NO HE VISTO NI ESPERO VER",11,4,"a",21,0,-1,0,139,139,"C-127","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0127-09",3,"Ninguna te ha de igualar\nEn todo este mundo entero.\nLo digo así y considero\nCuál será tu fundamento\nQue has nacido en este tiempo\nMás hermosa que un lucero.",3,1,0,29,"NO HE VISTO NI ESPERO VER",9,6,"eo",-1,0,-1,0,139,139,"C-127","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0127-10",3,"¡Hermosa y fragante flor\nQue en este mundo has nacido,\nOtra igual no he conocido\nNi en los jardines de amor!\nTu belleza es la mejor,\nNinguna podrá igualarte\nPorque eres tan elegante\nHecha de dos mil primores\nCodiciada de otras flores\nY más fina que un diamante.",3,1,0,29,"NO HE VISTO NI ESPERO VER",18,10,"ae",47,0,-1,0,139,139,"C-127","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0129-01",3,"No sé que hiciera de tí\nMi bien, dónde te escondiera,\nDonde solita te amara\nSin 'que otros ojos te vieran.",3,1,0,29,"NO SE QUE HICIERA DE TI",0,4,"ea",-1,0,-1,0,139,139,"C-129","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0129-02",3,"Si en ausencia te amo tanto\nEn presencia mucho más\n¿Dónde has de ir que no seas\nSiempre mi hechizo y mi encanto?\nSi en dormido me levanto\nY entre el sueño digo así:\nDi, mi bien, ¿estás aquí\nO te hallas en otra parte?\nAsí delirando amante\nNo sé que hiciera de tí.",3,1,0,29,"NO SE QUE HICIERA DE TI",18,10,"i",23,0,-1,0,139,139,"C-129","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0129-04",3,"Tomarás por posesión\nEl castillo de mi pecho,\nComo que tienes derecho\nEn mi amante corazón.\nPues mi sincera pasión\nMi fino amor te declara\nQue,si en tí dicha causara.\nSería brillante mi suerte\nSi consiguiera tenerte\nDonde solita te amara.",3,1,0,29,"NO SE QUE HICIERA DE TI",18,10,"aa",57,0,-1,0,139,140,"C-129","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0129-05",3,"En el rincón del oceano\nTe haré un redil de mi amor\nDonde como única flor\nTe cuidaré por mis manos;\nO cual prolijo hortelano\nSi tal suerte consiguiera\nEsto y mucho más hiciera\nQue es mi mayor interés,\nColocarte donde estés\nSin que otros ojos te vieran.",3,1,0,29,"NO SE QUE HICIERA DE TI",18,10,"ea",-1,0,-1,0,140,140,"C-129","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0129-a-01",3,"No sé que hiciera de tí\nNo sé dónde te escondiera\nDonde solito te amara\nSin que otros ojos te vieran.",3,1,0,29,"NO SE QUE HICIERA DE TI",0,4,"ea",-1,0,-1,0,140,140,"C-129-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0129-a-02",3,"Si en presencia te amo tanto\nEn ausencia mucho más\n¿Dónde irás que no serás\nSiempre mi dicha y mi encanto?\nY a fuerza de amarte tanto\nCon el mayor frenesí\nDí, mi bien, si estás aquí\nO te hallas en otra parte.\nPues delirando en amarte\nNo sé que hiciera de tí.",3,1,0,29,"NO SE QUE HICIERA DE TI",18,10,"i",23,0,-1,0,140,140,"C-129-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0129-a-03",3,"Si en el rincón del oceano\nAhí te rindiera mi amor\nDonde como única flor\nTe cuidara con mi mano.\nComo famoso hortelano\nSi tu venia consiguiera\nEso y mucho más hiciera\nQue sería mi voluntad;\nPara ocultar tu deidad\nNo sé dónde te escondiera.",3,1,0,29,"NO SE QUE HICIERA DE TI",18,10,"ea",44,0,-1,0,140,140,"C-129-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0129-a-04",3,"Si en el peñasco más duro\nResultas fino diamante.\nDeclaro no me es bastante\nEste asilo tan seguro.\n¿Qué será lo que procuro?",3,1,0,29,"NO SE QUE HICIERA DE TI",7,5,"uo",248,0,-1,0,140,140,"C-129-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0129-a-05",3,"¿En qué centro te pusiera,\nCon qué velo te cubriera\nQue fuera mi voluntad\nDónde te podría ocultar\nSin que otros ojos te vieran?",3,1,0,29,"NO SE QUE HICIERA DE TI",7,5,"ea",-1,0,-1,0,140,140,"C-129-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0130-01",3,"No te acobarden temores\nQue todo es amenazar,\nQuiéreme como te quiero\nY déjalo al mundo hablar.",3,1,0,29,"NO TE ACOBARDEN TEMORES",0,4,"a",21,0,-1,0,140,140,"C-130","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0130-02",3,"Por tu voluntad infiero\nQue contínuo te amenazan\nPorque ven que así no abrasan\nLas caricias con que os quiero;\nPorque ven que te venero\nTe ponen dos mil temores,\nQuieren privar los amores\nQue gozamos tan triunfantes.\nSé tu siempre fino amante\nNo te acobarden temores.",3,1,0,29,"NO TE ACOBARDEN TEMORES",18,10,"oe",5,0,-1,0,140,140,"C-130","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0130-03",3,"Ni aunque digas que a tu pecho\nLo destrozan con afán\nLlevate de aquel refrán\nQue \"hay mucho del dicho al hecho\".\nSi con un grande despecho\nNos quieren abandonar,\nNo tienes que recelar\nQue he despreciado tu suerte,\nSi te amenazan de muerte\nQue todo es amenazar.",3,1,0,29,"NO TE ACOBARDEN TEMORES",18,10,"a",21,0,-1,0,140,140,"C-130","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0130-04",3,"Ya lo veo que la gente\nRepara nuestra amistad,\nJuzgan que es temeridad\nY te ultrajan malamente,\nTú consérvate obediente\nCon un amor verdadero;\nSi alguno te es lisonjero\nTú le haces demostración\nPero entre tu corazón\nQuiéreme como te quiero.",3,1,0,29,"NO TE ACOBARDEN TEMORES",18,10,"eo",38,0,-1,0,140,140,"C-130","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0130-05",3,"Aunque digan que a tu vida\nLa parten con una espada,\nEs para que se deshaga\nLa voluntad que está unida.\n¿Qué no conoces, mi vida,",3,1,0,29,"NO TE ACOBARDEN TEMORES",7,5,"ia",37,0,-1,0,140,140,"C-130","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0130-06",3,"Que nos quieren estorbar\nUn amor tan singular\nQue ambos dos nos profesamos?\nGocemos lo que gozamos\nY déjalo al mundo hablar.",3,1,0,29,"NO TE ACOBARDEN TEMORES",7,5,"a",21,0,-1,0,141,141,"C-130","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0131-01",3,"Oculta, muy bien tu amor\nQue no sepan nuestro enredo,\nPorque si acaso se sabe\nEres perdida y me pierdo.",3,1,0,29,"OCULTA MUY BIEN TU AMOR",0,4,"eo",-1,0,-1,0,141,141,"C-131","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0131-02",3,"Procura disimular\nLa pasión que nos tenemos,\nPorque todo lo perdemos\nSi se llega a publicar.\nMira que no ha de faltar\nUn necio murmurador;\nY para evitar mejor\nDe que nos pongan apodo\nEchalo al silencio todo,\nOculta muy bien tu amor.",3,1,0,29,"OCULTA MUY BIEN TU AMOR",18,10,"o",72,0,-1,0,141,141,"C-131","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0131-03",3,"No tengas a novedad\nSi yo de tí me ausentare\nQue no falta quien repare\nCualquier cosa en la amistad.\nVos todo disimulad\nPorque yo hago cuanto puedo.\nAsí es que no tengo miedo\nPor tanto en nada me apuro,\nTan solamente procuro\nQue no sepan nuestro enredo.",3,1,0,29,"OCULTA MUY BIEN TU AMOR",18,10,"eo",304,0,-1,0,141,141,"C-131","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0131-04",3,"Muéstrame aborrecimiento\nY en público si es posible,\nAunque es un caso terrible\nApelar al fingimiento;\nPorque es mucho sufrimiento\nDisimular el querer\nEsto, mi bien, has de hacer\nNo vayas a descuidar\nQue no habrá mayor pesar\nSi esto se llega a saber.",3,1,0,29,"OCULTA MUY BIEN TU AMOR",18,10,"e",20,0,-1,0,141,141,"C-131","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0132-01",3,"Oye, ingrata, niña bella,\nLos acentos de mi voz,\nOye hermosa mi querella,\nNo te enojes, no, por Dios.",3,1,0,29,"OYE INGRATA NIÑA BELLA",1,4,"o",87,0,-1,0,141,141,"C-132","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0132-02",3,"Que al compás de mi guitarra\nA cantarte voy mi amor,\nQue las fibras ¡Ay, desgarra!\nDe mi pobre corazón.",3,1,0,29,"OYE INGRATA NIÑA BELLA",0,4,"o",-1,0,-1,0,141,141,"C-132","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0132-03",3,"Al través de una ventana\nTus hechizos contemplé,\nDesde entonces, soberana\nDe mi alma, te llamé.",3,1,0,29,"OYE INGRATA NIÑA BELLA",1,4,"e",77,0,-1,0,141,141,"C-132","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0132-04",3,"Desde entonces vago triste\nPor el campo del amor,\nY mi alma se resiste\nA la voz de la razón.",3,1,0,29,"OYE INGRATA NIÑA BELLA",0,4,"o",-1,0,-1,0,141,141,"C-132","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0132-05",3,"Sólo escucha apasionada\nEl gemir del corazón,\nY acaricia, desgraciada,\nDe mi ensueño la ficción.",3,1,0,29,"OYE INGRATA NIÑA BELLA",1,4,"o",31,0,-1,0,141,141,"C-132","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0132-06",3,"Es en vano que le diga\nQue destierre la ilusión,\nSólo escucha, dulce amiga,\nDe un amante la oración.",3,1,0,29,"OYE INGRATA NIÑA BELLA",1,4,"o",31,0,-1,0,141,141,"C-132","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0132-07",3,"Y por eso vago errante\nCual herido trovador,\nOstentando en mi semblante\nNegras sombras de dolor.",3,1,0,29,"OYE INGRATA NIÑA BELLA",1,4,"o",72,0,-1,0,141,141,"C-132","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0132-08",3,"Si llegan estos acentos\nA tu encantada mansión,\nNo desprecies mis lamentos\nTenme niña compasión.",3,1,0,29,"OYE INGRATA NIÑA BELLA",1,4,"o",31,0,-1,0,141,141,"C-132","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0132-09",3,"Que aquí al pie de tu ventana\nContemplando tu balcón,\nMe sorprende la mañana\nAbismado de dolor.",3,1,0,29,"OYE INGRATA NIÑA BELLA",0,4,"o",-1,0,-1,0,142,142,"C-132","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0133-01",3,"Paloma del alma mía\nEscuchadme en tu ventana\nQue ya la aurora cercana\nNos viene anunciando el día.\nAllá en la enramada umbría\nLos pajaritos cantores\nAlzan sus trinos mejores\nSaludántote contentos.\nMientras yo en tristes lamentos\nTe canto aquí mis amores.",3,1,0,29,"PALOMA DEL ALMA MÍA",18,10,"oe",5,0,-1,0,142,142,"C-133","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0133-02",3,"Escuchadme enternecida\nQue en cada verso que canto\nTe envío mojada en llanto\nLa esperanza de mi vida.\nEl silencio me convida\nA decirte niña hermosa\nCon voz triste y temblorosa\nEste amor que me maltrata\nY que mi alma se dilata\nEn esta hora misteriosa.",3,1,0,29,"PALOMA DEL ALMA MÍA",18,10,"oa",63,0,-1,0,142,142,"C-133","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0133-03",3,"¡Dulce paloma, perdona,\nSi entregada a tu beleño\nHa interrumpido tu sueño\nEl eco de mi canción!\nElla es pálida expresión\nDe mi inmenso amor y anhelo.\nPorque no hay en este suelo\nLengua para traducir\nLo que se llega a sentir\nInspirado por el cielo.",3,1,0,29,"PALOMA DEL ALMA MÍA",18,10,"eo",10,0,-1,0,142,142,"C-133","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0133-04",3,"Voy a terminar mi canto\nY me voy a retirar\nPero te quiero dejar\nAquí una gota de llanto.\nSabiendo que te amo tanto\nNo creerás que es de veneno,\nPor eso me voy sereno\nConfiado amada mujer,\nQue tú la has de recoger\nPara secarla en tu seno.",3,1,0,29,"PALOMA DEL ALMA MÍA",18,10,"eo",76,0,-1,0,142,142,"C-133","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0133-a-01",3,"Paloma del alma mía\nEscúchame a tu ventana\nQue ya la aurora cercana\nNos viene anunciando el día.\nAllá en la enramada umbría\nLos pajarillos cantores\nAlzan sus trinos mejores\nSaludándote contentos,\nMientras yo en tristes lamentos\nTe canto aquí mis amores.",3,1,0,29,"PALOMA DEL ALMA MÍA",18,10,"oe",5,0,-1,0,142,142,"C-133-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0133-a-02",3,"Escúchame enternecida\nQue en cada verso que canto\nTe envío empapado en llanto,\nUn pedazo de mi vida.\nQue en silencio me convida\nA explicarte, niña hermosa,\nCon voz triste y quejumbrosa\nLa pasión que me maltrata.\nEste mi amor se dilata\nEn esta hora misteriosa.",3,1,0,29,"PALOMA DEL ALMA MÍA",18,10,"oa",63,0,-1,0,142,142,"C-133-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0133-a-03",3,"¡Dulce paloma, perdón,\nSi entregada a tu beleño\nHa interrumpido tu sueño\nEl eco de mi canción!\nElla es pálida expresión\nDe mí extenso amor y anhelo,\nPorque no hay en este suelo\nLengua para traducir\nLo que se llega a sentir\nInspirado por el cielo.",3,1,0,29,"PALOMA DEL ALMA MÍA",18,10,"eo",10,0,-1,0,142,142,"C-133-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0134-01",3,"Por un acaso dichoso\nVoy siguiendo estos renglones,\nA ver si dos corazones\nSe unen con placer y gozo.",3,1,0,29,"POR UN ACASO DICHOSO",11,4,"oo",156,0,-1,0,142,142,"C-134","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0135-02",3,"Sin verte no puedo estar\nPorque sos todo mi anhelo;\nSuerte tan baja la mía,\nNi verte, ni hablarte puedo.",3,1,0,29,"QUIEN PUDIERA DUEÑO MIÓ",0,4,"eo",-1,0,-1,0,143,143,"C-135","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0136-01",3,"Quisiera verte y no verte\nQuisiera hablarte y no hablarte,\nQuisiera encontrarte a solas,\nY no quisiera encontrate.",3,1,0,29,"QUISIERA VERTE Y NO VERTE",0,4,"ae",-1,0,-1,0,143,143,"C-136","",0,"","","",12,0,0,[],""],["carrizo_salta-nc0136-03",3,"Si veo tu hermoso cielo\nMe pongo a considerar\nQue jamás he de alcanzar\nEsperanzas de consuelo.\nEn vano mi dulce anhelo\nSe afana por adorarte.\nNo me atrevo a declararte\nEl objeto que deseo.\nCada ocasión que te veo\nQuisiera hablarte y no hablarte.",3,1,0,29,"QUISIERA VERTE Y NO VERTE",18,10,"ae",8,0,-1,0,143,143,"C-136","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0136-04",3,"Si tus lindos ojos miro\nO vuestro ser adorado\nMi corazón angustiado\nExhala un triste suspiro.\nA los mares me retiro\nA deleitarme en las olas,\nComo creo que me inmolas\nCon tanta severidad\nMas, en una soledad\nQuisiera encontrarte sola.",3,1,0,29,"QUISIERA VERTE Y NO VERTE",18,10,"oa",-1,0,-1,0,143,143,"C-136","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0137-01",3,"Quisiera vivir contigo\nEn las lóbregas montañas,\nPara verme en las campañas\nLibre de todo enemigo.",3,1,0,29,"QUISIERA VIVIR CONTIGO",11,4,"io",106,0,-1,0,144,144,"C-137","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0137-02",3,"Solitarios arrabales\nDe habitación me sirvieran\nY sólo mis tratos fueran\nCon los brutos animales;\nPorque mis celos fatales\nDe ningún modo mitigan\nY así a decirte me obligan\nQue para librarme de ésto,\nEn el campo más funesto\nQuisiera vivir contigo.",3,1,0,29,"QUISIERA VIVIR CONTIGO",18,10,"io",-1,0,-1,0,144,144,"C-137","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0137-03",3,"Es mi fé tan verdadera\nY tanto quiero celarte\nQue quisiera encarcelarte\nA donde nadie te viera.\nO más antes me partiera\nPor esas tierras extrañas,\nTe ocultara en mis entrañas,\nPues el gusto me pedía\nVivir contigo, alma mía,\nEn las lóbregas montañas.",3,1,0,29,"QUISIERA VIVIR CONTIGO",18,10,"aa",42,0,-1,0,144,144,"C-137","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0137-04",3,"Tan sólo por tí sintiera\nVerme en esas soledades\nPor las incomodidades\nQue tu deidad padeciera;\nPero si en mí consistiera\nPor tí hiciera mil hazañas;\nCreedlo que no te engañas\nPues te tengo tal amor\nQue no me falta valor\nPara verme en las campañas.",3,1,0,29,"QUISIERA VIVIR CONTIGO",18,10,"aa",42,0,-1,0,144,144,"C-137","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0137-05",3,"Al que te quiere aborrezco,\nAl que no te quiere peor;\nY de aquí nace el ardor\nTan contrario que padezco;\nPues sólo lo que apetezco\nEs irme, mi bien, contigo,\nY como no lo consigo\nSe aumenta mi padecer,\nPorque no me puedo ver\nLibre de todo enemigo.",3,1,0,29,"QUISIERA VIVIR CONTIGO",18,10,"io",106,0,-1,0,144,144,"C-137","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0138-01",3,"Recordarás, vida mía,\nCuando intentes olvidarme,\nQue me compraron tus ojos\nCon el precio de mirarme.",3,1,0,29,"RECORDARAS MI VIDA",0,4,"ae",35,0,-1,0,144,144,"C-138","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0138-02",3,"Ponerme en eterno olvido\nSi intentaras algún día,\nDe mi amor constante y firme\nRecordarás, dueña mía.",3,1,0,29,"RECORDARAS MI VIDA",0,4,"ia",0,0,-1,0,144,144,"C-138","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0140-01",3,"¡Señorita, atiéndale\nLo que dice un desgraciado\nQue se rinde a su presencia\nDeseando ser su criado!",3,1,0,29,"SEÑORITA ATIÉNDALE",0,4,"ao",14,0,-1,0,145,145,"C-140","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0140-02",3,"Con imponderable amor\nA su presencia me vengo,\nPor ver si méritos tengo\nDe conseguir un favor.\nAsí con esta razón,\nSi me permite diré\nQue yo para Ud. seré,\nFirme y fiel hasta la muerte.\nAl que le habla de esta suerte\nSeñorita, atiéndale.",3,1,0,29,"SEÑORITA ATIÉNDALE",18,10,"ee",-1,0,-1,0,145,145,"C-140","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0140-03",3,"¿Hasta cuando podrá estar\nCautivo mi corazón?\nSi me saca de prisión\nYa dejaré de penar.\nDuélase de mi pesar\nEn que me hallo acongojado\nDe su vista apasionado,\nVolveré a prevalecer\nY ahora quiero hacerla ver\nLo que dice un desgraciado.",3,1,0,29,"SEÑORITA ATIÉNDALE",18,10,"ao",14,0,-1,0,145,145,"C-140","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0140-04",3,"Pero ¿hasta cuándo, mi cielo,\nMe has de tener padeciendo?\n¿No miras que estoy viviendo\nEn tan triste desconsuelo\nY llorando me desvelo\nEsperando tu sentencia?\nComo tienes experiencia\nDecide esta mi cuestión\nDesengaña a un corazón\nQue se rinde a tu presencia.",3,1,0,29,"SEÑORITA ATIÉNDALE",18,10,"ea",46,0,-1,0,145,145,"C-140","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0140-05",3,"Señorita, Ud. dirá\nCual es el fin de mi suerte\nSi soy de vida o de muerte\nBien me lo puede avisar.\nYa dejaré de penar,\nQue perezca un desgraciado,\nTanto tiempo que ha pasado\nEn tan contínuos desdenes\nY ahora a tu presencia viene\nDeseando ser su criado.",3,1,0,29,"SEÑORITA ATIÉNDALE",18,10,"ao",14,0,-1,0,145,145,"C-140","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0140-a-02",3,"Con imponderable amor\nA su presencia me vengo\nPor ver si mérito tengo\nDe conseguir un favor.\nAsí con esta razón\nSi me permite diré\nQue yo para Ud. seré\nFirme y fiel hasta la muerte.\nAl que le habla de esta suerte\nSeñorita, atiéndale.",3,1,0,29,"SEÑORITA ATIÉNDALE",18,10,"ee",-1,0,-1,0,146,146,"C-140-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0140-a-03",3,"¿Hasta cuando habrá de estar\nCautivo mi corazón?\nSi me saca esta prisión\nYa dejaré de penar.\nMire mi felicidad\nComo me hallo acongojado\nA su vista presentado\n¡Cómo ha de prevalecer!\nSólo por hacerla ver\nLo que dice un desgraciado.",3,1,0,29,"SEÑORITA ATIÉNDALE",18,10,"ao",14,0,-1,0,146,146,"C-140-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0140-a-04",3,"Pero ¿hasta cuando mi cielo\nHe de vivir padeciendo?\n¿No miras que estoy temiendo\nEl más triste desconsuelo?\nY llorando me desvelo\nEsperando tu sentencia.\nY como juez de experiencia\nDecide esta mi cuestión.\nDesengaña a un corazón\nQue se rinde a tu presencia.",3,1,0,29,"SEÑORITA ATIÉNDALE",18,10,"ea",46,0,-1,0,146,146,"C-140-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0140-a-05",3,"Señorita Ud. dirá\nCual es el fin de mi suerte\nSi soy de vida o de muerte\nYa basta para llorar.\nBien me lo podrá avisar\nQue fallezca un desgraciado",3,1,0,29,"SEÑORITA ATIÉNDALE",9,6,"ao",-1,0,-1,0,146,146,"C-140-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0140-a-06",3,"Que tanto tiempo ha pasado\nCon tan terribles desdenes.\nA su presencia me tiene\nDeseando ser su criado.",3,1,0,29,"SEÑORITA ATIÉNDALE",5,4,"ao",14,0,-1,0,146,146,"C-140-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0141-01",3,"Si con llorar yo pudiera\nRemediar la pena mía\nMi llanto no acabaría\nHasta que alivio tuviera.",3,1,0,29,"SI CON LLORAR YO PUDIERA",11,4,"ea",44,0,-1,0,146,146,"C-141","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0141-02",3,"Que te conmuevas quisiera\nDe este infeliz desgraciado\nQue se viene a tu presencia\nDeseando ser tu criado.",3,1,0,29,"SI CON LLORAR YO PUDIERA",0,4,"ao",14,0,-1,0,146,146,"C-141","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0141-03",3,"Un amor disimulado\nTe tengo en mi corazón\nNo te digo mi intención\nPor no verme despreciado.",3,1,0,29,"SI CON LLORAR YO PUDIERA",11,4,"ao",14,0,-1,0,146,146,"C-141","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0141-04",3,"Todo esto que yo te digo\nMe nace de mi pasión\nSi tú me das tu palabra\nYo te doy mi corazón.",3,1,0,29,"SI CON LLORAR YO PUDIERA",0,4,"o",31,0,-1,0,146,146,"C-141","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0141-05",3,"Si al corazón me lo pides\nAquí lo tienes rendido.\n¿Cómo te lo he de negar\nSi eres mi cielo querido?",3,1,0,29,"SI CON LLORAR YO PUDIERA",0,4,"io",101,0,-1,0,146,146,"C-141","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0141-06",3,"Eres mi cielito hermoso\nY mi lucero brillante\nOjalá que tú me quieras\nVida, para ser tu amante.",3,1,0,29,"SI CON LLORAR YO PUDIERA",0,4,"ae",47,0,-1,0,146,146,"C-141","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0142-01",3,"Si el mismo sol me la diera,\nYo al sol se la entregara\nPara que él me la guardara.\nAún que el mundo se opusiera\nHaría yo lo que quisiera;",3,1,0,29,"SI EL MISMO SOL ME LA DIERA",7,5,"ea",44,0,-1,0,146,147,"C-142","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0143-03",3,"Déjame sólo morir\nNo acompañes mi tormento\nQue es mayor mi sentimiento\nCuando yo te veo sentir.\nProcúrate divertir\nNo te dejes de alegrar\nAndá, si quieres andar\nGustoso por donde quieras.\nPorque te digo de veras\nYo quiero por tí penar.",3,1,0,29,"SI EL PADECER CAUSA AMOR",18,10,"a",-1,0,-1,0,147,147,"C-143","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0143-04",3,"Yo no siento pues tirano,\nQue me trates de abatir\nLo que siento es recibir\nUn desprecio de tus manos.\nA tus ojos soberanos\nLes tengo que suplicar\nSi me llegan a mirar\nQue me infieran una herida\nPero que me dejen vida\nPara poderte probar.",3,1,0,29,"SI EL PADECER CAUSA AMOR",18,10,"a",21,0,-1,0,147,147,"C-143","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0143-05",3,"Si yo supiera de cierto\nQue tu honor no peligrara\nPor las calles publicara\nQue tu amor me tiene muerto.\nAsí, mi bien, te lo advierto\nQue es muy crecido mi amor.\nSi algún otro adorador\nDice que por tí se muere\nPregúntale si te quiere\nComo yo te quiero a vos.",3,1,0,29,"SI EL PADECER CAUSA AMOR",18,10,"o",-1,0,-1,0,147,147,"C-143","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0144-01",3,"Si hay tras de la muerte amor\nDespués de muerto he de amarte,\nY aunque esté en polvo disuelto,\nSeré polvo y fino amante.",3,1,0,29,"SI HAY TRAS DE LA MUERTE",0,4,"ae",-1,0,-1,0,147,147,"C-144","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0144-02",3,"Parca inhumana podrá\nCortar de mi vida el hilo,\nY un sepulcro, el triste asilo,\nDe mis cenizas será;\nPero esto no impedirá\nQue te ame con más fervor,\nY con cariño mayor,\nAllá en la eterna morada,\nSerás de mí siempre amada,\nSi hay tras de la muerte amor.",3,1,0,29,"SI HAY TRAS DE LA MUERTE",18,10,"o",72,0,-1,0,147,148,"C-144","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0144-03",3,"Si el espíritu no muere,\nY de él nace el sentimiento,\nSerá mi mayor tormento\nMientras el alma existiere,\nY así que el cuerpo muriere,\nY el alma de mi se aparte,\nAcaso no podré hablarte,\nPero siempre viviré,\nY en dondequiera que esté\nDespués de muerto he de amarte.",3,1,0,29,"SI HAY TRAS DE LA MUERTE",18,10,"ae",8,0,-1,0,148,148,"C-144","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0144-04",3,"Si por desventura rara\nMi alma llegara a expirar,\nA fuerza de tanto amar,\nTal vez se inmortalizara,\nPero si mortal quedara,\nCuerpo y espíritu yerto,\nTe amaré después de muerto.\nY, si me sepulcro pisas\nTe adorarán mis cenizas\nAunque esté en polvo disuelto.",3,1,0,29,"SI HAY TRAS DE LA MUERTE",18,10,"eo",-1,0,-1,0,148,148,"C-144","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0144-05",3,"En sombría sepultura,\nCadáver inanimado,\nPodré acaso estar privado,\nDe mostrarte mi ternura,\nSumergido en tumba obscura,\nMelancólico habitante\nEnamorado aterrante\nDonde nunca cupo amor,\nDisuelto en polvo de horror\nSeré polvo y fino amante.",3,1,0,29,"SI HAY TRAS DE LA MUERTE",18,10,"ae",47,0,-1,0,148,148,"C-144","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0144-a-01",3,"Si hay tras de la muerte amor\nDespués de muerto he de amarte,\nY aunque esté en polvo disuelto\nSeré polvo y polvo amante.",3,1,0,29,"AMOR",0,4,"ae",-1,0,-1,0,148,148,"C-144-a","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0144-a-03",3,"Pero esto no impedirá\nQue te ame con más fervor\nY con cariño mayor\nAllá en la eterna morada\nSerás de mí siempre amada,\nSi hay tras de la muerte amor.",3,1,0,29,"AMOR",9,6,"o",72,0,-1,0,148,148,"C-144-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0144-a-04",3,"Si el espíritu no muere\nY de él nacen afectos\nNo cesarán los efectos\nMientras la causa existiera,\nMás, aunque el cuerpo muriera\nY el espíritu se aparte\nAcaso no podré hablarte\nPero a tu lado estaré\nY donde quiera que esté\nDespués de muerto he de amarte.",3,1,0,29,"AMOR",18,10,"ae",8,0,-1,0,148,148,"C-144-a","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0144-a-05",3,"Si por desventura rara\nMi alma llegara a expirar\nA fuerza de tanto amar\nTal vez se inmortalizara.\nPero si mortal quedara\nCuerpo y espíritu yerto\nEn mi triste polvo envuelto\nSi es que mi sepulcro pisas\nTe adorarán mis cenizas\nAunque esté en polvo disuelto.",3,1,0,29,"AMOR",18,10,"eo",354,0,-1,0,148,148,"C-144-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0144-a-06",3,"En el país de la muerte\nVagará mi sombra errante\nY siempre seré constante\nY eterno seré en quererte.\nSi puedo venir a verte\nNo perderé un sólo instante.\nAprovecharé anhelante\nLa ocasión que haya tenido\nY aunque en polvo convertido\nSeré polvo y polvo amante.",3,1,0,29,"AMOR",18,10,"ae",47,0,-1,0,148,148,"C-144-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0144-b-01",3,"Si hay tras de la muerte amor\nDespués de muerto he de amarte,\nY aunque esté en polvo disuelto\nSeré pobre y fino amante.",3,1,0,29,"",0,4,"ae",-1,0,-1,0,148,148,"C-144-b","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0144-b-02",3,"Parca inhumana podrá\nCortar de mi vida el hilo\nY un triste sepulcro, asilo\nDe mis cenizas será.\nMas, esto no impedirá\nQue te ame con más fervor\nY con cariño mayor\nAllá en la eterna morada,\nSerás de mí siempre amada\nSi hay tras de la muerte amor.",3,1,0,29,"",18,10,"o",72,0,-1,0,148,149,"C-144-b","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0144-b-03",3,"Si el espíritu no muere\nY de él nacen los afectos\nNo cesarán los efectos\nMientras la causa existiere.\nPero si el cuerpo muriere\nY el alma de mí, se parte\nAcaso no podré hablarte\nPero siempre viviré\nY en cualquier parte que esté\nDespués de muerto he de amarte.",3,1,0,29,"",18,10,"ae",8,0,-1,0,149,149,"C-144-b","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0145-02",3,"Cuando en un sepulcro frío\nEsté después que no viva,\nCon fuerza la más activa,\nTe adorará, el amor mío,\nAllí amaré tu desvío\nAllí amaré tu rigor,\nY allí con mayor ardor\nSiendo ya cadáver yerto\nTe he de amar entre los muertos\nSi hay tras de la muerte amor.",3,1,0,29,"SI HAY TRAS DE LA MUERTE AMOR",18,10,"o",72,0,-1,0,149,149,"C-145","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0145-03",3,"Cuando en escombros, deshecho,\nNo le quede a mi existencia,\nMás que una triste apariencia,\nTú estarás viva en mi pecho.\nDel cadavérico lecho\nDonde sólo se ve el arte\nLa destrucción y contraste,\nDe los seres que han vivido,\nAllí entre todos metido\nDespués de muerto he de amarte.",3,1,0,29,"SI HAY TRAS DE LA MUERTE AMOR",18,10,"ae",-1,0,-1,0,149,149,"C-145","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0145-04",3,"Cuando todos los amores\nDel mundo hayan acabado,\nY tan sólo hayan quedado,\nRestos de los amadores,\nRevivirán los ardores\nDe un triste cadáver yerto,\nQue aunque esté en la nada envuelto\nHa de acertar a nombrarte,\nY de allí vendrá a buscarte\nAunque esté en polvo disuelto.",3,1,0,29,"SI HAY TRAS DE LA MUERTE AMOR",18,10,"eo",354,0,-1,0,149,149,"C-145","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0145-05",3,"Nada tengo que temer\nNada tengo que sentir,\nYa no me es triste el morir\nPues siempre te he de querer,",3,1,0,29,"SI HAY TRAS DE LA MUERTE AMOR",11,4,"e",20,0,-1,0,149,149,"C-145","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0145-06",3,"Presente te he de tener,\nSin olvidarte un instante,\nAllí te seré constante\nEn ese caos de olvido,\nAunque en polvo convertido\nSeré polvo y fino amante.",3,1,0,29,"SI HAY TRAS DE LA MUERTE AMOR",9,6,"ae",47,0,-1,0,150,150,"C-145","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0146-01",3,"Si no tienes entregado\nTu corazón a otro amante\nDímelo que yo constante\nTe quiero cielo adorado.\nMucho tiempo he ocultado\nLa pasión que te tenía\nPero hoy no puedo, alma mía,\nOcultarte por más tiempo\nTodo el cariño que siento\nCon creciente idolatría.",3,1,0,29,"SI NO TIENES ENTREGADO",18,10,"ia",0,0,-1,0,150,150,"C-146","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0146-02",3,"Puedes creerme, dulce encanto,\nPorque mis palabras son\nNacidas del corazón\nDe quien te idolatra tanto.\nY con amor sacrosanto\nCon firmeza te amaré.\nY si con la misma fé\nPuedo ser corespondido\nEn este mundo, bien mío,\nEl más dichoso seré.",3,1,0,29,"SI NO TIENES ENTREGADO",18,10,"e",77,0,-1,0,150,150,"C-146","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0146-03",3,"Mi cariño es invencible\nEn el amor y querer\nY sabrá siempre vencer\nLos mayores imposibles;\nPero si tu amor es libre\nY me lo cedes a mí\nBello será el porvenir\nDe una dicha venturosa\nSi me quieres niña hermosa\nComo yo te quiero a tí.",3,1,0,29,"SI NO TIENES ENTREGADO",18,10,"i",-1,0,-1,0,150,150,"C-146","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0146-04",3,"En fin, hermosa deidad,\nConsidera que te quiero\nY que sólo de tí espero\nToda mi felicidad.\nSi alguna dificultad\nTuvieras una ocasión\nConsulta tu corazón\nCon la tranquila conciencia\nVerás la correspondencia,\nBien mío, de nuestro amor.",3,1,0,29,"SI NO TIENES ENTREGADO",18,10,"o",-1,0,-1,0,150,150,"C-146","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0147-01",3,"Si supieras el dolor\nQue por tu ausencia padezco\nVerías, mi bien, que merezco\nDe tu deidad un favor.",3,1,0,29,"SI SUPIERAS EL DOLOR",11,4,"o",72,0,-1,0,150,150,"C-147","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0147-02",3,"Aunque tuvieras, mi bien,\nDe mármol tu corazón\nA compasión te moviera\nSi supieras el dolor.",3,1,0,29,"SI SUPIERAS EL DOLOR",0,4,"o",-1,0,-1,0,150,150,"C-147","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0147-03",3,"Las noches velando paso\nCon suspiros, me amanezco\nContemplando, dulce encanto,\nQue por tu ausencia padezco.",3,1,0,29,"SI SUPIERAS EL DOLOR",0,4,"eo",355,0,-1,0,150,150,"C-147","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0147-04",3,"Si vieras mi corazón\nSupieras lo que padezco\nY si me vieras el pecho\nVerías mi bien que merezco.",3,1,0,29,"SI SUPIERAS EL DOLOR",0,4,"eo",-1,0,-1,0,150,150,"C-147","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0147-05",3,"En premio de las finezas\nDe mi dulce y tierno amor\nSólo espero me concedas\nDe tu deidad un favor.",3,1,0,29,"SI SUPIERAS EL DOLOR",0,4,"o",72,0,-1,0,150,150,"C-147","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0148-01",3,"Sueño que estoy a tu lado\nEn tus brazos, vida mía,\n¡Sólo, en sueños, ay, podría\nTener suerte un desgraciado!",3,1,0,29,"SUEÑO QUE ESTOY A TU LADO",11,4,"ao",14,0,-1,0,150,150,"C-148","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0148-02",3,"No se me quita un instante\nAquella hermosa ilusión\nDe tu bella perfección\nQue se me pone adelante.\nVé si será penetrante\nEl gran amor que me ha entrado\nCuando al sueño me he entregado\nPor ver si te echo en olvido\nApenas quedo dormido\nSueño que estoy a tu lado.",3,1,0,29,"SUEÑO QUE ESTOY A TU LADO",18,10,"ao",14,0,-1,0,150,150,"C-148","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0148-05",3,"Verte en tan corta distancia\nY no gozarte es dolor,\nMas viendo tibio tu amor\nentonces más crece mi ansia.\nY en esta cruel circunstancia\nQué haré si soy desgraciado!\nPero pienso ser premiado\nY ser fino eternamente\nPorque puede de repente\nTener suerte un desgraciado.",3,1,0,29,"SUEÑO QUE ESTOY A TU LADO",18,10,"ao",14,0,-1,0,151,151,"C-148","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0148-a-03",3,"Hoy con mi dulce contento\nA la voz de su deidad\nAl ver que no era verdad\nMe causa un gran sentimiento.\nSólo con el pensamiento\nPuedo tener alegría.\n¿Cuándo llegará aquel día\nDe aquel dichoso placer\nQue me hi de llegar a ver\nEn sus brazos vida mía?",3,1,0,29,"SOÑÉ QUE ESTABA A SU LADO",18,10,"ia",0,0,-1,0,151,151,"C-148-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0148-a-04",3,"Al verla en corta distancia\nEl no hablarla es mi dolor,\nCuando veo tibio mi amor\nEntonces crecen mis ansias.\n¿Qué haré yo en la circunstancia\nQue haré si soy desgraciado?\nEsperaré ser premiado\nNo desconfío enteramente.\nPueda ser que en de repente\nTenga gloria un desgraciado.",3,1,0,29,"SOÑÉ QUE ESTABA A SU LADO",18,10,"ao",14,0,-1,0,151,151,"C-148-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0149-01",3,"Te quiero más que a mi vida\nMás que a la tierra y al cielo\nTe quiero más que a mis padres\nYa más quererte no puedo.",3,1,0,29,"TE QUIERO MAS QUE A MI VIDA",0,4,"eo",-1,0,-1,0,151,151,"C-149","",0,"","","",7,0,0,[],""],["carrizo_salta-nc0149-02",3,"Más que a mi patria te adoro\nMás que a mi gloria y honor\nMás que a mi primer amor\nMás que el ambicioso al oro.",3,1,0,29,"TE QUIERO MAS QUE A MI VIDA",11,4,"oo",85,0,-1,0,151,151,"C-149","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0149-03",3,"Porque mi amor por sí mismo\nEs más grande que este mundo\nMás hondo que el mar profundo\nMás terrible que el abismo.",3,1,0,29,"TE QUIERO MAS QUE A MI VIDA",11,4,"io",356,0,-1,0,151,151,"C-149","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0149-04",3,"Si el universo muriera\nY no calentara el sol\nCon el fuego de mi amor\nPienso que a su ser volviera.",3,1,0,29,"TE QUIERO MAS QUE A MI VIDA",5,4,"ea",44,0,-1,0,151,151,"C-149","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0149-05",3,"Te diera el alma y la vida\nSólo porque me quisieras\nTe diera mi corazón\nSi el corazón me pidieras.",3,1,0,29,"TE QUIERO MAS QUE A MI VIDA",0,4,"ea",103,0,-1,0,151,151,"C-149","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0150-01",3,"Toda mi pasión en tí\nTodo mi consuelo es verte.\nQuitarme de que te quiera\n¿Quién podrá? ¡Sólo la muerte!",3,1,0,29,"TODA MI PASIÓN EN TI",0,4,"ee",134,0,-1,0,152,152,"C-150","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0150-02",3,"Eres todo mi deleite\nDesde el instante que os ví\nPues tu deidad cautivó\nToda mi pasión en tí.",3,1,0,29,"TODA MI PASIÓN EN TI",0,4,"i",23,0,-1,0,152,152,"C-150","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0150-03",3,"Por dichoso me contemplo\nNo puede menos mi suerte\nY así te confieso pues\nTodo mi consuelo es verte.",3,1,0,29,"TODA MI PASIÓN EN TI",0,4,"ee",134,0,-1,0,152,152,"C-150","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0150-04",3,"Dichoso puede llamarse\nVencedor en donde quiera\nMi bien,aquel que conciba\nQuitarme de que te quiera.",3,1,0,29,"TODA MI PASIÓN EN TI",0,4,"ea",-1,0,-1,0,152,152,"C-150","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0150-05",3,"Yo me abraso en vuestro amor\nMás ¡ay, qué fuego tan fuerte!\nEl atreverse a apagarle\n¿Quién podrá? ¡Sólo la muerte!",3,1,0,29,"TODA MI PASIÓN EN TI",0,4,"ee",134,0,-1,0,152,152,"C-150","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0151-01",3,"Todo mi fin es quererte\nNadie me lo ha de impedir,\nQue por tí pienso morir\nSi eres firme hasta la muerte.",3,1,0,29,"TODO MI FIN ES QUERERTE \u003c",11,4,"ee",134,0,-1,0,152,152,"C-151","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0151-02",3,"Más firme que el sol seré\nY más fino que un diamante,\nComo tú me seas constante\nTe guardaré toda fe.\nPor tí, la vida daré\nY el sacrificio más fuerte,\nTan sólo por merecerte\nMe rendiré al padecer,\nHasta la sangre daré\nTodo mi fin es quererte.",3,1,0,29,"TODO MI FIN ES QUERERTE \u003c",18,10,"ee",134,0,-1,0,152,152,"C-151","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0151-03",3,"Yo confieso que te quiero\nCon toda mi voluntad,\nBuscando voy tu amistad,\nSólo le temo al desprecio,",3,1,0,29,"TODO MI FIN ES QUERERTE \u003c",5,4,"eo",-1,0,-1,0,152,152,"C-151","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0151-04",3,"No me des de qué sentir\nPorque me quita el vivir\nEsta mi fuerte pasión.\nPara darte el corazón\nNadie me lo ha de impedir.",3,1,0,29,"TODO MI FIN ES QUERERTE \u003c",7,5,"i",157,0,-1,0,152,152,"C-151","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0151-05",3,"No desprecies mi fineza\nPor buscar otro placer.\nMira, que en otro poder\nNo has de hallar tanta firmeza.\nYo no te ofrezco grandeza\nPero te podré decir\nQue otro amante igual a mí\nEn el mundo no has de ver.\nTan firme soy al querer\nQue por tí pienso morir.",3,1,0,29,"TODO MI FIN ES QUERERTE \u003c",18,10,"i",-1,0,-1,0,152,152,"C-151","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0151-06",3,"Firme soy y te diré,\nPara mayor complacencia:\nTe aseguro la obediencia\nY te juro por mi fe,\nQue yo constante seré\nSi tú haces felíz mi suerte\nMi consuelo será el verte,\nNo te olvidaré un instante\nTe adoraré como amante\nSi eres firme hasta la muerte.",3,1,0,29,"TODO MI FIN ES QUERERTE \u003c",18,10,"ee",134,0,-1,0,152,152,"C-151","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0152-01",3,"Todo, todo en este mundo\nTerminará su existencia\nPero jamás la firmeza\nDe mi cariño profundo.\nY si un pesar iracundo\nViene a aumentar mi dolor\nEntonces con más fervor\nA esta mi pasión ardiente\nNo la borrará la muerte\nSi hay tras de la muerte amor.",3,1,0,29,"TODO, TODO EN ESTE MUNDO",18,10,"o",72,0,-1,0,152,152,"C-152","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0152-02",3,"Cuando en el sepulcro frío\nEsté mi cuerpo sin vida\nCon fuerza la más activa\nTe adorará el amor mío.\nTal vez tu eterno desvío\nMe trate con más rigor\nY aunque una fuerza mayor\nVenga a aumentar mi tormento\nTe amaré después de muerto\nSi hay tras de la muerte amor.",3,1,0,29,"TODO, TODO EN ESTE MUNDO",18,10,"o",72,0,-1,0,152,153,"C-152","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0152-04",3,"En fin mi prenda adorada\nLa muerte no sentiré\nSi después de ella hallaré\nDe mis pesares la calma.\nEl espíritu de mi alma\nTe hará luz en derredor\nDe la dicha al fulgor\nVerás con placer fecundo\nQue te amé en el otro mundo\nSi hay tras de la muerte amor.",3,1,0,29,"TODO, TODO EN ESTE MUNDO",18,10,"o",72,0,-1,0,153,153,"C-152","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0153-04",3,"El clavel que yo te ofrezco\nMi corazón sacrifica.\nEs fuego que te dedica\nMi amorosa voluntad,\nY si tú con humildad\nCorrespondes mis finezas\nConsagraré a tu belleza\nEn honor de tus amores\nUna corona de flores\nQue formó la naturaleza.",3,1,0,29,"TOMA HERMOSA ESTE CLAVEL",18,10,"ea",108,0,-1,0,153,153,"C-153","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0153-05",3,"¿Qué prueba más eficaz\nPuede darte un hortelano\nQue brindarte por su mano\nLa prenda que estima más?\nYa como amante veraz\nTe doy mi sangre y sudor\nRecibe, mi alma, esta flor\nQue en ella os doy a entender\nQue tú mi flor has de ser\nEn los jardines de amor.",3,1,0,29,"TOMA HERMOSA ESTE CLAVEL",18,10,"o",72,0,-1,0,153,153,"C-153","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0153-a-02",3,"En el clavel que te ofrezco\nVa cifrada mi pasión\nCon tal pena y confusión\nQue por tu causa padezco.\nSi algún alivio merezco\nPor mi fineza tan fiel\nNo te demuestres tan cruel,\nDulce fin de mi esperanza,\nY si quieres la probanza\nToma hermosa este clavel.",3,1,0,29,"TOMA HERMOSA ESTE CLAVEL",18,10,"e",32,0,-1,0,153,153,"C-153-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0154-01",3,"Entre tupidos vergeles\nLa vide feliz, graciosa,\nMás humilde que una rosa,\nAdornada de claveles.\nTus ojos son dos laureles\nDonde mi amor se esmeró\nCon afecto y con primor\nDe este tu amor lisonjero,\nQue pareces un jilguero\nQue en un pinar se paró.",3,1,0,29,"TOMO LA PLUMA DE MIS MANOS",18,10,"o",-1,0,-1,0,154,154,"C-154","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0154-02",3,"Tomo la pluma en mis manos\nPara escribir mi esperanza\nAunque tú me pagues mal\nEn mí no hallarás mudanza.",3,1,0,29,"",0,4,"aa",163,0,-1,0,154,154,"C-154","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0154-03",3,"Mudanza en mí no hallarás\nPorque te supe querer\nAunque mil tormentos pase\nMás firme te hi de querer.",3,1,0,29,"",0,4,"e",-1,0,-1,0,154,154,"C-154","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0154-04",3,"Más firme te hi de querer\nPorque no te hi de olvidar\nSólo el rato que yo duermo\nPor tí dejo de llorar.",3,1,0,29,"",0,4,"a",21,0,-1,0,154,154,"C-154","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0154-05",3,"Dejen de llorar mis ojos\nQue en mí cabe la tristeza\nAl pensar en vuestro cielo\nEl alma se me atraviesa.",3,1,0,29,"",0,4,"ea",201,0,-1,0,154,154,"C-154","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0154-06",3,"El alma se me atraviesa\nY al mundo doy por testigo\nYo te daré a conocer\nLo mucho que te he querido.",3,1,0,29,"",0,4,"io",-1,0,-1,0,154,154,"C-154","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0154-07",3,"Te hi querido dueña mía\nSin adulación ninguna\nY ahora que no me quieres\nSerá mi mala fortuna.",3,1,0,29,"",0,4,"ua",56,0,-1,0,154,154,"C-154","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0155-01",3,"Tú eres águila imperial\nQue en un pinar se paró,\nEres más bella que el alba\nCuando va rayando el sol.",3,1,0,29,"TU ERES ÁGUILA IMPERIAL",0,4,"o",-1,0,-1,0,154,154,"C-155","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0155-02",3,"De los campos vierten flores,\nDe las fuentes aguas claras,\nNacen de tu bella cara\nJardines muy superiores,\nEclipsan con tus colores\nA una rosa sin igual.\nAún metida en un cristal\nEres purísima rosa\nResplandeciente y hermosa\nTú eres águila imperial.",3,1,0,29,"TU ERES ÁGUILA IMPERIAL",18,10,"a",1,0,-1,0,154,154,"C-155","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0155-04",3,"Al fin ya he dicho lo que eres\nNo puedo decirte más\nPues que para mí serás\nUn prodigio de placeres,\nDime, mi bien, si me quieres\nO hay otro amor que más valga.\nYo te amé, con toda calma\nDesde el día en que te ví\nPues pienso que para mí\nEres más linda que el alba.",3,1,0,29,"TU ERES ÁGUILA IMPERIAL",18,10,"aa",-1,0,-1,0,154,154,"C-155","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0155-05",3,"Tú eres astro, el más luciente\nEngastado en luces bellas,\nCielo sembrado de estrellas.\nTú eres la luz del oriente.\nDe tí, la luna pendiente\nEl lucero y su candor\nNadie iguala a tu arrebol.\nTú eres misteriosa escala\nQue tu claridad iguala\nCuando va rayando el sol.",3,1,0,29,"TU ERES ÁGUILA IMPERIAL",18,10,"o",24,0,-1,0,154,154,"C-155","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0155-06",3,"Tú eres la reina y señora\nSoberana de mi amor,\nTú eres el brillante sol\nTú la refulgente aurora.\nTú eres a quién tanto adora\nMi corazón anhelante.\nTú eres la perla brillante\nQue mi pasión ilumina.\nTú eres la joya más fina\nA quien adoro constante.",3,1,0,29,"TU ERES LA REINA Y SEÑORA",18,10,"ae",47,0,-1,0,154,154,"C-155","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0155-07",3,"Yo soy quien puedo querer\nCon el mayor frenesí\nYo soy quién muero por tí\nSi no puedo merecerte.",3,1,0,29,"TU ERES LA REINA Y SEÑORA",5,4,"ee",-1,0,-1,0,154,154,"C-155","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0155-08",3,"Yo soy quien puedo ofrecerte\nEl culto de un puro amor,\nYo soy quien tengo valor\nDe venir a tu presencia,\nYo soy quien sin resistencia\nTe entregó su corazón.",3,1,0,29,"TU ERES LA REINA Y SEÑORA",9,6,"o",-1,0,-1,0,155,155,"C-155","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0155-09",3,"Tú eres del jardín la planta\nQue cultiva el jardinero\nTú eres, hermoso lucero,\nQue mi espíritu levanta\nTú eres rayo que quebranta\nDe los astros el fulgor,\nTú eres con todo primor\nDe la fortuna el dechado,\nTú eres quien más ha inspirado\nEl más purísimo amor.",3,1,0,29,"TU ERES LA REINA Y SEÑORA",18,10,"o",72,0,-1,0,155,155,"C-155","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0155-10",3,"Yo soy quien con voz segura\nTe declaro mi pasión,\nYo soy quien sin presunción\nAdora tanta hermosura,\nYo soy quien amor te jura\nCon ardiente frenesí,\nYo soy quien te pide el sí\nCon un cariño profundo,\nYo soy quien en este mundo\nSe muere de amor por tí.",3,1,0,29,"TU ERES LA REINA Y SEÑORA",18,10,"i",23,0,-1,0,155,155,"C-155","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0157-01",3,"Tú tienes, dulce paloma,\nLas reliquias de la vida\nTienes en la sien ceñida\nLa palma triunfal que aroma.\nTienes de viola el aroma\nEncantador y atrayente,\nTienes del amor ausente\nLa decidida constancia\nY tienes perseverancia\nPara amar sinceramente.",3,1,0,29,"TU TIENES DULCE PALOMA",18,10,"ee",15,0,-1,0,155,155,"C-157","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0157-02",3,"Yo tengo tan sólo espinas\nSembradas en mi camino,\nTengo como el peregrino\nNoches de triste neblina,\nTengo el alma que se inclina\nA la mansión infinita,\nTengo la desdicha escrita\nSobre mi destino cruel\nPero tengo un ángel fiel\nQue lo eres tú, Margarita.",3,1,0,29,"TU TIENES DULCE PALOMA",18,10,"ia",50,0,-1,0,155,155,"C-157","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0157-03",3,"Tú tienes divinidades\nEn tu sagrada persona\nY tienes una corona\nDe tus finas cualidades.\nTienes mil felicidades\nReservadas para mí,\nTienes de la frase, sí,\nLo más bello que ella encierra\nY tienes sobre la tierra\nMí querer con frenesí.",3,1,0,29,"TU TIENES DULCE PALOMA",18,10,"i",23,0,-1,0,155,155,"C-157","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0157-04",3,"Yo tengo mis pensamientos\nDepositados en tí\nTengo desde que te ví\nAlivio en mis sufrimientos,\nTengo preciosos momentos\nAunque tengo que sufrir\nTengo el placer de decir\nQue tú eres mi dulce Edén\nY tengo por tí, mi bien,\nUn cariño hasta morir.",3,1,0,29,"TU TIENES DULCE PALOMA",18,10,"i",157,0,-1,0,155,155,"C-157","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0158-01",3,"Tuyo seré mientras viva\nSi prometes el quererme\nDando fin a mi desdicha\nSi dichoso quieres verme.",3,1,0,29,"TUYO SERÉ MIENTRAS VIVA",0,4,"ee",245,0,-1,0,155,155,"C-158","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0158-02",3,"Siempre que tu amor destierre\nDe sí toda acción esquiva\nAunque todo se me oponga\nTuyo seré mientras viva.",3,1,0,29,"TUYO SERÉ MIENTRAS VIVA",0,4,"ia",53,0,-1,0,155,155,"C-158","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0158-03",3,"Nada importa que la suerte\nY el olvido quieran verme\nDistante de tu deidad\nSi prometes el quererme.",3,1,0,29,"TUYO SERÉ MIENTRAS VIVA",0,4,"ee",245,0,-1,0,155,155,"C-158","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0158-04",3,"Sólo el instante que os ví\nConocí lo que era dicha\nY a ser dichoso pasé\nDando fin a mi desdicha.",3,1,0,29,"TUYO SERÉ MIENTRAS VIVA",0,4,"ia",357,0,-1,0,155,155,"C-158","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0158-05",3,"No quieras, cielo del alma,\nDejar de corresponderme\nNi menos dejarme intentes\nSi dichoso quieres verme.",3,1,0,29,"TUYO SERÉ MIENTRAS VIVA",0,4,"ee",-1,0,-1,0,155,155,"C-158","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0159-01",3,"Ya me tiene confundido\nEsta mi gran aflicción\nAl ver que me es imposible\nQue rinda tu corazón.",3,1,0,29,"YA ME TIENE CONFUND",0,4,"o",31,0,-1,0,156,156,"C-159","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0159-03",3,"Si en un acaso gozara\nTu voluntad generosa\nFueras la planta frondosa\nEn quien yo me deleitara.\nEsto es lo que se declara\nEsta es mi única intención.\nQuisiera sin reflexión\nSer tu verdadero dueño\nLo que me pone al empeño\nEsta mi gran aflicción.",3,1,0,29,"YA ME TIENE CONFUND",18,10,"o",31,0,-1,0,156,156,"C-159","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0159-04",3,"No desprecies mis finezas\nY mi afecto verdadero,\nYo pondré el mayor esmero\nEn adorar tu belleza.\nEn mí verás la firmeza\nComo fuera más posible\nQuisiera ser más visible\nAl fin en mi pensamiento\nPero otra vez me arrepiento\nAl ver que me es imposible.",3,1,0,29,"YA ME TIENE CONFUND",18,10,"ie",259,0,-1,0,156,156,"C-159","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0159-05",3,"Y si acaso yo alcanzara\nConseguir lo que deseo\nSerías mi único recreo\nMi cielo, mi luna clara\nY espejo donde mirara\nReflejada mi pasión.\nNo tienes comparación\nY este mi querer es tanto\nQue te pido, dulce encanto,\nQue rindas tu corazón.",3,1,0,29,"YA ME TIENE CONFUND",18,10,"o",31,0,-1,0,156,156,"C-159","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0161-03",3,"¿Cuál es aquel que no yerra?\nY nadie de esto se asombre,\nEl error fué para el hombre,\nEn ésta y en otras tierras,\nY es tal la maldad que encierra,\nQue a cada instante yo observo\nQue les fastidia si duermo,\nLes fastidia el verme andar,\nY en fin, para caminar\nVarias veces me prevengo.",3,1,0,30,"A PAGAR CON UNA AUSENCIA",18,10,"eo",-1,0,-1,0,158,158,"C-161","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0161-04",3,"Al verme tan criminoso\nTal vez llegara a pensar,\nQue en algún otro lugar,\nNo serán escrupulosos,\nQuedarán todos gustosos,\nNo me verán los mirones,\nNo habrá más murmuraciones\nY dirán esos señores:\nNo son tanto los errores,\nMás son las almiraciones.",3,1,0,30,"A PAGAR CON UNA AUSENCIA",18,10,"oe",-1,0,-1,0,158,158,"C-161","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0162-01",3,"¡Ay, cielos! ¿Dónde estará?\n¿Vivirá, acaso, mi bien?\n¡Mis ojos ya no la ven!\n¡Muerta ya 'quizás será!",3,1,0,30,"¡AY, CIELOS; DONDE ESTARA!",11,4,"a",9,0,-1,0,158,158,"C-162","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0162-02",3,"Avecilla que al surcar\nEl aire con rapidez\n¿Habéisla visto tal vez\nLa has oído suspirar?\n¡Mas, ay; que vuestro callar\nEs cruel anuncio que ya\nEs muerta y ay, ¿quién podrá\nAsegurarlo de cierto?\nY si es factible que ha muerto,\n¡Ay, cielos! ¿Dónde estará?",3,1,0,30,"¡AY, CIELOS; DONDE ESTARA!",18,10,"a",9,0,-1,0,158,159,"C-162","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0162-03",3,"Decidme prados frondosos,\nQue mudos testigos fuísteis\nDe ocasiones que la vísteis\nEn mis brazos amorosos,\nParad, ríos caudalosos,\nVuestras corrientes detén,\nPara responder también,\n¿Vísteis a mi dulce encanto?\nO si padeciendo tanto\n¿Vivirá, acaso, mi bien?",3,1,0,30,"¡AY, CIELOS; DONDE ESTARA!",18,10,"e",242,0,-1,0,159,159,"C-162","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0162-04",3,"¿A dónde hallaré consuelo\nSi montes, valles y sierras,\nAves, peces, ríos, fieras,\nMudos aumentan mi duelo?\nYa me miro en este suelo\nSin mi más preciado bien,\n¡Oh, muerte: cortad también\nMi vida y toda mi gloria\n¡Acabadme; oh, cruel memoria!\n¡Mis ojos ya no la ven!",3,1,0,30,"¡AY, CIELOS; DONDE ESTARA!",18,10,"e",242,0,-1,0,159,159,"C-162","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0162-05",3,"De bosques, terribles fieras,\nDecidme si en las entrañas\nEn las breñas o montañas\nO cielos, valles o selvas,\nHay señales de que infiera\nQue allí oculta se hallará,\nY que viviendo podrá\nExistir sin su recreo,\nNo, no, fortuna, no creo,\n¡Muerta ya quizás será!",3,1,0,30,"¡AY, CIELOS; DONDE ESTARA!",18,10,"a",9,0,-1,0,159,159,"C-162","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0163-01",3,"¡Ay, fortuna! ¿qué te hiciste?\nConsuelo de mis tormentos,\nVivo en tanto desacierto\n¿Qué, no consuelas a un triste?",3,1,0,30,"¡AY FORTUNA! ¿QUE TE HICISTE?",5,4,"ie",153,0,-1,0,159,159,"C-163","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0163-02",3,"Se aumenta mi desconsuelo\nSin alivio ni esperanza,\nUnas con otras se alcanzan\nLas penas sin un consuelo;\nCompadezcansé los cielos\nDe las penas que me asisten,\nVivo tan penoso y triste\nEn los brazos de la muerte,\nNo hay placer donde no hay suerte\n¡Ay, fortuna! ¿qué te hiciste?",3,1,0,30,"¡AY FORTUNA! ¿QUE TE HICISTE?",18,10,"ie",153,0,-1,0,159,159,"C-163","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0163-03",3,"En equilibrio me tienen\nMis desgracias tan fatales,\nPorque tormentos y males\nSólo a mi presencia vienen,\nY conmigo se entretienen\nLos martirios más violentos,\nVes que mis padecimientos\nNo tienen fin, ni tendrán,\nSólo la muerte será\nConsuelo de mis tormentos.",3,1,0,30,"¡AY FORTUNA! ¿QUE TE HICISTE?",18,10,"eo",234,0,-1,0,159,159,"C-163","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0163-04",3,"Las glorias lejos de mí,\nLos placeres más distantes,\nY mirando a cada instante,\nMi suerte tan infeliz.",3,1,0,30,"¡AY FORTUNA! ¿QUE TE HICISTE?",5,4,"i",-1,0,-1,0,159,159,"C-163","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0164-05",3,"por mí y yo por vos\nsilencio descansamos,\naún a los ojos digamos,\npadecemos los dos.",3,1,0,30,"¡AY SUSPIRO, SOLO VOS!",11,4,"o",87,0,-1,0,160,160,"C-164","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0165-01",3,"¡Ay, suspiro, sólo vos\nComo que del pecho sales,\nSabes los acerbos males\nQue padecemos los dos.",3,1,0,30,";AY SUSPIRO, SOLO VOS!",11,4,"o",87,0,-1,0,160,160,"C-165","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0165-02",3,"Bien sabes que vivo ausente\nDe mi idolatrado hechizo,\nPorque el infortunio quiso\nQue padezca yo cruelmente,\nSabes que no hay accidente\nMas terrible ni veloz,\nNi incendio más atroz\nQue el querer y no gozar\n¿Quién lo puede remediar?\n¡Ay, suspiro, sólo vos!",3,1,0,30,";AY SUSPIRO, SOLO VOS!",18,10,"o",87,0,-1,0,160,160,"C-165","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0165-03",3,"Bien sabes cómo el amor\nCuando se le ausenta el dueño,\nLe adora con más empeño,\nY siente mayor dolor,\nYo también a mi favor,\nNo tengo sino crueldades,\nAsí, suspiro., no tardes\nDe apresurar tu partida,\nDale cuenta de mi vida\nComo que del pecho sales.",3,1,0,30,";AY SUSPIRO, SOLO VOS!",18,10,"ae",-1,0,-1,0,160,160,"C-165","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0165-04",3,"También sabes el cuidado\nQue tengo de obligación,\nPorque tengo una pasión\nQue ya me tiene privado;\nAsí dile que te he enviado\nA que le cuentes mis ayes,\nY todas las impiedades,\nQue afligen mi corazón,\nPorque tú con más razón\nSabes lo sacerbos males.",3,1,0,30,";AY SUSPIRO, SOLO VOS!",18,10,"ae",-1,0,-1,0,160,160,"C-165","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0165-05",3,"Dile que no tengo instante\nQue no piense en su hermosura\nQue sintiendo la amargura\nDe contemplarla distante,\nSiempre soy su fino amante\nFirme acero y fiel reloj,",3,1,0,30,";AY SUSPIRO, SOLO VOS!",9,6,"o",-1,0,-1,0,160,160,"C-165","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0165-06",3,"Y tan sujeto a su voz\nAunque ausente de su cielo,\nPero que tengo el consuelo\nQue padecemos los dos.",3,1,0,30,";AY SUSPIRO, SOLO VOS!",11,4,"o",87,0,-1,0,161,161,"C-165","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0166-01",3,"¡Ay, vivir y cómo cansas\nEn un pecho lastimado!\n¡Ay muerte, qué perezosa\nVienes para un desdichado!",3,1,0,30,"AY VIVIR Y COMO CANSAS",0,4,"ao",14,0,-1,0,161,161,"C-166","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0166-02",3,"¡Ay parca, que aunque te busco\nDiligente no te encuentro!\n¡Ay que impías que te muestras\nEn dilatarme el tormento!",3,1,0,30,"AY VIVIR Y COMO CANSAS",0,4,"eo",-1,0,-1,0,161,161,"C-166","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0166-03",3,"¡Ay infeliz y cruel hado\nNo huya de mi tu rigor!\nQue aunque el morir es sensible\n¡Ay vivir que es más dolor!",3,1,0,30,"AY VIVIR Y COMO CANSAS",0,4,"o",72,0,-1,0,161,161,"C-166","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0166-04",3,"Vengan tropas de tormentos\nQue para mí no hay martirio\nPorque el corazón que tengo\nEs más fuerte que un castillo.",3,1,0,30,"AY VIVIR Y COMO CANSAS",0,4,"io",-1,0,-1,0,161,161,"C-166","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0166-05",3,"Más, ¡Ay dolor! — ¿Es posible\nQue en un pecho como el mío\nQuepan desesperaciones\nCuando no tengo el consuelo?",3,1,0,30,"AY VIVIR Y COMO CANSAS",5,4,"eo",-1,0,-1,0,161,161,"C-166","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0167-01",3,"Blanca paloma, que el nido\nDejastes abandonado,\nPorque estaba envenenado\nCon mi aliento maldecido.\nPerdón mil veces te pido\nSi amándote con ternura\nYo labré tu desventura\nQue es mi más íntimo ardor,\nSin comprender que mi amor\nManchaba tu frente pura.",3,1,0,30,"BLANCA PALOMA QUE EL NIDO",18,10,"ua",17,0,-1,0,161,161,"C-167","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0167-02",3,"Hoy que errante sin consuelo\nMarcando mi rumbo incierto\nSólo encuentro en el desierto,\nLas luminarias del cielo.\nY en mi constante desvelo,\nPor tu recuerdo querido,\nHasta este sitio he venido\nQue guarda tanta ventura,\nBuscando tu imagen pura\nEn tu solitario nido.",3,1,0,30,"BLANCA PALOMA QUE EL NIDO",18,10,"io",101,0,-1,0,161,161,"C-167","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0168-01",3,"Bajo de un coposo pino\nLlorando me lamentaba,\nY el pino como era tierno\nDe verme llorar lloraba.",3,1,0,30,"BAJO DE UN COPOSO PINO",0,4,"aa",28,0,-1,0,161,161,"C-168","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0168-02",3,"Al mirar mi situación\nEn tan terrible destino,\nSe me partía el corazón\nBajo de un coposo pino.",3,1,0,30,"BAJO DE UN COPOSO PINO",1,4,"io",199,0,-1,0,161,161,"C-168","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0168-03",3,"Triste, confuso, afligido,\nTriste me desesperaba,\nAl mirar mi cruel destino\nLlorando me lamentaba.",3,1,0,30,"BAJO DE UN COPOSO PINO",0,4,"aa",28,0,-1,0,161,161,"C-168","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0168-04",3,"Todas las penas venían\nA hacer mi pecho un infierno,\nHasta los pastos gemían\nY el pino como era tierno.",3,1,0,30,"BAJO DE UN COPOSO PINO",1,4,"eo",225,0,-1,0,161,161,"C-168","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0168-05",3,"Viendo mi cruel sentimiento\nEste árbol se deshojaba,\nY hasta en sus ramas, el viento\nDe verme llorar lloraba.",3,1,0,30,"BAJO DE UN COPOSO PINO",1,4,"aa",28,0,-1,0,161,161,"C-168","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0169-01",3,"Bajo de un coposo pino,\nLlorando me lamentaba,\nEl pino como era tierno,\nDe verme llorar, lloraba.",3,1,0,30,"BAJO DE UN COPOSO PINO",0,4,"aa",28,0,-1,0,161,161,"C-169","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0170-02",3,"¡Corazón! ¿Por qué estás triste?\n¿En qué tenis que pensar?\nHabiendo nacido libre\n¿Quién te mandó cautivar?\n¡Calla y no llores\nTriste corazón!\netc.",3,1,0,30,"GUAINITO",4,7,"e",-1,0,-1,0,162,162,"C-170","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0170-03",3,"¡Levanta, corazón mío!\n¿Para cuándo es el valor\nSi no es para demostrarlo\nCuando se ofrece ocasión?\n¡Calla y no llores\nTriste corazón!\netc.",3,1,0,30,"GUAINITO",4,7,"e",-1,0,-1,0,162,162,"C-170","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0170-04",3,"Un corazón como el mío\nNo lo ha de tener cualquiera.\nCorazón que sufre y calla\nNo se encuentra donde quiera.\n¡Calla y no llores\nTriste corazón!\netc.",3,1,0,30,"GUAINITO",4,7,"e",-1,0,-1,0,162,162,"C-170","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0170-05",3,"¡Corazón, en tu tormento\nVives tan disimulado\nCualesquiera que te mira\nPresume que estás callado!\n¡Calla y no llores\nTriste corazón!\netc.",3,1,0,30,"GUAINITO",4,7,"e",-1,0,-1,0,162,162,"C-170","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0170-06",3,"No hay corazón como el mío\nPara sufrir una pena,\nAma y sufre su martirio\nAl que su amor lo encadena...\n¡Calla y no llores\nTriste corazón!\netc.",3,1,0,30,"GUAINITO",4,7,"e",-1,0,-1,0,162,162,"C-170","",0,"","","",9,0,0,[],""],["carrizo_salta-nc0170-07",3,"¡Corazón! ¿Qué es de tu brío?\n¿Qué es de la paz que anhelaste?\nCon tu loco desvarío\nTú mismo, tu mal labraste.\n¡Calla y no llores\nTriste corazón!\netc.",3,1,0,30,"GUAINITO",4,7,"e",-1,0,-1,0,162,162,"C-170","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0170-08",3,"Tú mismo tu mal labraste\nSin escuchar la razón\nLlora en silencio tus penas\nSufre y calla corazón.",3,1,0,30,"GUAINITO",0,4,"o",31,0,-1,0,163,163,"C-170","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0170-09",3,"¡Calla y no llores\nTriste corazón!\nCon el llanto no se apaga\nEl ardor de una pasión",3,1,0,30,"GUAINITO",0,4,"o",31,0,-1,0,163,163,"C-170","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0172-01",3,"Crié dormido una ilusión\nY al despertar la perdí,\nY al perderla, qué era, ví,\nDelirios del corazón.",3,1,0,30,"CRIE DORMIDO UNA ILUSIÓN",11,4,"o",31,0,-1,0,163,163,"C-172","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0172-02",3,"Quise gozar y aspiré\nLas tristes flores del suelo,\nMás, eran flores de duelo,\nY en su cáliz llanto hallé.",3,1,0,30,"CRIE DORMIDO UNA ILUSIÓN",11,4,"e",77,0,-1,0,163,163,"C-172","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0172-03",3,"Ayer ventura, hoy dolor,\nIncertidumbre mañana,\nTal es de la vida humana\nEl cuadro desgarrador.",3,1,0,30,"CRIE DORMIDO UNA ILUSIÓN",11,4,"o",72,0,-1,0,163,163,"C-172","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0172-04",3,"Ayer sueños seductores,\nHoy fatales desengaños,\nY vienen y van los años,\nCuál nacen y mueren flores.",3,1,0,30,"CRIE DORMIDO UNA ILUSIÓN",11,4,"oe",5,0,-1,0,163,163,"C-172","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0173-01",3,"De las desgracias rodeado\nEn este mundo he nacido,\nParece que maldecido,\nDios al mundo me ha lanzado.\nComo un hombre despreciado,\nNo hallo placer ni alegría;\nPara mí no hay sol ni día,\nLa noche me da temor,.\nTodo para mí es dolor,\n¿Qué estrella me alumbraría?",3,1,0,30,"DE LAS DESGRACIAS RODEADO",18,10,"ia",0,0,-1,0,163,163,"C-173","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0173-02",3,"Es tanto que mis amigos\nHan entrado a aborrecerme,\nQue ni cerca quieren verme,\nSin que les haya ofendido,\nY de este modo abatido,",3,1,0,30,"DE LAS DESGRACIAS RODEADO",7,5,"io",101,0,-1,0,163,163,"C-173","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0173-03",3,"¡Cuán amargos son mis días!\nViendo la desgracia mía\nMe lamento sin cesar,\n¡Oh, qué destino fatal!\n¿Qué estrella me alumbraría?",3,1,0,30,"DE LAS DESGRACIAS RODEADO",7,5,"ia",0,0,-1,0,164,164,"C-173","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0174-02",3,")ónde estará el bien que adoro?\niy cielos, qué desespero!\niuién me lo tendrá escondido\naquel hermoso lucero?",3,1,0,30,"DE LAS RAMAS DE UNA ROSA",0,4,"eo",38,0,-1,0,164,164,"C-174","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0174-08",3,"Sólo la cama en que duermo\nSe compadece de mí,\nPorque en ella gimo y lloro,\nDesde que mi bien perdí.",3,1,0,30,"DE LAS RAMAS DE UNA ROSA",0,4,"i",23,0,-1,0,164,164,"C-174","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0174-09",3,"Como fino apasionado\nTe dictaré mi dolor\nSi he de vivir padeciendo\nMorirme será mejor.",3,1,0,30,"DE LAS RAMAS DE UNA ROSA",0,4,"o",72,0,-1,0,164,164,"C-174","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0174-10",3,"Felices fueron mis brazos\nQue se abrieron para tí\nY mis labios que supieron\nBesarte con frenesí.",3,1,0,30,"DE LAS RAMAS DE UNA ROSA",0,4,"i",23,0,-1,0,164,164,"C-174","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0174-11",3,"Si ya no te vuelvo a ver\nO para siempre te pierdo,\nSi muere en tu alma el cariño,\nQue al menos viva el recuerdo.",3,1,0,30,"DE LAS RAMAS DE UNA ROSA",0,4,"eo",350,0,-1,0,164,164,"C-174","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0175-01",3,"Después de tanto penar\nCon una pasión tan fuerte,\nPor fin me has de dar la muerte\nSi no te puedo olvidar.\n¿Para qué ingrata buscar\nAlivio a mi mal creciente\nSi has de ser indiferente\nCon quién tanto te ha querido?\nYa no hay más ley que el olvido\nContra tu amor inclemente.",3,1,0,30,"DESPUÉS DE TANTO PENAR",18,10,"ee",15,0,-1,0,164,164,"C-175","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0175-02",3,"Ya no queda otro consuelo\nPara un infeliz amante\nSi una mujer inconstante,\nQue tan mal paga su anhelo,\nY si es castigo del cielo\nPorque te he querido tanto,\nJusto es que vierta mi lanto,\nDe mis desdenes heridos\nHasta que caigan rendidos\nAl peso de un desencanto.",3,1,0,30,"DESPUÉS DE TANTO PENAR",18,10,"ao",30,0,-1,0,164,164,"C-175","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0175-03",3,"Dejaré el tiempo pasar\nBuscaré en la ausencia calma,\nQue las heridas del alma\nLas suele el tiempo curar,\nSi no te puedo olvidar,\nVolveré ingrata a quererte,\nHasta que por fin la muerte\nPonga término a mis penas,\nYa que tan cruel me encadenas\nA vivir contra la suerte.",3,1,0,30,"DESPUÉS DE TANTO PENAR",18,10,"ee",134,0,-1,0,164,165,"C-175","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0175-a-02",3,"Dejaré el tiempo pasar,\nBuscaré en la ausencia calma\nQue las heridas del alma,\nLas suele el tiempo curar.\nSi no te puedo olvidar\nVolveré ingrata a quererte,\nHasta que por fin la muerte\nPonga término a mis penas,\nYa que tan cruel me encadenas\nA vivir contra mi suerte.",3,1,0,30,"DESPUÉS DE TANTO PENAR",18,10,"ee",134,0,-1,0,165,165,"C-175-a","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0176-01",3,"De una torre de placeres\nDe aquella amena mansión\nA las bajezas más tristes\nMe derribó una pasión.",3,1,0,30,"DE UNA TORRE DE PLACERES",0,4,"o",31,0,-1,0,165,165,"C-176","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0176-02",3,"Llorando estoy sin consuelo\nEsta mi infelicidad,\nSirviéndome de ejemplar\nLa vista del alto cielo,\nMi nota está por el suelo\nMiren en sus manos, seres,\nAsí hombres como mujeres\nNo se vean como yo,\nQue una insuerte me volteó\nDe una torre de placeres.",3,1,0,30,"DE UNA TORRE DE PLACERES",18,10,"ee",55,0,-1,0,165,165,"C-176","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0176-03",3,"¿Dónde estuvo mi advertencia\nQue no se presentó a tiempo\nY daba el consentimiento\nA tan bárbara indolencia?\n¿Cómo dobló mi conciencia\nO mi buena reflexión?\n¿Dónde estuvo mi razón,\nO se halló fuera de mí\nQue sin motivo salí\nDe aquella amena mansión?",3,1,0,30,"DE UNA TORRE DE PLACERES",18,10,"o",31,0,-1,0,165,165,"C-176","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0176-04",3,"Mi consorte quedó herido\nLlorando gotas de sangre\nY mis hijitos sin madre\n¿Qué es lo que me ha sucedido?\nVenga, sobre mí el castigo,\nQuizás ¡Oh cielo! ¿no viste?\n¡Fortuna! ¿Dónde te fuíste\nQue no has tenido piedad\nQue me dejastes bajar\nA las bajezas más tristes?",3,1,0,30,"DE UNA TORRE DE PLACERES",18,10,"ie",-1,0,-1,0,165,165,"C-176","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0176-05",3,"Adán y Eva desterrados\nDel Paraíso Terrenal\nEllos lloraban su mal\nHasta verse perdonados,\nNo fueron desesperados\nHasta que hubo redención\nQue una buena reflexión\nBorra del pecado el sello\nPero a mí lo mismo que a ellos\nMe derribó mi pasión.",3,1,0,30,"DE UNA TORRE DE PLACERES",18,10,"o",31,0,-1,0,165,165,"C-176","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0177-01",3,"De verme tan abatido\nTriste, afligido y penoso\nLlorando el tiempo perdido\nPor bribón y escandaloso.",3,1,0,30,"DE VERME TAN ABATIDO",1,4,"oo",160,0,-1,0,165,165,"C-177","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0177-02",3,"Cuando anduve en mi privanza\nTenía infinitos amigos\nHoy de mi mal son testigos\n¡Qué ingratitud, qué mudanza!\nEn los que tenía confianza\nCuando me vide afligido\nNi siquiera de fingido\nNinguno se me ofertaba,\nHasta el habla me negaban\nDe verme tan abatido.",3,1,0,30,"DE VERME TAN ABATIDO",18,10,"io",101,0,-1,0,165,165,"C-177","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0178-05",3,"Si lo busco entre mis ansias\nEn mi pecho no lo encuentro,\nPorque días ha que vive,\nSin alma este triste cuerpo.",3,1,0,30,"DONDE ESTA EL BIEN DE MI VIDA",0,4,"eo",-1,0,-1,0,166,166,"C-178","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0179-01",3,"¿Dónde me llevas fortuna\nDe esta manera rodando\nSin saber lo que he de ser\nDe mi triste vida al cabo?",3,1,0,30,"¿DONDE ME LLEVAS FORTUNA?",0,4,"ao",-1,0,-1,0,166,166,"C-179","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0179-02",3,"Provincias peregrinando\nPasando dos mil desvelos,\nEntre calores y hielos,\nAjenas caras mirando,\nDigan todos ponderando\nMis desdichas de una en una\nComo a mi suerte importunan\nDesdenes y desaciertos,\nPero, decidme de cierto:\n¿Dónde me llevas fortuna?",3,1,0,30,"¿DONDE ME LLEVAS FORTUNA?",18,10,"ua",-1,0,-1,0,166,166,"C-179","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0179-03",3,"¿De qué me sirve la pluma\nDe qué me sirve el saber\nSi hoy día me llego a ver\nEn una desdicha suma?\nQue todo en mí se consuma\nAl andar peregrinando,\nPaguen mis ojos llorando\nHasta que venga la muerte,\nSi me ha de tener la suerte\nDe esta manera rodando.",3,1,0,30,"¿DONDE ME LLEVAS FORTUNA?",18,10,"ao",33,0,-1,0,166,166,"C-179","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0179-04",3,"Si en un tiempo yo hacía alarde\nEstando en mi casa llena,\nHoy me veo en tierra ajena\nCareciendo de mi madre.\nSin árbol, sombra, ni padre\nNi hermanos para mi ver.\nMe dispongo a padecer,\nImitando a Jeremías\nSuspirando noche y día\nSin saber lo que he de ser.",3,1,0,30,"¿DONDE ME LLEVAS FORTUNA?",18,10,"e",20,0,-1,0,166,166,"C-179","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0179-05",3,"Madres, las que tengan hijos\nVarones para consuelo,\nAlcen sus ojos al cielo\nPidan que los lleven chicos,\nVerán afanes prolijos\nDe las miserias esclavos.\nEsto les digo y acabo\nCon lágrimas de mis ojos\nPara cantar los despojos\nDe mi triste vida al cabo.",3,1,0,30,"¿DONDE ME LLEVAS FORTUNA?",18,10,"ao",358,0,-1,0,166,167,"C-179","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0180-01",3,"Dos corazones amantes,\nAusentes por precisión,\nLloraban su división\nLas horas y los instantes.",3,1,0,30,"DOS CORAZONES AMANTES",11,4,"ae",262,0,-1,0,167,167,"C-180","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0180-02",3,"El uno clamaba al cielo\nLlorando su desventura,\nQue le vuelva por ventura\nA su idolatrado dueño.",3,1,0,30,"DOS CORAZONES AMANTES",5,4,"eo",-1,0,-1,0,167,167,"C-180","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0180-03",3,"Mas, el otro vacilando\nPenoso y triste decía:\n¿A dónde estás, vida mía,\nQue por tí vivo penando?",3,1,0,30,"DOS CORAZONES AMANTES",11,4,"ao",33,0,-1,0,167,167,"C-180","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0180-04",3,"Las lágrimas lastimosas\nQue a millares derramaban,\nMares y mares formaban,\nY también islas fragosas.",3,1,0,30,"DOS CORAZONES AMANTES",11,4,"oa",61,0,-1,0,167,167,"C-180","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0180-05",3,"Al fin los dos desdichados\nBuscan por dicha la muerte,\nPorque sienten de tal suerte\nTener vida separada.",3,1,0,30,"DOS CORAZONES AMANTES",5,4,"aa",-1,0,-1,0,167,167,"C-180","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-01",3,"El jilguero y la calandria\nEran dos que se querían\nTemerosos de un desprecio\nNinguno se descubría.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"ia",-1,0,-1,0,167,167,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-02",3,"Al cabo de tanto andar\nLe dijo el jilguero un día\nQue pretendía ser su amante\nQue por ella se moría.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"ia",0,0,-1,0,167,167,"C-181","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0181-03",3,"Estaban los dos sentados\nCuando el cazador los vió,\nY del susto que tuvieron\nSe separaron los dos.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"o",-1,0,-1,0,167,167,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-04",3,"Quedaron los dos perdidos\nEn la senda del amor,\nPero quedan a juntarse\nPara ir al nido los dos.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"o",-1,0,-1,0,167,167,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-05",3,"Llora triste en la montaña\nEl amoroso jilguero,\nCuando lo encontró una jaula\nDonde cayó prisionero.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"eo",38,0,-1,0,167,167,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-06",3,"¿De qué sirve mi existencia?\n¿De qué sirve haber nacido\nSi me he de ver para siempre\nEn la jaula sumergido?",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"io",101,0,-1,0,167,167,"C-181","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0181-07",3,"Más vale me hubiera muerto\nAntes de haberte querido.\nSi no hi de lograr mi intento\nNo te hubiera conocido.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"io",101,0,-1,0,167,167,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-08",3,"Estando triste el jilguero,\nEn medio de su prisión\nSe presentó la calandria\nA cantarle su pasión.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"o",31,0,-1,0,167,167,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-09",3,"—Decime juiguero amante\nTe pregunto por favor\nQue me interesa saber\nLa causa de tu prisión.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"o",-1,0,-1,0,167,167,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-10",3,"—Déjame pasar trabajos\nQue yo me encuentro conforme\nPorque sé que los trabajos\nSe hicieron para los hombres.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"oe",-1,0,-1,0,167,167,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-11",3,"—Oye jiuguerillo amante,\nTe pregunto por favor,\nMira que yo soy constante\nY no olvido nuestro amor.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",1,4,"o",72,0,-1,0,167,167,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-12",3,"—Voy a avisarle señora\nYa que tanto así me apura.\nLa causa de mi prisión\nEs por amar su hermosura.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"ua",17,0,-1,0,167,167,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-13",3,"-Lindo jiuguerillo amante\nYa me voy a retirar,\nVoy a mandar un enviado\nQue te ponga en libertad.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"a",-1,0,-1,0,168,168,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0181-14",3,"También debo prevenirte\nLo que usted puede dudar\nSépase que soy casada\nSoy mujer del cardenal.",3,1,0,30,"EL JILGUERO Y LA CALANDRIA",0,4,"a",-1,0,-1,0,168,168,"C-181","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0182-03",3,"Trabajó mi herido pecho\n)ía y noche sin cesar,\n(no pudiendo ablandar\nJoraba en mi triste lecho,\nJos mil imposibles he hecho\nÍL mil desdichas expuesto,\nfasta que a mi amor discreto\nVenció mi grande porfía.\nPor ver lo que producía\nSembré semillas de afectos.",3,1,0,30,"EN LAS TIERRAS DE CUPIDO",18,10,"eo",-1,0,-1,0,168,168,"C-182","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0182-05",3,"Al tiempo de cosechar\nDevisé por la ribera,\nY la ví a mi sementera\nPerdida por la mitad,\nTriste me puse a llorar\nDiciendo: ¡Cielo! ¿Qué es esto?\n¿Por qué he perdido tan presto\nFlores que han sido divinas?\nAlgunas dieron espinas\nY otras un amor perfecto.",3,1,0,30,"EN LAS TIERRAS DE CUPIDO",18,10,"eo",-1,0,-1,0,168,168,"C-182","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0183-01",3,"En mi triste situación\nNo hay parientes ni hay amigos,\nYa todos se han olvidado\nDe un infeliz abatido.",3,1,0,30,"EN MI TRISTE SITUACIÓN",0,4,"io",-1,0,-1,0,168,168,"C-183","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0183-02",3,"Hoy para mí no hay placer\nYa mis glorias dieron fin,\nTan sólo reinan en mí\nDesdichas y padecer.\nNo hay hermanas, no hay mujer\nEn la presente ocasión,\nLlora sangre el corazón\nAl verse tan mal pagado,\nDe todos abandonado\nEn mi triste situación.",3,1,0,30,"EN MI TRISTE SITUACIÓN",18,10,"o",31,0,-1,0,168,168,"C-183","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0183-03",3,"Y tan solamente el cielo\nEn medio de mi tormento,\nOye mis tristes lamentos,\nEl es mi único consuelo.\nPara mi mayor desvelo\nMe parece haber venido,\nMirándome confundido\nEn mis penas tan fatales.\nEn medio de tantos males\nNo hay parientes, no hay amigos.",3,1,0,30,"EN MI TRISTE SITUACIÓN",18,10,"io",-1,0,-1,0,168,168,"C-183","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0183-04",3,"En tiempos que yo gozaba\nDe distinción y cariño\nJamás me había persuadido\nQue todo fuera supuesto;\nConvencido de todo esto\nMi dolor se ha acrecentado,\nY de hora en hora he llorado\nMi desgracia sin cesar;\nYa no tengo qué esperar,\nYa todos se han olvidado.",3,1,0,30,"EN MI TRISTE SITUACIÓN",18,10,"ao",14,0,-1,0,168,169,"C-183","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0183-05",3,"Hoy me hallo en tierras ajenas\nSin tener ningún amparo,\nRodeado de los extraños\nEn medio de tantas penas,\nCautivo estoy sin cadenas\nSumergido en triste olvido,\nDe todos desconocidos\nEn este gran precipio.\nPero ¿quién ha de hacer juicio\nDe un infeliz abatido?",3,1,0,30,"EN MI TRISTE SITUACIÓN",18,10,"io",-1,0,-1,0,169,169,"C-183","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0184-01",3,"En otro tiempo existí\nEn mis glorias presumiendo,\nAhora vivo muriendo\nDesde que mi bien perdí.",3,1,0,30,"EN OTRO TIEMPO EXISTÍ",11,4,"i",23,0,-1,0,169,169,"C-184","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0184-02",3,"Cuando la noche sombría\nExtiende su obscuro velo\nAnsiosa remonta el vuelo,\nLa infeliz memoria mía.\nSe junta en mi fantasía\nEl dulce bien que perdí\nEntonces lloro ¡ay de mí!\nSu ausencia cual desgraciado\nRecordando que a su lado\nEn otro tiempo existí.",3,1,0,30,"EN OTRO TIEMPO EXISTÍ",18,10,"i",23,0,-1,0,169,169,"C-184","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0184-03",3,"Vuela el pensamiento ansioso\nTras la perdida ilusión,\nRecordando la ocasión\nQue fuí el mortal más dichoso,\nMe acuerdo que temeroso\nVi su corazón latiendo\nY dijo el mío: ya entiendo,\nAmor nos echó su lazo.\nY la estrechaba en mis brazos\nEn mis glorias presumiendo.",3,1,0,30,"EN OTRO TIEMPO EXISTÍ",18,10,"eo",52,0,-1,0,169,169,"C-184","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0184-04",3,"Mas ¡ay! qué poco duró\nAquel tan feliz momento.\nDespués sucedió el tormento\nQue el destino ocasionó,",3,1,0,30,"EN OTRO TIEMPO EXISTÍ",11,4,"o",2,0,-1,0,169,169,"C-184","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0184-05",3,"Su imagen me arrebató\nY desde entonces sufriendo,\nVoy mis lágrimas vertiendo,\nPorque eterno amor juré,\nEntonces casi expiré\nAhora vivo muriendo.",3,1,0,30,"EN OTRO TIEMPO EXISTÍ",9,6,"eo",52,0,-1,0,169,169,"C-184","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0184-06",3,"Inhumano dios Cupido,\nMuévate al fin mi dolencia,\nHaz que vuelva a mi presencia\nLa diosa por quién suspiro,\nSólo por ella respiro,\nLa vida que le rendí,\nY si en otro tiempo fuí,\nCual ninguno afortunado,\nMe veo en llanto anegado\nDesde que mi bien perdí.",3,1,0,30,"EN OTRO TIEMPO EXISTÍ",18,10,"i",23,0,-1,0,169,169,"C-184","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0185-01",3,"¿En qué estrella yo nací\nPara tanto padecer?\nMejor fuera haberme muerto\nAl instante de nacer.",3,1,0,30,"EN QUE ESTRELLA YO NACÍ",0,4,"e",20,0,-1,0,169,169,"C-185","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0185-02",3,"Yo, como infeliz, perdí\nLo seguro por lo incierto,\nSi fué causa de mi estrella\nYo no me quejo del tiempo.",3,1,0,30,"EN QUE ESTRELLA YO NACÍ",0,4,"eo",-1,0,-1,0,169,169,"C-185","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0185-03",3,"Yo no me quejo del tiempo\nQuéjese el tiempo de mí\nQue el tiempo dichas me dio\nYo pesares elegí.",3,1,0,30,"EN QUE ESTRELLA YO NACÍ",0,4,"i",23,0,-1,0,169,169,"C-185","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0185-04",3,"Yo adoré un falso diamante\nPorque fino lo creí,\nY si no logré mi intento\nQuéjese el tiempo de mí.",3,1,0,30,"EN QUE ESTRELLA YO NACÍ",0,4,"i",23,0,-1,0,169,169,"C-185","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0186-01",3,"En una cárcel de penas\nEn un calabozo estrecho;\nContemple cómo estaré,\nMeta la mano en el pecho.",3,1,0,30,"EN UNA CÁRCEL DE PENAS",0,4,"eo",60,0,-1,0,169,169,"C-186","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0187-01",3,"¡toy de vivir cansado\ne consume fatal suerte.\niy! diré, desesperado:\nespectro soy de la muerte!",3,1,0,30,"ESTOY DE VIVIR CANSADO",1,4,"ee",134,0,-1,0,170,170,"C-187","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0187-04",3,"Y cavilaciones tales\nMe consumen lentamente,\nQue las sombras de la muerte,\nYa van mi frente cubriendo,\nY lentamente muriendo\nMe consume fatal suerte.",3,1,0,30,"ESTOY DE VIVIR CANSADO",9,6,"ee",134,0,-1,0,170,170,"C-187","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0187-05",3,"Lágrimas de sangre vierten\nDe sus órbitas mis ojos,\nMirando tristes despojos,\nQue va dejando la muerte;\nY viéndome de esta suerte\nPálido, desfigurado,\nCon ojos tan marchitados,\nQue no pueden ni llorar,\n¡Ven muerte, mi alma a calmar!\n¡Ay! diré, desesperado.",3,1,0,30,"ESTOY DE VIVIR CANSADO",18,10,"ao",-1,0,-1,0,170,170,"C-187","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0187-06",3,"Sirva al mundo de ejemplar\nEste esqueleto ambulante\nQue por ser tan fino amante\nVa al sepulcro a descansar,\nMas, sabrás que ha de dejar\nUna sombra permanente,\nGritando continuamente\nA los que fino han amado:\n—Miren cómo me han dejado\n¡Espectro soy de la muerte!",3,1,0,30,"ESTOY DE VIVIR CANSADO",18,10,"ee",-1,0,-1,0,170,170,"C-187","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0188-02",3,"Y triste y acongojada,\nTe has de poner a llorar,\nY entonces te has de acordar\nQue fui tu planta estimada.",3,1,0,30,"FUI TU ÁRBOL ESTIMADO",11,4,"aa",49,0,-1,0,171,171,"C-188","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0188-a-01",3,"Yo era un jardín de alegría\nBellas flores dulces llamas,\nEn la sombra de mis ramas\nGustoso te recibía.\nDos mil cariños te hacía,\nY aplacaba tus ardores,\nY cortabas varias flores,\nDe aquel jardín tan florido;\nAhora todo has perdido\nSerá por otros amores.",3,1,0,30,"YO ERA UN JARDÍN DE ALEGRÍA",18,10,"oe",5,0,-1,0,171,171,"C-188-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0188-a-02",3,"Después de cortar la flor\nHas arrojado la planta\nSu sombra te ha de hacer falta\nCuando te fatigue el sol,\nY no has de tener valor\nViéndote desamparada.\nDe triste y desconsolada\nTe has de poner a llorar\nEntonces te has de acordar\nQue era tu prenda estimada.",3,1,0,30,"YO ERA UN JARDÍN DE ALEGRÍA",18,10,"aa",49,0,-1,0,171,171,"C-188-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0188-a-03",3,"Yo era tu árbol estimado\nQue te di mucho producto,\nAhora no te doy fruto,\nTú me miras deshojado;\nNo digas que me he secado,\nEstoy más verde que un yuyo,\nNo digas que esto es orgullo,\nPorque es cosa muy notoria\nNo seas de mala memoria\nAcuérdate que fui tuyo.",3,1,0,30,"YO ERA UN JARDÍN DE ALEGRÍA",18,10,"uo",78,0,-1,0,171,171,"C-188-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0189-01",3,"¿Has visto a algún pajarillo\nCantar triste y lastimado\nMaldiciendo su destino\nSin su consorte estimado?",3,1,0,30,"HAS VISTO A ALGÚN PAJARILLO",0,4,"ao",14,0,-1,0,171,171,"C-189","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0189-02",3,"Nada su pasión divierte\nY aún aborrece su nido,\nNo canta como solía\nA vista de un bien perdido.",3,1,0,30,"HAS VISTO A ALGÚN PAJARILLO",3,4,"io",101,0,-1,0,171,171,"C-189","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0189-03",3,"Ya con reclamos la llama,\nYa lo busca dando silbos,\nY de su pecho, la pena\nArranca tiernos suspiros.",3,1,0,30,"HAS VISTO A ALGÚN PAJARILLO",0,4,"io",-1,0,-1,0,171,171,"C-189","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0189-04",3,"Y después de haber andado\nDe su albergue fugitivo,\nBusca la rama más seca\nPara llorar afligido.",3,1,0,30,"HAS VISTO A ALGÚN PAJARILLO",0,4,"io",-1,0,-1,0,171,171,"C-189","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0189-05",3,"Yo soy aquel pajarillo\nDe tan infelice suerte,\nQue tengo de andar penando\nHasta que llegue la muerte.",3,1,0,30,"HAS VISTO A ALGÚN PAJARILLO",0,4,"ee",134,0,-1,0,171,171,"C-189","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0190-01",3,"Horrible fiebre devora\nMi cerebro con tesón,\nY, en más de una ocasión,\nMe amenaza aterradora.\nTu imagen consoladora\nNo se presente a mi mente,\nSolo sigue indiferente,\nInsensible a mi amargura,\nY a mi negra desventura\nSorda, ciega e inclemente.",3,1,0,30,"HORRIBLE FIEBRE DEVORA",18,10,"ee",15,0,-1,0,171,171,"C-190","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0190-02",3,"En vano quiero, ofendido\nLuchar con mi insomnio cruel,\nNo puedo olvidar la infiel,\nQue mi perdición ha sido.\n¿Qué me vale haber vivido\nPor su amor alimentado,\nSi al fin por ella arruinado,\nCaería en tan triste suerte,\nQue sólo viera en la muerte\nLa dicha que había soñado?",3,1,0,30,"HORRIBLE FIEBRE DEVORA",18,10,"ao",14,0,-1,0,171,171,"C-190","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0190-09",3,"Ya no hay gloria ni placer,\nEn mi pobre corazón,\nUn dolor y confusión,\nSólo pudiera tener,\nQuiero desaparecer\nSi tan desgraciado fui.\nVenga la muerte por mí,\nA llevarme con empeño,\nPorque a lado de otro dueño,\nHoy peno porque te vi.",3,1,0,30,"LA PENA Y LA QUE NO ES PENA",18,10,"i",23,0,-1,0,172,172,"C-190","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0192-01",3,"Las músicas me entristecen,\nMis placeres son tormentos,\nLos gustos remordimientos,\nLos astros se me obscurecen.",3,1,0,30,"LAS MÚSICAS ME ENTRISTECEN",11,4,"ee",359,0,-1,0,172,172,"C-192","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0192-02",3,"Un negro luto me cubre\nEn el centro de mi pecho,\nEn este mi triste lecho,\nCubierto de pesadumbre.\nNo miran lo que antes tuve\nY lo que el mundo me ofrece.\nMás y más mis penas crecen,\nMe es horroroso vivir.\nSi me quiero divertir,\nLas músicas me entristecen.",3,1,0,30,"LAS MÚSICAS ME ENTRISTECEN",18,10,"ee",359,0,-1,0,172,172,"C-192","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0192-03",3,"Dejando mi habitación\nSalgo a los bosques llorando,\nLa muerte pronosticando,\nLleno de tribulación.\nYo no encuentro l'ocasión\nUn momento de contento;\nSi busco divertimiento,\nMe acuerdo lo que he perdido\nY entre los bosques metido\nMis placeres son tormentos.",3,1,0,30,"LAS MÚSICAS ME ENTRISTECEN",18,10,"eo",-1,0,-1,0,172,172,"C-192","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0192-04",3,"Las aves girando el vuelo\nViendo mi suerte penosa,\nMe preguntan cuidadosas\nLa causa de mis desvelos.\nPara darme algún consuelo\nO mitigar mi tormento,\nSuave cantan un momento,\nY me causan grande placer;\nTodo esto me viene a hacer\nLos gustos remordimientos.",3,1,0,30,"LAS MÚSICAS ME ENTRISTECEN",18,10,"eo",-1,0,-1,0,172,173,"C-192","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0192-05",3,"Por tomar algún paseo\nSalgo al campo delicioso,\nBuscando lo más hermoso,\nFlores que causan recreo;\nPero apenas yo las veo\nVanas locuras parecen,\nAmanece y anochece,\nEnvuelto en mi triste duelo,\nCuando más claro está el cielo,\nLos astros se me obscurecen.",3,1,0,30,"LAS MÚSICAS ME ENTRISTECEN",18,10,"ee",-1,0,-1,0,173,173,"C-192","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0193-01",3,"Lejos de tí vida mía\nMientras viva lloraré,\nHasta mi última agonía\nTu nombre pronunciaré.",3,1,0,30,"LEJOS DE TI VIDA MÍA",1,4,"e",77,0,-1,0,173,173,"C-193","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0193-02",3,"¡Oh! Cuánto mejor sería\nAndar por el mundo errante,\nY no vivir un instante\nLejos de tí, vida mía.",3,1,0,30,"LEJOS DE TI VIDA MÍA",11,4,"ia",0,0,-1,0,173,173,"C-193","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0193-03",3,"La imagen siempre tendré\nDe la diosa de mi pecho,\nY entre suspiros deshecho\nMientras viva lloraré.",3,1,0,30,"LEJOS DE TI VIDA MÍA",11,4,"e",77,0,-1,0,173,173,"C-193","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0193-04",3,"Cuando la melancolía\nEl dolor vaya aumentando,\nYo te he de seguir amando\nHasta mi última agonía.",3,1,0,30,"LEJOS DE TI VIDA MÍA",11,4,"ia",0,0,-1,0,173,173,"C-193","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0193-05",3,"Abatido moriré\nEn los brazos de tu amor,\nY en tan continuo dolor\nTu nombre pronunciaré.",3,1,0,30,"LEJOS DE TI VIDA MÍA",11,4,"e",77,0,-1,0,173,173,"C-193","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0194-01",3,"Los pajaritos y yo\nA un tiempo nos levantamos,\nEllos a cantar la aurora,\nY yo a llorar mis trabajos.",3,1,0,30,"LOS PAJARITOS Y YO",0,4,"ao",-1,0,-1,0,173,173,"C-194","",0,"","","",5,0,0,[],""],["carrizo_salta-nc0194-02",3,"Ellos con dulce armonía\nDesde sus nidos gorjean,\nY con sus trinos desean,\nRomper los velos del día;\nY yo con melancolía\nLloro porque se ausentó,\nY a nuestro pecho rindió,\nEl peso de una inclemencia,\nVivimos en competencia,\nLos pajaritos y yo.",3,1,0,30,"LOS PAJARITOS Y YO",18,10,"o",2,0,-1,0,173,173,"C-194","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0194-03",3,"Ellos sacuden sus alas\nPara levantar el vuelo,\nY yo despidiendo al cielo,\nMis suspiros como bala,\nEn concertadas escalas\nLa pena y gloria entonamos.\nEste discurso ocupamos\nEn diferentes asuntos,\nSólo por madrugar juntos\nA un tiempo nos levantamos.",3,1,0,30,"LOS PAJARITOS Y YO",18,10,"ao",116,0,-1,0,173,173,"C-194","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0194-04",3,"Los jiugueros con empeño\nEn cuando me ven rendido,\nSe recogen a sus nidos,\nA descansar con el sueño;\nMi pecho, como sin dueño,\nEn vez de descansar, llora,\nImaginando aquella hora,\nQue los pajaritos cantan.\nMientras duermo se levantan\nEllos, a cantar la aurora.",3,1,0,30,"LOS PAJARITOS Y YO",18,10,"oa",107,0,-1,0,173,173,"C-194","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0194-05",3,"Como música compuesta,\nEllos cantan y yo lloro,\nAllí formamos un coro\nDe música con orquesta.\nEl monte atención nos presta,\nY con las hojas y gajos\nLlevamos compaces bajos\nY así cantando no cesan.\nEllos a cantar empiezan\nY yo a llorar mis trabajos.",3,1,0,30,"LOS PAJARITOS Y YO",18,10,"ao",286,0,-1,0,173,173,"C-194","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0196-01",3,"Mi placer, mi gusto y gloria,\nLas delicias con mi dueño,\nSe me fueron como un sueño,\nDejando tristes memorias.",3,1,0,30,"MI PLACER, MI GUSTO Y GLORIA",5,4,"oa",-1,0,-1,0,174,174,"C-196","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0196-02",3,"Mostrándose transitorias\nLas dichas me abandonaron,\nPara siempre me dejaron\nMi placer, mi gusto y gloria.",3,1,0,30,"MI PLACER, MI GUSTO Y GLORIA",5,4,"oa",-1,0,-1,0,174,174,"C-196","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0196-03",3,"El tiempo con cruel engaño\nMás me ha dado en que pensar,\nLo que no puedo gozar\nLas delicias con mi dueño.",3,1,0,30,"MI PLACER, MI GUSTO Y GLORIA",5,4,"eo",-1,0,-1,0,174,174,"C-196","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0196-04",3,"Todo aquel tiempo risueño\nDe placeres y ventura,\nDejándome en la amargura\nSe me fueron como un sueño.",3,1,0,30,"MI PLACER, MI GUSTO Y GLORIA",11,4,"eo",138,0,-1,0,174,174,"C-196","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0196-05",3,"Estas dichas ilusorias\nQue gocé tan vivamente,\nSe me fueron derrepente\nDejando tristes memorias.",3,1,0,30,"MI PLACER, MI GUSTO Y GLORIA",11,4,"oa",237,0,-1,0,174,174,"C-196","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0197-01",3,"No hay corazón como el mío\nQue sufre y calla sus penas,\nCorazón que sufre y calla..\nNo se encuentra donde quiera.",3,1,0,30,"NO HAY CORAZÓN COMO EL MIÓ",0,4,"ea",-1,0,-1,0,174,174,"C-197","",0,"","","",9,0,0,[],""],["carrizo_salta-nc0197-02",3,"Un tormento sin cesar\nMe acompaña, noche y día,\nNo sé qué pena es la mía...\n¡Qué ocasión para llorar!\n¡Qué cosa particular!\nYo no temo al cruel martirio,\nDe los desprecios me río,\nLloro si me quieren bien,\nQue para sufrir desdén\nNo hay corazón como el mío.",3,1,0,30,"NO HAY CORAZÓN COMO EL MIÓ",18,10,"io",3,0,-1,0,174,174,"C-197","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0197-03",3,"Lloró Jacob por su amada,\nY Raquel en catorce años,\nLloró y sufrió el desengaño\nAl ver su prenda trocada,\nEl labrador con la azada\nEl cautivo en la cadena.\nLloró y sufrió Magdalena\nTodo tiempo en su tesón,\n¿Quién tuviera un corazón\nQue sufra y calle sus penas?",3,1,0,30,"NO HAY CORAZÓN COMO EL MIÓ",18,10,"ea",-1,0,-1,0,174,175,"C-197","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0197-04",3,"Soy como la roca fuerte,\nQue no siente agravio alguno,\n¡Vengan males de uno en uno,\nY también venga la muerte!\nCompasivos de esta suerte\nMe quieren formar batalla,\nTengo una cota de malla,\nSi la tengo no la siento\nYo soy del pecho, el aliento,\nCorazón que sufre y calla.",3,1,0,30,"NO HAY CORAZÓN COMO EL MIÓ",18,10,"aa",249,0,-1,0,175,175,"C-197","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0198-01",3,"No fueran tantas mis penas\nSi a mi lado la tuviera..\nGrande fuera mi contento\nSi a mi presencia la viera.",3,1,0,30,"NO FUERAN TANTAS MIS PENAS",0,4,"ea",44,0,-1,0,175,175,"C-198","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0198-02",3,"Ya soy un cadáver yerto\nQue me pueden meditar,\nQue ya estoy para dentrar\nEn la cuenta de los muertos.\nA vivir en los desiertos\nA encerrarme en las cavernas,\nDonde sólo las sirenas\nSean testigos de mi muerte,\nHasta que volviera a verte\nNo fueran tantas mis penas.",3,1,0,30,"NO FUERAN TANTAS MIS PENAS",18,10,"ea",62,0,-1,0,175,175,"C-198","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0198-03",3,"Me acuerdo de los cariños\nY de sus dulces halagos;\nNo mirándola a mi lado,\nMis suspiros son perdidos,\nSe me apagan los sentidos,\nMi corazón desespera.\nQuiero salir para fuera\nCon el dolor de mi llanto,\nYa no padeciera tanto\nSi a mi lado la tuviera.",3,1,0,30,"NO FUERAN TANTAS MIS PENAS",18,10,"ea",44,0,-1,0,175,175,"C-198","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0199-01",3,"No tengo anhelo al vivir,\nSólo en morir tengo empeño,\n¿De qué me sirve vivir\nSi la que amo tiene dueño?",3,1,0,30,"NO TENGO ANHELO AL VIVIR",1,4,"eo",138,0,-1,0,175,175,"C-199","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0199-02",3,"Lloraré toda la vida\nEn un silencio profundo,\nSi la que amo tiene dueño\n¿Para qué andar en el mundo?",3,1,0,30,"NO TENGO ANHELO AL VIVIR",0,4,"uo",179,0,-1,0,175,175,"C-199","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0199-03",3,"No quiero andar en el mundo\nPues tengo tan mala suerte,\nSi la que amo tiene dueño\nMás bien prefiero la muerte.",3,1,0,30,"NO TENGO ANHELO AL VIVIR",0,4,"ee",134,0,-1,0,175,175,"C-199","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0199-04",3,"Mejor que venga la muerte\nConmigo, a hacer su deber,\nQue se me hace un contrapeso\nDe verla en otro poder.",3,1,0,30,"NO TENGO ANHELO AL VIVIR",0,4,"e",20,0,-1,0,175,175,"C-199","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0199-a-01",3,"No tengo afecto al vivir,\nAl morir sí pongo empeño,\n¿De qué me sirve el querer\nSi la que amo tiene dueño?",3,1,0,30,"NO TENGO AFECTO AL VIVIR",0,4,"eo",138,0,-1,0,175,175,"C-199-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0199-a-02",3,"Lloraré toda mi vida\nEn un silencio profundo,\nSi la que amo tiene dueño\nNo quiero andar en el mundo.",3,1,0,30,"NO TENGO AFECTO AL VIVIR",0,4,"uo",179,0,-1,0,175,175,"C-199-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0199-a-03",3,"No quiero andar en el mundo\nPorque tengo mala suerte,\nSi la que amo tiene dueño,\nMás bien que venga la muerte.",3,1,0,30,"NO TENGO AFECTO AL VIVIR",0,4,"ee",134,0,-1,0,175,175,"C-199-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0199-a-04",3,"Más bien que venga la muerte\nConmigo a hacer su deber,\nQue se me hace un contrapeso\nAl verte en otro poder.",3,1,0,30,"NO TENGO AFECTO AL VIVIR",0,4,"e",20,0,-1,0,175,175,"C-199-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0199-a-05",3,"Al verte en otro poder\nMi corazón se estremece\nY llora gotas de sangre\nPorque por tu amor padece.",3,1,0,30,"NO TENGO AFECTO AL VIVIR",0,4,"ee",64,0,-1,0,175,175,"C-199-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0200-01",3,"Padezco, suspiro y lloro,\nCuando por fortuna os miro;\nY de verme yo en clausura\nLloro, padezco y suspiro.",3,1,0,30,"PADEZCO, SUSPIRO Y LLORO",0,4,"io",222,0,-1,0,176,176,"C-200","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0200-02",3,"Confío, espero y aguardo\nQue a mis males deis alivio,\nY ser tuyo de una vez\nEspero, aguardo y confío.",3,1,0,30,"PADEZCO, SUSPIRO Y LLORO",0,4,"io",-1,0,-1,0,176,176,"C-200","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0200-03",3,"Y ahora para más pena,\nPones tu cariño en mí,\nPa que no goce atrevido\nLo que necio pretendí.",3,1,0,30,"PADEZCO, SUSPIRO Y LLORO",0,4,"i",23,0,-1,0,176,176,"C-200","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0200-04",3,"¡Ea, penas, a sufrir!\n¡Ea, ojos, a llorar!\nQue ya es forzoso morir\nPues no tengo de gozar.",3,1,0,30,"PADEZCO, SUSPIRO Y LLORO",1,4,"a",21,0,-1,0,176,176,"C-200","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0200-05",3,"Sólo el que entiende de amor\nSe puede doler de mí,\nConsiderándome solo\nDespedido ya de tí.",3,1,0,30,"PADEZCO, SUSPIRO Y LLORO",0,4,"i",23,0,-1,0,176,176,"C-200","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0201-01",3,"Para más atormentarme\nMe acuerdo de quien amé.\nNo me quisiera acordar\nDe quien nunca olvidaré.",3,1,0,30,"PARA MAS ATORMENTARME",0,4,"e",77,0,-1,0,176,176,"C-201","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0201-02",3,"Yo adoré a una niña bella,\nLa ingrata, supo dejarme\nTan sólo recuerdos tristes,\nPara más atormentarme.",3,1,0,30,"PARA MAS ATORMENTARME",0,4,"ae",35,0,-1,0,176,176,"C-201","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0201-05",3,"Al fin, ingrata me fué\nMi desgracia lloraré,\nSin borrar de mi memoria\nDe quien nunca olvidaré.",3,1,0,30,"PARA MAS ATORMENTARME",0,4,"e",77,0,-1,0,176,176,"C-201","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0202-01",3,"Para mí no hay tiempo alegre\nSoy un deshojado lirio,\nQue a los golpes de un martirio\nSe secan sus hojas verdes.",3,1,0,30,"PARA MI NO HAY TIEMPO ALEGRE",5,4,"ee",-1,0,-1,0,176,176,"C-202","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0202-02",3,"¿Si habrá de mí quién se acuerde\nEn este mi triste estado?\nDe mil tormentos rodeado,\nPara mí no hay tiempo alegre.",3,1,0,30,"PARA MI NO HAY TIEMPO ALEGRE",5,4,"ee",-1,0,-1,0,176,176,"C-202","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0202-03",3,"Vivo en continuo delirio,\nNo hallo remedio a mi mal,\nEn este mundo fatal\nSoy un deshojado lirio.",3,1,0,30,"PARA MI NO HAY TIEMPO ALEGRE",11,4,"io",360,0,-1,0,176,176,"C-202","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0202-04",3,"De balde lloro y suspiro\nSin consolarme jamás,\nY sin otro alivio más\nQue a los golpes de un martirio.",3,1,0,30,"PARA MI NO HAY TIEMPO ALEGRE",5,4,"io",-1,0,-1,0,176,176,"C-202","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0202-05",3,"Entre sufrimientos crueles\nSe agotará mi existencia,\nMientras que con la inclemencia\nSe secan mis hojas verdes.",3,1,0,30,"PARA MI NO HAY TIEMPO ALEGRE",5,4,"ee",-1,0,-1,0,176,176,"C-202","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0203-01",3,"Para mi todo es de noche\nComo negra tempestad,\nNací ciego, nada he visto,\nPara mí todo es igual.",3,1,0,30,"PARA MI TODO ES DE NOCHE",0,4,"a",-1,0,-1,0,176,176,"C-203","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0203-02",3,"¡Ay, qué desgraciado soy!\nCiego nací,\nNo he visto a mi madre,\nNo he visto a mi padre,\n¡Quiero morir!",3,1,0,30,"PARA MI TODO ES DE NOCHE",7,5,"i",-1,0,-1,0,176,176,"C-203","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0203-03",3,"A veces busco una rosa,\nEn las ramas de un rosal,\nY las espinas me dicen:\n—Pobre ciego ¿Adónde vas?",3,1,0,30,"PARA MI TODO ES DE NOCHE",0,4,"a",-1,0,-1,0,176,177,"C-203","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0203-05",3,"A veces busco en la noche\nSu belleza angelical,\nY las estrellas me dicen:\n—Pobre ciego ¿Adónde vas?",3,1,0,30,"PARA MI TODO ES DE NOCHE",0,4,"a",-1,0,-1,0,177,177,"C-203","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0203-07",3,"Muchas veces en mis noches\nAbrazado me sentí,\nY todo aquello era un sueño,\nQue despierto, nada vi.",3,1,0,30,"PARA MI TODO ES DE NOCHE",0,4,"i",23,0,-1,0,177,177,"C-203","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0204-01",3,"¡Pecho, si sabes sentir!\n¿Para cuándo es tu dolor?\n¿Qué no vierte por tus ojos,\nLíquido tu corazón?",3,1,0,30,"PECHO, SI SABES SENTIR",0,4,"o",-1,0,-1,0,177,177,"C-204","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0204-02",3,"Despierta del desengaño\n¿Cegado quieres seguir?\n¿Cómo no lloras tu engaño\nPecho, si sabes sentir?",3,1,0,30,"PECHO, SI SABES SENTIR",1,4,"i",157,0,-1,0,177,177,"C-204","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0204-03",3,"Si te hallas aprisionado\nMaltratado y sin honor,\n¿Cómo sufres tan callado?\n¿Para cuándo es tu dolor?",3,1,0,30,"PECHO, SI SABES SENTIR",1,4,"o",72,0,-1,0,177,177,"C-204","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0204-04",3,"Y si estás atormentado\nCon tus amargos despojos\n¿Dónde las lágrimas tienes\nQué no viertes por tus ojos?",3,1,0,30,"PECHO, SI SABES SENTIR",0,4,"oo",99,0,-1,0,177,177,"C-204","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0204-05",3,"Y si estás desconsolado,\n¡Qué se acabe tu pasión!\nArranca desesperado\nLíquido tu corazón.",3,1,0,30,"PECHO, SI SABES SENTIR",1,4,"o",31,0,-1,0,177,177,"C-204","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0205-01",3,"Pesares sobre pesares,\nTormento sobre tormento,\nRecibo a cada momento\nHaciendo mis ojos mares.",3,1,0,30,"PESARES SOBRE PESARES",11,4,"ae",164,0,-1,0,177,177,"C-205","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0205-02",3,"¿Viste las aves cantar\nCuándo aparece la aurora?\nCon mayor empeño llora\nMi corazón de pesar.\nAllí me pongo a juntar\nPensamientos a millares,\nBusco por todos lugares,\nLas noticias de mi centro,\nY tan solamente encuentro,\nPesares sobre pesares.",3,1,0,30,"PESARES SOBRE PESARES",18,10,"ae",164,0,-1,0,177,177,"C-205","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0205-03",3,"Si quiero tomar el sueño\nPor descansar algún tanto\nDe allí mismo me levanto,\nA llorar con más empeño.\nSoy como prenda sin dueño\nSin estimación ni afecto,\nTiernamente me lamento,\nSin saber lo que será,\n¿Qué pecho resistirá\nTormento sobre tormento?",3,1,0,30,"PESARES SOBRE PESARES",18,10,"eo",94,0,-1,0,177,177,"C-205","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0205-04",3,"Si lo miro al sol ardiente\nCubrirse en dorado manto,\nQuiero suspender el llanto.\nOtra vez vuelvo al instante\nA este mi llanto incesante,\nCon el dolor más violento;\nEntregado al sentimiento\nCon el pesar y desvelo.\nTorrentes de desconsuelo,\nRecibo a cada momento.",3,1,0,30,"PESARES SOBRE PESARES",18,10,"eo",-1,0,-1,0,177,177,"C-205","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0206-06",3,"Por un tropezón que di\nTodo el mundo se admiró\nOtros tropiezan y caen\n¿Cómo no me admiro yo?",3,1,0,30,"POR UN TROPEZÓN QUE DI",0,4,"o",2,0,-1,0,178,178,"C-206","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0206-07",3,"Erró en El Paraíso, Adán,\nY fué por haber pecado\nY no les causó cuidado\nY en mí les vino a causar.\nBien me pueden disculpar\nDel error que cometí,\nQue para infeliz nací,\nA padecer entre tantos;\nA todos les causó espanto\nPor un tropezón que di.",3,1,0,30,"POR UN TROPEZÓN QUE DI",18,10,"i",23,0,-1,0,178,178,"C-206","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0206-08",3,"También erró Lucifer\nPorque escribió en su memoria,\nPerdió su juicio y su gloria,\nTan sólo por su querer,\nY porque quiso tener,\nMayor mandato que Dios;\nA los infiernos cayó,\nNadie no se acuerda de él\nYo porque estoy al caer\nTodo el mundo se admiró.",3,1,0,30,"POR UN TROPEZÓN QUE DI",18,10,"o",2,0,-1,0,178,178,"C-206","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0206-09",3,"Salomón siendo de ciencia\nErró en sus leyes penales,\nDios lo dejó por los aires,\nEsperando su sentencia;\nEl no erró por su inocencia,\nNi porque el mundo lo engañe\nNadie estan libre que se halle\nEn la misma novedad,\nCon poca facilidad\nOtros tropiezan y caen.",3,1,0,30,"POR UN TROPEZÓN QUE DI",18,10,"ae",-1,0,-1,0,178,178,"C-206","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0206-10",3,"San Pedro siendo tan listo\nErró en el altar primero,\nEstaba a perder el cielo,\nPor haber negado a Cristo;\nY allí se formó el registro\nQue por el mismo pasó,\nAl cielo sus manos dio,\nEntre cumbre, mar y tierra.\nTantos que en el mundo yerran\n¿Cómo no me admiro yo?",3,1,0,30,"POR UN TROPEZÓN QUE DI",18,10,"o",2,0,-1,0,178,179,"C-206","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0207-01",3,"Sus lágrimas sin cesar?\nSe pone allí a lamentar\nDe verse tan desgraciada,\nConsidera, dueña amada,\nLa pena y la confusión\nQue sufre mi corazón\nQue está de males postrado.",3,1,0,30,"¿QUE AGUANTARA UN CORAZÓN?",4,7,"ao",-1,0,-1,0,179,179,"C-207","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0207-02",3,"¿Qué aguantará un corazón?\n¿Tan herido y lastimado?\n¿Qué resistirá un enfermo\nQue está de males postrado?",3,1,0,30,"",0,4,"ao",14,0,-1,0,179,179,"C-207","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0207-03",3,"¿Vistes una flor secarse\nCuando el riego se le quita,\nTriste, penosa y marchita,\nEmpezar a deshojarse,\nTriste, esperando el hallarse\nEn aquella situación,\nDonde con veneración,\nRiegan su planta constante?\nMas si esto no tiene aguante\n¿Qué aguantará un corazón?'",3,1,0,30,"",18,10,"",-1,0,-1,0,179,179,"C-207","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0207-04",3,"¿Vistes a un árbol perder\nSu verdor pronto y ligero\nCuando un afilado acero\nLa derriba de su ser,\nSin que le pueda valer\nEl verse tan encumbrado?\nLuego se cae deshojado,\nTriste, penoso y deshecho,\n¿Qué resistirá mi pecho\nTan herido y lastimado?",3,1,0,30,"",18,10,"ao",14,0,-1,0,179,179,"C-207","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0207-05",3,"¿Vistes una dura piedra\nCuando la hiere el acero\nLlorar centellas de fuego\nQue a tanto golpe se quiebra?\nMas cuando vé que se entrega\nA la porfía y al empeño,\nEntonces goza su dueño,\nAl ver triunfar su paciencia,\nSi en piedras no hay resistencia\n¿Qué resistirá un enfermo?",3,1,0,30,"",18,10,"eo",-1,0,-1,0,179,179,"C-207","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0208-01",3,"¡Qué largas las horas son\nEn el reloj de mi afán!\n¡Qué de poco a poco dan\nAlivio a mi corazón!",3,1,0,30,"¡QUE LARGAN LAS HORAN SON!",11,4,"o",31,0,-1,0,179,179,"C-208","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0208-02",3,"Para mí no hay sol ni luna,\nTarde ni noche ni día\nY siempre estoy, vida mía,\nPensando en tí desde la una;\nInfeliz de mi fortuna,\nA las dos con afición,\nTe entrego mi corazón\nY a las tres dice mi suerte:\nVida mía, para verte,\n¡Qué largas las horas son!",3,1,0,30,"¡QUE LARGAN LAS HORAN SON!",18,10,"o",31,0,-1,0,179,179,"C-208","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0208-03",3,"Con tanto amor te idolatro\nY con tantas excelencias\nQue el alma y las tres potencias\nTe las entrego a las cuatro.\nY a las cinco con encanto\nMis sentidos a ti van,\nPensando si llegarán\nA las seis a tu hermosura,\nPorque no hay hora segura\nEn el reloj de mi afán.",3,1,0,30,"¡QUE LARGAN LAS HORAN SON!",18,10,"a",147,0,-1,0,179,179,"C-208","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0208-04",3,"Siendo mi amor tan completo\nMe consume la tardanza,\nQue pierdo ya la esperanza,\nAl ver el tiempo tan quieto;\nAl dar las siete prometo\nQue ya las ocho darán,\nY que a las nueve serán,\nMis caricias bien premiadas,\n¡Qué horas tan dilatadas\nQue de poco a poco dan!",3,1,0,30,"¡QUE LARGAN LAS HORAN SON!",18,10,"a",147,0,-1,0,179,179,"C-208","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0210-03",3,"Hasta que llegue la muerte.\nMás mirando su sentencia,\nEsto fuera una imprudencia,\nSi no viera la razón,\nMuerto estoy en la ocasión,\nRendido a vuestra presencia.",3,1,0,30,"ÍENDIDO A VUESTRA PRESENCIA",9,6,"ea",46,0,-1,0,180,180,"C-210","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0210-04",3,"De mi placer, un quebranto,\nDel alma, dulce recreo,\nEl momento que la veo,\nSueltan mis ojos el llanto,\nMi pecho se enluta tanto,\nNo puedo verte, mi vida,\nYa la alma está enriquecida,\nPero ¡qué infeliz mi suerte!\nEn solicitud de verte\nVengo mi dueña querida.",3,1,0,30,"ÍENDIDO A VUESTRA PRESENCIA",18,10,"ia",37,0,-1,0,180,180,"C-210","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0211-01",3,"Si con vivir las ofendo\nYa no las ofenderé,\nA donde no haya memoria\nMi retiro formaré.",3,1,0,30,"SI CON VIVIR LAS OFENDO",0,4,"e",77,0,-1,0,180,180,"C-211","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0211-02",3,"En los bosques peligrosos,\nLloraré mi triste suerte,\nQuizás que viéndome ausente,\nQuedarán todos gustosos;\nTodos tendrán grandes gozos\nY yo, triste padeciendo,\nTristezas mis ojos viendo,\nY un lastimoso penar,\nAcábenme de matar,\nSi con vivir las ofendo.",3,1,0,30,"SI CON VIVIR LAS OFENDO",18,10,"eo",52,0,-1,0,180,180,"C-211","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0211-04",3,"En la más adversa suerte\nPorque no volveré a verte,\nTodo el mal remediaré;\nMuy lejos me ausentaré,\nA donde no haya un resquicio;\nViviendo en mi precipicio\nYa no las ofenderé.",3,1,0,30,"SI CON VIVIR LAS OFENDO",4,7,"e",77,0,-1,0,180,181,"C-211","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0211-05",3,"Y si me llego a morir,\nTal vez me van a soñar,\nY que por hacerles mal,\nAlgún tiempo he de venir.\nQuizás habrán de decir\nQue no he de tener dos glorias,\nPor mis dichas tan notorias,\nTambién por la ley escrita,\nYo he de ganar a una ermita,\nA donde no haya memoria.",3,1,0,30,"SI CON VIVIR LAS OFENDO",18,10,"oa",-1,0,-1,0,181,181,"C-211","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0211-06",3,"¿A quién he ofendido tanto?\n¿Qué cristales he quebrado?\n¿Qué espejos habré empañado\nPara tan crecido espanto?\nEn mí no cabe quebranto,\nMi fortuna lloraré,\nSi la debo pagaré,\nCon gusto y con alegría;\nPor una cruel tiranía\nMi retiro formaré.",3,1,0,30,"SI CON VIVIR LAS OFENDO",18,10,"e",77,0,-1,0,181,181,"C-211","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0212-01",3,"Sólo yo soy desgraciado\nY todos hablan de mí,\nSólo en mí ponen reparo\nNunca reparan en sí.",3,1,0,30,"SOLO YO SOY DESGRACIADO",0,4,"i",23,0,-1,0,181,181,"C-212","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0212-02",3,"Otros que roban y matan,\nViven muy gustosamente,\nPero sólo en mí se advierte\nA la más pequeña falta.\nSus vicios no los espanta,\nYo no he muerto ni he robado,\nA nadie he perjudicado,\nPara tanta habladuría,\nOtros hacen felonía,\nSólo yo soy desgraciado.",3,1,0,30,"SOLO YO SOY DESGRACIADO",18,10,"ao",14,0,-1,0,181,181,"C-212","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0212-03",3,"Varios con descaro roban\nY matan a discreción,\nEstos viven con honor\nY bailan, cantan y toman,\nA todo viviente embroman,\nTienen todo vicio al fin;\nDe estos no hablan, de mí sí,\nYa por buenos los vindican,\nMis defectos se publican,\nY todos hablan de mí.",3,1,0,30,"SOLO YO SOY DESGRACIADO",18,10,"i",23,0,-1,0,181,181,"C-212","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0212-04",3,"Muchos que deben no pagan\nY no les dicen tramposos,\nYo soy el facineroso\nEllos en su dicha nadan,\nEn sus faltas no reparan,\nSi han pagado o no han pagado,\nO si la deuda han negado,\nAl acreedor que les cobre;\nPero como soy un pobre,\nSólo en mí ponen reparo.",3,1,0,30,"SOLO YO SOY DESGRACIADO",18,10,"ao",-1,0,-1,0,181,181,"C-212","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0212-05",3,"Saben si tomo aguardiente,\nSi me divierto y con quién,\nY todos observan bien,\nCómo vivo y de qué suerte\nSi tomo aloja y si es fuerte,\nCon proligidad, así,\nDe mi modo de vivir,\nTodos están muy atentos\nPor reparar mis defectos\nNunca reparan en sí.",3,1,0,30,"SOLO YO SOY DESGRACIADO",18,10,"i",-1,0,-1,0,181,181,"C-212","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0213-01",3,"Tan amarga vida paso\nQue ya me cansa vivir\n¡Muera quién gustos no tiene!\n¡Viva quién nació feliz!",3,1,0,30,"TAN AMARGA VIDA PASO",0,4,"i",-1,0,-1,0,181,181,"C-213","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0213-02",3,"¡Cómo no he de apetecer\nDe mi vida el breve plazo\nSi a golpes de mi fortuna\nTan amarga vida paso!",3,1,0,30,"TAN AMARGA VIDA PASO",0,4,"ao",145,0,-1,0,181,181,"C-213","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0213-03",3,"¡Ven, muerte, tan escondida,\nNo me asustes con decir:\nQue la fortuna es contraria\nQue ya me cansa el vivir!",3,1,0,30,"TAN AMARGA VIDA PASO",0,4,"i",157,0,-1,0,181,181,"C-213","",0,"","","",7,0,0,[],""],["carrizo_salta-nc0213-04",3,"Si el signo en que yo nací\nEsto mismo me previene,\n¡Triunfe pues el más dichoso!\n¡Muera quien gustos no tiene!",3,1,0,30,"TAN AMARGA VIDA PASO",0,4,"ee",70,0,-1,0,181,181,"C-213","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0213-05",3,"Goce, goce el venturoso,\nus dichas de mil a mil!\na pesar del desdichado,\nViva quien nació feliz!",3,1,0,30,"TAN AMARGA VIDA PASO",0,4,"i",-1,0,-1,0,182,182,"C-213","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0215-01",3,"Un amor no agradecido,\nQue en mi pecho fomenté,\nTanto más traidor me fué,\nCuanto más constante he sido.",3,1,0,30,"UN AMOR NO AGRADECIDO",11,4,"io",101,0,-1,0,182,182,"C-215","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0215-02",3,"¿Qué planeta nacería\nJunto con mi nacimiento\nSeñalándome aquel tiempo\nDe tanta desgracia mía?\nLlegó sin remedio el día,\nDe mi estado convulsivo,\nDonde sin causa y motivo,\nVine a ser tan desgraciado,\nEsto es lo que me ha pagado\nUn amor no agradecido.",3,1,0,30,"UN AMOR NO AGRADECIDO",18,10,"io",-1,0,-1,0,182,182,"C-215","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0215-03",3,"No sólo en Ana Bolena\nSe ha mirado la inconstancia,\nTambién en esta distancia\nSe ha visto la misma escena.\nGrave dolor, duras penas,\nFueron las que yo pasé\nViendo destruirse mi fe,\nEn un grande desbarato,\nEsto hizo un amor ingrato\nQue en mi pecho fomenté.",3,1,0,30,"UN AMOR NO AGRADECIDO",18,10,"e",77,0,-1,0,182,182,"C-215","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0215-04",3,"Vengará el cielo mi agravio,\nComo que todo lo puede,\nCuando su término llegue,\nY esto es sentencia de un sabio,\nPronunciado por sus labios\nLo dijo y supo por qué,\nYo perdí lo que busqué,\n¡Oh; con qué dolor sentí\nCuando yo más fino fui,\nTanto más traidor me fué!",3,1,0,30,"UN AMOR NO AGRADECIDO",18,10,"e",77,0,-1,0,182,183,"C-215","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0215-05",3,"Al fin en este destino\nVoy a lamentar mi suerte\nHasta que la fatal muerte\nEjecute mi exterminio.\nY en los decretos divinos,\nSe verá lo cometido\nY como correspondido\nCon tanto vil proceder\nFué ese amor en todo infiel\nCuando más constante he sido.",3,1,0,30,"UN AMOR NO AGRADECIDO",18,10,"io",101,0,-1,0,183,183,"C-215","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0216-01",3,"Un año ha que te venero\nSin pensar en otra cosa,\nSólo en tí, deidad hermosa,\nPuse mi amor verdadero.",3,1,0,30,"UN AÑO HA QUE TE VENERO",11,4,"eo",38,0,-1,0,183,183,"C-216","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0216-02",3,"Para mi no hay tiempo alegre,\nSoy un deshojado lirio,\nQue a los golpes de un martirio,\nCayeron mis hojas verdes;\nPero espero de que llegue,\nMi esperanza por Enero,\nY me responda Febrero:\n—En Marzo has de descansar,\nDiciíndole a tu deidad:\n—Un año ha que te venero.",3,1,0,30,"UN AÑO HA QUE TE VENERO",18,10,"eo",38,0,-1,0,183,183,"C-216","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0216-03",3,"Llegó Abril y siempre está\nMi corazón desmayado,\nY mi llanto llegó a Mayo,\nSiempre en el mismo compás,\nJunio me esperaba atrás,\n¡Oh, qué estación tan penosa!\nNo me fué dificultosa\nPorque en deveras la amé,\nTodo este tiempo pasé,\nSin pensar en otra cosa.",3,1,0,30,"UN AÑO HA QUE TE VENERO",18,10,"oa",63,0,-1,0,183,183,"C-216","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0216-04",3,"Siempre en la misma manera\nMe halló Julio en agonía,\nPorque Agosto me ofrecía,\nSu florida primavera,\nPor Setiembre yo pudiera,\nTomar sus fragantes rosas,\nTan bellas y deliciosas.\nContemplando las miraba,\nPorque mi pensar estaba,\nSólo en tí, deidad hermosa.",3,1,0,30,"UN AÑO HA QUE TE VENERO",18,10,"oa",-1,0,-1,0,183,183,"C-216","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0216-05",3,"Al fin, a Octubre le pido,\nDe que dé fin a mis penas,\nAntes que Noviembre venga\nY me halle siempre cautivo,\nAsí mi último suspiro\nDaré por Diciembre entero,\nY de mis ayes postreros\nTe he de avisar lo que he hecho,\nEn ese indolente pecho\nPuse mi amor verdadero.",3,1,0,30,"UN AÑO HA QUE TE VENERO",18,10,"eo",-1,0,-1,0,183,183,"C-216","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0216-a-02",3,"Mi esperanza por Enero\nY me responde Febrero:\n—En Marzo has de descansar\nDiciéndole a tu deidad:\n—Un año ha que te venero.",3,1,0,30,"UN AÑO HA QUE TE VENERO",7,5,"eo",38,0,-1,0,183,183,"C-216-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0216-a-03",3,"Llegando Abril, llorará\nMi corazón desmayado,\nY mi llanto llega a Mayo\nSiempre en el mismo compás,\nJunio me esperaba atrás,\nQue es la estación más penosa,\nNo me fué dificultosa\nPorque de veras te amé,\nY a ese tiempo lo ocupé\nSin pensar en otra cosa.",3,1,0,30,"UN AÑO HA QUE TE VENERO",18,10,"oa",63,0,-1,0,183,183,"C-216-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0216-a-04",3,"Siempre en la misma manera\nJulio me halló en agonía,\nPero Agosto me ofrecía,\nSu florida primavera.\nAsí en Setiembre quisiera\nGozar su fragante rosa,\nQué bella y qué deliciosa,\nMuy constante la miraba,\nTodo mi pensar estaba,\nSólo en tí, deidad hermosa.",3,1,0,30,"UN AÑO HA QUE TE VENERO",18,10,"oa",63,0,-1,0,183,183,"C-216-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0218-02",3,"Ella no comía:\nMaíz, trigo ni arroz,\nYo la alimentaba\nSólo con mi amor.",3,1,0,30,"UNA PALOMITA",0,4,"o",-1,0,-1,0,184,184,"C-218","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0218-03",3,"Talvez con el tiempo,\nNo me eche al olvido,\nSuspire y le pese,\nLo que hizo conmigo.",3,1,0,30,"UNA PALOMITA",0,4,"io",-1,0,-1,0,184,184,"C-218","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0218-04",3,"Si, ella es constante,\nY sabe querer,\nTengo l'esperanza\nDe volverla a ver.",3,1,0,30,"UNA PALOMITA",6,4,"e",20,0,-1,0,184,184,"C-218","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0219-01",3,"Un domingo de mañana\nAndando de caminante,\nVide dentrar a la misa,\nA una niña con su amante.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"ae",47,0,-1,0,184,184,"C-219","",0,"","","",9,0,0,[],""],["carrizo_salta-nc0219-02",3,"No atendí tanto a la misa\nNi al padre que la rezaba,\nCuanto atendí a esa niña,\nQue el corazón me robaba.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"aa",28,0,-1,0,184,184,"C-219","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0219-03",3,"Yo que la estaba queriendo,\nY que la estaba adorando,\nVino el dueño y la llevó,\nY a mí me dejó llorando.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"ao",33,0,-1,0,184,184,"C-219","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0219-04",3,"Me subí en un alto cerro,\nPor ver si la divisaba,\nY sólo alcancé a mirar,\nEl coche que la llevaba.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"aa",28,0,-1,0,184,184,"C-219","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0219-05",3,"Agarré mi guitarrita\nPor ver si me consolaba,\nCuando más lindo tocaba\nGotas de sangre lloraba.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"aa",28,0,-1,0,184,184,"C-219","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0220-01",3,"Un domingo de mañana\nDe pena no me podía\nAl saber que se casaba\nLa prenda que yo quería.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"ia",0,0,-1,0,184,184,"C-220","",0,"","","",9,0,0,[],""],["carrizo_salta-nc0220-02",3,"Monté en mi caballo negro\nY a su casa me largué,\nNo creyendo se enajene\nEsta prenda que estimé.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"e",77,0,-1,0,185,185,"C-220","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0220-03",3,"Llegué en momentos que el fraile\nLe echaba la bendición,\nCasi me caigo allí muerto,\nDe un ataque al corazón.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"o",31,0,-1,0,185,185,"C-220","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0220-04",3,"Tomé entonces la guitarra\nPara despedir mi amor,\nY de este modo canté\nA pesar de mi dolor:",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"o",72,0,-1,0,185,185,"C-220","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0220-05",3,"\" Estás al fin ya casada\nEs bueno 'sirvas a Dios,\nMás esto no es para un día,\nNi una semana, ni dos.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"o",87,0,-1,0,185,185,"C-220","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0220-06",3,"\" Sufrirás toda la vida\nDe tu marido el gobierno,\nPuede ser que tengas glorias,\nO tu vida sea un infierno.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"eo",225,0,-1,0,185,185,"C-220","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0220-07",3,"\"Cuando ya te halles rodeada\nDe tus hijos, el demonio\nTe empezará a hacer sentir,\nEl peso del matrimonio.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"oo",169,0,-1,0,185,185,"C-220","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0220-08",3,"\"Más, pido a Dios, vida mía,\nQue bendiga tu contento,\nQue nunca asome a tus ojos,\nLa huella del sufrimiento.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"eo",94,0,-1,0,185,185,"C-220","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0220-09",3,"Yo me creeré muy feliz\nViendo tu felicidad,\nY cuando otra sea mi dueña,\nOlvidaré tu crueldad.\"",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"a",16,0,-1,0,185,185,"C-220","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0221-01",3,"Un Domingo de mañana\nCuando más contento estaba,\nMe llegaron las noticias\nQue mi novia se casaba.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"aa",28,0,-1,0,185,185,"C-221","",0,"","","",9,0,0,[],""],["carrizo_salta-nc0221-02",3,"Que se case ¡qué me importa,\nSi por otro me ha dejado!\nPero yo siento por ella\nEl corazón destrozado.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"ao",14,0,-1,0,186,186,"C-221","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0221-03",3,"Me dicen que tú te casas\n¡Mira que pena es la mía,\nAl ver en ajenos brazos\nLa prenda que yo quería!",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"ia",0,0,-1,0,186,186,"C-221","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0221-04",3,"Cuando a tí te estén poniendo\nAzahares en la cabeza,\nA mí me estarán poniendo\nEl cuerpo sobre una mesa.",3,1,0,30,"UN DOMINGO DE MAÑANA",1,4,"ea",201,0,-1,0,186,186,"C-221","",0,"","","",12,0,0,[],""],["carrizo_salta-nc0221-05",3,"Cuando a tí te estén poniendo\nPrendedores de brillantes,\nA mí me estarán poniendo\nCuatro velas por delante.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"ae",-1,0,-1,0,186,186,"C-221","",0,"","","",12,0,0,[],""],["carrizo_salta-nc0221-06",3,"Cuando te veas casada\nY con todos tus parientes,\nA mí me acompañarán\nMis amigos solamente.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"ee",-1,0,-1,0,186,186,"C-221","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0221-07",3,"Cuando te veas casada\nCasada ya sin remedio,\nOirás campanas doblar\nPara que pase mi entierro.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"eo",-1,0,-1,0,186,186,"C-221","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0221-08",3,"Cuando te veas casada\nCasada ya sin ventura,\nA mí me estarán poniendo\nEl cuerpo en la sepultura.",3,1,0,30,"UN DOMINGO DE MAÑANA",0,4,"ua",17,0,-1,0,186,186,"C-221","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0221-09",3,"Cuando vos estés comiendo\nLos confites de la suerte,\nA mí me estarán comiendo\nLos gusanos de la muerte.",3,1,0,30,"UN DOMINGO DE MAÑANA",1,4,"ee",134,0,-1,0,186,186,"C-221","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0222-01",3,"Un pajarillo cautivo\nQue está sin poder volar\n¡Pobre de ese pajarillo\nCautivo, sin libertad!",3,1,0,30,"UN PAJARILLO CAUTIVO",0,4,"a",-1,0,-1,0,186,186,"C-222","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0222-02",3,"Con la tijera de amor\nLe han aserrado la pluma,\nY sin dejarle ninguna\nTodo el vuelo le han quitado,\nCon gran dolor consternado,\nLanza del pecho un gemido,\nDe ver su vuelo perdido,\nDonde consuelo no encuentra,\nY con razón se lamenta,\nUn pajarillo cautivo.",3,1,0,30,"UN PAJARILLO CAUTIVO",18,10,"io",-1,0,-1,0,186,186,"C-222","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0222-03",3,"Ya no sacude las alas\nPara tenderlas al viento,\nSólo los tristes lamentos,\nSe le oyen dentro la jaula.\n¡Qué pesada y dura calma!\n¡Qué tormento sin igual!\nQue sin poderse aliviar,\nDe sus largas aflicciones,\nSin plumas y con prisiones\nEstá sin poder volar.",3,1,0,30,"UN PAJARILLO CAUTIVO",18,10,"a",21,0,-1,0,186,186,"C-222","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0222-04",3,"Al amanecer la aurora\nCon sus luces admirables,\nPrincipian todas las aves\nA cantar en aquella hora,\nEl que se halla preso llora,\nCon lo duro de los grillos,\nSirviéndole de martirio,\nVer otras aves que vuelan.\nY cómo el sólo se queda\n¡Pobre de ese pajarillo!",3,1,0,30,"UN PAJARILLO CAUTIVO",18,10,"io",-1,0,-1,0,186,186,"C-222","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0222-05",3,"Al fin por su mala suerte\nLarga un suspiro y se queda\nA vivir entre las penas,\nHasta que llegue la muerte.\nNadie su pesar advierte\nNi se puede consolar,\nTriste se pone a llorar,\nEn su amargo padecer,\nPorque hasta el fin ha de ser\nCautivo y sin libertad.",3,1,0,30,"UN PAJARILLO CAUTIVO",18,10,"a",-1,0,-1,0,186,186,"C-222","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0223-01",3,"¡Ven, muerte, tan escondida,\nSin que te sienta, venir,\nPorque el placer de morir\nNo me torne a dar la vida!",3,1,0,30,"VEN, MUERTE TAN ESCONDIDA",11,4,"ia",37,0,-1,0,187,187,"C-223","",0,"","","",7,0,0,[],""],["carrizo_salta-nc0223-02",3,"Presa el alma de dolor\nCon el corazón marchito,\nSoy como el árbol maldito\nQue no da fruto ni flor.\n¡Muerte, ven a mi clamor,\nQue en tí mi esperanza anida,\nVen, acaba con mi vida,\nVen, en silencio profundo,\nA llevarme de este mundo\nVen, muerte, tan escondida!",3,1,0,30,"VEN, MUERTE TAN ESCONDIDA",18,10,"ia",37,0,-1,0,187,187,"C-223","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0223-03",3,"Ya cansado de amarguras,\nSin esperar un consuelo,\nNo me queda en este suelo\nMás que tristes desventuras.\nDe mi pecho, las t e r n u r a s,\nHan dejado de existir,\nY me vienen a abatir.\nLos pesares más profundos,\n¡Llévame, muerte, del mundo\nSin que te sienta venir!",3,1,0,30,"VEN, MUERTE TAN ESCONDIDA",18,10,"i",157,0,-1,0,187,187,"C-223","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0223-05",3,"Al ver mi ardiente avidez\nPor acabar de existir,\nLos que estiman el vivir\nComo suprema ventura\nDirán, que es esta locura\nPor el placer de morir.",3,1,0,30,"VEN, MUERTE TAN ESCONDIDA",9,6,"i",157,0,-1,0,187,187,"C-223","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0223-06",3,"¡Ay; si vieran la inclemencia,\nEn que mi dolor se goza,\nQue hoja por hoja destroza\nLas flores de mi existencia,\nComprendieran la vehemencia\nCon que anhelo tu venida,\nPero sin que seas sentida\nNi te pueda conocer,\nPorque tan grande placer\nNo me torne a dar la vida!",3,1,0,30,"VEN, MUERTE TAN ESCONDIDA",18,10,"ia",37,0,-1,0,187,187,"C-223","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0224-01",3,"Ya se va el aburrecido\nYa no volveré jamás,\nYa no pisaré en sus puertas\nNo los ofenderé más.",3,1,0,30,"YA SE VA EL ABURRECIDO",0,4,"a",51,0,-1,0,187,187,"C-224","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0224-02",3,"Desde que llegué a tener\nEl uso de mi razón,\nMantengo en el corazón\nUn continuo padecer.\nNunca llegó a suceder\nQue tuviese algún alivio,\nPara eso yo había nacido\nPara no tener fortuna,\nQue digan todos a una:\n—Ya se va el aburrecido.",3,1,0,30,"YA SE VA EL ABURRECIDO",18,10,"io",101,0,-1,0,187,188,"C-224","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0224-03",3,"De que me digan quisiera\nEn qué los habré ofendido,\nLos que me han oscurecido\nComo si mal les hiciera.\nAl fin salgo de esta tierra\nSin ver lo que dejo atrás,\nMe retiro más y más,\nQue se acaben los disgustos,\nPara que vivan a gusto\nYa no volveré jamás.",3,1,0,30,"YA SE VA EL ABURRECIDO",18,10,"a",51,0,-1,0,188,188,"C-224","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0224-04",3,"Según he experimentado\nCuando sepan que me he muerto\nDe mí no harán sentimiento\nPorque soy un desgraciado,\nYa mi nombre se ha acabado,\nYa voy a cerrar mis cuentas,\nHasta aquí estoy dando vueltas,\nEs porque quiero decir,\nQue por no dar qué sentir\nYa no pisaré en sus puertas.",3,1,0,30,"YA SE VA EL ABURRECIDO",18,10,"ea",-1,0,-1,0,188,188,"C-224","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0224-05",3,"¡Adiós, mi padre y mi madre!\n¡Adiós, todos mis hermanos!\nNo hagan sentimientos vanos\nVoy como cosa perdida,\n¡Adiós, toda mi familia!\nNo se pongan a llorar\nQue soy persona cabaz,\nQue me perdonen les pido,\nSi en algo los he ofendido\nNo los ofenderé más.",3,1,0,30,"YA SE VA EL ABURRECIDO",18,10,"a",51,0,-1,0,188,188,"C-224","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0224-a-01",3,"Ya se va el aborrecido\nYa no volverá jamás\nYa no pisará sus puertas\nNi les ofenderá más.",3,1,0,30,"YA SE VA EL ABORRECIDO",0,4,"a",51,0,-1,0,188,188,"C-224-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0224-a-02",3,"De que me digan quisiera\nEn qué les habré ofendido,\nLos que me han aborrecido\nComo si mal les hiciera.",3,1,0,30,"YA SE VA EL ABORRECIDO",11,4,"ea",44,0,-1,0,188,188,"C-224-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0224-a-03",3,"Al fin salgo de esta tierra\nSin ver lo que dejo atrás,\nMe ausentaré más y más,\nQue se acaben los disgustos,\nPara que vivan a gusto\nYa no volveré jamás.",3,1,0,30,"YA SE VA EL ABORRECIDO",9,6,"a",51,0,-1,0,188,188,"C-224-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0224-a-04",3,"¡Adiós mi padre y madre!\n¡Adiós mis hijos y hermanos!\nNo hagan sentimientos vanos,\nVoy como cosa perdida,\nHan oscurecío mi vida\nComo si mal les hiciera.",3,1,0,30,"YA SE VA EL ABORRECIDO",9,6,"ea",-1,0,-1,0,188,188,"C-224-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0225-01",3,"Yo crié una palomita\nPara mi divertimiento,\nY ella me dió el sufrimiento,\nDe irse y dejarme solita.",3,1,0,30,"YO CRIE UNA PALOMITA",11,4,"ia",50,0,-1,0,189,189,"C-225","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0225-02",3,"A una rama que yo sé\nSe fué a sentar esa ingrata,\nSólo el pensarlo me mata\nY jamás me olvidaré.",3,1,0,30,"YO CRIE UNA PALOMITA",11,4,"e",77,0,-1,0,189,189,"C-225","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0225-03",3,"Anda palomita ingrata\nYo te cortaré las alas,\nY no has de poder volar\nNi a tus nidos ni a tus ramas.",3,1,0,30,"YO CRIE UNA PALOMITA",0,4,"aa",-1,0,-1,0,189,189,"C-225","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0225-04",3,"Se fué la paloma un día,\nA tierras donde nació,\nDejando mares por medio,\nPara que no vaya yo.",3,1,0,30,"YO CRIE UNA PALOMITA",0,4,"o",2,0,-1,0,189,189,"C-225","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0226-01",3,"Yo haré bajar a sus plantas\nPor conquistar a su amor\nA la luna del copete\nY de sus gremios al sol.",3,1,0,30,"YO HARÉ BAJAR A SUS PLANTAS",0,4,"o",-1,0,-1,0,189,189,"C-226","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0226-03",3,"De seda fina le haré\nUna alfombra donde pise\nGuarnecida de matices\nY un sitio donde se siente.",3,1,0,30,"YO HARÉ BAJAR A SUS PLANTAS",5,4,"ee",-1,0,-1,0,189,189,"C-226","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0226-04",3,"También yo le haré presente\nDe un castillo de valor\nPara que guarde su honor,\nTodo esto, haré como digo,\nPor conquistar a su amor.",3,1,0,30,"YO HARÉ BAJAR A SUS PLANTAS",7,5,"o",72,0,-1,0,189,189,"C-226","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0226-05",3,"Del oro del buen crisol\nUna corona le haré,\nEn vuestra mano pondré\nCentro del trono de Amor",3,1,0,30,"YO HARÉ BAJAR A SUS PLANTAS",5,4,"o",-1,0,-1,0,189,189,"C-226","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0226-06",3,"Se lo pondré por tapete\nSubiéndome como un cohete\nLas mandaré a las estrellas\nA que bajen de su huella\nA la luna, del copete.",3,1,0,30,"YO HARÉ BAJAR A SUS PLANTAS",7,5,"ee",285,0,-1,0,189,189,"C-226","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0227-01",3,"Yo no soy quién antes era,\nNi la sombra me ha quedado,\nEl tiempo me ha despojado\nMe ha puesto de esta manera.",3,1,0,30,"YO NO SOY QUIEN ANTES ERA",11,4,"ea",44,0,-1,0,189,189,"C-227","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0227-02",3,"Yo era un río caudaloso\nQue tenía mucha corriente,\nSe secaron mis vertientes\nMe quedé triste y penoso.\nEl tiempo calamitoso\nMe ha puesto en tan baja esfera.\nAsí por esta manera\nMe hallo triste y desvalido,\nDe la suerte despedido\nYa no soy quien antes era.",3,1,0,30,"YO NO SOY QUIEN ANTES ERA",18,10,"ea",44,0,-1,0,189,189,"C-227","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0227-03",3,"Yo era un árbol muy hermoso,\nVestido de verdes hojas,\nDaba bellas flores rojas,\nY frutos muy deliciosos.\nTodos tenían grandes gozos",3,1,0,30,"YO NO SOY QUIEN ANTES ERA",7,5,"oo",361,0,-1,0,189,189,"C-227","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0227-04",3,"verme en aquel estado,\nme hallo tan marchitado\ntan alto quedé bajo,\nos me hacharon los gajos,\nLa sombra me ha quedado.",3,1,0,30,"YO NO SOY QUIEN ANTES ERA",7,5,"ao",-1,0,-1,0,190,190,"C-227","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0227-05",3,"era jardín florecente\na todos daba consuelo,\ncon incesante anhelo,\nadoraban los vivientes,\nira, completamente\nencuentro tan despojado,\nflores se han acabado\nándome la alegría,\nque de la noche al día\ntiempo me ha despojado.",3,1,0,30,"YO NO SOY QUIEN ANTES ERA",18,10,"ao",14,0,-1,0,190,190,"C-227","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0227-06",3,"era una torre elevada\nun singular edificio,\nY sólo se hallan vestigios\nDonde estuvo edificada.\nY soy planta abandonada,\nAhora me pisa cualquiera,\nLo que sepan quisiera,\nlo que era y cómo me hallo,\nla fortuna, un desmayo,\nha puesto de esta manera.",3,1,0,30,"YO NO SOY QUIEN ANTES ERA",18,10,"ea",44,0,-1,0,190,190,"C-227","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0228-04",3,"¿Hasta cuando durará\nMi pesar y mi dolor?\n¿Hasta cuándo en el rigor\nMi corazón clamará?\n¿O solamente será\nMi descanso en el sepulcro?\nNo hallo el remedio que busco.\nPor diferentes caminos\nVoy a seguir mi destino.\nSe me acabaron los gustos.",3,1,0,30,"YO SOY AQUEL INFELIZ",18,10,"uo",-1,0,-1,0,190,190,"C-228","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0228-05",3,"Al fin ya desengañado\nDe lo adverso de mi suerte,\nVenga sobre mí la muerte,\nA hacer el último estrago,\nO si yo les causo enfado,\nVoy a desaparecer,\nDonde no pueda volver,\nComo una cosa perdida,\nCon mi fortuna abatida\nEcho menos el placer.",3,1,0,30,"YO SOY AQUEL INFELIZ",18,10,"e",20,0,-1,0,190,190,"C-228","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0229-01",3,"Yo soy aquel que nació\nDe la suerte maldecido,\nY que el mundo he recorrido\nDel uno al otro confín.\nPobrezas, miserias ví,\nQue en todo el orbe existía;\nContaba todos los días,\nLas desgracias del lugar,\nPero no alcancé a contar\nLas grandes desgracias mías.",3,1,0,30,"YO SOY AQUEL QUE NACIÓ",18,10,"ia",214,0,-1,0,190,190,"C-229","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0229-02",3,"Los astros del firmamento\nLos conté una noche obscura,\nConté con ciencia segura,\nLas variaciones del tiempo,\nConté las leguas que el viento,\nEn cada hora recorría,\nY conté en la zoología,\nToda clase de animales,\nY sólo son incontables\nLas grandes desgracias mías.",3,1,0,30,"YO SOY AQUEL QUE NACIÓ",18,10,"ia",-1,0,-1,0,190,190,"C-229","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0229-03",3,"Conté en la Historia Sagrada\nTodos los santos varones,\nConté todas las naciones,\nQue Dios hizo de la nada.\nConté las varas cuadradas\nQue todo el globo tenía,\nConté los peces que habían,\nEn ríos, lagos y mar,\nPero no alcancé a contar\nLas grandes desgracias mías.",3,1,0,30,"YO SOY AQUEL QUE NACIÓ",18,10,"ia",-1,0,-1,0,191,191,"C-229","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0229-04",3,"Conté todita la gente\nMujeres, chicos y grandes,\nConté todos los caudales,\nDe los palacios de Oriente.\nY en un día solamente,\nConté en la sabiduría,\nLas doncellas que vivían\nEn estado virginal,\nPero no alcancé a contar\nLas grandes desgracias mías.",3,1,0,30,"YO SOY AQUEL QUE NACIÓ",18,10,"ia",-1,0,-1,0,191,191,"C-229","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0229-05",3,"Conté todas las estrellas\nY las arenas del suelo,\nSaqué cuentas sin tintero,\nConté las flores más bellas,\nSaqué la cuenta por ellas.\nConté en la Contaduría,\nEl dinero que corría\nEn mil años sin cesar,\nConté los peces del mar\nSiete veces en un día.",3,1,0,30,"CONTÉ TODAS LAS ESTRELLAS",18,10,"ia",0,0,-1,0,191,191,"C-229","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0229-06",3,"Conté todos los granizos\nQue cayó en un aguacero,\nConté los mundos del cielo,\nY las flores de un paraíso;\nY también mi ciencia quiso\nContar la pronunciación,\nConté con justa razón\nLos vellos de una doctora,\nEn dos minutos y una hora\nFuí sabio y conté un millón.",3,1,0,30,"CONTÉ TODAS LAS ESTRELLAS",18,10,"o",31,0,-1,0,191,191,"C-229","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0229-07",3,"Yo conté todas las libras\nY onzas que pesaba el mar,\nY saqué todo el total\nLo puse donde se archiva,\nConté del mundo, las vidas,",3,1,0,30,"CONTÉ TODAS LAS ESTRELLAS",7,5,"ia",-1,0,-1,0,191,191,"C-229","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0229-08",3,"De los vivientes que habían,\nConté con grande armonía,\nLas palabras de un misal,\nY como soy memorial\nTodo esto lo hice en un día.",3,1,0,30,"CONTÉ TODAS LAS ESTRELLAS",7,5,"ia",0,0,-1,0,191,191,"C-229","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0229-09",3,"Yo conté todos los pastos\nTodos los maíces y trigos,\nY todos eran testigos\nDe lo que estaba mirando,\nSeguí adelante contando,\nDe cien mil años, los días,\nY los minutos que había\nSaqué la cuenta cabal,\nPero no alcancé a contar\nTodas las desgracias mías.",3,1,0,30,"CONTÉ TODAS LAS ESTRELLAS",18,10,"ia",-1,0,-1,0,191,191,"C-229","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0229-b-01",3,"Conté todos los granizos\nLlovidos de un aguacero\nConté los astros del cielo,\nY las flores de un paraíso,\nY como la ciencia quiso,\nContar la pronunciación,\nConté con justa razón,\nLos vellos de una señora,\nEn dos minutos y una hora\nFuí sabio y conté un millón.",3,1,0,30,"CONTÉ TODOS LOS GRANIZOS",18,10,"o",31,0,-1,0,191,191,"C-229-b","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0229-b-02",3,"También anoté en mis libros\nLas libras que pesa el mar,\nSaqué la cuenta cabal,\nLa puse donde se archiva,\nConté en el mundo la vida,\nDe los vivientes que había,\nConté con tal armonía\nLas letras de diez misales.\nComo era tan memorable\nTodo esto conté en un día.",3,1,0,30,"CONTÉ TODOS LOS GRANIZOS",18,10,"ia",0,0,-1,0,191,191,"C-229-b","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0229-b-03",3,"Conté las flores del campo\nConté los maíces y trigos,\nY los puse por testigo,\nA los que estaban mirando.\nSeguí adelante contando,\nDe cien mil años los días,\nY los minutos que había,\nSaqué la cuenta cabal;\nConté los peces del mar\nSiete veces en un día.",3,1,0,30,"CONTÉ TODOS LOS GRANIZOS",18,10,"ia",0,0,-1,0,191,191,"C-229-b","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0230-04",3,"Cuantas veces me lamento\nRecordando mi locura\nY otras tristes aventuras,\nA que un amor me arrastró.\nMas hoy, que comprendo yo,\nEl fruto que recogí",3,1,0,30,"YO SOY UN ARBCL PLANTADO",9,6,"i",-1,0,-1,0,192,192,"C-230","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0230-06",3,"Hoy tan sólo me han quedado\nRecuerdos de mi existencia,\nNo hallo para mí clemencia,\nVivo del mundo olvidado.\nYo soy un ser desgraciado,\nNo tengo amigos ni hermanos,\nNi quien me tienda la mano\nAliviando mi dolor,\nNi quién me preste un favor\nDoliéndose de mi estado.",3,1,0,30,"YO SOY UN ARBCL PLANTADO",18,10,"ao",-1,0,-1,0,192,192,"C-230","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0231-01",3,"Yo tuve una prenda bella\nQue la sabía adorar\nUn día se fué con otro\nYo no la hi vuelto a encontrar.",3,1,0,30,"YO TUVE UNA PRENDA BELLA",0,4,"a",21,0,-1,0,192,192,"C-231","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0231-02",3,"En la bulla o soledad,\nComo algo que hubiera muerto,\nLa tengo en mi pensamiento,\nY esa es mi intranquilidad.",3,1,0,30,"YO TUVE UNA PRENDA BELLA",5,4,"a",16,0,-1,0,192,192,"C-231","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0231-03",3,"Yo me acostaba a dormir\nPara ver si la olvidaba,\nY en el rato que dormía,\nA ella era la que soñaba.",3,1,0,30,"YO TUVE UNA PRENDA BELLA",0,4,"aa",28,0,-1,0,192,192,"C-231","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0231-05",3,"Al juego me dedicaba,\nA ver si remedio hubiera,\nSi dos mil pesos perdiera,\nCon verla me desquitara.",3,1,0,30,"YO TUVE UNA PRENDA BELLA",5,4,"aa",-1,0,-1,0,192,192,"C-231","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0231-06",3,"A las montañas inmensas\nYa me voy a retirar,\nSi tu eres fina y constante,\nMe hallarás sí, me hallarás.",3,1,0,31,"A LAS MONTAÑAS INMENSAS",0,4,"a",-1,0,-1,0,194,194,"C-231","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0233-03",3,"¿Cómo quieres que no llore\nViéndose por vuestra causa\nEntre grillos y cadenas\nAprisionado en la jaula?",3,1,0,31,"AQUEL PAJ AB1 LLO TRISTE",0,4,"aa",-1,0,-1,0,194,194,"C-233","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0233-04",3,"Recuerda con sus gorjeos,\nMadrugando con la aurora,\nPara sentir sus despechos\nTan ausente gime y llora.",3,1,0,31,"AQUEL PAJ AB1 LLO TRISTE",0,4,"oa",107,0,-1,0,194,194,"C-233","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0233-05",3,"Fué nacido entre jardines\nY su libertad muy alta,\nHoy, rendido a vuestras aras,\nComo enamorado canta.",3,1,0,31,"AQUEL PAJ AB1 LLO TRISTE",0,4,"aa",-1,0,-1,0,194,194,"C-233","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0234-01",3,"A tu puerta estoy sentado\nTemeroso y afligido,\nDe un desprecio que me has hecho\nM' hi sentido, m'hi sentido.",3,1,0,31,"A TU PUERTA ESTOY SENTADO",0,4,"io",101,0,-1,0,194,194,"C-234","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0234-02",3,"M' hi sentido de manera\nQue casi estoy por morirme,\nSin pronunciar más palabras\nYo quiero irme, yo quiero irme.",3,1,0,31,"A TU PUERTA ESTOY SENTADO",0,4,"ie",184,0,-1,0,194,194,"C-234","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0234-03",3,"Yo quiero irme, prenda mía,\nAnde nunca me verás,\nSi querís volverme a ver,\nAhí me hallarás, me hallarás.",3,1,0,31,"A TU PUERTA ESTOY SENTADO",0,4,"a",51,0,-1,0,194,194,"C-234","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0234-04",3,"Ahí me hallarás, me hallarás,\nY a la prueba me remito,\nQue un bien con un mal se paga,\nYa lo hi visto, ya lo hi visto!",3,1,0,31,"A TU PUERTA ESTOY SENTADO",0,4,"io",-1,0,-1,0,194,194,"C-234","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0234-05",3,"Ya lo hi visto, prenda mía,\nEn esos tus tristes ojos,\nY así pagáis mis amores,\nCon enojos, con enojos.",3,1,0,31,"A TU PUERTA ESTOY SENTADO",0,4,"oo",99,0,-1,0,194,194,"C-234","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0235-01",3,"Aunque de ti viva ausente\nEn los centros del olvido,\nEntre tu imaginación,\nAcuérdate que yo he sido.",3,1,0,31,"AUNQUE DE TI VIVÍA AUSENTE",0,4,"io",101,0,-1,0,194,194,"C-235","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0235-02",3,"El amor precisamente\nCon la larga ausencia calma,\nPero a tu imagen viviente,\nLa tengo impresa en el alma,\nAunque de ti viva ausente.",3,1,0,31,"AUNQUE DE TI VIVÍA AUSENTE",7,5,"ee",15,0,-1,0,194,194,"C-235","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0235-03",3,"La ausencia nunca ha podido\nBorrarte de mi memoria.\nHallándome confundido,\nPenas me has vuelto mis glorias,\nEn los centros del olvido.",3,1,0,31,"AUNQUE DE TI VIVÍA AUSENTE",7,5,"io",101,0,-1,0,195,195,"C-235","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0235-04",3,"¡Dueña de mi corazón!\nQue en tí me tenías grabado,\nY sin tener compasión,\nDel todo me habéis borrado,\nDe entre tu imaginación.",3,1,0,31,"AUNQUE DE TI VIVÍA AUSENTE",7,5,"o",31,0,-1,0,195,195,"C-235","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0235-05",3,"Mi corazón oprimido,\nUna tumba lo ha cubierto,\nPrivándolo del sentido\nPero no habiéndome muerto\nAcuérdate 'que yo he sido.",3,1,0,31,"AUNQUE DE TI VIVÍA AUSENTE",7,5,"io",101,0,-1,0,195,195,"C-235","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0236-01",3,"Ayer me dijiste que hoy,\nHoy me dirás que mañana,\nMañana me has de decir:\nYa se me quitó la gana.",3,1,0,31,"AYER ME DIJISTE QUE HOY",0,4,"aa",4,0,-1,0,195,195,"C-236","",0,"","","",10,0,0,[],""],["carrizo_salta-nc0236-02",3,"No seas variable, mujer,\nMira que mucho te afea,\nY dile a quien te desea,\nCuándo lo piensas querer.\nPara nunca más volver,\nYo de tu lado me voy.\nBien desengañado estoy,\nDe ver que el tiempo perdí,\nQue ibas a darme el sí,\nAyer me dijiste que hoy.",3,1,0,31,"AYER ME DIJISTE QUE HOY",18,10,"o",112,0,-1,0,195,195,"C-236","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0236-03",3,"Dime, ¿cuál es tu pensar\nQué tienes para colmigo?\nPor la fuerza te lo obligo,\nPara poder descansar.\nPaso en continuo penar\nCon una esperanza vana,\nHallo larga la semana,\nEn la vida del tormento,\nSi te cobro el juramento,\nHoy me dirás que mañana.",3,1,0,31,"AYER ME DIJISTE QUE HOY",18,10,"aa",4,0,-1,0,195,195,"C-236","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0236-04",3,"Habéis echado en olvido\nMi fino amor verdadero,\nSiendo que tanto te quiero.\nCumple con lo prometido,\nViéndome de amor herido,\nYo no puedo resistir,\n¿Qué te ganas con mentir?\nEres falsaria, inconstante,\n—Ya tengo otro nuevo amante,\nMañana me has de decir.",3,1,0,31,"AYER ME DIJISTE QUE HOY",18,10,"i",157,0,-1,0,195,195,"C-236","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0236-05",3,"Engañosa sin amor\nTe vas con quien te convida,\nPretendes pasar tu vida\nLo mismo que el picaflor.\nEn nada miras tu honor\nPor llevarte de jarana,\nAl alba y por la ventana,\nFuí a verte yo de prisa,\nMe dijiste con sonrisa:\n—Ya se me quitó la gana.",3,1,0,31,"AYER ME DIJISTE QUE HOY",18,10,"aa",4,0,-1,0,195,195,"C-236","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0236-06",3,"Por último, la coqueta\nNunca ha tenido buen fin,\nVuela como un volantín,\nY con nadie se sujeta\nNi al casado lo respeta\nViéndole que es hombre ajeno,\nSi no hay quien le tire el freno\nLa joven sola se mata,\nPero que en viéndole plata\nA todo le dice: bueno.",3,1,0,31,"AYER ME DIJISTE QUE HOY",18,10,"eo",76,0,-1,0,195,195,"C-236","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0237-01",3,"¡Cansado estoy de vivir\nLa vida que estoy viviendo,\nQue también la vida canta\nSi se vive padeciendo!",3,1,0,31,"CANSADO ESTOY DE VIVIR",0,4,"eo",52,0,-1,0,195,195,"C-237","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0237-02",3,"Todo es penar y sentir\nEn esta ausencia tan larga,\nPues ya no puedo sufrir.\nEsta vida tan amarga,\nCansado estoy de vivir!",3,1,0,31,"CANSADO ESTOY DE VIVIR",7,5,"i",157,0,-1,0,196,196,"C-237","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0238-01",3,"¿Cómo quieres que no sienta\nLa injuria que me habéis hecho?\n¿Cómo he de disimular\nLo que ha sentido mi pecho?",3,1,0,31,"COMO QUIERES QUE NO SIENTA",0,4,"eo",60,0,-1,0,196,196,"C-238","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0238-03",3,"Entre congojas y penas\nDe sentimiento, deshecho,\nNo me es posible olvidar\nLa injuria que me habéis hecho.",3,1,0,31,"COMO QUIERES QUE NO SIENTA",0,4,"eo",60,0,-1,0,196,196,"C-238","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0238-04",3,"El verte en ajenos brazos,\nLa vida me ha de costar,\nEste dolor tan intenso\n¡Cómo he de disimular?",3,1,0,31,"COMO QUIERES QUE NO SIENTA",0,4,"a",21,0,-1,0,196,196,"C-238","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0239-01",3,"¡Cuánto me ha pesado, ingrata,\nTener con vos relación!\nQue me sirva de ejemplar\nPara no tener pasión.",3,1,0,31,"CUANTO ME HA PESADO INGRATA",0,4,"o",31,0,-1,0,196,196,"C-239","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0239-02",3,"Yo fuí constante al quererte,\nY al guardarte lealtad,\nTe dí pruebas de amistad\nDespreciando toda suerte.\nCon decirte que a la muerte,\nNo le temí en ningún rato.\nEn mi pecho a tu retrato,\nTuve como relicario,\nMas ahora veo, al contrario,\n¡Cuánto me ha pesado, ingrata!",3,1,0,31,"CUANTO ME HA PESADO INGRATA",18,10,"aa",-1,0,-1,0,196,196,"C-239","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0239-03",3,"Mil proporciones perdí,\nTan sólo por serte fiel,\nYo por ser hombre de bien,\nQue no halles maldad en mi,\nMas, antes he visto en tí,\nLa falsedad y traición,\nEsto no en mi corazón,\nY es lo que mi pecho siente.\nInfeliz de aquel que intente\nTener con vos relación.",3,1,0,31,"CUANTO ME HA PESADO INGRATA",18,10,"o",31,0,-1,0,196,196,"C-239","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0239-04",3,"Tres mil cosas prometistes,\nY de esto no caes en cuenta,\nTe acordarás que contenta,\nA mis plantas te rendistes,\nY a mi pecho lo elegistes,\nPara sólo a él adorar,\nMas, me has llegado a olvidar,\nSin haberte yo faltado,\nPara no vivir confiado,\nQue me sirva de ejemplar.",3,1,0,31,"CUANTO ME HA PESADO INGRATA",18,10,"a",21,0,-1,0,196,196,"C-239","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0239-05",3,"Tú me has mostrado vileza,\nMe alegro que sea así,\nPara no tener en mí\nQuebraderos de cabeza,\nPorque donde no hay firmeza,\nNo debe haber ocasión.\nDe poner el corazón,\nEn falsarias como vos,\nMás bien que me lleve Dios,\nPara no tener pasión.",3,1,0,31,"CUANTO ME HA PESADO INGRATA",18,10,"o",-1,0,-1,0,196,196,"C-239","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0239-a-01",3,"¡Cuánto me ha pesado, ingrata,\nTener con ti relación!\nQue me sirva de ejemplar\nPa no tener más pasión.",3,1,0,31,"CUANTO ME HA PESADO INGRATA",0,4,"o",31,0,-1,0,197,197,"C-239-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0239-a-02",3,"Yo fuí constante al quererte,\nY te guardaba lealtad,\nEn prueba de voluntad,\nDespreciando toda suerte,\nCon decirte que a la muerte\nNo le temí ningún rato,\nEn mi pecho tu retrato,\nLo tenía de relicario\nAhora lo veo al contrario,\n¡Cuánto me ha pesado, ingrata!",3,1,0,31,"CUANTO ME HA PESADO INGRATA",18,10,"aa",-1,0,-1,0,197,197,"C-239-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0239-a-03",3,"Mil proporciones perdí\nPor vos para serte fiel,\nYo por ser hombre de bien,\nNo vistes maldad en mí,\nPero más se verá en tí,\nFalsedades y traición,\nLo que vé mi corazón\nEs lo que mi pecho siente,\nInfeliz de aquel que intente\nTener con tí relación.",3,1,0,31,"CUANTO ME HA PESADO INGRATA",18,10,"o",31,0,-1,0,197,197,"C-239-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0239-a-04",3,"Dos mil cosas prometiste,\nDe esto no caís en cuenta,\nAcordate que contenta\nA mi pecho le dijiste,\nQue no viva nunca triste,\nQue en él sólo has de morar,\nY me has llegado a olvidar\nSiendo así que tú has faltado.\nPa no vivir más confiado\nQue me sirva de ejemplar.",3,1,0,31,"CUANTO ME HA PESADO INGRATA",18,10,"a",21,0,-1,0,197,197,"C-239-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0239-a-05",3,"Mostraste en todo vileza,\nMás vale que esto sea así,\nPara no tener en mí,\nQuebradero de cabeza,\nPorque donde no hay firmeza,\nNo puede haber ocasión,\nPa poner el corazón,\nEn falsarias como vos,\nMás bien que me mate Dios,\nPa no tener más pasión.",3,1,0,31,"CUANTO ME HA PESADO INGRATA",18,10,"o",-1,0,-1,0,197,197,"C-239-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0240-01",3,"¡Dame el alma que te dí!\nQue el pedirla no es ofensa,\nPorque no quiero que esté,\nDonde no hay correspondencia.",3,1,0,31,"DAME EL ALMA QUE TE DI",0,4,"ea",-1,0,-1,0,197,197,"C-240","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0240-02",3,"Si otro tiene preferencia\nY ocupase mi lugar,\nMe retiraré a una ausencia,\nPuesto que no debo amar.",3,1,0,31,"DAME EL ALMA QUE TE DI",1,4,"a",21,0,-1,0,197,197,"C-240","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0240-03",3,"Yo constante te adoré,\nPongo al cielo por testigo,\nE inocente dígote:\n—Devuélveme mi cariño.",3,1,0,31,"DAME EL ALMA QUE TE DI",0,4,"io",-1,0,-1,0,197,197,"C-240","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0240-04",3,"De tus labios merecí\nEl dulce nombre de amante,\nSupuesto eres inconstante,\n¡Dame el alma que te dí!",3,1,0,31,"DAME EL ALMA QUE TE DI",11,4,"i",23,0,-1,0,197,197,"C-240","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0241-01",3,"Dime dueña la verdad,\n¿Qué motivo u ocasión\nTuvistes para agraviar\nA un rendido corazón?",3,1,0,31,"DIME DUEÑA LA VERDAD",0,4,"o",31,0,-1,0,197,197,"C-241","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0241-02",3,"Así, sólo, me dejaste,\nEn un mar de confusión,\nHas querido a otro dueño,\nAmándote tanto yo.",3,1,0,31,"DIME DUEÑA LA VERDAD",0,4,"o",-1,0,-1,0,197,197,"C-241","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0241-03",3,"Quiérelo porque es tu gusto,\nYa que tanto mereció,\nEse será más dichoso,\nPero más constante, no.",3,1,0,31,"DIME DUEÑA LA VERDAD",0,4,"o",2,0,-1,0,197,197,"C-241","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0241-04",3,"El cielo me ha de vengar\nDel mal pago que me has dado,\nPues en nada te he ofendido\nY sin causa me has dejado.",3,1,0,31,"DIME DUEÑA LA VERDAD",0,4,"ao",14,0,-1,0,197,197,"C-241","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0241-05",3,"Permita el cielo, tirana,\nEscuchar mi maldición,\nQue te mires mal pagada,\nAlma, vida y corazón.",3,1,0,31,"DIME DUEÑA LA VERDAD",0,4,"o",31,0,-1,0,197,197,"C-241","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0242-01",3,"Doce meses tiene el año,\nY así mi querida espero,\nSu pretensión en Enero\nPara ver mi desengaño.\nQue sería muy extraño\nEsperar hasta Febrero,\nSi es que por tu amor me muero\nAl nombrar tan largo plazo,\nHa llegado el mes de Marzo,\nTu contestación espero.",3,1,0,31,"DOCE MESES TiENE EL ASO",18,10,"eo",38,0,-1,0,198,198,"C-242","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0243-04",3,"Te has olvidado de mí,\n¿Qué causa te he dado, dí,\nPara tan gran abandono?\nTú me bajastes del trono\nDonde tan alto me ví.",3,1,0,31,"EN LA TORRE DE MIS GUSTOS",7,5,"i",23,0,-1,0,198,198,"C-243","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0243-05",3,"Claro, le puedes decir,\nAl que ocupa mi lugar,\nQue en no sabiendo subir,\nNo ha de tardar en bajar.\nSe ha de llegar a mirar\nDe su dicha muy escaso,\nConforme le llegue el plazo\nQue de tu vista le borres,\nY le digas que en su torre\nFueron los cimientos falsos.",3,1,0,31,"EN LA TORRE DE MIS GUSTOS",18,10,"ao",-1,0,-1,0,198,198,"C-243","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0243-06",3,"Por fin, cuéntaselo todo\nMas bien, no le digas nada,\nQue en siendo la hora llegada\nSe ha de ver del mismo modo,\nY por esto me acomodo,\nMi propio mal a sufrir,\nQue no se diga de mi\nQue soy, mudable cual tiempo,\nAsí en un rato y momento,\nOtro subió y yo caí.",3,1,0,31,"EN LA TORRE DE MIS GUSTOS",18,10,"i",23,0,-1,0,198,198,"C-243","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0244-01",3,"En tierra estéril sembré\nUn fino amor, ¡ay de mí!\nY el fruto que recogí\nFueron celos que lloré.",3,1,0,31,"EN TIERRA ESTÉRIL SEMBRÉ",11,4,"e",77,0,-1,0,198,198,"C-244","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0244-02",3,"¿De qué sirve en excesivo\nProdigar raro cuidado,\nSi el regar con lo llorado,\nSon golpes en pecho herido?\nVanos fueron mis cultivos,\nMal mi trabajo empleé,\nTodo lo perdí por qué,\nCual infeliz labrador,\nBuena semilla de amor\nEn tierra estéril sembré.",3,1,0,31,"EN TIERRA ESTÉRIL SEMBRÉ",18,10,"e",77,0,-1,0,198,198,"C-244","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0244-03",3,"Habiendo con mil desvelos,\nSembrado un amor tan fino,\nVi que de allí había nacido\nLa cizaña de los celos.\nSe aumentaron mis desvelos,\nYo perdí, sufrí y caí,\nPor ver si lograba así,\nEl fruto de mi trabajo,\nQue tan sólo me contrajo\nUn fino amor ¡ay de mi!",3,1,0,31,"EN TIERRA ESTÉRIL SEMBRÉ",18,10,"i",23,0,-1,0,198,199,"C-244","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0244-04",3,"Después de haber arrancado\nDel suelo unos brotes crueles,\nNacieron verdes laureles,\nDel amor que había quedado.\nEsto aprecia lo mandado,\nPor lo que al momento ví,\nQue dimanaba de allí\nDe mi amor, grandes sospechas,\nEstas fueron las cosechas\nY el fruto que recogí.",3,1,0,31,"EN TIERRA ESTÉRIL SEMBRÉ",18,10,"i",23,0,-1,0,199,199,"C-244","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0244-05",3,"Todo me fué sin provecho\nEn mi constante labor,\nSólo penas y dolor\nHe recogido en mi pecho.\nY hasta he perdido el derecho\nEn lo que tanto afané,\nPues mi vida consagré\nCon entusiasmo risueño,\nY el provecho de mi empeño\nFueron celos que lloré.",3,1,0,31,"EN TIERRA ESTÉRIL SEMBRÉ",18,10,"e",77,0,-1,0,199,199,"C-244","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0245-01",3,"En una te estoy queriendo,\nEn las dos todo mi encanto,\nA las tres, vidita mía,\nMe hallo padeciendo tanto.",3,1,0,31,"EN UNA TE ESTOY QUERIENDO",0,4,"ao",30,0,-1,0,199,199,"C-245","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0245-02",3,"Las cuatro dadas, te advierto,\nY en cinco te hago un pedido,\nA las seis, vidita mía,\nQue no me eches en olvido.",3,1,0,31,"EN UNA TE ESTOY QUERIENDO",0,4,"io",101,0,-1,0,199,199,"C-245","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0245-03",3,"En siete todo mi encanto,\nEn ocho preciosa flor,\nEn nueve no me desprecies,\nMe has de hacer ese favor.",3,1,0,31,"EN UNA TE ESTOY QUERIENDO",0,4,"o",72,0,-1,0,199,199,"C-245","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0246-01",3,"En un panteón de congojas\nMi amor se va a sepultar,\nDe haber muerto por amor,\nEn un sepulcro reposa.",3,1,0,31,"EN UN PANTEÓN DE CONGOJAS",5,4,"oa",-1,0,-1,0,199,199,"C-246","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0246-02",3,"Cuando libre del amor\nGozaba de dulce calma,\nSe vió prisionera mi alma,\nCon cadenas de dolor,\nInsensible a su rigor,\nTantos tormentos me apocan,\nY cual un árbol sin hojas,\nEstoy próximo a expirar,\nY me retiro a llorar\nEn un panteón de congojas.",3,1,0,31,"EN UN PANTEÓN DE CONGOJAS",18,10,"oa",364,0,-1,0,199,199,"C-246","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0246-03",3,"La alegría y el placer\nSe acabaron para mí\nDesde el momento que ví\nLo que no he de merecer,\n¡Mas, ay de mí! ¿qué hi de hacer?\n¿De qué me sirve el gozar\nCuando estoy al expirar\nSólo por haber querido?\nEn el centro del olvido\nMi amor se va a sepultar.",3,1,0,31,"EN UN PANTEÓN DE CONGOJAS",18,10,"a",21,0,-1,0,199,199,"C-246","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0246-06",3,"Por fin, todo se acabó,\nY quedarás convencida,\nAl ver que tu amante, vida,\nLa existencia por ti dió,\nEste infeliz ya murió,\nVive contenta y gustosa,\nPara que alegre y gozosa.\nDigas a los que han vivido,\nQue aquel que más te ha querido\nEn un sepulcro reposa.",3,1,0,31,"EN UN PANTEÓN DE CONGOJAS",18,10,"oa",63,0,-1,0,200,200,"C-246","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0247-03",3,"Es cierto que yo no he sido\nEl que tu flor marchitó,\nNi el que palabra te dió,\nDe ser tu esposo y marido.\nComo ves tu honor perdido,\nHoy hablas sabiendo que\nDtro tu perdición fué,\nY conmigo estás quejosa.\nYo no marchité la rosa\nAunque en el jardín entré.",3,1,0,31,"ES FALSA TU IMPUTACIÓN",18,10,"e",77,0,-1,0,200,200,"C-247","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0247-05",3,"Delante de un santo Cristo\nMe atrevería a jurar,\nNo tengo cuentas que dar\nAnte el tribunal Divino,\nQue el honor que tú has perdido\nEl cómo y cuándo lo sé,\nY lo que te afirmaré,\nPorque lo que digo es cierto,\nQue el hurto que hubo en tu huerto\nDe otro jardinero fué.",3,1,0,31,"ES FALSA TU IMPUTACIÓN",18,10,"e",77,0,-1,0,200,200,"C-247","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0248-01",3,"¿Es posible, cielo amado,\nQue me trates con rigor,\nSi he sufrido por tu amor\nMartirios que no he soñado?\nViéndome en tan triste estado,\nNo te condueles de mí,\n¿Cómo quieres que hasta quí,\nSiga mi desgracia en pos,\nSi hemos de sufrir los dos,\nTú por otro, y yo por tí?",3,1,0,31,"ES POSIBLE CIELO AMADO",18,10,"i",23,0,-1,0,200,200,"C-248","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0248-02",3,"Tú fuísteis juez de mi causa,\nContra mi tirana suerte,\nY con sentencia de muerte\nAumentastes mi desgracia.\nMirá que el tiempo se pasa,\nY sólo espero de tí,\nHasta conseguir el sí.\nVeo con dolor profundo,\nQue sufrimos en el mundo,\nTú por otro, y yo por tí.",3,1,0,31,"ES POSIBLE CIELO AMADO",18,10,"i",23,0,-1,0,200,200,"C-248","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0248-03",3,"Podrá ser, tesoro hermoso,\nEn el mundo aparecido,\nSi a mi corazón herido,\nVienes a darle reposo.\nHacé a este infeliz dichoso,\nCese mi dolor aquí,\nPero si no fuese así,\nY la esperanza perdemos,\nA la tumba bajaremos,\nTú por otro, yo por tí.",3,1,0,31,"ES POSIBLE CIELO AMADO",18,10,"i",23,0,-1,0,200,200,"C-248","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0249-01",3,"Estas lágrimas que lloro,\nPongo delante de Dios,\nAnte el tribunal divino,\nDarás cuentas por los dos.",3,1,0,31,"ESTAS LAGRIMAS QUE LLORO",0,4,"o",87,0,-1,0,201,201,"C-249","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0249-02",3,"Mi honra y mi estimación\nMarchitastes al perderme;\nYo, infeliz llegué a verme,\nCreyendo no eras traidor,\nCogistes la mejor flor,\nDe mi jardín que atesoro,\nHoy me veo sin decoro,\nPor consentir en tu intento,\nY te sirvan de escarmiento\nEstas lágrimas que lloro.",3,1,0,31,"ESTAS LAGRIMAS QUE LLORO",18,10,"oo",85,0,-1,0,201,201,"C-249","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0249-03",3,"Por que si fuese o no fuese,\nNo se lo dije a mi padre,\nAhora, aunque ya sea tarde,\nPues ya en mí la afrenta crece,\n¿Es justo de que siguiese\nMi conducta tan atroz?\nYo me vengaré de vos,\nCon suspiros y clamores,\nPues mis lágrimas y errores\nPongo delante de Dios.",3,1,0,31,"ESTAS LAGRIMAS QUE LLORO",18,10,"o",87,0,-1,0,201,201,"C-249","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0249-04",3,"Con un falso juramento,\nLograste el violentarme,\nDándome para engañarme\nPalabra de casamiento;\nYo que consentí en tu intento,\nRindiéndote mi amor fino,\nHice muy gran desatino,\nY ahora quieres escusarte,\nPues tendrás de ser culpante\nAnte el tribunal Divino.",3,1,0,31,"ESTAS LAGRIMAS QUE LLORO",18,10,"io",199,0,-1,0,201,201,"C-249","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0249-05",3,"Bien lo sabe el Padre Eterno,\nQue es nuestro Dios y testigo;\nCuando estuvistes conmigo,\nTres veces tembló el infierno,\nYo que seguí tu gobierno,\nCon un engaño veloz,\nMe perdistes a mi a Dios\nQue es cuanto hay que perder,\nPor tí lo llegué a ofender,\nDarás cuentas por los dos.",3,1,0,31,"ESTAS LAGRIMAS QUE LLORO",18,10,"o",87,0,-1,0,201,201,"C-249","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0250-02",3,"Años ha que ciego adoro,\nA la luz de nuestro cielo,\nEsperando algún consuelo,\nQue al no conseguirlo lloro.\nEres un rico tesoro,\nA quien procuro estimar;\nTambién tengo de esperar,\nCorrespondencia de amor,\nDime si me harás favor,\n¿O hasta cuándo he de esperar?",3,1,0,31,"HASTA CUANDO HE DE ESPERAR",18,10,"a",-1,0,-1,0,201,201,"C-250","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0250-03",3,"Si tú tienes desconfianza\nEn saber si yo soy firme,\nTú debes de persuadirme,\nQue en tu amor no habrá mudanza,\nY así verás sin tardarza,\nCómo te idolatro tanto,\nTambién verás el quebranto,\nEn que me hallo al verme así,\n¿Por qué me niegas a mí,\nEl alivio, dulce encanto?",3,1,0,31,"HASTA CUANDO HE DE ESPERAR",18,10,"ao",30,0,-1,0,201,201,"C-250","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0250-04",3,"Si es que tienes el intento\nDe abatirme o despreciarme,\nDe una vez desengañadme,\nQue ha de ser menos tormento.\nCada día va en aumento\nMi dolor y mi quebranto,\nY tú, mi vida, mi encanto,\nMi adorado cielo hermoso,\nPudiendo hacerme dichoso,\n¿Por qué me dilatas tanto?",3,1,0,31,"HASTA CUANDO HE DE ESPERAR",18,10,"ao",30,0,-1,0,201,201,"C-250","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0250-05",3,"Tantas penas me molestan,\nY los gustos me demoras,\nPues yo te suplico, ahora,\nNo me niegues la respuesta,\nY si en algo te molesta,\nLo que te vengo a rogar,\nBien me puedes disculpar\nPorque me acerco y te apuro,\nQuiero saber si aseguro\nEl premio que he de gozar.",3,1,0,31,"HASTA CUANDO HE DE ESPERAR",18,10,"a",21,0,-1,0,201,201,"C-250","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0251-01",3,"más a pensar llegué\nle yo de ti me apaltara,\nque tu amor olvidara\nfé con que te adoré.",3,1,0,31,"JAMAS A PENSAR LLEGUE",11,4,"e",77,0,-1,0,202,202,"C-251","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0251-02",3,"h, qué mal hice en quererte!\nh, quién me hubiera avisado\nle mi amor siempre pagado\n¡bía de ser de otra suerte!",3,1,0,31,"JAMAS A PENSAR LLEGUE",11,4,"ee",134,0,-1,0,202,202,"C-251","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0251-03",3,"mi amor siempre ha tenido\ntu pecho su lugar,\nhay razón para arrojar\nque tanto habéis querido.",3,1,0,31,"JAMAS A PENSAR LLEGUE",11,4,"io",101,0,-1,0,202,202,"C-251","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0251-04",3,"i mis brazos me decías,\n\\ vez que en ellos estabas,\níe sólo a mí me adorabas,\níe mi amor no olvida r í a s.",3,1,0,31,"JAMAS A PENSAR LLEGUE",5,4,"",-1,0,-1,0,202,202,"C-251","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0252-01",3,"ibró un amante un diamante,\ntú, divina hermosura,\nis más que un diamante dura,\nue no te ablanda un amante.",3,1,0,31,"ABRO UN AMANTE; UN DIAMANTE",11,4,"ae",47,0,-1,0,202,202,"C-252","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0252-03",3,"on un pulido buril\nabré el acero bruñido;\nCon dibujo muy pulido,\nCon un cincel muy sutil,\nLabré en un blanco marfil,\nHice una bella escultura,\nY si la razón me apura,\nPor defender mi derecho,\nTodo lo labré en mi pecho,\nY tú, divina hermosura.",3,1,0,31,"ABRO UN AMANTE; UN DIAMANTE",18,10,"ua",17,0,-1,0,202,202,"C-252","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0252-04",3,"Ni el mármol con su dureza,\nDe tan variados colores,\nMe negastes tus favores\nAumentando mi tristeza;\nMás ahora, recién me pesa,\nSufriendo las amarguras;\nEstas sí que son locuras,\nNi aún viendo lo que padezco,\nNi un cariño te merezco,\nSois más que un diamante dura.",3,1,0,31,"ABRO UN AMANTE; UN DIAMANTE",18,10,"ua",-1,0,-1,0,202,202,"C-252","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0252-05",3,"Por fin, ni el sol, ni la luna,\nNi el marfil, ni el duro acero,\nNi el buril con que me hiero,\nNi el mármol en su columna,\nNi las piedras de una en una,\nA mí no me dan aguante;\nY así diré a cada instante,\nY por diferentes modos:\nQue sois más dura que todos,\nQue no te ablanda un amante.",3,1,0,31,"ABRO UN AMANTE; UN DIAMANTE",18,10,"ae",47,0,-1,0,202,202,"C-252","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0253-01",3,"La privación de no verte\nA todas horas del día,\nMe da tal melancolía,\nQue ya deseo la muerte.",3,1,0,31,"LA PRIVACIÓN DE NO VERTE",11,4,"ee",134,0,-1,0,202,202,"C-253","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0253-02",3,"Fué tan grande mi pasión,\nY tanto he llegado a amarte,\nQue se me hace poco el darte,\nAlma, vida y corazón.\nTodo es pena y confusión\nEn este trance tan fuerte,\nNingún placer me divierte,\nMi corazón agoniza,\nPero más me martiriza\nLa privación de no verte.",3,1,0,31,"LA PRIVACIÓN DE NO VERTE",18,10,"ee",134,0,-1,0,202,202,"C-253","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0253-03",3,"Creo, que si acaso fueras\nHecha de bronce o diamante,\nTe apiadaras al instante,\nSi llorar por tí me vieras.\nMucha compasión te diera,\nAl mirar la pena mía,\nY con amante porfía,\nVoy tales actos pasando.\nDe tí me estoy acordando\nA todas horas del día.",3,1,0,31,"LA PRIVACIÓN DE NO VERTE",18,10,"ia",0,0,-1,0,203,203,"C-253","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0253-04",3,"Y por todas partes miro,\nPor ver si tu rostro veo,\nY en vano son mis deseos,\nPorque a un imposible aspiro.\nAsí me quejo y suspiro,\nSin encontrar alegría,\nTodo es pena y agonía,\nTodo congoja y pasión,\nAsí con justa razón,\nMe da tal melancolía.",3,1,0,31,"LA PRIVACIÓN DE NO VERTE",18,10,"ia",0,0,-1,0,203,203,"C-253","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0253-05",3,"Por fin, mi bien y mi cielo,\nMi recreo y mi placer,\nNo me hagas más padecer,\nProcura darme consuelo,\nApiádate de mi duelo,\nQue por causa de quererte,\nPadece mi infeliz suerte.\nPreso estoy, en tal estado,\nMe hallo tan desesperado,\nQue ya deseo la muerte.",3,1,0,31,"LA PRIVACIÓN DE NO VERTE",18,10,"ee",134,0,-1,0,203,203,"C-253","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0254-01",3,"Le dirás a ese dichoso,\nQue está gozando de tí,\nQue no viva tan ufano,\nQue donde se vé me ví.",3,1,0,31,"LE DIRÁS A ESE DICHOSO",0,4,"i",23,0,-1,0,203,203,"C-254","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0254-02",3,"Le dirás que ajenos gustos,\nNo me tienen cuidadoso,\nY que venga cuando quiera,\nLe dirás a ese dichoso.",3,1,0,31,"LE DIRÁS A ESE DICHOSO",0,4,"oo",160,0,-1,0,203,203,"C-254","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0254-03",3,"Las disculpas de tu boca\nYa no sirven para mí,\nPorque tus ojos me dicen,\nQue está gozando de tí.",3,1,0,31,"LE DIRÁS A ESE DICHOSO",0,4,"i",23,0,-1,0,203,203,"C-254","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0254-04",3,"Y dile que soy testigo,\nQue en su pasión vive vano,\nQue esos son despojos míos,\nQue no viva tan ufano.",3,1,0,31,"LE DIRÁS A ESE DICHOSO",0,4,"ao",81,0,-1,0,203,203,"C-254","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0254-05",3,"Al fin quédate con él,\nAl mismo tiempo sin mí,\nY no dejes de decirle,\nQue donde se vé, me ví.",3,1,0,31,"LE DIRÁS A ESE DICHOSO",0,4,"i",23,0,-1,0,203,203,"C-254","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0254-a-02",3,"Que sus contínuos halagos,\nNo me tienen cuidadoso,\nY así que viva con gusto,\nLe dirás a ese dichoso.",3,1,0,31,"LE DIRÁS A ESE DICHOSO",0,4,"oo",160,0,-1,0,203,203,"C-254-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0254-a-03",3,"Los favores que le ofreces,\nYa no sirven para mí,\nPorque hace días que sé,\nQue está gozando de tí.",3,1,0,31,"LE DIRÁS A ESE DICHOSO",0,4,"i",23,0,-1,0,203,203,"C-254-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0254-a-05",3,"fin quédate con él,\nil mismo tiempo sin mí,\nno dejes de decirle,\ne donde se vé me ví.",3,1,0,31,"LE DIRÁS A ESE DICHOSO",0,4,"i",23,0,-1,0,204,204,"C-254-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0255-01",3,"s halagos que me hacías,\nué mal, tirana, has cumplido!\namor tan extremado,\nnada se ha convertido.",3,1,0,31,"LOS HALAGOS QUE ME HACÍAS",0,4,"io",101,0,-1,0,204,204,"C-255","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0255-07",3,"Según estaba cegado.\nMás, ¡ay de mí, qué confiado!\nEn el engaño he vivido,\nTarde habiendo conocido,\nEs verdad que con dolor,\nQue tu promesas de amor,\nEn nada se han convertido.",3,1,0,31,"LOS HALAGOS QUE ME HACÍAS",4,7,"io",101,0,-1,0,204,204,"C-255","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0255-a-02",3,"Al principio de tu amor,\nTiernamente me apreciabas,\nY con esto aparentabas\nUn cariño superior.\nYo vivía en el error\nDe que tu amor no fingía,\nAl cabo de pocos días,\nMe hiciste ver ¡oh, tormento!\nQue sólo eran fingimientos\nLos halagos que me hacías.",3,1,0,31,"LOS HALAGOS QUE ME HACÍAS",18,10,"ia",214,0,-1,0,204,204,"C-255-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0255-a-03",3,"Me prometiste constante,\nPagarme tú mis desvelos,\nY que la furia de celos,\nNo afligiría a tu amante.\nPensaba verme triunfante,\nPues me lo habías prometido,\nPero al contrario, han salido,\nTus halagos, tus finezas,\nY olvidando tus promesas,\n¡Qué mal, tirana, has cumplido!",3,1,0,31,"LOS HALAGOS QUE ME HACÍAS",18,10,"io",101,0,-1,0,204,204,"C-255-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0255-a-04",3,"Confiado en tu buena fé,\nTe entregué mi corazón,\nMás tú buscaste ocasión\nDe engañarme cual se vé,\nDime tirana, ¿por qué\nA tu promesa has faltado?\nPero tú no me has amado,\nY en tu pecho fementido,\nNunca jamás ha existido,\nUn amor tan extremado.",3,1,0,31,"LOS HALAGOS QUE ME HACÍAS",18,10,"ao",14,0,-1,0,204,204,"C-255-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0255-a-06",3,"Era mi sueño dorado...\nMás, ¡ay de mí, qué confiado\nEn el engaño he vivido!\nTarde habiendo conocido,\nCon verdad y con dolor,\nQue tu firmeza y amor\nEn nada se ha convertido!",3,1,0,31,"LOS HALAGOS QUE ME HACÍAS",4,7,"io",101,0,-1,0,205,205,"C-255-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0255-b-01",3,"Los halagos que me hacías,\n¡Qué mal, tirana, has cumplido!\nUn amor tan extremado\nEn nada se ha convertido.",3,1,0,31,"LOS HALAGOS QUE ME HACÍAS",0,4,"io",101,0,-1,0,205,205,"C-255-b","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0255-b-02",3,"Al principio de tu amor,\nTiernamente me apreciabas,\nY con esto aparentabas,\nUn cariño superior.\nYo he vivido en el error,\nDe que tu amor no fingía,\nY al cabo de pocos días,\nMe has hecho ver los tormentos,\nQue eran sólo fingimientos,\nLos halagos que me hacías.",3,1,0,31,"LOS HALAGOS QUE ME HACÍAS",18,10,"ia",214,0,-1,0,205,205,"C-255-b","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0255-b-03",3,"Prometistes ser constante\nY pagarme los desvelos,\nQue la fuerza de los celos,\nNo afligirían a tu amante.\nPensaba salir triunfante,\nComo me habías prometido,\nMás, al contrario, ha salido,\nTu cariño y tu firmeza,\nFallastes a tu promesa,\n¡Qué mal, tirana, has cumplido!",3,1,0,31,"LOS HALAGOS QUE ME HACÍAS",18,10,"io",101,0,-1,0,205,205,"C-255-b","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0256-01",3,"Más bien quisiera, bien mío,\nLlorarte muerta en los brazos,\nQue no vida en los ajenos,\nGozando extraños halagos.",3,1,0,31,"MAS BIEN QUISIERA, BIEN MIÓ",0,4,"ao",-1,0,-1,0,205,205,"C-256","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0256-02",3,"Mi discreto resvarío,\nVer tus luces apagadas,\nY no de otros celebrada,\nMás bien quisiera, bien mío.",3,1,0,31,"MAS BIEN QUISIERA, BIEN MIÓ",5,4,"io",3,0,-1,0,205,205,"C-256","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0256-03",3,"Yo viera triste tu ocaso,\nY por no gemirte ajena,\nTuviera en ninguna pena,\nLlorarte muerta en los brazos.",3,1,0,31,"MAS BIEN QUISIERA, BIEN MIÓ",5,4,"ao",-1,0,-1,0,205,205,"C-256","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0256-04",3,"Porque siempre fuera menos\nQue la parca cruel te diera,\nEn mis brazos, muerte fiera,\nQue no vida en los ajenos.",3,1,0,31,"MAS BIEN QUISIERA, BIEN MIÓ",11,4,"eo",365,0,-1,0,205,205,"C-256","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0256-05",3,"Más valiera que hecho lagos\nDe lágrimas estuviesen\nMis ojos y no te viesen\nGozando extraños halagos.",3,1,0,31,"MAS BIEN QUISIERA, BIEN MIÓ",11,4,"ao",366,0,-1,0,205,205,"C-256","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0257-01",3,"Me dirás, querida dueña,\n¿Por qué me has abandonado?\nEn lo fino de tu amor,\n¿Algún tiempo te he faltado?",3,1,0,31,"ME DIRÁS QUERIDA DUEÑA",0,4,"ao",14,0,-1,0,205,205,"C-257","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0257-02",3,"Si porque me ves cautivo,\nMe borras de tu memoria,\nCada día más me acuerdo,\nDe aquellas pasadas glorias.",3,1,0,31,"ME DIRÁS QUERIDA DUEÑA",0,4,"oa",-1,0,-1,0,205,205,"C-257","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0257-03",3,"¿Quién será ese dichoso\nQue ha ocupado mi lugar?\nAdóralo con fineza,\nComo yo te supe amar.",3,1,0,31,"ME DIRÁS QUERIDA DUEÑA",0,4,"a",21,0,-1,0,205,205,"C-257","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0257-04",3,"Mirá, no le des mal pago,\nComo lo has hecho conmigo,\nPagar amor con vileza,\nAl que tanto te ha querido.",3,1,0,31,"ME DIRÁS QUERIDA DUEÑA",0,4,"io",-1,0,-1,0,205,205,"C-257","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0257-05",3,"Ya vez en lo que ha parado\nEse tu amor lisonjero,\nTanto que me asegurartes,\nTú me has faltado primero.",3,1,0,31,"ME DIRÁS QUERIDA DUEÑA",0,4,"eo",38,0,-1,0,205,205,"C-257","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0257-06",3,"mostrastes tiranía,\n\\ que yo te dé motivo,\nhaber sido constante,\né para verme abatido.",3,1,0,31,"ME MOSTRASES TIRANÍA",0,4,"io",-1,0,-1,0,206,206,"C-257","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0257-07",3,"Los caminos se perdieron,\nLos campos se trocaron,\nLas piedras se lamentaron\nCuando el mal pago supieron,\nEntonces, fué que se vieron,\nContemplad, cómo sería,\nQue hasta el mundo se ponía\nCubierto de confusión,\nmirar que sin razón\nMe mostrastes tiranía.",3,1,0,31,"ME MOSTRASES TIRANÍA",18,10,"ia",0,0,-1,0,206,206,"C-257","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0257-09",3,"ce tiempo que notaba\ntu conducta algo extraño,\nro aunque esto me hacía daño,\nnca te lo revelaba,\ncorazón ya esperaba,\nr tu conducta chocante,\nte paso repugnante,\ne has dado sin causa alguna,\nculpa, ha sido sin duda,\nhaber sido constante.",3,1,0,31,"ME MOSTRASES TIRANÍA",18,10,"ae",47,0,-1,0,206,206,"C-257","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0259-01",3,"¡Mira, que soy delicado,\nComo el vidrio de Venecia,\nNo quiero amistad contigo,\nSi hemos de tener pendencia!",3,1,0,31,"MIRA QUE SOY DELICADO",0,4,"ea",-1,0,-1,0,206,206,"C-259","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0259-03",3,"Serás bien correspondida,\nNo te he de ver divertida,\nCon otro, estando a mi lado,\nPuedes vivir con cuidado,\nSiempre temed mis rigores,\nAunque te veas entre flores,\n¡Mira que soy delicado!",3,1,0,31,"MIRA QUE SOY DELICADO",4,7,"ao",14,0,-1,0,206,206,"C-259","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0259-04",3,"¡Mira que soy liberal\nEn todo lo que te ordeno!\nSi de esta manera es bueno\nTu genio y el mío igualar,\nCon ninguno has de parlar\nEn vista y en mi presencia,\nQue si lo hacís en mi ausencia,\nPor eso mismo te aviso,\nMira, que soy quebradizo,\nComo el vidrio de Venecia.",3,1,0,31,"MIRA QUE SOY DELICADO",18,10,"ea",-1,0,-1,0,206,206,"C-259","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0259-05",3,"¡Mira, no has de ser ufana,\nCon nadies has de reñir,\nSolo a misa has de salir,\nUna vez a la semana,\nNo t'hi de ver en ventana,\nSi querís irte conmigo,\nPor eso mismo te digo,\nLo que te declaro aquí,\nY si no quieres así,\nNo quiero amistad contigo.",3,1,0,31,"MIRA QUE SOY DELICADO",18,10,"io",106,0,-1,0,206,206,"C-259","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0259-06",3,"La advertencia siempre es buena,\nComo te quiero advertir,\nQue siempre tendrís de mí,\nAlmuerzo, merienda y cena,\nDe esto no te cause pena,\nRecorre bien la conciencia,\nQue si en eso hay penitencia,\nNo puedas jugar maroma,\nBien está San Pedro en Roma,\nSi hemos de tener pendencia.",3,1,0,31,"MIRA QUE SOY DELICADO",18,10,"ea",46,0,-1,0,206,206,"C-259","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0260-01",3,"¡No me arrebates, dolor,\nEl resto de mi existencia,\nDeja formar con conciencia\nUn testamento de amor!\nDeclaro por mi tutor,\nY mi albacea un tormento,\nDeclaro que en el momento,\nQue sepas que he fallecido,\nPubliques: la causa ha sido:\nTu grande aburrecimiento.",3,1,0,31,"NO ME ARREBATES DOLOR",18,10,"eo",94,0,-1,0,207,207,"C-260","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0260-02",3,"Hoy te dejo por legado,\nA beneficio y favor,\nA todo enfermo de amor,\nEl llanto que he derramado.\nMás un vínculo formado,\nDejo de pura experiencia,\nTodo habido por herencia,\nDe un engañoso placer,\nY de un doble proceder\nO falsa correspondencia.",3,1,0,31,"NO ME ARREBATES DOLOR",18,10,"ea",46,0,-1,0,207,207,"C-260","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0260-03",3,"Cuando cubra el negro manto\nMi cadáver yerto y frío,\nMando que sea conducido\nAl panteón del desengaño,\nNo me hagas tú cabo de año,\nNi se oiga ningún lamento,\nNo quiero yo sentimiento,\nSuspiro, clamor, ni llanto,\nArrojad mi cuerpo al campo,\nY cumple mi testamento.",3,1,0,31,"NO ME ARREBATES DOLOR",18,10,"eo",94,0,-1,0,207,207,"C-260","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0260-04",3,"Muy triste mi muerte fué,\nY ya me hallarás dispuesto,\nSepultado en el feretro,\nQue yo mismo lo labré.\nEscribanos darán fé\nDe mi excesiva inquietud,\nY da testimonio tú,\nQue me vistes expirar.\nEn pago de tanto amar,\nMe mató tu ingratitud.",3,1,0,31,"NO ME ARREBATES DOLOR",18,10,"u",-1,0,-1,0,207,207,"C-260","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0261-01",3,"No sé qué motivo he dado\nPara que de mí te ausentes,\n¿Ya tienes inconvenientes?\n¿Así te lo habrán mandado?",3,1,0,31,"NO SE QUE MOTIVO HE DADO",11,4,"ao",14,0,-1,0,207,207,"C-261","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0261-02",3,"Sabes que quererte aspiro,\nQue te adoro, bien lo sabes,\nAun cuando yo no sé cuál es\nLa causa de tu retiro.\nCon justa razón me admiro\nDe ver tu amor tan trocado,\nTu pecho estará engalado,\nDe ver mi amor permanente,\nPorque hasta lo presente\nNo sé qué motivo he dado.",3,1,0,31,"NO SE QUE MOTIVO HE DADO",18,10,"ao",14,0,-1,0,207,207,"C-261","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0261-03",3,"Yo no acabo de entender\nPor qué me tratas así,\n¿Qué causas hallas en mí\nPara hacerme padecer?\nDí si has llegado a tener\nAlgunos antecedentes,\nDime claro lo que sientes,\nPorque yo en mi corazón,\nNo hallo ninguna razón\nPara que de mí te ausentes.",3,1,0,31,"NO SE QUE MOTIVO HE DADO",18,10,"ee",252,0,-1,0,207,207,"C-261","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0261-04",3,"Pero, ¿qué duda hay en esto?\n¿De qué tengo que admirarme?\nSi sé que para dejarme\nTe vales de este pretexto.\n¡Mira, tirana, qué presto\nVí tus engaños patentes!\nY cómo son evidentes,\nVengo a conocer de ti,\nSi para quererme a mí\nYa tienes inconvenitentes.",3,1,0,31,"NO SE QUE MOTIVO HE DADO",18,10,"ee",252,0,-1,0,207,207,"C-261","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0261-05",3,"Por último, bien se vé,\nY yo claramente miro,\nQue ese tu esquivo retiro,\nNace de tu poca fé.\nYo no hallo razón por qué\nDe mí te hayas retirado,\nQue si tú te has ausentado,\nVoy a creer solamente,\nPorque eres muy obediente,\nO así te lo habrán mandado.",3,1,0,31,"NO SE QUE MOTIVO HE DADO",18,10,"ao",14,0,-1,0,207,207,"C-261","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0261-a-01",3,"No sé qué motivo he dado,\nPara que de mí te ausentes,\n¿Has tenido inconvenientes\nO has tenido algún mandado?",3,1,0,31,"NO SE QUE MOTIVO HE DADO",11,4,"ao",14,0,-1,0,207,207,"C-261-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0261-a-02",3,"Ya ves que a quererte aspiro,\nHoy te adoro, bien lo veo,\nna es que yo no sé,\ncausa de tu retiro,\njustamente me admiro\nver tu amor tan trocado,\nestarís muy enojado,\nver mi amor permanente,\nY yo he estado presente,\nNo sé qué motivo he dado.",3,1,0,31,"NO SE QUE MOTIVO HE DADO",18,10,"ao",14,0,-1,0,207,208,"C-261-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0261-a-03",3,"no acabo de entender,\nqué te mostráis así,\ncausa hallaréis en mí\nPara hacerme padecer,\nllegásteis a entender\nunos antecedentes?\nDime claro lo que sientes,\nPorque yo en mi corazón,\nhallo ninguna razón\nPara que de mí te ausentes.",3,1,0,31,"NO SE QUE MOTIVO HE DADO",18,10,"ee",252,0,-1,0,208,208,"C-261-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0263-01",3,"No te descuides volando,\nPorque te velo durmiendo,\nQue lo que has hecho callando\nSin querer lo voy sabiendo.",3,1,0,31,"NO TE DESCUIDES VOLANDO",1,4,"eo",52,0,-1,0,208,208,"C-263","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0263-02",3,"Bien sabes que en esta vida\nNo hay deuda que no se pague,\nHoy te miras como el ave,\nEn tus glorias divertida;\nPero te advierto, mi vida,\nQue tu amor anda volando,\nLlevas la soga arrastrando\nSin mirarte como vuelas,\nPero tienes centinela,\nNo te descuides volando.",3,1,0,31,"NO TE DESCUIDES VOLANDO",18,10,"ao",33,0,-1,0,208,208,"C-263","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0263-03",3,"Hoy te hallas con gran fortuna,\nGozando entre amenos prados,\nTodos se vuelven cuidados,\nPor tu mala desventura,\nToda la dicha te dura\nMientras vivo padeciendo,\nMis celos le van siguiendo\nLos pasos a tu delito,\nTened presente y escrito,\nPorque te velo durmiendo.",3,1,0,31,"NO TE DESCUIDES VOLANDO",18,10,"eo",52,0,-1,0,208,208,"C-263","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0263-04",3,"Ya lo sé con evidencia,\nQue me has deseado la muerte,\nNo se te cambie la suerte,\nSe te vuelque la sentencia,\nLo sabes con toda ciencia\nQue en tí vivo cavilando,\nEn tus cautelas pensando,\nIngrata, cruel, mal amiga,\n¿Qué más quieres que te diga\nQue lo que has hecho callando?",3,1,0,31,"NO TE DESCUIDES VOLANDO",18,10,"ao",33,0,-1,0,208,208,"C-263","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0264-01",3,"Para divertir mis penas\nYo me crié un pajarillo,\nQue hoy anda de rama en rama\nMendigando extraño nido,\n¡Ay, pajarillo,\nQuien tal hace, que tal pague!\n¡Atención al estribillo!",3,1,0,31,"PARA DIVERTIR MIS PENAS",4,7,"io",228,0,-1,0,209,209,"C-264","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0264-02",3,"Cuántas veces por amarte,\nLloraba de hilo en hilo,\nPor divertir los pesares,\nQue ocasiona un fugitivo.\n¡Ay, pajarillo,\nCon la vara que midieres,\nCon ella has de ser medido!",3,1,0,31,"PARA DIVERTIR MIS PENAS",4,7,"io",-1,0,-1,0,209,209,"C-264","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0264-03",3,"Aquel amoroso lecho\nQue inventé para su abrigo,\nEra de ansias y cariño\nUn funesto entretejido.\n¡Ay, pajarillo,\nNo hay afecto que no canse,\nCon el que es desconocido!",3,1,0,31,"PARA DIVERTIR MIS PENAS",4,7,"io",-1,0,-1,0,209,209,"C-264","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0264-04",3,"No tuve jamás sosiego,\nQue lo diga aquel cariño\nCon que peinaba sus plumas,\nAun cuando estaba dormido.\n¡Ay, pajarillo,\nNo hay amor por despreciable\nQue no se llore perdido!",3,1,0,31,"PARA DIVERTIR MIS PENAS",4,7,"io",-1,0,-1,0,209,209,"C-264","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0264-05",3,"Pero ¿qué hago con quejarme\nDe aqueste desconocido,\nSi sus pasos atestiguan\nLo que ayer hizo conmigo?\n¡Ay, pajarillo,\nSi tú eres mi verdugo,\nOtro será tu cuchillo!",3,1,0,31,"PARA DIVERTIR MIS PENAS",4,7,"io",228,0,-1,0,209,209,"C-264","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0265-01",3,"Por llevarme de tu engaño,\nEché a otro amor en olvido;\nAsí como yo pagué,\nAsí me han correspondido.",3,1,0,31,"POR LLEVARME DE TU ENGAÑO",0,4,"io",101,0,-1,0,209,209,"C-265","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0265-02",3,"Yo descurrí fuese cierto,\nY fué fingido tu halago;\nOtro pilló lo seguro,\nPor llevarme de tu engaño.",3,1,0,31,"POR LLEVARME DE TU ENGAÑO",0,4,"ao",-1,0,-1,0,209,209,"C-265","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0265-03",3,"Pero, como la razón\nPredomina el albedrío,\nPor darte a tí sólo gusto,\nEché otro amor en olvido.",3,1,0,31,"POR LLEVARME DE TU ENGAÑO",0,4,"io",-1,0,-1,0,209,209,"C-265","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0265-04",3,"Pero como obré tan mal,\nCon quien me quería bien,\nMe castigó la razón,\nAsí como yo pagué.",3,1,0,31,"POR LLEVARME DE TU ENGAÑO",0,4,"e",-1,0,-1,0,209,209,"C-265","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0265-05",3,"A quien con tanta constancia\nSe mostraba amante fino,\nLe pagué con injusticia,\nAsí me ha correspondido.",3,1,0,31,"POR LLEVARME DE TU ENGAÑO",0,4,"io",-1,0,-1,0,209,209,"C-265","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0266-01",3,"Precisamente algún día,\nCon las mudanzas del tiempo,\nLlorarás como yo lloro,\nSentirás como yo siento.",3,1,0,31,"PRECISAMENTE ALGÚN DÍA",0,4,"eo",-1,0,-1,0,209,209,"C-266","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0266-02",3,"Esas penas y conflictos\nQue he padecido a porfía,\nTú también padecerás,\nPrecisamente algún día.",3,1,0,31,"PRECISAMENTE ALGÚN DÍA",0,4,"ia",0,0,-1,0,209,209,"C-266","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0266-03",3,"El gusto más complacido\nEn el mundo no está exento,\nQue lo amargue la desgracia,\nCon las mudanzas del tiempo.",3,1,0,31,"PRECISAMENTE ALGÚN DÍA",0,4,"eo",-1,0,-1,0,209,209,"C-266","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0266-04",3,"Si ahora tú eres feliz,\nMientras con pasión imploro,\nLlegarás la vez en qué,\nLlorarás como yo lloro.",3,1,0,31,"PRECISAMENTE ALGÚN DÍA",0,4,"oo",85,0,-1,0,209,209,"C-266","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0266-05",3,"Entonces, pues, sin consuelo,\nEn medio de tu tormento,\nSin esperanza de alivio,\nSentirás como yo siento.",3,1,0,31,"PRECISAMENTE ALGÚN DÍA",0,4,"eo",94,0,-1,0,209,209,"C-266","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0267-02",3,"fin, ingrata has de ser,\na quien tanto te quería;\nNunca había creído que tú\nmal pagues, vida mía.",3,1,0,31,"QUE BIEN HAS CORRESPONDIDO",3,4,"ia",0,0,-1,0,210,210,"C-267","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0268-04",3,"Si en tí no cabe ignorancia,\nY oyes que muriendo vivo,\nSólo por ver si te obligo\nA que te duelas de mí?\n¿Qué motivo tienes, dí,\nPara ser tan cruel conmigo?",3,1,0,31,"QUE CAUSA PUgfiES TENER",9,6,"io",106,0,-1,0,210,210,"C-268","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0268-05",3,"Dime, ¿no eres racional,\nNo tienes entendimiento,\nPor qué viendo mi tormento,\nQuieres que siga mi mal?\n¿Qué corazón de metal\nTienes, mi vida, te digo?\n¿Por qué hacer esto conmigo?\n¿Por qué tanto me maltratas,\nO por qué causa me matas\nSi yo no soy tu enemigo?",3,1,0,31,"QUE CAUSA PUgfiES TENER",18,10,"io",106,0,-1,0,210,210,"C-268","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0268-06",3,"¿No conoces que te adoro?\n¿No echas de ver que te quiero?\n¿No sabes que por tí muero,\nY que por tu crueldad lloro?\n¿No sabes que mi decoro\nConsiste en volverte a ver?\n¿No ves a mi pecho arder\nY que a tus pies estoy puesto?\n¿Cómo, si miras todo esto,\nPor qué me haces padecer?",3,1,0,31,"QUE CAUSA PUgfiES TENER",18,10,"e",20,0,-1,0,210,210,"C-268","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0269-01",3,"¡Qué poca pena te da\nVerme penar por quererte,\nCon mucho sosiego vives,\nSiendo causa de mi muerte!",3,1,0,31,"QUE POCA PENA TE DA",0,4,"ee",134,0,-1,0,210,210,"C-269","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0269-02",3,"¡Qué sensible es mi quebranto!\n¡Qué amargo mi sentimiento!\n¡Qué penoso es mi tormento!\n¡Y qué confuso es mi llanto!\n¿Quién al verme penar tanto\nNo se compadecerá?\n¿A quién no le causará\nLástima mi mal violento?\nY tú que eres mi tormento\n¡Qué poca pena te da!",3,1,0,31,"QUE POCA PENA TE DA",18,10,"a",9,0,-1,0,210,210,"C-269","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0269-03",3,"¡Qué poco estimas mi amor!\n¡Con qué desprecios me miras!\n¡Con qué rigor te retiras\nA fuerza de mi dolor!",3,1,0,31,"QUE POCA PENA TE DA",11,4,"o",72,0,-1,0,210,210,"C-269","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0269-04",3,"Dime, ¿No será mejor,\nIngrata, darme la muerte,\nY no verme de esta suerte\nPadeciendo un mal injusto?\nMás, ¿no lo harás por tu gusto\nVerme penar por quererte?",3,1,0,31,"QUE POCA PENA TE DA",9,6,"ee",134,0,-1,0,211,211,"C-269","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0269-05",3,"Cuando un doliente padece\nDe una gran enfermedad,\nDarle la muerte es piedad,\nPorque el morir apetece.\nPero en tí la impiedad crece,\nCuando mis quejas recibes,\nY cuando más apercibes,\nEl eco de mi dolor\nComo negando el favor\nCon mucho sosiego vives.",3,1,0,31,"QUE POCA PENA TE DA",18,10,"ie",367,0,-1,0,211,211,"C-269","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0269-06",3,"Finalmente, dueña mía,\nDarme la muerte pretendes,\nPorque cuando más me ofendes,\nTe quiero más todavía.\nAsí te digo a porfía,\nQue mi destino es quererte,\nY así puedo encarecerte\nCon mi pasión abatida,\nQue eres precio de mi vida,\nSiendo causa de mi muerte.",3,1,0,31,"QUE POCA PENA TE DA",18,10,"ee",134,0,-1,0,211,211,"C-269","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0270-01",3,"Que sí, que no, que sería...\nQue hoy, que mañana, que ayer...\nQue ahora, que luego, que cuando...\nNi el diablo te va a entender.",3,1,0,31,"QUE SI, QUE NO; QUE SERIA.",0,4,"e",20,0,-1,0,211,211,"C-270","",0,"","","",5,0,0,[],""],["carrizo_salta-nc0270-02",3,"Tan pronto dices que sí,\nTan pronto dices que no,\nLuego infieres de que yo\nMe estoy burlando de tí.\nPero más vale, decí,\nSi quieres o no ser mía,\nNo me tengas todo el día:\nQue tengo mucho recelo,\nQue quedo yo como el suelo,\nQue sí, que no, qué sería...",3,1,0,31,"QUE SI, QUE NO; QUE SERIA.",18,10,"ia",0,0,-1,0,211,211,"C-270","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0270-03",3,"Me muestras rostro risueño,\nCon equívocos me pagas,\nMe aborreces y me halagas,\nPero no me haces tu dueño.\nAl fin, me dirás tu empeño,\nAcaba de responder,\nPara que pueda tener\nAlivio en mi pena fiera;\nPorque en tu verdad se encierra,\nQue hoy, que mañana, que ayer...",3,1,0,31,"QUE SI, QUE NO; QUE SERIA.",18,10,"e",20,0,-1,0,211,211,"C-270","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0270-04",3,"Si amoroso a verte llego,\nRespondes sobresaltada:\nQue ahora estoy muy ocupada,\nQue anda vete, vuelve luego,\nEn este desasosiego,\nEl tiempo se va pasando,\nY yo me voy acabando\nCuando me dices que aguarde,\nQue a la noche, que a la tarde,\nQue ahora, que luego que cuando.",3,1,0,31,"QUE SI, QUE NO; QUE SERIA.",18,10,"ao",33,0,-1,0,211,211,"C-270","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0270-05",3,"En fin, para terminar,\nSin que a las vueltas andemos,\nAquí de una vez quedemos,\nEn lo que hemos de quedar;\nPorque con que hoy no hay lugar,\nQue entro un rato has de volver,\nCon que ahora no puede ser,\nQue no me dejan salir,\nCon hacerme ir y venir,\nNi el diablo te va a entender.",3,1,0,31,"QUE SI, QUE NO; QUE SERIA.",18,10,"e",20,0,-1,0,211,211,"C-270","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0271-01",3,"Retírese el infeliz,\nPara que goce el dichoso;\nMás vale caer en gracia\nQue ser a fuerza gracioso.",3,1,0,31,"RETÍRESE EL INFELIZ",0,4,"oo",160,0,-1,0,211,211,"C-271","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0271-02",3,"Aquel que ha servido menos,\nEs el más merecedor,\nDe gloria goza y de honor,\nCon cariño y con desvelo;\nCuando yo con grande anhelo,\nTanto tiempo le serví,",3,1,0,31,"RETÍRESE EL INFELIZ",9,6,"i",-1,0,-1,0,211,211,"C-271","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0271-06",3,"Así, por esta razón,\nEl hombre debe palpar,\nEl sabio tome ejemplar,\nEl estudiante lección.\nAtienda y ponga atención\nDe este suceso horroroso;\nDeje gozar al dichoso,\nNo haga extremo ni desvío,\nQue no hay mayor desvarío\n'Que ser a fuerza gracioso\".",3,1,0,31,"RETÍRESE EL INFELIZ",18,10,"oo",160,0,-1,0,212,212,"C-271","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0272-01",3,"Sin darme ningún consuelo,\nVivo de veras amando;\nDime, mi bien, ¿hasta cuándo\nSufriré tanto desvelo?",3,1,0,31,"SIN DARME NINGÚN CONS",11,4,"eo",10,0,-1,0,212,212,"C-272","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0272-02",3,"Por amarte casi he muerto\nCon el más largo tormento,\nDándote de sobra tiempo\nPara decirme lo cierto.\nQuiero quede descubierto\nEste, mi amor verdadero,",3,1,0,31,"SIN DARME NINGÚN CONS",9,6,"eo",-1,0,-1,0,212,212,"C-272","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0272-03",3,"Porque veas que te quiero,\nTe doy pruebas y señales,\nY tú me envuelves en males,\nSin darme ningún consuelo.",3,1,0,31,"SIN DARME NINGÚN CONS",5,4,"eo",-1,0,-1,0,212,212,"C-272","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0272-04",3,"Mi bien, no es ponderación\nLo que te voy a decir,\nQue dejaré de vivir\nPor darte mi corazón.\nSi mi amorosa pasión,\nLa vida me va quitando,\n¿Por qué me vas aumentando\nCada vez más mi dolor,\nCuando a ti, preciosa flor,\nVivo de veras amando?",3,1,0,31,"SIN DARME NINGÚN CONS",18,10,"ao",33,0,-1,0,212,212,"C-272","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0272-05",3,"Lo que más me martiriza\nEn mi vida, es el saber\nSi tú me piensas querer,\nQue es lo que más me precisa,\nPero el corazón me avisa\nQue me tienes engañando.\nNo me tengas demorando,\nEl consuelo que pretendo,\nSi he de vivir padeciendo,\nDime, mi bien, ¿hasta cuando?",3,1,0,31,"SIN DARME NINGÚN CONS",18,10,"ao",33,0,-1,0,212,212,"C-272","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0272-06",3,"Mil inconvenientes pones,\nSin tener ni un contratiempo,\nPuedes decirme al momento,\nSi amarme tú te dispones,\nO ¿qué es lo que te propones\nDilatando así mi anhelo?\nDime, pronto y sin recelo,\nQue ya no puedo esperar,\n¿Hasta cuándo, sin cesar,\nSufriré tanto desvelo?",3,1,0,31,"SIN DARME NINGÚN CONS",18,10,"eo",10,0,-1,0,212,212,"C-272","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0273-01",3,"Si no me das posesión,\nQue pido, según derecho,\nAlego fraude en tu pecho,\nProtestando apelación.",3,1,0,31,"SI NO ME DAS POSESIÓN",11,4,"o",31,0,-1,0,212,212,"C-273","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0273-02",3,"¿Qué importa que mi pasión\nAdore a tu cielo esquivo?\nViviré siempre contigo,\nSi no me das posesión.",3,1,0,31,"SI NO ME DAS POSESIÓN",5,4,"o",31,0,-1,0,212,212,"C-273","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0273-03",3,"Gozar de tu noble pecho,\nSerá mi única delicia,\nEsta es, mi bien, la justicia\nQue pido según derecho.",3,1,0,31,"SI NO ME DAS POSESIÓN",11,4,"eo",60,0,-1,0,212,213,"C-273","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0273-04",3,"Y si viéndome deshecho,\nAún sigue vuestro rigor,\nPor las leyes del amor,\nAlego fraude en tu pecho.",3,1,0,31,"SI NO ME DAS POSESIÓN",11,4,"eo",60,0,-1,0,213,213,"C-273","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0273-05",3,"Y si al fin, tu sinrazón,\nSin motivo mal me trata,\nTe diré que eres ingrata,\nProtestando apelación.",3,1,0,31,"SI NO ME DAS POSESIÓN",11,4,"o",31,0,-1,0,213,213,"C-273","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0274-01",3,"Si se va los dos nos vamos,\nYo no me quiero quedar,\nPorque si me quedo sé\nQue tú me vas a olvidar.",3,1,0,31,"SI SE VA, LOS DOS NOS VAMOS",0,4,"a",21,0,-1,0,213,213,"C-274","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0274-02",3,"En la tristeza sumido,\nCon un dolor importuno,\nHoy sin remedio ninguno,\nMe vas a echar en olvido.\nPero como he conocido,\nQue en de veras nos amamos,\nSi nuestro amor separamos,\nSentirá mi corazón;\nPara mejor ocasión,\nSi se va, los dos nos vamos.",3,1,0,31,"SI SE VA, LOS DOS NOS VAMOS",18,10,"ao",116,0,-1,0,213,213,"C-274","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0274-03",3,"Si yo supiera de cierto\nQue en su pecho me llevara,\nDesde luego me quedara,\nCon mucho gusto y contento.\nPero sé que en el momento\nQue te llegues a ausentar,\nDe mí no te has de acordar,\nSerá un dolor para mí,\nPara no llorar por tí,\nYo no me quiero 'quedar.",3,1,0,31,"SI SE VA, LOS DOS NOS VAMOS",18,10,"a",21,0,-1,0,213,213,"C-274","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0275-01",3,"Suspirando me amanezco,\nDespués de intranquilo sueño,\nQue con extremado empeño,\nConciliario no merezco.",3,1,0,31,"SUSPIRANDO ME AMANEZCO",11,4,"eo",-1,0,-1,0,213,213,"C-275","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0275-02",3,"Mi dolor aumenta presto,\nY desecharlo no puedo,\nEl sol se me eclipsa luego\nEn tinieblas paso el día,\nY en tan penosa agonía,\nMe abrazo en terrible fuego.",3,1,0,31,"SUSPIRANDO ME AMANEZCO",9,6,"eo",29,0,-1,0,213,213,"C-275","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0275-03",3,"Para más atormentarme,\nY aumentar más mi dolor,\nLa ingratitud de tu amor,\nViene del sueño a apartarme,\nY en este insomnio a matarme.\nMe acuerdo de quién amé,\nAún que sin saber por qué,\nHay veces que a mi pesar,\nNo me quisiera acordar\nDe quien nunca olvidaré.",3,1,0,31,"SUSPIRANDO ME AMANEZCO",18,10,"e",77,0,-1,0,213,213,"C-275","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0275-04",3,"Este mi fatal destino\nQue sigues con tanto anhelo,\nMe ha privado del consuelo,\nDe verme correspondido.\nMi corazón afligido\nLlora sin hallar remedio,\nMuchas veces en el medio,\nDe tanta melancolía,\nEs tan cruel la suerte mía,\nQue verte ni hablarte puedo.",3,1,0,31,"SUSPIRANDO ME AMANEZCO",18,10,"eo",-1,0,-1,0,213,213,"C-275","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0275-05",3,"No hallo cosa que me agrade,\nFeliz no soy un momento,\nY el más fiero sentimiento\nA mi corazón invade.\nEn esta vida sin clave,\nMi espíritu vive inerme,\nSalgo al campo a entretenerme,\nBusco lo que tanto anhelo,\nY no encuentro más consuelo\nQue cuando mi cuerpo duerme.",3,1,0,31,"SUSPIRANDO ME AMANEZCO",18,10,"ee",245,0,-1,0,213,213,"C-275","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0276-01",3,"Teniendo el bien en la mano,\nNo lo quisistes lograr,\nDespués tendrás que llorar,\nCuando conozcas tu engaño.",3,1,0,31,"TENIENDO EL BIEN EN LA MANO",5,4,"ao",-1,0,-1,0,213,213,"C-276","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0276-02",3,"Yo me puse a trabajar\nCon el corazón contento,\nPara verte en algún tiempo\nLlena de felicidad.",3,1,0,31,"TENIENDO EL BIEN EN LA MANO",5,4,"a",-1,0,-1,0,213,214,"C-276","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0276-03",3,"Pero tu infidelidad\nMe ha puesto en tanto desgano,\nQue ahora es pensar en vano,\nEsperar de florecer,\nPorque dejastes perder,\nTeniendo el bien en la mano.",3,1,0,31,"TENIENDO EL BIEN EN LA MANO",9,6,"ao",81,0,-1,0,214,214,"C-276","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0276-04",3,"Cuando tu familia y vos\ne murmuren sin sentir,\nas han de contradecir\nQuien nos conozca a los dos.\nDe sobra testigo es Dios,\nQue en nada supe faltar,\nMi amor pensé en realizar\nCon la mayor buena fé,\nMás tú sabrás el por qué\nNo lo quisistes lograr.",3,1,0,31,"TENIENDO EL BIEN EN LA MANO",18,10,"a",21,0,-1,0,214,214,"C-276","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0276-a-01",3,"Pero tu indocilidad\nMe ha puesto en tanto desgano,\nQue ahora es pensar en vano,\nQue vuelvas a florecer,\nPorque dejastes perder\nTeniendo el bien en las manos.",3,1,0,31,"",9,6,"ao",-1,0,-1,0,214,214,"C-276-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0277-01",3,"Tú eres un jardín florido,\nEn quien se fijó mi amor,\nTe prometo, hermosa flor,\nEl no quitarte el sentido.",3,1,0,31,"TU ERES UN JARDÍN FLORIDO",11,4,"io",101,0,-1,0,214,214,"C-277","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0277-03",3,"Muchos días son fatales,\nQue ando en vuestro seguimiento,\nPara decirte mi intento,\nMi vida, quisiera hablarte.\nDadme el lugar si lo quieres,\nDonde podré conversarte!",3,1,0,31,"TU ERES UN JARDÍN FLORIDO",9,6,"ae",8,0,-1,0,214,215,"C-277","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0277-05",3,"Si me quieres, vida mía,\nTe prometo el adorarte,\nYo seré tu fiel amante,\nTu adorable compañía.",3,1,0,31,"TU ERES UN JARDÍN FLORIDO",5,4,"ia",0,0,-1,0,215,215,"C-277","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0277-07",3,"Así mira, vida mía,\nCon un dolor infinito,\nDuélete de un pobrecito\nQue hoy pretende el adorarte.",3,1,0,31,"TU ERES UN JARDÍN FLORIDO",5,4,"ae",-1,0,-1,0,215,215,"C-277","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0278-01",3,"Tu mala correspondencia,\nEn tal estado me ha puesto,\nQue me parece que presto\nAacabará mi existencia.\nYa no tengo resistencia,\nAún el sepulcro estoy viendo,\nCuando yo muy bien comprendo,\nQue fué mi gloria el quererte,\nDame siquiera la muerte,\nSi con mi amor yo te ofendo.",3,1,0,31,"TU MALA CORRESPONDENCIA",18,10,"eo",52,0,-1,0,215,215,"C-278","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0278-02",3,"Predestinado nací\nPor el cielo y firmamento,\nY principió mi tormento,\nDesde el día en que te ví,\nMás dime, ¿en qué os ofendí\nCuando me voy esforzando?\nTe dije: —os estoy amando,\nPor tí me daré la muerte,\nY no quieres convencerte,\nPasiones vamos tocando.",3,1,0,31,"TU MALA CORRESPONDENCIA",18,10,"ao",33,0,-1,0,215,215,"C-278","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0278-03",3,"Pero, en mi triste dolor,\nSiempre más te he de querer,\nPues no pienso aborrecer,\nA quien tengo tanto amor.\nY aunque muera a tu rigor,\nMira bien, mi pecho helado,\nSucumbiré abandonado,\nA mi dolor tan profundo,\nPero, ay, ¡qué triste, en el mundo,\nMorir por haber amado.",3,1,0,31,"TU MALA CORRESPONDENCIA",18,10,"ao",14,0,-1,0,215,215,"C-278","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0278-04",3,"Ya exhaló el último aliento,\nY en el mismo aquel instante,\nEl placer de ser tu amante,\nSe ahoga en mi sentimiento,\nY he de proseguir mi intento,\nAunque tus planes entiendo,\nY te he de seguir queriendo,\nAunque sufra tantos males,\nSufriendo penas mortales,\nPues me estás aborreciendo.",3,1,0,31,"TU MALA CORRESPONDENCIA",18,10,"eo",52,0,-1,0,215,215,"C-278","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0278-06",3,"Más valiera el padecer\nEn un infierno abrasado,\nQue el corazón desgarrado,\nTener por un sentimiento,\nPorque es el mayor tormento\nAmar y no ser amado.",3,1,0,31,"TU MALA CORRESPONDENCIA",9,6,"ao",14,0,-1,0,215,215,"C-278","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0278-07",3,"Porque fiel mi corazón\nIdolatró tu hermosura,\nMe diste cruel amargura,\nSin tenerme compasión.\nYa que yo por mi pasión,\nTanto dolor he pasado,\nYa que soy tan desgraciado,\nPor tí, ingrata, por quien muero,\nSólo en esta vida quiero\nMorir viviendo olvidado.",3,1,0,31,"TU MALA CORRESPONDENCIA",18,10,"ao",14,0,-1,0,215,215,"C-278","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0279-01",3,"n amor disimulado,\n'e tengo en mi corazón,\nJo te digo mi intención,\n'or no verme despreciado.",3,1,0,31,"",11,4,"ao",14,0,-1,0,216,216,"C-279","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0279-04",3,"No podrás imaginarte\nCuánto mi pecho te adora,\nQue lamento hora por hora,\nEl momento de mirarte,\nSiendo esta causa el amarte\nCon tanta exageración,\nCuando tú sin compasión,\nMe miras indiferente,\nPor tu amor tan inclemente\nNo te digo mi intención.",3,1,0,31,"",18,10,"o",31,0,-1,0,216,216,"C-279","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0279-05",3,"El dolor más insufrible\nQue en el mundo puede haber,\nEs atreverse a querer,\nLo que se viera imposible.\nEsta congoja terrible,\nTiene a mi pecho embargado,\nDel tuyo está apasionado,\nY como imposibles halla,\nEncubre su pena y calla\nPorque se vé despreciado.",3,1,0,31,"",18,10,"ao",14,0,-1,0,216,216,"C-279","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0279-06",3,"Días ha que estoy sintiendo\nUn fuego en el pecho mío,\nQue lo apaga tu desvío,\nCuando yo mejor lo enciendo,\nAsí es que en esto comprendo,\nQue yo no soy de tu agrado,\nMe contemplo precisado,\nA desimular mi amor,\nAunque no hay tormento peor\nQue un amor desimulado.",3,1,0,31,"r»TAS HA QUE ESTOY SINTIENDO",18,10,"ao",14,0,-1,0,216,216,"C-279","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0279-07",3,"A veces también recibo\nMuestras de tu indignación,\nEs tan grande mi pasión,\nQue tus rigores aprecio,\nPorque un amor con exceso\nTe tiene mi corazón.",3,1,0,31,"r»TAS HA QUE ESTOY SINTIENDO",9,6,"o",31,0,-1,0,216,216,"C-279","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0280-01",3,"Un corazón lastimado,\nDespide tiernos lamentos,\nSin saber el fundamento\nPor qué se ve despreciado.",3,1,0,31,"UN CORAZÓN LASTIMADO",5,4,"ao",14,0,-1,0,216,216,"C-280","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0280-02",3,"Dime, mi bien, ¿por qué hieres\nA un corazón inocente\nQue te adora eternamente?\nO que te adore ¿no quieres?\nDime la razón que tienes,\nO ¿en qué mi amor te ha faltado?\n¿Qué motivo hay, cielo amado?\n¿Por qué me haces padecer?\nO ¿no te consterna el ver\nUn corazón lastimado?",3,1,0,31,"UN CORAZÓN LASTIMADO",18,10,"ao",14,0,-1,0,216,216,"C-280","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0280-03",3,"Si en mi lugar te pusieras,\nY yo me hiciera inconstante,\nEn el más ligero instante,\nQué cosa es dolor, supieras,\nY mis penas conocieras,\nPasando por tí tormentos\nY mí duro abatimiento.\nVieras que mi corazón,\nCon duplicada razón\nDespide tiernos lamentos.",3,1,0,31,"UN CORAZÓN LASTIMADO",18,10,"eo",-1,0,-1,0,216,217,"C-280","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0280-04",3,"Yo he sido firme al amarte,\nComo tú muy bien lo sabes,\nEn nada he sido variable,\nSiempre te he sido constante,\nNunca he mudado a otra parte,\nMi amor ni mi pensamiento.\nY tú con desabrimiento\nMe pagas lo que te adoro,\nAsí yo, inocente lloro,\nSin saber el fundamento.",3,1,0,31,"UN CORAZÓN LASTIMADO",18,10,"eo",94,0,-1,0,217,217,"C-280","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0280-05",3,"Si por otro amor me dejas,\nSepultado en el olvido,\nVengará el cielo divino,\nCuando aperciba mis quejas,\nSi injustamente te alejas,\nDe quien tanto te ha adorado,\nDime ¿por qué has agraviado\nEste corazón amante?\nSiendo tan fiel y constante,\n¿Por qué se ve despreciado?",3,1,0,31,"UN CORAZÓN LASTIMADO",18,10,"ao",14,0,-1,0,217,217,"C-280","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0281-01",3,"Un terrible sentimiento\nMe marchita el corazón.\nDesde que mal me has pagado,\nSin motivo ni razón.",3,1,0,31,"UN TERRIBLE SENTIMIENTO",0,4,"o",31,0,-1,0,217,217,"C-281","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0281-02",3,"Si yo, con llorar pudiera\nRemediar las penas mías,\nMi llanto no cesaría,\nHasta que alivio tuviera.\nQue te conmuevas quisiera\nDe mi dolor y tormento.\nPermita mi mal violento\nQue en tal estado te veas,\nPorque mi pecho posea,\nUn terrible sentimiento.",3,1,0,31,"UN TERRIBLE SENTIMIENTO",18,10,"eo",94,0,-1,0,217,217,"C-281","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0281-03",3,"Con verdad voy a decir,\nQue te quise con extremo,\nQue ni a la muerte le temo\nEl que me quite el vivir,\nPorque no siento el morir\nEn esta grande aflicción.\nPara mí no hay diversión,\nYa no hay placer ni alegría,\nPorque la melancolía\nMe marchita el corazón.",3,1,0,31,"UN TERRIBLE SENTIMIENTO",18,10,"o",31,0,-1,0,217,217,"C-281","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0281-04",3,"¡Ingrata, tienes valor\nPara resentirme el alma!\nVivo en la más dura calma\nViendo en tí tanto rigor.\nCon un empeño mayor\nTus desdenes me han postrado,\nAl ver mi amor desgraciado,\nNo sé los gustos del mundo,\nTriste vivo y me confundo,\nDesde que mal me has pagado.",3,1,0,31,"UN TERRIBLE SENTIMIENTO",18,10,"ao",14,0,-1,0,217,217,"C-281","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0282-01",3,"Vivo en tormentos, ingrata,\nPor tu mucha tiranía,\nLo que me haces padecer,\nLo has de llorar algún día.",3,1,0,31,"VIVO EN TORMENTOS, INGRATA",0,4,"ia",0,0,-1,0,217,217,"C-282","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0282-02",3,"Tu mucho desdén me mata\nY me procura la muerte,\nUn sepulcro me arrebata,\nY así sólo por quererte\nVivo en tormentos, ingrata.",3,1,0,31,"VIVO EN TORMENTOS, INGRATA",7,5,"aa",74,0,-1,0,217,217,"C-282","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0282-03",3,"Qué parca es la suerte mía,\nY ¡ay, qué mucha es tu indolencia!\nSi así dura más un día,\nConcluirá con mi existencia.\nPor tu mucha tiranía.",3,1,0,31,"VIVO EN TORMENTOS, INGRATA",7,5,"ia",0,0,-1,0,217,217,"C-282","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0282-04",3,"¿Hasta cuándo quieres ver,\nQue por tí padezca más?\nY el delito es el querer.\nCon el tiempo lo verás\nLo que me haces padecer.",3,1,0,31,"VIVO EN TORMENTOS, INGRATA",7,5,"e",20,0,-1,0,217,217,"C-282","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0282-05",3,"Yo sólo amante podría\nSobrellevar tu rigor,\nPor fin, ¡adiós, alma mía!\nSi sabes lo que es amor\nLo has de llorar algú ndía.",3,1,0,31,"VIVO EN TORMENTOS, INGRATA",7,5,"ia",0,0,-1,0,217,217,"C-282","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0284-02",3,"Yo mismo busqué mi mal,\nYo labré mi precipicio,\nY en la escala de mis males,\nNo desconozco el principio.",3,1,0,31,"",0,4,"io",-1,0,-1,0,218,218,"C-284","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0284-03",3,"Me cuento por desgraciado,\nSegún mi mal, sin remedio,\nAl mirar que no consigo,\nNi el más pequeño consuelo.",3,1,0,31,"",0,4,"eo",-1,0,-1,0,218,218,"C-284","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0284-04",3,"¡Ay, qué vida tan fatal\nEn este mundo traidor!\nQue vivo tan engañado,\nPor una ciega pasión.",3,1,0,31,"",0,4,"o",-1,0,-1,0,218,218,"C-284","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0284-05",3,"Al mirar tus bellos ojos,\nPuse toda mi afición,\nSabiendo que no hay quién pague,\nLas finezas del amor.",3,1,0,31,"",0,4,"o",-1,0,-1,0,218,218,"C-284","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0284-06",3,"Esta es la causa que lloro\nEn este mundo traidor,\n¡Maldita la hora que quise\nA quién no me tuvo amor!",3,1,0,31,"",0,4,"o",72,0,-1,0,218,218,"C-284","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0284-07",3,"\"Amarguras he tomado,\nQue hasta la hiel he bebido,\nY encuentro que es más amargo\nQuerer y no ser querido\".",3,1,0,31,"",0,4,"io",101,0,-1,0,218,218,"C-284","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0284-08",3,"A esta deuda me la debes,\nAndando la has de pagar\nCon otro que no te quiera\nNi te tenga voluntad.",3,1,0,31,"YA QUE ESTE MUNDO ABANDONO",0,4,"a",-1,0,-1,0,218,218,"C-284","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0286-01",3,"Yo he sembrado una pasión,\nY he cosechado un olvido,\nHe regado una esperanza,\nY un mal pago ha producido.",3,1,0,31,"YO HE SEMBRADO UNA PASIÓN",0,4,"io",101,0,-1,0,218,218,"C-286","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0286-02",3,"Como cruel y muy tirana\nMe has herido el corazón,\nMás yo, con mis propias manos,\nHe sembrado una pasión.",3,1,0,31,"YO HE SEMBRADO UNA PASIÓN",0,4,"o",31,0,-1,0,218,218,"C-286","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0286-04",3,"Creció la planta abundante,\nY sus ramas me han herido,\nComo he sembrado en Otoño,\nHe cosechado un olvido.",3,1,0,31,"YO HE SEMBRADO UNA PASIÓN",0,4,"io",101,0,-1,0,219,219,"C-286","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0286-05",3,"Me hieren todos los males,\nY nunca encuentro bonanza,\nCon lágrimas de mis ojos,\nHe regado una esperanza.",3,1,0,31,"YO HE SEMBRADO UNA PASIÓN",0,4,"aa",163,0,-1,0,219,219,"C-286","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0286-06",3,"Sólo me resta el morir,\nLa culpa yo la he tenido,\nSembré en tu pecho inhumano,\nY un mal pago ha producido.",3,1,0,31,"YO HE SEMBRADO UNA PASIÓN",0,4,"io",101,0,-1,0,219,219,"C-286","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0287-01",3,"Yo no sé qué me habrás hecho,\nPara que te quiera tanto,\nSin duda que algún encanto,\nTendrás oculto en tu pecho.",3,1,0,31,"YO NO SE QUE ME HABRÁS HECHO",11,4,"eo",60,0,-1,0,219,219,"C-287","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0287-02",3,"Yo me llegué ciego al lecho\nA adorarte con empeño,\nIgnorando que veneno\nTenías oculto en tu pecho.",3,1,0,31,"YO NO SE QUE ME HABRÁS HECHO",0,4,"eo",-1,0,-1,0,219,219,"C-287","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0287-03",3,"A otras regiones me iré\nA buscar mi soledad,\nInter mi infelicidad\nTu ingratitud lloraré.",3,1,0,31,"YO NO SE QUE ME HABRÁS HECHO",11,4,"e",77,0,-1,0,219,219,"C-287","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0287-04",3,"Allí me consumiré\nSin la menor esperanza,\nSupuesto que allá no alcanza\nEl poder de quien amé.",3,1,0,31,"YO NO SE QUE ME HABRÁS HECHO",11,4,"e",77,0,-1,0,219,219,"C-287","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0288-01",3,"Yo tuve una chinitilla,\nMuchos años la serví,\nDe verme tan abatido,\nPara otras tierras me fuí.",3,1,0,31,"YO TUVE UNA CHINITILLA",0,4,"i",23,0,-1,0,219,219,"C-288","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0288-02",3,"Y por ahí en lo que anduve,\nMe acordé lo que perdí,\nLa pobre de mi chinita,\n¿Si se acordará de mí?",3,1,0,31,"YO TUVE UNA CHINITILLA",0,4,"i",23,0,-1,0,219,219,"C-288","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0288-03",3,"A mis amigos pregunto,\nDesde el principio hasta el fin,\n¿A dónde han visto una prenda\nQue dejé cuando me fuí?",3,1,0,31,"YO TUVE UNA CHINITILLA",0,4,"i",-1,0,-1,0,219,219,"C-288","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0288-04",3,"Uno de ellos me contesta:\n—Ya se halla en otro poder,\nDivertida en otros brazos,\nYa no se acuerda de usted.",3,1,0,31,"YO TUVE UNA CHINITILLA",0,4,"e",-1,0,-1,0,219,219,"C-288","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0288-05",3,"Me arrimé y le pregunté:\n¿Chinita, me conocís?\n—No lo conozco, señor,\nNi lo he visto por aquí.",3,1,0,31,"YO TUVE UNA CHINITILLA",0,4,"i",-1,0,-1,0,219,219,"C-288","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0288-06",3,"La pena que reina en mí\nEl tiempo la acabará,\ntu ingratitud verá,\nQue puedo vivir sin tí.",3,1,0,32,"LA PENA QU*, EN MI REINA",11,4,"i",23,0,-1,0,221,221,"C-288","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0288-07",3,"Luego me arrojé por tí,\nSin conocer en tu engaño,\nHoy me alivia el desengaño\nLa pena que reina en mí.",3,1,0,32,"LA PENA QU*, EN MI REINA",11,4,"i",23,0,-1,0,221,221,"C-288","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0288-08",3,"Difícil remedio tendrá\nEste terrible dolor,\nPues mi firmeza y amor,\nEl tiempo lo acabará.",3,1,0,32,"LA PENA QU*, EN MI REINA",11,4,"a",9,0,-1,0,221,221,"C-288","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0290-02",3,"No olvides lo que te digo\nque te sirva de ejemplo,\nPuede ser que en algún tiempo\nLlores lo que hoy has perdido.\nMe voy para otro destino\nBien puedes regocijarte,\nPues tú quedas con tu amante,\npor mí, yo te aseguro,\nQue he sido tu amante y juro\nJamás volver a buscarte.",3,1,0,32,"NO TENGAS EN LA MEMORIA",18,10,"ae",-1,0,-1,0,221,221,"C-290","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0290-04",3,"Si a tí te causa placer\nYa que mi pecho te adora,\nTe prometo desde ahora,\nQue he de olvidar tu querer.\nHoy por tu mal proceder\nA otra me he dirigido.\nY es porque así lo has querido,\nNo tendrás que disculparte,\nJamás vuelvas acordarte\nSi algún amor me has tenido.",3,1,0,32,"NO TENGAS EN LA MEMORIA",18,10,"io",101,0,-1,0,221,221,"C-290","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0290-05",3,"Si a tí te causa disgusto\nQue te deje de querer,\nYo con otra he de tener,\nTodo mi placer y gusto.\nMe parece que es muy justo\nQue ahora trate de engañarte,\nDe mí no pienses burlarte\nPorque es de más te lo digo\nY si has vivido conmigo\nNo tendrás porque acordarte.",3,1,0,32,"NO TENGAS EN LA MEMORIA",18,10,"ae",8,0,-1,0,221,221,"C-290","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0291-01",3,"Por tu amor yo anduve loco\nY hoy me digo con espanto:\n¡Qué haya yo sufrido tanto\nPor quién merece tan poco!",3,1,0,32,"POR TU AMOR YO ANDUVE LOCO",11,4,"oo",152,0,-1,0,221,221,"C-291","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0291-02",3,"Te quise y tú me quisiste\nMe olvidaste y te olvidé,\nPor tu olvido no lloré\nNi por mi olvido sufristes\nSi tú no quedastes triste\nNo quedé triste tampoco\nTú amas si no me equivoco\nY yo por otra estoy ciego.\nEn un tiempo no lo niego\nPor tu amor anduve loco.",3,1,0,32,"POR TU AMOR YO ANDUVE LOCO",18,10,"oo",152,0,-1,0,221,221,"C-291","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0291-03",3,"Pero ese tiempo pasó\nY pasó mi amor por tí\nTú no te acuerdas de mí\nNi de tí me acuerdo yo\nEl juicio por fin entró\nY bendigo el desencanto\nQue me ahorra pena y llanto\nLibre de tal contrapeso\n¿Cómo pude ser tan leso?\nHoy me digo con espanto.",3,1,0,32,"POR TU AMOR YO ANDUVE LOCO",18,10,"ao",30,0,-1,0,221,221,"C-291","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0291-05",3,"Antes llorando pasaba\nY lamentando mi suerte\nYo creía que con verte\nMis dolencias yo curaba,\nMi alma de tu amor esclava,\nSufría eterno quebranto,\nPero hoy como, bebo y canto,\nY por otro amor deliro\nY al pensar en tí me admiro\nQue haya yo sufrido tanto.",3,1,0,32,"POR TU AMOR YO ANDUVE LOCO",18,10,"ao",30,0,-1,0,222,222,"C-291","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0291-07",3,"¡Cómo vas a padecer\nAl saber que me he casado\nY que por fin he encontrado\nLinda y virtuosa mujer!\nPálida te has de poner\nCuando con ella me veas,\nY si igual suerte deseas\nPara no atrapar a un viejo,\nLlévate de mi consejo:\n—Con nadie coqueta seas.",3,1,0,32,"POR TU AMOR YO ANDUVE LOCO",18,10,"ea",67,0,-1,0,222,222,"C-291","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0292-01",3,"¿Quién al verte tan hermosa\nHubiera llegado a creer\nQue eres en forma mujer\nCon ideas de mariposa?;\nEn vano tan candorosa\nApareces ante el mundo\nNo es un secreto profundo,\nDescubrir tu corazón,\nSi hasta mueve a compasión\nArbol que crece infecundo.",3,1,0,32,"QUIEN AL VERTE TAN HERMOSA",18,10,"uo",179,0,-1,0,222,222,"C-292","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0292-02",3,"—Tu falsedad inclemente\nNo ha dañado el alma mía,\nPorque más daño me hacía,\nTener cuernos en la frente.",3,1,0,32,"QUIEN AL VERTE TAN HERMOSA",11,4,"ee",15,0,-1,0,222,222,"C-292","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0292-03",3,"Si antes con amor ardiente\nTe amé de entusiasmo loco,\nHoy ya te quiero tan poco,\nAún cuando no te aborrezco,\nDe veras te compadezco\nY a Dios por tu suerte invoco.",3,1,0,32,"QUIEN AL VERTE TAN HERMOSA",9,6,"oo",152,0,-1,0,222,222,"C-292","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0292-04",3,"Una alma que sabe amar\nY que es noble en el querer,\nNo se ha hecho para mujer,\nQue no se alcanza apreciar;\nQuizás te puedas hallar\nEn el curso de la vida,\nOtra alma tan fementida,\nQue sea con la tuya igual\nPorque un mal con otro mal\nSuelen hallarse en seguida.",3,1,0,32,"QUIEN AL VERTE TAN HERMOSA",18,10,"ia",37,0,-1,0,222,222,"C-292","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0293-01",3,"¡Sal ingrata de mi pecho\nNo me preguntes por qué\nSi por firme te he querido\nHoy por falsa te dejé!",3,1,0,32,"SAL INGRATA DE MI PECHO",0,4,"e",77,0,-1,0,222,222,"C-293","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0293-02",3,"A ese que estás adorando\nNo lo desprecies por mí,\nNo sea que digas mañana,\n¡Malhayas por quién perdí!",3,1,0,32,"SAL INGRATA DE MI PECHO",0,4,"i",23,0,-1,0,222,222,"C-293","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0293-03",3,"¡Permita el cielo divino\nQue lo quieras más que a mí\nY al punto te dé el mal pago\nComo me lo has dado a mí!",3,1,0,32,"SAL INGRATA DE MI PECHO",0,4,"i",-1,0,-1,0,222,222,"C-293","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0293-04",3,"Dame al alma que te dí\nQue el pedirla no es ofensa,\nPorque no quiero que esté,\nDonde no hay correspondencia.",3,1,0,32,"SAL INGRATA DE MI PECHO",0,4,"ea",-1,0,-1,0,222,222,"C-293","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0294-04",3,"Un tigre de grande saña,\nTe agarre con más presteza\nY te corte la cabeza,\nUn lagarto con su maña,\nQue te devore una araña,\nEl corazón a pedazos,\nY que te tiren balazos,\nCon bala de artillería,\nY que en ese mismo día\nUn rayo te haga pedazos.",3,1,0,32,"UN COCODRILO TE CANTE",18,10,"ao",132,0,-1,0,223,223,"C-294","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0294-05",3,"Al fin lo que digo aquí\nQuiero que llegue a los cielos,\nQue tu pecho arda de celos,\nY te haga víctima a tí.\nCumpliéndose todo así.\nMe complaceré contigo\nQue te muelan como trigo,\nPara que nunca desmayes,\nPermita el cielo que te halles,\nSin árbol, sombra, ni abrigo.",3,1,0,32,"UN COCODRILO TE CANTE",18,10,"io",106,0,-1,0,223,223,"C-294","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0295-01",3,"Ya no quiero que me tenga\nEn tu memoria un momento,\nQue no ha sido dicha poca\nVer un desengaño a tiempo.",3,1,0,32,"YA NO QUIERO QUE ME TENGAS",0,4,"eo",-1,0,-1,0,223,223,"C-295","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0295-02",3,"A ese tu fingido amor\nBueno será lo prevengas,\nPorque en vuestro infame pecho\nYa no quiero que me tengas.",3,1,0,32,"YA NO QUIERO QUE ME TENGAS",0,4,"ea",368,0,-1,0,223,223,"C-295","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0295-03",3,"Si en algún tiempo te quise\nY te procuré el contento,\nProcuro ahora no estar,\nEn tu memoria un momento.",3,1,0,32,"YA NO QUIERO QUE ME TENGAS",0,4,"eo",94,0,-1,0,223,223,"C-295","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0295-04",3,"El conocer tus engaños,\nY mi porfía tan loca,\nPuedo decir con verdad:\n—Que no ha sido dicha poca.",3,1,0,32,"YA NO QUIERO QUE ME TENGAS",0,4,"oa",178,0,-1,0,223,223,"C-295","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0295-05",3,"Con eso ya no erraré\nNi buscaré más ejemplo,\nSupuesto que he merecido\nVer un desengaño a tiempo.",3,1,0,32,"YA NO QUIERO QUE ME TENGAS",0,4,"eo",-1,0,-1,0,223,223,"C-295","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0296-05",3,"¡rré en haberte querido,\n)0 enmiendo con olvidar,\nfa no quiero más amar.\ni quién tanto me ha ofendido,",3,1,0,33,"YA NO TE ACUERDES DE MI",11,4,"io",101,0,-1,0,225,225,"C-296","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0296-06",3,"Ingrata, tú me has herido,\nInhumana, sin piedad,\nHas pagado con crueldad,\nA mi fiel constante amor;\nA causa de tu rigor\nSe acabó nuestra amistad.",3,1,0,33,"YA NO TE ACUERDES DE MI",9,6,"a",16,0,-1,0,225,225,"C-296","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0297-01",3,"A despedirme he venido\nY a darte el último abrazo,\nPor sí, en la fortuna escaso,\nRinda mi último destino.",3,1,0,33,"A DESPEDIRME HE VENIDO",5,4,"io",-1,0,-1,0,225,225,"C-297","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0297-04",3,"Si no quieres mi amistad\nDespreciando mi inocencia,\nSoy como el vino en demencia\nEn este particular.\nYa me voy a retirar\nPues veo tu amor escaso,\nNo te voy a dar un plazo,\nPorque ya me voy sin vuelta,\nQuiero darte toda cuenta,\nY darte el último abrazo",3,1,0,33,"A DESPEDIRME HE VENIDO",18,10,"ao",43,0,-1,0,225,225,"C-297","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0298-01",3,"¡Adiós, ángel de mis ojos!\nMi querida dueña, ¡adiós!\nLlega el tiempo riguroso\nQue me separe de vos.",3,1,0,33,"ADIÓS, ÁNGEL DE MIS OJOS",0,4,"o",87,0,-1,0,225,225,"C-298","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0298-02",3,"Tristemente me despido,\n¡Sabe Dios, con qué dolor!,\nAl ver que me voy, mi amada,\nEn la fuerza de mi amor.",3,1,0,33,"ADIÓS, ÁNGEL DE MIS OJOS",0,4,"o",72,0,-1,0,226,226,"C-298","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0298-03",3,"Cuando dos se quieren bien\nY se adoran incesante,\n¿Cuál sufrirá mayor pena\nEl que queda o el que parte?",3,1,0,33,"ADIÓS, ÁNGEL DE MIS OJOS",0,4,"ae",-1,0,-1,0,226,226,"C-298","",0,"","","",8,0,0,[],""],["carrizo_salta-nc0298-04",3,"El que parte va pensando\nEn las leguas del camino,\nEl que queda, suspirando,\nCon un dolor de continuo.",3,1,0,33,"ADIÓS, ÁNGEL DE MIS OJOS",0,4,"io",-1,0,-1,0,226,226,"C-298","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0298-05",3,"Si el mundo cesa de andar,\nY el sol no dé resplandor,\nYo te dejaré de amar\nSi deja de haber amor.",3,1,0,33,"ADIÓS, ÁNGEL DE MIS OJOS",1,4,"o",72,0,-1,0,226,226,"C-298","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0298-06",3,"Dame tus brazos, mi bien,\nQue me despido llorando,\nYa no te volveré a ver,\nSólo Dios sabe hasta cuando.",3,1,0,33,"ADIÓS, ÁNGEL DE MIS OJOS",0,4,"ao",33,0,-1,0,226,226,"C-298","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0299-01",3,"¡Adiós, mi prenda querida!\nYa me voy a retirar,\nAlgún día puedo verte,\nSi el tiempo me da lugar.",3,1,0,33,"ADIÓS, MI PRENDA QUERIDA",0,4,"a",21,0,-1,0,226,226,"C-299","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0299-02",3,"El corazón se me parte\nAl despedirme de tí,\nPero te voy a decir\nQue jamás he de olvidarte.\nCon más fuerzas he de amarte\nEn donde quiera que viva;\nMientras Dios me preste vida\nSiempre he de ser el que fuí,\nSólo te puedo decir\n¡Adiós, mi prenda querida!",3,1,0,33,"ADIÓS, MI PRENDA QUERIDA",18,10,"ia",37,0,-1,0,226,226,"C-299","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0299-04",3,"Es verdad que me retiro;\nLos motivos no diré,\nPero luego has de saber,\nLo que antes no has advertido.\nY solamente te digo,\nDe que me tengas presente,\nQue aunque yo me encuentre ausente,\nTe dejaré esta experiencia,\nQue si Dios me dá licencia\nAlgún día puedo verte.",3,1,0,33,"ADIÓS, MI PRENDA QUERIDA",18,10,"ee",-1,0,-1,0,226,226,"C-299","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0299-05",3,"¡Adiós, que mi corazón\nTriste y confuso se vá!\nPero tu debes quedar,\nMuy contenta y sin dolor;\nPorque otra tribulación\nCon mayor velocidad,\nPuede herirte a mi pesar\nCon crueldad y con porfía;\nPues volveré algún día,\nSi el tiempo me da lugar.",3,1,0,33,"ADIÓS, MI PRENDA QUERIDA",18,10,"a",21,0,-1,0,226,226,"C-299","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0300-01",3,"¡Adiós, prenda idolatrada!\nVoy a dejar de existir,\nYa me es forzoso el partir\nAllá a la eterna morada;\nDe una vida infortunada\nAl mundo dejo un ejemplo,\nSólo el dejarte contemplo\nCon el dolor más amargo;\nY te dejo por encargo\nNo me olvides con el tiempo.",3,1,0,33,"ADIÓS, PRENDA IDOLATRADA",18,10,"eo",-1,0,-1,0,226,226,"C-300","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0300-02",3,"Me separo con ternura\nDe tus amorosos brazos,\nRompiendo estos duros lazos\nCon una muerte segura,\nMarcharé a la sepultura\nDonde seré sepultado,\nUn amante desdichado\nQue te quiso y amó tanto,\nRegarás con tierno llanto,\nLos restos de un desgraciado.",3,1,0,33,"ADIÓS, PRENDA IDOLATRADA",18,10,"ao",-1,0,-1,0,226,226,"C-300","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0301-01",3,"¡Adiós, vida de mi vida,\nEncanto de mi afición!\nTe dejo mi corazón\nComo última despedida.",3,1,0,33,"ADIÓS, VIDA DE MI VIDA",11,4,"ia",37,0,-1,0,227,227,"C-301","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0301-02",3,"El dejarte es un dolor\nY el no verte es un tormento,\nAsí será con el tiempo\nLos despojos del rigor,\nNo hay en mi pecho valor\nAl formar esta partida,\nPorque una mortal herida\nVa mí existencia acabando,\nY así te digo llorando:\n¡Adiós, vida de mi vida!",3,1,0,33,"ADIÓS, VIDA DE MI VIDA",18,10,"ia",37,0,-1,0,227,227,"C-301","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0301-03",3,"El partir y no sentir\nEs el mayor imposible,\nSólo una peña insensible\nPuede este golpe sufrir;\nComo no sabe morir\nY es materia sin razón,\nNo sabe lo que es pasión\nEn los racionales seres,\nYo siento por ti, que eres\nEncanto de mi afición.",3,1,0,33,"ADIÓS, VIDA DE MI VIDA",18,10,"o",31,0,-1,0,227,227,"C-301","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0301-04",3,"Si tú sientes como yo\nAyudarás a mi llanto,\nAl verme padecer tanto.\nNo me niegues, bella, no;\nPadeceremos los dos\nEsta cruel separación,\nQue con doblado tesón\nSe lamenta quien te adora,\nSiquiera para memoria,\nTe dejo mi corazón.",3,1,0,33,"ADIÓS, VIDA DE MI VIDA",18,10,"o",31,0,-1,0,227,227,"C-301","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0301-05",3,"Por fin, ¡adiós, alma mía!\nMe voy sin placer alguno.\nMis suspiros, de uno a uno,\nAcompañan mi agonía,\nSe queda el bien que quería,\nNingún amparo me abriga;\nVoy como cosa perdida,\nSin saber lo que vendrá,\nSi hablar mi lengua podrá\nPor última despedida.",3,1,0,33,"ADIÓS, VIDA DE MI VIDA",18,10,"ia",37,0,-1,0,228,228,"C-301","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0302-01",3,"Al ausentarme de ti\nVierto lágrimas amargas,\nPorque si la ausencia es larga\nTal vez te olvides de mí.\nTriste pena si es así,\nSuspira mi corazón,\nPero no es posible, no,\nQue tu amor sea tan cruel,\nSi he depositado en él\nLa esencia de un fino amor.",3,1,0,33,"AL AUSENTARME DE TI",18,10,"o",-1,0,-1,0,228,228,"C-302","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0302-02",3,"¡Mi alma! no puedo creer\nQue llegaras a olvidarte\nDe quien con amor constante\nSiempre te sabrá querer.\nNo quisiera que al volver\nHallase mudanza en ti,\nPorque si sucede así,\nGrande mi dolor sería,\nY sólo en la tumba fría\nDejaría de sufrir.",3,1,0,33,"AL AUSENTARME DE TI",18,10,"i",-1,0,-1,0,228,228,"C-302","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0302-03",3,"Me sería doloroso\nVerme de ti separado,\nPorque no estando a tu lado\nNo podré vivir dichoso.\nPero hoy día me es forzoso,\nDebo partir sin demora,\nMi corazón triste llora\nPensando en el bien que dejo.\n¡Adiós, que de ti me alejo!\nSe va quien tanto te adora.",3,1,0,33,"AL AUSENTARME DE TI",18,10,"oa",107,0,-1,0,228,228,"C-302","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0302-04",3,"¡Adiós, pues, que ya me ausento,\nDueña querida de mi alma!\nYa se va mi amor en calma,\nQueda en ti mi pensamiento.\nSi me retiro, un tormento\nHe de hallar en este mundo,\nPorque el destino iracundo\nDispone que sea así,\nConservaré para ti\nEl cariño más profundo.",3,1,0,33,"AL AUSENTARME DE TI",18,10,"uo",179,0,-1,0,228,228,"C-302","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0303-01",3,"Alégrate, que me voy,\nPorque ya no he de volver.\nUn preso, un muerto, un ausente\nUno no más viene a ser.",3,1,0,33,"ALÉGRATE QUE ME VOY",0,4,"e",20,0,-1,0,228,228,"C-303","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0303-02",3,"El cuatro del mes de Mayo\nDe ochocientos treinta y uno,\nVi al sol enlutarse de humo\nY oscurecerse sus rayos.\nTodo miro, sufro y callo\nPorque desgraciado soy,\nPero muy conforme estoy\nCon este mal tan injusto.\nYa te quedarás a gusto,\nAlégrate que me voy.",3,1,0,33,"ALÉGRATE QUE ME VOY",18,10,"o",112,0,-1,0,228,228,"C-303","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0303-03",3,"Porque tengo mala suerte\nVoy a salir a rodar,\nPara que dejes de estar\nSólo deseando mi muerte.\nTendrás glorias permanentes,\nGozarás gusto y placer,\nYo seguiré el padecer\nRodando de tierra en tierra,\nEs como si me muriera,\nPorque ya no he de volver.",3,1,0,33,"ALÉGRATE QUE ME VOY",18,10,"e",20,0,-1,0,228,228,"C-303","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0303-04",3,"Preso, voy de obligación;\nMuerto, de una ingratitud;\nAusente estoy de la luz\nPor una injusta razón.\nYa no tendrás opresión,\nYa gozarás libremente;\nTendrás glorias permanentes,\nNo me volverás a ver.\n¿En qué te puede ofender\nUn preso, un muerto, un ausente?",3,1,0,33,"ALÉGRATE QUE ME VOY",18,10,"ee",-1,0,-1,0,228,228,"C-303","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0303-05",3,"Dos prendas del corazón\nQuedan en vuestro poder;\nDios las ha de recoger\nCuando las arrojes vos.\nPorque no valiendo yo,",3,1,0,33,"ALÉGRATE QUE ME VOY",7,5,"o",-1,0,-1,0,228,228,"C-303","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0303-06",3,"3 prendas no han de valer,\niero la muerte más bien\ne vivir en mi lamento,\nle la pena y el tormento\n10 no más viene a ser.",3,1,0,33,"ALÉGRATE QUE ME VOY",7,5,"e",-1,0,-1,0,229,229,"C-303","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0304-03",3,"—¡Madrecita de mi vida,\nNo llore ni tenga pena,\nQue por mi gusto me voy\nA rodar tierras ajenas!",3,1,0,33,"CUANDO SALÍ DE MI TIERRA",0,4,"ea",-1,0,-1,0,229,229,"C-304","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0304-04",3,"Al subir a mi caballo\nMe subí tan riguroso,\nAl dar vueltas al camino\nDos mares eran mis ojos.",3,1,0,33,"CUANDO SALÍ DE MI TIERRA",0,4,"oo",-1,0,-1,0,229,229,"C-304","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0304-05",3,"Me fuí para mi querida,\nComo es prenda que adoraba,\nAl pisar a sus umbrales\nLe dije que me olvidara.",3,1,0,33,"CUANDO SALÍ DE MI TIERRA",0,4,"aa",-1,0,-1,0,229,229,"C-304","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0304-06",3,"Se levantó de la cama,\nSe arrimó junto a una reja.\n—¿Es posible, vida mía?\n¿Por qué te vais y me dejas?",3,1,0,33,"CUANDO SALÍ DE MI TIERRA",0,4,"ea",-1,0,-1,0,229,229,"C-304","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0304-07",3,"—Por más lejos que me vaya,\nNo pienses que yo te olvido,\nSólo con la propia muerte\nFaltaría a lo que digo.",3,1,0,33,"CUANDO SALÍ DE MI TIERRA",0,4,"io",-1,0,-1,0,229,229,"C-304","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0304-08",3,"—Lo que te encargo, bien mío,\nQue llegando a donde vais,\nMe escribais una cartita\nPara saber cómo estais.",3,1,0,33,"CUANDO SALÍ DE MI TIERRA",0,4,"a",-1,0,-1,0,229,229,"C-304","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0304-09",3,"Ahí te mando un papelito\nEscrito con letras verdes,\nPara que viendo esta carta\nMemorias de mí te acuerdes.",3,1,0,33,"CUANDO SALÍ DE MI TIERRA",0,4,"ee",369,0,-1,0,229,229,"C-304","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0304-10",3,"Al recibir esta carta\nDesmayado me quedé,\nEché mis quejas al aire,\nCon suspiros acabé.",3,1,0,33,"CUANDO SALÍ DE MI TIERRA",0,4,"e",77,0,-1,0,229,229,"C-304","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0305-01",3,"De tu cielo me despido,\nDe tu hermosura me alejo,\nSólo siento que te dejo\nAnsias, penas y suspiros.",3,1,0,33,"DE TU CIELO ME DESPIDO",5,4,"io",-1,0,-1,0,229,229,"C-305","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0305-03",3,"Con mi llanto y mi gemido,\nCon el corazón partido,\nTraspasado de dolor.\n¡Adiós, mi encantada flor,\nDe tu cielo me despido!",3,1,0,33,"DE TU CIELO ME DESPIDO",7,5,"io",101,0,-1,0,229,230,"C-305","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0305-04",3,"No pierdo las esperanzas,\nMi bien, de volverte a ver,\nY que siempre encontraré\nEn tu pecho la constancia.\nNo porque yo esté en distancia\nMe olvides, mi bien, por eso.\nYo la verdad te confieso,\nSiento el irme de tu lado.\n¡Adiós, clavel encarnado,\nDe tu hermosura me alejo!",3,1,0,33,"DE TU CIELO ME DESPIDO",18,10,"eo",-1,0,-1,0,230,230,"C-305","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0305-05",3,"Hoy me despido de ti.\n¡Mi sol, mi estrella, mi guía!\nSólo te pido, alma mía,\nQue no te olvides de mí.\nMi consuelo lo perdí,\nDe mi desgracia me quejo.\n¡Adiós, mi adorado espejo,\nVoy a llorar mi quebranto\nDe haberte querido tanto,\nSólo siento que te dejo!",3,1,0,33,"DE TU CIELO ME DESPIDO",18,10,"eo",264,0,-1,0,230,230,"C-305","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0305-06",3,"¡Adiós, mi adorada gloria,\nPlacer, cariño y contento!\nNo me olvides un momento,\nMi bien, de vuestra memoria.\nDueña mía, tú no ignoras\nQue por quererte he vivido.\n¡Adiós, clavel encendido\nDentro de mi corazón!\n¡Adiós, mi santa ilusión,\nAnsias, penas y suspiros!",3,1,0,33,"DE TU CIELO ME DESPIDO",18,10,"io",-1,0,-1,0,230,230,"C-305","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0306-01",3,"Hoy me despido llorando,\nHoy me despido de vos.\n¡Adiós, dulce prenda mía,\nMi hermoso lucero, adiós!",3,1,0,33,"HOY ME DESPIDO LLORANDO",0,4,"o",87,0,-1,0,230,230,"C-306","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0306-02",3,"¡Adiós, vidita de mi alma!\n¡Adiós, todo mi consuelo!\n¡Adiós, venerado cielo,\nLucero de la mañana!\nPorque el destino me llama,\nVoy sin saber hasta cuándo.\nDe ti me voy suspirando\nEn el pesar sumergido.\n¡Adiós, mi cielo querido!\nHoy me despido llorando.",3,1,0,33,"HOY ME DESPIDO LLORANDO",18,10,"ao",33,0,-1,0,230,230,"C-306","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0306-03",3,"Pero voy con la esperanza\nQue puedo verte algún día;\nPuede ser la suerte mía,\nSi la fortuna me alcanza,\nHe de volver sin tardanza,\nCon el favor de mi Dios,\nY nos veremos los dos\nEn la hora menos pensada.\nPorque voy de retirada,\nHoy me despido de vos.",3,1,0,33,"HOY ME DESPIDO LLORANDO",18,10,"o",87,0,-1,0,230,230,"C-306","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0306-04",3,"Sólo te suplicaré\nQue no te olvides de mí,\nQue lo mismo yo haré así\nY algún día volveré.\nYo jamás te olvidaré\nNi en un minuto del día,\nPensando que te quería,\nTriste, de ti me despido\nEn mi dolor confundido.\n¡Adiós, dulce prenda mía!",3,1,0,33,"HOY ME DESPIDO LLORANDO",18,10,"ia",0,0,-1,0,230,230,"C-306","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0306-05",3,"No porque de ti me ausente\nPienses que te he de olvidar,\nTú no vayas a escuchar\nLos consejos de la gente.\nSiempre portate decente,\nSin dar un vuelco veloz,\nY yo te juro por Dios\nEl mucho amor que te tengo.\nEn fin, todo te prevengo.\n¡Mi hermoso lucero, adiós!",3,1,0,33,"HOY ME DESPIDO LLORANDO",18,10,"o",87,0,-1,0,230,230,"C-306","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0307-01",3,"Hoy nos divide la suerte,\nNos despedimos los dos.\n¡Adiós, dulce prenda mía!\n¡Adiós, corazón, adiós!",3,1,0,33,"HOY NOS DIVIDE LA SUERTE",0,4,"o",87,0,-1,0,230,230,"C-307","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0307-02",3,"¡Infelices ojos míos,\nHáganse un profundo mar\nY ayúdenme a llorar\nPeñas, mares, montes, ríos!\nSe fueron los gustos míos.\n¡Ay, qué tormento tan fuerte\nSi a los brazos de la muerte\nMe ha postrado tu hermosura!\nY para más desventura\nHoy nos divide la suerte.",3,1,0,33,"HOY NOS DIVIDE LA SUERTE",18,10,"ee",134,0,-1,0,230,230,"C-307","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0308-02",3,"duélete, cielo, de mí,\nDe mi triste situación,\nY muévate a compasión\nLa fuerza de mi destino.",3,1,0,33,"LA FUERZA DE MI DESTINO",5,4,"io",-1,0,-1,0,231,231,"C-308","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0308-03",3,"No pretendas olvidarme,\nQue pronto volveré a verte,\nYa que la infeliz suerte\nTrata ya de separarme.",3,1,0,33,"LA FUERZA DE MI DESTINO",11,4,"ae",35,0,-1,0,231,231,"C-308","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0308-04",3,"La vida intentas quitarme,\nFortuna cruel, inhumana,\nSeparándome mañana\nDe la que supo robarme.",3,1,0,33,"LA FUERZA DE MI DESTINO",11,4,"ae",35,0,-1,0,231,231,"C-308","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0308-05",3,"Con el afecto más tierno,\nDueña de mi corazón,\nPuse a tu disposición\nVoluntad, vida y cariño.",3,1,0,33,"LA FUERZA DE MI DESTINO",5,4,"io",-1,0,-1,0,231,231,"C-308","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0309-01",3,"La infeliz fortuna mía\nNos separa y nos divide,\nLe encargo que no me olvide\nEl amor que me tenía.\nY mañana y otro día,\nLo que dure su existencia,\nPídale a la Omnipotencia\nLo mismo que yo le pido,\nQue causar en mí el olvido\nNunca ha de poder la ausencia.",3,1,0,33,"LA INFELIZ FORTUNA MÍA",18,10,"ea",46,0,-1,0,231,231,"C-309","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0309-02",3,"Día y noche considero,\nViendo mi placer cercano,\nY a países tan lejanos\nQuiero llevarte y no puedo.\nY así siento y desespero,\nQue el corazón se me parte.\nDe este modo quiero hablarte,\nMas no es posible que pueda,\nPorque te traigo la nueva\nQue ya es tiempo de dejarte.",3,1,0,33,"LA INFELIZ FORTUNA MÍA",18,10,"ae",8,0,-1,0,231,231,"C-309","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0309-03",3,"Pero al fin, ¡adiós, placer!\nSólo te quiero pedir\nQue te recuerdes de mí,\nCuando no tengas qué hacer,\nY si llega a suceder\nQue yo vuelva a idolatrarte,\nTe prometo de mi parte\nLa más fina voluntad.\nSólo la muerte podrá\nHacer que deje de amarte.",3,1,0,33,"LA INFELIZ FORTUNA MÍA",18,10,"ae",8,0,-1,0,231,231,"C-309","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0309-04",3,"Ya que se aproxima el plazo\nDe nuestra separación,\nTe digo con corazón\nQue es de mi vida el ocaso;\nY mi pecho hecho pedazos\nNo se puede consolar;\nY en tan doblado pesar\nTe dejo un mortal suspiro,\nY como ya me retiro,\nMi bien, te vengo a avisar.",3,1,0,33,"LA INFELIZ FORTUNA MÍA",18,10,"a",21,0,-1,0,231,231,"C-309","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0310-01",3,"La suerte que tan tirana\nCupo a la existencia mía,\nMe tuvo a tu lado un día\nPara ausentarme mañana;\nPor eso mi alma se afana,\nPero así tenía que ser;\nNo me puedo detener,\nMas, ya que de ti me alejo,\nEste recuerdo te dejo\nPor si no te vuelvo a ver.",3,1,0,33,"LA SUERTE QUE TAN TIRANA",18,10,"e",20,0,-1,0,232,232,"C-310","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0310-02",3,"Para un corazón que siente\nY alimenta una ilusión,\nTriste es la separación\nQue ha de matarlo inclemente.\nYa me tienes de ti ausente\nY pronto lejos de aquí,\nPero si me voy así,\nPorque el destino me obliga,\nPido a Dios, mi dulce amiga,\nQue no te olvides de mí.",3,1,0,33,"LA SUERTE QUE TAN TIRANA",18,10,"i",23,0,-1,0,232,232,"C-310","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0310-03",3,"Sólo anhela el alma mía\nQue Dios la dicha te ofrezca,\nSin que una nube obscurezca\nEl cielo de tu alegría,\nQue no llegue el triste día\nEn que tengas que sufrir,\nQue no te llegue a afligir\nUna pena dolorosa;\nQue sabiendo eres dichosa\nContento yo he de vivir.",3,1,0,33,"LA SUERTE QUE TAN TIRANA",18,10,"i",157,0,-1,0,232,232,"C-310","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0310-04",3,"Y aunque para mi tormento\nDe ti me vea alejado,\nConstantemente a tu lado\nEstará mi pensamiento.\nY hundido en triste lamento\nMe será consuelo el creer\nQue en tu memoria ha de haber\nUn recuerdo para mí,\nMientras yo pensaré en ti\nHasta que te vuelva a ver.",3,1,0,33,"LA SUERTE QUE TAN TIRANA",18,10,"e",20,0,-1,0,232,232,"C-310","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0310-05",3,"Y aún cuando con mi existencia\nPueda mi amor acabarse,\nSiempre la flor al secarse\nDeja en la planta su esencia.\nAsí yo, con la vehemencia\nDe quererte hasta la muerte,\nDejaré en mi cuerpo inerte\nLa esencia de mi cariño,\nY con la calma de un niño\nMoriré creyendo verte.",3,1,0,33,"LA SUERTE QUE TAN TIRANA",18,10,"ee",134,0,-1,0,232,232,"C-310","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0311-01",3,"Mañana me voy de aquí,\nComo todos lo verán;\nAl despedirme te digo:\n—No sé hasta cuándo será.",3,1,0,33,"MAÑANA ME VOY DE AQUÍ",0,4,"a",-1,0,-1,0,232,232,"C-311","",0,"","","",8,0,0,[],""],["carrizo_salta-nc0311-02",3,"Supuesto que ya me voy,\nDe ti despedirme quiero,\nPero llevo la esperanza\nDe verte; si no me muero.",3,1,0,33,"MAÑANA ME VOY DE AQUÍ",0,4,"eo",38,0,-1,0,232,232,"C-311","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0311-03",3,"De tu lado, vida mía,\nDe tu presencia me alejo;\nEn premio de tu fineza\nEste corazón te dejo.",3,1,0,33,"MAÑANA ME VOY DE AQUÍ",0,4,"eo",264,0,-1,0,232,232,"C-311","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0311-04",3,"Te dejo mi corazón,\nNo sé si te servirá;\nSi no te sirve lo botas,\nQue otra lo recogerá.",3,1,0,33,"MAÑANA ME VOY DE AQUÍ",0,4,"a",9,0,-1,0,232,232,"C-311","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0312-01",3,"¡Qué pocas horas les queda\nYa del término previsto,\nPara gozar de tu cielo,\nA los tristes ojos míos!",3,1,0,33,"QUE POCAS HORAS LES QUEDA",0,4,"io",-1,0,-1,0,232,232,"C-312","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0313-03",3,"Nada habrá lejos de ti\nQue me pueda consolar,\nMi vida será llorar\nComo estoy llorando aquí.\nSi tú te acuerdas de mí\nNo llores, amada mía,\nPorque tal vez llegaría\nA aumentar mi sinsabor\nEl eco de tu dolor,\nQue el alma me partiría.",3,1,0,33,"QUE TORMENTO MAS ATROZ",18,10,"ia",0,0,-1,0,233,233,"C-313","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0313-04",3,"¡Adiós, ya voy a dejarte\nPara ir a correr mi suerte!\n¡Quién sabe si vuelvo a verte,\nY si fiel he de encontrarte!\nYo nunca podré olvidarte;\nSi me lo permite Dios,\nMi pensamiento veloz\nCorrerá siempre a tu lado;\nNo olvides a un desgraciado.\n¡Adiós, mi esperanza, adiós!",3,1,0,33,"QUE TORMENTO MAS ATROZ",18,10,"o",87,0,-1,0,233,233,"C-313","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0314-01",3,"Sabrás, mi bien, que he venido\nTan solamente a avisarte,\nQue yo me voy y te dejo,\nSólo siento el no llevarte.",3,1,0,33,"SABRÁS MI BIEN QUE HE VENIDO",0,4,"ae",8,0,-1,0,233,233,"C-314","",0,"","","",5,0,0,[],""],["carrizo_salta-nc0314-02",3,"Un crecido sentimiento\nMe precisa, bien del alma,\nCómo mi amor queda en calma\nA declararte mi intento.\nEs mi viaje tan violento\nY mi término cumplido;\nLloro, pues, enternecido\nPorque fino amante soy,\nPor decirte que me voy,\nSabrás, mi bien, que he venido.",3,1,0,33,"SABRÁS MI BIEN QUE HE VENIDO",18,10,"io",101,0,-1,0,233,233,"C-314","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0314-03",3,"Yo te quisiera llevar,\nMi bien, en esta ocasión,\nDentro de mi corazón,\nQue es el perfecto lugar.",3,1,0,33,"SABRÁS MI BIEN QUE HE VENIDO",11,4,"a",21,0,-1,0,233,233,"C-314","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0314-04",3,"¡Qué pena tan sin igual,\nMi bien, es el no llevarte!\nMi corazón se me parte;\nQuédate con Dios, belleza,\nHoy me rinde mi fineza\nTan solamente a avisarte.",3,1,0,33,"SABRÁS MI BIEN QUE HE VENIDO",9,6,"ae",8,0,-1,0,234,234,"C-314","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0314-05",3,"Mientras Dios me diere vida\nY me ampare su favor,\nEspero que el Salvador\nMe volverá a mi partida.\nVolveré, prenda querida,\nA mirarme en ese espejo,\nDe mi fortuna me quejo\nY mi llanto no se calma,\nPues te he dicho, bien de mi alma,\nQue ya me voy y te dejo.",3,1,0,33,"SABRÁS MI BIEN QUE HE VENIDO",18,10,"eo",264,0,-1,0,234,234,"C-314","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0314-06",3,"¡Adiós, mi querida, adiós!\n¡Adiós, mi hermoso lucero!\nDame un abrazo postrero,\nNos despidamos los dos.\nComo bien lo sabe Dios,\nQue no quisiera dejarte,\nYo te prometo adorarte\nY tenerte en la memoria.\n¡Adiós, mi adorada gloria!\nSólo siento el no llevarte.",3,1,0,33,"SABRÁS MI BIEN QUE HE VENIDO",18,10,"ae",8,0,-1,0,234,234,"C-314","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0315-01",3,"Sabrás, mi bien, que he venido\nTan solamente a avisarte,\nQue yo me voy y te dejo;\nLo que siento es no llevarte.",3,1,0,33,"SABRÁS MI BIEN QUE HE VENIDO",0,4,"ae",8,0,-1,0,234,234,"C-315","",0,"","","",5,0,0,[],""],["carrizo_salta-nc0315-02",3,"Llevarte, mi bien, no puedo\nPorque es lejos donde voy,\nMas, si quieres padecer,\nVámonos juntos los dos.",3,1,0,33,"SABRÁS MI BIEN QUE HE VENIDO",0,4,"o",-1,0,-1,0,234,234,"C-315","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0315-03",3,"—Yo no siento el padecer,\nSi en caso me voy con vos;\nLo que siento es que me dejes.\n¿Cómo me quedo sin vos?",3,1,0,33,"SABRÁS MI BIEN QUE HE VENIDO",0,4,"o",-1,0,-1,0,234,234,"C-315","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0315-04",3,"¿Cómo me quedo sin vos,\nSin tu amante compañía?\nEmpezarán mis trabajos,\nPenas y melancolías.",3,1,0,33,"SABRÁS MI BIEN QUE HE VENIDO",0,4,"ia",-1,0,-1,0,234,234,"C-315","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0315-05",3,"Volvió la flor al jardín,\nVino el jardín a su ser,\nVolvieron a florecer\nLas flores que antes perdí.",3,1,0,33,"SABRÁS MI BIEN QUE HE VENIDO",5,4,"i",-1,0,-1,0,234,234,"C-315","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0316-01",3,"Si a mi lengua fácil fuera\nExplicarte lo que siento\nEn este amargo momento,\nDesahogos recibiera.\nSi algún alivio tuviera\nEn mis acerbas dolencias,\nSufriese las inclemencias\nCon que el cielo me castiga\nCuando ordena me persiga\nLa más injusta violencia.",3,1,0,33,"SI A MI LENGUA FÁCIL FUERA",18,10,"ea",-1,0,-1,0,234,234,"C-316","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0316-02",3,"No puedo, dueña querida,\nEvitar por más que quiero,\nEste paso tan severo\nDe mi triste despedida.\nMi alma ya está convencida\nDe ser ella irremediable,\nAunque es desagradable,\nSometer su corazón\nA la fuerza y al rigor\nDe un decreto irrevocable.",3,1,0,33,"SI A MI LENGUA FÁCIL FUERA",18,10,"ae",322,0,-1,0,234,234,"C-316","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0316-03",3,"Aunque es tan duro el prever\nLa llegada del instante\nEn que deje yo a mi amante\nEn medio de mi placer,\nQue prefiero el padecer\nY por la muerte pasar,\nAntes que ver asomar\nLa cruelísima ocasión\nEn que el cielo vengador\nMe ordene te deje ya.",3,1,0,33,"SI A MI LENGUA FÁCIL FUERA",18,10,"a",-1,0,-1,0,234,234,"C-316","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0316-04",3,"Aún sin querer, ha llegado\nEse momento fatal,\nEn que deje, a mi pesar,\nA mi objeto idolatrado.\nNo obstante, mí bien amado,\nNo me supongas variable,\nPues te juro que inviolable\nMi cariño sostendré,\nY si parto, partiré\nCon dolor inexplicable.",3,1,0,33,"SI A MI LENGUA FÁCIL FUERA",18,10,"ae",322,0,-1,0,234,234,"C-316","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0316-06",3,"Si Dios me presta la vida,\nY nos volvemos a ver,\nPuedo yo corresponder\nFinezas tan conocidas.\nPero, ¡adiós, prenda querida!\nAdiós, mi adorada gloria!\nTú estarás en mi memoria\nHasta que yo a Dios dé cuenta,\nAquí te dejo esta letra\nSiquiera para memoria.",3,1,0,33,"SI A MI LENGUA FÁCIL FUERA",18,10,"oa",-1,0,-1,0,235,235,"C-316","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0316-07",3,"Jamás pretendo olvidar\nA quien tal cariño me hace,\nn útil que me encontrase,\nCon franqueza ha de mandar,\nQue he de obedecer puntual,\nRecompensando el favor,\nEn prenda de este mi amor\nY tanto que la molesto,\nSiquiera en memoria de esto\nDejaré este borrador.",3,1,0,33,"SI A MI LENGUA FÁCIL FUERA",18,10,"o",72,0,-1,0,235,235,"C-316","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0318-01",3,"Te digo con sentimiento,\n¿Sabes que pienso dejarte?\nVida quisiera tener\nPara volver a mirarte.",3,1,0,33,"",0,4,"ae",8,0,-1,0,235,235,"C-318","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0318-02",3,"Mañana parto, ¡oh, verdad!\nCon gran dolor de mi pecho,\nTodo en lágrimas deshecho\nPorque quisiera quedar,\nCon vivos deseos de estar\nContigo a cada momento.\nRecibo el golpe violento,\nPues voy a dejar de verte,\nEn lo mejor de quererte,\nTe digo con sentimiento.",3,1,0,33,"",18,10,"eo",94,0,-1,0,235,235,"C-318","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0318-03",3,"Mañana me hallaré ausente,\nContemplando lo que dista,\nCareciendo de tu vista,\nPero te tendré presente.\nTú no saldrás de mi mente,\nPues cuando supe adorarte\nEl destino tomó parte\nEn nuestra separación\nCon tan enorme pasión.\n¿Sabes que pienso dejarte?",3,1,0,33,"",18,10,"ae",8,0,-1,0,235,235,"C-318","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0318-04",3,"No sé si soy o no soy\nCuando este caso ha llegado,\nSabes que pienso y no acabo,\nPorque te dejo y me voy.\nPero digo por quien soy\nQue siempre te he de querer,\nAunque pueda perecer\nEn los más grandes atrasos,\nPara estrecharte es mis brazos,\nVida quisiera tener.",3,1,0,33,"",18,10,"e",20,0,-1,0,235,235,"C-318","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0318-05",3,"Ya me voy, mi amado cielo,\nPorque el infortunio quiso.\nTe quedas, mi dulce hechizo,\nSiendo mi único consuelo.\nSabrás que si no me muero\nVolveré ansioso a abrazarte,\nPorque no podré olvidarte,\nY esto me pondrá capaz,\nPedir otros ojos más\nPara volver a mirarte.",3,1,0,33,"",18,10,"ae",8,0,-1,0,235,235,"C-318","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0319-01",3,"Trato de formar ausencia,\nDe este pueblo trato el irme,\nY a objeto de despedirme\nHe venido a tu presencia.\nQuizá con indiferencia\nMires hoy mi despedida,\nPero en mi amarga partida,\nUn consuelo llevaré,\nQue tus desprecios pagué\nCon mi pasión desmedida.",3,1,0,33,"TRATO DE FORMAR AUSENCIA",18,10,"ia",37,0,-1,0,236,236,"C-319","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0319-02",3,"Lastimado el corazón\nLo tengo constantemente,\nPero quiero ver si ausente,\nHallo alivio a mi dolor.\nBusco la separación\nA ver si hallo algún alivio,\nPorque un corazón herido,\nLleno de tantos pesares,\nBusca remedio a sus males\nEn la ausencia y el olvido.",3,1,0,33,"TRATO DE FORMAR AUSENCIA",18,10,"io",101,0,-1,0,236,236,"C-319","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0319-03",3,"Al ausentarme de aquí\nQuiero en todo ser cumplido,\nAunque en ti siempre haya habido\nIngratitud para mí.\nYo consideraba en ti\nUn ser muy bien estimado,\nPero me voy despreciado\nCon un desprecio iracundo,\nCuando nadie en este mundo\nComo yo te ha idolatrado.",3,1,0,33,"TRATO DE FORMAR AUSENCIA",18,10,"ao",14,0,-1,0,236,236,"C-319","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0319-04",3,"En fin, ya voy a ausentarme,\nComo claro te lo expreso,\nA ver si de tus desprecios\nPuedo algún día olvidarme.\nSi llegas a recordarme\nY sientes mi padecer,\nEntonces sólo has de ver\nEste recuerdo que dejo,\nDe un amante que tan lejos\nPor olvidarse se fué.",3,1,0,33,"TRATO DE FORMAR AUSENCIA",18,10,"e",-1,0,-1,0,236,236,"C-319","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0319-a-01",3,"Hoy trato formar ausencia,\nDe mi pago trato de irme,\nY a objeto de despedirme\nHe llegado a tu presencia.",3,1,0,33,"HOY TRATO FORMAR AUSENCIA",11,4,"ea",46,0,-1,0,236,236,"C-319-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0319-a-02",3,"Quizás con indiferencia\nMires hoy mi despedida,\nPero en mi amarga partida,\nUn consuelo llevaré,\nQue tus desprecios pagué\nCon cariño y simpatía.",3,1,0,33,"HOY TRATO FORMAR AUSENCIA",9,6,"ia",-1,0,-1,0,236,236,"C-319-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0319-a-03",3,"Lacerado el corazón\nLo llevo constantemente,\nPero quiero ver si ausente\nHallo alivio en mi dolor.\nBusco en la separación\nA ver si hallo algún alivio,\nPero un corazón herido,\nLleno de tantos pesares,\nBusca remedio a sus males\nEn la ausencia y el olvido.",3,1,0,33,"HOY TRATO FORMAR AUSENCIA",18,10,"io",101,0,-1,0,236,236,"C-319-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0319-a-04",3,"Pero si voy a ausentarme,\nComo claro te lo expreso,\nPara ver si tus desprecios\nPuedo algún día olvidarme,\nSi llegas a recordarme\nY sientes mi padecer,\nLlegarás a conocer,\nEste recuerdo que dejo\nUn amante que tan lejos\nPor olvidarte se fué.",3,1,0,33,"HOY TRATO FORMAR AUSENCIA",18,10,"e",-1,0,-1,0,236,236,"C-319-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0320-01",3,"Vaga la imaginación\nEn funestos pensamientos,\nSirviéndome de tormentos\nLa misma meditación.\nQuiero ocultar mi pasión\nPero al momento deliro,\nY cuando ya me retiro\nDe la prenda que yo adoro,\nA cada momento lloro,\nMi corazón da un suspiro.",3,1,0,33,"VAGA LA IMAGINACIÓN",18,10,"io",222,0,-1,0,236,236,"C-320","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0320-02",3,"Si allá en la eterna morada\nMe está prohibido el quererte,\nNo me ha de privar tenerte\nDentro mi pecho grabada.\nMas si te hallo sepultada\nAntes que yo me haya muerto,\nTen por seguro y por cierto\nQue sobre la losa fría,\nRegaré de noche y día\nCon mis lágrimas tus restos.",3,1,0,33,"VAGA LA IMAGINACIÓN",18,10,"eo",-1,0,-1,0,236,236,"C-320","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0320-04",3,"Sólo contemplando estoy\nDe mi muerte la amargura,\nMirando una sepultura\nCuyo poseedor yo soy.\nSuspiros al cielo doy\nDe tan penosa partida,\nPorque ya es tiempo, querida,\nDe que yo pague mi culpa,\nEsta mi muerte resulta,\nDe esta triste despedida.",3,1,0,33,"VAGA LA IMAGINACIÓN",18,10,"ia",37,0,-1,0,237,237,"C-320","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0320-05",3,"¡Adiós, preciosa hermosura!\nYa me voy a retirar,\nYa mi vida va a acabar,\nEntre penas y amarguras.\nMás, si tengo la ventura\nDe poder morir hablando,\nTu nombre estaré invocando,\nDándote el último adiós,\nAllí te llamaré a vos\nCuando estuviere expirando.",3,1,0,33,"ADIÓS PRECIOSA HERMOSURA",18,10,"ao",33,0,-1,0,237,237,"C-320","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0320-06",3,"Más, si en la eterna morada,\nLe está prohibido el quererte,\nNadie me ha i privar tenerte,\nDentro mi pecho grabada.\nY si te hallas sepultada,\nAntes que yo hubiera muerto,\nVen por seguro y por cierto,\nQue sobre la losa fría,\nLlegaré de noche y día,\nCon mis lágrimas tus restos.",3,1,0,33,"ADIÓS PRECIOSA HERMOSURA",18,10,"eo",-1,0,-1,0,237,237,"C-320","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0321-01",3,"Ya camino, ya me voy,\nYa me voy a retirar,\nDame la mano, querida,\nQue ya no te podré hablar.",3,1,0,33,"YA CAMINO YA ME VOY",0,4,"a",21,0,-1,0,237,237,"C-321","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0321-02",3,"Al tomarte de la mano,\nSólo me falta llorar,\nCon el corazón rendido\nYa me voy a retirar.",3,1,0,33,"YA CAMINO YA ME VOY",0,4,"a",21,0,-1,0,237,237,"C-321","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0321-03",3,"¡Adiós, esmeralda fina!\n¡Adiós, clavel encarnado!\n¡Adiós, vida de mi vida!\n¡Adiós, corazón amado!",3,1,0,33,"YA CAMINO YA ME VOY",0,4,"ao",14,0,-1,0,237,237,"C-321","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0322-01",3,"Ya llega el momento, ya,\nMi bien de decirte adiós,\n¡Adiós, mi prenda de amor,\nNo sé hasta cuándo será!",3,1,0,33,"YA LLEGA EL MOMENTO YA",5,4,"a",9,0,-1,0,237,237,"C-322","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0322-02",3,"De confusión mucho más,\nMi triste corazón parte,\nAl ver que para dejarte\nYa llega el momento, ya.",3,1,0,33,"YA LLEGA EL MOMENTO YA",5,4,"a",-1,0,-1,0,237,237,"C-322","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0322-03",3,"Con el puñal más atroz,\nQue parte un pecho sensible,\nMe es este lance terrible,\nMi bien, de decirte adiós.",3,1,0,33,"YA LLEGA EL MOMENTO YA",11,4,"o",87,0,-1,0,237,237,"C-322","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0322-04",3,"Antes que este gran dolor\nConsuma mi triste vida,\nEs preciso que te diga:\n¡Adiós, mi prenda de amor!",3,1,0,33,"YA LLEGA EL MOMENTO YA",5,4,"o",72,0,-1,0,237,237,"C-322","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0322-05",3,"Al fin, entre mi pesar,\nTe dejo mi corazón,\nPorque mi separación\nNo sé hasta cuándo será.",3,1,0,33,"YA LLEGA EL MOMENTO YA",5,4,"a",-1,0,-1,0,237,237,"C-322","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0323-01",3,"Ya que la suerte me priva,\nMi bien, de tus luces bellas,\nQuiero con lágrimas tristes,\nLlorar mis amargas penas.",3,1,0,33,"YA QUE LA SUERTE ME PRIVA",0,4,"ea",-1,0,-1,0,238,238,"C-323","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0323-02",3,"¡Adiós, que el alma te dejo\nEn dos mitades partida,\nSacrificada a tus aras,\nYa que la suerte me priva!",3,1,0,33,"YA QUE LA SUERTE ME PRIVA",0,4,"ia",-1,0,-1,0,238,238,"C-323","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0323-04",3,"¡Adiós, y sólo te pido\nQue mis finezas no olvides!\nY mira que encarecerlo,\nQuiero con lágrimas tristes.",3,1,0,33,"YA QUE LA SUERTE ME PRIVA",0,4,"ie",-1,0,-1,0,238,238,"C-323","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0323-05",3,"¡Adiós, en fin, pues te quedas!\nEscucha, mi bien, mis quejas,\nQue sabré, pues, que te quise,\nLlorar mis amargas penas.",3,1,0,33,"YA QUE LA SUERTE ME PRIVA",0,4,"ea",-1,0,-1,0,238,238,"C-323","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0323-09",3,"Él bien sabe que me miro\nSin alivio ni consuelo,\ndando ayes por tu cielo,\nÉl te dirá si respiro.",3,1,0,34,"AHÍ TE MANDO UN ¡AY, DE MI!",11,4,"io",222,0,-1,0,240,240,"C-323","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0323-10",3,"Por fin, el alma te dí,\nel ser firme te juré,\nEs justo que mi amor dé,\nSólo ayes, lejos de tí?",3,1,0,34,"AHÍ TE MANDO UN ¡AY, DE MI!",11,4,"i",23,0,-1,0,240,240,"C-323","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0325-02",3,"Ausente de vuestro amor\nPuedes creer, dueña de mi alma,\nQue jamás encuentra calma\nMi afligido corazón.\nMira esta separación\nCon una tristeza tal,",3,1,0,34,"AMARGO ES MI PADECER",9,6,"a",-1,0,-1,0,240,240,"C-325","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0325-03",3,"Tan sólo al considerar\nQue un destino desgraciado,\nMe priva de que a tu lado\nPueda de un placer gozar.",3,1,0,34,"AMARGO ES MI PADECER",11,4,"a",21,0,-1,0,240,240,"C-325","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0325-04",3,"Nunca llegué a imaginar\nEl separarme de vos,\nAsí lo dispuso Dios,\nNo se puede remediar.\nSerá un profundo pesar\nA un corazón desgraciado,\nSi así lo ha determinado\nEl Poderoso al instante,\nViviremos siendo amantes,\nEn el mundo separados.",3,1,0,34,"AMARGO ES MI PADECER",18,10,"ao",-1,0,-1,0,240,240,"C-325","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0325-05",3,"Y si nos ha separado\nUn poder tan iracundo,\nSeremos en este mundo,\nDos amantes desgraciados.\nY si me veo privado\nDe mi existencia al morir,\nSabrás que antes de partir,\nPor tu dicha a Dios rogué,\nY que de tí me acordé,\nTriste, al dejar de existir.",3,1,0,34,"AMARGO ES MI PADECER",18,10,"i",157,0,-1,0,240,240,"C-325","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0325-06",3,"Ausente de vuestro amor,\nPuedes creer, dueña del alma,\nQue jamás encuentra calma\nMi afligido corazón.\nMira esta separación\nCon una tristeza tal,\nTan sólo al considerar\nQue un destino desgraciado,\nMe priva de que a tu lado,\nPueda de un placer gozar.",3,1,0,34,"AUSENTE DE VUESTRO AMOR",18,10,"a",21,0,-1,0,240,240,"C-325","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0325-07",3,"Nunca llegué a imaginar\nEl separarme de vos,\nPero lo ha dispuesto Dios,\nNo se puede remediar.\nEs un profundo pesar\nPara un pobre desgraciado,\nSi así lo ha determinado,\nEl Poderoso al instante,\nViviremos siendo amantes,\nEn el mundo separados.",3,1,0,34,"AUSENTE DE VUESTRO AMOR",18,10,"ao",-1,0,-1,0,240,241,"C-325","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0325-08",3,"Bien sabes, prenda querida,\nQue una causa poderosa,\nHe tenido, y fué forzosa\nNuestra triste despedida.\nMi alma, de dolor transida\nSe encuentra constantemente,\nY si me privara el verte\nLa eterna fatalidad,\nMi amor te acompañará\nHasta el trance de la muerte.",3,1,0,34,"AUSENTE DE VUESTRO AMOR",18,10,"ee",134,0,-1,0,241,241,"C-325","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0325-09",3,"Y si nos ha separado\nEl poder más iracundo,\nSeremos en este mundo,\nDos amantes desgraciados.\nY si me veo privado\nDe mi existencia al partir,\nSabrás que antes de morir,\nPor tu dicha a Dios rogué,\nY tu nombre recordé\nTriste, al dejar de existir.",3,1,0,34,"AUSENTE DE VUESTRO AMOR",18,10,"i",157,0,-1,0,241,241,"C-325","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0326-01",3,"Aún cuando lejos de tí\nMe detiene el hado impío,\nSé que me quieres, bien mío,\nY que has de pensar en mí.\nOjalá que siempre así,\nGuarde tu pecho inocente,\nEn este amor que presiente\nTanta dicha el alma mía,\nY sin el cual viviría\nDesgraciado eternamente.",3,1,0,34,"AUN CUANDO LEJOS DE TI",18,10,"ee",15,0,-1,0,241,241,"C-326","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0326-02",3,"Aunque de tí, separado,\nPor mil causas que lamento,\nMi amoroso pensamiento,\nNo se aparta de tu lado.\nTu nombre siempre adorado,\nConstituye mi ventura,\nY en sus horas de amargura\nSe alegra mi corazón,\nRecordando con pasión\nTu cariño y tu hermosura.",3,1,0,34,"AUN CUANDO LEJOS DE TI",18,10,"ua",17,0,-1,0,241,241,"C-326","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0326-03",3,"Mi ardiente imaginación\nMira en tí un ángel del cielo,\nBajando a traer el consuelo\nQue falta a mi corazón.\nMi más risueña ilusión\nHa sido, hermoso lucero,\nDemostrarte el verdadero\nAmor que mi pecho siente,\nY que a tu lado o ausente,\nAún más, mi vida, te quiero.",3,1,0,34,"AUN CUANDO LEJOS DE TI",18,10,"eo",38,0,-1,0,241,241,"C-326","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0326-04",3,"En tí, morena querida,\nTodo mi encanto se encierra,\nY eres la única en la tierra,\nQue me hace desear la vida.\nMi corazón no te olvida,\nPor más que no pueda verte,\nY este anhelo de quererte,\nQue alimenta mi existencia,\nTan sólo con su inclemencia\nPodrá extinguirlo la muerte.",3,1,0,34,"AUN CUANDO LEJOS DE TI",18,10,"ee",134,0,-1,0,241,241,"C-326","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0327-01",3,"Ausente del alma mía,\nLa muerte más bien deseo,\nYa para mí no hay placer,\nEl rato que no te veo.",3,1,0,34,"AUSENTE DEL ALMA MÍA",0,4,"eo",66,0,-1,0,241,241,"C-327","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0327-02",3,"Lloraré toda mi vida,\nSiempre buscando tus brazos,\nEl corazón a pedazos,\nCon el alma enternecida.\nPorque mi pasión crecida,\nCon más fuerzas y porfía,\nBuscará tu idolatría,\nPara tranquilo vivir,\nQue ya no puedo existir\nAusente del alma mía.",3,1,0,34,"AUSENTE DEL ALMA MÍA",18,10,"ia",0,0,-1,0,241,241,"C-327","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0327-04",3,"Si me quiero consolar,\nBusco mi bien adorado,\nSi no lo encuentro a mi lado,\nTriste me pongo a llorar,\nAsí en esta soledad,\nMe abraza una pena impía,\nSin tener a quien quería,",3,1,0,34,"AUSENTE DEL ALMA MÍA",4,7,"ia",0,0,-1,0,241,242,"C-327","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0328-01",3,"Ausente de tí, mi vida,\nHe vivido suspirando,\nTan sólo en tu amor pensando,\nDueña del alma querida.\nSi fué triste mi partida\nCuando salí de tu lado,\nPiensa cuánto me ha costado\nTodo este tiempo perdido,\nPero por fin he venido\nA buscar lo que he dejado.",3,1,0,34,"AUSENTE DE TI MI VIDA",18,10,"ao",14,0,-1,0,242,242,"C-328","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0328-03",3,"Ya no queda otro consuelo\nPara el infeliz amante,\nDe una mujer inconstante,\nQue tan mal paga su anhelo.\nY si es castigo del cielo,\nPorque te he querido tanto,\nJusto es que vierta mi llanto\nPor tus desdenes herido,\nHasta que caiga rendido\nAl peso del desencanto.",3,1,0,34,"AUSENTE DE TI MI VIDA",18,10,"ao",30,0,-1,0,242,242,"C-328","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0328-04",3,"Dejaré el tiempo pasar,\nBuscaré en la ausencia calma,\nQue a las heridas del alma,\nLa suele el tiempo curar.\nSi no te puedo olvidar,\nVolveré, ingrata, a quererte,\nHasta que por fin la muerte,\nPonga término a mis penas,\nYa que tan cruel me encadena\nA vivir contra la suerte.",3,1,0,34,"AUSENTE DE TI MI VIDA",18,10,"ee",134,0,-1,0,242,242,"C-328","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0328-05",3,"Ya me voy a retirar,\nYa me obligan que te deje,\nMe voy y aún cuando me aleje\nDe tí, no podré olvidar,\nSi no has de recompensar\nMi pasión con mútuo amor,\nMás bien me será mejor,\nQuitarme de tu presencia,\nPara que con complacencia\nAceptes nuevo amador.",3,1,0,34,"AUSENTE DE TI MI VIDA",18,10,"o",72,0,-1,0,242,242,"C-328","",0,"","","",9,0,0,[],""],["carrizo_salta-nc0329-01",3,"¡Ay, dulce hechizo del alma!\n¿Cómo viviré sin tí?\n¿Qué corazón tendré yo\nPara amar y no sentir?",3,1,0,34,"AY DULCE HECHIZO DEL ALMA",0,4,"i",-1,0,-1,0,242,242,"C-329","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0329-02",3,"Mi corazón afligido,\nSus tristes penas lloraba,\nY suspirando decía:\n—¡Ay, dulce hechizo del alma!",3,1,0,34,"AY DULCE HECHIZO DEL ALMA",0,4,"aa",-1,0,-1,0,242,242,"C-329","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0329-03",3,"Si tus cariños han sido\nUn encanto para mí,\nRepara, contempla y mira,\nCómo viviré sin tí.",3,1,0,34,"AY DULCE HECHIZO DEL ALMA",0,4,"i",23,0,-1,0,242,242,"C-329","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0329-04",3,"Si el influjo de tu amor,\nEl ser a mi alma ha quitado,\nFaltándome todo el ser,\n¿Qué corazón tendré yo?",3,1,0,34,"AY DULCE HECHIZO DEL ALMA",5,4,"o",-1,0,-1,0,242,242,"C-329","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0329-05",3,"Bien conozco que tu ausencia,\nDe muerte me ha de servir,\nPor que no soy tan infiel,\nPara amar y no sentir.",3,1,0,34,"AY DULCE HECHIZO DEL ALMA",0,4,"i",157,0,-1,0,242,242,"C-329","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0330-01",3,"Como no te puedo ver,\nY en tí yo vivo pensando,\nHoy mis caricias te mando\nPor medio de este papel.",3,1,0,34,"COMO NO TE PUEDO VER",5,4,"e",-1,0,-1,0,242,242,"C-330","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0330-02",3,"Escucha, prenda querida,\nQue hoy me despido de vos,\nQue viene tu aborrecido\nA darte el último adiós.",3,1,0,34,"COMO NO TE PUEDO VER",0,4,"o",87,0,-1,0,243,243,"C-330","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0330-03",3,"Ya me voy, mi dueña mía,\nPara nunca más volver,\nPor que es grande mi dolor.\nDe verte en otro poder.",3,1,0,34,"COMO NO TE PUEDO VER",0,4,"e",20,0,-1,0,243,243,"C-330","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0330-04",3,"Ya me despido, mi dueña,\nCon llanto en mi corazón,\nLlorando gotas de sangre,\nDe ver mi separación.",3,1,0,34,"COMO NO TE PUEDO VER",0,4,"o",31,0,-1,0,243,243,"C-330","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0330-05",3,"Me pesa de haberte visto\nPara tener que pensar,\nComo me veo aborrecido,\nMe consuelo con llorar.",3,1,0,34,"COMO NO TE PUEDO VER",0,4,"a",21,0,-1,0,243,243,"C-330","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0330-06",3,"¡Adiós, prenda de mi vida!\nYa me voy, ¡Adiós, Adiós!\n¡Adiós, corazón amado,\nLlorando me voy por vos!",3,1,0,34,"COMO NO TE PUEDO VER",0,4,"o",87,0,-1,0,243,243,"C-330","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0331-01",3,"Cuando me vine, ¡ay de mí!\nLas aves que me miraban,\nJunto conmigo lloraban,\nAl verme llorar por tí.",3,1,0,34,"CUANDO ME VINE ¡AY DE MI!",11,4,"i",23,0,-1,0,243,243,"C-331","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0331-02",3,"La gloria que recibí,\nEstando con tu hermosura,\nSe convirtió en amargura\nCuando me vine, ¡ay de mí!",3,1,0,34,"CUANDO ME VINE ¡AY DE MI!",11,4,"i",23,0,-1,0,243,243,"C-331","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0331-03",3,"Tanto mis ojos lloraban\nTu ausencia, querido encanto,\nQue acompañaban mi llanto\nLas aves que me miraban.",3,1,0,34,"CUANDO ME VINE ¡AY DE MI!",11,4,"aa",39,0,-1,0,243,243,"C-331","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0331-04",3,"Y ¡cómo se consternaban\nDe mi insufrible tormento!\nUnidas al sentimiento,\nJunto conmigo lloraban.",3,1,0,34,"CUANDO ME VINE ¡AY DE MI!",11,4,"aa",39,0,-1,0,243,243,"C-331","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0331-05",3,"Tanto tu ausencia sentí,\nQue aún los brutos animales,\nSe consternaban iguales\nAl verme llorar por tí.",3,1,0,34,"CUANDO ME VINE ¡AY DE MI!",11,4,"i",23,0,-1,0,243,243,"C-331","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0332-02",3,"¡Contempla cómo me iría,\nOh, mi cielo apasionado!\nTan triste y desconsolado,\nDejando lo que quería.\nPuedes pensar, vida mía,\nCon qué amor me despedí,\nQue para decirte así,\nHasta sin vida quedé,\nQue hasta el alma te dejé\nCuando me vine, ¡ay, de mí!",3,1,0,34,"CUANDO ME VINE ¡AY! DE MI",18,10,"i",23,0,-1,0,243,243,"C-332","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0332-03",3,"Por esos campos, gimiendo,\nVenía mi corazón,\nHecho un mar de confusión,\nSus desdichas maldiciendo.\nSólo en mí se venían viendo,\nLos actos que me pasaban,\nPero como no cesaban\nMis ojos de llorar tanto,\nSoltaban la rienda al llanto,\nLas aves que me miraban.",3,1,0,34,"CUANDO ME VINE ¡AY! DE MI",18,10,"aa",39,0,-1,0,243,243,"C-332","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0332-04",3,"En la más triste espesura,\nEn el más solo lugar,\nAhí me puse a contemplar,\nEn tu pulida hermosura,\nY allí con grande ternura,\nMis lágrimas derramaba,\nCuando mis penas me ahogaban,\nEran mis lamentos tales,\nQue aún los brutos animales,\nJunto conmigo lloraban.",3,1,0,34,"CUANDO ME VINE ¡AY! DE MI",18,10,"aa",39,0,-1,0,243,243,"C-332","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0332-05",3,"Al fin, Dios me dé la gloria,\nEn ese infausto retiro,\nQue no me das un suspiro,\nSiquiera para memoria.\nMi constancia es muy notoria,\nQue no me olvido de tí,\nBien puedo decirte así,\nDueña de mi corazón,\nQue no tienes compasión\nAl verme llorar por tí.",3,1,0,34,"CUANDO ME VINE ¡AY! DE MI",18,10,"i",23,0,-1,0,243,243,"C-332","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0333-01",3,"De qué sirve la esperanza\nCuando el mal es sin remedio?\nNi de qué sirve el amor\nCuando no se goza el dueño?",3,1,0,34,"DE QUE SIRVE LA ESPERANZA",0,4,"eo",-1,0,-1,0,244,244,"C-333","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0333-02",3,"Dueño ausente de mi vida,\nNo de mi memoria ausente,\nQue como estás en mi pecho,\nSiempre te tengo presente.",3,1,0,34,"DE QUE SIRVE LA ESPERANZA",0,4,"ee",15,0,-1,0,244,244,"C-333","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0333-03",3,"Pero como falta en mí\nHablarte, verte y gozarte,\nLe aflige tanto este mal,\nQue el corazón se me parte.",3,1,0,34,"DE QUE SIRVE LA ESPERANZA",0,4,"ae",8,0,-1,0,244,244,"C-333","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0333-04",3,"No llores, corazón mío,\nCorazón, no llores más!\nSabed lo que es padecer,\nPues sabes lo que es amar.",3,1,0,34,"DE QUE SIRVE LA ESPERANZA",0,4,"a",-1,0,-1,0,244,244,"C-333","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0334-01",3,")esde aquí te envío un beso,\nC ansío que llegue a tí,\nPara que estando a tu lado,\nSTunca te olvides de mí.",3,1,0,34,"DESDE AQUÍ TE ENVIÓ UN BESO",0,4,"i",23,0,-1,0,244,244,"C-334","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0334-02",3,"31 te dirá que estoy triste,\nSin consuelo en mi dolor,\nMarchitas las ilusiones\nComo deshojada flor.",3,1,0,34,"DESDE AQUÍ TE ENVIÓ UN BESO",0,4,"o",72,0,-1,0,244,244,"C-334","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0334-03",3,"Te dirá que el cruel destino,\nMe ha condenado a llorar,\nMás, mis penas y alegrías\nNo te quisiera contar.",3,1,0,34,"DESDE AQUÍ TE ENVIÓ UN BESO",0,4,"a",21,0,-1,0,244,244,"C-334","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0334-04",3,"Cantando paso los días,\nCantando sé suspirar,\nCantando mi triste vida,\nQuisiera al cielo volar.",3,1,0,34,"DESDE AQUÍ TE ENVIÓ UN BESO",0,4,"a",21,0,-1,0,244,244,"C-334","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0334-05",3,"Y cuando deje esta tierra,\nTe voy a esperar allí,\nPara que me des el beso\nQue en este mundo te dí.",3,1,0,34,"DESDE AQUÍ TE ENVIÓ UN BESO",0,4,"i",23,0,-1,0,244,244,"C-334","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0335-01",3,"Dueña mía y apreciada,\nDueña de mi pensamiento,\nYo vengo en este momento,\nDe mi vida acongojada,\nA saber, mi bien amada,\nSi he de gozar vuestro amor;\nPorque no hay tormento peor\nPara un hombre que ama tanto,\nComo sufrir el quebranto\nDe un amor engañador.",3,1,0,34,"DUEÑA MÍA Y APRECIADA",18,10,"o",72,0,-1,0,244,244,"C-335","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0336-01",3,"En un retiro, bien mío,\nPor mis desdichas me ausento;\nY me ocupo en escribirte,\nYa que verte no merezco.",3,1,0,34,"EN UN RETIRO BIEN MIÓ",0,4,"eo",-1,0,-1,0,244,244,"C-336","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0336-02",3,"La pluma será el dolor,\nQue mi pecho va rasgando,\nEl secretario mi amor,\nPara que vaya copiando.",3,1,0,34,"EN UN RETIRO BIEN MIÓ",1,4,"ao",33,0,-1,0,244,244,"C-336","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0336-03",3,"Las lágrimas de mis ojos,\nQue por vos voy derramando,\nSerá la tinta con qué,\nLas letras iré formando.",3,1,0,34,"EN UN RETIRO BIEN MIÓ",0,4,"ao",33,0,-1,0,244,244,"C-336","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0336-04",3,"Los renglones son las noches\nQue por vos me he desvelado,\nEn sólo considerar\nLas penas que estoy pasando.",3,1,0,34,"EN UN RETIRO BIEN MIÓ",0,4,"ao",-1,0,-1,0,244,244,"C-336","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0336-05",3,"El papel será la pena\nEn que iré representando,\nA tan altiva hermosura,\nSin escribir ningún blanco.",3,1,0,34,"EN UN RETIRO BIEN MIÓ",0,4,"ao",-1,0,-1,0,244,244,"C-336","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0337-01",3,"Regalada, prenda mía,\nBuena, sin novedad se halle.\nCon la salud que deseo,\nPido al cielo que la guarde,",3,1,0,34,"REGALADA PRENDA MÍA",0,4,"ae",-1,0,-1,0,245,245,"C-337","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0337-02",3,"Hermosa aurora, belleza,\nDeidad, jardín peregrino,\nA vuestro cielo divino,\nEsta carta con cordura,\nLa remito a su hermosura\nEn este dichoso día,\nPara que con alegría,\nPueda saber si está buena,\nHermosísima azucena,\nRegalada, prenda mía.",3,1,0,34,"REGALADA PRENDA MÍA",18,10,"ia",0,0,-1,0,245,245,"C-337","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0337-03",3,"De mi amor recibirá\nSecretísimas memorias,\nY dándole las notorias,\nDel mucho amor que en mí vive,\nYo le pido, si me escribe,",3,1,0,34,"REGALADA PRENDA MÍA",7,5,"ie",370,0,-1,0,245,245,"C-337","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0337-04",3,"Yo le pido, si me escribe,\nNo me dé su resplandor,\nSi he de gozar de su amor,\nBuena, sin novedad se halle.",3,1,0,34,"REGALADA PRENDA MÍA",5,4,"ae",-1,0,-1,0,245,245,"C-337","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0337-05",3,"Sepa, mi princesa amada,\nQue yo servirla prefiero,\nY que ser su amante quiero,\nEs verdad muy declarada,\nAhí lo verá, prenda amada,\nSin el más mínimo alarde.\nSu respuesta no sea tarde,\nHermosísima deidad,\nQue yo de mi voluntad,\nPido al cielo que la guarde.",3,1,0,34,"REGALADA PRENDA MÍA",18,10,"ae",344,0,-1,0,245,245,"C-337","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0337-06",3,"Quiero saber, prenda amada,\nSi he de ser merecedor\nDe su cariño un deudor,\nEn mis amores triunfante,\nHe de ser su fiel amante.",3,1,0,34,"REGALADA PRENDA MÍA",7,5,"ae",47,0,-1,0,245,245,"C-337","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0338-01",3,"¡Mar inmenso que te agitas,\nSobre tu lecho de arena!\nY ahora en bonanza plena,\nTus olas no precipitas,",3,1,0,34,". MAR INMENSO QUE TE AGITAS",11,4,"ia",258,0,-1,0,245,245,"C-338","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0338-02",3,"Tú que bañas las benditas\nRiberas donde nací,\nLos sitios donde la ví,\nTan pura, radiante y bella,\nResponde si piensa en mí,\nComo estoy pensando en ella.",3,1,0,34,". MAR INMENSO QUE TE AGITAS",9,6,"ea",6,0,-1,0,245,245,"C-338","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0338-03",3,"¡Nubes, que en blancos celajes,\nBordas el azul del cielo,\nCual ave que alza su vuelo\nSobre el inmenso paisaje!\nDecidme si en vuestro viaje,\nLejos, muy lejos de aquí,\nLlegasteis a verla, dí,\nSi estará radiante y bella,\nSi estará pensando en mí,\nComo estoy pensando en ella.",3,1,0,34,". MAR INMENSO QUE TE AGITAS",18,10,"ea",6,0,-1,0,245,245,"C-338","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0338-04",3,"¡Sol, espléndido y radiante,\nEn la ancha esfera sujeto!\nNo te pregunto el secreto\nDe tu esplendor rutilante,\nNi por qué nubes distantes\nTiñen de ópalo y rubí,\nPero, perdóname si,\nTe pregunto en mi querella\nSi estará pensando en mí,\nComo estoy pensando en ella.",3,1,0,34,". MAR INMENSO QUE TE AGITAS",18,10,"ea",6,0,-1,0,245,245,"C-338","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0338-05",3,"¡Luna, brillante topacio!\nQue cual nebuloso tul\nBañas la techumbre azul\nEn las salas del espacio,\nSi se fijaron despacio\nSus bellos ojos en tí,\nDíme si la viste y sí\nEstaba doliente y bella,\nSi estará pensando en mí\nComo estoy pensando en ella.",3,1,0,34,". MAR INMENSO QUE TE AGITAS",18,10,"ea",6,0,-1,0,245,245,"C-338","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0338-06",3,"¡Brisa, que acaso pasando\nJugastes con sus cabellos!\nBesando su blanco cuello\nSu mejilla acariciando,\nY si luego suspirando,\nTe fuístes lejos de aquí,\nO si lo mismo que allí\nPasaste sin dejar huella,\nResponde si piensa en mí,\nComo estoy pensando en ella.",3,1,0,34,". MAR INMENSO QUE TE AGITAS",18,10,"ea",6,0,-1,0,245,245,"C-338","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0338-07",3,"¡Sol, estrellas, mar y viento,\nBrisa y nubes, ayúdame!\nEn vuestro idioma contadme\nSi es mío su pensamiento,\nSi es igual su sentimiento\nA aquel que mi pecho hiere,\nSi es que su amor prefiere\nLa dicha que perdió,\nResponde si ella me quiere\nLo mismo que la amo yo.",3,1,0,34,". MAR INMENSO QUE TE AGITAS",18,10,"o",2,0,-1,0,245,246,"C-338","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0338-a-01",3,"Sol, espléndido y brillante,\nEn la ancha esfera sujeto!\nNo te pregunto el secreto\nDe tu esplendor rutilante,\nNi por qué nube distante,\nTiñe de ópalo y rubí,\nPero perdóname, sí,\nTe pregunto en mis querellas,\nSi estará pensando en mí\nComo estoy pensando en ella.",3,1,0,34,"SOL ESPLENDIDO Y BRILLANTE",18,10,"ea",-1,0,-1,0,246,246,"C-338-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0338-a-02",3,"¡Luna, brillante topacio,\nQue cual nebuloso tul,\nCruzas la techumbre azul\nDe las salas del espacio!\n¿Si se fijarán despacio\nSus bellos ojos en mí?\nY si la miraste dí,\nSi estaba doliente y bella,\nResponde si piensa en mí\nComo estoy pensando en ella.",3,1,0,34,"SOL ESPLENDIDO Y BRILLANTE",18,10,"ea",6,0,-1,0,246,246,"C-338-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0338-a-03",3,"¡Brisa, que acaso pasando,\nJugastes con sus cabellos!\nTú que besaste su cuello,\nSu mejilla acariciando,\nY que después, suspirando,\nLejos, muy lejos de mí,\nO si lo mismo que aquí\nPasaste sin dejar huella,\nResponde si piensa en mí\nComo estoy pensando en ella.",3,1,0,34,"SOL ESPLENDIDO Y BRILLANTE",18,10,"ea",6,0,-1,0,246,246,"C-338-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0338-a-05",3,"Decime si estando ausente,\nDe mi amor ya se olvidó,\nO si su amor es ardiente\nLo mismo que la amo yo.",3,1,0,34,"SOL ESPLENDIDO Y BRILLANTE",1,4,"o",2,0,-1,0,246,246,"C-338-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0339-01",3,"Mucho me acuerdo de tí,\nMucho lloro por tu ausencia,\nTú no te acuerdas de mí,\n¡Mira la correspondencia!",3,1,0,34,"MUCHO ME ACUERDO DE TI",1,4,"ea",46,0,-1,0,246,246,"C-339","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0339-02",3,"Me acuerdo de los enojos\nQue sin causa me fingías,\nTambién de las alegrías,\nQue me brindaban tus ojos.\nMe acuerdo de los sonrojos\nQue por tu amor padecí,\nTambién me acuerdo que ví,\nTus mejillas como rosas,\nY por todas estas cosas,\nMucho me acuerdo de tí.",3,1,0,34,"MUCHO ME ACUERDO DE TI",18,10,"i",23,0,-1,0,246,246,"C-339","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0339-03",3,"¿Quién venciera ese embarazo,\nDulce amada, prenda mía?\n¿Quién me viera noche y día\nEncadenado a tus brazos?\n¿Quién dirigiera mis pasos\nA tu celestial presencia?\nPero veo en mis dolencias\nQue alcanzar esto no es dable,\nY con un llanto incansable,\nMucho lloro por tu ausencia.",3,1,0,34,"MUCHO ME ACUERDO DE TI",18,10,"ea",-1,0,-1,0,246,246,"C-339","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0339-04",3,"Cada vez que me levanto,\nSi es que alguna vez me acuesto,\nMe parece que molesto,\nA las aves con mi llanto.\nOtro que padezca tanto,\nEn mi vida, conocí,\nYo estoy haciendo por tí,\nDe mis lágrimas un lago,\nY ahora por darme mal pago,\nTú no te acuerdas de mí.",3,1,0,34,"MUCHO ME ACUERDO DE TI",18,10,"i",23,0,-1,0,246,246,"C-339","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0339-05",3,"En tan grande desventura\nMe iré para otra campaña,\nY entre lóbregas montañas,\nCavaré mi sepultura;\nPorque la muerte me apura",3,1,0,34,"MUCHO ME ACUERDO DE TI",7,5,"ua",17,0,-1,0,246,246,"C-339","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0339-06",3,"Con tan terrible violencia,\nQue digo con evidencia,\nQue me muero por tu amor,\nY me pagas con rigor,\n¡Mira la correspondencia!",3,1,0,34,"MUCHO ME ACUERDO DE TI",7,5,"ea",46,0,-1,0,247,247,"C-339","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0339-a-01",3,"¿Quién venciera este embarazo,\nDulce amada, prenda mía?\n¿Quién se hallare noche y día\nEncanenado en tus brazos?\n¿Quién dirigiera sus pasos\nA tu graciosa presencia?\nPero viendo en tu indolencia,\nQue alcanzar esto no es dable,\nCon un llanto incomparable\nMucho lloro por tu ausencia.",3,1,0,34,"QUIEN VENCIERA ESTE EMBARAZO",18,10,"ea",46,0,-1,0,247,247,"C-339-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0339-a-02",3,"Tempranito me levanto,\nSi es que alguna vez me acuesto;\nMe parece que molesto\nA las aves con mi llanto.\nOtro que te quiera tanto,\nEn mi vida, conocí.\nYo estoy haciendo por tí\nDe mis lágrimas un lago,\nY tú por darme un mal pago,\nYa no te acuerdas de mí.",3,1,0,34,"QUIEN VENCIERA ESTE EMBARAZO",18,10,"i",23,0,-1,0,247,247,"C-339-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0339-a-03",3,"Por mi grande desventura,\nMe iré para otras campañas,\nEntre lóbregas montañas,\nCavaré mi sepultura,\nPues ya la muerte me apura,\nCon tan terrible violencia,\nTe digo con evidencia,\nQue si muero por tu amor,\nNo me trates con rigor,\nQue esa no es correspondencia.",3,1,0,34,"QUIEN VENCIERA ESTE EMBARAZO",18,10,"ea",46,0,-1,0,247,247,"C-339-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0340-01",3,"¡Ojos, rasgad la corriente,\nLlorad sin intermisión,\nLlorad que tenéis razón,\nPues está tu dueño ausente!",3,1,0,34,"OJOS RASGAD LA CORRIENTE",11,4,"ee",15,0,-1,0,247,247,"C-340","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0340-02",3,"Los gustos ya para mí,\nSin remedio se acabaron,\nYa los placeres faltaron,\nMi bien, desde que os perdí.\nYa no seré lo que fuí,\nQue el placer no lo consiente,\nY pues, hallo solamente,\nAlgún alivio en llorar,\nPara templar el pesar,\n¡Ojos, rasgad la corriente!",3,1,0,34,"OJOS RASGAD LA CORRIENTE",18,10,"ee",15,0,-1,0,247,247,"C-340","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0340-03",3,"Sólo por tu vista anhelo,\nPrenda querida del alma,\nY como en mi amor no hay calma,\nEs incesante el desvelo.\nSin tí, no tengo consuelo\nQue minore mi aflicción,\nTodos sin tu vista son,\nMotivos de gran quebranto.\nY así, ojos, seguid el llanto,\nLlorad sin intermisión.",3,1,0,34,"OJOS RASGAD LA CORRIENTE",18,10,"o",31,0,-1,0,247,247,"C-340","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0340-04",3,"Quien no goza el bien que adora,\n¡Qué gusto puede tener!\n¡Ni cómo puede caber\nEn quien siempre gime y llora!\nDe asiento la pena, mora\nEn mi triste corazón,\nY supuesto que ocasión\nNo logro de estar contigo,\n¡Ojos, sabed que yo os digo:\nLlorad que tenéis razón.",3,1,0,34,"OJOS RASGAD LA CORRIENTE",18,10,"o",31,0,-1,0,247,247,"C-340","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0340-05",3,"No quiero divertimientos\nQue entretengan mis pesares,\nHáganse mis ojos mares,\nAumentaré el sentimiento.\n¡Afuera, afuera contento!\nSea el dolor permanente,\nY pues, hallo solamente,\nLa pena dentro mi pecho,\nEl gusto fuera mal hecho,\nPues está tu dueño ausente.",3,1,0,34,"OJOS RASGAD LA CORRIENTE",18,10,"ee",15,0,-1,0,247,247,"C-340","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0341-01",3,"Por medio de este papel,\nQuiero mis quejas enviarte,\nPero más quisiera hablarte\nPara decirte más bien.",3,1,0,34,"POR MEDIO DE ESTE PAPEL",5,4,"e",-1,0,-1,0,247,247,"C-341","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0341-03",3,"Con la espada del rigor\nCmpuñada en vuestra mano,\nüomo verdugo tirano,\nPagaste a mi corazón.\nQué penetrante dolor\nPara un corazón amante!\nQue por ser fino y constante,\nTan mal pago he recibido,\nPero con tiernos suspiros,\nQuiero mis quejas enviarte.",3,1,0,34,"POR MEDIO DE ESTE PAPEL",18,10,"ae",-1,0,-1,0,248,248,"C-341","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0341-04",3,"Por sobre escrito te mando\nUna pintura sangrienta,\nDonde una flecha violenta\nParte a parte está pasando,\nCon- qué impiedad penetrando,\nA quien de tanto llorarte,\nNo se cansó de esperarte,\nNi pudo echarte en olvido,\nPor fin, siquiera te escribo,\nAunque más quisiero, hablarte.",3,1,0,34,"POR MEDIO DE ESTE PAPEL",18,10,"ae",8,0,-1,0,248,248,"C-341","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0341-05",3,"Por fin, dejo tu mal pago,\nEn el rincón del olvido,\nMi amor se ha comprometido\nEn no olvidarse lo amado,\nNo porque te hayas trocado,\nMe hallo de otro parecer.\nTu servidor he de ser,\nEntre mi melancolía,\n¡Pudiera verte algún día!\nPara decirte más bien.",3,1,0,34,"POR MEDIO DE ESTE PAPEL",18,10,"e",-1,0,-1,0,248,248,"C-341","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0342-01",3,"¡Qué ausencia tan cruel, será\nLa que tendré que sentir,\nAl verme lejos de tí,\nCuando no te pueda hablar!",3,1,0,34,"QUE AUSENCIA TAN CRUEL SERA",5,4,"a",-1,0,-1,0,248,248,"C-342","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0342-02",3,"Triste me pongo a pensar\nLo que tendré que sufrir,\nY que tengo que partir\nPor obligación forzosa\nPensando en el porvenir.",3,1,0,34,"QUE AUSENCIA TAN CRUEL SERA",7,5,"i",157,0,-1,0,248,248,"C-342","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0342-03",3,"Yo, que tendré que ausentarme,\nY que dejaré de verte,\nAsí lo quiere mi suerte,\nMás no puedo consolarme.\nSé que es triste el separarme\nDe quien adoro constante,\nPorque no tendré un instante,\nDÉ placer y de alegría,\nAmargos serán los días\nAl verme de tí distante.",3,1,0,34,"QUE AUSENCIA TAN CRUEL SERA",18,10,"ae",47,0,-1,0,248,248,"C-342","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0342-04",3,"En esta separación\nNunca me veré contento,\nMucho será el sufrimiento,\nDe mi triste corazón.\nNo sé si este mi dolor\nPodrá tener resistencia,\nPara sufrir la inclemencia,\nDe mi amargo padecer,\nCuando no te puedo ver,\nDueña mía, en mi presencia.",3,1,0,34,"QUE AUSENCIA TAN CRUEL SERA",18,10,"ea",46,0,-1,0,248,248,"C-342","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0342-05",3,"En fin, con amarga pena\nLlega el momento fatal,\nQue me tengo que ausentar,\nPara muy lejanas tierras.\nEn mi corazón se encierra,\nEl dolor el más profundo,\nPero mi amor sin segundo,\nNo te olvidará un instante,\nY siempre fiel y constante,\nT' hi de amar en este mundo.",3,1,0,34,"QUE AUSENCIA TAN CRUEL SERA",18,10,"uo",179,0,-1,0,248,248,"C-342","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0343-01",3,"¡Qué bonito me cantaba\nLa palomita en su nido,\nAbriendo el pico y las alas,\nComo si hablara conmigo!",3,1,0,34,"QUE BONITO ME CANTABA",0,4,"io",-1,0,-1,0,248,248,"C-343","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0343-02",3,"En la jaula de mi pecho,\nDonde cautiva se hallaba,\nCon halagüeños acentos,\n¡Qué bonito me cantaba!",3,1,0,34,"QUE BONITO ME CANTABA",0,4,"aa",28,0,-1,0,248,249,"C-343","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0343-03",3,"Sin calmar en su canción,\nPor no verme sumergido,\nEstaba fiel y constante\nLa palomita en su nido.",3,1,0,34,"QUE BONITO ME CANTABA",0,4,"io",101,0,-1,0,249,249,"C-343","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0343-04",3,"Para elevarme a su trono,\nMe formó tales escalas,\nY gustosa me llamaba,\nAbriendo el pico y las alas.",3,1,0,34,"QUE BONITO ME CANTABA",0,4,"aa",-1,0,-1,0,249,249,"C-343","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0343-05",3,"Más, ¡ay, triste, desgraciado,\nPues ausente de ella vivo!\nY ahora, entusiasmada canta,\nComo si hablara conmigo.",3,1,0,34,"QUE BONITO ME CANTABA",3,4,"io",-1,0,-1,0,249,249,"C-343","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0344-01",3,"Recibirá de mi mano\nMi dueña muy apreciada,\nEsta carta mal trazada,\nQue me dicta mi fortuna,\nLa que sin prédida alguna,\nMi corazón te la envía,\nDeseando que llegue el día\nQue en tus brazos me he de ver,\nLleno de gusto y placer,\nRegalada, prenda mía.",3,1,0,34,"",18,10,"ia",0,0,-1,0,249,249,"C-344","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0344-02",3,"Yo deseo, dueña amada,\nQue te halles sin novedad,\nCon toda felicidad,\nY de Dios acompañada,\nQue tu dicha sea colmada\nSin que un momento desmaye,\nQue las penas de este valle\nNo sufras, cielo adorado,\nY cuando llegue a tu lado,\nBuena, sin novedad te halle.",3,1,0,34,"",18,10,"ae",371,0,-1,0,249,249,"C-344","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0344-03",3,"¡Qué triste lloro mis males\nDe mi lastimado pecho!\nLejos del bien que idolatro,\nEn llanto vivo deshecho.",3,1,0,34,"",0,4,"eo",60,0,-1,0,249,249,"C-344","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0344-04",3,"Ya yo no conozco el gusto,\nPorque todos son pesares,\nCon la ausencia de mi bien,\nQué triste lloro mis males.",3,1,0,34,"",0,4,"ae",-1,0,-1,0,249,249,"C-344","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0344-05",3,"Sin tener a quién quejarme,\nEntre congojas deshecho,\nLamento la desventura,\nDe mi lastimado pecho.",3,1,0,34,"",0,4,"eo",60,0,-1,0,249,249,"C-344","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0344-06",3,"Con ausencia tan penosa,\nSoy de la muerte el retrato;\n¿Cómo es posible vivir\nLejos del bien que idolatro?",3,1,0,34,"",0,4,"ao",-1,0,-1,0,249,249,"C-344","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0344-07",3,"Tomo por alivio el sueño,\nTe busco en mi triste lecho,\nSabiendo que estás ausente,\nEn llanto vivo deshecho.",3,1,0,34,"",0,4,"eo",60,0,-1,0,249,249,"C-344","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0345-01",3,"Regalada, prenda mía,\nBuena, sin novedad te halle,\nCon la salud que deseo,\nPido al cielo que te guarde.",3,1,0,34,"REGALADA PRENDA MÍA",0,4,"ae",-1,0,-1,0,249,249,"C-345","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0345-03",3,"Ahí te mando el corazón,\nEn seña de voluntad,\nPagando con igualdad,\nLas finezas de tu amor,\nEn mi pecho guardador,\nDel mucho amor que poseo,\nPues cuando yo no te veo,\nTodo se me va en llorar,\nAl creer que no te he de hallar\nCon la salud que seo.",3,1,0,34,"REGALADA PRENDA MÍA",18,10,"eo",66,0,-1,0,249,249,"C-345","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0345-04",3,"Ya que mi desgracia ha sido\nQue nos hallemos distantes,\nTe suplico como amante,\nQue no me eches en olvido,\nPorque tuyo siempre he sido,\nY en mi pecho un fogón arde,\nA mí no hay qué me acobarde,\nNingún rigor ni tormento,\nY amante a cada momento,\nPido al cielo que te guarde.",3,1,0,34,"REGALADA PRENDA MÍA",18,10,"ae",344,0,-1,0,249,249,"C-345","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0346-01",3,"Señora, de mi alto aprecio,\nSea en sus manos esta letra,\nGoze Vd. por muchos años\nDe una salud muy completa.",3,1,0,34,"SEÑORA DE MI ALTO APRECIO",0,4,"ea",-1,0,-1,0,249,249,"C-346","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0347-02",3,"Cuando veas esta sombrita,\nImagen fiel de tu amante,\nElla te hablará constante,\nDe aquel que fué tu vidita.",3,1,0,34,"SI ALGUNA VEZ VIDA MÍA",11,4,"ia",50,0,-1,0,250,250,"C-347","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0347-03",3,"Te recordará un lugar,\nEn una tarde sombría,\nCuando lágrimas vertía,\nViéndote también llorar.",3,1,0,34,"SI ALGUNA VEZ VIDA MÍA",11,4,"a",21,0,-1,0,250,250,"C-347","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0347-04",3,"Entre tus brazos, allí\nMis lágrimas derramaba,\nY tú conmigo llorabas\nAl verme llorar por tí.",3,1,0,34,"SI ALGUNA VEZ VIDA MÍA",5,4,"i",23,0,-1,0,250,250,"C-347","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0347-05",3,"Testigo de mi dolor\nEs un grupo de arbolitos,\nDonde lloramos juntitos,\nNuestra pena, nuestro amor.",3,1,0,34,"SI ALGUNA VEZ VIDA MÍA",11,4,"o",72,0,-1,0,250,250,"C-347","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0347-06",3,"Allí iré a llorar mi suerte,\nEn viéndome desgraciado,\nAllí iré por tí olvidado,\nA Dios, pidiendo la muerte.",3,1,0,34,"SI ALGUNA VEZ VIDA MÍA",11,4,"ee",134,0,-1,0,250,250,"C-347","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0347-07",3,"Por si acaban nuestras glorias,\nCausa de tu pecho ingrato,\nTe dejaré mi retrato,\nComo pequeña memoria.",3,1,0,34,"SI ALGUNA VEZ VIDA MÍA",5,4,"oa",-1,0,-1,0,250,250,"C-347","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0348-01",3,"Soy amante desgraciado,\nNo tengo ningún consuelo,\nQue mitigue mi dolor,\nY vivo clamando al cielo.",3,1,0,34,"SOY AMANTE DESGRACIADO",0,4,"eo",10,0,-1,0,250,250,"C-348","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0348-02",3,"Mi cerebro se entorpece\nCuando lejos pienso en tí,\n¿Qué puedo yo merecer?\n¡Ay, infeliz, ay, de mí!",3,1,0,34,"SOY AMANTE DESGRACIADO",0,4,"i",23,0,-1,0,250,250,"C-348","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0348-03",3,"Jamás encuentro consuelo,\nSufriendo de noche y día,\n¿Qué gusto puedo tener\nLejos de tí, vida mía?",3,1,0,34,"SOY AMANTE DESGRACIADO",0,4,"ia",0,0,-1,0,250,250,"C-348","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0348-04",3,"Nunca alejarme podré\nDe tu lado, prenda amada,\nViviré en tu compañía,\nSi hallo en tu pecho posada.",3,1,0,34,"SOY AMANTE DESGRACIADO",0,4,"aa",49,0,-1,0,250,250,"C-348","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0349-01",3,"Tan ardiente es la pasión\nQue se ha grabado en mi alma,\nQue siento perder la calma,\nEn mi triste corazón.\nLa culpa tiene el amor,\nQue en mi pecho se ha grabado,\nQue si no soy desairado,\nCuando mi pasión es tanta,\nDe rodillas a tus plantas\nMe tendrás enamorado.",3,1,0,34,"TAN ARDIENTE ES LA PASIÓN",18,10,"ao",14,0,-1,0,251,251,"C-349","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0349-02",3,"No me llames lisonjero\nAl pintarte mi pasión,\nPorque es fiel mi corazón,\nY mi amor es verdadero.\nDe veras te amo y te quiero,\nTe lo juro con lealtad,\nY si esa tu voluntad\nCorrespondiese a la mía,\nA tu lado viviría,\nLleno de felicidad.",3,1,0,34,"TAN ARDIENTE ES LA PASIÓN",18,10,"a",16,0,-1,0,251,251,"C-349","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0349-03",3,"No me trates de atrevido,\nAl recibir la presente,\nSi un cariño tan ardiente,\nOcultarte no he podido,\nSi por un tiempo he vivido,\nSilenciando mi pasión,\nTemeroso el corazón,\nAl recibir un desaire,\nPorque siempre fué cobarde\nEl más verdadero amor.",3,1,0,34,"TAN ARDIENTE ES LA PASIÓN",18,10,"o",-1,0,-1,0,251,251,"C-349","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0349-04",3,"Pero al fin, hoy es forzoso,\nMi cariño declararte,\nY con ansia suplicarte,\nQuieras hacerme dichoso.\nPorque eres el astro hermoso,\nQue mi ser recuerda siempre,\nY si eres condescendiente,\nA mi cariño profundo,\nComo nadie en este mundo,\nTe amaré constantemente.",3,1,0,34,"TAN ARDIENTE ES LA PASIÓN",18,10,"ee",15,0,-1,0,251,251,"C-349","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0350-01",3,"¡Tan lejos que estoy de tí!\nMi bien, ¿cuándo te veré?\nPero no te he de olvidar,\nAunque más lejos esté.",3,1,0,34,"TAN LEJOS QUE ESTOY DE TI",0,4,"e",77,0,-1,0,251,251,"C-350","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0350-02",3,"Hasta el fin he de ser fiel;\nSi a tu presencia no voy,\nEs porque todavía estoy\nMetido en este cuartel,\n¡Qué separación tan cruel!\n¡Ay, infeliz, ay de mí!\nDesde que te conocí\nTodo es padecimiento,\n¿Cómo viviré contento,\nTan lejos que estoy de tí?",3,1,0,34,"TAN LEJOS QUE ESTOY DE TI",18,10,"i",23,0,-1,0,251,251,"C-350","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0350-03",3,"No hemos de desconocernos,\nAunque sea larga mi ausencia,\nNo habiendo en ti diferencia,\nAunque tardemos en vernos.\nAún cuando sean muy tiernos,\nLos ayes que yo daré,\nCuanto más suspiraré,\nPor verte una vez siquiera,\nSolamente que muriera,\nMi bien, ya no te veré.",3,1,0,34,"TAN LEJOS QUE ESTOY DE TI",18,10,"e",77,0,-1,0,251,251,"C-350","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0350-04",3,"Yo te dirijo esta letra,\nYa que vernos no podemos,\nAlgún día gozaremos,\nDe una libertad completa.\nTú sabes qué me sujeta\nEn este triste lugar,\nCuando yo te quiero hablar,\nLa libertad no consigo,\nPor esto no estoy contigo,\nPero no te he de olvidar.",3,1,0,34,"TAN LEJOS QUE ESTOY DE TI",18,10,"a",21,0,-1,0,251,251,"C-350","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0353-03",3,"Luego que con ella hablés,\nPapel, te puedes venir,\nY dile que he de vivir,\nCon ella en el pensamiento,\nObsérvale el movimiento,\nY lo que esté conversando,\nVé si te está despreciando\nY te muestra buenos modos,\nPara que me cuentes todo,\nVolvete, papel volando.",3,1,0,34,"VUELA PAPEL VENTUROSO",18,10,"ao",33,0,-1,0,253,253,"C-353","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0353-06",3,"Y mira si te rescibe\ncon desdén o afición,\nY mira bien si concibe\nel daño de quien t'escriue\namorossa compassion:\nmira si huye de ti,\nsi te vee, si te oluida;\nmira si haze de si,\ndespués qu' de ella ártí\nmudanca con la partida.",3,1,0,34,"VUELA PAPEL VENTUROSO",18,10,"ia",37,0,-1,0,254,254,"C-353","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0353-07",3,"Lleno de melancolía,\nTrayendo en tu compañía\nUna gran pena terrible,\nPara mí será sensible,\nVer mi suerte en tal estado,\nDiré que soy desgraciado,\nPapel, si no te recibe.",3,1,0,34,"VUELA PAPEL VENTUROSO",4,7,"ie",-1,0,-1,0,254,254,"C-353","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0353-08",3,"Mira si tiene plazer\nmira sus tristes enojos,\ny mira por conoscer\nsu querer y no querer\nen lo que miran sus ojos:\ny mira bien en quexar\nlo que de mi daño sea;\ny mira sepas contar\nlo que podistes mirar\ncuando con ella me vea.",3,1,0,34,"VUELA PAPEL VENTUROSO",18,10,"ea",54,0,-1,0,254,254,"C-353","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0353-09",3,"Al tiempo doy por testigo,\nAunque no soy, puedo ser,\nVuelvan mis penas en glorias\nY mi disgusto en placer.",3,1,0,35,"AL TIEMPO DOV D™> TPCTICO",0,4,"e",20,0,-1,0,256,256,"C-353","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0353-10",3,"La planta inter no se seca,\nAunque sin hojas se vé,\nVuelve a ser lo que antes fué,\nSi el hielo no la penetra.\nAunque su verdor la trusca,\nDándole nuevo cultivo,\nFlorece y crece a lo vivo,\nNacen sus frutos por sí,\nEsto se ha de ver en mí\nAl tiempo doy por testigo.",3,1,0,35,"AL TIEMPO DOV D™> TPCTICO",18,10,"io",-1,0,-1,0,256,256,"C-353","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0353-11",3,"El jardín más primoroso,\nSuele perder sus colores,\nEn cortándole las flores,\nSe queda triste y penoso,\nAsí el tiempo venturoso,\nHace que vuelva a su ser,\nVolviéndole a recoger\nFlores que de antes, perdió,\nAsí me contemplo yo,\nAunque no soy, puedo ser.",3,1,0,35,"AL TIEMPO DOV D™> TPCTICO",18,10,"e",20,0,-1,0,256,256,"C-353","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0353-12",3,"El mar, baja mengua y crece,\nLos astros del cielo mudan,\n¿Por qué, pues, poner en duda\nDe lo que el tiempo me ofrece?\nLo que sí, mi alma padece\nPor sus dichas y victorias,\nSiempre traigo a la memoria\nQue el mundo da muchas vueltas.\nPuede ser que en una de éstas,\nVuelvan mis penas en gloria.",3,1,0,35,"AL TIEMPO DOV D™> TPCTICO",18,10,"oa",126,0,-1,0,256,256,"C-353","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0353-13",3,"El más alto pensamiento\nDe su esfera bajará,\nEl mío se subirá,\nGrada, grada, hasta su asiento.\nPues así yo lo presiento,\nY es caso que se ha de ver,\nCesará mi padecer,\nVolverá la dicha mía,\nMi tormento en alegría,\nY mi disgusto en placer.",3,1,0,35,"AL TIEMPO DOV D™> TPCTICO",18,10,"e",20,0,-1,0,256,256,"C-353","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0354-a-01",3,"Al tiempo doy por testigo,\nAunque no soy, puedo ser,\nVuelvan mis penas en gloria,\nY mi tormento en placer.",3,1,0,35,"AL TIEMPO DOY POR TESTIGO",0,4,"e",20,0,-1,0,256,256,"C-354-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0354-a-02",3,"La rama inter no se seca,\nAunque sin hojas se vé,\nPuede volver a su ser,\nSi el hielo no le penetra;\nInter su verdor no seca,\nProduce más a lo vivo,\nDándole nuevo cultivo,\nFlorece y da fruto en sí,\nEsto se ha de ver en mí,\nAl tiempo doy por testigo.",3,1,0,35,"AL TIEMPO DOY POR TESTIGO",18,10,"io",-1,0,-1,0,256,256,"C-354-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0354-a-03",3,"El jardín más primoroso\nLlega a perder su color,\nQue secándose la flor,\nSe queda triste y penoso.\nMás, el tiempo generoso,\nLo hace que vuelva a su ser,\nHaciéndole recoger\nLas flores que antes perdió.\nA sí me contemplo yo,\nAunque no soy, puedo ser.",3,1,0,35,"AL TIEMPO DOY POR TESTIGO",18,10,"e",20,0,-1,0,256,256,"C-354-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0354-a-04",3,"El mar crece, mengua y baja,\nLos astros del cielo mudan,\nLuego ¿por qué tienes duda\nDe lo que el tiempo te ofrece?\nTambién el mar se enfurece,\nDe ver su gloria notoria,\nY mantengo en la memoria,\nQue el mundo da muchas vueltas,\nPueda ser que en una de estas,\nVuelvan mis penas en gloria.",3,1,0,35,"AL TIEMPO DOY POR TESTIGO",18,10,"oa",126,0,-1,0,256,256,"C-354-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0355-01",3,"A mí me llevó un amigo\nA casa de la que amaba,\nYo, como amigo traidor,\nMe le quedé con su dama.",3,1,0,35,"A MI ME LLEVO UN AMIGO",0,4,"aa",-1,0,-1,0,256,256,"C-355","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0355-02",3,"Primero me preguntó\nSi yo era amigo legal,\nLe dije: —soy tan cabal,\nQue en nada faltaré yo;\nPues él de mí se confió,\nMarchó a la casa conmigo;\nYo mismo le dí el castigo,\nLo hice separar violento,\nPensando vivir contento,\nA mí me llevó un amigo.",3,1,0,35,"A MI ME LLEVO UN AMIGO",18,10,"io",106,0,-1,0,257,257,"C-355","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0355-03",3,"Ya no hay amigo constante,\nPor mí saco el deshechado,\nPorque lo puse trocado\nA mi amigo en un instante,\nLo hice que no fuera amante\nDe la prenda que adoraba,\nPues que tanto me encargaba,\nQue en la suya no me aciegue,\nHasta lo hice que no llegue,\nA casa de la que amaba.",3,1,0,35,"A MI ME LLEVO UN AMIGO",18,10,"aa",28,0,-1,0,257,257,"C-355","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0355-04",3,"Ya no hay que poner esmero,\nEs un amigo con fama,\nQué le ha de quitar la dama\nEse amigo traicionero.\nNo ví que era compañero\nPara fingirle traición,\nY en la primera ocasión,\nAproveché su descuido,\nLe soplé su bien querido,\nYo, como amigo traidor.",3,1,0,35,"A MI ME LLEVO UN AMIGO",18,10,"o",-1,0,-1,0,257,257,"C-355","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0355-05",3,"Empezó a tener recelos,\nY la culpaba conmigo,\nY creyéndose ofendido,\nDieron principio los celos.\nYo calmé su desconsuelo,\nLo hice volver a la calma,\nY estando tranquila su alma,\nPor pruebas que yo le dí,\nCuando engañado lo ví,\nMe le quedé con su dama.",3,1,0,35,"A MI ME LLEVO UN AMIGO",18,10,"aa",-1,0,-1,0,257,257,"C-355","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0356-01",3,"¡Amor, falso y desigual,\nQue entre el placer y la pena\nTodos sufren tu cadena!\n¡Amor, veneno mortal!",3,1,0,35,"AMOR, FALSO Y DESIGUAL",11,4,"a",1,0,-1,0,257,257,"C-356","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0356-02",3,"Amor, es sueño mental\nY es frenesí y es locura,\nY su estrago tanto apura,\nCuando más se cura el mal.",3,1,0,35,"AMOR, FALSO Y DESIGUAL",3,4,"a",1,0,-1,0,257,257,"C-356","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0356-03",3,"Amor, si a unos favorece,\nA otros vuelve desgraciado;\nEs un mal tan estimado,\nQue aunque mata se apetece.",3,1,0,35,"AMOR, FALSO Y DESIGUAL",11,4,"ee",64,0,-1,0,257,257,"C-356","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0356-04",3,"Amor, sólo muerte ofrece,\nY de su hacer homicida,\nAl pensar curar su herida,\nTanto más su herida crece.",3,1,0,35,"AMOR, FALSO Y DESIGUAL",11,4,"ee",64,0,-1,0,257,257,"C-356","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0357-01",3,"Antes era muy querido,\nAntes era prenda amada,\nHoy como me ven sin nada,\nYa no soy tan distinguido.\nAhora que me ven caído,\nYa me llenan de bajeza,\nYa no hay amor ni firmeza,\nYa no hay cariño ni halago,\nPara verse despreciado,\nNo hay como la pobreza.",3,1,0,35,"ANTES ERA MUY QUERIDO",18,10,"ea",108,0,-1,0,257,257,"C-357","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0357-02",3,"Antes de encontrarme así,\nAmigos y camaradas,\nMe guardaban las espaldas,\nY hoy todos huyen de mí,\nJusto es de que hagan así,\nPues notan mi mala suerte,\nMás bien quisiera la muerte,\nA sufrir tanto desdén,\nHoy nadie me quiere el bien\nPorque en pobreza me advierten.",3,1,0,35,"ANTES ERA MUY QUERIDO",18,10,"ee",-1,0,-1,0,257,257,"C-357","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0357-03",3,"Pueden llegar casos tales\nQue se acaben mis tormentos,\nAsí ha de llegar el tiempo,\nQue valga el que menos vale,\nMis amigos y parciales,\nSon distinguidos amantes,\nEstoy viendo cada instante,\nQue mi presencia es veneno,\nTodos me miran en menos,\nSólo yo soy el constante.",3,1,0,35,"ANTES ERA MUY QUERIDO",18,10,"ae",47,0,-1,0,257,257,"C-357","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0358-01",3,"¡A qué tiempo hemos llegado,\nDe tanta calamidad,\nGuerra sin necesidad\nEs lo que nos ha quedado!",3,1,0,35,"A QUE TIEMPO HEMOS LLEGADO",11,4,"ao",14,0,-1,0,258,258,"C-358","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0358-02",3,"Los pueblos en desunión\nUnos con otros están,\nY a pasos contados van,\nBuscando su desunión.\nLos ínfieles, la ocasión\nDe hacer el mal han buscado,\nEllos han muerto, han robado,\nNosotros tan afligidos,\nDecimos despavoridos:\n¡A qué tiempo hemos llegado!",3,1,0,35,"A QUE TIEMPO HEMOS LLEGADO",18,10,"ao",14,0,-1,0,258,258,"C-358","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0358-03",3,"Ya no hay lealtad en el amigo,\nYa no hay hijo para el padre,\nNi se respeta a la madre,\nPues con razones lo digo,\nY todo el mundo es testigo,\nDe que digo la verdad.\nYa no se encuentra lealtad,\nY ni en el pensamiento bueno,\nPorque el país está lleno,\nDe tanta calamidad.",3,1,0,35,"A QUE TIEMPO HEMOS LLEGADO",18,10,"a",16,0,-1,0,258,258,"C-358","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0358-04",3,"Ya falta la religión,\nY mucho más si quisieres,\nLos maridos, las mujeres,\nEstán en revolución.\n¡Qué pena, qué confusión\nEl ver que en tanta crueldad,\nSe pagan de la maldad,\nY que nos vamos matando!\nPor lo que estamos pasando\nGuerras sin necesidad.",3,1,0,35,"A QUE TIEMPO HEMOS LLEGADO",18,10,"a",16,0,-1,0,258,258,"C-358","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0358-05",3,"Las naciones han venido\nComo dicen, a ilustrar,\nY a mi modo de pensar,\nNos dan golpe de sentido,\nEllos han enriquecido\nCon lo mucho que han robado,\nEn esqueleto han dejado\nA todo este continente,\nSólo un orgullo indecente\nEs lo que nos ha quedado.",3,1,0,35,"A QUE TIEMPO HEMOS LLEGADO",18,10,"ao",14,0,-1,0,258,258,"C-358","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0360-01",3,"¡Bien haiga lo desparejo\nDel camino que yo he andado!\nLa culpa la tuve yo,\nPor no haberlo emparejado.",3,1,0,35,"BIEN HAIGA LO DESPAREJO",0,4,"ao",14,0,-1,0,258,258,"C-360","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0360-03",3,"Andará por serranías,\nPor montes y cordilleras,\nSin temer ninguna fiera,\nPor terrible y por temida,\nAsí pasará sus días,\nEl infeliz desgraciado;\nPasará desesperado\nComo un fingido Caín,\nDirá: ¿cuándo tendrá fin\nEl camino que yo he andado?",3,1,0,35,"BIEN HAIGA LO DESPAREJO",18,10,"ao",14,0,-1,0,259,259,"C-360","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0361-02",3,"Los cazadores de amantes,\nTambién los enfurecidos,\nSe valen de algún fingido,\nPara lograr bien su plan.\nNo es tan fácil acertar\nSi está el ave en falsa rama.",3,1,0,35,"CALANDRIA, ESTAS DIVERTIDA",9,6,"aa",-1,0,-1,0,259,259,"C-361","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0361-04",3,"El que fuera cazador\nY quiera lograr su tiro,\nPonga los puntos al ave,\nCuando esté echada en su nido.",3,1,0,35,"CALANDRIA, ESTAS DIVERTIDA",0,4,"io",-1,0,-1,0,259,259,"C-361","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0362-01",3,"Con mucha curiosidad\nA un sabio le pregunté,\nQue me dijera el por qué,\nEn la mujer no hay lealtad.\nMe respondió: con verdad,\nLa mujer es inconstante,\nY mal se funda un amante,\nQue de la mujer se fía,\nPorque de la noche al día,\nLo ha de dejar vacilante.",3,1,0,35,"CON MUCHA CURIOSIDAD",18,10,"ae",47,0,-1,0,259,259,"C-362","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0362-02",3,"La mujer es veleidosa,\nNo tiene sinceridad,\nElla le quita alevosa,\nAl hombre la libertad.\nY cuando en la adversidad\nLo llega a ver sumergido,\nMás pronto lo echa en olvido,\nCon la ingratitud más cruel,\nPorque la mujer no es fiel,\nViéndolo al hombre abatido.",3,1,0,35,"CON MUCHA CURIOSIDAD",18,10,"io",101,0,-1,0,259,259,"C-362","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0362-a-01",3,"A un sabio le pregunté,\nCon mucha curiosidad,\nQue me dijera el por qué,\nEn la mujer no hay lealtad.\nEl sabio me contestó:\n—La mujer es veleidosa,\nPorque le quita, alevosa,",3,1,0,35,"A UN SABIO LE PREGUNTE",4,7,"oa",63,0,-1,0,259,259,"C-362-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0363-02",3,"casarse nada cuesta,\nTrabajo es para vivir,\nA pesar de éste existir,\nNo sé qué locura es esta,\nPero si algo les molesta\nNo se miren con desdén,\nEchenlé la culpa a quién\nQué causa del cautiverio,\nhan de cargar el madero,\nCon paciencia han hecho bien.",3,1,0,35,"CON PACIENCIA HAN HECHO BIEN",18,10,"e",242,0,-1,0,260,260,"C-363","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0363-03",3,"Si quieres ganar el cielo,\nPreciso es que seas fiel,\nQue no seas mala mujer\nque aborrezcas los celos\nQué pueden ser tus desvelos,\ne tu llanto más atroz,\nAsí un castigo veloz,\nEspera de tu marido,\nQue seas humilde te pido,\nSi quieres servir a Dios.",3,1,0,35,"CON PACIENCIA HAN HECHO BIEN",18,10,"o",87,0,-1,0,260,260,"C-363","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0363-04",3,"Ya que el tiempo había llegado,\nQue se unan las voluntades,\nPara que vivan iguales,\nComo que ya se han juntado.\nCosas que Dios ha formado,\nNo se pueden deshacer,\nVenga el mal o venga el bien,\nEl casamiento y mortaja\nComo que del cielo baja,\nNo se traten con desdén.",3,1,0,35,"CON PACIENCIA HAN HECHO BIEN",18,10,"e",242,0,-1,0,260,260,"C-363","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0363-05",3,"¡Mirá, marido leal!\nSí te aqueja alguna cosa,\nNo maltrates a tu esposa,\nPor otro bien temporal.\nMirá, que si un animal,\nDe aquellos que formó Dios,\nY falta uno de los dos,\nLlama por el compañero.\nAsí, cargando el madero,\nVivan unidos los dos.",3,1,0,35,"CON PACIENCIA HAN HECHO BIEN",18,10,"o",-1,0,-1,0,260,260,"C-363","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0364-01",3,"Crece el hombre malamente,\nArrastrando la cadena.\nPor eso no causa pena,\nVer morir a un inocente.",3,1,0,35,"CRECE EL HOMBRE MALAMENTE",11,4,"ee",15,0,-1,0,260,260,"C-364","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0364-03",3,"Crece y agatas le dan,\nExtraños padres y amigos,\nSi de frío pide abrigo,\nNadie ofrece su gabán;\nY si de hambre pide pan,\nDel pobre nade se apena,\nHasta que su alma se llena,\nDe clamar en vano al cielo,\nRoba y mata y alza el vuelo,\nArrastrando la cadena.",3,1,0,35,"CRECE EL HOMBRE MALAMENTE",18,10,"ea",59,0,-1,0,260,260,"C-364","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0364-04",3,"Pasa en la cárcel sumido,\nEn hediondo calabozo,\nDentrando cuando era mozo,\nY saliendo envejecido.\nSólo habiendo conseguido,\nUn reuma o una gangrena.",3,1,0,35,"CRECE EL HOMBRE MALAMENTE",9,6,"ea",-1,0,-1,0,260,260,"C-364","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0364-06",3,"Bienvenido sea el ser,\nQue sólo deja en el mundo,\nLa existencia de un segundo,\nCuando le toca nacer.\nIgnorando el padecer,\nLímpida y pura la frente,\nComo cristal transparente,\nIrá derecho a la Gloria.\nNo es, pues, una triste historia,\nVer morir a un inocente.",3,1,0,35,"CRECE EL HOMBRE MALAMENTE",18,10,"ee",15,0,-1,0,260,261,"C-364","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0364-07",3,"¡Viva el angelito, pues!\nQue con sus brillantes alas,\nHa subido las escalas,\nDel palacio del Gran Juez.\nIrá donde no hay doblez\nNi dolores, ni mentiras,\nDonde nunca se suspira,\nPorque la pena no existe,\nPor eso no es canto triste\nEl que un angelito inspira.",3,1,0,35,"CRECE EL HOMBRE MALAMENTE",18,10,"ia",372,0,-1,0,261,261,"C-364","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0365-01",3,"Después de felicitarte\nPor la próxima ventura,\nPor esa dicha futura,\nQue tú esperas con casarte,\nUn consejo voy a darte,\nSin contrariar tus afectos,\nPorque no tengo derecho\nDe oponerme a tu intención,\nSólo te pido atención,\nQue te merezco respeto.",3,1,0,35,"DESPUÉS DE FELICITARTE",18,10,"eo",-1,0,-1,0,261,261,"C-365","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0365-02",3,"Antes que seas esposa\nDebes de considerar,\nQue inocente vas a entrar,\nEn una senda escabrosa.\nIgnoras lo peligrosa\nQue la vida del casado,\nPorque es un lazo sagrado,\nQue jamás podrás romper,\nEsto debes precaver\nAntes de tomar estado.",3,1,0,35,"DESPUÉS DE FELICITARTE",18,10,"ao",14,0,-1,0,261,261,"C-365","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0365-03",3,"Tú ignoras que el camino\nQue has de seguir con tu esposo,\nEstá sembrado de abrojos,\nY no sabes tu destino.\nTú deberás de continuo\nMis consejos recordar,\nQue puede algún día llegar,\nA ser tu esposo variable,\nEntonces será ya tarde,\nSi quieres refleccionar.",3,1,0,35,"DESPUÉS DE FELICITARTE",18,10,"a",21,0,-1,0,261,261,"C-365","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0365-04",3,"Día habrá que te has de hallar\nRodiada de tus criaturas,\nY con lágrimas bien puras,\nMis consejos recordar.\nEntonces has de desear,\nEstar como hoy, solterita,\nGozando con tu mamita,\nDe un cariño incomparable,\nEntonces será ya tarde\nSi quieres considerar.",3,1,0,35,"DESPUÉS DE FELICITARTE",18,10,"a",21,0,-1,0,261,261,"C-365","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0366-01",3,"El amor es una planta\nQue nace del corazón,\nSi la riegan con desprecio,\nSe ha de secar, con razón.",3,1,0,35,"EL AMOR ES UNA PLANTA",0,4,"o",31,0,-1,0,261,261,"C-366","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0366-02",3,"Siempre el amor va creciendo\nSolamente con su ardor,\nCon las ansias y el fulgor,\nVa sus llamas esparciendo.\nSi de riego careciendo,\nSu crecer no se quebranta,\nPor si mismo se adelanta,\nY no deja de crecer,\nPor esto es de comprender\nQue el amor es una planta.",3,1,0,35,"EL AMOR ES UNA PLANTA",18,10,"aa",148,0,-1,0,261,261,"C-366","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0366-03",3,"Por mal que se halle regado,\nNo deja de ser frondoso,\nEl es siempre bondadoso,\nNingún tiempo lo ha secado.\nTodos los que se han helado\nLlevan su buena intención,\nDe volver su aparición,\nCon la pureza de un niño;\nBusca el riego en el cariño,\nQue nace del corazón.",3,1,0,35,"EL AMOR ES UNA PLANTA",18,10,"o",31,0,-1,0,261,261,"C-366","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0366-04",3,"A toda planta al ponerla,\nAunque fuese en buen terreno,\nHay que cuidarla a lo menos,\nSin descuidarse en regarla.\nCuando sea tiempo podarla,\nSon cariño y mucho aprecio,\nDándole el debido precio,\nPara aprovechar el fruto,\nNo dará ningún producto\nSi la riegas con desprecio.",3,1,0,35,"EL AMOR ES UNA PLANTA",18,10,"eo",276,0,-1,0,261,261,"C-366","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0367-05",3,"El viejo es de suerte baja,\nEn la primera ocasión\nUn muchachito maltón\nLe lleva doble ventaja,\nPorque el viejo ya rebaja,\nAunque de antojo se muera.\nPor el interés pudiera\nQue al viejo le hagan favor,\nPero respecto al amor,\nYa no hay mujer que lo quiera.",3,1,0,35,"EL HOMBRE QUE LLEGA A VIEJO",18,10,"ea",44,0,-1,0,262,262,"C-367","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0368-01",3,"El jardinero de amor\nPone una planta y se vá,\nOtro la riega y la goza,\n¿De cuál de los dos será?",3,1,0,35,"EL JARDINERO DE AMOR",0,4,"a",9,0,-1,0,262,262,"C-368","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0368-02",3,"Al tribunal de Cupido\nApeló con afición\nPara aliviar su aflicción,\nUn hortelano afligido,\nQue con ayes desmedidos,\nLamentaba su dolor.\nLe dice: planté una flor\nCon amores de mi pecho,\nY hoy alegan el derecho\nAl jardinero de amor.",3,1,0,35,"EL JARDINERO DE AMOR",18,10,"o",72,0,-1,0,262,262,"C-368","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0368-03",3,"Cupido como letrado,\nReparó en el demandante,\n—Algo tuvo de inconstante\nPero más de apasionado.\nContemplo que al desgraciado\nLa peor parte se le dá,\nPero bien empleado está\nPorque es razón conocida\nComo una cosa perdida,\nPone la planta y se vá.",3,1,0,35,"EL JARDINERO DE AMOR",18,10,"a",9,0,-1,0,262,262,"C-368","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0368-04",3,"¡Señor, dice el hortelano,\nNo porque otro la regó\nTiene el derecho que yo,\nQue la puse con mi mano,\nY por eso más temprano,",3,1,0,35,"EL JARDINERO DE AMOR",7,5,"ao",81,0,-1,0,262,262,"C-368","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0368-05",3,"De voluntad anheloso,\nSiempre anduve cuidadoso,\nEn mirar su producción,\nHoy no sé por que razón,\nOtro la riega y la goza!",3,1,0,35,"EL JARDINERO DE AMOR",7,5,"oa",-1,0,-1,0,263,263,"C-368","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0368-06",3,"El otro herido de celos\nLe alega la posesión,\nPorque le dió estimación,\nA costa de su desvelo.\nTriste se queja a los cielos,\nDiciendo: tiempo vendrá\nQue de mí se acordará\nCuando seca llegue a verse,\nY allí podrá conocerse\nDe cuál de los dos será.",3,1,0,35,"EL JARDINERO DE AMOR",18,10,"a",9,0,-1,0,263,263,"C-368","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0369-01",3,"El rico no piensa en Dios\nPor pensar en sus caudales,\nPierde los bienes eternos,\nPor los bienes temporales.",3,1,0,35,"EL RICO NO PIENSA EN DIOS",0,4,"ae",26,0,-1,0,263,263,"C-369","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0369-02",3,"Una insaciable codicia\nTiene el rico donde se halla,\nY no hay cosa que no vaya\nLlevada de la avaricia.\nEl es dado a la impudicia\nY de un vivir muy atroz,\nSólo piensa en su reloj,\nEn su superfluo progreso;\nOcupado siempre en eso\nEl rico no piensa en Dios.",3,1,0,35,"EL RICO NO PIENSA EN DIOS",18,10,"o",-1,0,-1,0,263,263,"C-369","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0369-03",3,"Para el rico no ha de haber\nNi cantidad que lo llene,\nPorque él en cuanto más tiene\nTanto más quiere tener.\nLo que quiere es poseer\nAunque sean bienes ajenos,\nEl se avanza los terrenos,\nQue junto al que compró están,\nPor vivir en este afán\nPierde los bienes eternos.",3,1,0,35,"EL RICO NO PIENSA EN DIOS",18,10,"eo",-1,0,-1,0,263,263,"C-369","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0369-04",3,"El rico pone su anhelo\nEn la plata y en el oro,\nQue es el único tesoro\nQue tiene para consuelo.\nAl bien lo busca en el suelo,\nComo hacen los animales,\nLos bienes espirituales,\nQue ante Dios suelen servir\nEl no los puede adquirir\nPor pensar en sus caudales.",3,1,0,35,"EL RICO NO PIENSA EN DIOS",18,10,"ae",26,0,-1,0,263,263,"C-369","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0369-05",3,"Tiene el rico y no equivoco\nEterna ambición febril,\nTiene ducados cien mil,\nTodavía se le hace poco,\nY se suelta como loco,\nCercando los ventanares,\nMezquinando los caudales,\nPoniendo en ellos la mira,\nPorque ese infeliz aspira\nPor los bienes temporales.",3,1,0,35,"EL RICO NO PIENSA EN DIOS",18,10,"ae",26,0,-1,0,263,263,"C-369","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0370-01",3,"Empezaré mi mudanza\nPara empezar a cantar,\nEstilo voy a mudar\nCuando mude mi esperanza;\nMuda el peso la balanza,\nMudan los sastres el paño,\nMudan los días del año,\nY siempre queda una duda.\nY al mirar que todo muda\nQue yo mude no es extraño.",3,1,0,35,"EMPEZARE MI MUDANZA",18,10,"ao",40,0,-1,0,263,263,"C-370","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0370-02",3,"También muda el escribano\nLapicera, tinta y pluma,\nMuda toda ave su pluma,\nMuda prendas el paisano,\nHerramienta el cirujano,\nMuda el pájaro su nido,\nMuda hogar el ermitaño,\nMudan los meses del año,\nY al mirar que todo muda\nQue yo mude no es extraño.",3,1,0,35,"EMPEZARE MI MUDANZA",18,10,"ao",40,0,-1,0,263,263,"C-370","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0370-03",3,"Muda también el poeta\nSus versos y melodías,\nMudan los meses sus días,\nMuda el médico receta,\nMuda bueyes la carreta,\nLas plantas en todo el año,\nMuda la mujer de engaño,\nMudan caballos los coches,\nMudan los días, las noches,\nQue yo mude no es extraño.",3,1,0,35,"EMPEZARE MI MUDANZA",18,10,"ao",40,0,-1,0,263,263,"C-370","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0370-04",3,"Mudan también los colores\nEn el transcurso del tiempo,\nMuda su corriente el viento,\nMudan de aromas las flores,\nMudan también sus amores,\nLa joven más cariñosa,\nMuda de genio la esposa,\nCuando pasan los dos años,\nal mirar que todo muda\nQue yo mude no es extraño.",3,1,0,35,"EMPEZARE MI MUDANZA",18,10,"ao",-1,0,-1,0,264,264,"C-370","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0372-01",3,"En la labranza de amor\nDonde se siembran afectos,\nNacen finezas, mas crecen,\nPor frutos los escarmientos.",3,1,0,35,"EN LA LABRANZA DE AMOR",0,4,"eo",-1,0,-1,0,264,264,"C-372","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0372-02",3,"Ahuyentad otras penas\nBarbechad el corazón,\nPara sembrar la semilla\nDe que nace la pasión.",3,1,0,35,"EN LA LABRANZA DE AMOR",0,4,"o",31,0,-1,0,264,264,"C-372","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0372-03",3,"En el medio de los surcos,\nHas de poner tus desvelos,\nDesyerbando tus cuidados,\nLa cizaña de los celos.",3,1,0,35,"EN LA LABRANZA DE AMOR",0,4,"eo",192,0,-1,0,264,264,"C-372","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0372-04",3,"¡Llorad ojos para el riego\nDe esa prolija labor,\nQue las lágrimas cultivan\nLos sembradíos de amor!",3,1,0,35,"EN LA LABRANZA DE AMOR",0,4,"o",72,0,-1,0,264,264,"C-372","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0372-05",3,"De la yerba de los celos\nLa raíz arrancar procura,\nAdvirtiendo que si crece,\nTu cordura es la locura.",3,1,0,35,"EN LA LABRANZA DE AMOR",0,4,"ua",17,0,-1,0,264,264,"C-372","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0373-01",3,"¡Infeliz de aquél que vive\nMendigando voluntades,\nEn puertas desconocidas,\nPisando ajenos umbrales!",3,1,0,35,"INFELIZ DE AQUEL QUE VIVE",0,4,"ae",-1,0,-1,0,264,264,"C-373","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0373-02",3,"Cuando en la vida se acaba\nEl placer y la bonanza,\nSe queda sin esperanza\nPor que no se espera nada.\nEn vez de agradar se enfada,\nSi algún favor se le pide\nSólo desprecios recibe\nDe quien vive prosperando,\nDe esta manera rogando\nInfeliz de aquel que vive.",3,1,0,35,"INFELIZ DE AQUEL QUE VIVE",18,10,"ie",190,0,-1,0,264,264,"C-373","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0373-03",3,"Ya no hay parientes ni hermanos,\nNi prójimos compasivos,\nAmigos y conocidos,\nSe le muestran inhumano.\nTodos le niegan la mano,\nViéndolo en adversidades,\nY le hacen iniquidades,\nCon las mayores bajezas,\nViéndose por su pobreza\nMendigando voluntades.",3,1,0,35,"INFELIZ DE AQUEL QUE VIVE",18,10,"ae",373,0,-1,0,264,264,"C-373","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0373-04",3,"Si el infeliz, por desgracia\nSe sale a países ajenos,\nTodos dicen no por bueno\nSe vé fuera de tu casa.\nEstos malos tragos pasa,\nPesándole su salida,\nAl considerar su vida,\nSólo le queda el decir:\n—Esto y más he de sufrir\nEn puertas desconocidas.",3,1,0,35,"INFELIZ DE AQUEL QUE VIVE",18,10,"ia",-1,0,-1,0,264,265,"C-373","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0373-05",3,"También si consideramos\nAl pobre en su padecer,\nVeremos que viene a ser\nEsclavo de muchos años.\nNadie vé que con sus manos\nSuple sus necesidades,\nRemediando así sus males,\nPor salvar su esclavitud,\nAcaba su juventud,\nPisando ajenos umbrales.",3,1,0,35,"INFELIZ DE AQUEL QUE VIVE",18,10,"ae",26,0,-1,0,265,265,"C-373","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0374-01",3,"La lengua es el peor cuchillo\nQue tiene la humanidad,\nPorque hiere sin peligro,\nSin compasión, ni piedad.",3,1,0,35,"LA LENGUA ES EL PEOR CUCHILLO",0,4,"a",16,0,-1,0,265,265,"C-374","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0374-02",3,"Quien creyera que la lengua\nInocente al parecer,\nPudiera herir tan cruel\nHaciendo una total mengua\nDel honor, virtud y hacienda,\nEn mayor grado su brillo,\nAllí con feroz martirio,\nDestroza cruel todo bien,\nPor esto ustedes lo ven,\nLa lengua es el peor cuchillo.",3,1,0,35,"LA LENGUA ES EL PEOR CUCHILLO",18,10,"io",-1,0,-1,0,265,265,"C-374","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0374-03",3,"Con franqueza o con cautela\nHiere por doquier alcanza,\nLa codicia o la venganza\nO la envidia más rastrera,\nEn todo esto se revela\nSu indigna perversidad,\nVomitando con maldad,\nSu blasfemia y su perfidia,\nElla es la peor enemiga,\nQue tiene la humanidad.",3,1,0,35,"LA LENGUA ES EL PEOR CUCHILLO",18,10,"a",16,0,-1,0,265,265,"C-374","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0374-04",3,"En este su loco afán\nSigue su curso falaz,\nNo hallando fuerza capaz\nDe mitigar su desmán.\nNi sufrimientos le dan\nLas torturas y suspiros,\nSu cruel infamia es el tiro,\nCon que destroza el honor,\nCrece su saña y rigor\nPorque hiere sin peligro.",3,1,0,35,"LA LENGUA ES EL PEOR CUCHILLO",18,10,"io",-1,0,-1,0,265,265,"C-374","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0374-05",3,"Calumnia con vil furor\nDenigra la caridad,\nMata la paz del hogar\nY critica hasta el dolor.\nNo se escapa ni el amor\nNi inocente castidad,\nNi honra, ni dignidad,\nNi el amigo, ni la amiga,\nLa lengua a todos castiga\nSin compasión ni piedad.",3,1,0,35,"LA LENGUA ES EL PEOR CUCHILLO",18,10,"a",16,0,-1,0,265,265,"C-374","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0375-01",3,"La mujer es lo más bueno,\nLa mujer es lo más malo,\nPara el hombre es un regalo,\nY es para el hombre un veneno.",3,1,0,35,"LA MUJER ES LO MAS BUENO",11,4,"eo",76,0,-1,0,265,265,"C-375","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0375-02",3,"Cuando con amor constante\nY con fina voluntad,\nLa mujer llega a pagar\nLos cariños de un amante,\nSiendo fiel en adelante\nY ama con crecido extremo,\nY le da el debido llano\nDe su pasión hasta el fin,\nY usted se maneja así,\nLa mujer es lo más bueno.",3,1,0,35,"LA MUJER ES LO MAS BUENO",18,10,"eo",-1,0,-1,0,265,265,"C-375","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0375-03",3,"Al mismo tiempo se advierte\nQue haya mujer sin cordura,\nY que, para desventura,\nPiensa en servir solamente,\nY abandonarse no siente,\nAl más infeliz estado.",3,1,0,35,"LA MUJER ES LO MAS BUENO",9,6,"ao",-1,0,-1,0,265,265,"C-375","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0375-05",3,"Donde hay amor hay lealtad,\nGoza gusto y placer,\nindo a corresponder,\nAmor con otro igual.\nGuarda fidelidad\ni punto muy delicado,\nningún otro comparo,\nfinezas entre amores,\nTodos los corazones,\nPara el hombre un regalo.",3,1,0,35,"LA MUJER ES LO MAS BUENO",18,10,"ao",-1,0,-1,0,266,266,"C-375","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0376-01",3,"aves que hicieron nido\nárbol de hojas cargado,\nmiran desconocido\nque lo ven deshojado.",3,1,0,35,".AS AVES QUE HICIERON 1ÍIDO",1,4,"ao",14,0,-1,0,266,266,"C-376","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0376-04",3,"Pues lo tengo bien mirado\nQue una ave por ruin que sea\nHacer su nido desea,\nEn árbol de hojas cargado.",3,1,0,35,".AS AVES QUE HICIERON 1ÍIDO",11,4,"ao",14,0,-1,0,266,266,"C-376","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0376-05",3,"Yo he visto árbol que se vió\nVerde y después se marchita,\nQue el mismo tiempo le quita\nLo que otro tiempo le dió.\nY como seco se halló\nLas aves que hicieron nido\nY tal vez las que han nacido\nAl abrigo de sus hojas,\nComo el tiempo lo despoja\nLo miran desconocido.",3,1,0,35,".AS AVES QUE HICIERON 1ÍIDO",18,10,"io",101,0,-1,0,266,266,"C-376","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0376-06",3,"Todo árbol sin hojas, sabe\nEl tiempo en que reverdece,\nY luego que la hoja crece\nVuelven otra vez las aves.\nAllí trinan cantos suaves\nAl verlo tan bien poblado,\nSe vuelve a quedar postrado\nSi el tiempo le hace perjuicio,\nEntonces no le hacen juicio\nPorque lo ven deshojado.",3,1,0,35,".AS AVES QUE HICIERON 1ÍIDO",18,10,"ao",14,0,-1,0,266,266,"C-376","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0376-07",3,"¡Señores, creo que sin duda\nUstedes podrán notar,\nQue al hombre le pasa igual\nSi lo golpea la firtuna!\nNo halla distinción ninguna,\nNi tiene ningún amigo;\nEs como el árbol caído\nLo han de pisar y pasar,\nNo lo quieren ni mirar,\nLo relegan al olvido.",3,1,0,35,".AS AVES QUE HICIERON 1ÍIDO",18,10,"io",101,0,-1,0,266,266,"C-376","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0376-a-01",3,"Las aves que hicieron nido\nEn árbol de hojas cargado,\nLo miran desconocido\nCuando lo ven deshojado.",3,1,0,35,"LAS AVES QUE HICIERON NIDO",1,4,"ao",14,0,-1,0,266,266,"C-376-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0376-a-02",3,"Vestido de verdes hojas\nTodo árbol es muy hermoso,\nPero ¡qué triste y penoso\nCuando el tiempo lo deshoja!\nPorque perdiendo sus hojas,",3,1,0,35,"LAS AVES QUE HICIERON NIDO",7,5,"oa",-1,0,-1,0,266,266,"C-376-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0376-a-04",3,"Mas, un árbol libre, goza\nDe sus hojas jermanentes;\nVienen aves diferentes,\nY anidan en él gustosas.\nAllí viven cariñosas\nTeniendo su gusto empleado,\nYo lo tengo bien mirado,\nQue una ave por ruin que sea,\nHacer su nido desea\nEn árbol de hojas cargado.",3,1,0,35,"LAS AVES QUE HICIERON NIDO",18,10,"ao",14,0,-1,0,267,267,"C-376-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0376-a-05",3,"Yo ví árbol que vió\nVerde y después se marchita,\nPorque el invierno le quita,\nLo que el verano le dió.\nY cuando seco se vió\nLas aves que hicieron nido\nY también las que han nacido\nAl abrigo de sus hojas,\nComo el tiempo lo despoja\nLo miran desconocido.",3,1,0,35,"LAS AVES QUE HICIERON NIDO",18,10,"io",101,0,-1,0,267,267,"C-376-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0376-a-06",3,"Un árbol sin hojas, sabe\nEl tiempo en que reverdece,\nY luego que la hoja crece\nVuelven otra vez las aves.\nAllí trinan cantos suaves\nPorque se halla en buen estado,\nSe vuelve a quedar postrado\nSi el tiempo le hace perjuicio,\nY entonces no le hacen juicio\nPor'que lo ven deshojado.",3,1,0,35,"LAS AVES QUE HICIERON NIDO",18,10,"ao",14,0,-1,0,267,267,"C-376-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0377-01",3,"¡Lástima me da de verte\nPlanta, en tan terrible estado,\nEn esta mi larga ausencia\nDe poco no te han secado!",3,1,0,35,"¡LASTIMA ME DA DE VERTE!",0,4,"ao",14,0,-1,0,267,267,"C-377","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0377-04",3,"Son muchos los jardineros\nY hay unos tan relajados,\nQue no usan de los cuidados\nNi ponen ningún esmero,\nCon un amor verdadero\nYo te criaba a mi lado,\nMas, apenas me he ausentado,\nCuando otro vino a gozarte,\nDe modo que vengo a hallarte\nPlanta, en tan terrible estado.",3,1,0,35,"¡LASTIMA ME DA DE VERTE!",18,10,"ao",14,0,-1,0,267,267,"C-377","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0377-05",3,"Al dejarte te he regado\nCon lágrimas de mis ojos,\nY hoy hallo sólo despojos\nDe planta tan estimada.\nMe duele verte ultrajada,\nPor la bárbara indolencia,\nY la brutal inclemencia\nDe quien supo aprovecharte,\nY ni aún la sombra dejarte,\nEn esta mi larga ausencia.",3,1,0,35,"¡LASTIMA ME DA DE VERTE!",18,10,"ea",46,0,-1,0,267,267,"C-377","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0377-06",3,"Mas, todo en el mundo es sueño,\nY hay entre los desgraciados,\nMuchos mal intencionados,\nQue poniendo todo empeño\nEn cuanto se ausenta el dueño\nLogran lo que éste ha dejado.\nPor eso te han marchitado\nSin cuidar lo que es ajeno,\nRegándote con veneno\nDe poco, no te han secado.",3,1,0,35,"¡LASTIMA ME DA DE VERTE!",18,10,"ao",14,0,-1,0,267,267,"C-377","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0378-01",3,"Más antes querer a un perro\nQue querer a una mujer,\nEl perro es agradecido\nA quien le da de comer.",3,1,0,35,"MAS ANTES QUERER A UN PERRO",0,4,"e",20,0,-1,0,267,267,"C-378","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0378-02",3,"Aquel que quiera querer,\nDe adelante y atrás\nNo encontrará jamás\nConstancia en una mujer.\nNo sé si sabrán tener\nRazón de duro fierro,\nellas para hacer el yerro,\nbuscan cualquier pretexto\nPara librarse de ésto\nY antes querer a un perro.",3,1,0,35,"MAS ANTES QUERER A UN PERRO",18,10,"eo",-1,0,-1,0,268,268,"C-378","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0378-03",3,"Nunca el hombre ha de encontrar\nLealtad en la mujer,\nY todo le hace creer,\no engaña sin cesar;\nY se pone a llorar\nCuando quiere convencer,\nHaciéndole al hombre ver\nla pasión que no siente,\nY al perro que no miente,\nquerer a una mujer.",3,1,0,35,"MAS ANTES QUERER A UN PERRO",18,10,"e",20,0,-1,0,268,268,"C-378","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0378-04",3,"hombre pena y padece,\nira por tener plata,\nno es la mujer ingrata\nnca jamás le agradece,\nperro cuando se ofrece\nva distinto partido,\n•o con el entendido\n3 es mejor que una mujer,\nile al perro de comer\ne el perro es agradecido.",3,1,0,35,"MAS ANTES QUERER A UN PERRO",18,10,"io",101,0,-1,0,268,268,"C-378","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0379-03",3,"Me refiero a la mujer,\nYa sea casada o soltera,\nPorque todas son cortadas\nPor una misma tijera.",3,1,0,35,"E DICEN QUE NO HAY INFIERNO",0,4,"ea",44,0,-1,0,268,268,"C-379","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0379-04",3,"Si las llaman a un fandango\nA que vayan a bailar,\nAllí van hecho pacota\nTan sólo por murmurar.",3,1,0,35,"E DICEN QUE NO HAY INFIERNO",0,4,"a",21,0,-1,0,268,268,"C-379","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0379-05",3,"Si algún inocente mozo\nCon alguna se dirige,\nYa dicen las malas lenguas:\n—Ella sin amor lo exige.",3,1,0,35,"E DICEN QUE NO HAY INFIERNO",0,4,"ie",374,0,-1,0,268,268,"C-379","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0379-06",3,"Si con ella un rato quedo\nO la voy a visitar,\nYa dicen las malas lenguas:\n—Hoy día van arreglar.",3,1,0,35,"E DICEN QUE NO HAY INFIERNO",0,4,"a",21,0,-1,0,268,268,"C-379","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0379-07",3,"Si a la moza que visito\nLe ven prenda de valor,\nYa dicen las malas lenguas:\n—Ya empieza a darle el amor.",3,1,0,35,"E DICEN QUE NO HAY INFIERNO",0,4,"o",72,0,-1,0,268,268,"C-379","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0379-08",3,"Y si ella con su trabajo\nSe ha comprado un buen vestido,\nYa dicen las malas lenguas:\n—Ya el mozo le da seguido.",3,1,0,35,"E DICEN QUE NO HAY INFIERNO",0,4,"io",101,0,-1,0,268,268,"C-379","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0379-09",3,"Si la moza en tanto cuento\nConmigo se ha disgustado,\nY le llega una visita,\n—De intento le envía regalo.",3,1,0,35,"E DICEN QUE NO HAY INFIERNO",0,4,"ao",-1,0,-1,0,268,268,"C-379","",0,"","","",1,0,0,[],""]]);
